import type { CarClassId } from '@sim'

/**
 * The class as the track announcer would say it (F-711): drivetrain and motor turns first, then the class's rules, on
 * one short line the race screen keeps in the top band so that the person always knows what they are racing. Kept
 * beside the class rows, not in them: `CarClass` is the simulation's type and the sim has no use for a caption. The
 * words are in the HUD's pixel font, upper case, and the longest must fit the room between the order strip of a full
 * field and the weather icons (17 characters at the HUD's small size).
 */
export const CLASS_LEGEND: Readonly<Record<CarClassId, string>> = {
  'tc-stock-175': 'AWD 17.5T STOCK',
  'tc-mod-45': 'AWD 4.5T MODIFIED',
  'fwd-105': '10.5T FWD',
  'f1-215': '21.5T F1',
}
