import Phaser from 'phaser'
import type { CarsPerRace, Difficulty, Direction } from '@sim'
import { ROSTER } from '@content/roster'
import { LOGICAL_HEIGHT, LOGICAL_WIDTH } from '../config'
import { onNav, type NavKey } from '../input/keys'
import { CLASS_WORDS } from '../leaderboard'
import { pitStopLines, pitStopsOwed } from '../race/event-tables'
import { saves, withQuickRace } from '../persistence'
import { buildQuickRace, CARS_CHOICES, freshSeed, MINUTES_CHOICES, PENALTY_SECONDS_CHOICES, QUICK_RACE_DEFAULTS, quickChoicesFrom, WEATHER_CHOICES, withDebugOverrides, type PenaltySeconds, type QuickRaceChoices, type QuickWeather } from '../race/quick-race'
import { chooseTrack, chosenTrack, showsTrackSelector, trackOptions } from '../raceday/track-choice'
import { selection } from '../state/selection'
import { ButtonRow, CarPicture, Form, Panel, THEME, charsAcross, lineHeight, text, wrapText, type HasReadout, type Rect, type ScreenReadout, type Selector } from '../ui'
import type { GarageSceneData } from './GarageScene'
import type { RaceSceneData } from './RaceScene'

/**
 * What the screen lets the player change besides the car and the track (F-808: `QuickRaceChoices`). It opens on the
 * choices of the last quick race started, kept in the save as the event setup's are, and keeps any change while the
 * page is open; starting a race saves them.
 */
type Settings = QuickRaceChoices

const ON_OFF = [{ value: true, label: 'ON' }, { value: false, label: 'OFF' }] as const
let chosen: Settings = { ...QUICK_RACE_DEFAULTS }
/** Whether this page has read the saved choices yet: once, the first time the screen opens. */
let remembered = false

/**
 * Tall enough for the tallest form the screen shows: a final of a class that owes a pit stop, nine rows and the
 * three lines of its reminder under the buttons (the reminder's foot at y 946, the panel's padding under it). Its foot
 * at y 970 stays 46 px clear of the key hints at y 1016. A qualifying heat's ten rows and no reminder end higher.
 */
const PANEL: Rect = { x: Math.round((LOGICAL_WIDTH - 1200) / 2), y: 168, w: 1200, h: 802 }
/** The car's picture takes the left of the panel; the form stands to the right of it. */
const PICTURE_W = 280
const PICTURE_H = 170
const PICTURE_GAP = 40
const ROW_PITCH = 58
/** With the TRACK row there is one row more in the same panel (the selector shows only with a second track), so the rows stand closer. */
const ROW_PITCH_WITH_TRACK = 52
/** What the WEATHER row calls each forecast. */
const WEATHER_LABEL: Readonly<Record<QuickWeather, string>> = { dry: 'DRY', changeable: 'CHANGEABLE', wet: 'WET' }
const LABEL_CHARS = 11
/** Between the buttons and the pit-stop reminder under them, px. */
const NOTE_GAP = 24

/** The rows of the form, top to bottom; the track only with more than one to choose from; the qualifying start is there only for a qualifying heat on a track with a pit lane, and the penalty's length only while penalties are on. */
type RowId = 'track' | 'kind' | 'cars' | 'direction' | 'minutes' | 'difficulty' | 'weather' | 'qualifyingStart' | 'penalties' | 'penaltySeconds' | 'reverse' | 'actions'

/**
 * The race settings of a quick race, the screen after the garage (Title → QUICK RACE → Garage → here → race). The car
 * is the garage's choice, shown here and not changed here; kind, cars, direction, minutes and difficulty are chosen
 * with the arrow keys, and Enter on START builds the session (`buildQuickRace`) and starts the race scene with it.
 * Esc or BACK returns to the garage. The results screen's Enter returns to the title.
 */
export class QuickRaceScene extends Phaser.Scene implements HasReadout {
  private parts: Phaser.GameObjects.GameObject[] = []
  private panel: Panel | null = null
  private form: Form | null = null
  private picture: CarPicture | null = null
  /** What a final in a class that owes a pit stop says about it; absent in qualifying and for a class that owes none. */
  private pitNote: Phaser.GameObjects.BitmapText | null = null
  private buttons: ButtonRow | null = null
  private rowIds: RowId[] = []
  private release: (() => void) | null = null
  /** The kind or the penalties changed, so the form (which has a qualifying start only for qualifying and a penalty length only with penalties on) is built again once the key has been handled. */
  private rebuild = false
  private handled = 0

  constructor() {
    super('QuickRace')
  }

  create(): void {
    this.handled = 0
    this.rebuild = false
    if (!remembered) {
      chosen = quickChoicesFrom(saves.read().settings.lastQuickRace)
      remembered = true
    }
    this.cameras.main.setBackgroundColor(THEME.colours.background)
    this.parts.push(text(this, { x: 96, y: 48 }, 'QUICK RACE', 'large').setTint(THEME.colours.accent))
    this.parts.push(text(this, { x: 96, y: 116 }, 'SET UP THE RACE, THEN START', 'small').setTint(THEME.colours.textDim))
    this.parts.push(
      text(this, { x: LOGICAL_WIDTH / 2, y: LOGICAL_HEIGHT - 64 }, '↑ ↓ MOVE   ← → CHANGE   ENTER CHOOSE   ESC BACK', 'small').setOrigin(0.5, 0).setTint(THEME.colours.textDim),
    )
    this.panel = new Panel(this, PANEL, { title: 'RACE SETTINGS' })
    // The garage's car, as a picture with its class under it: the sprite shows the colour, so no words do.
    const { carClass, colour } = selection.get()
    const { inner } = this.panel
    this.picture = new CarPicture(this, { x: inner.x, y: inner.y, w: PICTURE_W, h: PICTURE_H }, carClass, colour, CLASS_WORDS[carClass])
    this.buildForm(null)
    this.release = onNav(this, (key) => this.onKey(key))
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, this.dispose, this)
  }

  readout(): ScreenReadout {
    const { carClass, colour } = selection.get()
    const car = this.picture?.info()
    return {
      focus: this.form?.focus ?? null,
      values: {
        handled: this.handled,
        class: carClass,
        colour,
        carLabel: car?.label ?? '',
        carAtlas: car?.atlas ?? '',
        carFrame: car?.frame ?? '',
        carScale: car?.scale ?? 0,
        carLengthPx: car?.lengthPx ?? 0,
        carLoading: car?.loading === true ? 1 : 0,
        pitNote: this.pitNote?.text ?? '',
        ...chosen,
        track: chosenTrack().id,
        penalties: chosen.penalties ? 'on' : 'off',
        reverse: chosen.reverse ? 'on' : 'off',
        shownQualifyingStart: this.rowIds.includes('qualifyingStart') ? chosen.qualifyingStart : '',
        rows: this.rowIds.join(','),
        buttonFocus: this.buttons?.focusedButton ?? '',
      },
    }
  }

  /**
   * Builds the form from the current choices. The qualifying start has a row only while the kind is qualifying and the
   * track has a pit lane, and the penalty's length only while penalties are on, so a change of either builds the form again; `focus` is the row that had focus, which gets it back.
   */
  private buildForm(focus: string | null): void {
    this.form?.destroy()
    this.pitNote?.destroy()
    this.pitNote = null
    const inner = (this.panel as Panel).inner
    const formX = inner.x + PICTURE_W + PICTURE_GAP
    const pitch = showsTrackSelector() ? ROW_PITCH_WITH_TRACK : ROW_PITCH
    const form = new Form(this, { x: formX, y: inner.y }, { size: 'body', pitch })
    const ids: RowId[] = []
    const add = <T>(id: Exclude<RowId, 'actions'>, label: string, options: ReadonlyArray<{ value: T; label: string }>, value: T, onChange: (value: T) => void): Selector<T> => {
      const selector = form.addSelector(id, label, options, value, { labelChars: LABEL_CHARS })
      selector.onChange(onChange)
      ids.push(id)
      return selector
    }

    if (showsTrackSelector()) {
      add<string>('track', 'TRACK', trackOptions(), chosenTrack().id, (value) => {
        chooseTrack(value)
        // The qualifying start and the pit-stop reminder depend on the track's pit lane: build the form again.
        this.rebuild = true
      })
    }
    add('kind', 'KIND', [{ value: 'qualifying', label: 'QUALIFYING' }, { value: 'final', label: 'FINAL' }] as const, chosen.kind, (value) => {
      chosen = { ...chosen, kind: value }
      // Not now: the selector that called this is about to draw itself.
      this.rebuild = true
    })
    add<CarsPerRace>('cars', 'CARS', CARS_CHOICES.map((n) => ({ value: n, label: String(n) })), chosen.cars, (value) => (chosen = { ...chosen, cars: value }))
    add<Direction>('direction', 'DIRECTION', [{ value: 'counter-clockwise', label: 'COUNTER-CLOCKWISE' }, { value: 'clockwise', label: 'CLOCKWISE' }], chosen.direction, (value) => (chosen = { ...chosen, direction: value }))
    add<3 | 5 | 7>('minutes', 'MINUTES', MINUTES_CHOICES.map((n) => ({ value: n, label: String(n) })), chosen.minutes, (value) => (chosen = { ...chosen, minutes: value }))
    add<Difficulty>('difficulty', 'DIFFICULTY', [{ value: 'club', label: 'CLUB' }, { value: 'regional', label: 'REGIONAL' }, { value: 'national', label: 'NATIONAL' }], chosen.difficulty, (value) => (chosen = { ...chosen, difficulty: value }))
    add<QuickWeather>('weather', 'WEATHER', WEATHER_CHOICES.map((value) => ({ value, label: WEATHER_LABEL[value] })), chosen.weather, (value) => (chosen = { ...chosen, weather: value }))
    if (chosen.kind === 'qualifying' && chosenTrack().pitLane !== undefined) {
      add<Settings['qualifyingStart']>('qualifyingStart', 'QUAL START', [{ value: 'pit-lane', label: 'PIT LANE' }, { value: 'start-boxes', label: 'START BOXES' }], chosen.qualifyingStart, (value) => (chosen = { ...chosen, qualifyingStart: value }))
    }
    add<boolean>('penalties', 'PENALTIES', ON_OFF, chosen.penalties, (value) => {
      chosen = { ...chosen, penalties: value }
      this.rebuild = true
    })
    if (chosen.penalties) {
      add<PenaltySeconds>('penaltySeconds', 'PENALTY', PENALTY_SECONDS_CHOICES.map((n) => ({ value: n, label: `${n} SECONDS` })), chosen.penaltySeconds, (value) => (chosen = { ...chosen, penaltySeconds: value }))
    }
    add<boolean>('reverse', 'REVERSE', ON_OFF, chosen.reverse, (value) => (chosen = { ...chosen, reverse: value }))
    this.buttons = form.addButtons('actions', [{ id: 'start', label: 'START' }, { id: 'back', label: 'BACK' }], 24)
    ids.push('actions')
    this.buttons.onPress((id) => this.leave(id))
    this.form = form
    this.rowIds = ids

    // A final in a class that owes a pit stop says so under the form (the stop is part of the race's rules, not of its settings).
    const { carClass } = selection.get()
    const note = pitStopLines(pitStopsOwed(chosen.kind, chosenTrack().pitLane !== undefined, carClass)).flatMap((words) => wrapText(words, charsAcross(inner.w - PICTURE_W - PICTURE_GAP, 'body')))
    if (note.length > 0) {
      const top = inner.y + (ids.length - 1) * pitch + 24 + lineHeight('body') + NOTE_GAP
      this.pitNote = text(this, { x: formX, y: top }, note.join('\n'), 'body').setTint(THEME.colours.accent)
    }

    // Focus is on the first row of a new form; move it to the row that had it.
    const at = focus === null ? 0 : Math.max(0, (ids as readonly string[]).indexOf(focus))
    for (let i = 0; i < at; i++) form.handle('down')
  }

  private onKey(key: NavKey): void {
    this.handled++
    if (key === 'back') {
      this.leave('back')
      return
    }
    const focus = this.form?.focus ?? null
    this.form?.handle(key)
    if (this.rebuild) {
      this.rebuild = false
      this.buildForm(focus)
    }
  }

  /** Stops listening at once, so that a second press before the next scene appears does nothing, then starts the race or goes back. */
  private leave(id: string): void {
    this.stopListening()
    if (id === 'back') {
      const garage: GarageSceneData = { role: 'quick-race' }
      this.scene.start('Garage', garage)
      return
    }
    // The choices of the race started are the ones the screen opens on next time, after a reload too.
    saves.update((data) => withQuickRace(data, chosen))
    const { carClass, colour } = selection.get()
    const config = withDebugOverrides(buildQuickRace({ ...chosen, carClass, colour, seed: freshSeed() }, chosenTrack(), ROSTER))
    const scenes = this.game.scene
    const data: RaceSceneData = { config, onContinue: () => scenes.start('Title') }
    this.scene.start('Race', data)
  }

  private stopListening(): void {
    this.release?.()
    this.release = null
  }

  private dispose(): void {
    this.stopListening()
    this.form?.destroy()
    this.form = null
    this.picture?.destroy()
    this.picture = null
    this.pitNote?.destroy()
    this.pitNote = null
    this.buttons = null
    this.rowIds = []
    this.panel?.destroy()
    this.panel = null
    for (const part of this.parts) part.destroy()
    this.parts = []
  }
}
