import Phaser from 'phaser'
import { resolveCar, type CarClassId, type CarColour } from '@sim'
import { CLASS_ORDER, classes } from '@content/classes'
import { tuning } from '@content/tuning'
import { directionSet, manifestOf, type AssetManifest } from '../assets/manifest'
import { LOGICAL_HEIGHT, LOGICAL_WIDTH } from '../config'
import { musicOf } from '../audio/music'
import { onNav, onText, type NavKey, type TextKey } from '../input/keys'
import { NO_NAME, saves, withCar, withDriverName } from '../persistence'
import { SHADOW_OFFSET_PX, carSpriteName, shadowSpriteName } from '../race/CarView'
import { PLAYER_COLOURS, selection } from '../state/selection'
import {
  BAR_LABELS,
  ButtonRow,
  Form,
  Panel,
  StatBars,
  THEME,
  atlasKeyFor,
  charWidth,
  charsAcross,
  classCard,
  classStats,
  ensureClassAtlas,
  lineHeight,
  queueClassAtlas,
  setTextIfChanged,
  text,
  type ClassAtlasLoad,
  type ClassStats,
  type HasReadout,
  type Rect,
  type ScreenReadout,
  type Selector,
  type TextField,
} from '../ui'

/** Whole-number scale of the preview car: the sprites are 36 px long and there is no larger art (F-203). */
const PREVIEW_SCALE = 8
/** The name of the placeholder shown while the first atlas downloads. */
const LOADING_NAME = 'loading'

const MARGIN = 96
const PANEL_TOP = 168
const PANEL_HEIGHT = 800
const LEFT_PANEL: Rect = { x: MARGIN, y: PANEL_TOP, w: 860, h: PANEL_HEIGHT }
const RIGHT_PANEL: Rect = { x: LEFT_PANEL.x + LEFT_PANEL.w + 44, y: PANEL_TOP, w: LOGICAL_WIDTH - 2 * MARGIN - LEFT_PANEL.w - 44, h: PANEL_HEIGHT }
const STAGE_HEIGHT = 340
const ROW_PITCH = 68

/** The body colours as the art build paints them (their "base" step, spec/00-product/art-direction.md), for the swatches. */
export const SWATCH: Readonly<Record<CarColour, number>> = {
  red: 0xd8323a,
  blue: 0x2a6fd6,
  yellow: 0xf0bc1e,
  green: 0x36b852,
  white: 0xd2d8e2,
  orange: 0xe8640c,
  pink: 0xfa90be,
}
/** What the key hint says while the name is being typed in. */
const KEYS_HINT = '↑ ↓ MOVE   ← → CHANGE   ENTER CHOOSE   ESC BACK'
const TYPING_HINT = 'TYPE A NAME   ← → MOVE   BACKSPACE DELETE   ENTER KEEP   ESC LEAVE IT AS IT WAS'
const SWATCH_SIZE = 36
const SWATCH_GAP = 14

/** What the garage is for: the player's START leads to practice, or on to the settings of a quick race or of a race day. */
export type GarageRole = 'practice' | 'quick-race' | 'race-day'

/** What starts the garage. Left out, it is the practice garage. */
export interface GarageSceneData {
  role?: GarageRole
}

/** The words that say what each role is for: the line under the heading and the label of the first button. */
const ROLE_WORDS: Readonly<Record<GarageRole, { subtitle: string; start: string; next: string }>> = {
  practice: { subtitle: 'PICK A CAR, THEN START PRACTICE', start: 'START PRACTICE', next: 'Race' },
  'quick-race': { subtitle: 'QUICK RACE: PICK A CAR, THEN SET UP THE RACE', start: 'RACE SETTINGS', next: 'QuickRace' },
  'race-day': { subtitle: 'RACE DAY: PICK A CAR, THEN SET UP THE EVENT', start: 'EVENT SETUP', next: 'EventSetup' },
}

/**
 * The garage: choose a class and a colour, see the car in that colour at a large whole-number scale, read what the
 * class is (name, drive layout, motor, character) and how it compares (four bars), then start practice. Everything
 * shown comes from the class rows; the choice lives in `selection` and reaches the race only through it. It opens on
 * the car that was chosen last, even in an earlier visit (F-405).
 */
export class GarageScene extends Phaser.Scene implements HasReadout {
  private parts: Phaser.GameObjects.GameObject[] = []
  private panels: Panel[] = []
  private form: Form | null = null
  private classSelector: Selector<CarClassId> | null = null
  private colourSelector: Selector<CarColour> | null = null
  private nameField: TextField | null = null
  private hint: Phaser.GameObjects.BitmapText | null = null
  private releaseText: (() => void) | null = null
  private buttons: ButtonRow | null = null
  private bars: StatBars | null = null
  private statsByClass: Partial<Record<CarClassId, ClassStats>> = {}
  private driveText: Phaser.GameObjects.BitmapText | null = null
  private motorText: Phaser.GameObjects.BitmapText | null = null
  private characterText: Phaser.GameObjects.BitmapText | null = null
  private loadingText: Phaser.GameObjects.BitmapText | null = null
  private body: Phaser.GameObjects.Image | null = null
  private shadow: Phaser.GameObjects.Image | null = null
  private swatchRings: Map<CarColour, Phaser.GameObjects.Rectangle> = new Map()
  private release: (() => void) | null = null
  private download: ClassAtlasLoad | null = null
  /** The scene to go to once the download in flight has finished: a download is never abandoned half way (it would still land, in a scene that has gone). */
  private waitingToLeave: string | null = null
  private alive = false
  private role: GarageRole = 'practice'
  private handled = 0

  constructor() {
    super('Garage')
  }

  init(data: GarageSceneData): void {
    this.role = data.role ?? 'practice'
  }

  /** Fetches the chosen class's car atlas if it is not already loaded (the player's first visit, or a hook-started session of another class). */
  preload(): void {
    if (queueClassAtlas(this, selection.get().carClass)) {
      text(this, { x: LOGICAL_WIDTH / 2, y: LOGICAL_HEIGHT / 2 }, 'LOADING', 'body').setOrigin(0.5).setTint(THEME.colours.textDim).setName(LOADING_NAME)
    }
  }

  create(): void {
    this.alive = true
    this.handled = 0
    this.waitingToLeave = null
    this.children.getByName(LOADING_NAME)?.destroy()
    const manifest = manifestOf(this)
    this.cameras.main.setBackgroundColor(THEME.colours.background)
    this.parts.push(text(this, { x: MARGIN, y: 48 }, 'GARAGE', 'large').setTint(THEME.colours.accent))
    this.parts.push(text(this, { x: MARGIN, y: 116 }, ROLE_WORDS[this.role].subtitle, 'small').setTint(THEME.colours.textDim))
    this.hint = text(this, { x: LOGICAL_WIDTH / 2, y: LOGICAL_HEIGHT - 64 }, KEYS_HINT, 'small').setOrigin(0.5, 0).setTint(THEME.colours.textDim)
    this.parts.push(this.hint)

    const car = new Panel(this, LEFT_PANEL, { title: 'CAR' })
    const preview = new Panel(this, RIGHT_PANEL, { title: 'PREVIEW' })
    this.panels.push(car, preview)

    this.buildForm(car.inner)
    this.buildCard(car.inner)
    this.buildPreview(manifest, preview.inner)
    this.buildStats(preview.inner)

    this.refresh()
    // The title's music goes on through the garage (F-705): the same piece, so it does not restart.
    musicOf(this.registry)?.play('title')
    this.release = onNav(this, (key) => this.onKey(key))
    this.releaseText = onText(this, (key) => this.onText(key), { spaces: true })
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, this.dispose, this)
  }

  readout(): ScreenReadout {
    const { carClass, colour } = selection.get()
    const body = this.body
    const bars = this.bars?.shown
    return {
      focus: this.form?.focus ?? null,
      values: {
        handled: this.handled,
        class: carClass,
        colour,
        shownClass: this.classSelector?.value ?? '',
        shownColour: this.colourSelector?.value ?? '',
        buttonFocus: this.buttons?.focusedButton ?? '',
        role: this.role,
        name: classes[carClass].name,
        driverName: this.nameField?.shown ?? '',
        driverNameSet: this.nameField?.value ?? '',
        typing: this.nameField?.editing === true ? 1 : 0,
        drive: this.driveText?.text ?? '',
        motor: this.motorText?.text ?? '',
        character: this.characterText?.text ?? '',
        previewLoading: this.loadingText?.visible === true ? 1 : 0,
        previewAtlas: body?.texture.key ?? '',
        previewFrame: body?.frame.name ?? '',
        previewScale: body?.scaleX ?? 0,
        previewX: body?.x ?? 0,
        previewY: body?.y ?? 0,
        previewLengthPx: body === null ? 0 : body.frame.cutWidth * body.scaleX,
        previewWidthPx: body === null ? 0 : body.frame.cutHeight * body.scaleY,
        previewShadowFrame: this.shadow?.frame.name ?? '',
        barAcceleration: bars?.acceleration ?? -1,
        barTopSpeed: bars?.topSpeed ?? -1,
        barGrip: bars?.grip ?? -1,
        barStability: bars?.stability ?? -1,
      },
    }
  }

  private buildForm(inner: Rect): void {
    const form = new Form(this, { x: inner.x, y: inner.y }, { size: 'body', pitch: ROW_PITCH })
    const chosen = selection.get()
    this.classSelector = form.addSelector('class', 'CLASS', CLASS_ORDER.map((id) => ({ value: id, label: classes[id].name })), chosen.carClass, { labelChars: 6 })
    this.colourSelector = form.addSelector('colour', 'COLOUR', PLAYER_COLOURS.map((colour) => ({ value: colour, label: colour.toUpperCase() })), chosen.colour, { labelChars: 6 })
    // The driver's name, one of the car's settings: YOU while none is set. Enter on it starts typing; Enter again keeps it, Esc leaves it as it was.
    this.nameField = form.addTextField('name', 'NAME', saves.read().settings.driverName, { labelChars: 6, empty: NO_NAME })
    this.nameField.onChange((name) => {
      saves.update((data) => withDriverName(data, name))
      this.showTyping()
    })
    this.buttons = form.addButtons(
      'actions',
      [
        { id: 'start', label: ROLE_WORDS[this.role].start },
        { id: 'back', label: 'BACK' },
      ],
      24,
    )
    this.form = form

    this.classSelector.onChange((carClass) => {
      selection.set({ carClass })
      this.refresh()
    })
    this.colourSelector.onChange((colour) => {
      selection.set({ colour })
      this.refresh()
    })
    this.buttons.onPress((id) => {
      if (id === 'start') {
        // The pick is remembered when the player goes on with it: the garage opens on this car next time (F-405).
        saves.update((data) => withCar(data, selection.get()))
        this.leave(ROLE_WORDS[this.role].next)
      } else this.leave('Title')
    })

    // A chip for each colour, the chosen one ringed, beside the colour row.
    const y = inner.y + ROW_PITCH
    const x0 = inner.x + 21 * charWidth('body')
    PLAYER_COLOURS.forEach((colour, i) => {
      const x = x0 + i * (SWATCH_SIZE + SWATCH_GAP)
      const ring = this.add.rectangle(x - 4, y - 4, SWATCH_SIZE + 8, SWATCH_SIZE + 8, THEME.colours.text).setOrigin(0, 0).setVisible(false)
      const chip = this.add.rectangle(x, y, SWATCH_SIZE, SWATCH_SIZE, SWATCH[colour]).setOrigin(0, 0)
      this.swatchRings.set(colour, ring)
      this.parts.push(ring, chip)
    })
  }

  private buildCard(inner: Rect): void {
    const top = inner.y + 4 * ROW_PITCH + 48
    this.parts.push(this.add.rectangle(inner.x, top - 36, inner.w, THEME.borderPx, THEME.colours.border).setOrigin(0, 0))
    this.driveText = text(this, { x: inner.x, y: top }, '', 'body')
    this.motorText = text(this, { x: inner.x, y: top + 56 }, '', 'body')
    this.characterText = text(this, { x: inner.x, y: top + 140 }, '', 'body').setTint(THEME.colours.textDim)
    this.parts.push(this.driveText, this.motorText, this.characterText)
  }

  private buildPreview(manifest: AssetManifest, inner: Rect): void {
    const stage = { x: inner.x, y: inner.y, w: inner.w, h: STAGE_HEIGHT }
    this.parts.push(this.add.rectangle(stage.x, stage.y, stage.w, stage.h, THEME.colours.stage).setOrigin(0, 0))
    const cx = stage.x + Math.round(stage.w / 2)
    const cy = stage.y + Math.round(stage.h / 2)
    const { carClass, colour } = selection.get()
    const body = directionSet(manifest, carSpriteName(carClass, colour))
    const shadow = directionSet(manifest, shadowSpriteName(carClass))
    this.shadow = this.add
      .image(cx + SHADOW_OFFSET_PX.x * PREVIEW_SCALE, cy + SHADOW_OFFSET_PX.y * PREVIEW_SCALE, shadow.atlas, shadow.frames[0])
      .setScale(PREVIEW_SCALE)
    this.body = this.add.image(cx, cy, body.atlas, body.frames[0]).setScale(PREVIEW_SCALE)
    this.loadingText = text(this, { x: cx, y: cy - Math.round(lineHeight('body') / 2) }, 'LOADING', 'body').setOrigin(0.5, 0).setVisible(false)
    this.parts.push(this.shadow, this.body, this.loadingText)
  }

  private buildStats(inner: Rect): void {
    const top = inner.y + STAGE_HEIGHT + 40
    this.parts.push(text(this, { x: inner.x, y: top }, 'HOW IT COMPARES', 'small').setTint(THEME.colours.accent))
    this.bars = new StatBars(this, { x: inner.x, y: top + lineHeight('small') + 24 }, inner.w)
    const noteY = top + lineHeight('small') + 24 + BAR_LABELS.length * 56 + 8
    this.parts.push(text(this, { x: inner.x, y: noteY }, 'EACH BAR IS A CLASS AGAINST THE BEST OF THE FOUR', 'small').setTint(THEME.colours.textDim))

    const all = CLASS_ORDER.map((id) => resolveCar(classes[id], tuning))
    CLASS_ORDER.forEach((id, i) => {
      const params = all[i]
      if (params !== undefined) this.statsByClass[id] = classStats(params, all)
    })
  }

  /** Brings everything that depends on the choice into line with it. */
  private refresh(): void {
    const { carClass, colour } = selection.get()
    const card = classCard(classes[carClass], charsAcross(LEFT_PANEL.w - 2 * THEME.padding, 'body'))
    if (this.driveText !== null) setTextIfChanged(this.driveText, `DRIVE  ${card.drive}`)
    if (this.motorText !== null) setTextIfChanged(this.motorText, `MOTOR  ${card.motor}`)
    if (this.characterText !== null) setTextIfChanged(this.characterText, card.character.join('\n'))
    const stats = this.statsByClass[carClass]
    if (stats !== undefined) this.bars?.set(stats)
    for (const [swatch, ring] of this.swatchRings) ring.setVisible(swatch === colour)
    this.showCar()
  }

  /** Puts the chosen car in the preview, loading its atlas first if this is the first time the class is seen. */
  private showCar(): void {
    const { carClass, colour } = selection.get()
    const manifest = manifestOf(this)
    const ready = this.textures.exists(atlasKeyFor(manifest, carClass))
    this.loadingText?.setVisible(!ready)
    this.body?.setVisible(ready)
    this.shadow?.setVisible(ready)
    if (!ready) {
      if (this.download === null) {
        this.download = ensureClassAtlas(this, carClass, () => {
          this.download = null
          if (!this.alive) return
          // The atlas that landed is the one of the class shown when it was asked for; the player may have moved on
          // since. Show the class chosen now, which starts its download if it is not in, and leave only once it is:
          // the next screen and the race then never start a second load of a key still on its way.
          this.showCar()
          const next = this.waitingToLeave
          if (next !== null && this.download === null) this.go(next)
        })
      }
      return
    }
    const body = directionSet(manifest, carSpriteName(carClass, colour))
    const shadow = directionSet(manifest, shadowSpriteName(carClass))
    this.body?.setTexture(body.atlas, body.frames[0])
    this.shadow?.setTexture(shadow.atlas, shadow.frames[0])
  }

  private onKey(key: NavKey): void {
    this.handled++
    // While the name is being typed in, Esc leaves the name as it was, not the garage.
    if (key === 'back' && this.form?.editing !== true) {
      this.leave('Title')
      return
    }
    this.form?.handle(key)
    this.showTyping()
  }

  private onText(key: TextKey): void {
    if (this.form?.editing !== true) return
    this.handled++
    this.form.type(key)
  }

  /** The key hint says how to type while the name is being typed in. */
  private showTyping(): void {
    if (this.hint !== null) setTextIfChanged(this.hint, this.form?.editing === true ? TYPING_HINT : KEYS_HINT)
  }

  /**
   * Stops listening at once, so that a second press before the next scene appears does nothing, then changes scene:
   * now, or when the class atlas that is still downloading has landed.
   */
  private leave(next: string): void {
    this.stopListening()
    if (this.download === null) this.go(next)
    else this.waitingToLeave = next
  }

  /**
   * Starts the next scene with data of its own, an empty set if it needs none. Phaser keeps the data a scene was last
   * started with and hands it to `init` again whenever the scene is started with none, so a practice race started bare
   * would be the last race's session (its class, its weather, its entries) over again (F-710).
   */
  private go(next: string): void {
    this.scene.start(next, {})
  }

  private stopListening(): void {
    this.release?.()
    this.release = null
    this.releaseText?.()
    this.releaseText = null
  }

  private dispose(): void {
    this.alive = false
    this.stopListening()
    this.download?.cancel()
    this.download = null
    this.waitingToLeave = null
    this.form?.destroy()
    this.form = null
    this.classSelector = null
    this.colourSelector = null
    this.nameField = null
    this.hint = null
    this.buttons = null
    this.bars?.destroy()
    this.bars = null
    for (const part of this.parts) part.destroy()
    this.parts = []
    for (const panel of this.panels) panel.destroy()
    this.panels = []
    this.swatchRings.clear()
    this.driveText = this.motorText = this.characterText = this.loadingText = null
    this.body = this.shadow = null
    this.statsByClass = {}
  }
}
