import Phaser from 'phaser'
import { createRng, type CarId, type CarSnapshot, type Rng, type Vec2 } from '@sim'
import { animation, type Animation } from '../assets/animation'
import { manifestOf } from '../assets/manifest'
import type { WorldView } from '../config'
import { DEPTH } from './depth'
import { dustPuffs, FX, layingRubber, puffFrame, slipRatios, smokeRate, wheelPoints, type TyreSlip, type WheelGeometry, TYRE_SLIP } from './car-effects'
import type { RenderCar } from './interpolate'

// Tyre smoke from an axle that slides, and dust where a car hits a wall (F-205). Two fixed pools of puffs, reused round
// and round: nothing is created or destroyed while the race runs, and the number alive never exceeds the pool. It reads
// snapshots and sim events and keeps no gameplay state; its own timers (how long a tyre has been sliding, puffs owed) are
// about what is on screen. Scatter comes from a seeded generator, so two runs look alike. The puffs are drawn pictures
// (F-802, art/fx/build.py): smoke pale, dust a step duller, each growing through its frames as it ages and fading out.

/** The pictures of a puff of smoke and of dust, in the HUD atlas, which the race loads. Four frames each, smallest first. */
export const SMOKE_SPRITE = 'fx.smoke'
export const DUST_SPRITE = 'fx.dust'

/** The most puffs alive at once, for every car together. */
export const SMOKE_CAP = 56
export const DUST_CAP = 24

/** How long a puff of smoke lasts, s: this, plus up to a third again. It is gone well inside a second. */
const SMOKE_LIFE_S = 0.6
const DUST_LIFE_S = 0.45
const SMOKE_ALPHA = 0.5
const DUST_ALPHA = 0.9
/** How much of the car's speed a puff of smoke is carried along with, and how far it drifts of its own, px/s. */
const SMOKE_CARRY = 0.12
const SMOKE_DRIFT_PX_S = 14
const DUST_SPEED_PX_S = 90

/** What the effects need of a car: where its tyres are and how long it is, for a wall hit's place on its nose. */
export interface FxCar {
  geometry: WheelGeometry
  lengthM: number
}

interface Puff {
  image: Phaser.GameObjects.Image
  vx: number
  vy: number
  /** Seconds left, and the whole life it was given. */
  leftS: number
  lifeS: number
}

/** What the effects have in the air, for the debug hook and the soak. */
export interface FxStats {
  smokeAlive: number
  smokeCap: number
  dustAlive: number
  dustCap: number
}

class Pool {
  private readonly puffs: Puff[] = []
  /** The pool is used round and round: the next puff takes the place of the oldest. */
  private next = 0

  constructor(
    scene: Phaser.Scene,
    size: number,
    private readonly art: Animation,
    private readonly alpha: number,
  ) {
    for (let i = 0; i < size; i++) {
      const image = scene.add.image(0, 0, art.atlas, art.frames[0]).setOrigin(art.pivot.x, art.pivot.y).setScale(art.scale).setDepth(DEPTH.spray).setVisible(false)
      this.puffs.push({ image, vx: 0, vy: 0, leftS: 0, lifeS: 1 })
    }
  }

  alive(): number {
    return this.puffs.reduce((count, puff) => count + (puff.leftS > 0 ? 1 : 0), 0)
  }

  emit(x: number, y: number, vx: number, vy: number, lifeS: number): void {
    const puff = this.puffs[this.next]
    this.next = (this.next + 1) % this.puffs.length
    puff.lifeS = lifeS
    puff.leftS = lifeS
    puff.vx = vx
    puff.vy = vy
    puff.image.setPosition(Math.round(x), Math.round(y)).setFrame(this.art.frames[0] ?? '').setAlpha(this.alpha).setVisible(true)
  }

  step(dtS: number): void {
    for (const puff of this.puffs) {
      if (puff.leftS <= 0) continue
      puff.leftS -= dtS
      if (puff.leftS <= 0) {
        puff.image.setVisible(false)
        continue
      }
      const age = 1 - puff.leftS / puff.lifeS
      const slowing = Math.max(0, 1 - 2.5 * dtS)
      puff.vx *= slowing
      puff.vy *= slowing
      puff.image
        .setPosition(puff.image.x + puff.vx * dtS, puff.image.y + puff.vy * dtS)
        .setFrame(this.art.frames[puffFrame(age, this.art.frames.length)] ?? '')
        .setAlpha(this.alpha * (1 - age))
    }
  }

  destroy(): void {
    for (const puff of this.puffs) puff.image.destroy()
    this.puffs.length = 0
  }
}

export class CarFx {
  private readonly smoke: Pool
  private readonly dust: Pool
  private readonly rng: Rng
  /** For each car and axle (front, rear): how long its tyres have slid past the smoke threshold, s, and the puffs owed. */
  private readonly slidingS: number[]
  private readonly owed: number[]
  private destroyed = false

  constructor(
    private readonly scene: Phaser.Scene,
    private readonly view: WorldView,
    private readonly cars: readonly FxCar[],
    seed: number,
    private readonly tyre: TyreSlip = TYRE_SLIP,
  ) {
    const manifest = manifestOf(scene)
    this.smoke = new Pool(scene, SMOKE_CAP, animation(manifest, SMOKE_SPRITE), SMOKE_ALPHA)
    this.dust = new Pool(scene, DUST_CAP, animation(manifest, DUST_SPRITE), DUST_ALPHA)
    // Its own sequence: the looks never draw from the sim's.
    this.rng = createRng((seed ^ 0x5eed5eed) >>> 0)
    this.slidingS = cars.flatMap(() => [0, 0])
    this.owed = cars.flatMap(() => [0, 0])
    scene.events.once(Phaser.Scenes.Events.SHUTDOWN, this.destroy, this)
  }

  /** What is in the air now. */
  stats(): FxStats {
    return { smokeAlive: this.smoke.alive(), smokeCap: SMOKE_CAP, dustAlive: this.dust.alive(), dustCap: DUST_CAP }
  }

  /**
   * Moves the puffs on by `dtS` and smokes from every axle whose tyres have been past the smoke threshold for
   * more than the delay. `cars` are the cars as drawn, `snapshots` the sim's latest.
   */
  update(dtS: number, cars: readonly RenderCar[], snapshots: readonly CarSnapshot[]): void {
    if (this.destroyed) return
    this.smoke.step(dtS)
    this.dust.step(dtS)
    for (const car of cars) {
      const snap = snapshots[car.id]
      const spec = this.cars[car.id]
      if (snap === undefined || spec === undefined) continue
      const sliding = layingRubber(snap) ? slipRatios(snap, spec.geometry, this.tyre) : { front: 0, rear: 0 }
      this.axle(dtS, car, snap, spec, 0, sliding.front)
      this.axle(dtS, car, snap, spec, 1, sliding.rear)
    }
  }

  private axle(dtS: number, car: RenderCar, snap: CarSnapshot, spec: FxCar, axle: 0 | 1, slip: number): void {
    const slot = car.id * 2 + axle
    if (!(slip > FX.smoke.from)) {
      this.slidingS[slot] = 0
      this.owed[slot] = 0
      return
    }
    this.slidingS[slot] += dtS
    if (this.slidingS[slot] <= FX.smoke.afterS) return
    this.owed[slot] += smokeRate(slip, snap.speedMS) * dtS
    if (this.owed[slot] < 1) return
    const wheels = wheelPoints({ x: car.x, y: car.y, angle: car.angle }, spec.geometry)
    const pair = axle === 0 ? [wheels.fl, wheels.fr] : [wheels.rl, wheels.rr]
    while (this.owed[slot] >= 1) {
      this.owed[slot] -= 1
      const from = pair[this.rng.next() < 0.5 ? 0 : 1]
      const { x, y } = this.toScreen(from)
      const drift = (): number => (this.rng.next() * 2 - 1) * SMOKE_DRIFT_PX_S
      this.smoke.emit(
        x,
        y,
        snap.velocity.x * this.view.pxPerM * SMOKE_CARRY + drift(),
        snap.velocity.y * this.view.pxPerM * SMOKE_CARRY + drift(),
        SMOKE_LIFE_S * (1 + this.rng.next() / 3),
      )
    }
  }

  /**
   * A car has hit a wall (the sim's `contact` event): a short puff of dust at the place it hit, which is taken to be
   * the nose of the car in the direction it was going (the event does not say where). None for a tap.
   */
  wall(car: CarId, impulseNs: number, before: CarSnapshot | undefined, now: CarSnapshot | undefined): void {
    const spec = this.cars[car]
    const snap = now ?? before
    if (this.destroyed || spec === undefined || snap === undefined) return
    const count = dustPuffs(impulseNs)
    if (count === 0) return
    const moving = before ?? snap
    const speed = Math.hypot(moving.velocity.x, moving.velocity.y)
    const heading = speed > 0.2 ? { x: moving.velocity.x / speed, y: moving.velocity.y / speed } : { x: Math.cos(snap.pose.angle), y: Math.sin(snap.pose.angle) }
    const at: Vec2 = { x: snap.pose.x + (heading.x * spec.lengthM) / 2, y: snap.pose.y + (heading.y * spec.lengthM) / 2 }
    const { x, y } = this.toScreen(at)
    for (let i = 0; i < count; i++) {
      const away = this.rng.next() * Math.PI * 2
      const pace = DUST_SPEED_PX_S * (0.4 + 0.6 * this.rng.next())
      this.dust.emit(x, y, Math.cos(away) * pace, Math.sin(away) * pace, DUST_LIFE_S * (1 + this.rng.next() / 2))
    }
  }

  private toScreen(p: Vec2): Vec2 {
    return { x: this.view.originX + p.x * this.view.pxPerM, y: this.view.originY + p.y * this.view.pxPerM }
  }

  destroy(): void {
    if (this.destroyed) return
    this.destroyed = true
    this.scene.events.off(Phaser.Scenes.Events.SHUTDOWN, this.destroy, this)
    this.smoke.destroy()
    this.dust.destroy()
  }
}
