import type Phaser from 'phaser'
import { lerp, type TrackData, type Vec2 } from '@sim'
import type { WorldView } from '../config'
import { DEPTH } from './depth'
import { LAYER, looseTyres, tyreTextureKey, type LooseTyre } from './track-draw'
import { BAKE_SCALE } from './track-style'

// The tyres that mark the corners, drawn where they are (F-308). They used to be part of the baked ground; now a
// car can push one, so each is an image of its own that follows the sim's snapshot. The picture is the one the
// ground had, made once per size by TrackRenderer; a tyre is never turned, however the sim's tyre has spun.

/**
 * Where the tyres are drawn among the race scene's layers: on the ground, as when they were baked into it (the
 * markers were its topmost layer), and under everything that is drawn over the ground.
 */
export const MARKER_DEPTH = DEPTH.ground + LAYER.markers / 100

/**
 * Where a tyre's centre is on screen at the instant a frame is drawn: `alpha` of the way from where the snapshot
 * before had it to where the current one has it. A snapshot that does not list the tyre leaves it where it lay.
 */
export function tyreScreenPlace(tyre: LooseTyre, prev: readonly Readonly<Vec2>[], curr: readonly Readonly<Vec2>[], alpha: number, view: WorldView): Vec2 {
  const now = curr[tyre.index] ?? tyre
  const before = prev[tyre.index] ?? now
  return {
    x: view.originX + lerp(before.x, now.x, alpha) * view.pxPerM,
    y: view.originY + lerp(before.y, now.y, alpha) * view.pxPerM,
  }
}

/**
 * One image per tyre of the track, kept where the tyre is. Create it after `TrackRenderer.bake()`, which makes the
 * pictures; call `update` every frame with the runner's two snapshots; `destroy()` it on shutdown.
 */
export class MarkerView {
  private readonly tyres: LooseTyre[]
  private images: Phaser.GameObjects.Image[]

  constructor(
    scene: Phaser.Scene,
    private readonly view: WorldView,
    track: TrackData,
  ) {
    this.tyres = looseTyres(track)
    this.images = this.tyres.map((tyre) => {
      const at = tyreScreenPlace(tyre, [], [], 0, view)
      return scene.add
        .image(at.x, at.y, tyreTextureKey(tyre.r))
        .setScale(1 / BAKE_SCALE)
        .setDepth(MARKER_DEPTH)
    })
  }

  /** Puts every tyre where the sim has it, between the snapshot before (`prev`) and the current one (`curr`). */
  update(prev: readonly Readonly<Vec2>[], curr: readonly Readonly<Vec2>[], alpha: number): void {
    for (let i = 0; i < this.images.length; i++) {
      const at = tyreScreenPlace(this.tyres[i], prev, curr, alpha, this.view)
      this.images[i].setPosition(at.x, at.y)
    }
  }

  destroy(): void {
    for (const image of this.images) image.destroy()
    this.images = []
  }
}
