import type { RaceControlCall } from '@sim'
import type { AudioMixer } from './AudioMixer'
import { startTones } from './mapping'

/** Attack and release of a tone, seconds: short enough to be crisp, long enough not to click. */
const EDGE_S = 0.006

/**
 * The start tones (F-704): `three-seconds` schedules three short low tones, one second apart; `start-tone` plays the
 * long high one at once, on the tick the race starts. Tones are placed on the audio clock, so a pause between them
 * (which freezes that clock) cannot let the long tone sound early or late against the short ones.
 */
export class StartTones {
  private readonly pending = new Set<{ osc: OscillatorNode; gain: GainNode }>()

  constructor(private readonly mixer: AudioMixer) {}

  /** Makes whatever tones `call` calls for. Returns how many were scheduled. */
  onCall(call: RaceControlCall): number {
    const steps = startTones(call)
    if (steps.length === 0 || !this.mixer.audible) return 0
    const { ctx } = this.mixer
    const now = ctx.currentTime
    for (const step of steps) {
      const at = now + step.offsetS
      const osc = ctx.createOscillator()
      osc.type = 'square'
      osc.frequency.value = step.freqHz
      const gain = ctx.createGain()
      gain.gain.setValueAtTime(0, at)
      gain.gain.linearRampToValueAtTime(step.gain, at + EDGE_S)
      gain.gain.setValueAtTime(step.gain, at + step.durationS - EDGE_S)
      gain.gain.linearRampToValueAtTime(0, at + step.durationS)
      osc.connect(gain)
      gain.connect(this.mixer.sfx)
      const tone = { osc, gain }
      this.pending.add(tone)
      osc.onended = () => this.release(tone)
      osc.start(at)
      osc.stop(at + step.durationS + 0.02)
    }
    return steps.length
  }

  dispose(): void {
    for (const tone of [...this.pending]) {
      try {
        tone.osc.stop()
      } catch {
        // Already stopped.
      }
      this.release(tone)
    }
  }

  private release(tone: { osc: OscillatorNode; gain: GainNode }): void {
    if (!this.pending.delete(tone)) return
    tone.osc.onended = null
    tone.osc.disconnect()
    tone.gain.disconnect()
  }
}
