import type { CarClass, CarClassId, Tuning } from '@sim'

// Applying a preset's changes to a class row and to the tuning block (F-807, moved out of the debug folder by F-811):
// the tuning panel puts a shipped preset in place with it, and DRIVING ASSISTANCE gives the player's car the NEWBIE
// setup with it, in every build. Pure: no engine and no browser, so it runs in Node too.

/** One value of a class row or of the tuning block. */
export type Leaf = number | string | boolean

export function isLeaf(value: unknown): value is Leaf {
  return typeof value === 'number' || typeof value === 'string' || typeof value === 'boolean'
}

export function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

/**
 * Checks a parsed value against the shape of a real one. Every key must be one the shape has, of the same kind; a
 * key left out takes the shape's value when `partial`, and is an error otherwise. Returns a new value in the shape's order.
 */
export function conform(parsed: unknown, shape: unknown, path: string, partial: boolean): unknown {
  const here = path === '' ? 'the value' : `'${path}'`
  if (isLeaf(shape)) {
    if (typeof parsed !== typeof shape) throw new TypeError(`${here} should be a ${typeof shape}`)
    if (typeof parsed === 'number' && !Number.isFinite(parsed)) throw new RangeError(`${here} is not a finite number`)
    return parsed
  }
  if (!isObject(shape)) throw new TypeError(`${here}: the shape has something that is neither a value nor a group`)
  if (!isObject(parsed)) throw new TypeError(`${here} should be a group of values`)
  for (const key of Object.keys(parsed)) {
    if (!Object.hasOwn(shape, key)) throw new TypeError(`'${path === '' ? key : `${path}.${key}`}' is not a field`)
  }
  const out: Record<string, unknown> = {}
  for (const [key, child] of Object.entries(shape)) {
    const childPath = path === '' ? key : `${path}.${key}`
    if (Object.hasOwn(parsed, key)) out[key] = conform(parsed[key], child, childPath, partial)
    else if (partial) out[key] = structuredClone(child)
    else throw new TypeError(`'${childPath}' is missing`)
  }
  return out
}

/** What a preset holds: its name, and its changes to the tuning block and to each class row it names. */
export interface PresetData {
  readonly name: string
  readonly tuning: object
  readonly classes: Readonly<Partial<Record<CarClassId, object>>>
}

/** A class row and the tuning block it is driven with. */
export interface CarSetup {
  car: CarClass
  tuning: Tuning
}

/** The tuning block with a preset's changes over it: a new value; a field the block lacks, or a value of the wrong kind, throws. */
export function presetTuning(preset: PresetData, shipped: Tuning): Tuning {
  return conform(preset.tuning, shipped, 'tuning', true) as Tuning
}

/** A class row with a preset's changes for that class over it (none, if the preset names no change for it): a new value, checked as `presetTuning` is. */
export function presetClass(preset: PresetData, shipped: CarClass): CarClass {
  return conform(preset.classes[shipped.id] ?? {}, shipped, `classes.${shipped.id}`, true) as CarClass
}

/** What a preset makes of one class: its class row and the tuning block, both with the preset's changes over the shipped values. */
export function presetSetup(preset: PresetData, shippedClass: CarClass, shippedTuning: Tuning): CarSetup {
  return { car: presetClass(preset, shippedClass), tuning: presetTuning(preset, shippedTuning) }
}
