import { TICK_RATE, type CarClassId, type CarId, type SessionKind, type SessionSnapshot } from '@sim'
import type { EventBus } from '../race/EventBus'
import type { RenderCar } from '../race/interpolate'
import type { AudioMixer, Volumes } from './AudioMixer'
import { Ambience } from './Ambience'
import { Crowd } from './Crowd'
import { impactGain, kerbRumbleGain, kerbThumpGain, splashGain } from './mapping'
import { MotorSynth } from './MotorSynth'
import { Sfx } from './Sfx'
import { StartTones } from './StartTones'

export interface RaceAudioOptions {
  classId: CarClassId
  /** The kind of session: the crowd cheers the first car home in a heat or a final (F-711), and never in practice. Left out, it does not cheer. */
  kind?: SessionKind
  /** How many cars are in the session. */
  cars: number
  /** The car the person drives, whose motor is louder and whose laps beep. Null when the game drives every car. */
  playerCar: CarId | null
  /** World x in metres to a stereo position -1..1 (the scene knows the view). */
  panOf: (worldX: number) => number
  /** The levels of the saved settings, applied when the race mounts. */
  volumes?: Volumes
}

/** How long a car on a kerb waits before its rumble is retriggered, seconds of sim time. */
const RUMBLE_EVERY_S = 0.14
/** A car must be this far inside a puddle's water, metres beyond its radius, to have splashed (a little slack for the car's width). */
const PUDDLE_SLACK_M = 0.05
/** Share of full level that the other cars' hits have against the player's own. */
const OTHERS_SHARE = 0.75

/**
 * Everything the race hears (F-704), mounted by the race scene: a `MotorSynth` per car, the one-shot `Sfx`, the weather's
 * `Ambience` and the `StartTones`. It subscribes to the scene's sim-event bus and reads the interpolated snapshot each
 * frame; it never touches the sim. Pausing is the mixer's (it suspends the context, which freezes all of this), so
 * nothing here needs to know about it, and `destroy` stops and disconnects every node it made.
 */
export class RaceAudio {
  private readonly motors: MotorSynth[] = []
  private readonly sfx: Sfx
  private readonly ambience: Ambience
  private readonly tones: StartTones
  private readonly cheering: Crowd
  /** The winner has crossed the line and the crowd has been told: it is told once. */
  private cheered = false
  private readonly unsubscribe: Array<() => void> = []
  /** Each car's stereo position and speed at the last frame, which the event handlers use. */
  private readonly pans: number[] = []
  private readonly speeds: number[] = []
  private readonly nextRumbleS: number[] = []
  private readonly scrapedFor: number[] = []
  /** Which puddles each car is in, by car then puddle index, so that a splash is made on entering. */
  private readonly inPuddle: boolean[][] = []
  private destroyed = false

  constructor(
    private readonly mixer: AudioMixer,
    bus: EventBus,
    private readonly options: RaceAudioOptions,
  ) {
    if (options.volumes !== undefined) mixer.setVolumes(options.volumes)
    this.sfx = new Sfx(mixer)
    this.ambience = new Ambience(mixer)
    this.tones = new StartTones(mixer)
    this.cheering = new Crowd(mixer)
    for (let car = 0; car < options.cars; car++) {
      this.motors.push(new MotorSynth(mixer, options.classId, car === options.playerCar))
      this.pans.push(0)
      this.speeds.push(0)
      this.nextRumbleS.push(0)
      this.scrapedFor.push(-1)
      this.inPuddle.push([])
    }

    const { playerCar } = options
    const share = (car: CarId): number => (car === playerCar ? 1 : OTHERS_SHARE)
    const timeOf = (tick: number): number => tick / TICK_RATE
    this.unsubscribe.push(
      bus.on('contact', (e) => {
        const gain = impactGain(e.impulseNs)
        if (gain === 0) return
        const kind = e.other === 'wall' || e.other === 'marshal' ? 'contact-wall' : e.other === 'marker' ? 'contact-tyre' : 'contact-car'
        this.sfx.play(kind, { gain: gain * share(e.car), pan: this.pans[e.car] ?? 0, car: e.car, timeS: timeOf(e.tick) })
      }),
      bus.on('kerb-hop', (e) => {
        this.sfx.play('kerb-thump', { gain: kerbThumpGain(e.speedMS) * share(e.car), pan: this.pans[e.car] ?? 0, car: e.car, timeS: timeOf(e.tick) })
      }),
      bus.on('flip', (e) => {
        this.sfx.play('roll-thump', { gain: share(e.car), pan: this.pans[e.car] ?? 0, car: e.car, timeS: timeOf(e.tick) })
      }),
      bus.on('car-righted', (e) => {
        this.sfx.play('righted', { gain: share(e.car), pan: this.pans[e.car] ?? 0, car: e.car, timeS: timeOf(e.tick) })
      }),
      bus.on('aquaplane', (e) => {
        this.sfx.play('splash', { gain: share(e.car), pan: this.pans[e.car] ?? 0, car: e.car, timeS: timeOf(e.tick) })
      }),
      // The lap beep and the personal-best chime are the player's: the rest of the field's laps are the commentary's.
      bus.on('lap', (e) => {
        if (e.car !== playerCar) return
        this.sfx.play(e.personalBest ? 'personal-best' : 'lap', { gain: 0.8, car: e.car, timeS: timeOf(e.tick) })
      }),
      bus.on('race-control', (e) => {
        this.tones.onCall(e.call)
      }),
      // The first car to take the chequered flag in a heat or a final: the crowd cheers, once (F-711). The cars after it get no cheer.
      bus.on('car-finished', () => {
        if (this.cheered || (options.kind !== 'qualifying' && options.kind !== 'final')) return
        this.cheered = true
        this.cheering.cheer()
      }),
    )
  }

  /** The one-shot effects, for the menus' blips and for tests. */
  get effects(): Sfx {
    return this.sfx
  }

  /** Called once a frame, after the scene has drawn: `cars` are the interpolated cars, `snapshot` the sim's latest. */
  update(dtS: number, snapshot: SessionSnapshot, cars: readonly RenderCar[]): void {
    if (this.destroyed) return
    const { weather } = snapshot
    const nowS = snapshot.tick / TICK_RATE
    for (let i = 0; i < this.motors.length; i++) {
      const render = cars[i]
      const sim = snapshot.cars[i]
      if (render === undefined || sim === undefined) continue
      const pan = this.options.panOf(render.x)
      this.pans[i] = pan
      this.speeds[i] = render.speedMS
      const grass = sim.surface === 'grass'
      this.motors[i]?.update({
        motorRadS: sim.motorRadS,
        throttle: sim.throttle,
        speedMS: render.speedMS,
        slipFront: render.slipFront,
        slipRear: render.slipRear,
        wetness: weather.wetness,
        onGrass: grass,
        bog: sim.bog,
        alive: sim.state === 'driving' || sim.state === 'finished',
        pan,
      })

      // A wheel on a kerb: a rumble, retriggered while it stays.
      if (sim.surface === 'kerb' && !sim.airborne && sim.state === 'driving' && nowS >= (this.nextRumbleS[i] ?? 0)) {
        const gain = kerbRumbleGain(render.speedMS)
        if (gain > 0) {
          this.sfx.play('kerb-rumble', { gain: gain * (i === this.options.playerCar ? 1 : OTHERS_SHARE), pan, car: i, timeS: nowS })
          this.nextRumbleS[i] = nowS + RUMBLE_EVERY_S
        }
      }

      // The roll's second phase: dragged on its roof. The thump was the `flip` event; the scrape begins at the slide tick.
      if (sim.state === 'flipped' && sim.rollSlideTick != null && snapshot.tick >= sim.rollSlideTick && this.scrapedFor[i] !== sim.stateSinceTick) {
        this.scrapedFor[i] = sim.stateSinceTick
        this.sfx.play('roll-scrape', { gain: i === this.options.playerCar ? 1 : OTHERS_SHARE, pan, car: i, timeS: nowS })
      }

      // Through a puddle: a splash on the way in.
      const inside = this.inPuddle[i]
      if (inside !== undefined) {
        weather.puddles.forEach((puddle, index) => {
          const now = puddle.r > 0 && Math.hypot(render.x - puddle.x, render.y - puddle.y) < puddle.r + PUDDLE_SLACK_M
          if (now && inside[index] !== true) {
            const gain = splashGain(render.speedMS, puddle.depth)
            if (gain > 0) this.sfx.play('splash', { gain: gain * (i === this.options.playerCar ? 1 : OTHERS_SHARE), pan, car: i, timeS: nowS })
          }
          inside[index] = now
        })
      }
    }
    this.ambience.update(dtS, weather.rainIntensity, Math.hypot(weather.wind.x, weather.wind.y))
  }

  /** The crowd's cheer at the finish: how many were asked for and heard, and whether one sounds now. For the debug hook and the tests. */
  get crowd(): { requested: number; played: number; playing: boolean } {
    return { requested: this.cheering.requested, played: this.cheering.played, playing: this.cheering.playing }
  }

  /** Whether the weather's beds have live nodes: rain, wind. */
  get beds(): { rain: boolean; wind: boolean } {
    return { rain: this.ambience.rainRunning, wind: this.ambience.windRunning }
  }

  /** Stops every voice and one-shot and disconnects every node this race made, and hands the context back to the menus. */
  destroy(): void {
    if (this.destroyed) return
    this.destroyed = true
    for (const off of this.unsubscribe) off()
    this.unsubscribe.length = 0
    for (const motor of this.motors) motor.dispose()
    this.motors.length = 0
    this.ambience.dispose()
    this.tones.dispose()
    this.cheering.dispose()
    this.sfx.dispose()
    // The race may have been left from its pause overlay; the menus after it make sound.
    this.mixer.resume()
  }
}
