import Phaser from 'phaser'
import { loadFailure, type Failure } from './failure'

// Putting a failure on the screen (F-803): every scene that loads files asks `failOnLoadError`, and anything that cannot
// carry on calls `reportFailure`. The first failure is the one that is shown; whatever else goes wrong after it is a
// consequence of it, and the scenes that were running are stopped so that nothing carries on to cover it.

const failed = new WeakSet<Phaser.Game>()

/** A failure has been reported: scenes that go on from a load (a `COMPLETE` callback, a `create`) must check this before they do. */
export function hasFailed(game: Phaser.Game): boolean {
  return failed.has(game)
}

/** Stops every scene that is up and shows the error scene with `failure`. Only the first call has any effect. */
export function reportFailure(game: Phaser.Game, failure: Failure): void {
  if (failed.has(game)) return
  failed.add(game)
  for (const scene of game.scene.getScenes(false)) {
    const { status } = scene.sys.settings
    if (status >= Phaser.Scenes.INIT && status <= Phaser.Scenes.SLEEPING) game.scene.stop(scene.scene.key)
  }
  game.scene.start('Error', failure)
}

/**
 * Makes a file that cannot be loaded, by this scene's loader, a failure on the screen. The scene's loader drops its
 * listeners when the scene shuts down, so this is called each time the scene starts, before it loads anything.
 * `ignore` names the files whose loss the game can live without: they are not reported. Returns the function that stops watching.
 */
export function failOnLoadError(scene: Phaser.Scene, ignore: (file: Phaser.Loader.File) => boolean = () => false): () => void {
  const failed = (file: Phaser.Loader.File): void => {
    if (!ignore(file)) reportFailure(scene.game, loadFailure(file))
  }
  scene.load.on(Phaser.Loader.Events.FILE_LOAD_ERROR, failed)
  return () => {
    scene.load.off(Phaser.Loader.Events.FILE_LOAD_ERROR, failed)
  }
}
