import type Phaser from 'phaser'
import type { Vec2 } from '@sim'
import { THEME, charWidth, lineHeight } from './theme'
import { setTextIfChanged, text } from './text'
import type { ClassStats } from './stats'

/** The words beside each bar, in the order they are drawn. */
export const BAR_LABELS: ReadonlyArray<readonly [keyof ClassStats, string]> = [
  ['acceleration', 'ACCELERATION'],
  ['topSpeed', 'TOP SPEED'],
  ['grip', 'GRIP'],
  ['stability', 'STABILITY'],
]

const LABEL_CHARS = 12
const BAR_HEIGHT = 24
/** Logical pixels between the tops of two bars. */
const PITCH = 56

/** Four labelled bars, each a track with a filled part whose length is the value (0..1) and a percentage after it. */
export class StatBars {
  private readonly fills = new Map<keyof ClassStats, Phaser.GameObjects.Rectangle>()
  private readonly percents = new Map<keyof ClassStats, Phaser.GameObjects.BitmapText>()
  private readonly parts: Phaser.GameObjects.GameObject[] = []
  private readonly values: ClassStats = { acceleration: -1, topSpeed: -1, grip: -1, stability: -1 }
  private readonly barWidth: number

  constructor(scene: Phaser.Scene, pos: Vec2, widthPx: number) {
    const label = LABEL_CHARS * charWidth('body')
    const percent = 5 * charWidth('body')
    this.barWidth = widthPx - label - percent - 2 * THEME.padding
    const barX = pos.x + label + THEME.padding
    BAR_LABELS.forEach(([key, words], i) => {
      const y = pos.y + i * PITCH
      const textY = y + Math.round((BAR_HEIGHT - lineHeight('body')) / 2)
      this.parts.push(text(scene, { x: pos.x, y: textY }, words, 'body'))
      this.parts.push(scene.add.rectangle(barX, y, this.barWidth, BAR_HEIGHT, THEME.colours.barTrack).setOrigin(0, 0))
      const fill = scene.add.rectangle(barX, y, 0, BAR_HEIGHT, THEME.colours.barFill).setOrigin(0, 0)
      this.fills.set(key, fill)
      const pct = text(scene, { x: barX + this.barWidth + THEME.padding, y: textY }, '', 'body').setTint(THEME.colours.textDim)
      this.percents.set(key, pct)
      this.parts.push(fill, pct)
    })
  }

  /** The bars as drawn, 0..1 each (-1 before the first `set`). */
  get shown(): Readonly<ClassStats> {
    return this.values
  }

  /** Shows `stats`. Only a bar whose value changed is touched. */
  set(stats: ClassStats): void {
    for (const [key] of BAR_LABELS) {
      const value = Math.min(1, Math.max(0, stats[key]))
      if (value === this.values[key]) continue
      this.values[key] = value
      this.fills.get(key)?.setSize(Math.round(value * this.barWidth), BAR_HEIGHT)
      const pct = this.percents.get(key)
      if (pct !== undefined) setTextIfChanged(pct, `${Math.round(value * 100)}%`.padStart(4))
    }
  }

  destroy(): void {
    for (const part of this.parts) part.destroy()
    this.parts.length = 0
    this.fills.clear()
    this.percents.clear()
  }
}
