import type Phaser from 'phaser'
import type { CarClassId, CarColour } from '@sim'
import { directionSet, manifestOf } from '../assets/manifest'
import { carSpriteName, shadowSpriteName, SHADOW_OFFSET_PX } from '../race/CarView'
import { atlasKeyFor } from './atlas'
import type { Rect } from './layout'
import { ensureClassAtlas, type ClassAtlasLoad } from './loader'
import { setTextIfChanged, text } from './text'
import { THEME, lineHeight } from './theme'

/** Whole-number scale of the sprite: the sprites are 36 px long and there is no larger art (F-203). */
const SCALE = 6
/** Room between the stage and the label under it. */
const LABEL_GAP = 16

/** What a test or a tool may read of the picture. */
export interface CarPictureInfo {
  atlas: string
  frame: string
  scale: number
  lengthPx: number
  label: string
  loading: boolean
}

/**
 * A car shown as a picture: the sprite the garage shows for the class and colour (by manifest name), in its colour,
 * on a stage, with the class label under it. The class's atlas is fetched on demand if it is not in the cache yet
 * (the picture says LOADING until it lands). The label is given, not looked up: the screen says which words it wants.
 * The stage is `rect` wide and `stageHeight` tall; the label takes the line under it.
 */
export class CarPicture {
  private readonly stage: Phaser.GameObjects.Rectangle
  private readonly shadow: Phaser.GameObjects.Image
  private readonly body: Phaser.GameObjects.Image
  private readonly loadingText: Phaser.GameObjects.BitmapText
  private readonly labelText: Phaser.GameObjects.BitmapText
  private download: ClassAtlasLoad | null = null
  private alive = true
  private carClass: CarClassId
  private colour: CarColour

  constructor(
    private readonly scene: Phaser.Scene,
    rect: Rect,
    carClass: CarClassId,
    colour: CarColour,
    label: string,
  ) {
    this.carClass = carClass
    this.colour = colour
    const cx = rect.x + Math.round(rect.w / 2)
    const cy = rect.y + Math.round(rect.h / 2)
    this.stage = scene.add.rectangle(rect.x, rect.y, rect.w, rect.h, THEME.colours.stage).setOrigin(0, 0)
    this.shadow = scene.add.image(cx + SHADOW_OFFSET_PX.x * SCALE, cy + SHADOW_OFFSET_PX.y * SCALE, '__DEFAULT').setScale(SCALE).setVisible(false)
    this.body = scene.add.image(cx, cy, '__DEFAULT').setScale(SCALE).setVisible(false)
    this.loadingText = text(scene, { x: cx, y: cy - Math.round(lineHeight('body') / 2) }, 'LOADING', 'body').setOrigin(0.5, 0).setVisible(false)
    this.labelText = text(scene, { x: cx, y: rect.y + rect.h + LABEL_GAP }, label, 'body').setOrigin(0.5, 0)
    this.show(carClass, colour, label)
  }

  /** Shows this car, with this label under it, fetching the class's atlas first if it is not there. */
  show(carClass: CarClassId, colour: CarColour, label: string): void {
    this.carClass = carClass
    this.colour = colour
    setTextIfChanged(this.labelText, label)
    const manifest = manifestOf(this.scene)
    const ready = this.scene.textures.exists(atlasKeyFor(manifest, carClass))
    this.loadingText.setVisible(!ready)
    this.body.setVisible(ready)
    this.shadow.setVisible(ready)
    if (!ready) {
      if (this.download === null) {
        this.download = ensureClassAtlas(this.scene, carClass, () => {
          this.download = null
          if (this.alive) this.show(this.carClass, this.colour, this.labelText.text)
        })
      }
      return
    }
    const body = directionSet(manifest, carSpriteName(carClass, colour))
    const shadow = directionSet(manifest, shadowSpriteName(carClass))
    this.body.setTexture(body.atlas, body.frames[0])
    this.shadow.setTexture(shadow.atlas, shadow.frames[0])
  }

  info(): CarPictureInfo {
    const { body } = this
    return {
      atlas: body.texture.key,
      frame: String(body.frame.name),
      scale: body.scaleX,
      lengthPx: body.frame.cutWidth * body.scaleX,
      label: this.labelText.text,
      loading: this.loadingText.visible,
    }
  }

  destroy(): void {
    this.alive = false
    this.download?.cancel()
    this.download = null
    for (const part of [this.stage, this.shadow, this.body, this.loadingText, this.labelText]) part.destroy()
  }
}
