import type Phaser from 'phaser'
import type { Vec2 } from '@sim'
import type { NavKey, TextKey } from '../input/keys'
import { cleanName, nameReduce, nameStart, NAME_MAX, type NameState } from '../persistence/name'
import { Row } from './Row'
import { THEME, charWidth, type TextSize } from './theme'

export interface TextFieldOptions {
  size?: TextSize
  /** Characters the label column takes; the default fits the label. */
  labelChars?: number
  /** What is shown while no value is set. */
  empty: string
}

/** Blank characters between the label and the value. */
const GAP = 3
const CARET_WIDTH = 3

/**
 * One setting that is a short piece of text, a name: it reads `▶ LABEL   VALUE` like a row of a form, and Enter on it
 * starts typing. While it is being typed in, a caret shows where the next character goes; ← → move it, Backspace
 * deletes, Enter keeps what was typed (cleaned: capitals, no leading or trailing spaces; nothing left means no value)
 * and Esc leaves the value as it was. The characters come from the guarded `onText` helper, through `type`. Pass the
 * row to a `Form` to share a focus ring with other rows.
 */
export class TextField {
  private readonly row: Row
  private readonly caret: Phaser.GameObjects.Rectangle
  private readonly labelChars: number
  private readonly size: TextSize
  private readonly kept: Array<(value: string | null) => void> = []
  private current: string | null
  private state: NameState | null = null
  private focused = false

  constructor(
    scene: Phaser.Scene,
    private readonly pos: Vec2,
    private readonly label: string,
    value: string | null,
    private readonly opts: TextFieldOptions,
  ) {
    this.size = opts.size ?? 'body'
    this.labelChars = opts.labelChars ?? label.length
    this.current = value
    const chars = this.line().length + NAME_MAX
    this.row = new Row(scene, pos.x, pos.y, chars * charWidth(this.size), this.size, this.line())
    this.caret = scene.add.rectangle(0, pos.y, CARET_WIDTH, this.row.heightPx, THEME.colours.accent).setOrigin(0, 0).setVisible(false)
    this.paint()
  }

  /** The value kept: the name, or null when there is none. */
  get value(): string | null {
    return this.current
  }

  /** Whether the field is being typed in: every nav key and every typed key belongs to it. */
  get editing(): boolean {
    return this.state !== null
  }

  /** What is on the field's line after the label: the text being typed, or the value, or the empty word. */
  get shown(): string {
    return this.state?.text ?? this.current ?? this.opts.empty
  }

  /** The height of the row, for stacking. */
  get heightPx(): number {
    return this.row.heightPx
  }

  /** Calls `fn` with the value each time Enter keeps what was typed. */
  onChange(fn: (value: string | null) => void): void {
    this.kept.push(fn)
  }

  setFocused(focused: boolean): void {
    this.focused = focused
    // Focus moves only when the field is not being typed in, but a field that loses it anyway is left as it was.
    if (!focused) this.state = null
    this.paint()
  }

  /** Acts on a menu key; true if the field used it. Enter starts the typing; while typing, every key is the field's. */
  handle(key: NavKey): boolean {
    const state = this.state
    if (state === null) {
      if (key !== 'confirm') return false
      this.state = nameStart(this.current)
      this.paint()
      return true
    }
    if (key === 'left' || key === 'right') this.state = nameReduce(state, { type: key })
    else if (key === 'confirm') {
      this.current = cleanName(state.text)
      this.state = null
      for (const fn of this.kept) fn(this.current)
    } else if (key === 'back') this.state = null
    this.paint()
    return true
  }

  /** A typed character or Backspace; ignored unless the field is being typed in. */
  type(key: TextKey): void {
    if (this.state === null) return
    this.state = nameReduce(this.state, key)
    this.paint()
  }

  private line(): string {
    const cursor = this.focused ? THEME.cursorGlyph : ' '
    return `${cursor} ${this.label.padEnd(this.labelChars)}${' '.repeat(GAP)}${this.shown}`
  }

  private paint(): void {
    this.row.setLabel(this.line())
    this.row.setTone(this.focused ? 'focus' : 'normal')
    const state = this.state
    this.caret.setVisible(state !== null)
    if (state !== null) this.caret.setX(this.pos.x + (2 + this.labelChars + GAP + state.cursor) * charWidth(this.size))
  }

  destroy(): void {
    this.row.destroy()
    this.caret.destroy()
    this.kept.length = 0
  }
}
