export interface Focusable {
  id: string
  enabled: boolean
}

/**
 * Which one item of a list has focus. Exactly one item is focused at any time (or none, when nothing is enabled);
 * moving skips disabled items and, by default, wraps round the ends. Pure, so the rules are tested without an engine.
 */
export class FocusRing {
  private items: Focusable[]
  private index: number

  constructor(
    items: readonly Focusable[],
    private readonly wrap = true,
  ) {
    this.items = items.map((item) => ({ ...item }))
    this.index = this.firstEnabled()
  }

  /** The id of the focused item, or null if there is no enabled item. */
  get current(): string | null {
    return this.items[this.index]?.id ?? null
  }

  /** Moves focus to the next (+1) or previous (-1) enabled item and returns the focused id. At an end without wrap, focus stays. */
  move(delta: 1 | -1): string | null {
    const count = this.items.length
    if (this.index < 0) return null
    let at = this.index
    for (let step = 0; step < count; step++) {
      at += delta
      if (at < 0 || at >= count) {
        if (!this.wrap) break
        at = (at + count) % count
      }
      if (this.items[at]?.enabled === true) {
        this.index = at
        break
      }
    }
    return this.current
  }

  /** Focuses the item with this id. An unknown id or a disabled item is ignored. */
  set(id: string): void {
    const at = this.items.findIndex((item) => item.id === id)
    if (at >= 0 && this.items[at]?.enabled === true) this.index = at
  }

  /** Replaces the items. The focused one keeps focus if it is still there and enabled; otherwise the first enabled item takes it. */
  update(items: readonly Focusable[]): void {
    const keep = this.current
    this.items = items.map((item) => ({ ...item }))
    this.index = this.firstEnabled()
    if (keep !== null) this.set(keep)
  }

  private firstEnabled(): number {
    return this.items.findIndex((item) => item.enabled)
  }
}
