import Phaser from 'phaser'
import { manifestOf, registerFonts } from '../assets/manifest'
import { LOGICAL_HEIGHT, LOGICAL_WIDTH } from '../config'
import { hideFailureDom, showFailureDom } from './failure-dom'
import type { Failure } from './failure'
import { charsAcross, wrapText } from '../ui/layout'
import { FONT, text } from '../ui/text'
import { THEME, lineHeight } from '../ui/theme'

/** The text column's width on the 1920x1080 canvas. */
const COLUMN_PX = 1280
const TITLE_Y = 330
const GAP_PX = 36

/**
 * The screen for a game that cannot go on (F-803): what happened and what to try, in the game's own font, centred, with
 * nothing else on it. Started by `reportFailure` with a `Failure`; where the pixel font has not arrived (it is one of the
 * files that can fail) or the notice is not wanted in the canvas, the same words go up as an HTML panel instead. A notice
 * (`dismiss`) goes on to the title on a key press; a failure stays until the page is reloaded.
 */
export class ErrorScene extends Phaser.Scene {
  private failure: Failure | null = null
  private release: (() => void) | null = null

  constructor() {
    super('Error')
  }

  init(data: Failure): void {
    this.failure = data
  }

  /**
   * The pixel font is there to draw with. The boot scene registers it only once everything it loads has arrived, so when another
   * file was the one that failed the font may be in the cache's files and not yet in its fonts: register it here if it has come.
   * If the font, or the manifest that says where it is, is what did not arrive, there is nothing to register and the answer is no.
   */
  private hasFont(): boolean {
    if (this.cache.bitmapFont.exists(FONT)) return true
    try {
      registerFonts(this, manifestOf(this))
    } catch {
      return false
    }
    return this.cache.bitmapFont.exists(FONT)
  }

  create(): void {
    const { failure } = this
    if (failure === null) return
    this.cameras.main.setBackgroundColor(THEME.colours.background)
    if (!this.hasFont()) {
      showFailureDom(failure)
      this.events.once(Phaser.Scenes.Events.SHUTDOWN, hideFailureDom)
      return
    }
    const centre = LOGICAL_WIDTH / 2
    text(this, { x: centre, y: TITLE_Y }, failure.title.toUpperCase(), 'large').setOrigin(0.5, 0).setTint(THEME.colours.accent).setName('failure-title')
    let y = TITLE_Y + lineHeight('large') + GAP_PX
    for (const line of failure.lines) {
      const wrapped = wrapText(line, charsAcross(COLUMN_PX, 'body'))
      text(this, { x: centre, y }, wrapped.join('\n'), 'body').setOrigin(0.5, 0).setName('failure-line')
      y += wrapped.length * lineHeight('body') + GAP_PX
    }
    if (failure.dismiss) {
      text(this, { x: centre, y: Math.min(LOGICAL_HEIGHT - 120, y + GAP_PX) }, 'PRESS ANY KEY', 'body').setOrigin(0.5, 0).setTint(THEME.colours.textDim).setName('failure-hint')
      // A plain DOM listener (AGENTS.md rule 2 keeps the game off Phaser's key events): any key goes on to the title.
      const go = (): void => {
        this.release?.()
        this.release = null
        this.scene.start('Title')
      }
      window.addEventListener('keydown', go, true)
      this.release = () => window.removeEventListener('keydown', go, true)
    }
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => {
      this.release?.()
      this.release = null
    })
  }
}
