import type { AssetManifest } from './manifest'

// Animations in the art build's manifest (contracts.md §11): a marshal's walk, a driver's reaction. Like every other
// sprite they are asked for by manifest name. This file has no engine in it, so that the rules that choose an
// animation can be tested without one.

/** A list of frames played in order, by manifest name. */
export interface Animation {
  atlas: string
  /** Atlas frames, in the order they are shown. */
  frames: readonly string[]
  /** Frames a second at the animation's own rate. */
  fps: number
  /** Whether it starts again after its last frame. */
  loop: boolean
  /** The whole cell, in art pixels: the same for every frame, so one placement serves them all. */
  size: { w: number; h: number }
  /** The point of the cell that is placed, 0..1. For a person it is the ground between the feet. */
  pivot: { x: number; y: number }
  /** Screen pixels per art pixel at the art's own density. */
  scale: number
}

/**
 * An animation by manifest name. Throws for an unknown name, for a single frame, and for a baked direction set, whose
 * frames are headings and not moments.
 */
export function animation(manifest: AssetManifest, name: string): Animation {
  const entry = manifest.sprites[name]
  if (entry === undefined) throw new Error(`The manifest has no sprite named '${name}'`)
  if (!('frames' in entry) || entry.directions !== undefined || entry.frameSize === undefined) throw new Error(`Sprite '${name}' is not an animation`)
  return {
    atlas: entry.atlas,
    frames: entry.frames,
    fps: entry.fps,
    loop: entry.loop,
    size: entry.frameSize,
    pivot: entry.pivot ?? { x: 0.5, y: 0.5 },
    scale: 1 / (entry.artPixelsPerScreenPixel ?? 1),
  }
}
