import type Phaser from 'phaser'
import { manifestOf, still } from '../assets/sprites'
import { Skin } from './skin'
import { THEME, lineHeight, type TextSize } from './theme'
import { setTextIfChanged, text } from './text'

/**
 * How a row of text looks: focus is the skin's focus bar and the accent colour (the cursor glyph is part of the words);
 * a row that cannot be chosen is dim and carries the unavailable mark in the cursor's column, so that neither state is
 * told by colour alone; a button that is not focused stands in the button frame.
 */
export type RowTone = 'normal' | 'focus' | 'dim' | 'off'

const TINT: Record<RowTone, number> = {
  normal: THEME.colours.text,
  focus: THEME.colours.accent,
  dim: THEME.colours.textDim,
  off: THEME.colours.textOff,
}

/** Space the highlight bar adds above and below the text, and to its left, in logical pixels. */
const BAR_PAD = 6
const BAR_PAD_X = 12

/**
 * One line of a menu: a line of text and, behind it while focused, the focus bar. The building block of the list, the
 * selector and the buttons. Its first character is the cursor's column: the cursor glyph when focused, the unavailable
 * mark (a picture, not a character, so the words stay the same) when it cannot be chosen.
 */
export class Row {
  readonly label: Phaser.GameObjects.BitmapText
  private readonly bar: Skin
  /** The frame of a button that is not focused; null for a row that is not a button. */
  private readonly frame: Skin | null
  private readonly offMark: Phaser.GameObjects.Image
  private tone: RowTone | null = null

  constructor(
    scene: Phaser.Scene,
    readonly x: number,
    readonly y: number,
    readonly widthPx: number,
    readonly size: TextSize,
    value: string,
    opts: { button?: boolean } = {},
  ) {
    const box = { x: x - BAR_PAD_X, y: y - BAR_PAD, w: widthPx + 2 * BAR_PAD_X, h: lineHeight(size) + 2 * BAR_PAD }
    this.frame = opts.button === true ? new Skin(scene, THEME.skin.button).place(box).setVisible(false) : null
    this.bar = new Skin(scene, THEME.skin.bar).place(box).setVisible(false)
    const mark = still(manifestOf(scene), THEME.offMark)
    this.offMark = scene.add.image(x, y, mark.atlas, mark.frame).setOrigin(0, 0).setScale(THEME.sizes[size]).setVisible(false)
    this.label = text(scene, { x, y }, value, size)
    this.setTone('normal')
  }

  /** The height of the row's text. */
  get heightPx(): number {
    return lineHeight(this.size)
  }

  setLabel(value: string): void {
    setTextIfChanged(this.label, value)
  }

  setTone(tone: RowTone): void {
    if (tone === this.tone) return
    this.tone = tone
    this.label.setTint(TINT[tone])
    this.bar.setVisible(tone === 'focus')
    this.frame?.setVisible(tone !== 'focus')
    this.offMark.setVisible(tone === 'off')
  }

  destroy(): void {
    this.bar.destroy()
    this.frame?.destroy()
    this.offMark.destroy()
    this.label.destroy()
  }
}
