import type Phaser from 'phaser'
import type { NavKey } from '../input/keys'
import { ButtonRow } from './ButtonRow'
import { Panel } from './Panel'
import { charsAcross, wrapText } from './layout'
import { THEME, lineHeight } from './theme'
import { text } from './text'

export interface ConfirmOptions {
  message: string
  confirmLabel?: string
  cancelLabel?: string
  /** The dialog's width in logical pixels. */
  widthPx?: number
}

const DEFAULT_WIDTH = 900

/**
 * A modal question over the current scene: a dimmed screen, a panel with the message and two buttons. Focus starts
 * on the cancel button, so Enter alone never does the thing asked about; Esc cancels. Route every menu key to
 * `handle` while it is open.
 */
export class ConfirmDialog {
  private readonly parts: Phaser.GameObjects.GameObject[] = []
  private readonly panel: Panel
  private readonly buttons: ButtonRow
  private readonly answers: Array<(confirmed: boolean) => void> = []

  constructor(scene: Phaser.Scene, opts: ConfirmOptions) {
    const { width, height } = scene.scale
    const w = opts.widthPx ?? DEFAULT_WIDTH
    const lines = wrapText(opts.message, charsAcross(w - 2 * THEME.padding, 'body'))
    const h = 2 * THEME.padding + (lines.length + 3) * lineHeight('body')
    const rect = { x: Math.round((width - w) / 2), y: Math.round((height - h) / 2), w, h }
    this.parts.push(scene.add.rectangle(0, 0, width, height, THEME.colours.shade, 0.6).setOrigin(0, 0))
    this.panel = new Panel(scene, rect)
    this.parts.push(text(scene, { x: this.panel.inner.x, y: this.panel.inner.y }, lines.join('\n'), 'body'))
    this.buttons = new ButtonRow(scene, { x: this.panel.inner.x, y: rect.y + h - THEME.padding - lineHeight('body') }, [
      { id: 'cancel', label: opts.cancelLabel ?? 'CANCEL' },
      { id: 'confirm', label: opts.confirmLabel ?? 'OK' },
    ])
    this.buttons.setFocused(true)
    this.buttons.onPress((id) => this.answer(id === 'confirm'))
  }

  /** Calls `fn` once with true if the player confirmed and false if they cancelled. */
  onAnswer(fn: (confirmed: boolean) => void): void {
    this.answers.push(fn)
  }

  /** Acts on a menu key. The dialog uses every key: nothing reaches the screen under it. */
  handle(key: NavKey): boolean {
    if (key === 'back') this.answer(false)
    else this.buttons.handle(key)
    return true
  }

  private answer(confirmed: boolean): void {
    const listeners = this.answers.splice(0)
    for (const fn of listeners) fn(confirmed)
  }

  destroy(): void {
    this.buttons.destroy()
    this.panel.destroy()
    for (const part of this.parts) part.destroy()
    this.parts.length = 0
    this.answers.length = 0
  }
}
