// The driving keys and what the player may rebind them to (F-801, contracts.md § 12). Pure: no engine, so that the rules
// run in Node. A key is a `KeyboardEvent.code` (the key's place on the keyboard, whatever the layout and whatever the
// shift state), which is what the settings keep and what `Keyboard` reads while driving.

export type Action = 'throttle' | 'brake' | 'left' | 'right' | 'pause'
export type Bindings = Record<Action, string>

/** The five actions in the order the options screen lists them. */
export const ACTIONS: readonly Action[] = ['throttle', 'brake', 'left', 'right', 'pause']

/** What each action is called on the options screen. */
export const ACTION_LABELS: Readonly<Record<Action, string>> = {
  throttle: 'THROTTLE',
  brake: 'BRAKE',
  left: 'STEER LEFT',
  right: 'STEER RIGHT',
  pause: 'PAUSE',
}

/** The arrow keys and P (game-design.md, "Controls"). Esc pauses as well, always. */
export const DEFAULT_BINDINGS: Readonly<Bindings> = Object.freeze({ throttle: 'ArrowUp', brake: 'ArrowDown', left: 'ArrowLeft', right: 'ArrowRight', pause: 'KeyP' })

/**
 * Keys that cannot be bound: Enter and Esc drive the menus; Tab, Backspace, the function keys, the Windows/Command
 * keys and the context-menu key belong to the browser; M, V, T, L and O already do something in a race (the music, the
 * voices, the tuning panel, the racing lines and the walls) and would fire while driving.
 */
export const RESERVED: ReadonlySet<string> = new Set([
  'Enter',
  'NumpadEnter',
  'Escape',
  'Tab',
  'Backspace',
  'ContextMenu',
  'MetaLeft',
  'MetaRight',
  'OSLeft',
  'OSRight',
  ...Array.from({ length: 12 }, (_, i) => `F${i + 1}`),
  'KeyM',
  'KeyV',
  'KeyT',
  'KeyL',
  'KeyO',
])

/**
 * The keys that can be bound, each with the key code Phaser's key capture knows it by (the arrows are captured so that the page
 * does not scroll). The letters, digits, arrows, space, the number pad and the punctuation keys of a US layout.
 */
const CAPTURE: Readonly<Record<string, number>> = {
  ArrowLeft: 37,
  ArrowUp: 38,
  ArrowRight: 39,
  ArrowDown: 40,
  Space: 32,
}

const PUNCTUATION = ['Comma', 'Period', 'Slash', 'Semicolon', 'Quote', 'BracketLeft', 'BracketRight', 'Backslash', 'Minus', 'Equal', 'Backquote']
const NUMPAD = ['Numpad0', 'Numpad1', 'Numpad2', 'Numpad3', 'Numpad4', 'Numpad5', 'Numpad6', 'Numpad7', 'Numpad8', 'Numpad9', 'NumpadAdd', 'NumpadSubtract', 'NumpadMultiply', 'NumpadDivide', 'NumpadDecimal']

const BINDABLE: ReadonlySet<string> = new Set([
  ...Object.keys(CAPTURE),
  ...Array.from({ length: 26 }, (_, i) => `Key${String.fromCharCode(65 + i)}`),
  ...Array.from({ length: 10 }, (_, i) => `Digit${i}`),
  ...PUNCTUATION,
  ...NUMPAD,
])

/** Whether a key code can be bound at all: a key the game knows how to name, that is not reserved. */
export const isBindable = (code: string): boolean => BINDABLE.has(code) && !RESERVED.has(code)

/** The key code Phaser's key capture is given for a bound key, or null where the key needs none (a letter does not scroll the page). */
export const captureCodeOf = (code: string): number | null => CAPTURE[code] ?? null

export type RebindError = 'reserved' | 'unsupported'

/**
 * The bindings with `action` on `code`. A key another action already has is swapped: the other action takes the key
 * `action` had. A reserved key, or one the game cannot name, changes nothing. Binding an action to its own key is no change.
 */
export function rebind(current: Bindings, action: Action, code: string): { bindings: Bindings; swappedWith: Action | null } | { error: RebindError } {
  if (RESERVED.has(code)) return { error: 'reserved' }
  if (!BINDABLE.has(code)) return { error: 'unsupported' }
  const other = ACTIONS.find((one) => one !== action && current[one] === code) ?? null
  if (other === null) return { bindings: { ...current, [action]: code }, swappedWith: null }
  return { bindings: { ...current, [action]: code, [other]: current[action] }, swappedWith: other }
}

/**
 * Bindings read back from storage: a value that is not a bindable key, or that two actions share, is a damaged setting, and the
 * whole set goes back to the defaults. An action missing from an older save has its default, if no other action has taken that key.
 */
export function readBindings(raw: unknown): Bindings {
  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) return { ...DEFAULT_BINDINGS }
  const stored = raw as Record<string, unknown>
  const read: Partial<Bindings> = {}
  for (const action of ACTIONS) {
    const value = stored[action]
    if (value === undefined) continue
    if (typeof value !== 'string' || !isBindable(value)) return { ...DEFAULT_BINDINGS }
    read[action] = value
  }
  const taken = new Set(Object.values(read))
  if (taken.size !== Object.keys(read).length) return { ...DEFAULT_BINDINGS }
  const bindings = { ...DEFAULT_BINDINGS }
  for (const action of ACTIONS) {
    const value = read[action]
    if (value !== undefined) bindings[action] = value
    else if (taken.has(bindings[action])) return { ...DEFAULT_BINDINGS }
  }
  return bindings
}

/** Whether two sets of bindings are the same keys. */
export const sameBindings = (a: Bindings, b: Bindings): boolean => ACTIONS.every((action) => a[action] === b[action])

const NAMED: Readonly<Record<string, string>> = {
  ArrowLeft: '←',
  ArrowUp: '↑',
  ArrowRight: '→',
  ArrowDown: '↓',
  Space: 'SPACE',
  Comma: ',',
  Period: '.',
  Slash: '/',
  Semicolon: ';',
  Quote: "'",
  BracketLeft: '[',
  BracketRight: ']',
  Backslash: '\\',
  Minus: '-',
  Equal: '=',
  Backquote: '`',
  NumpadAdd: 'NUM +',
  NumpadSubtract: 'NUM -',
  NumpadMultiply: 'NUM *',
  NumpadDivide: 'NUM /',
  NumpadDecimal: 'NUM .',
}

/** The words for a key on the options screen, in the pixel font's characters: ←, A, 5, SPACE, NUM 7. */
export function keyLabel(code: string): string {
  const named = NAMED[code]
  if (named !== undefined) return named
  if (/^Key[A-Z]$/.test(code)) return code.slice(3)
  if (/^Digit\d$/.test(code)) return code.slice(5)
  if (/^Numpad\d$/.test(code)) return `NUM ${code.slice(6)}`
  return code.toUpperCase()
}
