import type Phaser from 'phaser'
import { animation } from '../assets/animation'
import { manifestOf } from '../assets/manifest'
import { TAG_COLOUR } from '../race/hud-format'
import { CONFETTI, confettiFlakes, flakeAt, type Flake } from './confetti-fall'

/** The confetti's flake in the skin atlas (art/skin/build.py): four turns, white, tinted here to a body colour. */
const FLAKE = 'skin.confetti'

/**
 * A burst of confetti falling once over a screen (F-802, the podium): the flakes of `confettiFlakes`, each a picture of
 * the skin atlas tinted to a body colour's base step and turning over as it falls, at `depth`. Driven by the frame clock
 * through `update`; every flake is hidden once it has fallen out of sight, and the whole is gone after `CONFETTI.lastS`.
 */
export class Confetti {
  private readonly flakes: Array<{ flake: Flake; image: Phaser.GameObjects.Image }>
  private readonly frames: readonly string[]
  private readonly fps: number
  private startS: number | null = null

  constructor(scene: Phaser.Scene, seed: number, width: number, depth: number) {
    const art = animation(manifestOf(scene), FLAKE)
    this.frames = art.frames
    this.fps = art.fps
    this.flakes = confettiFlakes(seed, width).map((flake) => ({
      flake,
      image: scene.add
        .image(flake.x, flake.y0, art.atlas, art.frames[flake.frame] ?? art.frames[0])
        .setOrigin(art.pivot.x, art.pivot.y)
        .setScale(art.scale)
        .setTint(TAG_COLOUR[flake.colour])
        .setDepth(depth)
        .setVisible(false),
    }))
  }

  /** Moves every flake to where it is `timeMs` (the frame clock) after the first call. */
  update(timeMs: number): void {
    this.startS ??= timeMs / 1000
    const t = timeMs / 1000 - this.startS
    for (const { flake, image } of this.flakes) {
      const { x, y } = flakeAt(flake, t)
      const shown = y > -8 && y < CONFETTI.floorPx + 8
      image.setVisible(shown)
      if (!shown) continue
      image.setPosition(x, y).setFrame(this.frames[(flake.frame + Math.floor(t * this.fps)) % this.frames.length] ?? '')
    }
  }

  /** How many flakes are on screen now. */
  get falling(): number {
    return this.flakes.reduce((count, { image }) => count + (image.visible ? 1 : 0), 0)
  }

  destroy(): void {
    for (const { image } of this.flakes) image.destroy()
    this.flakes.length = 0
  }
}
