import Phaser from 'phaser'
import { TICK_RATE, type Sky, type Tick, type WeatherSnapshot } from '@sim'
import { still, type AssetManifest } from '../assets/manifest'
import { THEME } from '../ui/theme'
import { DEPTH } from './depth'
import type { EventBus } from './EventBus'
import { ARROW_DIRECTIONS, ARROW_PX, arrowIndex, arrowPixels, kickOf, sockPicture, weatherHudLayout, type Box, type SockPicture } from './weather-look'

// The weather on the HUD (F-603): at the far right of the band above the track, the wind arrow, the windsock and the
// sky icon. The sock says how hard the wind blows and, to the nearest of its four drawn directions, which way; the
// arrow says exactly which way, to the nearest of sixteen. The sock's pictures and the sky icons are F-605's, in the
// atlas `hud`; the arrow is drawn here as hard pixels, once, into a texture of sixteen cells, in the HUD's text colour.

const ARROWS_KEY = 'hud-wind-arrows'
/** The icons and the sock are shown at the HUD's density, two screen pixels to an art pixel; the arrow's cells too. */
const ARROW_SCALE = 2

/** What the HUD's weather pieces show, for the debug hook and the browser tests. */
export interface WindSockInfo {
  sky: Sky
  skyPicture: string
  sock: SockPicture & { x: number; y: number; shakePx: number }
  arrow: { index: number; box: Box }
  boxes: { arrow: Box; sock: Box; sky: Box }
  /** The sock is being kicked by a gust. */
  kicked: boolean
}

export class WindSock {
  private readonly skyImage: Phaser.GameObjects.Image
  private readonly sockImage: Phaser.GameObjects.Image
  private readonly arrowImage: Phaser.GameObjects.Image
  private readonly layout: ReturnType<typeof weatherHudLayout>
  private readonly release: Array<() => void> = []
  private shownSky: Sky | null = null
  private shownSock = ''
  private shownArrow = -1
  private shownShake = 0
  private picture: SockPicture = { name: 'hud.windsock.0', flipX: false, flipY: false }
  private kick = { extra: 0, shakePx: 0 }
  /** The sim tick a gust last began on; null before the first. */
  private gustTick: Tick | null = null
  private destroyed = false

  constructor(
    private readonly scene: Phaser.Scene,
    private readonly manifest: AssetManifest,
    bus: EventBus,
    bandHeight: number,
  ) {
    this.layout = weatherHudLayout(bandHeight)
    const { sky, sock, arrow } = this.layout
    const depth = DEPTH.hud + 1

    this.bakeArrows()
    const first = still(manifest, 'hud.sky.sunny')
    const sockStill = still(manifest, 'hud.windsock.0')
    this.skyImage = scene.add.image(sky.x + sky.w / 2, sky.y + sky.h / 2, first.atlas, first.frame).setScale(first.scale).setDepth(depth)
    this.sockImage = scene.add.image(sock.x + sock.w / 2, sock.y + sock.h / 2, sockStill.atlas, sockStill.frame).setScale(sockStill.scale).setDepth(depth)
    this.arrowImage = scene.add.image(arrow.x + arrow.w / 2, arrow.y + arrow.h / 2, ARROWS_KEY, '0').setScale(ARROW_SCALE).setDepth(depth)
    this.release.push(bus.on('gust', (event) => (this.gustTick = event.tick)))
  }

  /** Sixteen cells of 12 x 12 art pixels in one canvas, one arrow in each, in the HUD's text colour. */
  private bakeArrows(): void {
    const { textures } = this.scene
    if (textures.exists(ARROWS_KEY)) textures.remove(ARROWS_KEY)
    const canvas = textures.createCanvas(ARROWS_KEY, ARROW_PX * ARROW_DIRECTIONS, ARROW_PX)
    if (canvas === null) throw new Error('WindSock: the arrow texture could not be created')
    const ctx = canvas.getContext()
    ctx.fillStyle = `#${THEME.colours.text.toString(16).padStart(6, '0')}`
    for (let i = 0; i < ARROW_DIRECTIONS; i++) {
      const pixels = arrowPixels(i)
      for (let y = 0; y < ARROW_PX; y++) for (let x = 0; x < ARROW_PX; x++) if (pixels[y * ARROW_PX + x] === 1) ctx.fillRect(i * ARROW_PX + x, y, 1, 1)
      canvas.add(String(i), 0, i * ARROW_PX, 0, ARROW_PX, ARROW_PX)
    }
    canvas.refresh()
    canvas.setFilter(Phaser.Textures.FilterMode.NEAREST)
  }

  /** Brings the sky icon, the sock and the arrow up to the weather as it is at session tick `tick`. */
  update(weather: WeatherSnapshot, tick: Tick): void {
    if (this.destroyed) return
    if (weather.sky !== this.shownSky) {
      this.shownSky = weather.sky
      this.skyImage.setFrame(still(this.manifest, `hud.sky.${weather.sky}`).frame)
    }

    this.kick = kickOf(this.gustTick === null ? null : (tick - this.gustTick) / TICK_RATE)
    this.picture = sockPicture(weather.wind, this.kick.extra)
    const key = `${this.picture.name}|${this.picture.flipX}|${this.picture.flipY}`
    if (key !== this.shownSock) {
      this.shownSock = key
      this.sockImage.setFrame(still(this.manifest, this.picture.name).frame).setFlip(this.picture.flipX, this.picture.flipY)
    }
    if (this.kick.shakePx !== this.shownShake) {
      this.shownShake = this.kick.shakePx
      this.sockImage.setY(this.layout.sock.y + this.layout.sock.h / 2 + this.kick.shakePx)
    }

    const index = arrowIndex(weather.wind)
    if (index !== this.shownArrow) {
      this.shownArrow = index
      this.arrowImage.setFrame(String(index))
    }
  }

  info(): WindSockInfo {
    return {
      sky: this.shownSky ?? 'sunny',
      skyPicture: this.skyImage.frame.name,
      sock: { ...this.picture, x: this.sockImage.x, y: this.sockImage.y, shakePx: this.kick.shakePx },
      arrow: { index: this.shownArrow, box: this.layout.arrow },
      boxes: this.layout,
      kicked: this.kick.extra > 0,
    }
  }

  destroy(): void {
    if (this.destroyed) return
    this.destroyed = true
    for (const off of this.release) off()
    this.release.length = 0
    this.skyImage.destroy()
    this.sockImage.destroy()
    this.arrowImage.destroy()
    if (this.scene.textures.exists(ARROWS_KEY)) this.scene.textures.remove(ARROWS_KEY)
  }
}
