import { angleDiff, lerp, TWO_PI, wrapAngle, type CarId, type CarSnapshot, type CarState, type Pose } from '@sim'

/** What the renderers need of a car at the instant a frame is drawn: the sim's last two snapshots blended. */
export interface RenderCar {
  id: CarId
  /** World metres. */
  x: number
  y: number
  /** Radians, clockwise from +x, in (-π, π]. */
  angle: number
  speedMS: number
  state: CarState
  slipFront: number
  slipRear: number
  steerRad: number
}

/**
 * A pose `alpha` of the way from `a` to `b` (0 gives `a`, 1 gives `b`). Position blends linearly; the heading
 * turns the short way round, so 359° to 1° passes through 0°.
 */
export function lerpPose(a: Pose, b: Pose, alpha: number): Pose {
  return { x: lerp(a.x, b.x, alpha), y: lerp(a.y, b.y, alpha), angle: lerpAngle(a.angle, b.angle, alpha) }
}

function lerpAngle(from: number, to: number, alpha: number): number {
  if (alpha <= 0) return from
  if (alpha >= 1) return to
  return wrapAngle(from + angleDiff(from, to) * alpha)
}

/**
 * Further than any car drives in one tick: 0.25 m is 30 m/s, five times the fastest car. A car whose centre moves
 * more than this between two snapshots was not driven there: it was set down (by the stand-in for the marshals,
 * F-207, and later by a marshal).
 */
export const CARRIED_M = 0.25

/**
 * Blends the previous and current snapshot of every car into `out`, reusing its objects. Cars are matched by
 * position in the arrays; a car that has no earlier snapshot is shown where it is. A discrete state is the later
 * snapshot's, never a blend. A car that was set down somewhere else within the tick is shown where it now is,
 * not on the way there.
 */
export function interpolateCars(prev: readonly CarSnapshot[], curr: readonly CarSnapshot[], alpha: number, out: RenderCar[]): void {
  out.length = curr.length
  for (let i = 0; i < curr.length; i++) {
    const b = curr[i]
    const a = prev[i] ?? b
    const target: RenderCar =
      out[i] ?? (out[i] = { id: b.id, x: 0, y: 0, angle: 0, speedMS: 0, state: b.state, slipFront: 0, slipRear: 0, steerRad: 0 })
    const carried = Math.hypot(b.pose.x - a.pose.x, b.pose.y - a.pose.y) > CARRIED_M
    const t = carried ? 1 : alpha
    target.id = b.id
    target.x = lerp(a.pose.x, b.pose.x, t)
    target.y = lerp(a.pose.y, b.pose.y, t)
    target.angle = lerpAngle(a.pose.angle, b.pose.angle, t)
    target.speedMS = lerp(a.speedMS, b.speedMS, t)
    target.state = b.state
    target.slipFront = lerp(a.slipFront, b.slipFront, t)
    target.slipRear = lerp(a.slipRear, b.slipRear, t)
    target.steerRad = lerp(a.steerRad, b.steerRad, t)
  }
}

/**
 * Which frame of a baked direction set shows a car heading `angle`: the nearest of `directions` headings spaced
 * evenly clockwise from +x (ADR-005). Cars are never rotated at runtime.
 */
export function headingFrame(angle: number, directions: number): number {
  const index = Math.round((angle / TWO_PI) * directions)
  return ((index % directions) + directions) % directions
}
