import type Phaser from 'phaser'
import type { WorldView } from '../config'
import { THEME } from '../ui/theme'
import { DEPTH } from './depth'
import type { RenderCar } from './interpolate'

// The thin ring that follows the player's car (F-304), so that it can always be found among six, stationary or not.

/** The ring's diameter as a multiple of the car's length (art-direction.md, "HUD"). */
export const RING_DIAMETER_PER_LENGTH = 1.6
/** The ring's line, in screen pixels: the white line and the dark ink it sits on, which keeps it visible on pale ground. */
const LINE_PX = 2
const INK_PX = 4
const LINE_COLOUR = THEME.colours.text
const INK_COLOUR = THEME.colours.background
/** The ink under the line is a little see-through, so that the ring does not shout. */
const INK_ALPHA = 0.8

/** The ring's radius on screen, in pixels, for a car `lengthM` long. */
export const ringRadiusPx = (lengthM: number, view: WorldView): number => (RING_DIAMETER_PER_LENGTH * lengthM * view.pxPerM) / 2

/**
 * One ring, drawn once and then only moved. It is under the cars, over the rubber and the puddles, so that no car
 * is ever hidden by it. The ring is a picture painted into a canvas texture once and shown as an image (F-803): a
 * `Graphics` ring is tessellated again by the engine on every frame it is shown, which was the largest per-frame
 * allocation in a race. A canvas texture, unlike one drawn into by the engine, survives a lost graphics context.
 */
export class PlayerMarker {
  static readonly TEXTURE_KEY = 'player-ring'

  private readonly ring: Phaser.GameObjects.Image

  constructor(
    private readonly scene: Phaser.Scene,
    private readonly view: WorldView,
    private readonly carId: number,
    lengthM: number,
  ) {
    const { textures } = scene
    if (textures.exists(PlayerMarker.TEXTURE_KEY)) textures.remove(PlayerMarker.TEXTURE_KEY)
    const radius = ringRadiusPx(lengthM, view)
    // Even, so that the centre is on a pixel corner and the ring sits where a ring drawn at a whole pixel would.
    const side = 2 * Math.ceil(radius + INK_PX / 2) + 2
    const texture = textures.createCanvas(PlayerMarker.TEXTURE_KEY, side, side)
    if (texture === null) throw new Error('PlayerMarker: the ring texture could not be created')
    const ctx = texture.getContext()
    // Painted pixel by pixel, hard-edged like everything else on this screen: a pixel is the line's if its centre is within half the line's width of the circle, the ink's if within half of the ink's.
    const picture = ctx.createImageData(side, side)
    const [lr, lg, lb] = [(LINE_COLOUR >> 16) & 0xff, (LINE_COLOUR >> 8) & 0xff, LINE_COLOUR & 0xff]
    const [ir, ig, ib] = [(INK_COLOUR >> 16) & 0xff, (INK_COLOUR >> 8) & 0xff, INK_COLOUR & 0xff]
    for (let y = 0; y < side; y++) {
      for (let x = 0; x < side; x++) {
        const off = Math.abs(Math.hypot(x + 0.5 - side / 2, y + 0.5 - side / 2) - radius)
        const at = (y * side + x) * 4
        if (off <= LINE_PX / 2) picture.data.set([lr, lg, lb, 255], at)
        else if (off <= INK_PX / 2) picture.data.set([ir, ig, ib, Math.round(INK_ALPHA * 255)], at)
      }
    }
    ctx.putImageData(picture, 0, 0)
    texture.refresh()
    this.ring = scene.add.image(0, 0, PlayerMarker.TEXTURE_KEY).setDepth(DEPTH.cars - 0.5).setVisible(false)
  }

  /** Puts the ring on the player's car at the instant being drawn. */
  update(cars: readonly RenderCar[]): void {
    const car = cars[this.carId]
    this.ring.setVisible(car !== undefined)
    if (car === undefined) return
    this.ring.setPosition(Math.round(this.view.originX + car.x * this.view.pxPerM), Math.round(this.view.originY + car.y * this.view.pxPerM))
  }

  destroy(): void {
    this.ring.destroy()
    if (this.scene.textures.exists(PlayerMarker.TEXTURE_KEY)) this.scene.textures.remove(PlayerMarker.TEXTURE_KEY)
  }
}
