import { buildRacingLine, buildTrackRuntime, createRng, type PitLane, type Point, type Rng, type TrackData } from '@sim'
import {
  CHECKER_ROWS,
  CHECKER_SQUARE_M,
  GLYPH,
  GRAIN_COLOR,
  RUBBER_COLOR,
  TUFT_DENSITY,
  TYRE_COLORS,
  WEAR_FLECK_M,
  type TrackStyle,
} from './track-style'

// The track picture as data. Everything here is pure: world metres in, a list of drawing commands out. Phaser
// is touched only by TrackRenderer, which bakes the list into a texture. The tyres are not in that list: they
// lie loose and move (F-308), so each is a small picture of its own, drawn where the tyre is on every frame.

export type DrawCommand =
  /** A filled polygon; `alpha` below 1 lays the colour over what is under it at that strength (F-802: the rubbered-in line). */
  | { op: 'fill'; layer: number; color: number; polygon: Point[]; holes?: Point[][]; alpha?: number }
  /** Single flecks a whole number of screen pixels across (`sizePx`), on the screen's pixel grid, at these world points (F-802: worn paint). */
  | { op: 'flecks'; layer: number; color: number; points: Point[]; sizePx: number }
  | { op: 'stroke'; layer: number; color: number; widthM: number; polyline: Point[]; closed: boolean; dashM?: [on: number, off: number] }
  | { op: 'disc'; layer: number; color: number; x: number; y: number; r: number }
  | { op: 'checker'; layer: number; a: Point; b: Point; depthM: number; squares: number }
  /** Seeded flecks inside `polygon` and outside `holes`. How many is `strength` times the area. */
  | { op: 'grain'; layer: number; polygon: Point[]; holes?: Point[][]; seed: number; strength: number }
  /** Seeded grass tufts, laid like grain. */
  | { op: 'tufts'; layer: number; polygon: Point[]; holes?: Point[][]; seed: number; strength: number }
  /**
   * A filled block. `border` is a line of `widthM`, centred on the stated edges (edge `i` runs from `polygon[i]` to
   * the next point) and painted straight after the fill, so a block's border is not covered by its own fill.
   */
  | { op: 'block'; layer: number; color: number; polygon: Point[]; border?: { color: number; widthM: number; edges: number[] } }
  /**
   * A short run of glyphs from the pixel font, centred on (x, y) as a box of ink: it reads along `heading` (radians,
   * clockwise from +x as everywhere) and its digits are about `heightM` tall, to a whole number of screen pixels
   * per art pixel (`glyphArtPx`).
   */
  | { op: 'glyphs'; layer: number; color: number; text: string; x: number; y: number; heading: number; heightM: number }
  /**
   * A picture from an atlas stamped into the ground (F-504: what lies flat, such as the driver stand and the pit
   * tables). (x, y) is the centre of its cell in metres; `scale` is screen pixels per art pixel and `wPx` x `hPx` its
   * cell on screen, which the baker uses to put the picture's edge on a whole screen pixel.
   */
  | { op: 'sprite'; layer: number; atlas: string; frame: string; x: number; y: number; scale: number; wPx: number; hPx: number }

/** Where each kind of thing sits within the bake. Surfaces take 0 to 9 in data order. */
export const LAYER = {
  surfaceMax: 9,
  grain: 10,
  /** Surface detail (F-802): cracks on the grain, the rubbered-in line over them, both under the pit blocks and every line. */
  cracks: 10.5,
  rubber: 11,
  /** Pit blocks sit on the asphalt and its grain, under every line. */
  blocks: 12,
  lines: 20,
  /** Wear on the painted marks: flecks of asphalt over the paint (F-802), under the numbers. */
  wear: 22,
  /** Numbers painted on the ground, over the lines that box them in. */
  glyphs: 26,
  /** The finish strip is paint on the asphalt: over the lines, under the kerb it runs up to. */
  chequer: 28,
  kerbs: 30,
  barriers: 32,
  /** Flat props (the driver stand, the pit tables) lie on everything that is painted on the ground, tyre markers excepted. */
  props: 34,
  markers: 40,
} as const

type SurfaceData = TrackData['surfaces'][number]
type Quad = [Point, Point, Point, Point]

// ---------------------------------------------------------------------------------------------------------
// Polylines by arc length

interface Path {
  pts: Point[]
  cum: number[]
  total: number
}

function makePath(polyline: readonly Point[], closed: boolean): Path {
  const pts = closed && polyline.length > 0 ? [...polyline, polyline[0]] : [...polyline]
  const cum = [0]
  for (let i = 1; i < pts.length; i++) cum.push(cum[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]))
  return { pts, cum, total: cum[cum.length - 1] ?? 0 }
}

/** Index of the first vertex whose arc length exceeds `s`. */
function upperIndex(path: Path, s: number): number {
  let lo = 0
  let hi = path.cum.length
  while (lo < hi) {
    const mid = (lo + hi) >> 1
    if (path.cum[mid] > s) hi = mid
    else lo = mid + 1
  }
  return lo
}

function sampleAt(path: Path, s: number): Point {
  const last = path.pts.length - 1
  const hi = Math.min(Math.max(upperIndex(path, s), 1), last)
  const lo = hi - 1
  const len = path.cum[hi] - path.cum[lo]
  const t = len > 0 ? Math.min(Math.max((s - path.cum[lo]) / len, 0), 1) : 0
  return [path.pts[lo][0] + (path.pts[hi][0] - path.pts[lo][0]) * t, path.pts[lo][1] + (path.pts[hi][1] - path.pts[lo][1]) * t]
}

/** Direction of travel at arc length `s`, from a short chord either side so that a corner does not tilt a stripe edge. */
function tangentAt(path: Path, s: number, delta: number, closed: boolean): Point {
  let s0 = s - delta
  let s1 = s + delta
  if (closed) {
    if (s0 < 0) s0 += path.total
    if (s1 > path.total) s1 -= path.total
  } else {
    // Near an end the chord shrinks to stay centred on the point, so that an end's direction is the line's own.
    const reach = Math.max(Math.min(delta, s, path.total - s), 1e-3)
    s0 = Math.max(0, s - reach)
    s1 = Math.min(path.total, s + reach)
  }
  const a = sampleAt(path, s0)
  const b = sampleAt(path, s1)
  const len = Math.hypot(b[0] - a[0], b[1] - a[1])
  return len > 1e-12 ? [(b[0] - a[0]) / len, (b[1] - a[1]) / len] : [1, 0]
}

// ---------------------------------------------------------------------------------------------------------
// Kerbs

export interface KerbStripe {
  /** The stripe's four corners: start left, end left, end right, start right. */
  quad: Quad
  /** The stripe's outline: the same corners, with a point every `KERB_RAIL_STEP_M` along its inner and outer edge, so that a curve is round. */
  polygon: Point[]
  red: boolean
}

/** Points along the centreline of a kerb at most this far apart carry its edges: a hairpin's edges are then smooth arcs. */
export const KERB_RAIL_STEP_M = 0.015
/** The half-length of the chord that gives the direction of a kerb at a point (the same for every point, so neighbouring stripes meet exactly). */
const KERB_TANGENT_M = 0.02

/**
 * Alternating red and white stripes along a kerb, centred on its polyline. The polyline's length is divided
 * into a whole number of equal stripes as near `stripeM` as it allows (an even number round a closed kerb, so
 * the colours alternate across the seam). A stripe is a wedge: its ends are straight across the kerb, and its
 * two long edges follow the curve. Neighbouring stripes share their end edge exactly, so they meet without a gap.
 */
export function kerbStripes(polyline: readonly Point[], widthM: number, stripeM: number, closed: boolean): KerbStripe[] {
  if (polyline.length < 2 || !(stripeM > 0)) return []
  const path = makePath(polyline, closed)
  if (!(path.total > 0)) return []

  const wanted = path.total / stripeM
  const count = closed ? Math.max(2, 2 * Math.round(wanted / 2)) : Math.max(1, Math.round(wanted))
  const step = path.total / count
  const half = widthM / 2
  const edges = (s: number): { left: Point; right: Point } => {
    const p = sampleAt(path, s)
    const [tx, ty] = tangentAt(path, s, KERB_TANGENT_M, closed)
    return { left: [p[0] - ty * half, p[1] + tx * half], right: [p[0] + ty * half, p[1] - tx * half] }
  }

  const boundaries: Array<{ left: Point; right: Point }> = []
  for (let k = 0; k <= count; k++) {
    if (closed && k === count) {
      boundaries.push(boundaries[0])
      break
    }
    boundaries.push(edges(k * step))
  }

  const pieces = Math.max(1, Math.ceil(step / KERB_RAIL_STEP_M))
  const stripes: KerbStripe[] = []
  for (let k = 0; k < count; k++) {
    const a = boundaries[k]
    const b = boundaries[k + 1]
    const left: Point[] = [a.left]
    const right: Point[] = [a.right]
    for (let i = 1; i < pieces; i++) {
      const { left: l, right: r } = edges(k * step + (step * i) / pieces)
      left.push(l)
      right.push(r)
    }
    left.push(b.left)
    right.push(b.right)
    stripes.push({ quad: [a.left, b.left, b.right, a.right], polygon: [...left, ...right.reverse()], red: k % 2 === 0 })
  }
  return stripes
}

// ---------------------------------------------------------------------------------------------------------
// Dashes and strokes

/** The "on" stretches of a dashed polyline, as separate polylines. Dashes start with an "on" at the first point. */
export function dashSegments(polyline: readonly Point[], on: number, off: number, closed: boolean): Point[][] {
  const path = makePath(polyline, closed)
  if (path.pts.length < 2) return []
  if (!(on > 0) || !(off > 0)) return [path.pts]
  const out: Point[][] = []
  let s = 0
  let drawing = true
  while (s < path.total) {
    const end = Math.min(path.total, s + (drawing ? on : off))
    if (drawing) {
      const piece: Point[] = [sampleAt(path, s)]
      for (let i = upperIndex(path, s); i < path.pts.length && path.cum[i] < end; i++) piece.push(path.pts[i])
      piece.push(sampleAt(path, end))
      out.push(piece)
    }
    s = end
    drawing = !drawing
  }
  return out
}

const JOIN_STEP = Math.PI / 16

/**
 * Triangles (flat x0 y0 x1 y1 x2 y2 ...) that cover a polyline stroked `width` wide: a quad per segment and a
 * round join, a fan of triangles on the outside of the turn, at every shared vertex. Ends are butt. No corner
 * shows however sharp the turn, which is why this is not left to the engine's own strokes.
 */
export function strokeTriangles(points: readonly Point[], width: number, closed: boolean): number[] {
  const h = width / 2
  const p: Point[] = []
  for (const q of points) {
    const last = p[p.length - 1]
    if (last === undefined || last[0] !== q[0] || last[1] !== q[1]) p.push(q)
  }
  if (closed && p.length > 1 && p[0][0] === p[p.length - 1][0] && p[0][1] === p[p.length - 1][1]) p.pop()
  const n = p.length
  if (n < 2 || !(h > 0)) return []

  const segments = closed ? n : n - 1
  const dx: number[] = []
  const dy: number[] = []
  for (let i = 0; i < segments; i++) {
    const a = p[i]
    const b = p[(i + 1) % n]
    const len = Math.hypot(b[0] - a[0], b[1] - a[1])
    dx.push((b[0] - a[0]) / len)
    dy.push((b[1] - a[1]) / len)
  }

  const out: number[] = []
  for (let i = 0; i < segments; i++) {
    const a = p[i]
    const b = p[(i + 1) % n]
    const ox = -dy[i] * h
    const oy = dx[i] * h
    out.push(a[0] + ox, a[1] + oy, b[0] + ox, b[1] + oy, b[0] - ox, b[1] - oy)
    out.push(a[0] + ox, a[1] + oy, b[0] - ox, b[1] - oy, a[0] - ox, a[1] - oy)
  }

  for (let v = closed ? 0 : 1; v < (closed ? n : n - 1); v++) {
    const i0 = (v - 1 + n) % n
    const i1 = v % n
    const cross = dx[i0] * dy[i1] - dy[i0] * dx[i1]
    const turn = Math.atan2(cross, dx[i0] * dx[i1] + dy[i0] * dy[i1])
    if (Math.abs(turn) < 1e-3) continue
    const side = cross > 0 ? -1 : 1
    const start = Math.atan2(side * dx[i0], side * -dy[i0])
    const steps = Math.ceil(Math.abs(turn) / JOIN_STEP)
    const [cx, cy] = p[v]
    for (let k = 0; k < steps; k++) {
      const a0 = start + (turn * k) / steps
      const a1 = start + (turn * (k + 1)) / steps
      out.push(cx, cy, cx + h * Math.cos(a0), cy + h * Math.sin(a0), cx + h * Math.cos(a1), cy + h * Math.sin(a1))
    }
  }
  return out
}

// ---------------------------------------------------------------------------------------------------------
// Numbers painted on the ground

type GlyphsCommand = Extract<DrawCommand, { op: 'glyphs' }>
type GlyphBox = Pick<GlyphsCommand, 'text' | 'x' | 'y' | 'heading' | 'heightM'>

/**
 * Whole screen pixels per art pixel of the pixel font for digits about `heightM` tall at `pxPerM`, never fewer
 * than one. Whole, so that a number drawn on the pixel grid has the same hard pixels as the font itself.
 */
export function glyphArtPx(heightM: number, pxPerM: number): number {
  return Math.max(1, Math.round((heightM * pxPerM) / GLYPH.capRows))
}

/** How many art pixels across a run of digits is: its first glyph's ink, and a cell for each one after. */
export function glyphCols(text: string): number {
  return text.length > 0 ? GLYPH.advance * (text.length - 1) + GLYPH.inkCols : 0
}

/** The box that a run's ink fills, in world metres at `pxPerM`: top left, top right, bottom right, bottom left of the text. */
export function glyphInk(glyphs: GlyphBox, pxPerM: number): [Point, Point, Point, Point] {
  const art = glyphArtPx(glyphs.heightM, pxPerM) / pxPerM
  const halfW = (glyphCols(glyphs.text) * art) / 2
  const halfH = (GLYPH.capRows * art) / 2
  const c = Math.cos(glyphs.heading)
  const s = Math.sin(glyphs.heading)
  const at = (u: number, v: number): Point => [glyphs.x + c * u - s * v, glyphs.y + s * u + c * v]
  return [at(-halfW, -halfH), at(halfW, -halfH), at(halfW, halfH), at(-halfW, halfH)]
}

const lerp = (a: Point, b: Point, t: number): Point => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t]

/** The middle of what a start box leaves free: between its two sides, and between the line across it and the mouth. */
function startBoxCentre(polygon: readonly Point[], lineM: number): Point {
  const [a, b, c, d] = polygon
  const base = lerp(b, c, 0.5)
  const mouth = lerp(a, d, 0.5)
  const depth = Math.hypot(mouth[0] - base[0], mouth[1] - base[1])
  const t = (lineM / 2 + depth) / 2 / depth
  return lerp(lerp(b, a, t), lerp(c, d, t), 0.5)
}

/**
 * The number of each start box, painted inside it. A box is a line drawn on the lane: two sides and a base, open
 * towards the lane's edge, four points of a `mark` line. Slot `i` of the stagger start gets number `i + 1` in
 * the box it stands in, so box 1 is the first released whichever way the track is raced.
 */
export function startBoxNumbers(track: TrackData, style: TrackStyle): DrawCommand[] {
  const boxes = track.lines.filter((l) => l.kind === 'mark' && !l.closed && l.polyline.length === 4)
  const pairs: Array<{ slot: number; box: number; distance: number }> = []
  track.staggerStart.forEach((slot, i) => {
    boxes.forEach((box, j) => {
      const [bx, by] = lerp(box.polyline[1], box.polyline[2], 0.5)
      pairs.push({ slot: i, box: j, distance: Math.hypot(slot.x - bx, slot.y - by) })
    })
  })
  pairs.sort((p, q) => p.distance - q.distance)

  const boxOf = new Map<number, number>()
  const taken = new Set<number>()
  for (const { slot, box } of pairs) {
    if (boxOf.has(slot) || taken.has(box)) continue
    boxOf.set(slot, box)
    taken.add(box)
  }

  const out: DrawCommand[] = []
  for (const [slot, box] of [...boxOf].sort((p, q) => p[0] - q[0])) {
    const line = boxes[box]
    const [x, y] = startBoxCentre(line.polyline, line.widthM)
    out.push({ op: 'glyphs', layer: LAYER.glyphs, color: style.startNumber, text: String(slot + 1), x, y, heading: 0, heightM: style.startNumberHeightM })
  }
  return out
}

// ---------------------------------------------------------------------------------------------------------
// Pit blocks

/** Within this of a quarter turn, an angle taken from a measured pose is that quarter turn exactly. */
const QUARTER_SNAP_RAD = 0.01

function snapToQuarterTurns(angle: number): number {
  const quarter = Math.PI / 2
  const nearest = Math.round(angle / quarter) * quarter + 0
  return Math.abs(angle - nearest) < QUARTER_SNAP_RAD ? nearest : angle
}

/**
 * The pit blocks: a white block each, a red line down each boundary between them and at the two ends, and each
 * block's number in the middle of it, upright for a car parked in it (its top is the car's nose). A block owns the
 * divider on its low side, the last also the one on its high side, and blocks are painted from low to high, so
 * no block's fill is laid over the half of a divider that falls on it.
 */
export function pitBlockPaint(pit: PitLane, style: TrackStyle): DrawCommand[] {
  const lateral = (p: Point, angle: number): number => p[0] * Math.cos(angle + Math.PI / 2) + p[1] * Math.sin(angle + Math.PI / 2)
  const centre = (polygon: readonly Point[]): Point => [
    polygon.reduce((n, p) => n + p[0], 0) / polygon.length,
    polygon.reduce((n, p) => n + p[1], 0) / polygon.length,
  ]
  const ordered = [...pit.blocks].sort((p, q) => lateral(centre(p.polygon), p.pose.angle) - lateral(centre(q.polygon), q.pose.angle))

  const out: DrawCommand[] = []
  const numbers: DrawCommand[] = []
  ordered.forEach((block, index) => {
    const { polygon, pose } = block
    const fx = Math.cos(pose.angle)
    const fy = Math.sin(pose.angle)
    // The two edges that run along the car: the lowest and highest of them are the dividers.
    const along = polygon
      .map((p, i) => {
        const q = polygon[(i + 1) % polygon.length]
        const length = Math.hypot(q[0] - p[0], q[1] - p[1])
        return { i, skew: Math.abs((q[0] - p[0]) * fy - (q[1] - p[1]) * fx) / length, at: lateral(lerp(p, q, 0.5), pose.angle) }
      })
      .sort((p, q) => p.skew - q.skew)
      .slice(0, 2)
      .sort((p, q) => p.at - q.at)
    const edges = index === ordered.length - 1 ? along.map((e) => e.i) : [along[0].i]
    out.push({ op: 'block', layer: LAYER.blocks, color: style.pitBlock, polygon, border: { color: style.pitDivider, widthM: style.pitDividerWidthM, edges } })

    const [x, y] = centre(polygon)
    numbers.push({
      op: 'glyphs',
      layer: LAYER.glyphs,
      color: style.pitNumber,
      text: String(block.number),
      x,
      y,
      heading: snapToQuarterTurns(pose.angle + Math.PI / 2),
      heightM: style.pitNumberHeightM,
    })
  })
  return [...out, ...numbers]
}

// ---------------------------------------------------------------------------------------------------------
// Tyres

/** A tyre that lies loose on the track: where the track has it, and which of the track's markers it is. */
export interface LooseTyre {
  /** Its place in `TrackData.markers`, which is its place in the snapshot's `markers`. */
  index: number
  /** Where it lies when nothing has moved it, and its outer radius. World metres. */
  x: number
  y: number
  r: number
}

/** The tyres of a track, in marker order: its markers of kind `dot`. Every other marker stands where it is, in the bake. */
export function looseTyres(track: TrackData): LooseTyre[] {
  return track.markers.flatMap((marker, index) => (marker.kind === 'dot' ? [{ index, x: marker.x, y: marker.y, r: marker.r }] : []))
}

/**
 * The side, in screen pixels, of the square picture of a tyre of outer radius `r`: the tyre itself and a pixel
 * clear all round, so that a tyre drawn part of the way between two pixels is not cut off at the picture's edge.
 */
export function tyrePicturePx(r: number, pxPerM: number): number {
  return 2 * (Math.ceil(r * pxPerM) + 1)
}

/** The texture that holds the picture of a tyre of outer radius `r`: one for all the tyres of a size. */
export function tyreTextureKey(r: number): string {
  return `marker-tyre-${Math.round(r * 1000)}mm`
}

/** The hole through a tyre, as a share of its outer radius. */
export const TYRE_HOLE = 0.38

export interface TyrePart {
  color: number
  /** Radii from the tyre's centre, in metres. */
  inner: number
  outer: number
  /** The sector, in radians clockwise from +x on screen, running from `from` up to `to` (`to` is above `from`). */
  from: number
  to: number
}

const TOP_LEFT = (5 * Math.PI) / 4
const BOTTOM_RIGHT = Math.PI / 4
const degrees = (d: number): number => (d * Math.PI) / 180

/**
 * A tyre of outer radius `r` as ring sectors, painted in the order given (a later one covers an earlier one),
 * lit from the top left like everything else in the game: dark rubber with a sidewall ring on it; round the
 * outside a tread edge, light on the lit side and ink on the shadow side; round the hole an inner wall that is
 * lit on the far side from the light and in shade on the near one. Nothing is painted inside the hole. The
 * outside radius is `r` exactly, because the marker's radius is what the physics sees.
 */
export function tyreParts(r: number): TyrePart[] {
  const hole = r * TYRE_HOLE
  const full = (color: number, inner: number, outer: number): TyrePart => ({ color, inner: inner * r, outer: outer * r, from: 0, to: 2 * Math.PI })
  const arc = (color: number, inner: number, outer: number, centre: number, half: number): TyrePart => ({
    color,
    inner: inner * r,
    outer: outer * r,
    from: centre - half,
    to: centre + half,
  })
  return [
    { ...full(TYRE_COLORS.rubber, TYRE_HOLE, 1), inner: hole },
    full(TYRE_COLORS.sidewall, 0.56, 0.7),
    arc(TYRE_COLORS.ink, 0.82, 1, BOTTOM_RIGHT, degrees(95)),
    arc(TYRE_COLORS.sidewall, 0.82, 1, TOP_LEFT, degrees(100)),
    arc(TYRE_COLORS.highlight, 0.86, 1, TOP_LEFT, degrees(60)),
    { ...arc(TYRE_COLORS.ink, TYRE_HOLE, TYRE_HOLE + 0.12, TOP_LEFT, degrees(90)), inner: hole },
    { ...arc(TYRE_COLORS.highlight, TYRE_HOLE, TYRE_HOLE + 0.1, BOTTOM_RIGHT, degrees(70)), inner: hole },
  ]
}

const SECTOR_STEP = Math.PI / 36

/** Triangles (flat x0 y0 x1 y1 x2 y2 ...) that cover the ring sector between two radii and two angles round (cx, cy). */
export function ringSectorTriangles(cx: number, cy: number, inner: number, outer: number, from: number, to: number): number[] {
  const steps = Math.max(1, Math.ceil((to - from) / SECTOR_STEP))
  const out: number[] = []
  for (let i = 0; i < steps; i++) {
    const a0 = from + ((to - from) * i) / steps
    const a1 = from + ((to - from) * (i + 1)) / steps
    const [c0, s0, c1, s1] = [Math.cos(a0), Math.sin(a0), Math.cos(a1), Math.sin(a1)]
    out.push(cx + inner * c0, cy + inner * s0, cx + outer * c0, cy + outer * s0, cx + outer * c1, cy + outer * s1)
    out.push(cx + inner * c0, cy + inner * s0, cx + outer * c1, cy + outer * s1, cx + inner * c1, cy + inner * s1)
  }
  return out
}

// ---------------------------------------------------------------------------------------------------------
// Chequered strip

export interface CheckerQuad {
  quad: Quad
  dark: boolean
}

/** The squares of a chequered strip along a to b, `depthM` deep and centred on that line. */
export function checkerQuads(cmd: { a: Point; b: Point; depthM: number; squares: number }): CheckerQuad[] {
  const [ax, ay] = cmd.a
  const len = Math.hypot(cmd.b[0] - ax, cmd.b[1] - ay)
  if (!(len > 0) || cmd.squares < 1) return []
  const ux = (cmd.b[0] - ax) / len
  const uy = (cmd.b[1] - ay) / len
  const nx = -uy
  const ny = ux
  const side = len / cmd.squares
  const rows = Math.max(1, Math.round(cmd.depthM / side))
  const rowDepth = cmd.depthM / rows

  const at = (along: number, across: number): Point => [ax + ux * along + nx * across, ay + uy * along + ny * across]
  const out: CheckerQuad[] = []
  for (let r = 0; r < rows; r++) {
    const c0 = -cmd.depthM / 2 + r * rowDepth
    const c1 = c0 + rowDepth
    for (let i = 0; i < cmd.squares; i++) {
      out.push({ quad: [at(i * side, c0), at((i + 1) * side, c0), at((i + 1) * side, c1), at(i * side, c1)], dark: (i + r) % 2 === 1 })
    }
  }
  return out
}

// ---------------------------------------------------------------------------------------------------------
// Grain and tufts

/**
 * Point-in-ring tests for one ring, made fast for many points: the ring's edges are sorted into horizontal bands
 * once, so a test looks only at the edges that cross its own band instead of at all of them.
 */
function ringTester(ring: readonly Point[]): (x: number, y: number) => boolean {
  let minY = Infinity
  let maxY = -Infinity
  let minX = Infinity
  let maxX = -Infinity
  for (const [x, y] of ring) {
    minX = Math.min(minX, x)
    maxX = Math.max(maxX, x)
    minY = Math.min(minY, y)
    maxY = Math.max(maxY, y)
  }
  const bands = Math.max(1, Math.min(128, ring.length >> 2))
  const height = (maxY - minY) / bands || 1
  const edges: number[][] = Array.from({ length: bands }, () => [])
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const lo = Math.min(ring[i][1], ring[j][1])
    const hi = Math.max(ring[i][1], ring[j][1])
    const first = Math.min(bands - 1, Math.floor((lo - minY) / height))
    const last = Math.min(bands - 1, Math.floor((hi - minY) / height))
    for (let band = first; band <= last; band++) edges[band].push(i, j)
  }
  return (x, y) => {
    if (y < minY || y > maxY || x < minX || x > maxX) return false
    const list = edges[Math.min(bands - 1, Math.floor((y - minY) / height))]
    let inside = false
    for (let k = 0; k < list.length; k += 2) {
      const [xi, yi] = ring[list[k]]
      const [xj, yj] = ring[list[k + 1]]
      if (yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) inside = !inside
    }
    return inside
  }
}

/** Candidate points used to measure how much of a polygon is really left to cover. */
const AREA_PROBES = 8192

/**
 * Where the flecks (or tufts) of a grain command go, in world metres. A pure function of the command: the same
 * seed always gives the same points, all of them inside the polygon and outside its holes. `footprintPx` is the
 * side of one fleck on screen: the count is `strength` of the area, in pixels, divided by that footprint. The
 * area is what is left of the polygon after its holes, measured by probing (holes may overlap or nest, so their
 * areas cannot simply be subtracted); the probing is seeded too, so the count is as repeatable as the points.
 */
export function scatterPoints(
  cmd: { polygon: readonly Point[]; holes?: readonly (readonly Point[])[]; seed: number; strength: number },
  pxPerM: number,
  footprintPx: number,
): Array<[x: number, y: number]> {
  if (cmd.polygon.length < 3 || !(cmd.strength > 0)) return []
  const holes = cmd.holes ?? []

  let minX = Infinity
  let minY = Infinity
  let maxX = -Infinity
  let maxY = -Infinity
  for (const [x, y] of cmd.polygon) {
    minX = Math.min(minX, x)
    minY = Math.min(minY, y)
    maxX = Math.max(maxX, x)
    maxY = Math.max(maxY, y)
  }

  const inside = ringTester(cmd.polygon)
  const inHole = holes.map(ringTester)
  const rng = createRng(cmd.seed)
  const candidate = (r: Rng): [number, number] | null => {
    const x = r.range(minX, maxX)
    const y = r.range(minY, maxY)
    return inside(x, y) && !inHole.some((test) => test(x, y)) ? [x, y] : null
  }

  const probe = rng.fork('area')
  let hits = 0
  for (let i = 0; i < AREA_PROBES; i++) if (candidate(probe) !== null) hits++
  const areaM2 = ((maxX - minX) * (maxY - minY) * hits) / AREA_PROBES
  const count = Math.min(200_000, Math.round((areaM2 * pxPerM * pxPerM * cmd.strength) / (footprintPx * footprintPx)))

  const place = rng.fork('points')
  const out: Array<[number, number]> = []
  for (let attempts = 0; out.length < count && attempts < count * 60; attempts++) {
    const point = candidate(place)
    if (point !== null) out.push(point)
  }
  return out
}

// ---------------------------------------------------------------------------------------------------------
// Surface detail (F-802)

function segmentDistance(x: number, y: number, a: Point, b: Point): number {
  const dx = b[0] - a[0]
  const dy = b[1] - a[1]
  const lengthSq = dx * dx + dy * dy
  const t = lengthSq === 0 ? 0 : Math.min(1, Math.max(0, ((x - a[0]) * dx + (y - a[1]) * dy) / lengthSq))
  return Math.hypot(x - (a[0] + dx * t), y - (a[1] + dy * t))
}

function polylineDistance(x: number, y: number, polyline: readonly Point[], closed: boolean): number {
  let best = Infinity
  const last = closed ? polyline.length : polyline.length - 1
  for (let i = 0; i < last; i++) best = Math.min(best, segmentDistance(x, y, polyline[i], polyline[(i + 1) % polyline.length]))
  return best
}

/**
 * Whether a mark that reaches `reachM` from the point (x, y) stays clear of everything whose contrast against the asphalt
 * must not change: by `detailClearM` from every painted line (lane edges, the pit lane's lines, the dashed line and the
 * start boxes, inside which nothing is laid, so that their numbers stand on plain asphalt), every kerb and every
 * barrier, and by `puddleClearM` from every puddle spot's edge.
 */
function clearOfBorders(track: TrackData, style: TrackStyle): (x: number, y: number, reachM: number) => boolean {
  const borders = [
    ...track.lines.map((l) => ({ polyline: l.polyline, closed: l.closed, halfM: (l.widthM > 0 ? l.widthM : style.edgeLineWidthM) / 2 })),
    ...track.kerbs.map((k) => ({ polyline: k.polyline, closed: k.closed, halfM: k.widthM / 2 })),
    ...track.walls.filter((w) => w.kind === 'barrier').map((w) => ({ polyline: w.polyline, closed: w.closed, halfM: style.barrierWidthM / 2 })),
  ]
  // The start boxes, closed across their mouths: their numbers stand on plain asphalt inside them.
  const boxes = track.lines.filter((l) => l.kind === 'mark' && !l.closed && l.polyline.length === 4)
  const inBox = boxes.map((l) => ringTester(l.polyline))
  return (x, y, reachM) =>
    track.puddleSpots.every((spot) => Math.hypot(x - spot.x, y - spot.y) - reachM >= spot.r + style.puddleClearM) &&
    borders.every((b) => polylineDistance(x, y, b.polyline, b.closed) - b.halfM - reachM >= style.detailClearM) &&
    boxes.every((box, i) => !inBox[i]?.(x, y) && polylineDistance(x, y, box.polyline, true) - reachM >= style.detailClearM)
}

/** Whether a world point is on asphalt: the last surface that contains it, in data order, is asphalt. */
function onAsphalt(track: TrackData): (x: number, y: number) => boolean {
  const tests = track.surfaces.map((surface) => {
    const outer = ringTester(surface.polygon)
    const holes = surface.holes.map(ringTester)
    return { asphalt: surface.kind === 'asphalt', inside: (x: number, y: number): boolean => outer(x, y) && !holes.some((hole) => hole(x, y)) }
  })
  return (x, y) => {
    let asphalt = false
    for (const test of tests) if (test.inside(x, y)) asphalt = test.asphalt
    return asphalt
  }
}

/**
 * The rubbered-in racing line: the line a car of the style's width drives, as two bands of faint ink (the full width and
 * half of it), broken wherever a band would come within the clearance of a border or a puddle. Each unbroken stretch is
 * one polygon, so no part of a band is laid twice.
 */
function rubberBands(track: TrackData, style: TrackStyle, clear: ReturnType<typeof clearOfBorders>): DrawCommand[] {
  if (!(style.rubberStrength > 0) || !(style.rubberWidthM > 0)) return []
  const line = buildRacingLine(buildTrackRuntime(track), style.rubberCarWidthM)
  const pts: Point[] = line.points.map((p) => [p.x, p.y])
  const n = pts.length
  if (n < 3) return []
  const normals: Point[] = pts.map((_, i) => {
    const a = pts[(i - 1 + n) % n]
    const b = pts[(i + 1) % n]
    const length = Math.hypot(b[0] - a[0], b[1] - a[1]) || 1
    return [-(b[1] - a[1]) / length, (b[0] - a[0]) / length]
  })
  const out: DrawCommand[] = []
  for (const widthM of [style.rubberWidthM, style.rubberWidthM / 2]) {
    const half = widthM / 2
    const ok = pts.map(([x, y]) => clear(x, y, half))
    // Unbroken stretches, starting after a gap so that a stretch never straddles the loop's seam.
    const start = ok.indexOf(false)
    const runs: number[][] = []
    let run: number[] = []
    for (let k = 0; k < n; k++) {
      const i = start < 0 ? k : (start + 1 + k) % n
      if (ok[i]) run.push(i)
      else if (run.length > 0) {
        runs.push(run)
        run = []
      }
    }
    if (run.length > 0) runs.push(run)
    for (const stretch of runs) {
      if (stretch.length < 3) continue
      const left = stretch.map((i): Point => [pts[i][0] + normals[i][0] * half, pts[i][1] + normals[i][1] * half])
      const right = stretch.map((i): Point => [pts[i][0] - normals[i][0] * half, pts[i][1] - normals[i][1] * half])
      if (start < 0) out.push({ op: 'fill', layer: LAYER.rubber, color: RUBBER_COLOR, polygon: left, holes: [right.reverse()], alpha: style.rubberStrength })
      else out.push({ op: 'fill', layer: LAYER.rubber, color: RUBBER_COLOR, polygon: [...left, ...right.reverse()], alpha: style.rubberStrength })
    }
  }
  return out
}

/** Cracks: short jagged runs in the grain colour, seeded, on asphalt and clear of every border. */
function cracks(track: TrackData, style: TrackStyle, clear: ReturnType<typeof clearOfBorders>): DrawCommand[] {
  if (!(style.crackStrength > 0)) return []
  const asphalt = track.surfaces.filter((s) => s.kind === 'asphalt')
  const area = asphalt.reduce((sum, s) => sum + Math.abs(ringArea(s.polygon)) - s.holes.reduce((h, hole) => h + Math.abs(ringArea(hole)), 0), 0)
  const count = Math.round(area * style.crackStrength)
  const xs = asphalt.flatMap((s) => s.polygon.map((p) => p[0]))
  const ys = asphalt.flatMap((s) => s.polygon.map((p) => p[1]))
  const box = { x0: Math.min(...xs), x1: Math.max(...xs), y0: Math.min(...ys), y1: Math.max(...ys) }
  const on = onAsphalt(track)
  const rng = createRng(style.crackSeed)
  const reach = style.crackWidthM / 2
  const fits = (a: Point, b: Point): boolean => {
    const steps = Math.max(1, Math.ceil(Math.hypot(b[0] - a[0], b[1] - a[1]) / 0.01))
    for (let k = 0; k <= steps; k++) {
      const x = a[0] + ((b[0] - a[0]) * k) / steps
      const y = a[1] + ((b[1] - a[1]) * k) / steps
      if (!on(x, y) || !clear(x, y, reach)) return false
    }
    return true
  }
  const out: DrawCommand[] = []
  for (let attempt = 0; out.length < count && attempt < count * 40; attempt++) {
    let at: Point = [rng.range(box.x0, box.x1), rng.range(box.y0, box.y1)]
    let heading = rng.range(0, Math.PI * 2)
    const segments = rng.int(3, 6)
    const polyline: Point[] = [at]
    let whole = true
    for (let k = 0; k < segments; k++) {
      heading += rng.range(-0.7, 0.7)
      const length = rng.range(0.03, 0.07)
      const next: Point = [at[0] + Math.cos(heading) * length, at[1] + Math.sin(heading) * length]
      if (!fits(at, next)) {
        whole = false
        break
      }
      polyline.push(next)
      at = next
    }
    if (whole) out.push({ op: 'stroke', layer: LAYER.cracks, color: GRAIN_COLOR, widthM: style.crackWidthM, polyline, closed: false })
  }
  return out
}

function ringArea(ring: readonly Point[]): number {
  let sum = 0
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) sum += ring[j][0] * ring[i][1] - ring[i][0] * ring[j][1]
  return sum / 2
}

/** Worn paint: flecks of asphalt on the start boxes and the dashed line (their drawn dashes only), never on a lane edge. */
function wornPaint(track: TrackData, style: TrackStyle): DrawCommand[] {
  if (!(style.lineWearStrength > 0)) return []
  const edges = track.lines.filter((l) => l.kind === 'edge' || l.kind === 'solid')
  const awayFromEdges = (p: Point): boolean => edges.every((l) => polylineDistance(p[0], p[1], l.polyline, l.closed) > (l.widthM > 0 ? l.widthM : style.edgeLineWidthM) / 2 + 0.01)
  const rng = createRng(style.lineWearSeed)
  const points: Point[] = []
  for (const line of track.lines) {
    if (line.kind !== 'mark' && line.kind !== 'dashed') continue
    const widthM = line.widthM > 0 ? line.widthM : style.edgeLineWidthM
    const pieces = line.kind === 'dashed' && line.dashM !== undefined ? dashSegments(line.polyline, line.dashM[0], line.dashM[1], line.closed) : [line.polyline]
    for (const piece of pieces) {
      const path = makePath(piece, false)
      const count = Math.round(((path.total * widthM) / (WEAR_FLECK_M * WEAR_FLECK_M)) * style.lineWearStrength)
      for (let k = 0; k < count; k++) {
        const s = rng.range(0, path.total)
        const across = rng.range(-0.4, 0.4) * widthM
        const p = sampleAt(path, s)
        const [tx, ty] = tangentAt(path, s, 0.01, false)
        const point: Point = [p[0] - ty * across, p[1] + tx * across]
        if (awayFromEdges(point)) points.push(point)
      }
    }
  }
  return points.length > 0 ? [{ op: 'flecks', layer: LAYER.wear, color: style.asphalt, points, sizePx: 1 }] : []
}

/**
 * The surface detail of a track (F-802): the rubbered-in racing line, cracks and worn paint, as drawing commands. All of
 * it seeded, all of it faint, none of it within the style's clearance of a lane edge, kerb, barrier or puddle.
 */
export function surfaceDetail(track: TrackData, style: TrackStyle): DrawCommand[] {
  const clear = clearOfBorders(track, style)
  return [...cracks(track, style, clear), ...rubberBands(track, style, clear), ...wornPaint(track, style)]
}

// ---------------------------------------------------------------------------------------------------------
// The list

/** Commands in drawing order: ascending layer, and in the order given within a layer. */
export function orderCommands(...lists: readonly (readonly DrawCommand[])[]): DrawCommand[] {
  return lists.flat().sort((a, b) => a.layer - b.layer)
}

function surfaceColor(surface: SurfaceData, style: TrackStyle): number {
  if (surface.kind === 'asphalt') return style.asphalt
  return surface.look === 'outfield' ? style.outfieldGrass : style.infieldGrass
}

/** What is left to see of surface `index`: its own holes, and everything laid over it later. */
function visibleHoles(surfaces: TrackData['surfaces'], index: number): Point[][] {
  return [...surfaces[index].holes, ...surfaces.slice(index + 1).map((s) => s.polygon)]
}

const withHoles = (holes: Point[][]): { holes?: Point[][] } => (holes.length > 0 ? { holes } : {})

/** Everything the data says is drawn into the ground, in world metres and in drawing order. */
export function trackDrawList(track: TrackData, style: TrackStyle): DrawCommand[] {
  const out: DrawCommand[] = []

  track.surfaces.forEach((surface, i) => {
    const layer = Math.min(i, LAYER.surfaceMax)
    out.push({ op: 'fill', layer, color: surfaceColor(surface, style), polygon: surface.polygon, ...withHoles(surface.holes) })
    if (surface.kind === 'asphalt' && style.grainStrength > 0) {
      out.push({
        op: 'grain',
        layer: LAYER.grain,
        polygon: surface.polygon,
        ...withHoles(visibleHoles(track.surfaces, i)),
        seed: style.grainSeed + i,
        strength: style.grainStrength,
      })
    }
    if (surface.kind === 'grass' && surface.look === 'outfield' && style.grainStrength > 0) {
      out.push({
        op: 'tufts',
        layer: layer + 0.5,
        polygon: surface.polygon,
        ...withHoles(visibleHoles(track.surfaces, i)),
        seed: style.grainSeed + 1000 + i,
        strength: style.grainStrength * TUFT_DENSITY,
      })
    }
  })

  out.push(...surfaceDetail(track, style))

  if (track.pitLane !== undefined) out.push(...pitBlockPaint(track.pitLane, style))

  for (const line of track.lines) {
    const widthM = line.widthM > 0 ? line.widthM : style.edgeLineWidthM
    const base = { op: 'stroke', layer: LAYER.lines, color: style.edgeLine, widthM, polyline: line.polyline, closed: line.closed } as const
    out.push(line.kind === 'dashed' && line.dashM !== undefined ? { ...base, dashM: line.dashM } : base)
  }

  for (const kerb of track.kerbs) {
    for (const stripe of kerbStripes(kerb.polyline, kerb.widthM, style.kerbStripeM, kerb.closed)) {
      out.push({ op: 'fill', layer: LAYER.kerbs, color: stripe.red ? style.kerbRed : style.kerbWhite, polygon: stripe.polygon })
    }
  }

  for (const wall of track.walls) {
    if (wall.kind !== 'barrier') continue
    out.push({ op: 'stroke', layer: LAYER.barriers, color: style.barrier, widthM: style.barrierWidthM, polyline: wall.polyline, closed: wall.closed })
  }

  out.push(...startBoxNumbers(track, style))

  const [a, b] = track.timing.line
  const squares = Math.max(2, Math.round(Math.hypot(b[0] - a[0], b[1] - a[1]) / CHECKER_SQUARE_M))
  const square = Math.hypot(b[0] - a[0], b[1] - a[1]) / squares
  out.push({ op: 'checker', layer: LAYER.chequer, a, b, depthM: CHECKER_ROWS * square, squares })

  // The tyres (kind `dot`) are not baked: see `looseTyres`.
  for (const marker of track.markers) {
    if (marker.kind !== 'dot') out.push({ op: 'disc', layer: LAYER.markers, color: style.marker, x: marker.x, y: marker.y, r: marker.r })
  }

  return orderCommands(out)
}
