import { STEPS_PER_BAR, type NoteEvent, type Piece, type PieceId, type Voice } from './sequence'

// The music's note data (F-705). Both pieces are original, written for this game: a light chiptune (square, triangle
// and a noise hat) that stays out of the way of the motors. Each loops without a seam: the last bar is a chord that
// leads into the first, no note is held across the join, and no note starts early.
//
// The notation of a melody line is one token per sixteenth, sixteen to a bar, bars divided by `|`:
// a note name (`E5`, `F#4`) starts a note, `-` holds it for another sixteenth, `.` is a rest.

const SEMITONES: Readonly<Record<string, number>> = { C: 0, D: 2, E: 4, F: 5, G: 7, A: 9, B: 11 }

/** `E5` → 76; `F#4` → 66. Middle C is `C4`, 60. */
function midiOf(name: string): number {
  const match = /^([A-G])(#?)(\d)$/.exec(name)
  if (match === null) throw new Error(`pieces: '${name}' is not a note name`)
  return 12 * (Number(match[3]) + 1) + (SEMITONES[match[1] ?? ''] ?? 0) + (match[2] === '#' ? 1 : 0)
}

/** A melody written out, one token a sixteenth. */
function line(text: string, vel = 1): NoteEvent[] {
  const bars = text.split('|').map((bar) => bar.trim().split(/\s+/))
  const notes: NoteEvent[] = []
  bars.forEach((tokens, bar) => {
    if (tokens.length !== STEPS_PER_BAR) throw new Error(`pieces: bar ${bar + 1} has ${tokens.length} tokens, not ${STEPS_PER_BAR}`)
    tokens.forEach((token, i) => {
      const step = bar * STEPS_PER_BAR + i
      if (token === '.') return
      if (token === '-') {
        const held = notes[notes.length - 1]
        if (held === undefined || held.step + held.len !== step) throw new Error(`pieces: a '-' at step ${step} holds nothing`)
        held.len++
        return
      }
      notes.push({ step, len: 1, midi: midiOf(token), vel })
    })
  })
  return notes
}

/** [step in the bar, length in sixteenths, midi, velocity]. */
type Hit = readonly [number, number, number, number]

/** Notes made bar by bar: `make` gives the bar's notes. */
function build(bars: number, make: (bar: number) => readonly Hit[]): NoteEvent[] {
  const notes: NoteEvent[] = []
  for (let bar = 0; bar < bars; bar++) {
    for (const [step, len, midi, vel] of make(bar)) notes.push({ step: bar * STEPS_PER_BAR + step, len, midi, vel })
  }
  return notes
}

interface Chord {
  /** The bass note, midi. */
  root: number
  /** Semitones above the root: the three chord tones and the octave. */
  tones: readonly [number, number, number, number]
}
const MINOR = [0, 3, 7, 12] as const
const MAJOR = [0, 4, 7, 12] as const

/** The tone an arpeggio asks for: index 0..3 are the chord's tones, 4 and up the same an octave higher. */
const toneOf = (chord: Chord, base: number, index: number): number => base + (chord.tones[index % 4] ?? 0) + (index >= 4 ? 12 : 0)

/** The arpeggio's eight eighths, as indices into the chord. */
const EIGHTHS = [0, 1, 2, 3, 2, 1, 2, 1] as const
/** The same four tones, up and back, for sixteenths. */
const SIXTEENTHS = [0, 1, 2, 1] as const

// ── Title and menus ─────────────────────────────────────────────────────────────────────────────────────────────
// A minor, 96 bpm, 16 bars (40 s): Am, F, C, G, two bars each, twice round. The second time round the arpeggio
// doubles its pace and the hat comes in with eighths. All white keys.

const TITLE_CHORDS: readonly Chord[] = [
  { root: midiOf('A2'), tones: MINOR },
  { root: midiOf('F2'), tones: MAJOR },
  { root: midiOf('C3'), tones: MAJOR },
  { root: midiOf('G2'), tones: MAJOR },
]
const titleChord = (bar: number): Chord => TITLE_CHORDS[Math.floor(bar / 2) % 4] ?? TITLE_CHORDS[0]!

const TITLE_LEAD =
  // Am
  'E5 - - - . . D5 - C5 - - - D5 - E5 - | A4 - - - - - - - - - - - . . . . |' +
  // F
  ' C5 - - - . . A4 - C5 - - - D5 - C5 - | C5 - - - . . . . A4 - C5 - . . . . |' +
  // C
  ' E5 - - - G5 - - - E5 - D5 - C5 - - - | D5 - - - . . E5 - - - - - . . . . |' +
  // G
  ' D5 - - - B4 - - - D5 - E5 - G5 - - - | E5 - - - D5 - - - B4 - - - . . A4 - |' +
  // the second time round, a little higher and busier. Am
  ' A4 - C5 - E5 - - - A5 - - - G5 - E5 - | E5 - - - . . D5 - C5 - - - . . . . |' +
  // F
  ' F5 - - - E5 - C5 - A4 - C5 - F5 - - - | E5 - - - C5 - - - . . A4 - C5 - - - |' +
  // C
  ' G5 - - - E5 - - - C5 - E5 - G5 - - - | F5 - - - E5 - - - D5 - - - C5 - . . |' +
  // G
  ' B4 - D5 - G5 - - - D5 - B4 - A4 - - - | B4 - - - A4 - - - G4 - - - . . . .'

const TITLE_VOICES: readonly Voice[] = [
  { name: 'lead', wave: 'square', gain: 0.09, filterHz: 3200, attackS: 0.012, releaseS: 0.14, sustain: 0.75, notes: line(TITLE_LEAD) },
  {
    name: 'arp',
    wave: 'square',
    gain: 0.045,
    filterHz: 2200,
    attackS: 0.004,
    releaseS: 0.08,
    sustain: 0.4,
    notes: build(16, (bar): Hit[] => {
      const chord = titleChord(bar)
      const base = chord.root + 12
      // Quarter notes the first time round, eighths the second.
      if (bar < 8) return [0, 1, 2, 3].map((q): Hit => [q * 4, 2, toneOf(chord, base, SIXTEENTHS[q] ?? 0), 0.8])
      return EIGHTHS.map((index, e): Hit => [e * 2, 2, toneOf(chord, base, index), 0.8])
    }),
  },
  {
    name: 'bass',
    wave: 'triangle',
    gain: 0.16,
    filterHz: 900,
    attackS: 0.01,
    releaseS: 0.08,
    sustain: 0.85,
    notes: build(16, (bar): Hit[] => {
      const r = titleChord(bar).root
      return bar % 2 === 0
        ? [[0, 6, r, 1], [6, 2, r, 0.7], [8, 4, r + 7, 0.8], [12, 2, r + 12, 0.7]]
        : [[0, 6, r, 1], [8, 2, r + 7, 0.8], [10, 2, r + 12, 0.8], [12, 4, r + 7, 0.7]]
    }),
  },
  {
    name: 'hat',
    wave: 'noise',
    gain: 0.04,
    filterHz: 7500,
    attackS: 0.001,
    releaseS: 0.02,
    sustain: 0.2,
    notes: build(16, (bar): Hit[] => {
      if (bar < 2) return []
      if (bar < 8) return [[4, 1, 0, 0.45], [12, 1, 0, 0.45]]
      return [[2, 1, 0, 0.3], [4, 1, 0, 0.5], [6, 1, 0, 0.3], [10, 1, 0, 0.3], [12, 1, 0, 0.5], [14, 1, 0, 0.3]]
    }),
  },
]

// ── Session ─────────────────────────────────────────────────────────────────────────────────────────────────────
// E minor, 128 bpm, 16 bars (30 s): Em, C, G, D, a bar each. It starts bare, a bass and a light arpeggio, so that
// every pass of the loop begins quietly; the hat comes in at bar 5, the snare and the lead's fuller tune at bar 9.
// Everything is in the key of G major (one black key, F sharp).

const SESSION_CHORDS: readonly Chord[] = [
  { root: midiOf('E2'), tones: MINOR },
  { root: midiOf('C3'), tones: MAJOR },
  { root: midiOf('G2'), tones: MAJOR },
  { root: midiOf('D3'), tones: MAJOR },
]
const sessionChord = (bar: number): Chord => SESSION_CHORDS[bar % 4] ?? SESSION_CHORDS[0]!

const SESSION_LEAD =
  // bars 1-4 rest
  '. . . . . . . . . . . . . . . . | . . . . . . . . . . . . . . . . | . . . . . . . . . . . . . . . . | . . . . . . . . . . . . . . . . |' +
  // Em, C
  ' B4 - - - - - - - G4 - - - B4 - - - | C5 - - - - - - - E5 - - - . . . . |' +
  // G, D
  ' D5 - - - - - B4 - G4 - - - B4 - D5 - | A4 - - - - - - - F#4 - - - . . . . |' +
  // the fuller tune. Em, C
  ' B4 - E5 - G5 - - - F#5 - E5 - . . D5 - | E5 - - - . . G5 - - - E5 - C5 - - - |' +
  // G, D
  ' D5 - - - G5 - - - F#5 - G5 - A5 - - - | F#5 - - - . . D5 - - - A4 - . . . . |' +
  // Em, C
  ' G5 - - - E5 - - - B4 - E5 - G5 - - - | E5 - - - G5 - - - C5 - - - E5 - - - |' +
  // G, D
  ' D5 - B4 - G4 - B4 - D5 - - - . . . . | A4 - - - F#4 - - - A4 - - - . . . .'

const SESSION_VOICES: readonly Voice[] = [
  { name: 'lead', wave: 'square', gain: 0.08, filterHz: 3000, attackS: 0.01, releaseS: 0.1, sustain: 0.7, notes: line(SESSION_LEAD) },
  {
    name: 'arp',
    wave: 'square',
    gain: 0.04,
    filterHz: 2400,
    attackS: 0.003,
    releaseS: 0.05,
    sustain: 0.5,
    notes: build(16, (bar): Hit[] => {
      const chord = sessionChord(bar)
      const base = chord.root + 12
      if (bar < 4) return EIGHTHS.map((index, e): Hit => [e * 2, 2, toneOf(chord, base, index), 0.7])
      return Array.from({ length: 16 }, (_, s): Hit => [s, 1, toneOf(chord, base, SIXTEENTHS[s % 4] ?? 0), 0.5])
    }),
  },
  {
    name: 'bass',
    wave: 'triangle',
    gain: 0.17,
    filterHz: 1000,
    attackS: 0.006,
    releaseS: 0.05,
    sustain: 0.9,
    notes: build(16, (bar): Hit[] => {
      const r = sessionChord(bar).root
      return [0, 0, 12, 0, 0, 12, 0, 7].map((offset, e): Hit => [e * 2, 2, r + offset, e % 2 === 0 ? 1 : 0.8])
    }),
  },
  {
    name: 'hat',
    wave: 'noise',
    gain: 0.035,
    filterHz: 8000,
    attackS: 0.001,
    releaseS: 0.02,
    sustain: 0.2,
    notes: build(16, (bar): Hit[] => {
      if (bar < 4) return []
      const offBeats = [2, 6, 10, 14].map((s): Hit => [s, 1, 0, 0.5])
      return bar < 8 ? offBeats : [...offBeats, ...[0, 4, 8, 12].map((s): Hit => [s, 1, 0, 0.25])]
    }),
  },
  {
    name: 'snare',
    wave: 'noise',
    gain: 0.05,
    filterHz: 1800,
    attackS: 0.001,
    releaseS: 0.04,
    sustain: 0.15,
    notes: build(16, (bar): Hit[] => (bar < 8 ? [] : [[4, 2, 0, 0.6], [12, 2, 0, 0.6]])),
  },
]

export const PIECES: Readonly<Record<PieceId, Piece>> = {
  title: { id: 'title', bpm: 96, bars: 16, level: 1.6, voices: TITLE_VOICES },
  session: { id: 'session', bpm: 128, bars: 16, level: 1, voices: SESSION_VOICES },
}

export const PIECE_IDS: readonly PieceId[] = ['title', 'session']
