import type { AudioMixer } from './AudioMixer'
import { CHEER, CHEER_S, cheerPlan, type CheerPlan } from './crowd-plan'
import { noiseBuffer } from './noise'

/**
 * The level of the cheer's output node, against full scale, set so that the cheer peaks at about a third of full scale
 * before the buses: rendered offline in Chrome (the real graph, an `OfflineAudioContext`) when the cheer was two seconds, its peak
 * was 0.33 and its level over the two seconds 0.048 (RMS), made of a roar at 0.028, voices at 0.037 and claps at 0.014 on their own
 * (the four-second cheer of F-712 has the same layers at the same budgets, twice as long). That is
 * as loud as a close contact and under the motors of a full field together; the master limiter catches it if it lands
 * on them. A first guess by the numbers, to be set by ear.
 */
export const CROWD_LEVEL = 0.45

/** The claps' stereo lanes, left and right of the middle. */
const LANE_PAN: readonly [number, number] = [-0.6, 0.6]
/** Every source is stopped this long after the cheer's end (`CHEER_S`), so that none is cut off while it can still be heard. */
const STOP_SLACK_S = 0.05

/** The slice of the mixer the crowd needs: the context, the effects bus, and whether anything would be heard. */
export type CrowdMixer = Pick<AudioMixer, 'ctx' | 'sfx' | 'audible'>

/**
 * The crowd's cheer when the winner takes the chequered flag (F-711) and when the event's podium appears (F-712): four seconds of roar, voices and clapping,
 * synthesised from the plan in `crowd-plan.ts`, through the mixer's effects bus (so that it is paused with the game,
 * silenced by the mute and the effects slider, and gone when the scene is). Nodes exist only while it sounds.
 */
export class Crowd {
  /** How many cheers were asked for, and how many of them were heard (started). For the tests and the debug hook. */
  requested = 0
  played = 0
  private nodes: AudioNode[] = []
  private sources: Array<AudioScheduledSourceNode> = []

  constructor(
    private readonly mixer: CrowdMixer,
    private readonly random: () => number = Math.random,
  ) {}

  /** Whether a cheer is sounding now. */
  get playing(): boolean {
    return this.nodes.length > 0
  }

  /** Cheers, at `level` (0..1) of its full level; false if it was not heard: the game is not making sound, or one is already sounding. */
  cheer(level = 1): boolean {
    this.requested++
    const { mixer } = this
    if (!mixer.audible || this.playing || !(level > 0)) return false
    const { ctx } = mixer
    const plan = cheerPlan(this.random)
    const t0 = ctx.currentTime
    const out = ctx.createGain()
    out.gain.value = CROWD_LEVEL * Math.min(1, level)
    out.connect(mixer.sfx)
    this.nodes.push(out)
    this.roar(ctx, out, t0)
    this.claps(ctx, out, t0, plan)
    for (const voice of plan.voices) this.voice(ctx, out, t0, voice)
    // Everything ends within the same moment; the roar's source is the one that tells.
    const roarSource = this.sources[0]
    roarSource.onended = () => this.release()
    this.played++
    return true
  }

  /** Stops the cheer, if one is sounding, and disconnects everything it made. */
  dispose(): void {
    for (const source of this.sources) {
      try {
        source.stop()
      } catch {
        // Already stopped.
      }
    }
    this.release()
  }

  private release(): void {
    for (const source of this.sources) source.onended = null
    for (const node of this.nodes) node.disconnect()
    this.sources = []
    this.nodes = []
  }

  private add<T extends AudioNode>(node: T): T {
    this.nodes.push(node)
    return node
  }

  private noise(ctx: AudioContext, t0: number): AudioBufferSourceNode {
    const source = ctx.createBufferSource()
    source.buffer = noiseBuffer(ctx)
    source.loop = true
    // A different stretch of the shared noise for each layer, so that the roar and the claps are not the same noise.
    source.start(t0, this.random() * source.buffer.duration)
    source.stop(t0 + CHEER_S + STOP_SLACK_S)
    this.sources.push(source)
    this.nodes.push(source)
    return source
  }

  /** The roar: broad band-passed noise, swelling in a quarter of a second, held, and dying away to nothing at the end. */
  private roar(ctx: AudioContext, out: AudioNode, t0: number): void {
    const { roar } = CHEER
    const source = this.noise(ctx, t0)
    const low = this.add(ctx.createBiquadFilter())
    low.type = 'highpass'
    low.frequency.value = roar.lowHz
    const high = this.add(ctx.createBiquadFilter())
    high.type = 'lowpass'
    high.frequency.value = roar.highHz
    const gain = this.add(ctx.createGain())
    gain.gain.setValueAtTime(0, t0)
    gain.gain.linearRampToValueAtTime(roar.gain, t0 + roar.attackS)
    gain.gain.setValueAtTime(roar.gain, t0 + roar.holdUntilS)
    gain.gain.linearRampToValueAtTime(0, t0 + CHEER_S)
    source.connect(low)
    low.connect(high)
    high.connect(gain)
    gain.connect(out)
  }

  /** The claps: bright noise bursts, a few milliseconds up and thirty down, in two stereo lanes. */
  private claps(ctx: AudioContext, out: AudioNode, t0: number, plan: CheerPlan): void {
    const { claps } = CHEER
    for (const lane of [0, 1] as const) {
      const source = this.noise(ctx, t0)
      const band = this.add(ctx.createBiquadFilter())
      band.type = 'bandpass'
      band.frequency.value = claps.hz
      band.Q.value = 1.2
      const gain = this.add(ctx.createGain())
      gain.gain.setValueAtTime(0, t0)
      for (const clap of plan.claps) {
        if (clap.lane !== lane) continue
        const at = t0 + clap.atS
        gain.gain.setValueAtTime(0, at)
        gain.gain.linearRampToValueAtTime(claps.gain * clap.gain, at + 0.003)
        gain.gain.linearRampToValueAtTime(0, at + claps.lengthS)
      }
      const pan = this.add(ctx.createStereoPanner())
      pan.pan.value = LANE_PAN[lane]
      source.connect(band)
      band.connect(gain)
      gain.connect(pan)
      pan.connect(out)
    }
  }

  /** One voice: a sawtooth that rises into a "whoo" and falls back, through two vowel resonances, in and out in a tenth of a second. */
  private voice(ctx: AudioContext, out: AudioNode, t0: number, voice: CheerPlan['voices'][number]): void {
    const start = t0 + voice.startS
    const end = start + voice.lengthS
    const osc = ctx.createOscillator()
    osc.type = 'sawtooth'
    osc.detune.value = voice.detune
    osc.frequency.setValueAtTime(voice.hz * 0.9, start)
    osc.frequency.linearRampToValueAtTime(voice.hz * 1.15, start + voice.lengthS / 3)
    osc.frequency.linearRampToValueAtTime(voice.hz, end)
    const gain = this.add(ctx.createGain())
    const peak = voice.gain * CHEER.voices.gain
    gain.gain.setValueAtTime(0, start)
    gain.gain.linearRampToValueAtTime(peak, start + 0.08)
    gain.gain.setValueAtTime(peak, end - 0.15)
    gain.gain.linearRampToValueAtTime(0, end)
    voice.formants.forEach((hz, i) => {
      const band = this.add(ctx.createBiquadFilter())
      band.type = 'bandpass'
      band.frequency.value = hz
      band.Q.value = CHEER.voices.q[i] ?? CHEER.voices.q[0]
      osc.connect(band)
      band.connect(gain)
    })
    const pan = this.add(ctx.createStereoPanner())
    pan.pan.value = voice.pan
    gain.connect(pan)
    pan.connect(out)
    osc.start(start)
    osc.stop(t0 + CHEER_S + STOP_SLACK_S)
    this.sources.push(osc)
    this.nodes.push(osc)
  }
}
