import type Phaser from 'phaser'
import type { Vec2 } from '@sim'
import type { NavKey } from '../input/keys'
import { FocusRing } from './focus'
import { Row } from './Row'
import { THEME, charWidth, lineHeight, type TextSize } from './theme'

export interface MenuItem {
  id: string
  label: string
  enabled?: boolean
}

export interface MenuListOptions {
  size?: TextSize
  /** Whether `pos.x` is the list's left edge or its middle. Every row shares one left edge, so the cursors line up. */
  anchor?: 'left' | 'centre'
  /** Logical pixels between the tops of two rows. */
  pitch?: number
}

const CURSOR = `${THEME.cursorGlyph} `
const NO_CURSOR = '  '

/** A vertical list of items: up and down move focus (skipping disabled items, wrapping), Enter chooses. The focused item shows the cursor glyph, a highlight bar and the accent colour. */
export class MenuList {
  private readonly rows = new Map<string, Row>()
  private readonly ring: FocusRing
  private readonly items: MenuItem[]
  private readonly confirmed: Array<(id: string) => void> = []

  constructor(scene: Phaser.Scene, pos: Vec2, items: readonly MenuItem[], opts: MenuListOptions = {}) {
    this.items = items.map((item) => ({ ...item }))
    const size = opts.size ?? 'body'
    const pitch = opts.pitch ?? Math.round(lineHeight(size) * 1.6)
    const chars = CURSOR.length + items.reduce((most, item) => Math.max(most, item.label.length), 0)
    const widthPx = chars * charWidth(size)
    const left = opts.anchor === 'centre' ? pos.x - Math.round(widthPx / 2) : pos.x
    this.ring = new FocusRing(this.items.map((item) => ({ id: item.id, enabled: item.enabled ?? true })))
    this.items.forEach((item, i) => {
      this.rows.set(item.id, new Row(scene, left, pos.y + i * pitch, widthPx, size, `${NO_CURSOR}${item.label}`))
    })
    this.paint()
  }

  /** The id of the focused item. */
  get focus(): string | null {
    return this.ring.current
  }

  /** Calls `fn` with the id of the item Enter chose. */
  onConfirm(fn: (id: string) => void): void {
    this.confirmed.push(fn)
  }

  /** Acts on a menu key; true if the list used it. */
  handle(key: NavKey): boolean {
    if (key === 'up' || key === 'down') {
      this.ring.move(key === 'down' ? 1 : -1)
      this.paint()
      return true
    }
    if (key === 'confirm') {
      const id = this.ring.current
      if (id === null) return true
      for (const fn of this.confirmed) fn(id)
      return true
    }
    return false
  }

  private paint(): void {
    const focus = this.ring.current
    for (const item of this.items) {
      const row = this.rows.get(item.id)
      if (row === undefined) continue
      const enabled = item.enabled ?? true
      const focused = item.id === focus
      row.setLabel(`${focused ? CURSOR : NO_CURSOR}${item.label}`)
      row.setTone(!enabled ? 'off' : focused ? 'focus' : 'normal')
    }
  }

  destroy(): void {
    for (const row of this.rows.values()) row.destroy()
    this.rows.clear()
    this.confirmed.length = 0
  }
}
