import { clamp, type CarId, type CarSnapshot, type Pose, type Vec2 } from '@sim'
import { tuning } from '@content/tuning'

// What a car's behaviour looks like on the ground (F-205): where its tyres touch, how much rubber each lays, when it
// smokes, how it leans. Everything here is a pure function of what the sim reports (snapshots, never state of its
// own about the race) and none of it knows Phaser, so that it is tested in Node. `SkidLayer` and `CarFx` draw it.

// ── The constants block ──────────────────────────────────────────────────────────────────────────────────────

/**
 * Every number that shapes the rubber on the track, in one place.
 *
 * A tyre lays two kinds of rubber. The **film** is the faint scrub of a tyre that is working: its alpha follows how
 * much of the axle's grip budget is in use (the snapshot's `slipFront` / `slipRear`), from braking, cornering and
 * drive alike, and it is nothing on a straight where the tyres are barely loaded. It adds up over a session, from
 * every car, to the film's ceiling, so that the line cars share builds as the session goes on and never turns black.
 * The **slide** is the dark mark of a tyre that is well past its peak slip angle; it adds to the film and may take
 * the pixel higher, to its own ceiling.
 *
 * Alphas are per pass: what one tyre leaves on a pixel it rolls over once.
 */
export const RUBBER = {
  /** Ink, the darkest colour in the game (art-direction.md). The layer's alpha makes it asphalt-dark, not black. */
  colour: 0x16161e,
  /** A tyre's width, m. A mark is this wide at the current pixels per metre, and never under one pixel. */
  tyreWidthM: 0.03,
  /**
   * How far apart consecutive stamps are along a line, as a share of the mark's width: half, so each pixel is
   * covered by two stamps each laying half the alpha, which keeps the line even whichever way it runs.
   */
  spacingShare: 0.5,
  film: {
    /** Below this share of an axle's grip budget in use, a tyre lays nothing. */
    floor: 0.3,
    /** How quickly the film darkens above the floor: 1 is in a straight line to the most. */
    exponent: 1.6,
    /** The most one pass lays, at the whole budget in use. */
    passAlpha: 0.17,
    /** The most the film alone builds a pixel up to, over any number of laps and cars. */
    ceiling: 0.42,
  },
  slide: {
    /** Slip angle, in multiples of the tyre's peak slip angle: nothing darker below `from`, the whole of it at `full`. */
    from: 1.2,
    full: 2.2,
    passAlpha: 0.3,
    /** The most a pixel is built up to where a car has slid. */
    ceiling: 0.62,
  },
  /** Below this speed, m/s, a car lays nothing: it is not rolling, it is standing and turning its tyres. */
  minSpeedMS: 0.15,
  /** A wheel that moves further than this between two frames, px, was set down, not driven: the line is not drawn across. */
  breakPx: 60,
  /** A stamp that would lay less than this alpha is not made: the texture cannot hold it. */
  minStampAlpha: 1 / 255,
} as const

/**
 * Smoke and dust. Smoke comes from a tyre sliding well past its peak slip angle for more than `afterS`; dust from a
 * hard enough hit on a wall. The slip of both is in multiples of the tyre's peak slip angle.
 */
export const FX = {
  smoke: {
    /** Slip, in multiples of the peak slip angle, at which smoke starts, and the slip at which it is thickest. */
    from: 1.6,
    full: 2.6,
    /** Puffs a second from one axle at the most. */
    maxPerS: 28,
    /** A tyre must have slid this long, s, before it smokes. */
    afterS: 0.1,
    /** Below this speed, m/s, there is no smoke: a car barely moving only scrubs. */
    minSpeedMS: 0.5,
  },
  dust: {
    /** A wall hit below this impulse, N·s (1.6 N·s is about 1 m/s into the wall for a 1.3 kg car), raises none. */
    minImpulseNs: 1,
    /** The impulse at which the puff is as big as it gets. */
    fullImpulseNs: 6,
    /** Puffs for a hit just over the threshold, and for the hardest. */
    minPuffs: 3,
    maxPuffs: 8,
  },
  /** The brake tell shows above this brake, while the car is going forward at more than `brakeMinSpeedMS`. */
  brakeAbove: 0.2,
  brakeMinSpeedMS: 0.05,
  /** The lean: it is one pixel, once a car is at this share of its grip limit, and goes again below `leanOff`. */
  leanOn: 0.55,
  leanOff: 0.4,
} as const

/** The frame of a puff `age` (0 at birth, 1 at its end) through its life (F-802): it grows through its frames evenly. */
export function puffFrame(age: number, frames: number): number {
  return Math.min(frames - 1, Math.max(0, Math.floor(age * frames)))
}

// ── Wheel geometry ───────────────────────────────────────────────────────────────────────────────────────────

/** The part of a car's geometry that says where its tyres are. */
export interface WheelGeometry {
  wheelbaseM: number
  widthM: number
  cgToFrontAxleM: number
}

/** Where a car's four tyres touch the ground. World metres. */
export interface WheelPoints {
  fl: Vec2
  fr: Vec2
  rl: Vec2
  rr: Vec2
}

/**
 * Where the tyres touch, as a share of the body's width: the same figure the sim finds kerbs by (the contact patch
 * is inside the body, which swells over the wheel), so a mark and a kerb hop agree on where a wheel is.
 */
export const WHEEL_TRACK_SHARE = tuning.surface.kerb.wheelTrackShare

/**
 * The four tyres' contact points for a car at `pose`: the front axle `cgToFrontAxleM` ahead of the centre of mass,
 * the rear one `wheelbaseM` behind that, the two tyres of an axle `trackShare` of the width apart. `l` is the car's
 * left, which on a screen with y down is the smaller y at heading 0.
 */
export function wheelPoints(pose: Pose, p: WheelGeometry, trackShare = WHEEL_TRACK_SHARE): WheelPoints {
  const cos = Math.cos(pose.angle)
  const sin = Math.sin(pose.angle)
  const half = (p.widthM * trackShare) / 2
  const front = p.cgToFrontAxleM
  const rear = p.cgToFrontAxleM - p.wheelbaseM
  const at = (along: number, across: number): Vec2 => ({
    x: pose.x + cos * along - sin * across,
    y: pose.y + sin * along + cos * across,
  })
  return { fl: at(front, -half), fr: at(front, half), rl: at(rear, -half), rr: at(rear, half) }
}

// ── What the tyres are doing ─────────────────────────────────────────────────────────────────────────────────

/** What the slip angle is read against: the tyre curve's peak, and the speed it never reads the roll below. */
export interface TyreSlip {
  peakSlipRad: number
  slipSpeedFloorMS: number
}

/** The tyre figures the sim runs on. */
export const TYRE_SLIP: TyreSlip = { peakSlipRad: tuning.tyre.peakSlipRad, slipSpeedFloorMS: tuning.tyre.slipSpeedFloorMS }

/** How far each axle's tyres are sliding, in multiples of their peak slip angle: 1 is the grip at its best, 2 is twice the angle. */
export interface SlipRatios {
  front: number
  rear: number
}

/**
 * The slip angle of each axle, from what the snapshot holds of the car's motion, as the vehicle model finds it
 * (the sideways speed of the tyre's contact patch over its rolling speed), over the tyre's peak slip angle. The
 * snapshot's own `slipFront` / `slipRear` say how much of the grip is in use but stop at 1; this says how far
 * past the peak the tyre is, which is what a slide is.
 */
export function slipRatios(
  car: Pick<CarSnapshot, 'pose' | 'velocity' | 'yawRateRadS' | 'steerRad'>,
  geometry: Pick<WheelGeometry, 'wheelbaseM' | 'cgToFrontAxleM'>,
  tyre: TyreSlip = TYRE_SLIP,
): SlipRatios {
  const cos = Math.cos(car.pose.angle)
  const sin = Math.sin(car.pose.angle)
  const vLong = cos * car.velocity.x + sin * car.velocity.y
  const vLat = -sin * car.velocity.x + cos * car.velocity.y
  const latFront = vLat + geometry.cgToFrontAxleM * car.yawRateRadS
  const latRear = vLat - (geometry.wheelbaseM - geometry.cgToFrontAxleM) * car.yawRateRadS
  const cosS = Math.cos(car.steerRad)
  const sinS = Math.sin(car.steerRad)
  const rollFront = Math.max(Math.abs(vLong * cosS + latFront * sinS), tyre.slipSpeedFloorMS)
  const rollRear = Math.max(Math.abs(vLong), tyre.slipSpeedFloorMS)
  const front = Math.atan2(-vLong * sinS + latFront * cosS, rollFront)
  const rear = Math.atan2(latRear, rollRear)
  return { front: Math.abs(front) / tyre.peakSlipRad, rear: Math.abs(rear) / tyre.peakSlipRad }
}

const smooth = (t: number): number => t * t * (3 - 2 * t)
const ramp = (value: number, from: number, to: number): number => clamp((value - from) / (to - from), 0, 1)

/**
 * The faint film a tyre lays per pass when `use` of its axle's grip budget is in use (0..1): nothing below the
 * floor, rising to the film's pass alpha with the whole budget.
 */
export function filmAlpha(use: number): number {
  const { floor, exponent, passAlpha } = RUBBER.film
  return passAlpha * Math.pow(ramp(use, floor, 1), exponent)
}

/**
 * The dark mark a tyre lays per pass when it slips `slip` times its peak slip angle: nothing below the threshold,
 * rising smoothly to the slide's pass alpha, darker with more slip.
 */
export function skidAlpha(slip: number): number {
  const { from, full, passAlpha } = RUBBER.slide
  return passAlpha * smooth(ramp(slip, from, full))
}

/** What one axle lays per pass, and the highest it may build a pixel up to. A zero alpha lays nothing. */
export interface Deposit {
  alpha: number
  ceiling: number
}

/** The rubber an axle lays: the film for its load, plus the dark mark if it slides, under the ceiling of the darker of the two. */
export function axleDeposit(use: number, slip: number): Deposit {
  const film = filmAlpha(use)
  const slide = skidAlpha(slip)
  if (film + slide < RUBBER.minStampAlpha) return { alpha: 0, ceiling: RUBBER.film.ceiling }
  return { alpha: film + slide, ceiling: slide > 0 ? RUBBER.slide.ceiling : RUBBER.film.ceiling }
}

/**
 * Whether a car lays rubber at all: only while it is being driven along on the asphalt, rolling. None in the air
 * over a kerb hop, on the kerb or the grass, or while it is stricken, held or being carried.
 */
export function layingRubber(car: Pick<CarSnapshot, 'state' | 'surface' | 'airborne' | 'speedMS'>): boolean {
  return (
    (car.state === 'driving' || car.state === 'finished') &&
    car.surface === 'asphalt' &&
    !car.airborne &&
    Math.abs(car.speedMS) >= RUBBER.minSpeedMS
  )
}

/** The rubber each axle of a car lays now. */
export interface AxleRubber {
  front: Deposit
  rear: Deposit
}

const NO_DEPOSIT: Deposit = Object.freeze({ alpha: 0, ceiling: RUBBER.film.ceiling })

/** What each axle of a car lays, given how loaded it is (the interpolated `slipFront`, `slipRear`) and how far it slides. */
export function rubberFor(
  use: { slipFront: number; slipRear: number },
  slip: SlipRatios,
  car: Pick<CarSnapshot, 'state' | 'surface' | 'airborne' | 'speedMS'>,
): AxleRubber {
  if (!layingRubber(car)) return { front: NO_DEPOSIT, rear: NO_DEPOSIT }
  return { front: axleDeposit(use.slipFront, slip.front), rear: axleDeposit(use.slipRear, slip.rear) }
}

// ── Marks in a line ──────────────────────────────────────────────────────────────────────────────────────────

/** A mark's width in screen pixels: the tyre's, at this scale, and never under one. */
export function markWidthPx(pxPerM: number): number {
  return Math.max(1, Math.round(RUBBER.tyreWidthM * pxPerM))
}

/**
 * The points to stamp to carry a line from `prev` toward `curr`, both in world metres: one every `spacingPx` at
 * `pxPerM`, starting that far from `prev`, as many as fit before `curr`. The last may fall short of `curr` by less
 * than the spacing, and the caller carries on from it, so that a fast car leaves a line and not dots and a slow one
 * leaves no more rubber per metre than a fast one. A car that has not moved a spacing gets none.
 */
export function stampsBetween(prev: Vec2, curr: Vec2, spacingPx: number, pxPerM: number): Vec2[] {
  const dx = curr.x - prev.x
  const dy = curr.y - prev.y
  const distancePx = Math.hypot(dx, dy) * pxPerM
  const count = Math.floor(distancePx / spacingPx + 1e-9)
  const points: Vec2[] = []
  for (let i = 1; i <= count; i++) {
    const share = (i * spacingPx) / distancePx
    points.push({ x: prev.x + dx * share, y: prev.y + dy * share })
  }
  return points
}

/**
 * What every pixel of the track has been given so far: the alpha of the rubber on it, 0 for none. It mirrors the
 * texture the marks are stamped into, pixel for pixel, so that a pixel can be refused more than its ceiling; the
 * texture alone cannot say how dark a pixel already is without reading it back.
 */
export class RubberGrid {
  private readonly alpha: Float32Array

  constructor(
    readonly width: number,
    readonly height: number,
  ) {
    this.alpha = new Float32Array(width * height)
  }

  /** The alpha of the rubber on a pixel, 0 off the grid. */
  at(x: number, y: number): number {
    return x >= 0 && y >= 0 && x < this.width && y < this.height ? this.alpha[y * this.width + x] : 0
  }

  /**
   * Lays a `size` pixel square whose top-left pixel is `x`, `y`, wanting `alpha` over each pixel it covers but
   * never taking the darkest of them above `ceiling`. Returns the alpha it laid: 0 if nothing was, and then nothing
   * was changed. Overlaps add the way stamping one over another does: 1 - (1 - a)(1 - b).
   */
  deposit(x: number, y: number, size: number, alpha: number, ceiling: number): number {
    const x0 = Math.max(0, x)
    const y0 = Math.max(0, y)
    const x1 = Math.min(this.width, x + size)
    const y1 = Math.min(this.height, y + size)
    if (x1 <= x0 || y1 <= y0) return 0
    let darkest = 0
    for (let row = y0; row < y1; row++) {
      for (let col = x0; col < x1; col++) darkest = Math.max(darkest, this.alpha[row * this.width + col])
    }
    if (darkest >= ceiling) return 0
    const laid = Math.min(alpha, (ceiling - darkest) / (1 - darkest))
    if (laid < RUBBER.minStampAlpha) return 0
    for (let row = y0; row < y1; row++) {
      for (let col = x0; col < x1; col++) {
        const at = row * this.width + col
        this.alpha[at] += laid * (1 - this.alpha[at])
      }
    }
    return laid
  }

  clear(): void {
    this.alpha.fill(0)
  }
}

/** Where the world sits on the screen: the part of `WorldView` the marks need. */
export interface MarkView {
  pxPerM: number
  originX: number
  originY: number
}

/** One mark to put on the texture: a square of `size` pixels with its top-left pixel at `x`, `y`, of this alpha. */
export interface Stamp {
  x: number
  y: number
  size: number
  alpha: number
}

/** What the layer needs of a car for one frame: where it is drawn and what each axle lays. */
export interface MarkedCar {
  id: CarId
  pose: Pose
  rubber: AxleRubber
}

const WHEELS = 4

/**
 * Turns frames of cars into stamps, and keeps the grid of what has been laid. Each wheel remembers where it was on
 * the last frame; each frame the line is carried from there to where it is now, a stamp every mark's width, with
 * the alpha its axle lays, cut off where the grid says a pixel is dark enough. Cost depends on how far the cars
 * went this frame, never on how much has been laid. It holds no race state: a new layer is an empty track.
 */
export class RubberLayer {
  readonly grid: RubberGrid
  private readonly widthPx: number
  /**
   * Where each wheel's line stands, world metres, as pairs: front left, front right, rear left, rear right of each
   * car. While a wheel lays rubber it is the last stamp; otherwise it is where the wheel was on the last frame.
   */
  private readonly last: Float64Array
  private readonly seen: Uint8Array
  private readonly enabled: boolean[]
  private readonly stampBuffer: Stamp = { x: 0, y: 0, size: 0, alpha: 0 }

  constructor(
    private readonly view: MarkView,
    screen: { w: number; h: number },
    private readonly geometries: readonly WheelGeometry[],
  ) {
    this.grid = new RubberGrid(screen.w, screen.h)
    this.widthPx = markWidthPx(view.pxPerM)
    this.last = new Float64Array(geometries.length * WHEELS * 2)
    this.seen = new Uint8Array(geometries.length * WHEELS)
    this.enabled = geometries.map(() => true)
  }

  /** Lets a car lay rubber or stops it (the wet track stops marks, F-603). A car that stops forgets where its wheels were. */
  setEnabledFor(car: CarId, enabled: boolean): void {
    if (this.enabled[car] === undefined) return
    this.enabled[car] = enabled
    if (!enabled) this.seen.fill(0, car * WHEELS, (car + 1) * WHEELS)
  }

  /** Forgets every mark and every wheel's place: an empty track. */
  clear(): void {
    this.grid.clear()
    this.seen.fill(0)
  }

  /** The width of every mark, px. */
  get markPx(): number {
    return this.widthPx
  }

  /** Carries every car's wheels on to where `cars` have them now, calling `emit` for each stamp to put on the texture. */
  lay(cars: readonly MarkedCar[], emit: (stamp: Stamp) => void): void {
    for (const car of cars) {
      const geometry = this.geometries[car.id]
      if (geometry === undefined) continue
      const points = wheelPoints(car.pose, geometry)
      const wheels = [points.fl, points.fr, points.rl, points.rr]
      const allowed = this.enabled[car.id]
      for (let w = 0; w < WHEELS; w++) {
        const slot = car.id * WHEELS + w
        const to = wheels[w]
        const deposit = w < 2 ? car.rubber.front : car.rubber.rear
        if (allowed && deposit.alpha > 0) this.carry(slot, to, deposit, emit)
        else this.rest(slot, to)
      }
    }
  }

  /** The wheel is not laying: its line starts afresh from wherever it is when it does. */
  private rest(slot: number, at: Vec2): void {
    this.last[slot * 2] = at.x
    this.last[slot * 2 + 1] = at.y
    this.seen[slot] = 1
  }

  /** Carries the wheel's line from its last stamp to `to`. */
  private carry(slot: number, to: Vec2, deposit: Deposit, emit: (stamp: Stamp) => void): void {
    const { pxPerM } = this.view
    const spacingPx = this.widthPx * RUBBER.spacingShare
    const from = { x: this.last[slot * 2], y: this.last[slot * 2 + 1] }
    // A wheel with no line yet, or one that jumped (the car was set down), starts a line where it is.
    if (this.seen[slot] === 0 || Math.hypot(to.x - from.x, to.y - from.y) * pxPerM > RUBBER.breakPx) {
      this.stamp(to, deposit, emit)
      this.rest(slot, to)
      return
    }
    const points = stampsBetween(from, to, spacingPx, pxPerM)
    for (const point of points) this.stamp(point, deposit, emit)
    const end = points[points.length - 1]
    if (end !== undefined) this.rest(slot, end)
  }

  private stamp(at: Vec2, deposit: Deposit, emit: (stamp: Stamp) => void): void {
    const size = this.widthPx
    const x = Math.round(this.view.originX + at.x * this.view.pxPerM - size / 2)
    const y = Math.round(this.view.originY + at.y * this.view.pxPerM - size / 2)
    const laid = this.grid.deposit(x, y, size, deposit.alpha * RUBBER.spacingShare, deposit.ceiling)
    if (laid === 0) return
    this.stampBuffer.x = x
    this.stampBuffer.y = y
    this.stampBuffer.size = size
    this.stampBuffer.alpha = laid
    emit(this.stampBuffer)
  }
}

// ── Smoke, dust, the brake tell, the lean ────────────────────────────────────────────────────────────────────

/**
 * Puffs of smoke a second from an axle that slips `slip` times its peak slip angle at `speedMS`: none below the
 * threshold, rising to the most, and fewer the slower the car goes until it is barely moving, when there are none.
 */
export function smokeRate(slip: number, speedMS: number): number {
  const { from, full, maxPerS, minSpeedMS } = FX.smoke
  const speed = Math.abs(speedMS)
  if (speed < minSpeedMS) return 0
  return maxPerS * ramp(slip, from, full) * Math.min(1, speed / (4 * minSpeedMS))
}

/** How many puffs of dust a wall hit of `impulseNs` raises: none below the threshold, more the harder it is. */
export function dustPuffs(impulseNs: number): number {
  const { minImpulseNs, fullImpulseNs, minPuffs, maxPuffs } = FX.dust
  if (!(impulseNs >= minImpulseNs)) return 0
  return Math.round(minPuffs + (maxPuffs - minPuffs) * ramp(impulseNs, minImpulseNs, fullImpulseNs))
}

/** Whether the brake lights show: the brake is on and the car is moving forward. */
export function brakeTell(brake: number, speedMS: number): boolean {
  return brake > FX.brakeAbove && speedMS > FX.brakeMinSpeedMS
}

/** The sideways acceleration of a car, m/s²: speed times yaw rate. Positive is a turn to the right (clockwise). */
export function lateralAccelMS2(speedMS: number, yawRateRadS: number): number {
  return speedMS * yawRateRadS
}

/**
 * How far the body leans toward the outside of the corner, in whole pixels: at most one, in the direction of the
 * outside (positive: to the car's left, the outside of a right turn). `lateral` is the sideways acceleration and
 * `limit` the class's grip limit, in the same units. A car at the on-share of its limit leans, and keeps leaning
 * until it is back below the off-share: `previous`, the lean it had, stops it flickering at the edge.
 */
export function leanOffsetPx(lateral: number, limit: number, previous = 0): number {
  if (!(limit > 0)) return 0
  const share = lateral / limit
  const held = Math.sign(previous)
  if (Math.abs(share) >= FX.leanOn) return Math.sign(share)
  if (held !== 0 && Math.abs(share) >= FX.leanOff && Math.sign(share) === held) return held
  return 0
}

/**
 * The lean as a screen offset: one pixel along whichever axis the car's left lies closest to, so that the body
 * never moves further than a pixel from its shadow. `lean` is `leanOffsetPx`'s answer.
 */
export function leanVector(angle: number, lean: number): { x: number; y: number } {
  if (lean === 0) return { x: 0, y: 0 }
  const leftX = Math.sin(angle)
  const leftY = -Math.cos(angle)
  return Math.abs(leftX) >= Math.abs(leftY) ? { x: Math.sign(leftX) * lean, y: 0 } : { x: 0, y: Math.sign(leftY) * lean }
}
