import type Phaser from 'phaser'
import { assignColours, chooseOpponents, createSession, gripLimitMS2, orientTrack, resolveCar, CALM_WEATHER, type CarClassId, type Session, type SessionConfig, type SessionEntry, type SessionPhase } from '@sim'
import { classes } from '@content/classes'
import { ROSTER } from '@content/roster'
import { cuencaRc } from '@content/tracks'
import { tuning } from '@content/tuning'
import type { DirectionSet } from '../assets/manifest'
import type { WorldView } from '../config'
import { CarView, carSpriteName, flippedSpriteName, NUMBER_TINT, numberSpriteName, shadowSpriteName, type CarLook, type CarSpriteInfo } from './CarView'
import { EventBus } from './EventBus'
import { interpolateCars, type RenderCar } from './interpolate'
import { SimRunner } from './SimRunner'

// The race behind the title (F-801): seven AI cars of one class on the home track, drawn by the race scene's own car renderer
// with no HUD, no commentary and no sound. It owns a session and a runner and draws only the cars: the ground under them is
// the title's. When a session finishes, a new one with another field begins, so that the race never ends.

/** The field: the most a session holds. */
export const ATTRACT_CARS = 7

/** Long enough that it is effectively endless; the next session begins when this one finishes. */
const ATTRACT_DURATION_S = 900

/** The sim's staging and countdown are skipped by running them fast, so the cars are racing within a second of the title appearing. */
const START_TIME_SCALE = 40

/** Where the tail lamps sit, as shares of the car's length behind its centre and of its width either side of the middle (the race scene's). */
const LAMP_ALONG_SHARE = 0.46
const LAMP_ACROSS_SHARE = 0.34

/**
 * The session behind the title for a class: seven drivers of the roster on the home track, counter-clockwise, strongest on
 * the front of the grid, in seven different colours; every one driven by the game. Pure: the same seed gives the same field.
 */
export function attractConfig(carClass: CarClassId, seed: number): SessionConfig {
  const field = chooseOpponents('regional', ATTRACT_CARS, ROSTER, seed)
  const last = field[ATTRACT_CARS - 1]
  if (last === undefined || field.length !== ATTRACT_CARS) throw new Error(`The attract session needs ${ATTRACT_CARS} drivers and the roster gave ${field.length}`)
  // `assignColours` seats a player and at most six drivers; the seventh car takes his own colour and plays the part of the player.
  const colours = assignColours(
    field.slice(0, ATTRACT_CARS - 1).map((driver) => driver.id),
    last.preferredColour,
    ROSTER,
  )
  const entries: SessionEntry[] = field.map((driver, i) => ({
    driverId: driver.id,
    number: i + 1,
    colour: colours[driver.id] ?? last.preferredColour,
    controller: 'ai',
    startSlot: i,
  }))
  return {
    seed,
    kind: 'final',
    label: 'Attract',
    track: orientTrack(cuencaRc, 'counter-clockwise'),
    carClass,
    durationS: ATTRACT_DURATION_S,
    entries,
    difficulty: 'regional',
    weather: { ...CALM_WEATHER },
  }
}

/** What the debug hook reports of the race behind the title. */
export interface AttractInfo {
  carClass: CarClassId
  cars: number
  tick: number
  phase: SessionPhase
  /** How many sessions have begun, the first included. */
  sessions: number
  sprites: CarSpriteInfo[]
}

/** Where a car's pictures come from: a baked direction set by manifest name, on whichever atlas the caller loaded the class's cars under. */
export type DirectionSets = (name: string) => DirectionSet

export class AttractMode {
  private session: Session
  private runner: SimRunner
  private carView: CarView
  private bus = new EventBus()
  private readonly renderCars: RenderCar[] = []
  private lastTime = -1
  private sessions = 1
  private seed: number
  private destroyed = false

  /**
   * `sets` gives the cars' pictures (the title loads the class's atlas in the background under a key of its own, and says so here);
   * they must already be in the scene. `seed` makes the first field; later sessions count up from it.
   */
  constructor(
    private readonly scene: Phaser.Scene,
    private readonly view: WorldView,
    private readonly carClass: CarClassId,
    private readonly sets: DirectionSets,
    seed: number,
  ) {
    this.seed = seed
    const made = this.begin(seed)
    this.session = made.session
    this.runner = made.runner
    this.carView = made.carView
  }

  /** Steps the race by the real time since the last frame (`time` is the frame's raw timestamp, ms) and draws the cars. */
  update(time: number): void {
    if (this.destroyed) return
    const elapsedMs = this.lastTime < 0 ? 0 : time - this.lastTime
    this.lastTime = time
    const { runner } = this
    runner.timeScale = runner.curr.phase === 'staging' || runner.curr.phase === 'countdown' ? START_TIME_SCALE : 1
    this.bus.emit(runner.advance(elapsedMs))
    this.draw()
    if (runner.curr.phase === 'finished') this.restart()
  }

  info(): AttractInfo {
    return { carClass: this.carClass, cars: this.session.config.entries.length, tick: this.runner.curr.tick, phase: this.runner.curr.phase, sessions: this.sessions, sprites: this.carView.sprites() }
  }

  destroy(): void {
    if (this.destroyed) return
    this.destroyed = true
    this.carView.destroy()
    this.bus.clear()
    this.renderCars.length = 0
  }

  private draw(): void {
    const { runner } = this
    interpolateCars(runner.prev.cars, runner.curr.cars, runner.alpha, this.renderCars)
    this.carView.carrying(runner.curr.marshals)
    this.carView.update(this.renderCars, runner.curr.tick - 1 + runner.alpha, runner.curr.cars)
  }

  /** The session is over: another field takes the track. */
  private restart(): void {
    this.carView.destroy()
    this.bus.clear()
    this.bus = new EventBus()
    this.seed += 1
    this.sessions += 1
    const made = this.begin(this.seed)
    this.session = made.session
    this.runner = made.runner
    this.carView = made.carView
    this.lastTime = -1
  }

  /** A new session from `seed`, with the runner that steps it and the renderer of its cars. */
  private begin(seed: number): { session: Session; runner: SimRunner; carView: CarView } {
    const config = attractConfig(this.carClass, seed)
    const session = createSession(config)
    const runner = new SimRunner(session)
    const carView = new CarView(this.scene, this.view, this.looks(config))
    // The cars' lift over a kerb and a roll are the events the car renderer is told of.
    this.bus.on('kerb-hop', (hop) => carView.hop(hop.car, hop.tick, hop.airborneTicks))
    this.bus.on('flip', (flip) => carView.flip(flip.car, flip.tick))
    return { session, runner, carView }
  }

  /** How each car is drawn: the race scene's own looks. */
  private looks(config: SessionConfig): CarLook[] {
    const { carClass } = config
    const params = classes[carClass]
    const limit = gripLimitMS2(resolveCar(params, tuning))
    return config.entries.map((entry) => ({
      body: this.sets(carSpriteName(carClass, entry.colour)),
      flipped: this.sets(flippedSpriteName(carClass, entry.colour)),
      shadow: this.sets(shadowSpriteName(carClass)),
      number: this.sets(numberSpriteName(carClass, entry.number)),
      numberTint: NUMBER_TINT[entry.colour],
      lamps: { alongM: params.lengthM * LAMP_ALONG_SHARE, acrossM: params.widthM * LAMP_ACROSS_SHARE },
      gripLimitMS2: limit,
    }))
  }
}
