import Phaser from 'phaser'
import type { CarClassId } from '@sim'
import { gameFile } from '../assets/base'
import { manifestOf } from '../assets/manifest'
import { failOnLoadError, hasFailed } from '../lifecycle/report'
import { atlasFiles, atlasKeyFor } from './atlas'

/**
 * Puts the atlas with a class's car sprites into the scene's loader unless it is already in the texture cache
 * (ADR-005: only what a session needs is loaded). Does not start the loader: call it from `preload`, which does.
 * Returns true if the atlas was queued.
 */
export function queueClassAtlas(scene: Phaser.Scene, carClass: CarClassId): boolean {
  const manifest = manifestOf(scene)
  const key = atlasKeyFor(manifest, carClass)
  if (scene.textures.exists(key)) return false
  const files = atlasFiles(manifest, key)
  scene.load.atlas(key, gameFile(files.image), gameFile(files.data))
  return true
}

export interface ClassAtlasLoad {
  /** True if a download was started; false if the atlas was already there (and `done` has been called). */
  loading: boolean
  /** Forgets the callback; the download, if any, carries on. */
  cancel(): void
}

/**
 * Loads a class's atlas from a scene that is already running (the garage, when the player moves to a class not yet
 * seen). Calls `done` once the atlas is in the texture cache. A file that cannot be fetched puts the error screen up (F-803), as at boot.
 * Start it only when the scene's loader is idle.
 */
export function ensureClassAtlas(scene: Phaser.Scene, carClass: CarClassId, done: () => void): ClassAtlasLoad {
  if (!queueClassAtlas(scene, carClass)) {
    done()
    return { loading: false, cancel: () => undefined }
  }
  // A file that cannot be fetched puts the error screen up (F-803), and the callback is never made.
  const unwatch = failOnLoadError(scene)
  const finished = (): void => {
    unwatch()
    if (!hasFailed(scene.game)) done()
  }
  scene.load.once(Phaser.Loader.Events.COMPLETE, finished)
  scene.load.start()
  return {
    loading: true,
    cancel: () => {
      unwatch()
      scene.load.off(Phaser.Loader.Events.COMPLETE, finished)
    },
  }
}

let coverSerial = 0

export interface CoverAtlases {
  /** The texture key under which the atlas of a class was loaded here; the frame names inside are the manifest's. */
  keyOf(carClass: CarClassId): string
  /** Stops downloads still going, forgets the callback and removes the textures, whether they have arrived or still do. Safe to call twice. */
  dispose(): void
}

/**
 * Fetches the atlases of some classes in the background, for a scene that does not need them to be up (the title's
 * cover cars), and calls `done` once they are all in. They are loaded under keys of their own, never the ones the
 * garage and the race use, so a scene that opens in the meantime and asks for the same atlas cannot meet a
 * half-loaded one under its key (two loads of one key end in "Texture key already in use"); the cost is that the
 * same file is fetched again, from the browser's cache, if the player goes on to use the class. `dispose` removes
 * them, including any that land after the scene has gone.
 */
export function loadCoverAtlases(scene: Phaser.Scene, carClasses: readonly CarClassId[], done: () => void): CoverAtlases {
  const manifest = manifestOf(scene)
  const serial = ++coverSerial
  const coverKeys = new Map<string, string>()
  for (const carClass of carClasses) {
    const key = atlasKeyFor(manifest, carClass)
    if (!coverKeys.has(key)) coverKeys.set(key, `cover-${serial}-${key}`)
  }
  const { textures } = scene
  const load = scene.load
  for (const [key, coverKey] of coverKeys) {
    const files = atlasFiles(manifest, key)
    load.atlas(coverKey, gameFile(files.image), gameFile(files.data))
  }
  const queued = [...load.list]
  // The cover is the one thing the game can do without: a file of it that does not arrive leaves the title as it is, with no race behind the menu (F-803), and no error screen.
  let missing = false
  const lost = (): void => {
    missing = true
  }
  load.on(Phaser.Loader.Events.FILE_LOAD_ERROR, lost)
  const finished = (): void => {
    load.off(Phaser.Loader.Events.FILE_LOAD_ERROR, lost)
    if (!missing) done()
  }
  load.once(Phaser.Loader.Events.COMPLETE, finished)
  load.start()
  let disposed = false
  return {
    keyOf: (carClass) => {
      const coverKey = coverKeys.get(atlasKeyFor(manifest, carClass))
      if (coverKey === undefined) throw new Error(`No cover atlas for class '${carClass}'`)
      return coverKey
    },
    dispose: () => {
      if (disposed) return
      disposed = true
      load.off(Phaser.Loader.Events.COMPLETE, finished)
      load.off(Phaser.Loader.Events.FILE_LOAD_ERROR, lost)
      for (const file of queued) for (const part of file instanceof Phaser.Loader.MultiFile ? file.files : [file]) part.xhrLoader?.abort()
      for (const coverKey of coverKeys.values()) {
        if (textures.exists(coverKey)) textures.remove(coverKey)
        // A file whose download had ended but whose picture was still being decoded lands after this scene has gone.
        else textures.once(`${Phaser.Textures.Events.ADD}-${coverKey}`, () => textures.remove(coverKey))
      }
    },
  }
}
