import type Phaser from 'phaser'
import type { CarSnapshot } from '@sim'
import type { WorldView } from '../config'
import { text } from '../ui/text'
import { THEME } from '../ui/theme'
import { strickenLabel } from './car-incident'
import { DEPTH } from './depth'
import type { RenderCar } from './interpolate'

// The word over a car that is wedged (F-207, F-510): WEDGED, over a car that can still get itself out by reversing; gone
// when it has. Nothing is written over a rolled, bogged or marshalled car (the owner, M5 live test). The words are
// `strickenLabel`'s (car-incident.ts).

/** How far above the car's centre the bottom of the tag sits, in screen pixels: clear of the car at any heading. */
const ABOVE_PX = 34
/** Space between the words and the edge of the plate behind them. */
const PAD_PX = 6
/** The plate behind the words: the game's darkest ink (art-direction.md), mostly opaque, so the tag reads on grass. */
const PLATE_COLOR = THEME.colours.background
const PLATE_ALPHA = 0.8

interface Tag {
  plate: Phaser.GameObjects.Rectangle
  words: Phaser.GameObjects.BitmapText
  shown: string | null
}

/**
 * One small label per car that is given one, in the game's pixel font on a dark plate, drawn above the car and
 * moving with it. Hidden while the car needs no words.
 */
export class StrickenTag {
  private readonly tags = new Map<number, Tag>()

  /**
   * `cars` are the ids of the cars that get a tag: the player's, until other cars need telling apart. `canReverse` is
   * the session's reverse setting: with it off a wedged car is its marshal's, and has no tag.
   */
  constructor(
    scene: Phaser.Scene,
    private readonly view: WorldView,
    cars: readonly number[],
    private readonly canReverse: boolean,
  ) {
    for (const id of cars) {
      const plate = scene.add
        .rectangle(0, 0, 1, 1, PLATE_COLOR, PLATE_ALPHA)
        .setOrigin(0.5, 1)
        .setDepth(DEPTH.hud - 2)
        .setVisible(false)
      const words = text(scene, { x: 0, y: 0 }, '', 'small')
        .setOrigin(0.5, 1)
        .setTint(THEME.colours.accent)
        .setDepth(DEPTH.hud - 1)
        .setVisible(false)
      this.tags.set(id, { plate, words, shown: null })
    }
  }

  /**
   * Shows or hides each tag by its car's state, and keeps a shown one over its car. `now` are the sim's latest car
   * snapshots, for why the car is stricken.
   */
  update(cars: readonly RenderCar[], now: readonly CarSnapshot[]): void {
    for (const car of cars) {
      const tag = this.tags.get(car.id)
      if (tag === undefined) continue
      const label = strickenLabel(car.state, now[car.id]?.strickenCause ?? null, this.canReverse)
      if (label !== tag.shown) {
        tag.shown = label
        tag.words.setText(label ?? '').setVisible(label !== null)
        tag.plate.setVisible(label !== null)
        if (label !== null) tag.plate.setSize(tag.words.width + 2 * PAD_PX, tag.words.height + 2 * PAD_PX)
      }
      if (label === null) continue
      const x = Math.round(this.view.originX + car.x * this.view.pxPerM)
      const y = Math.round(this.view.originY + car.y * this.view.pxPerM) - ABOVE_PX
      tag.words.setPosition(x, y - PAD_PX)
      tag.plate.setPosition(x, y)
    }
  }

  destroy(): void {
    for (const { plate, words } of this.tags.values()) {
      plate.destroy()
      words.destroy()
    }
    this.tags.clear()
  }
}
