import { settleForecast, type CarClassId, type CarsPerRace, type Difficulty, type Direction, type DriverId, type SessionKind, type SessionResult, type SettledForecast, type WeatherPlan } from '@sim'
import type { SaveData } from '../persistence/storage'

// The rules of the two top-10 tables (F-406): which results qualify, where they rank, how a board takes an entry and
// how a stored board is cleaned. Pure and view-side, with no engine and no storage: the sim knows nothing of them.
// Only types are imported from the persistence module, which in turn uses the cleaning functions of this one.

/** How many entries a board holds. */
export const BOARD_SIZE = 10
/** The most characters of initials. */
export const INITIALS_MAX = 6
/** The round lengths a race board exists for, in minutes. A session of any other length feeds the fastest-lap board only. */
export const RACE_MINUTES: readonly (3 | 5 | 7)[] = [3, 5, 7]

/** The weather a record was set under (F-818): the forecast the session was raced under, which is never `surprise`: a race day set to SURPRISE records the forecast it settled to. */
export type Weather = SettledForecast
/** The three conditions, driest first. Each keeps its own top ten on a board. */
export const WEATHERS: readonly Weather[] = ['dry', 'changeable', 'wet']
/** What an entry that has no weather (a save made before F-818) reads as. */
export const DEFAULT_WEATHER: Weather = 'dry'
/** What the leaderboard screen's WEATHER row shows: every condition, or one. */
export type WeatherFilter = 'all' | Weather

/** The forecast a session was raced under: its plan's own, or for the plan of a debug session still set to `surprise`, the one the seed settles to. */
export const weatherOf = (plan: Pick<WeatherPlan, 'forecast'>, seed: number): Weather => settleForecast(plan.forecast, seed)

/** The fields both kinds of entry share. */
interface BoardEntryBase {
  /** 1..6 characters from A-Z and 0-9. */
  initials: string
  /** When it was set, as `Date.toISOString()`: shown, never used for ranking. */
  dateISO: string
  /** The size of the field it was set against. */
  cars: CarsPerRace
  difficulty: Difficulty
  /**
   * The forecast the session was raced under (F-818). An entry saved before it has none and reads `dry`; the old `wet`
   * mark such an entry may carry is dropped when the save is read, and nothing reads it.
   */
  weather: Weather
  /**
   * Set with DRIVING ASSISTANCE on (F-811): shown with (A*) after the time. Written only when true; absent on every
   * entry set with it off and on every entry of a save made before it. It does not change the ranking.
   */
  assisted?: boolean
}

/** A fastest-lap entry: ranked lowest `lapMs` first. */
export interface LapEntry extends BoardEntryBase {
  lapMs: number
}

/** A best-race entry: ranked most `laps` first, then lowest `timeMs`. */
export interface RaceEntry extends BoardEntryBase {
  laps: number
  timeMs: number
}

/** The boards as the save holds them: lap boards by `lapKey`, race boards by `raceKey`. */
export type Boards = SaveData['leaderboards']

/** The key of a fastest-lap board: one per track, direction and class. */
export const lapKey = (trackId: string, direction: Direction, carClass: CarClassId): string => `${trackId}/${direction}/${carClass}`

/** The key of a best-race board: the lap key and the round length. */
export const raceKey = (trackId: string, direction: Direction, carClass: CarClassId, minutes: 3 | 5 | 7): string => `${lapKey(trackId, direction, carClass)}/${minutes}`

/** Whether a number of minutes is a round length that has a race board. */
export const isRaceMinutes = (minutes: number): minutes is 3 | 5 | 7 => RACE_MINUTES.some((one) => one === minutes)

// ── Ranking ─────────────────────────────────────────────────────────────────────────────────────────────────────

/** Whether lap `a` stands ahead of or level with lap `b`. */
const lapNotBehind = (a: Pick<LapEntry, 'lapMs'>, b: Pick<LapEntry, 'lapMs'>): boolean => a.lapMs <= b.lapMs
/** Whether race `a` stands ahead of or level with race `b`: more laps, or the same laps in no more time. */
const raceNotBehind = (a: Pick<RaceEntry, 'laps' | 'timeMs'>, b: Pick<RaceEntry, 'laps' | 'timeMs'>): boolean => a.laps > b.laps || (a.laps === b.laps && a.timeMs <= b.timeMs)

/** Lowest lap time first. */
export const compareLap = (a: LapEntry, b: LapEntry): number => a.lapMs - b.lapMs
/** Most laps first, then lowest race time. */
export const compareRace = (a: RaceEntry, b: RaceEntry): number => b.laps - a.laps || a.timeMs - b.timeMs

const isTime = (value: unknown): value is number => typeof value === 'number' && Number.isFinite(value) && value > 0

/**
 * The 1-based rank a lap of `lapMs` would take among the entries of its own `weather` on `board` (each condition has a
 * top ten of its own, F-818), or null if it does not make that top 10. A lap level with an entry already there ranks
 * below it: the earlier entry stays ahead.
 */
export function lapRank(board: readonly LapEntry[], lapMs: number, weather: Weather): number | null {
  if (!isTime(lapMs)) return null
  const ahead = board.filter((entry) => entry.weather === weather && lapNotBehind(entry, { lapMs })).length
  return ahead < BOARD_SIZE ? ahead + 1 : null
}

/** The 1-based rank a race of `laps` laps in `timeMs` would take among the entries of its own `weather` on `board`, or null if it does not make that top 10. Ties stay behind the earlier entry. */
export function raceRank(board: readonly RaceEntry[], laps: number, timeMs: number, weather: Weather): number | null {
  if (!Number.isInteger(laps) || laps < 1 || !isTime(timeMs)) return null
  const ahead = board.filter((entry) => entry.weather === weather && raceNotBehind(entry, { laps, timeMs })).length
  return ahead < BOARD_SIZE ? ahead + 1 : null
}

/** `ranked` (best first) with only the ten best of each condition kept: a wet lap is never pushed out by dry ones. */
function tenPerCondition<T extends { weather: Weather }>(ranked: readonly T[]): T[] {
  const kept: Record<Weather, number> = { dry: 0, changeable: 0, wet: 0 }
  return ranked.filter((entry) => kept[entry.weather]++ < BOARD_SIZE)
}

/** The board with `entry` in its place, cut to the ten best of each condition. The board it was given is not changed. */
export function insertLap(board: readonly LapEntry[], entry: LapEntry): LapEntry[] {
  return tenPerCondition([...board, entry].sort(compareLap))
}

/** The board with `entry` in its place, cut to the ten best of each condition. The board it was given is not changed. */
export function insertRace(board: readonly RaceEntry[], entry: RaceEntry): RaceEntry[] {
  return tenPerCondition([...board, entry].sort(compareRace))
}

/** The ten places the leaderboard screen shows for a stored (ranked) board: the ten best of every condition under ALL, or the ten best of the one chosen. */
export function visibleEntries<T extends { weather: Weather }>(board: readonly T[], filter: WeatherFilter): T[] {
  return board.filter((entry) => filter === 'all' || entry.weather === filter).slice(0, BOARD_SIZE)
}

// ── Cleaning what was stored ────────────────────────────────────────────────────────────────────────────────────

const INITIALS_SHAPE = new RegExp(`^[A-Z0-9]{1,${INITIALS_MAX}}$`)

/** Initials as they may be stored: one to six letters and digits, upper case. */
export const isInitials = (value: unknown): value is string => typeof value === 'string' && INITIALS_SHAPE.test(value)

const FIELD_SIZES: readonly unknown[] = [2, 4, 7]
const DIFFICULTIES: readonly unknown[] = ['club', 'regional', 'national']

const isWeather = (value: unknown): value is Weather => WEATHERS.some((one) => one === value)

function isBase(value: unknown): value is Record<string, unknown> {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return false
  const entry = value as Record<string, unknown>
  const assisted = entry['assisted']
  return (
    isInitials(entry['initials']) &&
    typeof entry['dateISO'] === 'string' &&
    FIELD_SIZES.includes(entry['cars']) &&
    DIFFICULTIES.includes(entry['difficulty']) &&
    isWeather(entry['weather']) &&
    (assisted === undefined || typeof assisted === 'boolean')
  )
}

/** Whether something read from storage is a lap entry. */
export const isLapEntry = (value: unknown): value is LapEntry => isBase(value) && isTime(value['lapMs'])
/** Whether something read from storage is a race entry. */
export const isRaceEntry = (value: unknown): value is RaceEntry => isBase(value) && typeof value['laps'] === 'number' && Number.isInteger(value['laps']) && value['laps'] >= 1 && isTime(value['timeMs'])

/**
 * An entry as the current save holds it (F-818): one stored without a `weather` (before it) reads `dry`, and the old
 * `wet` mark is dropped. Anything that is not an object is left as it is, for the validity check to turn away.
 */
function current(raw: unknown): unknown {
  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) return raw
  const entry = { ...(raw as Record<string, unknown>) }
  delete entry['wet']
  return entry['weather'] === undefined ? { ...entry, weather: DEFAULT_WEATHER } : entry
}

/**
 * What a stored board holds: the entries that are valid, in rank order (entries that tie keep the order they were
 * stored in), the ten best of each condition. Anything that is not an array is an empty board. It never throws.
 */
export function sanitiseBoard<T extends { weather: Weather }>(raw: unknown, isValid: (entry: unknown) => entry is T, compare: (a: T, b: T) => number): T[] {
  if (!Array.isArray(raw)) return []
  return tenPerCondition((raw as unknown[]).map(current).filter(isValid).sort(compare))
}

/** The stored tables of one kind, each cleaned; a table left with nothing is dropped. */
export function sanitiseTables<T extends { weather: Weather }>(raw: unknown, isValid: (entry: unknown) => entry is T, compare: (a: T, b: T) => number): Record<string, T[]> {
  const tables: Record<string, T[]> = {}
  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) return tables
  for (const [key, board] of Object.entries(raw)) {
    const clean = sanitiseBoard(board, isValid, compare)
    if (clean.length > 0) tables[key] = clean
  }
  return tables
}

// ── What a finished session offers ──────────────────────────────────────────────────────────────────────────────

/** What, if anything, a finished session offers the boards: the result and the rank each board would give it. */
export interface Offer {
  lap: { key: string; lapMs: number; rank: number } | null
  race: { key: string; laps: number; timeMs: number; rank: number } | null
}

export const NO_OFFER: Offer = Object.freeze({ lap: null, race: null })

/** Whether anything is on offer. */
export const isOffered = (offer: Offer): boolean => offer.lap !== null || offer.race !== null

export interface OfferArgs {
  result: SessionResult
  /** The driver the person at the keyboard is. */
  playerId: DriverId
  kind: SessionKind
  trackId: string
  direction: Direction
  carClass: CarClassId
  /** The session's length. Only 3, 5 and 7 have a race board; any other length offers the fastest lap alone. */
  minutes: number
  /** The forecast the session was raced under: the result ranks among the entries of that condition alone (F-818). */
  weather: Weather
  /** What the session was driven with: the autopilot or the tuning panel make it count for nothing. */
  flags: { autopilot: boolean; tuned: boolean }
  boards: Boards
}

/**
 * What a finished session offers the boards. Only the player's own result counts, only if they finished it, and not
 * in practice, nor in a session the autopilot drove or the tuning panel changed. The fastest lap comes from a
 * qualifying heat, a final or a quick race; the best race from a final in one of the three round lengths.
 */
export function offerFor(args: OfferArgs): Offer {
  const { result, playerId, kind, trackId, direction, carClass, minutes, weather, flags, boards } = args
  if (kind === 'practice' || flags.autopilot || flags.tuned) return NO_OFFER
  const row = result.rows.find((one) => one.driverId === playerId)
  if (row === undefined || !row.finished) return NO_OFFER

  const lapMs = row.bestLapMs
  const lapAt = lapKey(trackId, direction, carClass)
  const lapPlace = lapMs === null ? null : lapRank(boards.lap[lapAt] ?? [], lapMs, weather)

  let race: Offer['race'] = null
  if (kind === 'final' && isRaceMinutes(minutes)) {
    const raceAt = raceKey(trackId, direction, carClass, minutes)
    const racePlace = raceRank(boards.race[raceAt] ?? [], row.laps, row.timeMs, weather)
    if (racePlace !== null) race = { key: raceAt, laps: row.laps, timeMs: row.timeMs, rank: racePlace }
  }
  return { lap: lapMs !== null && lapPlace !== null ? { key: lapAt, lapMs, rank: lapPlace } : null, race }
}

// ── Writing an entry ────────────────────────────────────────────────────────────────────────────────────────────

/** Which boards a session's result belongs to: the track, direction and class it was run on, and its length in minutes. */
export interface BoardWhere {
  trackId: string
  direction: Direction
  carClass: CarClassId
  minutes: number
}

/** What the game layer knows of the session that the offer does not carry. */
export interface EntryInfo {
  cars: CarsPerRace
  difficulty: Difficulty
  /** The forecast the session was raced under (F-818). */
  weather: Weather
  /** The session was driven with DRIVING ASSISTANCE (F-811): the entries are written with the mark. Left out, it was not. */
  assisted?: boolean
}

/** The field size a board shows for a session with `entries` cars: the smallest size the game offers that holds them (a debug session of an odd size is shown as the next one up). */
export function carsOf(entries: number): CarsPerRace {
  return entries <= 2 ? 2 : entries <= 4 ? 4 : 7
}

/**
 * The boards with the offered results written under `initials`, one entry for each board on offer, both with the same
 * initials and date. The boards it was given are not changed.
 */
export function withOffer(boards: Boards, offer: Offer, info: EntryInfo, initials: string, dateISO: string): Boards {
  const { assisted, ...rest } = info
  const base = { initials, dateISO, ...rest, ...(assisted === true ? { assisted: true } : {}) }
  return {
    lap: offer.lap === null ? boards.lap : { ...boards.lap, [offer.lap.key]: insertLap(boards.lap[offer.lap.key] ?? [], { ...base, lapMs: offer.lap.lapMs }) },
    race: offer.race === null ? boards.race : { ...boards.race, [offer.race.key]: insertRace(boards.race[offer.race.key] ?? [], { ...base, laps: offer.race.laps, timeMs: offer.race.timeMs }) },
  }
}
