import type Phaser from 'phaser'
import { mixerOf } from '..'
import { saves } from '../../persistence'
import { MusicPlayer } from './MusicPlayer'

export { MusicPlayer, type MusicPlayerOptions, type Timers } from './MusicPlayer'
export { PIECES, PIECE_IDS } from './pieces'
export { loopSeconds, notesInWindow, type Piece, type PieceId } from './sequence'

/** The registry key the music player is kept under, next to the mixer's. */
export const MUSIC_KEY = 'audio-music'

/**
 * The game's music player (made the first time a scene asks, on the mixer the boot scene made, and set from the saved
 * `music` setting), or null in a game that was started without a mixer.
 */
export function musicOf(registry: Phaser.Data.DataManager): MusicPlayer | null {
  const existing: unknown = registry.get(MUSIC_KEY)
  if (existing instanceof MusicPlayer) return existing
  const mixer = mixerOf(registry)
  if (mixer === null) return null
  const player = new MusicPlayer(mixer, { enabled: saves.read().settings.music })
  registry.set(MUSIC_KEY, player)
  return player
}

/** Turns the music on or off and remembers it (`SaveData.settings.music`). Returns the new state; false when there is no player. */
export function setMusic(registry: Phaser.Data.DataManager, on: boolean): boolean {
  const player = musicOf(registry)
  if (player === null) return false
  saves.update((data) => (data.settings.music === on ? data : { ...data, settings: { ...data.settings, music: on } }))
  player.setEnabled(on)
  return on
}

/** The music key (M): flips the setting. Returns the new state. */
export function toggleMusic(registry: Phaser.Data.DataManager): boolean {
  const player = musicOf(registry)
  return player === null ? false : setMusic(registry, !player.enabled)
}
