import Phaser from 'phaser'
import { AudioMixer, MIXER_KEY, mixerOf, zzfxBackend } from '../audio'
import { manifestOf, MANIFEST_KEY, MANIFEST_URL, queueAssets, registerFonts } from '../assets/manifest'
import { ttsOf } from '../audio/Tts'
import { saves, speechOn } from '../persistence'
import { KEYBOARD_REQUIRED, needsKeyboardNotice, readInputEnvironment } from '../lifecycle/failure'
import { failOnLoadError, hasFailed } from '../lifecycle/report'
import { LoadingBar } from '../ui/LoadingBar'
import { LOGICAL_HEIGHT, LOGICAL_WIDTH } from '../config'

/** How much of the bar the manifest takes: it is one small file, and the fonts and the skin are the rest. */
const MANIFEST_SHARE = 0.1

/**
 * Makes the game's mixer (F-704) and arms its unlock on the first key press, loads the asset manifest, then the pixel
 * font, and hands over to the title. Nothing else is loaded here: a car's
 * atlas is fetched when the garage first shows its class or a session starts (ADR-005), so the title is up as soon
 * as the font is. While it loads there is a progress bar (F-803), made of rectangles because there is no font yet; a
 * file that does not arrive puts the error screen up (`failOnLoadError`) instead of a blank page; and a device whose
 * primary pointer is a finger (F-908) is told that a keyboard is needed before the title.
 */
export class BootScene extends Phaser.Scene {
  constructor() {
    super('Boot')
  }

  /** The progress bar; null before `preload` and after the scene has gone. The debug hook reads it. */
  private bar: LoadingBar | null = null
  /** What share of the bar the loader's own progress, 0..1, maps onto: the manifest first, then the fonts and the skin. */
  private stage = { from: 0, to: MANIFEST_SHARE }

  /** How full the bar is, 0..1; null when there is none. */
  progress(): number | null {
    return this.bar?.progress ?? null
  }

  preload(): void {
    failOnLoadError(this)
    this.bar = new LoadingBar(this, { x: LOGICAL_WIDTH / 2, y: LOGICAL_HEIGHT / 2 })
    this.load.on(Phaser.Loader.Events.PROGRESS, (share: number) => this.bar?.set(this.stage.from + share * (this.stage.to - this.stage.from)))
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => {
      this.bar?.destroy()
      this.bar = null
    })
    this.load.json(MANIFEST_KEY, MANIFEST_URL)
  }

  create(): void {
    if (hasFailed(this.game)) return
    this.mountAudio()
    // With voice on in the save, the browser is asked for its voices now, while the title is up: Chrome loads them only
    // when first asked, and a list asked for at the first line comes too late for it (F-816).
    if (speechOn()) ttsOf(this.registry, () => mixerOf(this.registry)?.voiceVolume() ?? 1).prepare()
    const manifest = manifestOf(this)
    const start = (): void => {
      if (hasFailed(this.game)) return
      registerFonts(this, manifest)
      if (needsKeyboardNotice(readInputEnvironment((query) => window.matchMedia(query)))) this.scene.start('Error', KEYBOARD_REQUIRED)
      else this.scene.start('Title')
    }
    this.stage = { from: MANIFEST_SHARE, to: 1 }
    this.bar?.set(MANIFEST_SHARE)
    if (queueAssets(this, manifest, 'fonts') === 0) {
      start()
      return
    }
    this.load.once(Phaser.Loader.Events.COMPLETE, start)
    this.load.start()
  }

  /**
   * The mixer lives for the game, in the registry. Its context is suspended until a key press (the browsers' autoplay rule),
   * so the game is silent until then. A plain DOM listener, not a Phaser key event (AGENTS.md, rule 2): it waits for no
   * particular key, and keeps asking on each press until the context is running, because a browser may not count the
   * first (Escape, in Chrome).
   */
  private mountAudio(): void {
    if (mixerOf(this.registry) !== null) return
    const mixer = new AudioMixer(zzfxBackend())
    mixer.setVolumes(saves.read().settings.volume)
    this.registry.set(MIXER_KEY, mixer)
    const unlock = (): void => {
      if (mixer.ctx.state === 'running') {
        window.removeEventListener('keydown', unlock, true)
        return
      }
      void mixer.unlock()
    }
    window.addEventListener('keydown', unlock, true)
  }
}
