import type Phaser from 'phaser'
import type { Vec2 } from '@sim'
import type { NavKey, TextKey } from '../input/keys'
import { ButtonRow, type ButtonSpec } from './ButtonRow'
import { FocusRing } from './focus'
import { Selector, type SelectorOptions } from './Selector'
import { TextField, type TextFieldOptions } from './TextField'
import type { TextSize } from './theme'

/** What a form needs of each of its rows. */
interface FormRow {
  readonly heightPx: number
  setFocused(focused: boolean): void
  handle(key: NavKey): boolean
  /** Set on a row that takes typed text while it is being typed in: it then has every key. */
  readonly editing?: boolean
  type?(key: TextKey): void
  destroy(): void
}

export interface FormOptions {
  size?: TextSize
  /** Logical pixels between the tops of two rows. */
  pitch?: number
}

/**
 * A vertical stack of selectors and button rows that share one focus ring: up and down move between rows, left and
 * right act inside the focused row, Enter presses the focused button. Rows are added top to bottom.
 */
export class Form {
  private readonly rows: Array<{ id: string; row: FormRow }> = []
  private readonly ring = new FocusRing([])
  private y: number

  constructor(
    private readonly scene: Phaser.Scene,
    private readonly pos: Vec2,
    private readonly opts: FormOptions = {},
  ) {
    this.y = pos.y
  }

  /** Adds a selector under the rows so far. */
  addSelector<T>(
    id: string,
    label: string,
    options: ReadonlyArray<{ value: T; label: string }>,
    initial: T,
    opts: Omit<SelectorOptions, 'size'> = {},
  ): Selector<T> {
    const selector = new Selector(this.scene, { x: this.pos.x, y: this.y }, label, options, initial, { size: this.opts.size ?? 'body', ...opts })
    this.push(id, selector)
    return selector
  }

  /** Adds a text field (a name) under the rows so far. */
  addTextField(id: string, label: string, value: string | null, opts: Omit<TextFieldOptions, 'size'>): TextField {
    const field = new TextField(this.scene, { x: this.pos.x, y: this.y }, label, value, { size: this.opts.size ?? 'body', ...opts })
    this.push(id, field)
    return field
  }

  /** Adds a row of buttons under the rows so far, `gap` logical pixels lower than the pitch would put it. */
  addButtons(id: string, buttons: readonly ButtonSpec[], gap = 0): ButtonRow {
    this.y += gap
    const row = new ButtonRow(this.scene, { x: this.pos.x, y: this.y }, buttons, this.opts.size ?? 'body')
    this.push(id, row)
    return row
  }

  /** The id of the focused row: the id given to the selector or the button row. */
  get focus(): string | null {
    return this.ring.current
  }

  /** Whether a row is being typed in: the keys, the arrows and Esc included, are then that row's, and the scene must not use them. */
  get editing(): boolean {
    return this.rows.some((entry) => entry.row.editing === true)
  }

  /** A typed character or Backspace, for the row being typed in. */
  type(key: TextKey): void {
    this.rows.find((entry) => entry.row.editing === true)?.row.type?.(key)
  }

  /** Acts on a menu key; true if the form used it. */
  handle(key: NavKey): boolean {
    const typing = this.rows.find((entry) => entry.row.editing === true)
    if (typing !== undefined) return typing.row.handle(key)
    if (key === 'up' || key === 'down') {
      this.ring.move(key === 'down' ? 1 : -1)
      this.paint()
      return true
    }
    const focused = this.rows.find((entry) => entry.id === this.ring.current)
    return focused?.row.handle(key) ?? false
  }

  private push(id: string, row: FormRow): void {
    this.rows.push({ id, row })
    this.y += this.opts.pitch ?? Math.round(row.heightPx * 1.7)
    this.ring.update(this.rows.map((entry) => ({ id: entry.id, enabled: true })))
    this.paint()
  }

  private paint(): void {
    const current = this.ring.current
    for (const entry of this.rows) entry.row.setFocused(entry.id === current)
  }

  destroy(): void {
    for (const entry of this.rows) entry.row.destroy()
    this.rows.length = 0
  }
}
