import Phaser from 'phaser'
import type { CarClassId, Direction } from '@sim'
import { CLASS_ORDER } from '@content/classes'
import { tracks } from '@content/tracks'
import { LOGICAL_HEIGHT, LOGICAL_WIDTH } from '../config'
import { onNav, type NavKey } from '../input/keys'
import {
  BOARD_WORDS,
  CLASS_WORDS,
  DIRECTION_WORDS,
  FOOTNOTE_H,
  LABEL_CHARS,
  LEADERBOARD_HEADING,
  LEADERBOARD_HINT_BROWSE,
  LEADERBOARD_HINT_FLOW,
  LEFT_PANEL,
  MARGIN,
  RACE_MINUTES,
  RIGHT_PANEL,
  ROW_PITCH,
  VALUE_CHARS,
  WEATHERS,
  WEATHER_WORDS,
  boardTitle,
  columnsFor,
  footnoteFor,
  lapKey,
  lapRows,
  raceKey,
  raceRows,
  visibleEntries,
  type BoardKind,
  type Weather,
  type WeatherFilter,
} from '../leaderboard'
import { saves } from '../persistence'
import { selection } from '../state/selection'
import { Form, Panel, Table, THEME, lineHeight, setTextIfChanged, text, type HasReadout, type ScreenReadout } from '../ui'

type Minutes = 3 | 5 | 7

/** What the screen shows: one board of the ten there are for each track, direction and class (and, for a race, round length), of every condition or one (F-818). */
interface Choice {
  board: BoardKind
  trackId: string
  direction: Direction
  carClass: CarClassId
  minutes: Minutes
  weather: WeatherFilter
}

/** The row of a board to point out: its place, counted from 0, among the entries of `weather` on the board with this key. It is pointed out only while the WEATHER row shows that condition. */
interface Marked {
  key: string
  index: number
  weather: Weather
}

/** What starts the leaderboards screen. */
export interface LeaderboardInit {
  /** The board to open on; left out, the one last looked at (the first time: fastest lap, home track, counter-clockwise, the garage's class, 5 minutes). */
  open?: Choice
  /** The rows to point out, on the lap board and on the race board, when the screen opens on a result just set. */
  highlight?: { lap?: Marked; race?: Marked }
  /** What leaving does: the screen the player was going to; left out, the title. */
  onClose?: () => void
}

/** Kept while the page is open, so that the boards are looked at as they were left. */
let chosen: Choice | null = null

/** The rows of the form, top to bottom; the round length is there for the best-race board only. */
type RowId = 'track' | 'direction' | 'class' | 'board' | 'minutes' | 'weather'

/**
 * The two top-10 tables (F-406), reached from the title and, after a result has been entered, on their own: the
 * track, direction, class, board, (for races) round length and weather are chosen with the arrow keys, and the table shows up
 * to ten rows with places nobody holds left blank. A result just entered has its row highlighted. Enter or Esc leaves.
 */
export class LeaderboardScene extends Phaser.Scene implements HasReadout {
  private parts: Phaser.GameObjects.GameObject[] = []
  private left: Panel | null = null
  private right: Panel | null = null
  private form: Form | null = null
  private table: Table | null = null
  /** What the table was built for: the board kind and its columns' widths. A board whose rows need wider columns gets a new table. */
  private tableShape: string | null = null
  private caption: Phaser.GameObjects.BitmapText | null = null
  /** Under the table, in the hints' style: what (A*) means; blank on a board with no assisted row (F-815). */
  private footnote: Phaser.GameObjects.BitmapText | null = null
  private rowIds: RowId[] = []
  private release: (() => void) | null = null
  private request: LeaderboardInit = {}
  /** The board changed, so the form (which has the round length for a race only) is built again once the key has been handled. */
  private rebuild = false
  private handled = 0
  /** What the table shows now, for the readout. */
  private shown: { rows: number; initials: string[]; highlight: number } = { rows: 0, initials: [], highlight: -1 }

  constructor() {
    super('Leaderboard')
  }

  init(data: LeaderboardInit | undefined): void {
    this.request = data ?? {}
    this.handled = 0
    this.rebuild = false
    this.tableShape = null
    this.shown = { rows: 0, initials: [], highlight: -1 }
    chosen = this.request.open ?? chosen ?? { board: 'lap', trackId: Object.keys(tracks)[0] ?? '', direction: 'counter-clockwise', carClass: selection.get().carClass, minutes: 5, weather: 'all' }
  }

  create(): void {
    this.cameras.main.setBackgroundColor(THEME.colours.background)
    const flow = this.request.onClose !== undefined
    this.parts.push(text(this, { x: MARGIN, y: 48 }, LEADERBOARD_HEADING, 'large').setTint(THEME.colours.accent))
    this.parts.push(text(this, { x: MARGIN, y: 116 }, 'THE TEN BEST OF EACH BOARD', 'small').setTint(THEME.colours.textDim))
    this.parts.push(text(this, { x: LOGICAL_WIDTH / 2, y: LOGICAL_HEIGHT - 64 }, flow ? LEADERBOARD_HINT_FLOW : LEADERBOARD_HINT_BROWSE, 'small').setOrigin(0.5, 0).setTint(THEME.colours.textDim))
    this.left = new Panel(this, LEFT_PANEL, { title: 'BOARD' })
    this.right = new Panel(this, RIGHT_PANEL, { title: 'TOP 10' })
    this.caption = text(this, { x: this.right.inner.x, y: this.right.inner.y }, '', 'small').setTint(THEME.colours.textDim)
    this.parts.push(this.caption)
    this.footnote = text(this, { x: this.right.inner.x, y: this.right.inner.y + this.right.inner.h - lineHeight('small') }, '', 'small').setTint(THEME.colours.textDim)
    this.parts.push(this.footnote)
    this.buildForm(null)
    this.refresh()
    this.release = onNav(this, (key) => this.onKey(key))
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, this.dispose, this)
  }

  readout(): ScreenReadout {
    const current = chosen
    return {
      focus: this.form?.focus ?? null,
      values: {
        handled: this.handled,
        board: current?.board ?? '',
        track: current?.trackId ?? '',
        direction: current?.direction ?? '',
        class: current?.carClass ?? '',
        minutes: current?.board === 'race' ? current.minutes : 0,
        weather: current?.weather ?? '',
        selectors: this.rowIds.join(','),
        rows: this.shown.rows,
        filled: this.shown.initials.length,
        initials: this.shown.initials.join(','),
        highlight: this.shown.highlight,
        title: this.caption?.text ?? '',
        footnote: this.footnote?.text ?? '',
        tableShape: this.tableShape ?? '',
      },
    }
  }

  /** Builds the form from the current choice; `focus` is the row that had focus, which gets it back. */
  private buildForm(focus: string | null): void {
    this.form?.destroy()
    const { left } = this
    if (left === null || chosen === null) return
    const form = new Form(this, { x: left.inner.x, y: left.inner.y }, { size: 'body', pitch: ROW_PITCH })
    const ids: RowId[] = []
    const add = <T>(id: RowId, label: string, options: ReadonlyArray<{ value: T; label: string }>, value: T, change: (next: T) => void): void => {
      form.addSelector(id, label, options, value, { labelChars: LABEL_CHARS, valueChars: VALUE_CHARS }).onChange((next) => {
        change(next)
        if (id === 'board') this.rebuild = true
        this.refresh()
      })
      ids.push(id)
    }
    const update = (change: Partial<Choice>): void => {
      chosen = { ...(chosen as Choice), ...change }
    }

    add<string>('track', 'TRACK', Object.values(tracks).map((track) => ({ value: track.id, label: track.name.toUpperCase() })), chosen.trackId, (trackId) => update({ trackId }))
    add<Direction>('direction', 'DIRECTION', (['counter-clockwise', 'clockwise'] as const).map((value) => ({ value, label: DIRECTION_WORDS[value] })), chosen.direction, (direction) => update({ direction }))
    add<CarClassId>('class', 'CLASS', CLASS_ORDER.map((value) => ({ value, label: CLASS_WORDS[value] })), chosen.carClass, (carClass) => update({ carClass }))
    add<BoardKind>('board', 'BOARD', (['lap', 'race'] as const).map((value) => ({ value, label: BOARD_WORDS[value] })), chosen.board, (board) => update({ board }))
    if (chosen.board === 'race') add<Minutes>('minutes', 'LENGTH', RACE_MINUTES.map((value) => ({ value, label: `${value} MIN` })), chosen.minutes, (minutes) => update({ minutes }))
    add<WeatherFilter>('weather', 'WEATHER', (['all', ...WEATHERS] as const).map((value) => ({ value, label: WEATHER_WORDS[value] })), chosen.weather, (weather) => update({ weather }))
    this.form = form
    this.rowIds = ids

    const at = focus === null ? 0 : Math.max(0, (ids as readonly string[]).indexOf(focus))
    for (let i = 0; i < at; i++) form.handle('down')
  }

  /** Draws the table for the current choice: the ten places of its board, the highlighted one marked. */
  private refresh(): void {
    const { right, caption } = this
    const current = chosen
    if (right === null || caption === null || current === null) return
    const boards = saves.read().leaderboards
    const key = current.board === 'lap' ? lapKey(current.trackId, current.direction, current.carClass) : raceKey(current.trackId, current.direction, current.carClass, current.minutes)
    // The ten best of the condition chosen, or of every condition under ALL (F-818).
    const lap = visibleEntries(boards.lap[key] ?? [], current.weather)
    const race = visibleEntries(boards.race[key] ?? [], current.weather)
    const entries = current.board === 'lap' ? lap : race
    const rows = current.board === 'lap' ? lapRows(lap) : raceRows(race)

    // A row set with DRIVING ASSISTANCE has (A*) after its time (F-811, F-815): its board's result column is wider, and the table stays at the body size (the panel is laid out for the widest row, `layout.ts`).
    const columns = columnsFor(current.board, rows)
    const rect = { x: right.inner.x, y: right.inner.y + lineHeight('small') + 24, w: right.inner.w, h: right.inner.h - lineHeight('small') - 24 - FOOTNOTE_H }
    const shape = `${current.board}/${columns.map((column) => column.chars).join(',')}`
    let table = this.table
    if (table === null || this.tableShape !== shape) {
      table?.destroy()
      table = new Table(this, rect, columns, 'body')
      this.table = table
      this.tableShape = shape
    }
    const track = tracks[current.trackId]
    setTextIfChanged(caption, boardTitle(current.board, track?.name ?? current.trackId, current.direction, current.carClass, current.minutes, current.weather))

    const marked = this.request.highlight?.[current.board]
    const highlight = marked !== undefined && marked.key === key && marked.weather === current.weather ? marked.index : -1
    table.setRows(rows, highlight >= 0 ? highlight : undefined)
    if (this.footnote !== null) setTextIfChanged(this.footnote, footnoteFor(entries))
    this.shown = { rows: rows.length, initials: entries.map((entry) => entry.initials), highlight }
  }

  private onKey(key: NavKey): void {
    this.handled++
    if (key === 'back' || key === 'confirm') {
      this.leave()
      return
    }
    const focus = this.form?.focus ?? null
    this.form?.handle(key)
    if (this.rebuild) {
      this.rebuild = false
      this.buildForm(focus)
    }
  }

  /** Stops listening at once, so that a second press before the next scene appears does nothing, then goes where the player was going. */
  private leave(): void {
    this.release?.()
    this.release = null
    const { onClose } = this.request
    if (onClose === undefined) this.scene.start('Title')
    else {
      this.scene.stop()
      onClose()
    }
  }

  private dispose(): void {
    this.release?.()
    this.release = null
    this.form?.destroy()
    this.form = null
    this.table?.destroy()
    this.table = null
    this.left?.destroy()
    this.left = null
    this.right?.destroy()
    this.right = null
    for (const part of this.parts) part.destroy()
    this.parts = []
    this.caption = null
    this.footnote = null
    this.rowIds = []
    this.request = {}
  }
}
