const cache = new WeakMap<BaseAudioContext, AudioBuffer>()

/** Seconds of white noise in the shared buffer. Long enough that its loop is not heard as a pattern under a filter. */
const NOISE_SECONDS = 3

/** One buffer of white noise per context, shared by every noise voice (a car's scrub and grass, the rain, the wind). */
export function noiseBuffer(ctx: BaseAudioContext): AudioBuffer {
  let buffer = cache.get(ctx)
  if (buffer === undefined) {
    buffer = ctx.createBuffer(1, Math.round(ctx.sampleRate * NOISE_SECONDS), ctx.sampleRate)
    const data = buffer.getChannelData(0)
    for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1
    cache.set(ctx, buffer)
  }
  return buffer
}

/** A looping noise source, started at a random point of the buffer so that two voices are not the same noise. */
export function startNoise(ctx: BaseAudioContext): AudioBufferSourceNode {
  const source = ctx.createBufferSource()
  source.buffer = noiseBuffer(ctx)
  source.loop = true
  source.start(0, Math.random() * NOISE_SECONDS)
  return source
}
