// The pure half of the music (F-705): a piece is data, and this turns a piece and a window of time into the notes that
// fall in it. No WebAudio, no clock, no randomness: the same piece gives the same notes every time, and Node tests all
// of it. The player (MusicPlayer.ts) only asks "what starts between these two instants?" and hands the answer to oscillators.

/** Sixteenth notes in a bar: every piece is in 4/4 on a sixteenth grid. */
export const STEPS_PER_BAR = 16

/** What a voice sounds like: two tones and filtered noise. */
export type Wave = 'square' | 'triangle' | 'noise'

/** One note on the grid. `midi` is the note number (60 = middle C); noise has no pitch and uses 0. */
export interface NoteEvent {
  /** The sixteenth, counted from the first bar of the loop. */
  step: number
  /** How many sixteenths it lasts. */
  len: number
  midi: number
  /** Loudness of this note against the voice's own level, 0..1. */
  vel: number
}

export interface Voice {
  name: string
  wave: Wave
  /** Peak amplitude of the voice at full velocity, before the music bus. The pieces are balanced by these. */
  gain: number
  /** Where the voice's filter sits: a low-pass for the tones; for noise, `hat` is a high-pass and `snare` a band-pass. */
  filterHz: number
  /** Seconds to rise, and to fall at the end of a note. */
  attackS: number
  releaseS: number
  /** The level a held note settles at after its first moment, against its peak: 1 holds, less plucks. */
  sustain: number
  notes: readonly NoteEvent[]
}

export interface Piece {
  id: PieceId
  bpm: number
  /** Bars in the loop. The last bar leads into the first. */
  bars: number
  /** The piece's level against the music bus: the menus' piece has no motors to sit under and is a little fuller than the session's. */
  level: number
  voices: readonly Voice[]
}

export type PieceId = 'title' | 'session'

/** One note of the answer: when it starts (seconds from the start of the piece, loops included), how long, how high, how loud. */
export interface ScheduledNote {
  voice: number
  startS: number
  durS: number
  freqHz: number
  vel: number
}

/** The length of a sixteenth, seconds. */
export const stepSeconds = (piece: Pick<Piece, 'bpm'>): number => 60 / piece.bpm / 4

/** Sixteenths in one pass of the loop. */
export const loopSteps = (piece: Pick<Piece, 'bars'>): number => piece.bars * STEPS_PER_BAR

/** Seconds in one pass of the loop. */
export const loopSeconds = (piece: Pick<Piece, 'bpm' | 'bars'>): number => loopSteps(piece) * stepSeconds(piece)

/** Equal temperament, A4 = 440 Hz. */
export const midiToHz = (midi: number): number => 440 * 2 ** ((midi - 69) / 12)

/**
 * Every note that starts in `[fromS, toS)`, seconds from the start of the piece (the piece repeats for ever), in the
 * order they start. A note belongs to exactly one window: two windows that meet, one ending where the next begins,
 * hand over every note once, across the seam from the last bar to the first as anywhere else.
 */
export function notesInWindow(piece: Piece, fromS: number, toS: number): ScheduledNote[] {
  const out: ScheduledNote[] = []
  if (!(toS > fromS)) return out
  const step = stepSeconds(piece)
  const length = loopSteps(piece)
  const loopLen = length * step
  const first = Math.max(0, Math.floor(fromS / loopLen) - 1)
  const last = Math.floor(toS / loopLen) + 1
  for (let loop = first; loop <= last; loop++) {
    piece.voices.forEach((voice, v) => {
      for (const note of voice.notes) {
        const startS = (loop * length + note.step) * step
        if (startS >= fromS && startS < toS) out.push({ voice: v, startS, durS: note.len * step, freqHz: voice.wave === 'noise' ? 0 : midiToHz(note.midi), vel: note.vel })
      }
    })
  }
  // Stable: notes that start together keep the voices' order.
  return out.sort((a, b) => a.startS - b.startS)
}
