import type { Sky } from '@sim'
import { COMMENTARY_TUNING } from './tuning'
import { PLACEHOLDERS, type Placeholder } from './vocabulary'

/** What a candidate knows to say. `bio` is the list of facts to draw one from when the line is written. */
export type FillValues = Partial<Record<Exclude<Placeholder, 'bio'>, string>> & { bio?: readonly string[] }

const PLACEHOLDER = /\{(\w+)\}/g

/** A lap or gap time: `12.84`, or `1:02.31` from a minute up. Hundredths are rounded once, from whole milliseconds. */
export function formatTime(ms: number): string {
  const hundredths = Math.round(ms / 10)
  const minutes = Math.floor(hundredths / 6000)
  const rest = hundredths - minutes * 6000
  const seconds = Math.floor(rest / 100)
  const cents = rest % 100
  const tail = String(cents).padStart(2, '0')
  return minutes > 0 ? `${minutes}:${String(seconds).padStart(2, '0')}.${tail}` : `${seconds}.${tail}`
}

const ORDINAL_WORDS = ['first', 'second', 'third', 'fourth', 'fifth', 'sixth', 'seventh'] as const

/** A place, said: `third`; past seven, `11th`. */
export function ordinalWord(place: number): string {
  const word = ORDINAL_WORDS[place - 1]
  if (word !== undefined) return word
  const teen = place % 100 >= 11 && place % 100 <= 13
  return `${place}${teen ? 'th' : (['th', 'st', 'nd', 'rd'][place % 10] ?? 'th')}`
}

export function skyText(sky: Sky): string {
  return sky.replace('-', ' ')
}

/** The placeholder names a text uses, each once, in order. */
export function placeholdersIn(text: string): string[] {
  const found: string[] = []
  for (const match of text.matchAll(PLACEHOLDER)) {
    const name = match[1] ?? ''
    if (!found.includes(name)) found.push(name)
  }
  return found
}

const isKnown = (name: string): name is Placeholder => (PLACEHOLDERS as readonly string[]).includes(name)

/** True when every placeholder of the text has a value (a bio needs at least one fact). */
export function canFill(text: string, values: FillValues): boolean {
  return placeholdersIn(text).every((name) => {
    if (!isKnown(name)) return false
    return name === 'bio' ? (values.bio?.length ?? 0) > 0 : values[name] !== undefined
  })
}

/** The text with its placeholders filled and its first letter capitalised. `pickFact` chooses the bio fact. */
export function fillText(text: string, values: FillValues, pickFact: (facts: readonly string[]) => string): string {
  const filled = text.replace(PLACEHOLDER, (_whole, raw: string) => {
    if (!isKnown(raw)) throw new Error(`fillText: unknown placeholder {${raw}}`)
    if (raw === 'bio') {
      if (values.bio === undefined || values.bio.length === 0) throw new Error('fillText: no value for {bio}')
      return pickFact(values.bio)
    }
    const value = values[raw]
    if (value === undefined) throw new Error(`fillText: no value for {${raw}}`)
    return value
  })
  return filled.charAt(0).toUpperCase() + filled.slice(1)
}

/** How long the line takes to say, s: words over 2.8 a second, and never under a second and a half. */
export function estimateDurationS(text: string): number {
  const words = text.split(/\s+/).filter((word) => word !== '').length
  return Math.max(COMMENTARY_TUNING.minDurationS, words / COMMENTARY_TUNING.wordsPerS)
}
