import { DEFAULT_BINDINGS, keyLabel } from './bindings'

/** The hint for the tuning panel and the racing lines, which the race screen adds once they are unlocked (F-813). */
export const TOOLS_HINT = 'T TUNE   L LINES'

/**
 * The key hints at the bottom right of the race screen, with the pause key named once the player has moved it from P
 * (F-801). The tuning panel and the racing lines (`T TUNE   L LINES`) are in it only when they are unlocked: always in
 * development, test and demo builds, and in the released game from the moment the code has been typed (F-813).
 */
export function keyHint(pauseCode: string, toolsUnlocked: boolean): string {
  const pause = pauseCode === DEFAULT_BINDINGS.pause ? 'ESC' : `ESC OR ${keyLabel(pauseCode)}`
  return `↑ GAS   ↓ BRAKE   ← → STEER   ${pause} PAUSE${toolsUnlocked ? `   ${TOOLS_HINT}` : ''}`
}
