import type { TrackData } from '@sim'
import { cuencaRc, tracks } from '@content/tracks'

// Which track the next race is on (F-804). The registry in src/content/tracks/ is what the game ships; this is what the
// screens ask: the tracks on offer, whether there is any choice to show, and the one chosen. With one track there is no
// selector. The choice is kept while the page is open, and shared by event setup and quick race, so a second race starts
// where the last one did; it is not saved, because a track the player once chose may not be shipped next time.

/** Tracks a test has added to the registry's: never set in play. */
let extra: TrackData[] = []
let chosenId: string | null = null

/** Every track the screens offer: the registry's, in its order, then any a test has added. */
export const availableTracks = (): readonly TrackData[] => [...Object.values(tracks), ...extra]

/** The selector is there only when there is a choice. */
export const showsTrackSelector = (): boolean => availableTracks().length > 1

/** The selector's options: each track's name, in capitals as the screens print it. */
export const trackOptions = (): Array<{ value: string; label: string }> => availableTracks().map((track) => ({ value: track.id, label: track.name.toUpperCase() }))

/** The track the next race is on: the one chosen, or the first when none was chosen or the one chosen is gone. */
export function chosenTrack(): TrackData {
  const all = availableTracks()
  return all.find((track) => track.id === chosenId) ?? all[0] ?? cuencaRc
}

/** Choose a track by id; an id that is not on offer changes nothing. */
export function chooseTrack(id: string): void {
  if (availableTracks().some((track) => track.id === id)) chosenId = id
}

/** For tests and for looking at the selector before a second track ships: put a track beside the registry's, once. */
export function registerTestTrack(track: TrackData): void {
  if (!availableTracks().some((known) => known.id === track.id)) extra = [...extra, track]
}

/** Take back every track `registerTestTrack` added, and the choice. */
export function clearTestTracks(): void {
  extra = []
  chosenId = null
}
