import type { CarClassId, Difficulty, Direction } from '@sim'
import type { TableColumn } from '../ui/layout'
import { ASSISTED_MEANS, markAssisted } from '../race/assistance'
import { formatLapTime } from '../race/PracticeReadout'
import { BOARD_SIZE, type LapEntry, type Offer, type RaceEntry, type Weather, type WeatherFilter } from './boards'

// What the leaderboard screens say: the table's columns and rows, the dates, and the words of the initials screen.
// Pure, so that every character is checked against the pixel font in a test.

export type BoardKind = 'lap' | 'race'

const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'] as const

/** A stored date as `DD MMM YYYY` in the player's own calendar, or blank when it is not a date. */
export function formatDate(dateISO: string): string {
  const date = new Date(dateISO)
  if (Number.isNaN(date.getTime())) return ''
  return `${String(date.getDate()).padStart(2, '0')} ${MONTHS[date.getMonth()] ?? ''} ${date.getFullYear()}`
}

const RANK: TableColumn = { key: 'rank', title: 'RK', chars: 2, align: 'right' }
/** The result column's width: `12 3:01.456`, the most laps and time an entry set with the assistance off can show. */
const RESULT_CHARS = 11
const REST: readonly TableColumn[] = [
  { key: 'name', title: 'NAME', chars: 6, align: 'left' },
  { key: 'result', title: '', chars: RESULT_CHARS, align: 'left' },
  { key: 'date', title: 'DATE', chars: 11, align: 'left' },
  { key: 'cars', title: 'CARS', chars: 4, align: 'right' },
  { key: 'level', title: 'LEVEL', chars: 8, align: 'left' },
  { key: 'weather', title: 'WEATHER', chars: 7, align: 'left' },
]

/**
 * The columns of a board: the result column is titled for what the board ranks, and is as wide as the widest result
 * of `rows` (an entry set with DRIVING ASSISTANCE has (A*) after its time, F-811), never narrower than it always was.
 */
export function columnsFor(kind: BoardKind, rows: ReadonlyArray<Readonly<Record<string, string>>> = []): TableColumn[] {
  const chars = rows.reduce((most, row) => Math.max(most, row['result']?.length ?? 0), RESULT_CHARS)
  return [RANK, ...REST.map((column) => (column.key === 'result' ? { ...column, title: kind === 'lap' ? 'LAP TIME' : 'LAPS / TIME', chars } : column))]
}

/** The line under a table that holds an entry set with DRIVING ASSISTANCE, saying what (A*) means (F-815); blank for a table with none. */
export const footnoteFor = (board: ReadonlyArray<{ readonly assisted?: boolean }>): string => (board.some((entry) => entry.assisted === true) ? ASSISTED_MEANS : '')

/** The WEATHER column's word for each condition: `CHANG` is CHANGEABLE cut to 5 characters, the widest word, so that the column is only as wide as its title (F-818). */
export const WEATHER_CELLS: Readonly<Record<Weather, string>> = { dry: 'DRY', changeable: 'CHANG', wet: 'WET' }
/** The WEATHER row's word for each choice, and the word in the table's title line. */
export const WEATHER_WORDS: Readonly<Record<WeatherFilter, string>> = { all: 'ALL', dry: 'DRY', changeable: 'CHANGEABLE', wet: 'WET' }

const common = (rank: number, entry: LapEntry | RaceEntry): Record<string, string> => ({
  rank: String(rank),
  name: entry.initials,
  date: formatDate(entry.dateISO),
  cars: String(entry.cars),
  level: entry.difficulty.toUpperCase(),
  weather: WEATHER_CELLS[entry.weather],
})

/** The ten places of a board: one row per entry, then the places nobody holds, blank but for their number. */
export function lapRows(board: readonly LapEntry[]): Array<Record<string, string>> {
  return Array.from({ length: BOARD_SIZE }, (_, i) => {
    const entry = board[i]
    return entry === undefined ? { rank: String(i + 1) } : { ...common(i + 1, entry), result: markAssisted(formatLapTime(entry.lapMs), entry.assisted === true) }
  })
}

/** The ten places of a best-race board, the result as laps then time. */
export function raceRows(board: readonly RaceEntry[]): Array<Record<string, string>> {
  return Array.from({ length: BOARD_SIZE }, (_, i) => {
    const entry = board[i]
    return entry === undefined ? { rank: String(i + 1) } : { ...common(i + 1, entry), result: markAssisted(`${entry.laps} ${formatLapTime(entry.timeMs)}`, entry.assisted === true) }
  })
}

// ── Words ───────────────────────────────────────────────────────────────────────────────────────────────────────

/** How each class is named on the leaderboard screens: short, so that the selector stays narrow. */
export const CLASS_WORDS: Readonly<Record<CarClassId, string>> = {
  'tc-stock-175': 'STOCK 17.5T',
  'tc-mod-45': 'MODIFIED 4.5T',
  'fwd-105': 'FWD 10.5T',
  'f1-215': 'F1 21.5T',
}

export const DIRECTION_WORDS: Readonly<Record<Direction, string>> = { 'counter-clockwise': 'COUNTER-CLOCKWISE', clockwise: 'CLOCKWISE' }
export const BOARD_WORDS: Readonly<Record<BoardKind, string>> = { lap: 'FASTEST LAP', race: 'BEST RACE' }
export const LEVEL_WORDS: Readonly<Record<Difficulty, string>> = { club: 'CLUB', regional: 'REGIONAL', national: 'NATIONAL' }

/** The line over the table: which board it is, and the condition when one is chosen (F-818). `minutes` is left out for a lap board. */
export const boardTitle = (kind: BoardKind, trackName: string, direction: Direction, carClass: CarClassId, minutes: number | null, weather: WeatherFilter = 'all'): string =>
  [BOARD_WORDS[kind], trackName.toUpperCase(), DIRECTION_WORDS[direction], CLASS_WORDS[carClass], ...(kind === 'race' && minutes !== null ? [`${minutes} MIN`] : []), ...(weather === 'all' ? [] : [WEATHER_WORDS[weather]])].join('  ')

export const INITIALS_HEADING = 'NEW TOP 10 RESULT'
export const INITIALS_PANEL = 'ENTER YOUR INITIALS'
export const INITIALS_HINT = 'TYPE LETTERS AND DIGITS   ← → MOVE   ↑ ↓ CHANGE   BACKSPACE DELETE'
export const INITIALS_KEYS = 'ENTER OK   ESC SKIP'
export const DISCARD_QUESTION = 'DISCARD THIS RESULT? IT WILL NOT GO ON THE BOARD.'
export const DISCARD_CONFIRM = 'DISCARD'
export const DISCARD_CANCEL = 'KEEP IT'

/** The line of the initials screen for a result that makes a board: which board, at what rank, and the result. */
export const offerWords = (kind: BoardKind, offer: NonNullable<Offer['lap'] | Offer['race']>): string => {
  const result = 'lapMs' in offer ? formatLapTime(offer.lapMs) : `${offer.laps} ${offer.laps === 1 ? 'LAP' : 'LAPS'}  ${formatLapTime(offer.timeMs)}`
  return `${BOARD_WORDS[kind]}  RANK ${offer.rank}  ${result}`
}

export const LEADERBOARD_HEADING = 'LEADERBOARDS'
export const LEADERBOARD_HINT_BROWSE = '↑ ↓ MOVE   ← → CHANGE   ESC BACK'
export const LEADERBOARD_HINT_FLOW = '↑ ↓ MOVE   ← → CHANGE   ENTER CONTINUE'
