import { resolveCar, type CarClassId, type CarParams, type SessionConfig } from '@sim'
import { classes } from '@content/classes'
import { newbie } from '@content/presets'
import { tuning } from '@content/tuning'
import { presetSetup, type CarSetup } from './presets'

// DRIVING ASSISTANCE (F-811): with the setting on, the player's car has the NEWBIE setup (F-807) in every session they
// drive, and every AI car the shipped one. The arrows drive as they always do. Laps and races driven with it count for
// the bests and the boards like any other, and carry the mark (A*) wherever they are shown (F-815).

/** The preset the assistance gives the player's car. */
export const ASSISTANCE_PRESET = newbie

/** What follows a time set with the assistance on, wherever it is shown. */
export const ASSISTED_MARK = '(A*)'

/** What the mark means, in the hints' style: under a leaderboard table that holds a marked row, and among the foot lines of the results screen. Names the switch as the options screen does. */
export const ASSISTED_MEANS = '* A -> DRIVING ASSISTANCE ON'

/** A time as shown, with the mark after it when it was set with the assistance on. */
export const markAssisted = (time: string, assisted: boolean): string => (assisted ? `${time} ${ASSISTED_MARK}` : time)

/** The class row and tuning block of the assisted car of a class: NEWBIE over the shipped ones, exactly as the tuning panel applies the preset. */
export function assistedSetup(carClass: CarClassId): CarSetup {
  return presetSetup(ASSISTANCE_PRESET, classes[carClass], tuning)
}

/** The parameters the assisted car of a class is driven with, resolved as the sim resolves every car. */
export function assistedParams(carClass: CarClassId): CarParams {
  const setup = assistedSetup(carClass)
  return resolveCar(setup.car, setup.tuning)
}

/**
 * The session as the player drives it: with the assistance `on`, every human entry carries the assisted car's
 * parameters (`SessionEntry.params`) and every AI entry is left as it is, with the shipped car; with it off, the
 * config itself. Read when a session is built, so a change to the setting applies from the next session.
 */
export function assistedConfig(config: SessionConfig, on: boolean): SessionConfig {
  if (!on || !config.entries.some((entry) => entry.controller === 'human')) return config
  const params = assistedParams(config.carClass)
  return { ...config, entries: config.entries.map((entry) => (entry.controller === 'human' ? { ...entry, params } : entry)) }
}

/** Whether a session was built with the assistance: its human entry has the assisted car's parameters. */
export function isAssistedConfig(config: SessionConfig): boolean {
  return config.entries.some((entry) => entry.controller === 'human' && entry.params !== undefined)
}
