export const CARS_CHOICES: readonly CarsPerRace[] = [2, 4, 7]
export const MINUTES_CHOICES: readonly (3 | 5 | 7)[] = [3, 5, 7]
/** The forecasts the quick race offers (F-603): the WEATHER row. "Surprise me" is an event's choice, not a quick race's. */
export type QuickWeather = Extract<Forecast, 'dry' | 'changeable' | 'wet'>
export const WEATHER_CHOICES: readonly QuickWeather[] = ['dry', 'changeable', 'wet']

/** What the quick-race screen asks for, and what the garage chose. */
export interface QuickRaceOptions {
  kind: Extract<SessionKind, 'qualifying' | 'final'>
  cars: CarsPerRace
  direction: Direction
  minutes: 3 | 5 | 7
  difficulty: Difficulty
  /** The forecast the session follows; left out, dry. */
  weather?: QuickWeather
  carClass: CarClassId
  colour: CarColour
  seed: number
  /** Where a qualifying heat starts from. Only a qualifying heat on a track with a pit lane has the choice; elsewhere it is left out of the config. */
  qualifyingStart?: 'pit-lane' | 'start-boxes'
  /**
   * Whether the stop penalties are on and how long each holds a car, and whether the cars can reverse (F-508, F-510).
   * Left out, the config leaves them out too, which the sim reads as on, five seconds, on. The screen always gives all three.
   */
  penalties?: boolean
  penaltySeconds?: PenaltySeconds
  reverse?: boolean
}

/** The lengths of a penalty the settings offer, s. */
export type PenaltySeconds = 3 | 4 | 5
export const PENALTY_SECONDS_CHOICES: readonly PenaltySeconds[] = [3, 4, 5]

/** What the quick-race screen lets the player change besides the car and the track: kept in the save, so that the screen opens on the last race's choices (F-808). */
export interface QuickRaceChoices {
  kind: QuickRaceOptions['kind']
  cars: CarsPerRace
  direction: Direction
  minutes: QuickRaceOptions['minutes']
  difficulty: Difficulty
  weather: QuickWeather
  qualifyingStart: 'pit-lane' | 'start-boxes'
  penalties: boolean
  penaltySeconds: PenaltySeconds
  reverse: boolean
}

/** What the screen starts on with nothing saved: the rulebook's defaults. */
export const QUICK_RACE_DEFAULTS: Readonly<QuickRaceChoices> = { kind: 'final', cars: 7, direction: 'counter-clockwise', minutes: 5, difficulty: 'club', weather: 'dry', qualifyingStart: 'pit-lane', penalties: true, penaltySeconds: 5, reverse: true }

/** The values each choice may take. */
const QUICK_RACE_ALLOWED: { readonly [K in keyof QuickRaceChoices]: readonly QuickRaceChoices[K][] } = {
  kind: ['qualifying', 'final'],
  cars: CARS_CHOICES,
  direction: ['counter-clockwise', 'clockwise'],
  minutes: MINUTES_CHOICES,
  difficulty: ['club', 'regional', 'national'],
  weather: WEATHER_CHOICES,
  qualifyingStart: ['pit-lane', 'start-boxes'],
  penalties: [true, false],
  penaltySeconds: PENALTY_SECONDS_CHOICES,
  reverse: [true, false],
}

/** The screen's starting choices from what was saved of the last quick race: each saved value that is still a choice, the default for the rest (a save made before they were kept has none of them). */
export function quickChoicesFrom(saved: unknown): QuickRaceChoices {
  const last: Record<string, unknown> = typeof saved === 'object' && saved !== null ? (saved as Record<string, unknown>) : {}
  const pick = <K extends keyof QuickRaceChoices>(key: K): QuickRaceChoices[K] => {
    const value = last[key]
    const allowed: readonly unknown[] = QUICK_RACE_ALLOWED[key]
    return allowed.includes(value) ? (value as QuickRaceChoices[K]) : QUICK_RACE_DEFAULTS[key]
  }
  return {
    kind: pick('kind'),
    cars: pick('cars'),
    direction: pick('direction'),
    minutes: pick('minutes'),
    difficulty: pick('difficulty'),
    weather: pick('weather'),
    qualifyingStart: pick('qualifyingStart'),
    penalties: pick('penalties'),
    penaltySeconds: pick('penaltySeconds'),
    reverse: pick('reverse'),
  }
}

/** The player's driver id and car number in a quick race (the player keeps number 1, as at an event). */
export const PLAYER_DRIVER_ID = 'player'
export const PLAYER_NUMBER = 1

/** The player's start slot in a quick final, counted from pole as 0: the middle of the grid, which is 4th of 7 (slot 3), 3rd of 4 (slot 2) and 2nd of 2 (slot 1). */
export const finalGridSlot = (cars: CarsPerRace): number => Math.floor(cars / 2)

/**
 * The session for a quick race: the player and `cars - 1` roster drivers on the track oriented for the direction.
 *
 * - Numbers: the player is 1; the opponents are 2.. in order of skill, strongest first.
 * - Colours: the player's own; each opponent's preferred colour if free, else the next free one (`assignColours`).
 * - Start slots: in qualifying the order is drawn at random from the seed, the player included, so the same seed gives
 *   the same order and two seeds differ. In a final the player starts from the middle of the grid and the opponents
 *   take the other places, strongest nearest the front.
 * - The entries are in start-slot order, so that a car's id is its slot.
 */
export function buildQuickRace(opts: QuickRaceOptions, track: TrackData, roster: readonly DriverProfile[]): SessionConfig {
  const opponents = chooseOpponents(opts.difficulty, opts.cars - 1, roster, opts.seed)
  const colours = assignColours(
    opponents.map((driver) => driver.id),
    opts.colour,
    roster,
  )
  const drawn = opts.kind === 'qualifying' ? seededPermutation(opts.cars, opts.seed, 'quick-qualifying-order') : null
  const playerSlot = drawn?.[0] ?? finalGridSlot(opts.cars)
  const entries: SessionEntry[] = [{ driverId: PLAYER_DRIVER_ID, number: PLAYER_NUMBER, colour: opts.colour, controller: 'human', startSlot: playerSlot }]
  let slot = 0
  opponents.forEach((driver, i) => {
    if (drawn === null && slot === playerSlot) slot++
    entries.push({ driverId: driver.id, number: PLAYER_NUMBER + 1 + i, colour: colours[driver.id] ?? opts.colour, controller: 'ai', startSlot: drawn?.[i + 1] ?? slot })
    slot++
  })
  entries.sort((a, b) => a.startSlot - b.startSlot)

  const oriented = orientTrack(track, opts.direction)
  const config: SessionConfig = {
    seed: opts.seed,
    kind: opts.kind,
    label: opts.kind === 'final' ? 'Quick final' : 'Quick qualifying',
    track: oriented,
    carClass: opts.carClass,
    durationS: opts.minutes * 60,
    entries,
    difficulty: opts.difficulty,
    // The first sky, wetness and wind the chosen forecast draws, as a race day draws them (F-601); dry, with its light wind, when none is chosen.
    weather: firstWeatherPlan(opts.weather ?? 'dry', opts.seed),
  }
  if (opts.kind === 'qualifying' && oriented.pitLane !== undefined && opts.qualifyingStart !== undefined) config.qualifyingStart = opts.qualifyingStart
  // One that gives either penalty setting gives the session both, the other at its default (the way the race day does, `nextSession`).
  if (opts.penalties !== undefined || opts.penaltySeconds !== undefined) config.penalties = { enabled: opts.penalties ?? true, holdS: opts.penaltySeconds ?? 5 }
  if (opts.reverse !== undefined) config.reverse = opts.reverse
  return config
}

/**
 * Switches only the debug hook sets (development and test builds): a session length in seconds that replaces the
 * screen's minutes, so that a browser test can run a whole race in seconds, and a seed in place of a fresh one.
 * Both are null in play, and nothing in a production bundle sets them.
 */
export const quickRaceDebug: { durationS: number | null; seed: number | null } = { durationS: null, seed: null }

/** The seed for a quick race the player starts: the debug seed if the hook set one, else one from the wall clock. */
export const freshSeed = (): number => quickRaceDebug.seed ?? Date.now() % 2_147_483_647

/** The config with the debug session length applied, if the hook set one. */
export const withDebugOverrides = (config: SessionConfig): SessionConfig => (quickRaceDebug.durationS === null ? config : { ...config, durationS: quickRaceDebug.durationS })

// The results table (the pure part of the results screen, so that it is tested without an engine).

/** What the table calls a player who has not set a name, and who is not in the roster. */
export const PLAYER_NAME = NO_NAME
/** Printed beside a car's laps and time when it did not finish. */
export const DNF = 'DNF'
/** Printed in front of the best lap of the session's fastest car. */
export const FASTEST_MARK = '*'

export const RESULTS_COLUMNS: readonly TableColumn[] = [
  { key: 'pos', title: 'POS', chars: 3, align: 'right' },
  { key: 'no', title: 'NO', chars: 2, align: 'right' },
  { key: 'name', title: 'DRIVER', chars: 17, align: 'left' },
  { key: 'time', title: 'LAPS / TIME', chars: 18, align: 'left' },
  { key: 'best', title: 'BEST LAP', chars: 9, align: 'right' },
]

export interface ResultsTable {
  /** One line of cells per car, in result order. */
  rows: Array<Record<string, string>>
  /** The index of the player's row, or -1. */
  playerRow: number
  /** The indexes of the rows that are marked as the fastest lap of the session (none, or one). */
  fastestRows: number[]
}

/** The name shown for a driver: the roster's name in capitals, or the player's: the name they set in the garage, or YOU (`playerName`, the one place that says). */
export function driverName(driverId: DriverId, playerId: DriverId, roster: readonly DriverProfile[]): string {
  if (driverId === playerId) return playerName()
  const profile = roster.find((driver) => driver.id === driverId)
  return (profile?.name ?? driverId).toUpperCase()
}

/**
 * The rows of the results table for a finished session: position, number, name, laps and time (a car that did not
 * finish has DNF beside them) and best lap, with the fastest lap of the session marked.
 */
export function resultsTable(result: SessionResult, playerId: DriverId, roster: readonly DriverProfile[]): ResultsTable {
  const fastestId = result.fastestLap?.driverId ?? null
  const fastestRows: number[] = []
  const rows = result.rows.map((row, i) => {
    const fastest = fastestId !== null && row.driverId === fastestId && row.bestLapMs === result.fastestLap?.lapMs
    if (fastest) fastestRows.push(i)
    const time = `${row.laps} ${formatLapTime(row.timeMs > 0 ? row.timeMs : null)}`
    return {
      pos: String(i + 1),
      no: String(row.number),
      name: driverName(row.driverId, playerId, roster),
      time: row.finished ? time : `${time} ${DNF}`,
      best: `${fastest ? FASTEST_MARK : ''}${formatLapTime(row.bestLapMs)}`,
    }
  })
  return { rows, playerRow: result.rows.findIndex((row) => row.driverId === playerId), fastestRows }
}
