import type { ControlInput } from '@sim'

/** Which of the four driving keys are held down right now. */
export interface HeldKeys {
  up: boolean
  down: boolean
  left: boolean
  right: boolean
}

/**
 * The raw intent four keys express (game-design.md, "Controls"): throttle and brake at 0 or 1, steering at -1, 0 or 1.
 * Brake wins over throttle, and opposite steering keys cancel. Shaping (slew, ramps, reverse) is the sim's job, so
 * nothing is smoothed here.
 */
export function keysToInput(keys: HeldKeys): ControlInput {
  return {
    throttle: keys.up && !keys.down ? 1 : 0,
    brake: keys.down ? 1 : 0,
    steer: (keys.right ? 1 : 0) - (keys.left ? 1 : 0),
  }
}
