import type { CarClassId } from '@sim'
import type { AudioMixer } from './AudioMixer'
import { GRASS_ENTRY_BOG, PLAYER_BOOST, grassVoice, motorCutoffHz, motorPartials, motorVoice, scrubVoice } from './mapping'
import { DRIVETRAIN_SOUND } from './motor-sound'
import { startNoise } from './noise'

/** What one car's sound is made from this frame. All of it from the interpolated snapshot. */
export interface CarSoundInput {
  motorRadS: number
  throttle: number
  speedMS: number
  slipFront: number
  slipRear: number
  /** The track's wetness 0..1, which makes the tyres hiss. */
  wetness: number
  /** On the grass: the sim's `bog`, 0 off it. */
  onGrass: boolean
  bog: number
  /** Whether the motor is in a driver's hands (driving or finished and rolling); false on its roof, stuck, held or carried. */
  alive: boolean
  /** -1..1 from the car's screen position. */
  pan: number
}

/** Time constants of the smoothing that keeps a changing parameter from zippering. */
const PITCH_TAU_S = 0.04
const LEVEL_TAU_S = 0.05
const PAN_TAU_S = 0.08
/** The square oscillator sits this far above the saw: the two together beat a little, as two windings' fields do. */
const DETUNE_CENTS = 12

/**
 * One car's continuous voices (F-704), on a single panner so the car sits where it is on the screen:
 * - the motor: a sawtooth and a slightly detuned square at the whine's pitch, a sine at the pinion-and-spur mesh
 *   frequency and a triangle at the belt's tooth-passing frequency (none on the F1), all through one low-pass whose cutoff
 *   opens with load and speed. The class sets the tooth counts and the mix (`motor-sound.ts`);
 * - tyre scrub: noise through a band-pass, in when an axle passes its grip;
 * - grass drag: noise through a low-pass, in with the car's bog.
 * The parameters are all `mapping.ts`'s; this class only applies them, with `setTargetAtTime` so nothing steps.
 */
export class MotorSynth {
  private readonly nodes: AudioNode[] = []
  private readonly sources: Array<AudioScheduledSourceNode> = []
  private readonly saw: OscillatorNode
  private readonly square: OscillatorNode
  private readonly mesh: OscillatorNode
  private readonly belt: OscillatorNode
  private readonly lowpass: BiquadFilterNode
  private readonly motorGain: GainNode
  private readonly scrubFilter: BiquadFilterNode
  private readonly scrubGain: GainNode
  private readonly grassFilter: BiquadFilterNode
  private readonly grassGain: GainNode
  private readonly panner: StereoPannerNode
  private disposed = false

  constructor(
    private readonly mixer: AudioMixer,
    private readonly classId: CarClassId,
    private readonly player: boolean,
  ) {
    const { ctx } = mixer
    const { mix } = DRIVETRAIN_SOUND[classId]
    const track = <T extends AudioNode>(node: T): T => {
      this.nodes.push(node)
      return node
    }
    const oscillator = (type: OscillatorType, level: number, into: AudioNode, detune = 0): OscillatorNode => {
      const osc = ctx.createOscillator()
      osc.type = type
      osc.frequency.value = 0
      osc.detune.value = detune
      const gain = track(ctx.createGain())
      gain.gain.value = level
      osc.connect(gain)
      gain.connect(into)
      this.sources.push(osc)
      this.nodes.push(osc)
      osc.start()
      return osc
    }

    this.panner = track(ctx.createStereoPanner())
    this.panner.connect(mixer.sfx)

    this.motorGain = track(ctx.createGain())
    this.motorGain.gain.value = 0
    this.motorGain.connect(this.panner)
    this.lowpass = track(ctx.createBiquadFilter())
    this.lowpass.type = 'lowpass'
    this.lowpass.Q.value = 0.7
    this.lowpass.frequency.value = motorCutoffHz(0.2)
    this.lowpass.connect(this.motorGain)
    // The whine: 60 % saw and 40 % square of its level, the square a few cents sharp.
    this.saw = oscillator('sawtooth', mix.whine * 0.6, this.lowpass)
    this.square = oscillator('square', mix.whine * 0.4, this.lowpass, DETUNE_CENTS)
    this.mesh = oscillator('sine', mix.mesh, this.lowpass)
    this.belt = oscillator('triangle', mix.belt, this.lowpass)

    this.scrubGain = track(ctx.createGain())
    this.scrubGain.gain.value = 0
    this.scrubGain.connect(this.panner)
    this.scrubFilter = track(ctx.createBiquadFilter())
    this.scrubFilter.type = 'bandpass'
    this.scrubFilter.Q.value = 0.9
    this.scrubFilter.frequency.value = 1500
    this.scrubFilter.connect(this.scrubGain)
    const scrub = startNoise(ctx)
    scrub.connect(this.scrubFilter)
    this.sources.push(scrub)
    this.nodes.push(scrub)

    this.grassGain = track(ctx.createGain())
    this.grassGain.gain.value = 0
    this.grassGain.connect(this.panner)
    this.grassFilter = track(ctx.createBiquadFilter())
    this.grassFilter.type = 'lowpass'
    this.grassFilter.Q.value = 0.6
    this.grassFilter.frequency.value = 600
    this.grassFilter.connect(this.grassGain)
    const grass = startNoise(ctx)
    grass.connect(this.grassFilter)
    this.sources.push(grass)
    this.nodes.push(grass)
  }

  update(p: CarSoundInput): void {
    if (this.disposed) return
    const now = this.mixer.ctx.currentTime
    const { classId } = this
    const motor = motorVoice({ motorRadS: p.motorRadS, throttle: p.throttle, classId })
    const partials = motorPartials({ motorRadS: p.motorRadS, classId })
    const live = p.alive
    this.saw.frequency.setTargetAtTime(motor.freqHz, now, PITCH_TAU_S)
    this.square.frequency.setTargetAtTime(motor.freqHz, now, PITCH_TAU_S)
    this.mesh.frequency.setTargetAtTime(partials.meshHz, now, PITCH_TAU_S)
    this.belt.frequency.setTargetAtTime(partials.beltHz, now, PITCH_TAU_S)
    this.lowpass.frequency.setTargetAtTime(motorCutoffHz(motor.brightness), now, LEVEL_TAU_S)
    this.motorGain.gain.setTargetAtTime(live ? motor.gain * (this.player ? PLAYER_BOOST : 1) : 0, now, LEVEL_TAU_S)

    const scrub = scrubVoice({ slipFront: p.slipFront, slipRear: p.slipRear, speedMS: p.speedMS, wetness: p.wetness })
    this.scrubGain.gain.setTargetAtTime(live ? scrub.gain : 0, now, LEVEL_TAU_S)
    this.scrubFilter.frequency.setTargetAtTime(scrub.cutoffHz, now, LEVEL_TAU_S)

    const grass = grassVoice({ bog: p.onGrass ? Math.max(p.bog, GRASS_ENTRY_BOG) : 0, speedMS: p.speedMS })
    this.grassGain.gain.setTargetAtTime(p.onGrass ? grass.gain : 0, now, LEVEL_TAU_S)
    this.grassFilter.frequency.setTargetAtTime(grass.cutoffHz, now, LEVEL_TAU_S)

    this.panner.pan.setTargetAtTime(p.pan, now, PAN_TAU_S)
  }

  /** Stops every oscillator and noise source and disconnects every node the voice made. */
  dispose(): void {
    if (this.disposed) return
    this.disposed = true
    for (const source of this.sources) {
      try {
        source.stop()
      } catch {
        // Already stopped.
      }
    }
    for (const node of this.nodes) node.disconnect()
    this.nodes.length = 0
    this.sources.length = 0
  }
}
