import type { Sky, SurfaceKind, Vec2 } from '@sim'

// What the weather looks like, as pure mappings (F-603): from the numbers in the sim's weather snapshot to the numbers
// the renderers use. No engine in here, so that every scenario is tested in Node. Every number that shapes how a
// weather effect looks is in this file; WeatherFx.ts and WindSock.ts only apply them.

const clamp = (value: number, low: number, high: number): number => Math.min(high, Math.max(low, value))
const finite = (value: number): number => (Number.isFinite(value) ? value : 0)
const smoothstep = (low: number, high: number, value: number): number => {
  const t = clamp((value - low) / (high - low), 0, 1)
  return t * t * (3 - 2 * t)
}

// ── Rain ────────────────────────────────────────────────────────────────────────────────────────────────────

export const RAIN = {
  /** Streaks born each second, over the whole screen, at an intensity of 1. */
  maxPerS: 2600,
  /** Rain this light is not drawn at all. */
  minIntensity: 0.02,
  /** How fast a drop falls down the screen, px/s, and how far each metre a second of wind carries it sideways, px/s. */
  fallPxS: 1500,
  driftPxPerMS: 150,
  /** The most a streak leans from the vertical, rad: the wind never lays the rain flat. */
  maxSlantRad: (40 * Math.PI) / 180,
  /** Ground splashes born each second, as a share of the streaks. */
  splashShare: 0.1,
} as const

/** Streaks to start each second at a rain intensity of 0..1: none when it is not raining, then in proportion. */
export function rainParticleRate(intensity: number): number {
  const i = clamp(finite(intensity), 0, 1)
  return i < RAIN.minIntensity ? 0 : RAIN.maxPerS * i
}

/** Splashes where the drops land, each second. */
export const groundSplashRate = (intensity: number): number => rainParticleRate(intensity) * RAIN.splashShare

/**
 * How far a falling streak leans from the vertical, rad: positive leans to the right (the drops are carried toward
 * +x, as in a wind from the left), more the stronger the wind across the screen, and never more than `maxSlantRad`.
 */
export function rainSlantRad(wind: Vec2): number {
  const lean = Math.atan2(Math.abs(finite(wind.x)) * RAIN.driftPxPerMS, RAIN.fallPxS)
  return Math.sign(finite(wind.x)) * Math.min(RAIN.maxSlantRad, lean)
}

// ── The wet track ───────────────────────────────────────────────────────────────────────────────────────────

/** How dark a wet surface goes at wetness 1 (the alpha of the dark overlay), by surface. */
const WET_DARKEST: Readonly<Record<SurfaceKind, number>> = { asphalt: 0.62, kerb: 0.5, grass: 0.3 }
/** The overlay climbs a little faster than the wetness at first and flattens, so that the first rain shows. */
const WET_CURVE = 0.85
/** The sheen of a wet road: the alpha of the pale veil at wetness 1, asphalt only. */
const SHEEN_BRIGHTEST = 0.14
const SHEEN_CURVE = 1.4

/** The alpha of the dark overlay over a surface at a wetness of 0..1: nothing when dry, darker as it gets wet, no step on the way. */
export function wetOverlayAlpha(wetness: number, surface: SurfaceKind): number {
  return WET_DARKEST[surface] * Math.pow(clamp(finite(wetness), 0, 1), WET_CURVE)
}

/** The alpha of the sheen over a surface: the asphalt gains it as it gets wet, the grass never does. */
export function sheenAlpha(wetness: number, surface: SurfaceKind): number {
  return surface === 'grass' ? 0 : SHEEN_BRIGHTEST * Math.pow(clamp(finite(wetness), 0, 1), SHEEN_CURVE)
}

/** A puddle's alpha from its depth: it fades in and out with the water, and is nearly solid from a depth of 0.2. */
export function puddleAlpha(depth: number): number {
  return 0.96 * smoothstep(0, 0.25, finite(depth))
}

/** Tyre marks are not laid down above this local wetness. */
export const SKID_WET_LIMIT = 0.5
export const skidsLaid = (localWetnessNow: number): boolean => !(localWetnessNow > SKID_WET_LIMIT)

// ── Spray ───────────────────────────────────────────────────────────────────────────────────────────────────

export const SPRAY = {
  /** A car throws spray only above this speed, m/s, and on a surface at least this wet. */
  minSpeedMS: 2,
  minWetness: 0.3,
  /** Puffs a second from one car at the most. */
  maxPerS: 60,
  /** The speed at which the speed share is whole, m/s above the minimum. */
  fullSpeedSpanMS: 6,
} as const

/** Puffs of spray a second from a car at `speedMS` on a surface of `localWetnessNow`: none below the limits, more with speed and with water. */
export function sprayRate(speedMS: number, localWetnessNow: number): number {
  const speed = Math.abs(finite(speedMS))
  if (!(speed > SPRAY.minSpeedMS) || !(localWetnessNow > SPRAY.minWetness)) return 0
  const speedShare = clamp((speed - SPRAY.minSpeedMS) / SPRAY.fullSpeedSpanMS, 0, 1)
  const wetShare = clamp((localWetnessNow - SPRAY.minWetness) / (1 - SPRAY.minWetness), 0, 1)
  return 6 + (SPRAY.maxPerS - 6) * (0.35 + 0.65 * speedShare) * (0.3 + 0.7 * wetShare)
}

// ── Light ───────────────────────────────────────────────────────────────────────────────────────────────────

const LIGHT: Readonly<Record<Sky, number>> = { sunny: 1, cloudy: 0.92, 'light-rain': 0.84, 'heavy-rain': 0.74 }
/** The light moves to a new level with this time constant, s: a change of sky settles in about eight seconds. */
const LIGHT_EASE_S = 2.4

/** How bright the scene is under a sky, 0..1 of full sun: the brightest in sun, duller through cloud, light rain and heavy rain. */
export const lightLevel = (sky: Sky): number => LIGHT[sky]

/** `level` moved toward `target` by `dtS` seconds of easing: it never overshoots. */
export function easeLight(level: number, target: number, dtS: number): number {
  return target + (level - target) * Math.exp(-Math.max(0, dtS) / LIGHT_EASE_S)
}

/** The alpha of the cool veil over the scene that takes it down to `level`: none in full sun. */
export const lightVeilAlpha = (level: number): number => clamp(1 - level, 0, 1)

// ── Cloud shadows ───────────────────────────────────────────────────────────────────────────────────────────

export const CLOUD_SHADOW = {
  /** The most shadows on screen, and the cover at which the first appears and at which each next one does. */
  slots: 3,
  firstCover: 0.15,
  coverPerSlot: 0.3,
  /** A shadow fades in over this much more cover. */
  fadeCover: 0.15,
  /** The darkest a shadow is: a faint veil, never a patch that draws the eye from the cars. */
  maxAlpha: 0.26,
  /** Drift: this many px/s for each m/s of wind, and never more than the cap, however hard it blows. */
  driftPxPerMS: 3,
  maxDriftPxS: 12,
  /** The drift follows the wind with this time constant, s, so that a gust does not jerk the shadows. */
  easeS: 4,
  /** How far past the screen's edge a shadow's centre goes before it is placed again upwind, px: a little over half the picture's long side. */
  halfExtentPx: 600,
} as const

/** How many shadows the cover calls for: none below 0.15, then one more for each 0.3 more cover, at most three. */
export function cloudShadowCount(cover: number): number {
  const c = finite(cover)
  if (c < CLOUD_SHADOW.firstCover) return 0
  return Math.min(CLOUD_SHADOW.slots, 1 + Math.floor((c - CLOUD_SHADOW.firstCover) / CLOUD_SHADOW.coverPerSlot))
}

/** The alpha of shadow `slot` (0-based) at a cloud cover of 0..1: it fades in over a stretch of cover once the cover has reached its own. */
export function cloudShadowAlpha(cover: number, slot: number): number {
  const from = CLOUD_SHADOW.firstCover + slot * CLOUD_SHADOW.coverPerSlot
  return CLOUD_SHADOW.maxAlpha * smoothstep(from, from + CLOUD_SHADOW.fadeCover, finite(cover))
}

/** Where the shadows drift, px/s: the wind's way, 3 px/s for each m/s of it, and never faster than 12 px/s. */
export function cloudDrift(wind: Vec2): Vec2 {
  const speed = Math.hypot(finite(wind.x), finite(wind.y))
  if (speed === 0) return { x: 0, y: 0 }
  const pace = Math.min(CLOUD_SHADOW.maxDriftPxS, speed * CLOUD_SHADOW.driftPxPerMS)
  return { x: (wind.x / speed) * pace, y: (wind.y / speed) * pace }
}

/** The centre of a shadow on the screen, px. */
export interface ShadowState {
  x: number
  y: number
}

/**
 * A shadow after `dtS` of drifting at `drift` px/s. One that has gone more than `extent` px past the screen on the
 * side it is drifting toward is put just beyond the opposite side, at a new height or place across the screen
 * (`rand`, 0..1), to drift in again: there are always as many shadows as there were.
 */
export function stepShadow(shadow: ShadowState, drift: Vec2, dtS: number, screen: { w: number; h: number }, extent: number, rand: () => number): ShadowState {
  let x = shadow.x + drift.x * dtS
  let y = shadow.y + drift.y * dtS
  const across = (size: number): number => -0.1 * size + rand() * 1.2 * size
  if (drift.x > 0 && x > screen.w + extent) {
    x = -extent
    y = across(screen.h)
  } else if (drift.x < 0 && x < -extent) {
    x = screen.w + extent
    y = across(screen.h)
  }
  if (drift.y > 0 && y > screen.h + extent) {
    y = -extent
    x = across(screen.w)
  } else if (drift.y < 0 && y < -extent) {
    y = screen.h + extent
    x = across(screen.w)
  }
  return { x, y }
}

// ── The windsock and the wind arrow ─────────────────────────────────────────────────────────────────────────

export const SOCK = {
  /** The sock hangs limp below this wind, m/s, and stands fully out at this one and above. */
  limpMS: 0.5,
  fullMS: 6,
  /** The extension frames drawn for each view, limp to straight out. */
  frames: 4,
  /** A gust kicks the sock for this long, s, shaking it every `shakeS`. */
  kickS: 1.2,
  shakeS: 0.07,
  shakePx: 2,
} as const

/** The sock's pose for a wind: the way it points (rad, clockwise from +x on the screen) and how far out it stands, 0 limp to 1 straight out. */
export function windsockPose(wind: Vec2): { angleRad: number; extension: number } {
  const x = finite(wind.x)
  const y = finite(wind.y)
  const speed = Math.hypot(x, y)
  return { angleRad: Math.atan2(y, x), extension: speed < SOCK.limpMS ? 0 : clamp((speed - SOCK.limpMS) / (SOCK.fullMS - SOCK.limpMS), 0, 1) }
}

/** What a gust does to the sock `ageS` seconds after it began (null: no gust): one frame more, and a shake of a couple of pixels, back and forth. */
export function kickOf(ageS: number | null): { extra: number; shakePx: number } {
  if (ageS === null || !(ageS >= 0) || ageS >= SOCK.kickS) return { extra: 0, shakePx: 0 }
  return { extra: 1, shakePx: Math.floor(ageS / SOCK.shakeS) % 2 === 0 ? -SOCK.shakePx : SOCK.shakePx }
}

/** A picture of the sock by manifest name, with how it is turned over: the sock is never rotated (F-605). */
export interface SockPicture {
  name: string
  flipX: boolean
  flipY: boolean
}

/**
 * The picture of the sock for a wind, `extra` frames further out than the wind alone gives (a gust's kick). Of the
 * four directions drawn (the side view blowing right, mirrored for left; the view from above blowing down, flipped
 * for up) it takes the nearest to the wind's, the side view on a tie; limp, it is frame 0 of the side view blowing right.
 */
export function sockPicture(wind: Vec2, extra: number): SockPicture {
  const { angleRad, extension } = windsockPose(wind)
  const frame = Math.min(SOCK.frames - 1, Math.round(extension * (SOCK.frames - 1)) + extra)
  if (extension === 0) return { name: `hud.windsock.${frame}`, flipX: false, flipY: false }
  const across = Math.cos(angleRad)
  const down = Math.sin(angleRad)
  if (Math.abs(across) + 1e-9 >= Math.abs(down)) return { name: `hud.windsock.${frame}`, flipX: across < 0, flipY: false }
  return { name: `hud.windsock.down.${frame}`, flipX: false, flipY: down < 0 }
}

/** The directions the wind arrow is drawn in, from +x clockwise on the screen in equal steps: 22.5 degrees, so the arrow is never more than 11.25 degrees off. */
export const ARROW_DIRECTIONS = 16
/** The arrow's cell, in art pixels (the HUD's density: two screen pixels each). */
export const ARROW_PX = 12

/** Which of the sixteen arrows shows a wind: the one nearest the way the air is going. */
export function arrowIndex(wind: Vec2): number {
  const angle = Math.atan2(finite(wind.y), finite(wind.x))
  const step = (Math.PI * 2) / ARROW_DIRECTIONS
  return ((Math.round(angle / step) % ARROW_DIRECTIONS) + ARROW_DIRECTIONS) % ARROW_DIRECTIONS
}

/** The distance from a point to a segment. */
function distanceToSegment(px: number, py: number, ax: number, ay: number, bx: number, by: number): number {
  const dx = bx - ax
  const dy = by - ay
  const t = clamp(((px - ax) * dx + (py - ay) * dy) / (dx * dx + dy * dy), 0, 1)
  return Math.hypot(px - (ax + t * dx), py - (ay + t * dy))
}

/** How thick a stroke of the arrow is, art pixels: a pixel is ink when its centre is this near the stroke. */
const ARROW_REACH = 0.6
const ARROW_HALF_LENGTH = 5.3
const ARROW_BARB = 3.8
const ARROW_BARB_ANGLE = (140 * Math.PI) / 180
/** The arrow's middle, art pixels: on a pixel's centre, so that a shaft along an axis is one pixel thick. */
export const ARROW_CENTRE = ARROW_PX / 2 - 0.5

/**
 * The arrow `index` as hard pixels: `ARROW_PX` x `ARROW_PX` values, row by row, 1 where there is ink. A shaft from
 * the middle's tail to its tip, and two barbs back from the tip. Drawn by code, once, into a texture (WindSock).
 */
export function arrowPixels(index: number): Uint8Array {
  const pixels = new Uint8Array(ARROW_PX * ARROW_PX)
  const angle = (index * Math.PI * 2) / ARROW_DIRECTIONS
  const c = ARROW_CENTRE
  const tipX = c + Math.cos(angle) * ARROW_HALF_LENGTH
  const tipY = c + Math.sin(angle) * ARROW_HALF_LENGTH
  const tailX = c - Math.cos(angle) * ARROW_HALF_LENGTH
  const tailY = c - Math.sin(angle) * ARROW_HALF_LENGTH
  const strokes: Array<[number, number, number, number]> = [[tailX, tailY, tipX, tipY]]
  for (const side of [-1, 1]) {
    const back = angle + Math.PI + side * (Math.PI - ARROW_BARB_ANGLE)
    strokes.push([tipX, tipY, tipX + Math.cos(back) * ARROW_BARB, tipY + Math.sin(back) * ARROW_BARB])
  }
  for (let y = 0; y < ARROW_PX; y++) {
    for (let x = 0; x < ARROW_PX; x++) {
      const near = strokes.some(([ax, ay, bx, by]) => distanceToSegment(x + 0.5, y + 0.5, ax, ay, bx, by) <= ARROW_REACH)
      pixels[y * ARROW_PX + x] = near ? 1 : 0
    }
  }
  return pixels
}

/** A box on the canvas, px. */
export interface Box {
  x: number
  y: number
  w: number
  h: number
}

/** The HUD's weather pieces in the far right of the band above the track (art-direction.md, "HUD"): the wind arrow, the windsock and the sky icon, left to right. */
export const HUD_WEATHER = { margin: 24, gap: 16, icon: 40, arrow: ARROW_PX * 2 } as const

export function weatherHudLayout(bandHeight: number, canvasWidth = 1920): { arrow: Box; sock: Box; sky: Box } {
  const { margin, gap, icon, arrow } = HUD_WEATHER
  const top = (h: number): number => Math.round((bandHeight - h) / 2)
  const sky: Box = { x: canvasWidth - margin - icon, y: top(icon), w: icon, h: icon }
  const sock: Box = { x: sky.x - gap - icon, y: top(icon), w: icon, h: icon }
  const arrowBox: Box = { x: sock.x - gap - arrow, y: top(arrow), w: arrow, h: arrow }
  return { arrow: arrowBox, sock, sky }
}
