import Phaser from 'phaser'
import { orientTrack, type CarClassId } from '@sim'
import { CLASS_ORDER } from '@content/classes'
import { cuencaRc } from '@content/tracks'
import { directionSet, manifestOf, still } from '../assets/manifest'
import { GRAPHICS_RESTORED } from '../lifecycle/context'
import { fitWorld, LOGICAL_HEIGHT, LOGICAL_WIDTH, type WorldView } from '../config'
import { musicOf, toggleMusic } from '../audio/music'
import { onKey, onNav, type NavKey } from '../input/keys'
import { cleanCapture, stampShown } from '../input/tools'
import { AttractMode, type AttractInfo } from '../race/AttractMode'
import { CONTINUE_LABEL, nextWords } from '../persistence'
import { RACE_DAY_KEY, RaceDayController, type RaceDayFlowData } from '../raceday/RaceDayController'
import { freshSeed } from '../race/quick-race'
import { VERSION } from '../version'
import { TrackRenderer } from '../race/TrackRenderer'
import { CornerRibbon, MenuList, THEME, charWidth, lineHeight, loadCoverAtlases, text, type CoverAtlases, type HasReadout, type ScreenReadout } from '../ui'
import type { GarageSceneData } from './GarageScene'
import type { LeaderboardInit } from './LeaderboardScene'

/**
 * Practice, Quick race, Race day, Leaderboards, Options and Credits. Practice stays first: it is what Enter on a fresh title chooses;
 * each later item comes after the ones that were there, so that they keep their places.
 */
const ITEMS = [
  { id: 'practice', label: 'PRACTICE' },
  { id: 'quick-race', label: 'QUICK RACE' },
  { id: 'race-day', label: 'RACE DAY' },
  { id: 'leaderboards', label: 'LEADERBOARDS' },
  { id: 'options', label: 'OPTIONS' },
  { id: 'credits', label: 'CREDITS' },
]
/** With an event in progress, CONTINUE is the first item, so that Enter on the title resumes it. */
const CONTINUE = { id: 'continue', label: CONTINUE_LABEL }
/** The menu's top and the distance between items: lower and wider on a title with no event, and higher and closer with CONTINUE, so that seven fit above the key hint. */
const MENU_Y = 520
const MENU_Y_WITH_CONTINUE = 496
const MENU_PITCH = 80
const MENU_PITCH_WITH_CONTINUE = 72
/** The longest label of the menu, which sets how wide the focus bar is. */
const WIDEST_LABEL = Math.max(...ITEMS.map((item) => item.label.length))

/** The line of keys at the bottom: Enter, and M for the music with what it will do next being what it says now. */
const hintWords = (musicOn: boolean): string => `ENTER CHOOSE   M MUSIC ${musicOn ? 'ON' : 'OFF'}`

/**
 * The cover's picture: the home track baked once and dimmed, a race of seven AI cars running over it (F-801), and the logo
 * and menu over a darker veil, between a strip of chequers along the top and the bottom of the screen (F-802). Draw order,
 * back to front: the ground, the dimming, the cars (the race's own depths), the darker veil behind the menu and the
 * chequers, then the logo, the menu and the ribbon.
 */
const DIM_ALPHA = 0.6
/** A darker veil behind the name and menu: solid for 800 px, then fading out over the next 480. */
const VEIL_ALPHA = 0.5
const VEIL_SOLID_PX = 800
const VEIL_STEPS = 24
const VEIL_STEP_PX = 20
const LEFT = 120
/** The logo's top-left corner (art/skin/build.py draws it: original lettering, the game's name over a strip of kerb), where the name in the font stood. */
const LOGO_TOP = 120
const LOGO = 'skin.logo'
/**
 * The line under the logo (F-809). The logo's kerb stripe ends with its last coloured row at y = 321 and the stripe's ink
 * outline under it at y = 322 and 323 (art rows 100 and 101, two screen px each); the letters' highest pixel is 4 px under
 * the text's top. So the highest pixel is 331: 9 px under the stripe's colour and 7 under its outline.
 */
const TAGLINE_Y = 327
const TAGLINE = '1/10 Electric RC Racing'
const CHEQUER = 'skin.chequer'
/** Depths of the layers over the cars (the race draws its cars at 40 and up). */
const DEPTH_DIM = 1
const DEPTH_VEIL = 50
const DEPTH_UI = 60
const DEPTH_RIBBON = 70

/** Whether a game object can be given a depth (the display objects can). */
const hasDepth = (object: Phaser.GameObjects.GameObject): object is Phaser.GameObjects.GameObject & Phaser.GameObjects.Components.Depth => 'setDepth' in object

/**
 * The title: a cover and a short menu on it. The cover is the home track baked in the engine, with the logo and the chequers
 * of the skin atlas (F-802), which is loaded with the font. The track, the logo, the menu and (outside the production build) the DEMO ribbon are drawn at once, so the title is up without any
 * car atlas; the race of seven AI cars behind the menu (F-801, `AttractMode`) begins when the atlas of its class has
 * downloaded in the background, with no HUD, no commentary and no sound of its own. Choosing an item disposes it. Esc does
 * nothing here. With an event in progress in the save (F-405) CONTINUE is the first item, with the next session named under it.
 */
export class TitleScene extends Phaser.Scene implements HasReadout {
  private menu: MenuList | null = null
  private ground: TrackRenderer | null = null
  private ribbon: CornerRibbon | null = null
  /** The version stamp at the right end of the key line. */
  private stamp: Phaser.GameObjects.BitmapText | null = null
  private parts: Phaser.GameObjects.GameObject[] = []
  private release: (() => void) | null = null
  private releaseMusicKey: (() => void) | null = null
  /** The key hint at the bottom, which says what the M key will do (F-705). */
  private hint: Phaser.GameObjects.BitmapText | null = null
  /** The logo, for the readout. */
  private logo: Phaser.GameObjects.Image | null = null
  private atlases: CoverAtlases | null = null
  /** The race behind the menu; null until its atlas has come, and after the scene has gone. */
  attract: AttractMode | null = null
  private view: WorldView | null = null
  /** The event in progress, ready to be continued; null when there is none (or the one that was saved cannot be run). */
  private resumable: RaceDayController | null = null
  private handled = 0

  constructor() {
    super('Title')
  }

  create(): void {
    this.handled = 0
    // Back at the title no controller is running (an event left here is kept in the save, and CONTINUE builds a new one): tools must not find a stale one.
    this.registry.remove(RACE_DAY_KEY)
    this.cameras.main.setBackgroundColor(THEME.colours.background)
    this.paintCover()
    // Everything made from here on is over the cars; what is made above (the ground and its dimming) is under them.
    const cover = new Set(this.children.list)
    this.paintName()

    this.resumable = RaceDayController.saved(cuencaRc)
    const top = this.resumable === null ? MENU_Y : MENU_Y_WITH_CONTINUE
    this.menu = new MenuList(this, { x: LEFT + 12, y: top }, this.resumable === null ? ITEMS : [CONTINUE, ...ITEMS], { size: 'large', anchor: 'left', pitch: this.resumable === null ? MENU_PITCH : MENU_PITCH_WITH_CONTINUE })
    if (this.resumable !== null) {
      // Which session is next, beside CONTINUE and clear of the widest item's highlight bar.
      const beside = LEFT + 12 + (2 + WIDEST_LABEL) * charWidth('large') + 36
      this.parts.push(text(this, { x: beside, y: top + Math.round((lineHeight('large') - lineHeight('small')) / 2) }, nextWords(this.resumable.nextHeading), 'small').setTint(THEME.colours.textDim))
    }
    this.menu.onConfirm((id) => {
      if (id === 'continue') this.resume()
      else if (id === 'practice') this.leave('Garage', { role: 'practice' })
      else if (id === 'quick-race') this.leave('Garage', { role: 'quick-race' })
      else if (id === 'race-day') this.leave('Garage', { role: 'race-day' })
      else if (id === 'leaderboards') this.leave('Leaderboard')
      else if (id === 'options') this.leave('Options', { from: 'title' })
      else if (id === 'credits') this.leave('Credits', {})
    })
    this.hint = text(this, { x: LEFT, y: LOGICAL_HEIGHT - 72 }, hintWords(musicOf(this.registry)?.enabled ?? false), 'small').setTint(THEME.colours.textDim)
    this.parts.push(this.hint)
    // The version and the commit the build was made from (F-805), at the right end of the key line.
    this.stamp = text(this, { x: LOGICAL_WIDTH - LEFT, y: LOGICAL_HEIGHT - 72 }, `V${stampShown(VERSION, cleanCapture(this.registry))}`, 'small').setOrigin(1, 0).setTint(THEME.colours.textDim)
    this.parts.push(this.stamp)
    // The DEMO ribbon is for builds that are not the shipped game: development, test and the demo build (F-805). The expression is written out in full, as in RaceScene.ts: the bundler does not fold a constant shared between modules, so the ribbon's drawing would stay in the production bundle.
    if (import.meta.env.DEV || import.meta.env.MODE === 'test' || import.meta.env.MODE === 'demo') {
      this.ribbon = new CornerRibbon(this, 'DEMO')
      this.ribbon.shown?.setDepth(DEPTH_RIBBON).setVisible(!cleanCapture(this.registry))
    }
    // The name, the menu and the hint are over the cars: whatever was made after the ground and its dimming and has no depth of its own yet.
    for (const object of this.children.list) if (!cover.has(object) && hasDepth(object) && object.depth === 0) object.setDepth(DEPTH_UI)

    // The race comes last and without holding anything up: the picture is complete without it.
    const seed = freshSeed()
    const carClass = CLASS_ORDER[seed % CLASS_ORDER.length]
    if (carClass !== undefined) this.atlases = loadCoverAtlases(this, [carClass], () => this.startAttract(carClass, seed))

    this.release = onNav(this, (key) => this.onKey(key))
    // The music (F-705): the title's piece plays on the title and in the garage, and M turns it off and on.
    const music = musicOf(this.registry)
    music?.play('title')
    const keyboard = this.input.keyboard
    if (keyboard !== null && music !== null) this.releaseMusicKey = onKey(keyboard, 'M', () => this.hint?.setText(hintWords(toggleMusic(this.registry))))
    // The graphics context was lost and is back (F-803): the baked track is empty, and is drawn again.
    this.game.events.on(GRAPHICS_RESTORED, this.rebake, this)
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, this.dispose, this)
  }

  /** Shows or hides the dev-build details (the DEMO ribbon, the commit in the stamp) as the clean-capture flag says, on the screen that is up (F-819). */
  applyCleanCapture(): void {
    const clean = cleanCapture(this.registry)
    this.ribbon?.shown?.setVisible(!clean)
    this.stamp?.setText(`V${stampShown(VERSION, clean)}`)
  }

  private rebake(): void {
    this.ground?.rebake()
  }

  /** The race behind the menu runs on the frame clock. */
  update(time: number): void {
    this.attract?.update(time)
  }

  readout(): ScreenReadout {
    return {
      focus: this.menu?.focus ?? null,
      values: {
        handled: this.handled,
        attractCars: this.attract?.info().cars ?? 0,
        ribbon: this.ribbon?.shown === null || this.ribbon === null ? 0 : 1,
        logo: this.logo === null ? '' : `${this.logo.x},${this.logo.y},${this.logo.displayWidth},${this.logo.displayHeight}`,
        continueNext: this.resumable?.nextHeading ?? '',
        music: this.hint?.text.includes('MUSIC ON') === true ? 1 : 0,
      },
    }
  }

  /** What the race behind the menu is doing, for the debug hook; null before it has begun. */
  attractInfo(): AttractInfo | null {
    return this.attract?.info() ?? null
  }

  /** The atlas has come: the race of the class begins, its pictures read from the atlas as it was loaded here. */
  private startAttract(carClass: CarClassId, seed: number): void {
    const { atlases, view } = this
    if (atlases === null || view === null || this.attract !== null) return
    const key = atlases.keyOf(carClass)
    const manifest = manifestOf(this)
    this.attract = new AttractMode(this, view, carClass, (name) => ({ ...directionSet(manifest, name), atlas: key }), seed)
  }

  /** CONTINUE: the event goes on at the session that was next. */
  private resume(): void {
    const controller = this.resumable
    if (controller === null) return
    this.stopListening()
    this.registry.set(RACE_DAY_KEY, controller)
    this.scene.start(controller.nextScene(), { controller } satisfies RaceDayFlowData)
  }

  /** The home track, baked exactly as the race bakes it, dimmed so that the race over it does not shout, and a darker veil behind the name and menu. */
  private paintCover(): void {
    const track = orientTrack(cuencaRc, 'counter-clockwise')
    const view = fitWorld(track.bounds, { w: LOGICAL_WIDTH, h: LOGICAL_HEIGHT }, 0)
    this.view = view
    this.ground = new TrackRenderer(this, track, view)
    this.ground.bake()
    this.parts.push(this.add.rectangle(0, 0, LOGICAL_WIDTH, LOGICAL_HEIGHT, THEME.colours.background, DIM_ALPHA).setOrigin(0, 0).setDepth(DEPTH_DIM))
    const veil = [
      this.add.rectangle(0, 0, VEIL_SOLID_PX, LOGICAL_HEIGHT, THEME.colours.background, VEIL_ALPHA).setOrigin(0, 0),
      // ...fading out towards the cars in even steps, so that no edge shows.
      ...Array.from({ length: VEIL_STEPS }, (_, i) =>
        this.add
          .rectangle(VEIL_SOLID_PX + i * VEIL_STEP_PX, 0, VEIL_STEP_PX, LOGICAL_HEIGHT, THEME.colours.background, (VEIL_ALPHA * (VEIL_STEPS - 1 - i)) / VEIL_STEPS)
          .setOrigin(0, 0),
      ),
    ]
    // A strip of chequers along the top and the bottom edge of the screen, over the veil, as a broadcast frames its picture.
    const chequer = still(manifestOf(this), CHEQUER)
    for (const y of [0, LOGICAL_HEIGHT - chequer.size.h * chequer.scale]) {
      this.parts.push(this.add.image(0, y, chequer.atlas, chequer.frame).setOrigin(0, 0).setScale(chequer.scale).setDepth(DEPTH_VEIL))
    }
    for (const piece of veil) piece.setDepth(DEPTH_VEIL)
    this.parts.push(...veil)
  }

  /** The logo where the name stood, and the line under it. */
  private paintName(): void {
    const art = still(manifestOf(this), LOGO)
    this.logo = this.add.image(LEFT, LOGO_TOP, art.atlas, art.frame).setOrigin(0, 0).setScale(art.scale)
    this.parts.push(this.logo)
    this.parts.push(text(this, { x: LEFT + 8, y: TAGLINE_Y }, TAGLINE, 'small').setTint(THEME.colours.textDim))
  }

  private onKey(key: NavKey): void {
    this.handled++
    this.menu?.handle(key)
  }

  /** Stops listening at once, so that a second press before the next scene appears does nothing, then changes scene; the race behind the menu is put away with the scene. */
  private leave(next: string, data: GarageSceneData | LeaderboardInit | { from: 'title' } | Record<string, never> = {}): void {
    this.stopListening()
    this.scene.start(next, data)
  }

  private stopListening(): void {
    this.release?.()
    this.release = null
    this.releaseMusicKey?.()
    this.releaseMusicKey = null
  }

  private dispose(): void {
    this.game.events.off(GRAPHICS_RESTORED, this.rebake, this)
    this.stopListening()
    // The race behind the menu first: its cars are the pictures that use the cover atlas.
    this.attract?.destroy()
    this.attract = null
    this.menu?.destroy()
    this.menu = null
    this.hint = null
    this.stamp = null
    this.ribbon?.destroy()
    this.ribbon = null
    this.ground?.destroy()
    this.ground = null
    for (const part of this.parts) part.destroy()
    this.parts = []
    this.resumable = null
    this.logo = null
    this.view = null
    // Last: the pictures that use the cover atlas are gone, and so is the atlas.
    this.atlases?.dispose()
    this.atlases = null
  }
}
