import { onPageKeys, type KeyLike, type PageKeyEvents } from './keys'
import { createCodeReader, type CodeReader } from './secret-code'

// Whether the tuning tools (the panel on T, the racing lines on L) are unlocked, kept where every scene can reach it (F-813).
// In development, test and demo builds they are on from the start. In the released game they are off until the player types
// the code (`secret-code.ts`), and then on until the page is reloaded: nothing is saved.

/** The registry key the state is kept under. */
export const TOOLS_KEY = 'mrr-tools-unlocked'
/** The game event sent once, when the tools are unlocked by the code. Scenes that are up listen for it. */
export const TOOLS_UNLOCKED = 'mrr-tools-unlocked'

/** The registry key the clean-capture flag is kept under (F-819): set only by the debug hook, never saved, gone on reload. */
export const CLEAN_CAPTURE_KEY = 'mrr-clean-capture'

/** The part of the game the gate uses, so that it is tested without an engine (`Phaser.Game` has both). */
export interface ToolsHost {
  registry: { get(key: string): unknown; set(key: string, value: unknown): unknown }
  events: { emit(event: string): unknown }
}

/** Whether the tools are unlocked. */
export function toolsUnlocked(registry: Pick<ToolsHost['registry'], 'get'>): boolean {
  return registry.get(TOOLS_KEY) === true
}

/** Whether a recording asked for the dev-build details to be hidden (F-819): the title's ribbon and commit, and the race's `T TUNE   L LINES`. */
export function cleanCapture(registry: Pick<ToolsHost['registry'], 'get'>): boolean {
  return registry.get(CLEAN_CAPTURE_KEY) === true
}

/** Whether the race's key hint names the tools: they are unlocked and a clean capture has not hidden them. The keys themselves work either way. */
export function toolsHinted(registry: Pick<ToolsHost['registry'], 'get'>): boolean {
  return toolsUnlocked(registry) && !cleanCapture(registry)
}

/** The version stamp as the title shows it: `1.0.0+d15e816` is `1.0.0` for a clean capture, and any other stamp is as it was. */
export function stampShown(version: string, clean: boolean): string {
  return clean ? version.replace(/\+.*$/, '') : version
}

/** Unlocks the tools and tells the scenes that are up. False, and nothing sent, if they already were. */
export function unlockTools(host: ToolsHost): boolean {
  if (toolsUnlocked(host.registry)) return false
  host.registry.set(TOOLS_KEY, true)
  host.events.emit(TOOLS_UNLOCKED)
  return true
}

export interface ToolsGateOptions {
  /** True where the tools are on from the start (development, test and demo builds): the code then does nothing. */
  startUnlocked: boolean
  /** True while a key press is a binding (the options screen waiting for a key), not a letter of the code. Asked at every key press. */
  capturing(): boolean
  /** Called once, when the code has just unlocked the tools: the sound, the line, the loading of the tools' code. */
  onUnlock(): void
}

/**
 * The one place the code is read (F-813): sets the state, and, in a build that starts locked, listens to every key press
 * on the page through the guarded helper and unlocks on the code. Returns the function that stops listening.
 */
export function watchForCode(host: ToolsHost, page: PageKeyEvents, options: ToolsGateOptions, reader: CodeReader = createCodeReader()): () => void {
  host.registry.set(TOOLS_KEY, options.startUnlocked)
  if (options.startUnlocked) return () => undefined
  return onPageKeys(page, (event: KeyLike) => {
    // A key held down repeats; and a key that is a binding is not a letter.
    if (event.repeat === true || toolsUnlocked(host.registry) || options.capturing()) return
    if (reader.feed(event) && unlockTools(host)) options.onUnlock()
  })
}
