import type { SaveData } from './storage'
import { saves } from './store'

// Whether the game speaks (F-703): the saved `tts` setting, off for a fresh save. The V key turns it on and off.

/** Whether speech is on, read from the game's save so that no screen has its own idea of it. */
export const speechOn = (): boolean => saves.read().settings.tts

/** The save with speech on or off; the same save, unchanged, if it already is. */
export function withSpeech(data: SaveData, on: boolean): SaveData {
  return on === data.settings.tts ? data : { ...data, settings: { ...data.settings, tts: on } }
}

/** Turns speech on if it is off and off if it is on, and remembers it. Returns the new state. */
export function toggleSpeech(): boolean {
  return saves.update((data) => withSpeech(data, !data.settings.tts)).settings.tts
}
