import type Phaser from 'phaser'
import type { TrackData } from '@sim'
import { still, type AssetManifest } from '../assets/manifest'
import type { WorldView } from '../config'
import { layoutDecor, snapCentre, undrawnDecor, type Layer } from './decor-layout'
import { DEPTH } from './depth'
import { LAYER, type DrawCommand } from './track-draw'

// The track's decor on screen (F-504): the driver stand and the pit tables, which lie flat, go into the baked ground;
// what stands up, the trees, is an image each, over everything but the HUD. Both are drawn once and never move.

/** Where each group of decor is among the race scene's layers. What is flat is in the ground and has no depth of its own. */
export const DECOR_DEPTH: Readonly<Record<Exclude<Layer, 'ground'>, number>> = {
  standing: DEPTH.people,
  canopy: DEPTH.canopy,
}

/** What the debug hook reports about one picture of the decor. */
export interface DecorSprite {
  sprite: string
  layer: Layer
  item: number
  /** The cell's centre on the 1920 x 1080 canvas. */
  x: number
  y: number
  /** Whether it lies in the baked ground (`depth` is then the ground's) or is an image of its own. */
  baked: boolean
  depth: number
}

/** The part of the ground renderer that the decor needs. */
export interface BakeTarget {
  addToBake(commands: DrawCommand[]): void
}

export class DecorLayer {
  private images: Phaser.GameObjects.Image[] = []
  private readonly shown: DecorSprite[] = []

  /**
   * Hands what lies flat to `ground` (call before `ground.bake()`) and puts up what stands. The atlases the decor
   * uses must be loaded. A kind of decor with no picture is left out, and `onUndrawn` is told its name once (the race
   * scene passes a console warning in development builds and nothing in production).
   */
  constructor(scene: Phaser.Scene, view: WorldView, track: TrackData, manifest: AssetManifest, ground: BakeTarget, onUndrawn?: (kind: string) => void) {
    for (const kind of undrawnDecor(track)) onUndrawn?.(kind)
    const commands: DrawCommand[] = []
    for (const placement of layoutDecor(track, view.pxPerM)) {
      const art = still(manifest, placement.sprite)
      const wPx = art.size.w * art.scale * placement.scaleX
      const hPx = art.size.h * art.scale * placement.scaleY
      const x = snapCentre(view.originX + placement.x, wPx)
      const y = snapCentre(view.originY + placement.y, hPx)
      if (placement.layer === 'ground') {
        commands.push({ op: 'sprite', layer: LAYER.props, atlas: art.atlas, frame: art.frame, x: placement.x / view.pxPerM, y: placement.y / view.pxPerM, scale: art.scale, wPx, hPx })
      } else {
        const image = scene.add
          .image(x, y, art.atlas, art.frame)
          .setOrigin(art.pivot.x, art.pivot.y)
          .setScale(art.scale * placement.scaleX, art.scale * placement.scaleY)
          .setRotation(placement.angle)
          .setDepth(DECOR_DEPTH[placement.layer])
        this.images.push(image)
      }
      const depth = placement.layer === 'ground' ? DEPTH.ground : DECOR_DEPTH[placement.layer]
      this.shown.push({ sprite: placement.sprite, layer: placement.layer, item: placement.item, x, y, baked: placement.layer === 'ground', depth })
    }
    ground.addToBake(commands)
  }

  /** Every picture of the decor and where it is, for the debug hook and the tests. */
  sprites(): DecorSprite[] {
    return this.shown.map((one) => ({ ...one }))
  }

  /** How many images of its own the decor holds (what is in the ground is not one). */
  imageCount(): number {
    return this.images.length
  }

  destroy(): void {
    for (const image of this.images) image.destroy()
    this.images = []
    this.shown.length = 0
  }
}
