/**
 * How the track looks: colours, widths and grain. Every colour is from the shared palette in
 * spec/00-product/art-direction.md; the infield green is the one the palette leaves to F-105 and is the
 * Green ramp's "shade" step (a green body, whose base is lighter, stays visible against it).
 */
export interface TrackStyle {
  asphalt: number
  infieldGrass: number
  outfieldGrass: number
  barrier: number
  barrierWidthM: number
  edgeLine: number
  /** Width of a painted line that carries none of its own. */
  edgeLineWidthM: number
  kerbRed: number
  kerbWhite: number
  /** Length of one red or white kerb stripe along its kerb. */
  kerbStripeM: number
  marker: number
  /** A pit block's ground, the red lines that divide the blocks and the width of those lines. */
  pitBlock: number
  pitDivider: number
  pitDividerWidthM: number
  /** The numbers in the pit blocks and in the start boxes: colour and the height of their digits. */
  pitNumber: number
  pitNumberHeightM: number
  startNumber: number
  startNumberHeightM: number
  /** Share of the asphalt's pixels that carry a fleck of grain, 0 to 1. */
  grainStrength: number
  grainSeed: number
  /**
   * Surface detail (F-802), all procedural, seeded and faint. Nothing of it is laid within `detailClearM` of a painted
   * line, a kerb or a barrier, or within `puddleClearM` of a puddle spot's edge, so the asphalt beside each of them is
   * exactly the asphalt colour: the detail cannot lower the contrast of any of them.
   *
   * The rubbered-in racing line: the line a car `rubberCarWidthM` wide drives, as two bands of ink, `rubberWidthM` and
   * half that wide, each at `rubberStrength` (an alpha), so the middle of the line is the darkest. 0 draws none.
   */
  rubberWidthM: number
  rubberStrength: number
  rubberCarWidthM: number
  /** Cracks in the asphalt, in the grain colour: how many a square metre of asphalt, their width, and their seed. */
  crackStrength: number
  crackWidthM: number
  crackSeed: number
  /** Wear on the painted marks (the start boxes and the dashed line, never a lane edge): the share of their paint gone back to asphalt, in flecks a screen pixel across. */
  lineWearStrength: number
  lineWearSeed: number
  detailClearM: number
  puddleClearM: number
}

export const DEFAULT_STYLE: TrackStyle = {
  asphalt: 0x5a5d68,
  infieldGrass: 0x1c7e40,
  outfieldGrass: 0x4f8a3c,
  barrier: 0xa81e34,
  barrierWidthM: 0.04,
  edgeLine: 0xe8ecf2,
  edgeLineWidthM: 0.05,
  kerbRed: 0xd8323a,
  kerbWhite: 0xeef1f6,
  kerbStripeM: 0.2,
  marker: 0x22242e,
  pitBlock: 0xeef1f6,
  pitDivider: 0xd8323a,
  pitDividerWidthM: 0.03,
  pitNumber: 0x22242e,
  // Digits are drawn a whole number of screen pixels per art pixel of the font (7 high at 90 px/m, so 1 and 2).
  pitNumberHeightM: 14 / 90,
  startNumber: 0xe8ecf2,
  startNumberHeightM: 7 / 90,
  grainStrength: 0.03,
  grainSeed: 20261007,
  rubberWidthM: 0.26,
  rubberStrength: 0.035,
  rubberCarWidthM: 0.19,
  crackStrength: 0.12,
  crackWidthM: 1.2 / 90,
  crackSeed: 20261016,
  lineWearStrength: 0.06,
  lineWearSeed: 20261017,
  detailClearM: 0.05,
  puddleClearM: 0.12,
}

/** A tyre marker seen from above, all from the palette's shared materials: ink, carbon, and the lighter carbon steps. */
export const TYRE_COLORS = { ink: 0x16161e, rubber: 0x22242e, sidewall: 0x3a3d4a, highlight: 0x5a5e6e } as const

/** Asphalt grain fleck (palette: asphalt grain); the cracks are drawn in it too (F-802). */
export const GRAIN_COLOR = 0x4c4f5a
/** The rubbered-in line (F-802): ink, the darkest colour in the game, at a faint strength, as the skid marks are. */
export const RUBBER_COLOR = 0x16161e
/** A fleck of worn paint is this much of the world across: about a screen pixel at the home track's 90 px/m. */
export const WEAR_FLECK_M = 1 / 90
/** Outfield tuft blades, dark and light (palette: Green shade and light). */
export const TUFT_COLORS = { dark: 0x1c7e40, light: 0x5cc85a } as const
/** Tufts are laid this many times as densely as the asphalt grain. */
export const TUFT_DENSITY = 2

/** The chequered strip: squares of about this size, in this many rows across the direction of travel. */
export const CHECKER_SQUARE_M = 0.12
export const CHECKER_ROWS = 2
/** Palette: the kerb white and ink. */
export const CHECKER_COLORS = { light: 0xeef1f6, dark: 0x16161e } as const

/** Screen footprint, in pixels, of one grain fleck and of one tuft. Fixes how many of each a strength means. */
export const GRAIN_FLECK_PX = 2
export const TUFT_PX = 3

/**
 * The ground is baked at this many times the screen's resolution and shown at 1/BAKE_SCALE with linear
 * filtering: each screen pixel is then the exact average of BAKE_SCALE x BAKE_SCALE baked pixels, which is what
 * makes every painted edge smooth. Nothing else in the game is filtered; shapes laid on whole screen pixels
 * stay as crisp as they were drawn.
 */
export const BAKE_SCALE = 2

/**
 * The pixel font's digits (public/assets/font.retro.json): a cell is `advance` art pixels wide and holds a glyph
 * `inkCols` wide; capitals and digits stand on `capRows` rows starting `capTop` rows down the cell.
 */
export const GLYPH = { advance: 6, inkCols: 5, capTop: 2, capRows: 7 } as const
/** The texture the font's glyphs are read from (the manifest's `pixel` font atlas), and how a character names its frame. */
export const FONT_ATLAS = 'font'
export const glyphFrame = (char: string): string => `font/${char.charCodeAt(0).toString(16).padStart(4, '0')}`
