import type Phaser from 'phaser'
import { animation, type Animation } from '../assets/animation'
import { still, type AssetManifest } from '../assets/manifest'
import { text } from '../ui/text'
import { THEME, lineHeight, type TextSize } from '../ui/theme'
import { DEPTH } from './depth'
import type { Speaker, Window } from './CommentaryDirector'
import { BUBBLE, bubbleRegion, layoutBubble, layoutCommentary, officialWindow, type BubbleLayout, type PixelRect } from './hud-format'

// The window (F-509, F-703): a portrait at the bottom left of the screen, over the trees, and the speech bubble beside
// it that carries every word the game has for the player. Two speakers share it, the race official and the commentator
// (one portrait, one bubble, whoever is talking: the owner's ruling); the director (CommentaryDirector) says who. The
// official's words are drawn as big as they need and keep the tone the message table gives them; the commentator's are
// small, in as many as three lines. With nobody talking there is no bubble and the resting speaker (the official, in a race; the commentator on a result screen, F-809) blinks now and then. The
// bubble is a nine-slice of `ui.bubble.*` (the HUD's dark colours). `Bubble` is the nine-slice itself, which the HELP!
// bubbles over the drivers use too.

/** The pieces of a nine-slice, in the order they are made. */
const PIECES = ['nw', 'n', 'ne', 'w', 'c', 'e', 'sw', 's', 'se'] as const
type Piece = (typeof PIECES)[number]

export type BubbleTail = 'left' | 'down'

/** One piece of a bubble: the image, and the size the picture has in art pixels (for the stretch). */
interface Slice {
  image: Phaser.GameObjects.Image
  piece: Piece
}

/**
 * A speech bubble of any size, put together from the pieces of a skin (`ui.bubble` or `ui.bubble-small`): the four
 * corners as they are, the edges and the middle stretched (they are the same along their length), and a tail whose
 * pivot is put on the bubble's edge. Everything is hidden until `place` is called.
 */
export class Bubble {
  private readonly slices: Slice[]
  private readonly tail: Phaser.GameObjects.Image
  private readonly corner: number
  private readonly kind: BubbleTail

  /** `atlas` must be loaded. Every part is at `depth`. */
  constructor(scene: Phaser.Scene, manifest: AssetManifest, skin: 'bubble' | 'bubble-small', kind: BubbleTail, depth: number) {
    this.kind = kind
    const nw = still(manifest, `ui.${skin}.nw`)
    this.corner = nw.size.w * nw.scale
    this.slices = PIECES.map((piece) => {
      const art = still(manifest, `ui.${skin}.${piece}`)
      return { piece, image: scene.add.image(0, 0, art.atlas, art.frame).setOrigin(art.pivot.x, art.pivot.y).setDepth(depth).setVisible(false) }
    })
    const tail = still(manifest, `ui.${skin}.tail-${kind}`)
    // The tail is drawn after the edge, whose rim it opens.
    this.tail = scene.add.image(0, 0, tail.atlas, tail.frame).setOrigin(tail.pivot.x, tail.pivot.y).setScale(tail.scale).setDepth(depth).setVisible(false)
  }

  /** Lays the bubble out with its body (without the tail) in `box`, the tail's pivot `along` px along the left edge (or the bottom edge, for a tail that points down). */
  place(box: PixelRect, along: number): void {
    const c = this.corner
    const { x, y, w, h } = box
    const inner = { w: w - 2 * c, h: h - 2 * c }
    const at: Record<Piece, [number, number, number, number]> = {
      nw: [x, y, c, c],
      n: [x + c, y, inner.w, c],
      ne: [x + w - c, y, c, c],
      w: [x, y + c, c, inner.h],
      c: [x + c, y + c, inner.w, inner.h],
      e: [x + w - c, y + c, c, inner.h],
      sw: [x, y + h - c, c, c],
      s: [x + c, y + h - c, inner.w, c],
      se: [x + w - c, y + h - c, c, c],
    }
    for (const { image, piece } of this.slices) {
      const [px, py, pw, ph] = at[piece]
      image.setPosition(px, py).setDisplaySize(pw, ph).setVisible(true)
    }
    if (this.kind === 'left') this.tail.setPosition(x, y + along)
    else this.tail.setPosition(x + along, y + h)
    this.tail.setVisible(true)
  }

  hide(): void {
    for (const { image } of this.slices) image.setVisible(false)
    this.tail.setVisible(false)
  }

  /** Whether the bubble is on screen. */
  get shown(): boolean {
    return this.tail.visible
  }

  destroy(): void {
    for (const { image } of this.slices) image.destroy()
    this.tail.destroy()
  }
}

/** What the debug hook reports about the official. */
export interface OfficialInfo {
  /** Whose portrait is in the window: the official's, or the commentator's while he talks. */
  speaker: Speaker
  /** The speaker is talking: words are up. */
  talking: boolean
  /** The words in the bubble, on one line (the bubble may break them over two or, for the commentator, three), or null when there is no bubble. */
  text: string | null
  /** The lines as the bubble shows them. */
  lines: string[]
  /** Their size, null with no bubble. */
  size: TextSize | null
  /** The animation and frame on show. */
  clip: 'idle' | 'talk'
  frame: string
  /** The portrait window on the 1920 x 1080 canvas. */
  window: PixelRect
  /** The bubble, tail included, on the same canvas; null with no bubble. */
  bubble: PixelRect | null
}

/** A blink every this many seconds of session time, and the animation of it is the two frames of `official.idle`. */
export const BLINK_EVERY_S = 3.4

/** Which frame of a clip shows `sinceS` seconds in: looping ones go round, the others stop on their last frame. */
export function clipFrame(clip: Pick<Animation, 'frames' | 'fps' | 'loop'>, sinceS: number): number {
  const frame = Math.floor(Math.max(0, sinceS) * clip.fps)
  return clip.loop ? frame % clip.frames.length : Math.min(frame, clip.frames.length - 1)
}

/** The frame of the blink at `timeS`: the first frame at rest, the pair played through once every `BLINK_EVERY_S`. */
export function blinkFrame(clip: Pick<Animation, 'frames' | 'fps'>, timeS: number): number {
  const into = ((timeS % BLINK_EVERY_S) + BLINK_EVERY_S) % BLINK_EVERY_S
  return into < clip.frames.length / clip.fps ? Math.floor(into * clip.fps) : 0
}

/** The portrait's two animations for one speaker. */
interface Clips {
  idle: Animation
  talk: Animation
}

/** The most lines any bubble has: the commentator's. */
const MOST_LINES = 3

export class Official implements Window {
  private readonly window: PixelRect
  private readonly region: PixelRect
  private readonly portrait: Phaser.GameObjects.Image
  private readonly clips: Record<Speaker, Clips>
  private readonly bubble: Bubble
  private readonly lines: Phaser.GameObjects.BitmapText[] = []
  private layout: BubbleLayout | null = null
  private words: string | null = null
  private speaker: Speaker
  /** Whose portrait is in the window when nobody talks: the official's in a race, the commentator's on a result screen, where the official has nothing to say. */
  private readonly resting: Speaker
  private timeS = 0
  private talkSinceS = 0
  private clip: 'idle' | 'talk' = 'idle'
  private frame = 0

  /**
   * `bandTop` is the stand's upper edge, the top of the band; `standLeft` its left edge, where the bubble stops (null with
   * no stand). The window is at the left margin unless `left` says otherwise (a result screen with no room there). `resting` is whose
   * portrait is there while nobody talks (F-809): the official's, unless the screen is one he never speaks on. The atlas `ui` must be loaded.
   */
  constructor(scene: Phaser.Scene, manifest: AssetManifest, bandTop: number, standLeft: number | null, left?: number, resting: Speaker = 'official') {
    this.resting = resting
    this.speaker = resting
    this.window = officialWindow(bandTop, left)
    this.region = bubbleRegion(this.window, standLeft)
    this.clips = {
      official: { idle: animation(manifest, 'official.idle'), talk: animation(manifest, 'official.talk') },
      commentator: { idle: animation(manifest, 'commentator.idle'), talk: animation(manifest, 'commentator.talk') },
    }
    const { idle } = this.clips[resting]
    // Over the trees, which stand behind his window.
    this.portrait = scene.add
      .image(this.window.x + this.window.w / 2, this.window.y + this.window.h / 2, idle.atlas, idle.frames[0])
      .setOrigin(idle.pivot.x, idle.pivot.y)
      .setScale(idle.scale)
      .setDepth(DEPTH.hud)
    this.bubble = new Bubble(scene, manifest, 'bubble', 'left', DEPTH.hud + 1)
    for (let i = 0; i < MOST_LINES; i++) this.lines.push(text(scene, { x: 0, y: 0 }, '', 'body').setDepth(DEPTH.hud + 2).setVisible(false))
  }

  /**
   * `speaker` talks: his portrait is in the window and `words` are in the bubble in `colour`, laid out as `size` says
   * (the official's as big as they need, the commentator's small and in up to three lines). The same words again only
   * change the colour; new words, or another speaker, lay the bubble out afresh.
   */
  show(speaker: Speaker, words: string, colour: number, size: 'official' | 'commentary'): void {
    for (const line of this.lines) line.setTint(colour)
    if (words === this.words && speaker === this.speaker) return
    if (this.words === null || speaker !== this.speaker) this.talkSinceS = this.timeS
    this.words = words
    this.speaker = speaker
    const layout = size === 'commentary' ? layoutCommentary(words, this.region) : layoutBubble(words, this.region)
    this.layout = layout
    this.bubble.place(layout.box, layout.tailAlong)
    const scale = THEME.sizes[layout.size]
    this.lines.forEach((line, i) => {
      const value = layout.lines[i]
      if (value === undefined) return void line.setVisible(false)
      line
        .setText(value)
        .setScale(scale)
        .setTint(colour)
        .setPosition(layout.box.x + BUBBLE.inset, layout.box.y + BUBBLE.inset + i * lineHeight(layout.size))
        .setVisible(true)
    })
  }

  /** Nobody talks: the bubble goes and the resting speaker (the official, unless the window was made for another) is in the window at rest. */
  rest(): void {
    this.speaker = this.resting
    if (this.words === null) return
    this.words = null
    this.layout = null
    this.bubble.hide()
    for (const line of this.lines) line.setVisible(false)
  }

  /** Brings the portrait to `timeS` on the sim's clock (so that a pause holds him still). Call it every frame. */
  update(timeS: number): void {
    this.timeS = timeS
    const talking = this.words !== null
    this.clip = talking ? 'talk' : 'idle'
    const clips = this.clips[this.speaker]
    const clip = talking ? clips.talk : clips.idle
    this.frame = talking ? clipFrame(clip, timeS - this.talkSinceS) : blinkFrame(clip, timeS)
    this.portrait.setFrame(clip.frames[this.frame] ?? clip.frames[0])
  }

  /** What he is doing and where, for the debug hook and the tests. */
  info(): OfficialInfo {
    const { layout } = this
    const clips = this.clips[this.speaker]
    const clip = this.clip === 'talk' ? clips.talk : clips.idle
    return {
      speaker: this.speaker,
      talking: this.words !== null,
      text: this.words,
      lines: layout?.lines ?? [],
      size: layout?.size ?? null,
      clip: this.clip,
      frame: clip.frames[this.frame] ?? clip.frames[0],
      window: { ...this.window },
      bubble: layout === null ? null : { x: layout.box.x - BUBBLE.tail, y: layout.box.y, w: layout.box.w + BUBBLE.tail, h: layout.box.h },
    }
  }

  destroy(): void {
    this.portrait.destroy()
    this.bubble.destroy()
    for (const line of this.lines) line.destroy()
    this.lines.length = 0
  }
}
