import Phaser from 'phaser'
import type { CarId, CarSnapshot } from '@sim'
import type { WorldView } from '../config'
import { DEPTH } from './depth'
import {
  RUBBER,
  rubberFor,
  RubberLayer,
  slipRatios,
  TYRE_SLIP,
  type MarkedCar,
  type Stamp,
  type TyreSlip,
  type WheelGeometry,
} from './car-effects'
import type { RenderCar } from './interpolate'

/** What the layer needs to know of each car: where its tyres are. */
export interface SkidCar {
  geometry: WheelGeometry
}

/** What the layer has done, for the debug hook and the soak. */
export interface SkidStats {
  /** Stamps made since the session began, and in the latest frame. */
  stamps: number
  stampsLastFrame: number
  /** The texture's size in pixels and its memory, bytes (RGBA, one byte a channel). */
  width: number
  height: number
  bytes: number
  /** How many pixels of the track carry any rubber, and the darkest of them, 0..1. */
  coveredPx: number
  darkest: number
}

/**
 * The rubber on the track (F-205): one screen-sized texture, stamped into as the cars move and shown as one image
 * over the ground and under the cars. Every frame the stamps the cars' wheels call for are put on it and it is
 * rendered once, so what a frame costs depends on how far the cars went, not on how much has been laid (ADR-001).
 * The mapping from what the sim reports to where and how dark is `car-effects.ts`, which knows nothing of Phaser.
 * A scene creates it, calls `update` each frame and `destroy()`s it on shutdown; a new scene makes a new, empty one.
 */
export class SkidLayer {
  static readonly TEXTURE_KEY = 'skid-layer'
  static readonly STAMP_KEY = 'skid-stamp'

  private readonly layer: RubberLayer
  private readonly texture: Phaser.Textures.DynamicTexture
  private image: Phaser.GameObjects.Image | null
  private readonly marked: MarkedCar[] = []
  private readonly emit: (stamp: Stamp) => void
  private stamped = 0
  private stampsLast = 0
  private destroyed = false

  constructor(
    private readonly scene: Phaser.Scene,
    view: WorldView,
    private readonly cars: readonly SkidCar[],
    private readonly tyre: TyreSlip = TYRE_SLIP,
  ) {
    const { textures } = scene
    // A texture left behind by a scene that did not clean up would otherwise be found instead of replaced.
    for (const key of [SkidLayer.TEXTURE_KEY, SkidLayer.STAMP_KEY]) if (textures.exists(key)) textures.remove(key)

    const { width, height } = scene.scale
    const texture = textures.addDynamicTexture(SkidLayer.TEXTURE_KEY, width, height)
    if (texture === null) throw new Error('SkidLayer: the skid texture could not be created')
    this.texture = texture

    // One opaque pixel in the colour of rubber: each stamp is this, stretched to the mark's size, at the alpha it lays.
    const stamp = textures.createCanvas(SkidLayer.STAMP_KEY, 1, 1)
    if (stamp === null) throw new Error('SkidLayer: the stamp texture could not be created')
    const context = stamp.getContext()
    context.fillStyle = `#${RUBBER.colour.toString(16).padStart(6, '0')}`
    context.fillRect(0, 0, 1, 1)
    stamp.refresh()

    this.layer = new RubberLayer(view, { w: width, h: height }, cars.map((car) => car.geometry))
    this.emit = (s) => {
      this.texture.stamp(SkidLayer.STAMP_KEY, undefined, s.x, s.y, { alpha: s.alpha, scale: s.size, originX: 0, originY: 0 })
      this.stamped++
      this.stampsLast++
    }
    this.image = scene.add.image(0, 0, SkidLayer.TEXTURE_KEY).setOrigin(0, 0).setDepth(DEPTH.skids)
    scene.events.once(Phaser.Scenes.Events.SHUTDOWN, this.destroy, this)
  }

  /** Lets a car lay rubber or stops it; the wet track stops marks (F-603). */
  setEnabledFor(car: CarId, enabled: boolean): void {
    this.layer.setEnabledFor(car, enabled)
  }

  /**
   * Lays this frame's rubber: `cars` are the cars as drawn (the pose and the use of each axle's grip, blended between
   * ticks) and `snapshots` the sim's latest, for what is not blended (where the car is, how it moves). One render
   * for the frame, and none when nothing was laid.
   */
  update(cars: readonly RenderCar[], snapshots: readonly CarSnapshot[]): void {
    if (this.destroyed) return
    this.marked.length = 0
    for (const car of cars) {
      const snap = snapshots[car.id]
      const spec = this.cars[car.id]
      if (snap === undefined || spec === undefined) continue
      this.marked.push({ id: car.id, pose: { x: car.x, y: car.y, angle: car.angle }, rubber: rubberFor(car, slipRatios(snap, spec.geometry, this.tyre), snap) })
    }
    this.stampsLast = 0
    this.layer.lay(this.marked, this.emit)
    if (this.stampsLast > 0) this.texture.render()
  }

  /** What has been laid. */
  stats(): SkidStats {
    const { grid } = this.layer
    let coveredPx = 0
    let darkest = 0
    for (let y = 0; y < grid.height; y++) {
      for (let x = 0; x < grid.width; x++) {
        const alpha = grid.at(x, y)
        if (alpha > 0) coveredPx++
        if (alpha > darkest) darkest = alpha
      }
    }
    return {
      stamps: this.stamped,
      stampsLastFrame: this.stampsLast,
      width: this.texture.width,
      height: this.texture.height,
      bytes: this.texture.width * this.texture.height * 4,
      coveredPx,
      darkest,
    }
  }

  /** How much rubber is on a pixel of the screen, 0 for none up to the darkest a pixel is let reach. */
  alphaAt(x: number, y: number): number {
    return this.layer.grid.at(Math.round(x), Math.round(y))
  }

  destroy(): void {
    if (this.destroyed) return
    this.destroyed = true
    this.scene.events.off(Phaser.Scenes.Events.SHUTDOWN, this.destroy, this)
    this.image?.destroy()
    this.image = null
    const { textures } = this.scene
    for (const key of [SkidLayer.TEXTURE_KEY, SkidLayer.STAMP_KEY]) if (textures.exists(key)) textures.remove(key)
  }
}
