import Phaser from 'phaser'
import { gameFile } from './base'
import { isRecord, type AssetManifest } from './sprites'

export * from './sprites'

const descriptorKey = (font: string): string => `font-descriptor-${font}`

/** Which atlases a set of fonts draws from. */
function fontAtlases(manifest: AssetManifest): Set<string> {
  return new Set(Object.values(manifest.fonts).map((font) => font.atlas))
}

/**
 * Puts one atlas of the manifest into the scene's loader unless it is already in the texture cache (ADR-005: only
 * what a screen needs is loaded). Does not start the loader: call it from `preload`, which does. Returns true if the
 * atlas was queued.
 */
export function queueAtlas(scene: Phaser.Scene, manifest: AssetManifest, key: string): boolean {
  if (scene.textures.exists(key)) return false
  const atlas = manifest.atlases.find((one) => one.key === key)
  if (atlas === undefined) throw new Error(`The manifest has no atlas '${key}'`)
  scene.load.atlas(key, gameFile(atlas.image), gameFile(atlas.data))
  return true
}

/**
 * The atlas of the UI skin (F-802): every panel, focus bar and the title's logo are drawn from it, so it is loaded with the
 * fonts, before the title.
 */
export const SKIN_ATLAS = 'skin'

/**
 * Puts the files for the fonts (their atlases and descriptors) and the UI skin, or for everything else, into the scene's
 * loader and returns how many were queued. Fonts and skin go first so that the first screen can already use them.
 */
export function queueAssets(scene: Phaser.Scene, manifest: AssetManifest, which: 'fonts' | 'rest'): number {
  const first = fontAtlases(manifest)
  first.add(SKIN_ATLAS)
  let queued = 0
  for (const atlas of manifest.atlases) {
    if (first.has(atlas.key) !== (which === 'fonts')) continue
    scene.load.atlas(atlas.key, gameFile(atlas.image), gameFile(atlas.data))
    queued += 2
  }
  if (which === 'fonts') {
    for (const [name, font] of Object.entries(manifest.fonts)) {
      scene.load.json(descriptorKey(name), gameFile(font.descriptor))
      queued++
    }
  }
  return queued
}

function isRetroConfig(value: unknown): value is Phaser.Types.GameObjects.BitmapText.RetroFontConfig {
  return (
    isRecord(value) &&
    typeof value.image === 'string' &&
    typeof value.width === 'number' &&
    typeof value.height === 'number' &&
    typeof value.chars === 'string' &&
    typeof value.charsPerRow === 'number' &&
    typeof value['offset.x'] === 'number' &&
    typeof value['offset.y'] === 'number' &&
    typeof value['spacing.x'] === 'number' &&
    typeof value['spacing.y'] === 'number' &&
    typeof value.lineSpacing === 'number'
  )
}

/**
 * Registers every font in the manifest as a bitmap font under its manifest name (`pixel`), so that
 * `add.bitmapText(x, y, 'pixel', ...)` works. The descriptor's texture key is the atlas's, which must be loaded.
 */
export function registerFonts(scene: Phaser.Scene, manifest: AssetManifest): void {
  for (const [name, font] of Object.entries(manifest.fonts)) {
    if (scene.cache.bitmapFont.exists(name)) continue
    const descriptor: unknown = scene.cache.json.get(descriptorKey(name))
    if (!isRecord(descriptor) || !isRetroConfig(descriptor.config)) throw new Error(`Font '${name}': descriptor ${font.descriptor} is not a retro-font config`)
    if (descriptor.config.image !== font.atlas) throw new Error(`Font '${name}': its descriptor names texture '${descriptor.config.image}', not the atlas '${font.atlas}'`)
    scene.cache.bitmapFont.add(name, Phaser.GameObjects.RetroFont.Parse(scene, descriptor.config))
  }
}

/** The display scale of a font: how many screen pixels one art pixel of its glyphs covers. */
export function fontScale(manifest: AssetManifest, name: string): number {
  const font = manifest.fonts[name]
  if (font === undefined) throw new Error(`The manifest has no font named '${name}'`)
  return 1 / font.artPixelsPerScreenPixel
}
