import type Phaser from 'phaser'
import type { CarSnapshot, SessionConfig } from '@sim'
import { LOGICAL_HEIGHT } from '../config'
import { PANEL_NAME } from '../ui/layout'
import { Skin } from '../ui/skin'
import { THEME } from '../ui/theme'
import { DEPTH } from './depth'
import { BAND_EDGE, BAND_GAP, PLATE_PAD, hintLines, hintsPlate } from './hud-format'
import { ASSISTED_MARK } from './assistance'

/** The pixel font's glyph cell in art pixels (public/assets/manifest.json). */
const CELL_W = 6
const CELL_H = 12
const PADDING_PX = 12
/** Flat panel behind the text: the game's darkest ink (art-direction.md), mostly opaque. */
const PANEL_COLOR = 0x16161e
const PANEL_ALPHA = 0.78
const TEXT_COLOR = 0xeef1f6
const HINT_COLOR = 0xc9d6e2
/** A line of the hints: the font's cell height at the hints' 2x. */
const HINT_LINE_PX = CELL_H * 2
const LINES = 3
/** The widest line, 'LAST  0:25.066', in characters. The readout is no wider with DRIVING ASSISTANCE: wider, it would reach the driver stand. */
const COLUMNS = 14
/** The scale of the (A*) mark under the best lap (F-811): the hints' size, so that the taller readout stays below the road. */
const MARK_SCALE = 2

/**
 * What a practice session always has (F-810): no penalties and reverse on, whatever the config was handed (the title, the
 * garage, a restart from the pause menu, the tuning panel's class change, the debug hook), so that no other screen's last
 * choice reaches it. A heat or a final keeps the settings it is given.
 */
export function practiceSettings(config: SessionConfig): SessionConfig {
  if (config.kind !== 'practice') return config
  return { ...config, penalties: { enabled: false, holdS: config.penalties?.holdS ?? 5 }, reverse: true }
}

/** A lap time as minutes, seconds and milliseconds: 0:25.066. Null (no such lap yet) is dashes. */
export function formatLapTime(ms: number | null): string {
  if (ms === null) return '-:--.---'
  const total = Math.round(ms)
  const minutes = Math.floor(total / 60000)
  const seconds = Math.floor((total % 60000) / 1000)
  const millis = total % 1000
  return `${minutes}:${String(seconds).padStart(2, '0')}.${String(millis).padStart(3, '0')}`
}

/**
 * The lines of the practice readout for one car: laps completed, last lap, best lap. In a session driven with DRIVING
 * ASSISTANCE (F-811) the best lap has (A*) under its time, on a fourth line, once there is one.
 */
export function readoutLines(car: Pick<CarSnapshot, 'lap' | 'lastLapMs' | 'bestLapMs'>, assisted = false): string[] {
  const lines = [`LAPS  ${car.lap}`, `LAST  ${formatLapTime(car.lastLapMs)}`, `BEST  ${formatLapTime(car.bestLapMs)}`]
  if (assisted) lines.push(car.bestLapMs === null ? '' : ASSISTED_MARK)
  return lines
}

/**
 * The plain text readout of practice mode (the real HUD is F-304): laps completed, last lap and best lap, on a flat
 * dark panel at the foot of the screen, and the key hints on a plate of their own, two lines, at the right end, with the
 * readout to the left of them (F-509): the left of the screen is the official's, the middle the driver stand's. All text
 * is the game's pixel font, an integer multiple of its glyph.
 */
export class PracticeReadout {
  private readonly panel: Phaser.GameObjects.Rectangle
  private readonly text: Phaser.GameObjects.BitmapText
  /** The (A*) under the best lap, at the hints' size and right-aligned under its time (F-811); null in a session without DRIVING ASSISTANCE. */
  private readonly mark: Phaser.GameObjects.BitmapText | null
  private readonly hintPanel: Phaser.GameObjects.Rectangle
  private readonly hint: Phaser.GameObjects.BitmapText[]
  /** The frames of the two plates, in the HUD's skin (F-802). */
  private readonly frames: Skin[]
  /** The readout panel's size and the text's scale, kept to lay the panel out again when the hints change (F-813). */
  private readonly size: { w: number; h: number; scale: number }
  private shown = ''

  /** `assisted`: the session is driven with DRIVING ASSISTANCE, and the best lap carries the mark, on a line of its own (F-811). */
  constructor(scene: Phaser.Scene, font: string, scale: number, hint: string, private readonly assisted = false) {
    const width = COLUMNS * CELL_W * scale + 2 * PADDING_PX
    const height = LINES * CELL_H * scale + (assisted ? CELL_H * MARK_SCALE : 0) + 2 * PADDING_PX
    // The key hints: one plate at the right end of the foot of the screen, the driving keys on its first line; the readout stands left of it.
    const lines = hintLines(hint)
    const plate = hintsPlate(lines)
    const left = plate.x - BAND_GAP - width
    const top = LOGICAL_HEIGHT - BAND_EDGE - height
    this.size = { w: width, h: height, scale }
    this.panel = scene.add.rectangle(left, top, width, height, PANEL_COLOR, PANEL_ALPHA).setOrigin(0, 0).setDepth(DEPTH.hud).setName(PANEL_NAME)
    this.text = scene.add
      .bitmapText(left + PADDING_PX, top + PADDING_PX, font, '')
      .setScale(scale)
      .setTint(TEXT_COLOR)
      .setDepth(DEPTH.hud + 1)
    this.mark = assisted
      ? scene.add
          .bitmapText(left + width - PADDING_PX - ASSISTED_MARK.length * CELL_W * MARK_SCALE, top + PADDING_PX + LINES * CELL_H * scale, font, '')
          .setScale(MARK_SCALE)
          .setTint(TEXT_COLOR)
          .setDepth(DEPTH.hud + 1)
      : null
    this.hintPanel = scene.add.rectangle(plate.x, plate.y, plate.w, plate.h, PANEL_COLOR, PANEL_ALPHA).setOrigin(0, 0).setDepth(DEPTH.hud).setName(PANEL_NAME)
    this.frames = [
      new Skin(scene, THEME.skin.hud).place({ x: left, y: top, w: width, h: height }).setDepth(DEPTH.hud),
      new Skin(scene, THEME.skin.hud).place(plate).setDepth(DEPTH.hud),
    ]
    this.hint = lines.map((line, i) =>
      scene.add
        .bitmapText(plate.x + PLATE_PAD, plate.y + PLATE_PAD + i * HINT_LINE_PX, font, line)
        .setScale(2)
        .setTint(HINT_COLOR)
        .setDepth(DEPTH.hud + 1),
    )
  }

  /**
   * Shows other key hints, as when the tuning tools are unlocked in a race that is running (F-813): the hints' plate is laid out
   * again for the new words (its right edge stays where it was) and the readout moves with it.
   */
  setHint(hint: string): void {
    const lines = hintLines(hint)
    const plate = hintsPlate(lines)
    const { w, h, scale } = this.size
    const left = plate.x - BAND_GAP - w
    const top = LOGICAL_HEIGHT - BAND_EDGE - h
    this.panel.setPosition(left, top)
    this.text.setPosition(left + PADDING_PX, top + PADDING_PX)
    this.mark?.setPosition(left + w - PADDING_PX - ASSISTED_MARK.length * CELL_W * MARK_SCALE, top + PADDING_PX + LINES * CELL_H * scale)
    this.frames[0]?.place({ x: left, y: top, w, h })
    this.hintPanel.setPosition(plate.x, plate.y).setSize(plate.w, plate.h)
    this.frames[1]?.place(plate)
    this.hint.forEach((line, i) => line.setText(lines[i] ?? '').setPosition(plate.x + PLATE_PAD, plate.y + PLATE_PAD + i * HINT_LINE_PX))
  }

  /** What the readout shows now, one entry per line. */
  lines(): string[] {
    return this.shown.split('\n')
  }

  /** Redraws the text only when it changed. */
  update(car: Pick<CarSnapshot, 'lap' | 'lastLapMs' | 'bestLapMs'> | undefined): void {
    if (car === undefined) return
    const next = readoutLines(car, this.assisted).join('\n')
    if (next === this.shown) return
    this.shown = next
    const lines = next.split('\n')
    this.text.setText(lines.slice(0, LINES).join('\n'))
    this.mark?.setText(lines[LINES] ?? '')
  }

  destroy(): void {
    this.panel.destroy()
    this.text.destroy()
    this.mark?.destroy()
    this.hintPanel.destroy()
    for (const frame of this.frames) frame.destroy()
    for (const line of this.hint) line.destroy()
  }
}
