import type { AudioMixer } from './AudioMixer'
import { BED_STOP_BELOW, rainGain, windCutoffHz, windGain } from './mapping'
import { startNoise } from './noise'

/** How fast a bed follows its target, seconds: slow, because the sky changes slowly and a step would be heard. */
const BED_TAU_S = 0.35
/** A frame longer than this is a stall; the bed's own bookkeeping does not run on it. */
const MAX_DT_S = 0.1

interface BedNodes {
  source: AudioBufferSourceNode
  filters: BiquadFilterNode[]
  gain: GainNode
}

/**
 * A bed of filtered noise that exists only while it is audible. At a target of nothing it fades and is then *stopped and
 * disconnected*, not left running silent; the next time it is wanted a fresh source is made (a source cannot restart).
 */
class NoiseBed {
  private nodes: BedNodes | null = null
  /** What the gain has reached, tracked here so the bed knows when it has faded out. */
  private level = 0

  constructor(
    private readonly mixer: AudioMixer,
    private readonly build: (ctx: AudioContext) => BiquadFilterNode[],
  ) {}

  /** Whether the bed has live nodes (the tests ask: at nothing it must not). */
  get running(): boolean {
    return this.nodes !== null
  }

  update(dtS: number, target: number, cutoffHz?: number): void {
    const { ctx } = this.mixer
    if (this.nodes === null) {
      if (target < BED_STOP_BELOW) return
      const source = startNoise(ctx)
      const filters = this.build(ctx)
      const gain = ctx.createGain()
      gain.gain.value = 0
      let tail: AudioNode = source
      for (const filter of filters) {
        tail.connect(filter)
        tail = filter
      }
      tail.connect(gain)
      gain.connect(this.mixer.sfx)
      this.nodes = { source, filters, gain }
      this.level = 0
    }
    const { gain, filters } = this.nodes
    gain.gain.setTargetAtTime(target, ctx.currentTime, BED_TAU_S)
    if (cutoffHz !== undefined && filters[0] !== undefined) filters[0].frequency.setTargetAtTime(cutoffHz, ctx.currentTime, BED_TAU_S)
    this.level += (target - this.level) * (1 - Math.exp(-Math.min(dtS, MAX_DT_S) / BED_TAU_S))
    if (target < BED_STOP_BELOW && this.level < BED_STOP_BELOW) this.stop()
  }

  stop(): void {
    const { nodes } = this
    if (nodes === null) return
    this.nodes = null
    this.level = 0
    try {
      nodes.source.stop()
    } catch {
      // Already stopped.
    }
    nodes.source.disconnect()
    for (const filter of nodes.filters) filter.disconnect()
    nodes.gain.disconnect()
  }
}

/** The weather's beds (F-704): rain by intensity, wind by the air's speed. */
export class Ambience {
  private readonly rain: NoiseBed
  private readonly wind: NoiseBed

  constructor(mixer: AudioMixer) {
    // Rain: a hiss between 900 Hz and 7 kHz.
    this.rain = new NoiseBed(mixer, (ctx) => {
      const high = ctx.createBiquadFilter()
      high.type = 'highpass'
      high.frequency.value = 900
      const low = ctx.createBiquadFilter()
      low.type = 'lowpass'
      low.frequency.value = 7000
      return [high, low]
    })
    // Wind: a band of noise whose centre rises with the speed of the air.
    this.wind = new NoiseBed(mixer, (ctx) => {
      const band = ctx.createBiquadFilter()
      band.type = 'bandpass'
      band.Q.value = 1.1
      band.frequency.value = 400
      return [band]
    })
  }

  get rainRunning(): boolean {
    return this.rain.running
  }

  get windRunning(): boolean {
    return this.wind.running
  }

  /** `rainIntensity` 0..1 and the wind's speed in m/s, from the weather snapshot. */
  update(dtS: number, rainIntensity: number, windSpeedMS: number): void {
    this.rain.update(dtS, rainGain(rainIntensity))
    this.wind.update(dtS, windGain(windSpeedMS), windCutoffHz(windSpeedMS))
  }

  dispose(): void {
    this.rain.stop()
    this.wind.stop()
  }
}
