import type { CommentaryEngine } from './types'

/**
 * The engine, handing out at most `count` lines in all and nothing after them: the result screens say their piece and
 * are silent (F-703), the podium says the result and then the player's place in the event (F-709).
 */
export function atMost(engine: CommentaryEngine, count: number): CommentaryEngine {
  let given = 0
  return {
    observe: (events, snapshot, nowS) => engine.observe(events, snapshot, nowS),
    next(nowS, speakerBusy) {
      if (given >= count) return null
      const line = engine.next(nowS, speakerBusy)
      if (line !== null) given++
      return line
    },
  }
}
