// The race HUD (F-304), for qualifying heats and finals. The track fills the screen, so everything that stays up
// during a race lives in the bands of outfield above and below the track's rectangle and never covers asphalt:
//
//   top band     the lap readout on the left, the position and clock in the centre, the order strip right of
//                centre, the class legend (F-711), and at the far right the wind arrow, the windsock and the sky icon (F-603)
//   bottom band  the key hints on a plate at the left, the message line (messages, and "TIME UP") centred in the room
//                between them and the driver stand, which is at the right and is never covered
//
// Only what is brief or comes when the player is not racing lies over the track: the start calls (StartLights), the
// lap time flashing in the centre of the screen, and the classification table once the player has finished. The HUD
// reads snapshots and listens to the sim's events; it decides nothing. Text is rewritten only when what it says changes, and nothing is allocated per
// frame while the HUD is steady. The bands' sizes come from the track's rectangle and the view, not from numbers.

// ── Layout, in logical (1920 x 1080) pixels ────────────────────────────────────────────────────────────────

const PAD = 12
const PLATE_ALPHA = 0.78
const PLATE = THEME.colours.background

/** Space in the readout between segments is one character; this is the room kept between it and the clock. */
const READOUT_GUTTER = 32
const READOUT_LEFT = 16
/** The clock is laid out for this many characters ("4:55"); the last ten seconds are longer and grow to the right. */
const CLOCK_CHARS = 4
const CLOCK_TENTHS_CHARS = 6
const POSITION_CHARS = 2
/** The strip begins this far, in pixels, past the clock's longest form. */
const STRIP_GAP = 48

const TAG = 36
const TAG_PITCH = 44
const TAG_OUTLINE = 2

const CENTRE_X = LOGICAL_WIDTH / 2

/** The lap time's two lines: the plate behind them is faint, so that a car under it can still be seen. */
const LAP_TIME_PLATE_ALPHA = 0.35
const LAP_TIME_SIZE: TextSize = 'body'
/** The little chequered flag either side of LAP TIME, and how far its middle is from the title's end, px (F-802). */
const LAP_FLAG = 'accent.lap-flag'
const LAP_FLAG_GAP = 20
/** The arrows beside the position when it changes, and the sparkle of a personal best (F-802). */
const ARROW = { up: 'accent.position.up', down: 'accent.position.down' } as const
const SPARKLE = 'fx.sparkle'

const COLOUR = {
  text: THEME.colours.text,
  dim: THEME.colours.textDim,
  accent: THEME.colours.accent,
  good: 0x5cc85a,
  bad: 0xee5a48,
  /** The session's best lap: the palette's pink (art-direction.md), the one colour no other tone uses. */
  session: TAG_COLOUR.pink,
} as const

/** The colour of the official's words in each tone: the message line's, and practice's lap call (F-810). */
export const MESSAGE_COLOUR: Readonly<Record<MessageTone, number>> = { info: COLOUR.accent, good: COLOUR.good, bad: COLOUR.bad }
const LAP_TIME_COLOUR = { session: COLOUR.session, personal: COLOUR.good, plain: COLOUR.text } as const
const END_COLOUR: Readonly<Record<EndCall, number>> = { 'time-up': COLOUR.bad, finished: COLOUR.good, 'did-not-finish': COLOUR.bad }

/** What was last written to a line, so that it is rewritten only when it changes. */
const UNSET = -1e9

/** The segments of the lap readout, in order. */
const LAP = 0
const NOW = 1
const LAST = 2
const BEST = 3
const GAP = 4

/** A plate and the lines of text on it, centred on the screen's middle line, at a fixed top. */
class Banner {
  private readonly plate: Phaser.GameObjects.Rectangle
  private readonly frame: Skin
  private readonly lines: Phaser.GameObjects.BitmapText[]

  constructor(
    scene: Phaser.Scene,
    private readonly sizes: readonly TextSize[],
    private readonly top: number,
    private readonly pad = PAD,
  ) {
    this.plate = scene.add.rectangle(0, 0, 1, 1, PLATE, PLATE_ALPHA).setOrigin(0, 0).setDepth(DEPTH.hud).setVisible(false)
    this.frame = new Skin(scene, THEME.skin.hud).setDepth(DEPTH.hud)
    this.lines = sizes.map((size) => text(scene, { x: 0, y: 0 }, '', size).setDepth(DEPTH.hud + 1).setVisible(false))
  }

  /** Shows `words` (one per line; the first in `colour`) or, for null, nothing. */
  set(words: readonly string[] | null, colour: number): void {
    const visible = words !== null && words.length > 0
    this.plate.setVisible(visible)
    const centre = CENTRE_X
    let widest = 0
    let y = this.top + this.pad
    for (let i = 0; i < this.lines.length; i++) {
      const line = this.lines[i]
      const value = words?.[i]
      if (value === undefined) {
        line.setVisible(false)
        continue
      }
      const size = this.sizes[i]
      const w = value.length * charWidth(size)
      widest = Math.max(widest, w)
      line.setScale(THEME.sizes[size]).setText(value).setTint(i === 0 ? colour : COLOUR.text).setVisible(true).setPosition(Math.round(centre - w / 2), y)
      y += lineHeight(size)
    }
    if (visible) {
      this.plate.setPosition(Math.round(centre - widest / 2) - 2 * PAD, this.top).setSize(widest + 4 * PAD, y - this.top + this.pad)
      this.frame.place({ x: this.plate.x, y: this.plate.y, w: this.plate.width, h: this.plate.height })
    }
    this.frame.setVisible(visible)
  }

  destroy(): void {
    this.plate.destroy()
    this.frame.destroy()
    for (const line of this.lines) line.destroy()
  }
}

/** The lap time just done: two lines, "LAP TIME" between two little chequered flags (F-802) and the time, flashing in the centre of the screen on a faint framed plate. */
class LapTime {
  private readonly plate: Phaser.GameObjects.Rectangle
  private readonly frame: Skin
  private readonly flags: Phaser.GameObjects.Image[]
  private readonly title: Phaser.GameObjects.BitmapText
  private readonly time: Phaser.GameObjects.BitmapText
  private since: Tick | null = null
  private on = false

  constructor(scene: Phaser.Scene, manifest: AssetManifest) {
    this.plate = scene.add.rectangle(0, 0, 1, 1, PLATE, LAP_TIME_PLATE_ALPHA).setOrigin(0, 0).setDepth(DEPTH.hud).setVisible(false)
    this.frame = new Skin(scene, THEME.skin.hud).setDepth(DEPTH.hud)
    const flag = still(manifest, LAP_FLAG)
    this.flags = [1, -1].map((side) => scene.add.image(0, 0, flag.atlas, flag.frame).setOrigin(0.5, 0.5).setScale(flag.scale).setFlipX(side < 0).setDepth(DEPTH.hud + 1).setVisible(false))
    this.title = text(scene, { x: 0, y: 0 }, LAP_TIME_TITLE, LAP_TIME_SIZE).setDepth(DEPTH.hud + 1).setVisible(false)
    this.time = text(scene, { x: 0, y: 0 }, '', LAP_TIME_SIZE).setDepth(DEPTH.hud + 1).setVisible(false)
  }

  /** A lap has just been completed at `tick`. */
  start(tick: Tick, words: string, colour: number): void {
    this.since = tick
    this.on = false
    this.time.setText(words)
    this.title.setTint(colour)
    this.time.setTint(colour)
    const h = lineHeight(LAP_TIME_SIZE)
    const w = Math.max(LAP_TIME_TITLE.length, words.length) * charWidth(LAP_TIME_SIZE)
    const top = Math.round(LOGICAL_HEIGHT / 2 - h)
    this.plate.setPosition(Math.round(CENTRE_X - w / 2) - PAD, top - PAD).setSize(w + 2 * PAD, 2 * h + 2 * PAD)
    const titleW = LAP_TIME_TITLE.length * charWidth(LAP_TIME_SIZE)
    this.title.setPosition(Math.round(CENTRE_X - titleW / 2), top)
    this.time.setPosition(Math.round(CENTRE_X - (words.length * charWidth(LAP_TIME_SIZE)) / 2), top + h)
    this.frame.place({ x: this.plate.x, y: this.plate.y, w: this.plate.width, h: this.plate.height })
    this.frame.setVisible(false)
    // A flag either side of the title, inside the plate's padding: the right one mirrored, so both fly outward.
    this.flags.forEach((flag, i) => flag.setPosition(Math.round(CENTRE_X + (i === 0 ? -1 : 1) * (titleW / 2 + LAP_FLAG_GAP)), top + Math.round(h / 2)))
  }

  /** Shows it while it is on, hides it while it is off and once it is over. */
  update(tick: Tick): void {
    if (this.since === null) return
    const age = (tick - this.since) / TICK_RATE
    const show = lapTimeShown(age)
    if (show !== this.on) {
      this.on = show
      this.plate.setVisible(show)
      this.frame.setVisible(show)
      for (const flag of this.flags) flag.setVisible(show)
      this.title.setVisible(show)
      this.time.setVisible(show)
    }
    if (age >= LAP_TIME_SECONDS) this.since = null
  }

  destroy(): void {
    this.plate.destroy()
    this.frame.destroy()
    for (const flag of this.flags) flag.destroy()
    this.title.destroy()
    this.time.destroy()
  }
}

/**
 * The sparkle round the player's car when a lap is a personal best (F-802): a few stars of `fx.sparkle` about the car,
 * each played once, a little after the one before, following the car while they last.
 */
class Sparkle {
  private readonly stars: Phaser.GameObjects.Image[]
  private readonly frames: readonly string[]
  private readonly fps: number
  private since: Tick | null = null

  constructor(scene: Phaser.Scene, manifest: AssetManifest) {
    const art = animation(manifest, SPARKLE)
    this.frames = art.frames
    this.fps = art.fps
    this.stars = SPARKLES.map(() => scene.add.image(0, 0, art.atlas, art.frames[0]).setOrigin(art.pivot.x, art.pivot.y).setScale(art.scale).setDepth(DEPTH.hud).setVisible(false))
  }

  start(tick: Tick): void {
    this.since = tick
  }

  /** Each star on its frame `tick` after the lap, beside where the car is drawn now (`at`, screen px); all hidden once over. */
  update(tick: Tick, at: { x: number; y: number } | null): void {
    if (this.since === null) return
    const age = (tick - this.since) / TICK_RATE
    let any = false
    this.stars.forEach((star, i) => {
      const place = SPARKLES[i]
      const frame = place === undefined || at === null ? null : sparkleFrame(age, place.delayS, this.frames.length, this.fps)
      star.setVisible(frame !== null)
      if (frame === null || place === undefined || at === null) return
      any = true
      star.setPosition(Math.round(at.x + place.dx), Math.round(at.y + place.dy)).setFrame(this.frames[frame] ?? '')
    })
    const last = SPARKLES[SPARKLES.length - 1]
    if (!any && last !== undefined && age > last.delayS) this.since = null
  }

  /** Whether a star is on screen. */
  get shown(): boolean {
    return this.stars.some((star) => star.visible)
  }

  destroy(): void {
    for (const star of this.stars) star.destroy()
  }
}

/** What the class legend reports to the debug hook and the tests: the class's words, the round's, each line's box and the column's, on the 1920 x 1080 canvas. */
export interface LegendInfo {
  /** The class's words (the first line). */
  text: string
  /** The round's words under it: QUAL N, FINAL LEG N, QUALIFYING, FINAL or PRACTICE (F-712). */
  round: string
  /** The column the two lines make. */
  box: PixelRect
  /** The two lines, the class first. */
  lines: LegendLine[]
  /** The thin vertical divider between the column and the weather pieces (F-712). */
  divider: PixelRect
}

/**
 * The class being raced and, under it, the round (F-711, F-712), in small dim text in one column in the top band between
 * the order strip and the weather pieces: the HUD's, and in practice, which has no HUD, the scene's, on a plate of its
 * own the height of the band. `bandHeight` is the top band's; the column ends a fixed gap before the first of the weather pieces,
 * and a thin divider in the HUD's dim colour stands in the middle of that gap (the plate, in practice, reaches the weather's edge to hold it).
 */
export class ClassLegend {
  private readonly column: ReturnType<typeof legendColumn>
  private readonly labels: Phaser.GameObjects.BitmapText[]
  private readonly divider: PixelRect
  private readonly dividerBar: Phaser.GameObjects.Rectangle
  private readonly plate: Phaser.GameObjects.Rectangle | null
  private readonly frame: Skin | null

  constructor(scene: Phaser.Scene, private readonly words: string, private readonly round: string, bandHeight: number, plate: boolean) {
    const weatherLeft = weatherHudLayout(bandHeight).arrow.x
    this.column = legendColumn([words, round], weatherLeft, bandHeight)
    this.divider = legendDivider(this.column.box, weatherLeft, bandHeight)
    const { x } = this.column.box
    this.plate = plate ? scene.add.rectangle(x - PAD, 0, weatherLeft - x + PAD, bandHeight, PLATE, PLATE_ALPHA).setOrigin(0, 0).setDepth(DEPTH.hud).setName(PANEL_NAME) : null
    // Its frame runs off the top of the screen: only its sides and its foot show.
    this.frame = this.plate === null ? null : new Skin(scene, THEME.skin.hud).place({ x: this.plate.x, y: -PAD, w: this.plate.width, h: bandHeight + PAD }).setDepth(DEPTH.hud)
    const bar = this.divider
    this.dividerBar = scene.add.rectangle(bar.x, bar.y, bar.w, bar.h, COLOUR.dim).setOrigin(0, 0).setDepth(DEPTH.hud + 1)
    this.labels = this.column.lines.map((line) => text(scene, { x: line.x, y: line.y }, line.text, LEGEND_SIZE).setTint(COLOUR.dim).setDepth(DEPTH.hud + 1))
  }

  info(): LegendInfo {
    return { text: this.words, round: this.round, box: { ...this.column.box }, lines: this.column.lines.map((line) => ({ ...line })), divider: { ...this.divider } }
  }

  destroy(): void {
    this.plate?.destroy()
    this.frame?.destroy()
    this.dividerBar.destroy()
    for (const label of this.labels) label.destroy()
  }
}

/** The classification, once the player has finished: a title, a header and a row for each car that has finished. */
class ClassTable {
  private readonly plate: Phaser.GameObjects.Rectangle
  private readonly frame: Skin
  private readonly title: Phaser.GameObjects.BitmapText
  private readonly lines: Phaser.GameObjects.BitmapText[]

  /** `rows` is the most rows it can hold: one for every car. */
  constructor(scene: Phaser.Scene, private readonly top: number, rows: number) {
    this.plate = scene.add.rectangle(0, 0, 1, 1, PLATE, PLATE_ALPHA).setOrigin(0, 0).setDepth(DEPTH.hud).setVisible(false)
    this.frame = new Skin(scene, THEME.skin.hud).setDepth(DEPTH.hud)
    this.title = text(scene, { x: 0, y: 0 }, '', 'large').setDepth(DEPTH.hud + 1).setVisible(false)
    this.lines = Array.from({ length: rows + 1 }, () => text(scene, { x: 0, y: 0 }, '', 'body').setDepth(DEPTH.hud + 1).setVisible(false))
  }

  /** Shows the title and the lines (the header first; `playerRow` is the index of the player's among the rows after it), or nothing. */
  set(title: string | null, lines: readonly string[], playerRow: number): void {
    this.plate.setVisible(title !== null)
    this.frame.setVisible(title !== null)
    this.title.setVisible(title !== null)
    if (title === null) {
      for (const line of this.lines) line.setVisible(false)
      return
    }
    const rowH = lineHeight('body')
    const chars = lines.reduce((widest, line) => Math.max(widest, line.length), 0)
    const w = chars * charWidth('body')
    const left = Math.round(CENTRE_X - w / 2)
    this.title.setText(title).setTint(COLOUR.good).setPosition(Math.round(CENTRE_X - (title.length * charWidth('large')) / 2), this.top + PAD)
    let y = this.top + PAD + lineHeight('large')
    for (let i = 0; i < this.lines.length; i++) {
      const line = this.lines[i]
      const words = lines[i]
      if (words === undefined) {
        line.setVisible(false)
        continue
      }
      line.setText(words).setTint(i === 0 ? COLOUR.dim : i - 1 === playerRow ? COLOUR.accent : COLOUR.text).setVisible(true).setPosition(left, y)
      y += rowH
    }
    this.plate.setPosition(left - 2 * PAD, this.top).setSize(w + 4 * PAD, y - this.top + PAD)
    this.frame.place({ x: this.plate.x, y: this.plate.y, w: this.plate.width, h: this.plate.height })
  }

  destroy(): void {
    this.plate.destroy()
    this.frame.destroy()
    this.title.destroy()
    for (const line of this.lines) line.destroy()
  }
}

/** The numbered colour tag of one car, in the order strip. */
interface Tag {
  fill: Phaser.GameObjects.Rectangle
  number: Phaser.GameObjects.BitmapText
}

/** What the debug hook reports of the PITS section: the stops the player began with, those still owed and those served, the label's box and each box's, on the 1920 x 1080 canvas. */
export interface PitsInfo {
  total: number
  owed: number
  served: number
  label: PixelRect
  boxes: Array<PixelRect & { checked: boolean }>
}

export interface HudOptions {
  config: SessionConfig
  /** The art's manifest: the check boxes of the PITS section (the atlas `ui` must be loaded). */
  manifest: AssetManifest
  bus: EventBus
  view: WorldView
  /** The sim's latest snapshot, read when an event arrives. */
  snapshot: () => SessionSnapshot
  /** The key hints: they are put on a plate at the right end of the band below the track, on two lines. */
  hint: string
  /**
   * The director (F-703): the HUD hands it the message the official has to say, every frame, and it puts the official or
   * the commentator in the window. The scene makes it and puts it away.
   */
  director: Pick<CommentaryDirector, 'official'>
  /** The length of the cars, m: the ring is a multiple of it. */
  carLengthM: number
  /** The car the person at the keyboard drives; null when nobody does. */
  playerId: CarId | null
}

export class Hud {
  private readonly parts: Phaser.GameObjects.GameObject[] = []
  /** The frames of the HUD's plates (F-802). */
  private readonly frames: Skin[] = []
  /** The key hints' plate, its frame and its two lines, kept to lay them out again when the hints change (F-813). */
  private readonly hintPlate: Phaser.GameObjects.Rectangle
  private readonly hintFrame: Skin
  private readonly hintTexts: Phaser.GameObjects.BitmapText[]
  private readonly release: Array<() => void> = []
  private readonly playerId: CarId | null
  private readonly kind: SessionConfig['kind']

  // Top band, centre: position and clock, at the largest whole-number scale the band allows.
  private readonly position: Phaser.GameObjects.BitmapText
  private readonly clock: Phaser.GameObjects.BitmapText
  private readonly bigScale: number
  private shownPosition = 0
  private shownClockKey = UNSET
  private pulseOn = false
  /** The arrows beside the position (F-802), the one showing and since when. */
  private readonly arrows: Record<'up' | 'down', Phaser.GameObjects.Image>
  private arrow: { dir: 'up' | 'down'; since: Tick } | null = null
  /** The sparkle round the player's car on a personal best (F-802). */
  private readonly sparkle: Sparkle

  // Top band, left: the lap readout, one line of segments.
  private readonly readout: Phaser.GameObjects.BitmapText[] = []
  private readonly segments: string[] = ['', '', '', '', '']
  private readonly readoutChars: number
  private shownLap = UNSET
  private shownLast = UNSET
  private shownBest = UNSET
  private shownNow = UNSET
  private shownGap = UNSET
  private shownGapPosition = UNSET
  private shownGapLaps = UNSET
  private shownGapAge = UNSET

  // Top band, before the position: PITS and a box for each stop the player began by owing (F-514); none in a session that owes none.
  private readonly pitBoxes: Array<{ empty: Phaser.GameObjects.Image; done: Phaser.GameObjects.Image }> = []
  private pitsLabel: PixelRect | null = null
  private pitsTotal = 0
  private shownServed = UNSET

  // Top band, right of centre: the order strip.
  private readonly tags: Tag[] = []
  private readonly outline: Phaser.GameObjects.Rectangle
  private readonly stripLeft: number
  private readonly shownSlot: number[]

  // Bottom band: the messages, said by the official through the director.
  private readonly director: Pick<CommentaryDirector, 'official'>
  /** The standing message and the timed one over it (F-404). */
  private readonly line = createMessageLine()
  /** The message on the line last frame, and the session time it came on. */
  private shownMessage: HudMessage | null = null
  private messageSinceS = 0

  // Over the track, briefly: the lap time, the classification and the did-not-finish banner.
  private readonly lapTime: LapTime
  private readonly table: ClassTable
  private readonly end: Banner
  private shownEnd: EndCall | null = null
  /** Each car's place in the table while it is on it, -1 while it has not finished: the table is rebuilt when any changes. */
  private readonly shownFinish: number[]

  private readonly lights: StartLights
  private readonly marker: PlayerMarker | null
  /** The wind arrow, the windsock and the sky icon at the far right of the top band (F-603). */
  readonly windSock: WindSock
  /** The class being raced, left of them (F-711). */
  readonly legend: ClassLegend

  constructor(scene: Phaser.Scene, private readonly options: HudOptions) {
    const { config, bus, view, playerId } = options
    this.playerId = playerId
    this.director = options.director
    this.kind = config.kind
    const hud = DEPTH.hud
    // The track's rectangle on screen; the bands of outfield above and below it are where the HUD lives.
    const rect = trackRect(config.track, view)
    const topBand = Math.max(0, Math.floor(rect.y))
    const hasPlayer = playerId !== null

    // Top band: a strip across it, and on it the position and clock as big as the band allows (a whole number times the font).
    this.parts.push(scene.add.rectangle(0, 0, LOGICAL_WIDTH, topBand, PLATE, PLATE_ALPHA).setOrigin(0, 0).setDepth(hud).setName(PANEL_NAME))
    // Its frame runs off the screen at the top and both ends: only its foot, along the bottom of the band, shows (F-802).
    this.frames.push(new Skin(scene, THEME.skin.hud).place({ x: -PAD, y: -PAD, w: LOGICAL_WIDTH + 2 * PAD, h: topBand + PAD }).setDepth(hud))
    this.bigScale = Math.max(1, Math.floor((topBand - 2 * BAND_MARGIN) / FONT_CELL.h))
    const bigY = Math.round((topBand - FONT_CELL.h * this.bigScale) / 2)
    const cw = FONT_CELL.w * this.bigScale
    const blockLeft = Math.round(CENTRE_X - ((hasPlayer ? POSITION_CHARS + 1 : 0) + CLOCK_CHARS) * cw / 2)
    this.position = this.keep(text(scene, { x: blockLeft, y: bigY }, '', 'body').setScale(this.bigScale).setDepth(hud + 1).setVisible(hasPlayer))
    this.clock = this.keep(text(scene, { x: blockLeft + (hasPlayer ? POSITION_CHARS + 1 : 0) * cw, y: bigY }, '', 'body').setScale(this.bigScale).setDepth(hud + 1))
    // The arrows stand in the character's gap between the position and the clock.
    const arrowAt = { x: Math.round(blockLeft + (POSITION_CHARS + 0.5) * cw), y: Math.round(topBand / 2) }
    const arrowImage = (name: string): Phaser.GameObjects.Image => {
      const art = still(options.manifest, name)
      return this.keep(scene.add.image(arrowAt.x, arrowAt.y, art.atlas, art.frame).setOrigin(art.pivot.x, art.pivot.y).setScale(art.scale).setDepth(hud + 1).setVisible(false))
    }
    this.arrows = { up: arrowImage(ARROW.up), down: arrowImage(ARROW.down) }
    this.sparkle = new Sparkle(scene, options.manifest)

    // Top band, before the position and clock: PITS and a box for each stop the player's car begins by owing (F-514).
    const readoutY = Math.round((topBand - lineHeight('body')) / 2)
    const owed = playerId === null ? 0 : (options.snapshot().cars[playerId]?.pitStopsOwed ?? 0)
    let readoutRight = blockLeft
    if (owed > 0) {
      const section = pitsSection(owed, blockLeft)
      readoutRight = section.left
      this.pitsTotal = owed
      this.pitsLabel = { x: section.labelX, y: readoutY, w: PITS_TEXT.length * charWidth('body'), h: lineHeight('body') }
      this.keep(text(scene, { x: section.labelX, y: readoutY }, PITS_TEXT, 'body').setDepth(hud + 1))
      const empty = still(options.manifest, 'ui.check.empty')
      const done = still(options.manifest, 'ui.check.done')
      for (const x of section.boxes) {
        const place = (art: typeof empty): Phaser.GameObjects.Image =>
          this.keep(scene.add.image(x, readoutY + PITS.boxDrop, art.atlas, art.frame).setOrigin(art.pivot.x, art.pivot.y).setScale(art.scale).setDepth(hud + 1))
        this.pitBoxes.push({ empty: place(empty), done: place(done).setVisible(false) })
      }
    }

    // Top band, left: the lap readout, for the player only. It has the room between its left margin and what is before the position.
    this.readoutChars = Math.floor((readoutRight - READOUT_GUTTER - READOUT_LEFT) / charWidth('body'))
    for (let i = 0; i < 5; i++) {
      this.readout.push(this.keep(text(scene, { x: READOUT_LEFT, y: readoutY }, '', 'body').setDepth(hud + 1).setVisible(false)))
    }

    // Right of centre: one tag per car, in position order.
    this.stripLeft = Math.round(blockLeft + (hasPlayer ? POSITION_CHARS + 1 : 0) * cw + CLOCK_TENTHS_CHARS * cw + STRIP_GAP)
    const tagY = Math.round((topBand - TAG) / 2)
    this.outline = this.keep(
      scene.add.rectangle(0, tagY - TAG_OUTLINE, TAG + 2 * TAG_OUTLINE, TAG + 2 * TAG_OUTLINE, COLOUR.text).setOrigin(0, 0).setDepth(hud).setVisible(hasPlayer),
    )
    config.entries.forEach((entry, id) => {
      const fill = this.keep(scene.add.rectangle(0, tagY, TAG, TAG, TAG_COLOUR[entry.colour]).setOrigin(0, 0).setDepth(hud + 1))
      const number = this.keep(
        text(scene, { x: 0, y: tagY + (TAG - lineHeight('small')) / 2 }, String(entry.number), 'small').setTint(NUMBER_TINT[entry.colour]).setDepth(hud + 2),
      )
      this.tags[id] = { fill, number }
    })
    this.shownSlot = config.entries.map(() => UNSET)

    this.windSock = new WindSock(scene, options.manifest, bus, topBand)
    this.legend = new ClassLegend(scene, CLASS_LEGEND[config.carClass], roundWords(config.kind, config.label), topBand, false)

    this.lapTime = new LapTime(scene, options.manifest)

    // Bottom band: the key hints on one plate at the right end. The official and his bubble are the scene's (F-509).
    const lines = hintLines(options.hint)
    const plate = hintsPlate(lines)
    this.hintPlate = this.keep(scene.add.rectangle(plate.x, plate.y, plate.w, plate.h, PLATE, PLATE_ALPHA).setOrigin(0, 0).setDepth(hud).setName(PANEL_NAME))
    this.hintFrame = new Skin(scene, THEME.skin.hud).place(plate).setDepth(hud)
    this.frames.push(this.hintFrame)
    this.hintTexts = lines.map((line, i) => this.keep(text(scene, { x: plate.x + PAD, y: plate.y + PAD + i * lineHeight('small') }, line, 'small').setTint(COLOUR.dim).setDepth(hud + 1)))

    // Over the track, briefly: the start calls and the end banner, a quarter of the way down the track.
    const callTop = Math.round(rect.y + rect.h / 4)
    this.end = new Banner(scene, ['large'], callTop)
    // The classification sits under the top band, over the straight, clear of the timing line and of the lap time at the centre.
    this.table = new ClassTable(scene, Math.ceil(rect.y) + 2 * PAD, config.entries.length)
    this.shownFinish = config.entries.map(() => UNSET)
    this.lights = new StartLights(scene, bus, config.kind, playerId, config.entries.map((entry) => entry.number), CENTRE_X, callTop)
    this.marker = playerId === null ? null : new PlayerMarker(scene, view, playerId, options.carLengthM)

    // What the sim tells: a lap of the player's puts up the lap time, and every event type that has a row in the
    // message table is offered to it.
    this.release.push(
      bus.on('lap', (event) => {
        if (playerId === null || event.car !== playerId) return
        this.lapTime.start(event.tick, lapTimeLine(event.lapMs), LAP_TIME_COLOUR[lapTone(event)])
        if (event.personalBest) this.sparkle.start(event.tick)
      }),
    )
    for (const type of MESSAGE_EVENTS) this.release.push(bus.on(type, (event) => this.onMessageEvent(event)))
  }

  /** Shows other key hints, as when the tuning tools are unlocked in a race that is running (F-813): the plate keeps its right edge and foot and grows to the left. */
  setHint(hint: string): void {
    const lines = hintLines(hint)
    const plate = hintsPlate(lines)
    this.hintPlate.setPosition(plate.x, plate.y).setSize(plate.w, plate.h)
    this.hintFrame.place(plate)
    this.hintTexts.forEach((line, i) => line.setText(lines[i] ?? '').setPosition(plate.x + PAD, plate.y + PAD + i * lineHeight('small')))
  }

  private keep<T extends Phaser.GameObjects.GameObject>(object: T): T {
    this.parts.push(object)
    return object
  }

  private onMessageEvent(event: SimEvent): void {
    const message = messageFor(event, this.options.snapshot(), this.playerId)
    if (message === null) return
    postToLine(this.line, message, event.tick)
  }

  /** Brings every part of the HUD up to `snapshot`; `cars` are the cars as drawn this frame, for the ring. */
  update(snapshot: SessionSnapshot, cars: readonly RenderCar[]): void {
    const { tick } = snapshot
    const player = this.playerId === null ? undefined : snapshot.cars[this.playerId]
    const call = endCallFor(snapshot.phase, player?.state ?? null, snapshot.clockRemainingS)

    this.updateTop(snapshot, player, call)
    if (player !== undefined) this.updateReadout(snapshot, player)
    if (player !== undefined && this.pitBoxes.length > 0) this.updatePits(player)
    this.updateStrip(snapshot)
    this.lights.update(snapshot)
    this.updateMessage(tick, call)
    this.lapTime.update(tick)
    const car = this.playerId === null ? undefined : cars[this.playerId]
    this.sparkle.update(tick, car === undefined ? null : { x: this.options.view.originX + car.x * this.options.view.pxPerM, y: this.options.view.originY + car.y * this.options.view.pxPerM })
    this.updateEnd(snapshot, call)
    this.marker?.update(cars)
    this.windSock.update(snapshot.weather, tick)
  }

  private updateTop(snapshot: SessionSnapshot, player: CarSnapshot | undefined, call: EndCall | null): void {
    const placed = player?.position ?? 0
    const key = clockKey(snapshot.clockRemainingS)
    if (key !== this.shownClockKey) {
      this.shownClockKey = key
      setTextIfChanged(this.clock, formatClock(snapshot.clockRemainingS))
    }
    if (placed !== this.shownPosition) {
      const dir = positionArrow(this.shownPosition, placed)
      if (dir !== null) this.arrow = { dir, since: snapshot.tick }
      this.shownPosition = placed
      if (placed !== 0) setTextIfChanged(this.position, formatPosition(placed))
    }
    const arrow = this.arrow
    const showing = arrow !== null && arrowShown((snapshot.tick - arrow.since) / TICK_RATE) ? arrow.dir : null
    if (arrow !== null && showing === null) this.arrow = null
    if (this.arrows.up.visible !== (showing === 'up')) this.arrows.up.setVisible(showing === 'up')
    if (this.arrows.down.visible !== (showing === 'down')) this.arrows.down.setVisible(showing === 'down')
    // At time up the clock pulses, on the sim's clock: half a second red, half a second white.
    const pulse = call === 'time-up' && Math.floor(snapshot.tick / (TICK_RATE / 2)) % 2 === 0
    if (pulse !== this.pulseOn) {
      this.pulseOn = pulse
      this.clock.setTint(pulse ? COLOUR.bad : COLOUR.text)
    }
  }

  /** Sets one segment of the readout, and lays the line out again if its words changed. */
  private setSegment(index: number, words: string, colour: number): void {
    this.segments[index] = words
    this.readout[index].setTint(colour)
    this.layoutReadout()
  }

  /** Puts the segments that fit in a row, one space apart, from the left margin. */
  private layoutReadout(): void {
    const shown = fitReadout(this.segments, this.readoutChars)
    let x = READOUT_LEFT
    for (let i = 0; i < shown.length; i++) {
      const piece = this.readout[i]
      const words = shown[i]
      piece.setVisible(words !== '')
      if (words === '') continue
      setTextIfChanged(piece, words)
      piece.setX(x)
      x += (words.length + 1) * charWidth('body')
    }
  }

  private updateReadout(snapshot: SessionSnapshot, car: CarSnapshot): void {
    if (car.lap !== this.shownLap) {
      this.shownLap = car.lap
      this.setSegment(LAP, lapCountLine(car.lap), COLOUR.text)
    }
    // The lap in progress: tenths of a second, dashes before the line is first crossed, nothing once the car has finished.
    const sinceMs = car.lapStartMs === null ? null : (snapshot.tick * 1000) / TICK_RATE - car.lapStartMs
    const nowKey = car.state === 'finished' ? -3 : !car.lapValid ? -2 : sinceMs === null ? -1 : Math.floor(sinceMs / 100)
    if (nowKey !== this.shownNow) {
      this.shownNow = nowKey
      this.setSegment(NOW, nowKey === -3 ? '' : currentLapLine(sinceMs, car.lapValid), nowKey === -2 ? COLOUR.bad : COLOUR.text)
    }
    const lastKey = car.lastLapMs ?? -1
    if (lastKey !== this.shownLast) {
      this.shownLast = lastKey
      this.setSegment(LAST, lastLapLine(car.lastLapMs), COLOUR.text)
    }
    const bestKey = car.bestLapMs ?? -1
    if (bestKey !== this.shownBest) {
      this.shownBest = bestKey
      this.setSegment(BEST, bestLapLine(car.bestLapMs), COLOUR.text)
    }
    this.updateGap(snapshot, car)
  }

  /** The gap: rewritten when the gap changes at the tenth, the place changes, or the laps behind change. */
  private updateGap(snapshot: SessionSnapshot, car: CarSnapshot): void {
    let leaderLap = car.lap
    for (let i = 0; i < snapshot.cars.length; i++) if (snapshot.cars[i].position === 1) leaderLap = snapshot.cars[i].lap
    const lapsBehind = Math.max(0, leaderLap - car.lap)
    const gapKey = car.gapAheadMs === null ? -1 : Math.round(car.gapAheadMs / 100)
    // What the gap can say changes with the age of the race: not started, too young to have a gap for everybody, old enough.
    const raceS = car.elapsedMs / 1000
    const age = !(raceS > 0) ? 0 : raceS < RULES.gap.historyS ? 1 : 2
    if (gapKey === this.shownGap && car.position === this.shownGapPosition && lapsBehind === this.shownGapLaps && age === this.shownGapAge) return
    this.shownGap = gapKey
    this.shownGapPosition = car.position
    this.shownGapLaps = lapsBehind
    this.shownGapAge = age
    const words = gapLine(this.kind, car.position, car.gapAheadMs, lapsBehind, raceS)
    this.setSegment(GAP, words, words === formatGap(null) ? COLOUR.accent : COLOUR.dim)
  }

  /** A box is checked for each stop served: those the player began with less those still owed (a void stop is owed again, and its box is empty again). */
  private updatePits(car: CarSnapshot): void {
    const served = Math.min(this.pitsTotal, Math.max(0, this.pitsTotal - car.pitStopsOwed))
    if (served === this.shownServed) return
    this.shownServed = served
    this.pitBoxes.forEach((box, i) => {
      box.empty.setVisible(i >= served)
      box.done.setVisible(i < served)
    })
  }

  /** The PITS section as it is, for the debug hook and the tests; null when the player's car began owing no stop. */
  pits(): PitsInfo | null {
    if (this.pitsLabel === null) return null
    const served = Math.max(0, this.shownServed)
    return {
      total: this.pitsTotal,
      owed: this.pitsTotal - served,
      served,
      label: { ...this.pitsLabel },
      boxes: this.pitBoxes.map((box, i) => ({ x: box.empty.x, y: box.empty.y, w: PITS.box, h: PITS.box, checked: i < served })),
    }
  }

  /** Each tag stands in the slot of its car's position; a tag is moved only when its car's position changes. */
  private updateStrip(snapshot: SessionSnapshot): void {
    for (let i = 0; i < snapshot.cars.length; i++) {
      const car = snapshot.cars[i]
      const slot = car.position - 1
      if (slot === this.shownSlot[car.id]) continue
      this.shownSlot[car.id] = slot
      const tag = this.tags[car.id]
      const x = this.stripLeft + slot * TAG_PITCH
      tag.fill.setX(x)
      tag.number.setX(x + (TAG - charWidth('small')) / 2)
      if (car.id === this.playerId) this.outline.setX(x - TAG_OUTLINE)
    }
  }

  /**
   * The messages: what the table last returned, until its time is up, and then the standing message again if there is
   * one; with the player's clock out and a lap to finish, "TIME UP — FINISH YOUR LAP" under all of them, pulsing
   * (`onLine`). The official says it, through the director, which decides whether it is the official's turn in the
   * window (it always is: his messages come first). The director is told every frame what is on the line, with the
   * seconds counted out and the colour the pulse has now, and when this message came on.
   */
  private updateMessage(tick: Tick, call: EndCall | null): void {
    // The official's own start calls (F-514): each release of a staggered start goes over whatever is on the line, which comes back when it is over; the wait for the player's own release goes under it.
    const start = this.lights.officialCall()
    const message = start !== null && start.text !== 'WAIT' ? start : (onLine(this.line, tick, call) ?? start)
    if (message !== this.shownMessage) {
      this.shownMessage = message
      this.messageSinceS = tick / TICK_RATE
    }
    if (message === null) {
      this.director.official(null)
      return
    }
    const ends = lineEnds(this.line, message)
    const pulse = message.pulse === true && Math.floor(tick / (TICK_RATE / 2)) % 2 === 0
    const colour = message.pulse === true ? (pulse ? COLOUR.bad : COLOUR.text) : MESSAGE_COLOUR[message.tone]
    // A start call is his to make but not his to keep: the start takes it away. Only WAIT stands, with the rest that have no end.
    const startCall = start !== null && message === start && start.text !== 'WAIT'
    this.director.official({
      text: messageText(message, ends, tick) ?? message.text,
      colour,
      standing: isStandingMessage(ends, startCall),
      since: this.messageSinceS,
    })
  }

  /**
   * Once the player's car has finished: "FINISHED" over the classification, a row for each car that has finished, in
   * order, and a row more as each remaining car finishes. "DID NOT FINISH" if the session ends without the player's finish.
   */
  private updateEnd(snapshot: SessionSnapshot, call: EndCall | null): void {
    const shown = call === 'time-up' ? null : call
    let dirty = shown !== this.shownEnd
    this.shownEnd = shown
    if (shown === 'finished') {
      for (let i = 0; i < snapshot.cars.length; i++) {
        const car = snapshot.cars[i]
        const place = car.state === 'finished' ? car.position : -1
        if (place !== this.shownFinish[car.id]) {
          this.shownFinish[car.id] = place
          dirty = true
        }
      }
    }
    if (!dirty) return
    if (shown !== 'finished') {
      this.shownFinish.fill(UNSET)
      this.table.set(null, [], -1)
    } else {
      const finished: FinishedCar[] = []
      for (const car of snapshot.cars) if (car.state === 'finished') finished.push({ id: car.id, position: car.position, lap: car.lap, elapsedMs: car.elapsedMs })
      const { lines, playerRow } = classification(finished, this.options.config.entries, this.playerId, ROSTER)
      this.table.set(END_TEXT.finished, lines, playerRow)
    }
    if (shown === 'did-not-finish') this.end.set([END_TEXT[shown]], END_COLOUR[shown])
    else this.end.set(null, COLOUR.text)
  }

  destroy(): void {
    for (const off of this.release) off()
    this.release.length = 0
    this.lights.destroy()
    this.marker?.destroy()
    this.windSock.destroy()
    this.legend.destroy()
    this.end.destroy()
    this.table.destroy()
    this.lapTime.destroy()
    this.sparkle.destroy()
    for (const frame of this.frames) frame.destroy()
    this.frames.length = 0
    for (const part of this.parts) part.destroy()
    this.parts.length = 0
    this.tags.length = 0
    this.readout.length = 0
  }
}
