import { RULES, type CarColour, type CarId, type DriverProfile, type SessionEntry, type SessionKind, type TrackData } from '@sim'
import { LOGICAL_HEIGHT, LOGICAL_WIDTH, type WorldView } from '../config'
import { THEME, charWidth, lineHeight, type TextSize } from '../ui/theme'
import { ELLIPSIS, tableLines, type TableColumn } from '../ui/layout'
