// What the race HUD says about numbers (F-304), as pure functions: no engine, so they are tested in Node. Every
// character produced here is in the pixel font (a test checks it).

/** Float noise in a clock that is meant to be a whole number of ticks must not tip a displayed second over. */
const EPS = 1e-6
/** From this many seconds down the clock shows tenths. */
const TENTHS_BELOW_S = 10

const pad2 = (n: number): string => String(n).padStart(2, '0')

/**
 * The session clock for `remainingS` seconds to go: whole seconds ("4:55", counting a second down only when it is
 * over, so "0:00" means time is up), tenths under ten seconds ("0:09.4"), and "0:00" at zero or below.
 */
export function formatClock(remainingS: number): string {
  if (!(remainingS > 0)) return '0:00'
  if (remainingS >= TENTHS_BELOW_S) {
    const whole = Math.ceil(remainingS - EPS)
    return `${Math.floor(whole / 60)}:${pad2(whole % 60)}`
  }
  const tenths = Math.floor(remainingS * 10 + EPS)
  return `0:${pad2(Math.floor(tenths / 10))}.${tenths % 10}`
}

/**
 * A number that changes exactly when `formatClock` would show something different, so a caller can compare it
 * every frame and build the text only when it changed. Whole seconds are 1000 and up, tenths 1..100, zero is 0.
 */
export function clockKey(remainingS: number): number {
  if (!(remainingS > 0)) return 0
  if (remainingS >= TENTHS_BELOW_S) return 1000 + Math.ceil(remainingS - EPS)
  return Math.floor(remainingS * 10 + EPS) + 1
}

/** A lap time to the hundredth: "12.84", "1:02.31". */
export function formatLap(ms: number): string {
  const hundredths = Math.round(ms / 10)
  const minutes = Math.floor(hundredths / 6000)
  const seconds = Math.floor((hundredths % 6000) / 100)
  const rest = pad2(hundredths % 100)
  return minutes > 0 ? `${minutes}:${pad2(seconds)}.${rest}` : `${seconds}.${rest}`
}

/** The lap in progress, to the tenth: "7.3", "1:02.3". It changes ten times a second, not a hundred. */
export function formatLiveLap(ms: number): string {
  const tenths = Math.max(0, Math.floor(ms / 100))
  const minutes = Math.floor(tenths / 600)
  const seconds = Math.floor((tenths % 600) / 10)
  return minutes > 0 ? `${minutes}:${pad2(seconds)}.${tenths % 10}` : `${seconds}.${tenths % 10}`
}

/** How far behind the car ahead: "+1.4" to the tenth; "LEADER" for no car ahead. */
export function formatGap(ms: number | null): string {
  if (ms === null) return 'LEADER'
  return `+${(Math.round(ms / 100) / 10).toFixed(1)}`
}

/** Which colour a lap flash takes: the session's best beats the driver's own best, which beats neither. */
export function lapTone(e: { personalBest: boolean; sessionBest: boolean }): 'session' | 'personal' | 'plain' {
  if (e.sessionBest) return 'session'
  return e.personalBest ? 'personal' : 'plain'
}

/** "P4". */
export const formatPosition = (position: number): string => `P${position}`

/** Shown where a lap time does not exist yet. */
const NO_LAP = '--.--'

/** The line that says which lap the car is on: laps completed, plus the one it is in. */
export const lapCountLine = (completed: number): string => `LAP ${completed + 1}`
export const lastLapLine = (ms: number | null): string => `LAST ${ms === null ? NO_LAP : formatLap(ms)}`
export const bestLapLine = (ms: number | null): string => `BEST ${ms === null ? NO_LAP : formatLap(ms)}`

/** The current lap: its time so far, "NOW VOID" once it cannot count (the lap line is one line, so "LAP NOT COUNTED" is shortened), dashes before the car has crossed the line. */
export function currentLapLine(sinceStartMs: number | null, valid: boolean): string {
  if (!valid) return 'NOW VOID'
  return `NOW ${sinceStartMs === null ? '-.-' : formatLiveLap(sinceStartMs)}`
}

/**
 * The segments of the one-line lap readout (lap, current, last, best, gap) as they fit in `maxChars` characters with a
 * space between neighbours. When they do not fit, the gap is dropped first and then the current lap; the lap count and
 * the last and best times always stay. An empty segment takes no room. Returns the segments to show, empty for a dropped one.
 */
export function fitReadout(segments: readonly string[], maxChars: number): string[] {
  const shown = [...segments]
  const width = (): number => {
    const used = shown.filter((segment) => segment !== '')
    return used.reduce((n, segment) => n + segment.length, 0) + Math.max(0, used.length - 1)
  }
  for (const drop of [4, 1]) {
    if (width() > maxChars) shown[drop] = ''
  }
  return shown
}

/** A rectangle on the 1920 x 1080 canvas, in pixels. */
export interface PixelRect {
  x: number
  y: number
  w: number
  h: number
}

/**
 * The track's rectangle on screen: the slab, the closed edge wall that fences the track in (the plain green rectangle
 * of the art direction), taken through the view's own mapping. What is round it is outfield, and that is where the HUD lives.
 * A track with no such wall has its bounds.
 */
export function trackRect(track: TrackData, view: WorldView): PixelRect {
  let minX = Infinity
  let minY = Infinity
  let maxX = -Infinity
  let maxY = -Infinity
  for (const wall of track.walls) {
    if (!wall.closed || wall.kind !== 'edge') continue
    for (const [x, y] of wall.polyline) {
      minX = Math.min(minX, x)
      minY = Math.min(minY, y)
      maxX = Math.max(maxX, x)
      maxY = Math.max(maxY, y)
    }
  }
  if (minX === Infinity) [minX, minY, maxX, maxY] = [0, 0, track.bounds.w, track.bounds.h]
  const x = view.originX + minX * view.pxPerM
  const y = view.originY + minY * view.pxPerM
  return { x, y, w: (maxX - minX) * view.pxPerM, h: (maxY - minY) * view.pxPerM }
}

/**
 * The gap segment of the lap readout. A final shows the gap to the car ahead, "LEADER" in first place; a car that has no
 * gap shows laps behind the leader, or "+30+" when it is on the leader's lap but further back than the sim keeps
 * track of (`RULES.gap.historyS`). The sim has no gap for a car in the first seconds of a race either, so until the
 * race is that old a missing gap shows nothing. Qualifying and practice have no gap to show, and before the start
 * tone there is none yet: the line is empty. `raceS` is the race clock, 0 until the tone.
 */
export function gapLine(kind: SessionKind, position: number, gapAheadMs: number | null, lapsBehind: number, raceS: number): string {
  if (kind !== 'final' || !(raceS > 0)) return ''
  if (position === 1) return formatGap(null)
  if (gapAheadMs !== null) return formatGap(gapAheadMs)
  if (lapsBehind >= 1) return `-${lapsBehind} ${lapsBehind === 1 ? 'LAP' : 'LAPS'}`
  return raceS >= RULES.gap.historyS ? `+${RULES.gap.historyS}+` : ''
}

/**
 * The seven body colours as the art build paints them (their base step, spec/00-product/art-direction.md): what an
 * order-strip tag is filled with. The garage keeps the same table for its swatches.
 */
