// ── The lap time shown at the end of a lap ──────────────────────────────────────────────────────────────────

/** The first of the two lines shown when the player completes a lap. */
export const LAP_TIME_TITLE = 'LAP TIME'
/** The second: the time to the hundredth, and the unit: "21.43 s". */
export const lapTimeLine = (ms: number): string => `${formatLap(ms)} s`

/** How long it stays, in session seconds (under three), and how long it is on and then off while it flashes. */
export const LAP_TIME_SECONDS = 2.4
export const LAP_TIME_BLINK_S = 0.25

/** Whether the lap time is drawn `ageS` seconds after the lap: on for the first blink, then off, then on, until it is over. */
export function lapTimeShown(ageS: number): boolean {
  return ageS >= 0 && ageS < LAP_TIME_SECONDS && Math.floor(ageS / LAP_TIME_BLINK_S) % 2 === 0
}

// ── Accents (F-802) ────────────────────────────────────────────────────────────────────────────────────────────

/** How long the arrow beside the position stays after the position changes, in session seconds. */
export const ARROW_SECONDS = 2

/** The arrow to show when the player's position goes from `before` to `now`: up for a place gained, down for one lost; none for no change or no place (the first one, given at the start, is not a change). */
export function positionArrow(before: number, now: number): 'up' | 'down' | null {
  if (before <= 0 || now <= 0 || before === now) return null
  return now < before ? 'up' : 'down'
}

/** Whether the arrow is drawn `ageS` seconds after the position changed. */
export function arrowShown(ageS: number): boolean {
  return ageS >= 0 && ageS < ARROW_SECONDS
}

/** The sparkles round the player's car on a personal best: where each is from the car's centre, px, and when it starts after the lap, s. */
export const SPARKLES: ReadonlyArray<{ dx: number; dy: number; delayS: number }> = [
  { dx: -18, dy: -12, delayS: 0 },
  { dx: 16, dy: -16, delayS: 0.12 },
  { dx: 4, dy: 18, delayS: 0.24 },
]

/** The frame of a sparkle `ageS` seconds after the lap, starting at `delayS`, or null before it starts and after its last frame: it plays once. */
export function sparkleFrame(ageS: number, delayS: number, frames: number, fps: number): number | null {
  if (ageS < delayS) return null
  const frame = Math.floor((ageS - delayS) * fps + 1e-9)
  return frame < frames ? frame : null
}

// ── The classification, once the player has finished ────────────────────────────────────────────────────────

/** The columns of the table: a mark for the player's row, position, car number, driver, laps and time. */
export const CLASSIFICATION_COLUMNS: readonly TableColumn[] = [
  { key: 'mark', title: '', chars: 1, align: 'left' },
  { key: 'pos', title: 'POS', chars: 3, align: 'right' },
  { key: 'no', title: 'NO', chars: 2, align: 'right' },
  { key: 'name', title: 'DRIVER', chars: 17, align: 'left' },
  { key: 'laps', title: 'LAPS', chars: 4, align: 'right' },
  { key: 'time', title: 'TIME', chars: 8, align: 'right' },
]

/** What the table reads of a car that has finished. */
export interface FinishedCar {
  id: CarId
  /** Its place now: the sim re-orders the cars as each finishes. */
  position: number
  /** Laps completed. */
  lap: number
  /** Its clock when it last crossed the line, ms. */
  elapsedMs: number
}

/**
 * The lines of the classification: the header, then a row for each car that has finished, best placed first (sorted
 * here by the sim's own place, so a car that finishes ahead of one already shown takes its row). The player's row
 * has the cursor glyph in front of it; `playerRow` is its index among the rows, or -1. Driver names are the roster's,
 * in capitals, and the name the player set (YOU when none) for the player.
 */
export function classification(
  finished: readonly FinishedCar[],
  entries: readonly SessionEntry[],
  playerId: CarId | null,
  roster: readonly DriverProfile[],
): { lines: string[]; playerRow: number } {
  const order = [...finished].sort((a, b) => a.position - b.position)
  const playerDriver = playerId === null ? '' : (entries[playerId]?.driverId ?? '')
  const rows = order.map((car, i) => {
    const entry = entries[car.id]
    return {
      mark: car.id === playerId ? THEME.cursorGlyph : '',
      pos: String(i + 1),
      no: String(entry?.number ?? car.id + 1),
      name: driverName(entry?.driverId ?? '', playerDriver, roster),
      laps: String(car.lap),
      time: formatLap(car.elapsedMs),
    }
  })
  return { lines: tableLines(CLASSIFICATION_COLUMNS, rows), playerRow: order.findIndex((car) => car.id === playerId) }
}

// ── PITS and its boxes in the top band (F-514) ──────────────────────────────────────────────────────────────

/** The label of the section, in the readout's `body` size. */
export const PITS_TEXT = 'PITS'
/**
 * The section's measures, px: a box is `ui.check.empty` / `ui.check.done` (12 art pixels, 24 on screen), set `boxDrop`
 * below the top of the label's line where it sits round the capitals; at most `maxBoxes` are drawn, so that the lap
 * readout keeps its lap, last and best times (27 characters) in the room that is left of it.
 */
export const PITS = { box: 24, boxGap: 6, labelGap: 12, positionGap: 24, boxDrop: 4, maxBoxes: 6 } as const

/** Where the pieces of the section are: its left edge, the label's, and the left edge of each box. */
export interface PitsLayout {
  left: number
  labelX: number
  boxes: number[]
}

/**
 * The section for a player who started owing `owed` stops, its right edge `PITS.positionGap` left of `positionLeft`,
 * where the position and the clock begin: PITS, then a box for each stop (`PITS.maxBoxes` at most).
 */
export function pitsSection(owed: number, positionLeft: number): PitsLayout {
  const count = Math.min(Math.max(0, Math.floor(owed)), PITS.maxBoxes)
  const label = PITS_TEXT.length * charWidth('body')
  const width = label + PITS.labelGap + count * PITS.box + Math.max(0, count - 1) * PITS.boxGap
  const left = positionLeft - PITS.positionGap - width
  const first = left + label + PITS.labelGap
  return { left, labelX: left, boxes: Array.from({ length: count }, (_, i) => first + i * (PITS.box + PITS.boxGap)) }
}

// ── The class legend and the round (F-711, F-712) ───────────────────────────────────────────────────────────────

/** The legend is the HUD's small text, and a gap of this many pixels is kept between it and the weather pieces on its right. */
export const LEGEND_SIZE: TextSize = 'small'
export const LEGEND_GAP = 24

/** The room a big number keeps above and below it in the top band, and the legend's column with it. */
export const BAND_MARGIN = 4

/**
 * The session's round as it is said under the class (F-712): QUAL N or FINAL LEG N in a race day, whose sessions are
 * labelled "Qualifying round N" and "Final leg N" (`sessionLabel` in the sim); QUALIFYING or FINAL in a quick race, which
 * has one of each; PRACTICE in practice. The session's kind decides, the label only gives the number.
 */
export function roundWords(kind: SessionKind, label: string): string {
  if (kind === 'practice') return 'PRACTICE'
  const number = (kind === 'qualifying' ? /^qualifying round (\d+)$/i : /^final leg (\d+)$/i).exec(label)?.[1]
  if (kind === 'qualifying') return number === undefined ? 'QUALIFYING' : `QUAL ${number}`
  return number === undefined ? 'FINAL' : `FINAL LEG ${number}`
}

/** One line of the legend's column: its words and the box they cover. */
export interface LegendLine extends PixelRect {
  text: string
}

/**
 * Where the class legend and the round stand in the top band (F-712): a column of lines of `LEGEND_SIZE` text, the class
 * over the round, right-aligned so that the right edge is `LEGEND_GAP` left of the first of the weather pieces (the wind
 * arrow, at `weatherLeft`), the column centred on the band's height. Two lines of 24 px are 48 px: with the band's 56 they
 * leave the 4 px `BAND_MARGIN` above and below, the room the position and clock keep. The words grow to the left, into the
 * room the order strip leaves; it is the same place for every field size, so that it does not move from one race to the next.
 */
export function legendColumn(words: readonly string[], weatherLeft: number, bandHeight: number): { box: PixelRect; lines: LegendLine[] } {
  const h = lineHeight(LEGEND_SIZE)
  const widths = words.map((text) => text.length * charWidth(LEGEND_SIZE))
  const w = Math.max(0, ...widths)
  const box: PixelRect = { x: weatherLeft - LEGEND_GAP - w, y: Math.round((bandHeight - words.length * h) / 2), w, h: words.length * h }
  const lines = words.map((text, i): LegendLine => ({ text, x: box.x + w - (widths[i] ?? 0), y: box.y + i * h, w: widths[i] ?? 0, h }))
  return { box, lines }
}

/** The divider between the column and the weather pieces is this many pixels wide: one art pixel of the HUD's density. */
export const DIVIDER_WIDTH = 2

/**
 * Where the thin vertical divider between the class-and-round column and the weather pieces stands (F-712): centred in the
 * gap between the column's right edge and `weatherLeft`, as high as the column, so that it is inside the band's margins
 * with it.
 */
export function legendDivider(column: PixelRect, weatherLeft: number, bandHeight: number): PixelRect {
  const right = column.x + column.w
  const h = column.h
  return { x: Math.floor((right + weatherLeft - DIVIDER_WIDTH) / 2), y: Math.round((bandHeight - h) / 2), w: DIVIDER_WIDTH, h }
}

// ── The band below the track (F-509) ────────────────────────────────────────────────────────────────────────
//
// Left to right along the foot of the screen: the official's portrait over the trees, with his speech bubble beside
// him, then the driver stand (in front of the pit, covering its whole width, with the pit tables behind it), then the
// key hints on one plate at the right end (in practice, the lap readout left of the hints). Everything is placed in
// the 1920 x 1080 canvas; a bigger or smaller window scales the whole canvas. The band's top is the stand's upper edge:
// the lowest point of the asphalt, so that nothing in it covers a road, a kerb, the pit lane or a start box.

/** The room between the screen's edge and the plates at the foot of it, and between the plate's edge and its words, px. */
export const BAND_EDGE = 24
export const PLATE_PAD = 12
/** The room kept between two things in the band, px. */
export const BAND_GAP = 12

/** How many of the hints, between their three-space separators, are driving keys: they are the first line. */
const DRIVING_KEYS = 3

/**
 * The key hints as the two lines of their plate: the driving keys on the first, everything else (pause, and the
 * tuning and racing-line keys in the builds that have them) on the second. The words are the hint's own, unchanged.
 */
export function hintLines(hint: string): [string, string] {
  const keys = hint.split('   ')
  return [keys.slice(0, DRIVING_KEYS).join('   '), keys.slice(DRIVING_KEYS).join('   ')]
}

/**
 * The key hints' plate: its right edge `BAND_EDGE` inside the canvas's (or at `right`), its foot `BAND_EDGE` above the
 * canvas's, as wide as the longer line and a pad round it, two lines of `small` text high.
 */
export function hintsPlate(lines: readonly string[], right: number = LOGICAL_WIDTH - BAND_EDGE): PixelRect {
  const w = Math.max(...lines.map((line) => line.length), 0) * charWidth('small') + 2 * PLATE_PAD
  const h = lines.length * lineHeight('small') + 2 * PLATE_PAD
  return { x: right - w, y: LOGICAL_HEIGHT - BAND_EDGE - h, w, h }
}

/** The official's portrait window on screen, px (`official.idle` is 48 art pixels, shown at two). */
export const OFFICIAL_PX = 96
/** The room between the band's top and the portrait's top, px. */
const OFFICIAL_DROP = 8

/** The official's window: at the left margin (or at `left`, on a screen that has no room there), a little under the band's top (`bandTop`, the stand's upper edge). */
export function officialWindow(bandTop: number, left: number = BAND_EDGE): PixelRect {
  return { x: left, y: bandTop + OFFICIAL_DROP, w: OFFICIAL_PX, h: OFFICIAL_PX }
}

/**
 * How a speech bubble is built, screen px (art pixels are two screen pixels): `corner` is the nine-slice's corner, the
 * tail sticks out of the bubble by `tail`, and `inset` is the room between the box's edge and the words (the skin's
 * rim, 2 art pixels, and its padding, 3: `art/out/ui/stats.json`).
 */
export const BUBBLE = { corner: 8, inset: 10, tail: 12, tallest: 96 } as const

/** The commentator's words: the small size, the HUD's light text colour, three lines at most (F-703). */
export const COMMENTARY_SIZE: TextSize = 'small'

/** The most lines the official's bubble holds, and the commentator's (F-703). */
const BUBBLE_LINES = 2
const COMMENTARY_LINES = 3

/** The room the bubble keeps from the stand, px: less than the other gaps, so that the longest warning (27 characters) stays on one line. */
const BUBBLE_STAND_GAP = 6

/**
 * The room the official's bubble may take, tail included: from a gap right of his window to a little short of the stand
 * (or the canvas's margin where there is none), `BUBBLE.tallest` high and centred on the window's middle.
 */
export function bubbleRegion(window: PixelRect, standLeft: number | null): PixelRect {
  const x = window.x + window.w + BAND_GAP
  const right = standLeft === null ? LOGICAL_WIDTH - BAND_EDGE : standLeft - BUBBLE_STAND_GAP
  return { x, y: window.y + window.h / 2 - BUBBLE.tallest / 2, w: Math.max(0, right - x), h: BUBBLE.tallest }
}

/** A bubble as laid out: the words' size and lines, the body's box (the tail lies outside it, to its left) and where the tail meets the left edge. */
export interface BubbleLayout {
  size: TextSize
  lines: string[]
  /** The body, without the tail. */
  box: PixelRect
  /** The tail's tip is this far down the left edge, px (an even number: a whole number of art pixels). */
  tailAlong: number
}

/**
 * Breaks `words` at its spaces into at most `maxLines` lines of at most `maxChars` characters: on one line if it fits,
 * otherwise on as few lines as will hold it, split where the longest line is shortest, so that the lines are as even as
 * the words allow. A dash stays with the word before it, so that no line begins with one. Null if it will not go.
 */
export function wrapWords(words: string, maxChars: number, maxLines = BUBBLE_LINES): string[] | null {
  if (words.length <= maxChars) return [words]
  if (maxLines < 2) return null
  const tokens = words.split(' ').reduce<string[]>((made, word) => {
    if (word === '—' && made.length > 0) made[made.length - 1] += ' —'
    else made.push(word)
    return made
  }, [])
  for (let count = 2; count <= Math.min(maxLines, tokens.length); count++) {
    const best = evenestSplit(tokens, count)
    if (best !== null && Math.max(...best.map((line) => line.length)) <= maxChars) return best
  }
  return null
}

/** `tokens` in `count` lines, the longest line as short as it can be and, among those, the lines as even as they can be (the first such split on a tie); null when there are not enough tokens. */
function evenestSplit(tokens: readonly string[], count: number): string[] | null {
  let best: string[] | null = null
  let bestScore: [number, number] = [Infinity, Infinity]
  const cuts: number[] = []
  const walk = (from: number): void => {
    if (cuts.length === count - 1) {
      const edges = [0, ...cuts, tokens.length]
      const lines = edges.slice(1).map((end, i) => tokens.slice(edges[i], end).join(' '))
      const longest = Math.max(...lines.map((line) => line.length))
      const spread = lines.reduce((sum, line) => sum + line.length * line.length, 0)
      if (longest < bestScore[0] || (longest === bestScore[0] && spread < bestScore[1])) {
        best = lines
        bestScore = [longest, spread]
      }
      return
    }
    for (let cut = from; cut < tokens.length - (count - 2 - cuts.length); cut++) {
      cuts.push(cut)
      walk(cut + 1)
      cuts.pop()
    }
  }
  if (tokens.length < count) return null
  walk(1)
  return best
}

const EVEN = (n: number): number => 2 * Math.round(n / 2)

/**
 * The bubble for `words` in `region`: as big as its words need. At `large` on one line where it fits, otherwise at
 * `body` on one line or two; and `small` on two only for words that fit neither (no message does today). The body is
 * centred on the region's middle, left edge a tail's length in from the region's.
 */
export function layoutBubble(words: string, region: PixelRect): BubbleLayout {
  const room = region.w - BUBBLE.tail - 2 * BUBBLE.inset
  const tries: Array<[TextSize, number]> = [['large', 1], ['body', BUBBLE_LINES], ['small', BUBBLE_LINES]]
  let size: TextSize = 'small'
  let lines: string[] = [words]
  for (const [candidate, maxLines] of tries) {
    const wrapped = wrapWords(words, Math.floor(room / charWidth(candidate)), maxLines)
    if (wrapped !== null) {
      size = candidate
      lines = wrapped
      break
    }
  }
  return bubbleAround(size, lines, region)
}

/** The body for `lines` at `size` in `region`: centred on the region's middle, its left edge a tail's length in from the region's, the tail meeting the left edge at the middle. */
function bubbleAround(size: TextSize, lines: string[], region: PixelRect): BubbleLayout {
  const w = Math.max(...lines.map((line) => line.length)) * charWidth(size) + 2 * BUBBLE.inset
  const h = lines.length * lineHeight(size) + 2 * BUBBLE.inset
  const centre = region.y + region.h / 2
  const y = Math.min(Math.max(EVEN(centre - h / 2), region.y), region.y + region.h - h)
  // The tail is 16 px tall about its tip: between the corners.
  const tailAlong = Math.min(Math.max(EVEN(centre - y), 2 * BUBBLE.corner), h - 2 * BUBBLE.corner)
  return { size, lines, box: { x: region.x + BUBBLE.tail, y, w, h }, tailAlong }
}

/**
 * The commentator's bubble for `words` in `region` (F-703): always the `small` size, in as few as three lines, centred
 * as the official's is. Three lines of `small` are 92 px with the inset, inside the bubble's 96. Words that will not
 * go in three lines (the library keeps them short; this is for the ones that slip through) are cut at a space and end in the font's
 * ellipsis, so that the bubble never spills out of the band.
 */
export function layoutCommentary(words: string, region: PixelRect): BubbleLayout {
  const maxChars = Math.max(1, Math.floor((region.w - BUBBLE.tail - 2 * BUBBLE.inset) / charWidth(COMMENTARY_SIZE)))
  const whole = wrapWords(words, maxChars, COMMENTARY_LINES)
  if (whole !== null) return bubbleAround(COMMENTARY_SIZE, whole, region)
  const kept = words.split(' ')
  while (kept.length > 1) {
    kept.pop()
    const cut = wrapWords(`${kept.join(' ')}${ELLIPSIS}`, maxChars, COMMENTARY_LINES)
    if (cut !== null) return bubbleAround(COMMENTARY_SIZE, cut, region)
  }
  return bubbleAround(COMMENTARY_SIZE, [`${words.slice(0, Math.max(0, maxChars - ELLIPSIS.length))}${ELLIPSIS}`], region)
}

/**
 * Whether a message of the official's stands: it has no end (`ends` is Infinity) and is not a start call, which the
 * start itself makes and takes away again. A standing message is shown first, and the commentator talks in its
 * gaps (CommentaryDirector).
 */
export const isStandingMessage = (ends: number, startCall: boolean): boolean => ends === Infinity && !startCall
