/**
 * A fixed list of options with one of them showing, stepped with left and right and cycling round the ends. The
 * model behind `Selector`; pure, so its rules are tested without an engine.
 */
export class OptionCursor<T> {
  private index: number
  private readonly listeners: Array<(value: T) => void> = []

  constructor(
    readonly options: ReadonlyArray<{ value: T; label: string }>,
    initial: T,
  ) {
    if (options.length === 0) throw new Error('OptionCursor: there must be at least one option')
    this.index = Math.max(0, this.indexOf(initial))
  }

  get value(): T {
    return this.options[this.index]?.value as T
  }

  get label(): string {
    return this.options[this.index]?.label ?? ''
  }

  /** Subscribes to changes; the listener is given the new value. */
  onChange(fn: (value: T) => void): void {
    this.listeners.push(fn)
  }

  /** Steps to the next (+1) or previous (-1) option, cycling, and tells the listeners. With one option nothing changes. */
  step(delta: 1 | -1): void {
    const count = this.options.length
    if (count < 2) return
    this.index = (this.index + delta + count) % count
    for (const fn of this.listeners) fn(this.value)
  }

  /** Shows `value` without telling the listeners (the caller already knows). An unknown value is ignored. */
  set(value: T): void {
    const at = this.indexOf(value)
    if (at >= 0) this.index = at
  }

  private indexOf(value: T): number {
    return this.options.findIndex((option) => option.value === value)
  }
}
