/// <reference lib="dom" />
import type { Failure } from './failure'

// The failure as an HTML panel, for the two times the game has nothing of its own to draw it with: the page has no WebGL
// (no engine can start) and the font did not arrive (the engine is up, but there are no letters). This is the one place
// the game uses DOM text, and the reason it is allowed to (AGENTS.md rule 5 is about the game's screens).

const PANEL_ID = 'mrr-failure'

/** Puts the failure on the page, over everything, replacing any that is there. Returns the panel. */
export function showFailureDom(failure: Failure, parent: HTMLElement = document.body): HTMLElement {
  document.getElementById(PANEL_ID)?.remove()
  const panel = document.createElement('div')
  panel.id = PANEL_ID
  panel.setAttribute('role', 'alert')
  Object.assign(panel.style, {
    position: 'fixed',
    inset: '0',
    zIndex: '10',
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '16px',
    padding: '24px',
    boxSizing: 'border-box',
    background: '#16161e',
    color: '#eef1f6',
    font: '18px/1.5 ui-monospace, Menlo, Consolas, monospace',
    textAlign: 'center',
  })
  const heading = document.createElement('h1')
  heading.textContent = failure.title
  Object.assign(heading.style, { margin: '0', color: '#f0bc1e', font: 'bold 28px/1.3 ui-monospace, Menlo, Consolas, monospace' })
  panel.append(heading)
  for (const line of failure.lines) {
    const p = document.createElement('p')
    p.textContent = line
    Object.assign(p.style, { margin: '0', maxWidth: '40em' })
    panel.append(p)
  }
  parent.append(panel)
  return panel
}

/** Takes the panel off the page, if it is there. */
export function hideFailureDom(): void {
  document.getElementById(PANEL_ID)?.remove()
}
