import type { CarClassId } from '@sim'
import type { AssetManifest } from '../assets/manifest'

/** The key of the atlas that holds a class's car sprites, found through the manifest's own entry for its red body. */
export function atlasKeyFor(manifest: AssetManifest, carClass: CarClassId): string {
  const entry = manifest.sprites[`car.${carClass}.red`]
  if (entry === undefined) throw new Error(`The manifest has no sprite for class '${carClass}'`)
  return entry.atlas
}

/** The file paths of an atlas, as the manifest lists them, below `assets/`. */
export function atlasFiles(manifest: AssetManifest, atlasKey: string): { image: string; data: string } {
  const atlas = manifest.atlases.find((a) => a.key === atlasKey)
  if (atlas === undefined) throw new Error(`The manifest has no atlas '${atlasKey}'`)
  return { image: atlas.image, data: atlas.data }
}
