import { THEME, charWidth, type TextSize } from './theme'

// Text layout on the pixel font's fixed character grid: every character is as wide as every other, so a column is a
// number of characters and a panel holds a number of columns. Pure, so it is tested without an engine.

export interface Rect {
  x: number
  y: number
  w: number
  h: number
}

/** The name every panel's outside rectangle carries, so that tools (the debug hook) can find the panels on screen. */
export const PANEL_NAME = 'panel'

/** The font has this glyph (U+2026). */
export const ELLIPSIS = '…'

/** `text` cut to at most `chars` characters, ending in an ellipsis if anything was cut. */
export function truncate(text: string, chars: number): string {
  if (chars <= 0) return ''
  if (text.length <= chars) return text
  return chars === 1 ? ELLIPSIS : `${text.slice(0, chars - 1)}${ELLIPSIS}`
}

/** `text` truncated, then padded with spaces to exactly `chars` characters. */
export function padCell(text: string, chars: number, align: 'left' | 'right'): string {
  const cut = truncate(text, chars)
  return align === 'right' ? cut.padStart(chars) : cut.padEnd(chars)
}

/** How many characters of `size` fit across `widthPx`. */
export const charsAcross = (widthPx: number, size: TextSize): number => Math.max(0, Math.floor(widthPx / charWidth(size)))

/** How many characters of `size` fit across a panel's inside (its width less the padding on both sides). */
export const charsInPanel = (panelWidthPx: number, size: TextSize): number => charsAcross(panelWidthPx - 2 * THEME.padding, size)

/**
 * `text` broken into lines of at most `chars` characters at spaces. A word longer than a line is cut with an ellipsis
 * rather than allowed to run on.
 */
export function wrapText(text: string, chars: number): string[] {
  if (chars <= 0) return []
  const lines: string[] = []
  let line = ''
  for (const word of text.split(/\s+/).filter((w) => w.length > 0)) {
    const piece = truncate(word, chars)
    if (line === '') line = piece
    else if (line.length + 1 + piece.length <= chars) line = `${line} ${piece}`
    else {
      lines.push(line)
      line = piece
    }
  }
  if (line !== '') lines.push(line)
  return lines
}

export interface TableColumn {
  key: string
  title: string
  chars: number
  align: 'left' | 'right'
}

/** Blank characters between two columns. */
export const COLUMN_GAP = 1

/** The width of the whole grid in characters. */
export const tableChars = (columns: readonly TableColumn[]): number =>
  columns.reduce((sum, column) => sum + column.chars, 0) + COLUMN_GAP * Math.max(0, columns.length - 1)

/** One line of the grid: every cell cut or padded to its column, joined by the gap, the whole cut to `maxChars` if given. */
export function tableLine(columns: readonly TableColumn[], cells: Readonly<Record<string, string>>, maxChars = Infinity): string {
  const line = columns.map((column) => padCell(cells[column.key] ?? '', column.chars, column.align)).join(' '.repeat(COLUMN_GAP))
  return truncate(line, maxChars)
}

/** The header line, then one line per row. */
export function tableLines(columns: readonly TableColumn[], rows: ReadonlyArray<Readonly<Record<string, string>>>, maxChars = Infinity): string[] {
  const header = Object.fromEntries(columns.map((column) => [column.key, column.title]))
  return [header, ...rows].map((cells) => tableLine(columns, cells, maxChars))
}
