import type { SimEvent } from '@sim'

/**
 * One of the commentator's lines (F-702). The shape is that of the engine's `LineTemplate` (contracts.md §10; a test
 * holds it to that); it is declared here because content does not import the engine. Every line is the commentator's:
 * the official's words are the HUD's message table.
 */
export interface CommentaryLine {
  id: string
  voice: 'commentator'
  trigger: SimEvent['type'] | 'filler' | 'session-result' | 'event-result'
  when?: string
  text: string
  priority: number
  ttlS: number
  cooldownS: number
}

/** Lines that share a trigger, a condition and their numbers. */
export interface LineGroup {
  trigger: CommentaryLine['trigger']
  when?: string
  /** Names the group in its ids, after the condition: `filler.bio.3`, `phase.final.grid.2`. */
  key?: string
  priority: number
  ttlS: number
  cooldownS: number
  texts: readonly string[]
}

/** The groups' lines, with ids `trigger.condition.key.n`, or `trigger.any.n` for a group with neither. */
export const linesOf = (groups: readonly LineGroup[]): readonly CommentaryLine[] =>
  groups.flatMap(({ trigger, when, key, priority, ttlS, cooldownS, texts }) => {
    const name = [when, key].filter((part) => part !== undefined).join('.') || 'any'
    return texts.map((text, i): CommentaryLine => ({
      id: `${trigger}.${name}.${i + 1}`,
      voice: 'commentator',
      trigger,
      ...(when === undefined ? {} : { when }),
      text,
      priority,
      ttlS,
      cooldownS,
    }))
  })
