import { SKIES, type CarClassId, type Classification, type Direction, type DriverId, type EventSettings, type Forecast, type RaceDayState, type SessionResult, type WeatherPlan } from '@sim'
import { DEFAULT_BINDINGS, readBindings, type Bindings } from '../input/bindings'
import type { QuickRaceChoices } from '../race/quick-race'
import { cleanName } from './name'
import { compareLap, compareRace, isInitials, isLapEntry, isRaceEntry, RACE_MINUTES, sanitiseTables, type LapEntry, type RaceEntry } from '../leaderboard/boards'

// What the game remembers between visits (F-405, contracts.md §12). Pure data and a few functions: no Phaser, and the
// storage is a parameter, so all of it runs in Node against a fake. Every storage access is wrapped: blocked or
// private-mode storage means "nothing is remembered", never an error.

/** The one key the game writes. Nothing but `SaveData` is ever stored under it. */
export const STORAGE_KEY = 'mini-rc-racers/v1'

/** The browser's storage as far as the game uses it. */
export type ReadableStorage = Pick<Storage, 'getItem'>
export type WritableStorage = Pick<Storage, 'setItem'>
export type RemovableStorage = Pick<Storage, 'removeItem'>

/** Top-10 tables (F-406): each sorted best first and at most ten long. Lap tables are keyed by `lapKey`, race tables by `raceKey`. */
export interface Leaderboards {
  lap: Record<string, LapEntry[]>
  race: Record<string, RaceEntry[]>
}

/** The round lengths a race can be run at; a best race is kept for each. */
export type RoundMinutes = 3 | 5 | 7
export const ROUND_MINUTES: readonly RoundMinutes[] = RACE_MINUTES

export interface BestRace {
  laps: number
  timeMs: number
  /** Set with DRIVING ASSISTANCE on (F-811): shown with (A*). Absent for one set with it off, and for every best of a save made before it. */
  assisted?: true
}

export interface Best {
  bestLapMs: number | null
  /** The best lap was set with DRIVING ASSISTANCE on (F-811); absent otherwise, as in a save made before it. */
  bestLapAssisted?: true
  /** The best race at each round length: a 3-minute race is compared only with the stored 3-minute race. */
  bestRace: Partial<Record<RoundMinutes, BestRace>>
}

export interface SaveData {
  schema: 1
  settings: {
    /** The spoken commentary and race control (F-703): off until the player turns it on (key V). */
    tts: boolean
    /** The names of the voices the player chose in the options (F-801); null is the game's own choice (F-708). The official was "race control" before F-801: an older save's `raceControlVoice` is read as his. */
    commentatorVoice: string | null
    officialVoice: string | null
    volume: { master: number; sfx: number; voice: number }
    /**
     * DRIVING ASSISTANCE (F-811): the player's car has the NEWBIE setup in every session, and the records it sets are marked
     * (A*). Off for a fresh save and for one made before it: the `steerAssist` of an older save meant something else and is not read.
     */
    drivingAssistance: boolean
    /** The keys that drive (F-801), as `KeyboardEvent.code`: the arrows and P for a fresh save and for one made before they could be changed. */
    bindings: Bindings
    /** The ambient music (F-705): on or off. On for a fresh save and for one made before it existed. */
    music: boolean
    lastEvent: Partial<EventSettings>
    /** The quick-race screen's choices when a quick race was last started (F-808), as stored: read through `quickChoicesFrom`, which puts the default in for anything missing or damaged. Empty for a fresh save and for one made before they were kept. */
    lastQuickRace: Partial<QuickRaceChoices>
    lastInitials: string | null
    /** What the player is called on the screens (F-407); null is no name, and the screens say YOU. View-side only: the sim's id for the player stays 'player'. */
    driverName: string | null
  }
  /** Keyed by `bestKey`. */
  bests: Record<string, Best>
  eventInProgress: RaceDayState | null
  lastClassification: { settings: EventSettings; rows: Classification[] } | null
  leaderboards: Leaderboards
}

/** A fresh save: the defaults of every setting, no bests, no event, empty leaderboards. */
export function defaultSave(): SaveData {
  return {
    schema: 1,
    settings: {
      tts: false,
      commentatorVoice: null,
      officialVoice: null,
      volume: { master: 0.8, sfx: 0.8, voice: 1 },
      drivingAssistance: false,
      bindings: { ...DEFAULT_BINDINGS },
      music: true,
      lastEvent: {},
      lastQuickRace: {},
      lastInitials: null,
      driverName: null,
    },
    bests: {},
    eventInProgress: null,
    lastClassification: null,
    leaderboards: { lap: {}, race: {} },
  }
}

/** The key of a track, direction and class in `bests` (and in the leaderboards' lap tables). */
export const bestKey = (trackId: string, direction: Direction, carClass: CarClassId): string => `${trackId}/${direction}/${carClass}`

// ── Reading ─────────────────────────────────────────────────────────────────────────────────────────────────────

type Raw = Record<string, unknown>

const isObject = (value: unknown): value is Raw => typeof value === 'object' && value !== null && !Array.isArray(value)
const isNumber = (value: unknown): value is number => typeof value === 'number' && Number.isFinite(value)
const orNull = (value: unknown): string | null => (typeof value === 'string' ? value : null)
/** The initials last used, if what was stored still are some. */
const orInitials = (value: unknown): string | null => (isInitials(value) ? value : null)
/** A real time or a count: finite and above zero. */
const isPositive = (value: unknown): value is number => isNumber(value) && value > 0

function readSettings(raw: unknown): SaveData['settings'] {
  const base = defaultSave().settings
  if (!isObject(raw)) return base
  const volume = isObject(raw['volume']) ? raw['volume'] : {}
  const level = (key: string, fallback: number): number => {
    const value = volume[key]
    return isNumber(value) && value >= 0 && value <= 1 ? value : fallback
  }
  // The official's voice was kept as `raceControlVoice` until F-801; the old name is read, and not carried on. The steering
  // assist of F-801 (`steerAssist`) is gone and is neither read nor carried on (F-811).
  const { raceControlVoice, ...kept } = raw
  delete kept['steerAssist']
  return {
    // Fields this feature does not know (a later feature's additions to the block) are carried as they are.
    ...kept,
    tts: typeof raw['tts'] === 'boolean' ? raw['tts'] : base.tts,
    commentatorVoice: orNull(raw['commentatorVoice']),
    officialVoice: orNull(raw['officialVoice'] ?? raceControlVoice),
    volume: { master: level('master', base.volume.master), sfx: level('sfx', base.volume.sfx), voice: level('voice', base.volume.voice) },
    drivingAssistance: typeof raw['drivingAssistance'] === 'boolean' ? raw['drivingAssistance'] : base.drivingAssistance,
    bindings: readBindings(raw['bindings']),
    music: typeof raw['music'] === 'boolean' ? raw['music'] : base.music,
    lastEvent: isObject(raw['lastEvent']) ? (raw['lastEvent'] as Partial<EventSettings>) : {},
    lastQuickRace: isObject(raw['lastQuickRace']) ? (raw['lastQuickRace'] as Partial<QuickRaceChoices>) : {},
    lastInitials: orInitials(raw['lastInitials']),
    // Absent from a save made before F-407, which loads with no name.
    driverName: typeof raw['driverName'] === 'string' ? cleanName(raw['driverName']) : null,
  }
}

/** A best-race table of 3, 5 and 7 minutes, an entry that is damaged left out; null if it is not a table at all (the one-slot shape of an earlier build among them). */
function readRaceTable(raw: unknown): Best['bestRace'] | null {
  if (!isObject(raw) || Object.keys(raw).some((key) => !ROUND_MINUTES.some((minutes) => String(minutes) === key))) return null
  const table: Best['bestRace'] = {}
  for (const minutes of ROUND_MINUTES) {
    const race = raw[String(minutes)]
    if (isObject(race) && isPositive(race['laps']) && isPositive(race['timeMs'])) table[minutes] = { laps: race['laps'], timeMs: race['timeMs'], ...(race['assisted'] === true ? { assisted: true } : {}) }
  }
  return table
}

/** The bests of each key; a key whose entry is damaged is dropped and the rest are kept. */
function readBests(raw: unknown): SaveData['bests'] {
  const bests: SaveData['bests'] = {}
  if (!isObject(raw)) return bests
  for (const [key, entry] of Object.entries(raw)) {
    if (!isObject(entry)) continue
    const bestRace = readRaceTable(entry['bestRace'])
    if (bestRace === null) continue
    const bestLapMs = isPositive(entry['bestLapMs']) ? entry['bestLapMs'] : null
    bests[key] = { bestLapMs, ...(bestLapMs !== null && entry['bestLapAssisted'] === true ? { bestLapAssisted: true } : {}), bestRace }
  }
  return bests
}

/** Whether `raw` has the shape of a `RaceDayState` the flow can be built from: enough to hand it to the sim, not a proof it is sound (the controller proves that by asking the sim for the next session). */
function isRaceDayState(raw: unknown): raw is RaceDayState {
  if (!isObject(raw)) return false
  const { settings, entries, schedule, cursor, results, finalGrid } = raw
  return (
    isObject(settings) &&
    typeof settings['trackId'] === 'string' &&
    Array.isArray(entries) &&
    entries.length > 0 &&
    Array.isArray(schedule) &&
    schedule.length > 0 &&
    isNumber(cursor) &&
    Number.isInteger(cursor) &&
    cursor >= 0 &&
    cursor <= schedule.length &&
    Array.isArray(results) &&
    results.length === cursor &&
    (finalGrid === null || Array.isArray(finalGrid))
  )
}

const FORECASTS: readonly Forecast[] = ['dry', 'changeable', 'wet', 'surprise']

/** Whether `raw` is weather a session can begin with (F-601): a forecast and a sky that exist, a wetness of 0 to 1, a wind that is two real numbers. */
function isWeatherPlan(raw: unknown): raw is WeatherPlan {
  if (!isObject(raw)) return false
  const { forecast, initialSky, initialWetness, windDirRad, windSpeedMS } = raw
  return (
    FORECASTS.some((one) => one === forecast) &&
    SKIES.some((sky) => sky === initialSky) &&
    isNumber(initialWetness) &&
    initialWetness >= 0 &&
    initialWetness <= 1 &&
    isNumber(windDirRad) &&
    isNumber(windSpeedMS) &&
    windSpeedMS >= 0
  )
}

/**
 * The event in progress as it was stored, or null if what is stored is not one. The weather it carries from its last
 * session (F-601) is kept if it is sound. A save made before the weather has none, and a damaged one is left out:
 * either way the next session begins with the forecast's own first draw, and nothing else of the event is lost.
 */
function readEvent(raw: unknown): RaceDayState | null {
  if (!isRaceDayState(raw)) return null
  if (raw.weather === undefined || isWeatherPlan(raw.weather)) return raw
  const event = { ...raw }
  delete event.weather
  return event
}

function readClassification(raw: unknown): SaveData['lastClassification'] {
  if (!isObject(raw) || !isObject(raw['settings']) || !Array.isArray(raw['rows'])) return null
  const rows = raw['rows'].filter((row): row is Classification => isObject(row) && isNumber(row['position']) && typeof row['driverId'] === 'string')
  return { settings: raw['settings'] as unknown as EventSettings, rows }
}

/** Turns what was stored into a `SaveData`: anything unusable is replaced by its default, a part at a time. A schema other than 1 gives the defaults whole. */
function parse(text: string): SaveData {
  const raw: unknown = JSON.parse(text)
  if (!isObject(raw) || raw['schema'] !== 1) return defaultSave()
  const leaderboards = isObject(raw['leaderboards']) ? raw['leaderboards'] : {}
  return {
    schema: 1,
    settings: readSettings(raw['settings']),
    bests: readBests(raw['bests']),
    eventInProgress: readEvent(raw['eventInProgress']),
    lastClassification: readClassification(raw['lastClassification']),
    leaderboards: { lap: sanitiseTables(leaderboards['lap'], isLapEntry, compareLap), race: sanitiseTables(leaderboards['race'], isRaceEntry, compareRace) },
  }
}

/** The browser's local storage, or null where there is none or the browser refuses it (private mode, blocked site data). */
export function browserStorage(): Storage | null {
  try {
    return globalThis.localStorage ?? null
  } catch {
    return null
  }
}

/**
 * What is stored, or the defaults when there is nothing, when it is not JSON, when its schema is not 1, or when the
 * storage throws. It never throws and it never writes: data of an unknown schema stays where it is until the next save.
 */
export function load(storage: ReadableStorage | null = browserStorage()): SaveData {
  try {
    const text = storage?.getItem(STORAGE_KEY)
    return text === null || text === undefined ? defaultSave() : parse(text)
  } catch {
    return defaultSave()
  }
}

/** Writes the save under the one key. False when the write failed (blocked or full storage): the game carries on without remembering. */
export function save(data: SaveData, storage: WritableStorage | null = browserStorage()): boolean {
  try {
    if (storage === null) return false
    storage.setItem(STORAGE_KEY, JSON.stringify(data))
    return true
  } catch {
    return false
  }
}

/** Removes the save. False when the storage refused. */
export function clearSave(storage: RemovableStorage | null = browserStorage()): boolean {
  try {
    if (storage === null) return false
    storage.removeItem(STORAGE_KEY)
    return true
  } catch {
    return false
  }
}

// ── Bests ───────────────────────────────────────────────────────────────────────────────────────────────────────

/** Whether race `a` beats race `b`: more laps, then less time. Only meaningful for two races of one round length. */
export const beatsRace = (a: Pick<BestRace, 'laps' | 'timeMs'>, b: Pick<BestRace, 'laps' | 'timeMs'>): boolean => a.laps > b.laps || (a.laps === b.laps && a.timeMs < b.timeMs)

/**
 * The save with the player's result of a finished qualifying heat or final counted in. The best lap is the player's
 * quickest lap of the session; the best race is its laps and time, kept for the round length it was run at (3, 5 or 7
 * minutes) and compared only with the stored race of that length. A session of any other length sets no best race,
 * its lap still counts. A practice result, a player who is not in it and a player who did not finish change nothing.
 * A best set in a session driven with DRIVING ASSISTANCE (`assisted`, F-811) counts like any other and is stored with
 * its mark; a best it replaces loses the mark it had. Returns a new value.
 */
export function updateBests(data: SaveData, trackId: string, direction: Direction, carClass: CarClassId, result: SessionResult, playerId: DriverId, minutes: number, assisted = false): SaveData {
  if (result.kind === 'practice') return data
  const row = result.rows.find((one) => one.driverId === playerId)
  if (row === undefined || !row.finished) return data
  const key = bestKey(trackId, direction, carClass)
  const stored: Best = data.bests[key] ?? { bestLapMs: null, bestRace: {} }

  const mark = assisted ? { assisted: true as const } : {}
  const lap = row.bestLapMs
  const newLap = lap !== null && lap > 0 && (stored.bestLapMs === null || lap < stored.bestLapMs) ? lap : null
  const length = ROUND_MINUTES.find((one) => one === minutes)
  const race: BestRace = { laps: row.laps, timeMs: row.timeMs, ...mark }
  const held = length === undefined ? undefined : stored.bestRace[length]
  const better = length !== undefined && row.laps > 0 && row.timeMs > 0 && (held === undefined || beatsRace(race, held))
  const bestRace = better ? { ...stored.bestRace, [length]: race } : stored.bestRace

  if (newLap === null && bestRace === stored.bestRace) return data
  const bestLap: Pick<Best, 'bestLapMs' | 'bestLapAssisted'> = newLap !== null
    ? { bestLapMs: newLap, ...(assisted ? { bestLapAssisted: true } : {}) }
    : { bestLapMs: stored.bestLapMs, ...(stored.bestLapAssisted === true ? { bestLapAssisted: true } : {}) }
  return { ...data, bests: { ...data.bests, [key]: { ...bestLap, bestRace } } }
}

/** What a result added to the bests of one track, direction and class: the two things the results screen announces. */
export interface NewBests {
  lap: number | null
  race: (BestRace & { minutes: RoundMinutes }) | null
}

/** The bests `after` holds for the key that `before` did not: the new best lap, the new best race (at one round length), either or none. */
export function newBests(before: SaveData, after: SaveData, key: string): NewBests {
  const was = before.bests[key]
  const now = after.bests[key]
  const length = ROUND_MINUTES.find((minutes) => now?.bestRace[minutes] !== undefined && now.bestRace[minutes] !== was?.bestRace[minutes])
  const race = length === undefined ? undefined : now?.bestRace[length]
  return {
    lap: now?.bestLapMs != null && now.bestLapMs !== was?.bestLapMs ? now.bestLapMs : null,
    race: length === undefined || race === undefined ? null : { ...race, minutes: length },
  }
}
