import type { DriverProfile, SessionSnapshot, SimEvent } from '@sim'
import { buildWorld, createDerived, digestOf, eventResultGroup, fillerGroup, groupsFromClock, groupsFromEvents, type Digest, type Group, type View } from './candidates'
import { canFill, estimateDurationS, fillText } from './fill'
import { createCommentaryRng } from './rng'
import { COMMENTARY_TUNING as T } from './tuning'
import type { CommentaryContext, CommentaryEngine, LineTemplate, LineTrigger, SpokenLine } from './types'
import { validateLines } from './validate'

/** One of `items`, drawing from the generator only when there is a choice to make. */
function pickOne<T>(items: readonly T[], rng: { int(n: number): number }): T | undefined {
  return items.length <= 1 ? items[0] : items[rng.int(items.length)]
}

interface Choice {
  readonly template: LineTemplate
  readonly score: number
}

/**
 * The commentary engine (contracts.md §10, F-701). `observe` turns events into candidate moments; `next` chooses the
 * most worthwhile line that is still true, or fills a silence, or says nothing because somebody else is talking.
 * Pure: a generator of its own, session time passed in, no state but its own.
 */
export function createCommentary(lines: readonly LineTemplate[], roster: readonly DriverProfile[], seed: number, context: CommentaryContext): CommentaryEngine {
  validateLines(lines)
  const world = buildWorld(roster, context)
  const rng = createCommentaryRng(seed)
  const derived = createDerived()
  const byTrigger = new Map<LineTrigger, LineTemplate[]>()
  for (const line of lines) byTrigger.set(line.trigger, [...(byTrigger.get(line.trigger) ?? []), line])

  let digest: Digest | null = null
  let pending: Group[] = []
  /** When each template was last returned, s. */
  const lastReturnedS = new Map<string, number>()
  /** The last moment the speaker was seen busy or a line was handed out: silence is counted from there (or from the session's start). */
  let quietSinceS = 0

  const view = (nowS: number): View => ({ world, digest, nowS })

  /** Templates of the group's trigger that fit its conditions and can be filled: whether or not they have expired or are cooling down. */
  const fitting = (group: Group): LineTemplate[] =>
    (byTrigger.get(group.trigger) ?? []).filter((one) => (one.when === undefined || group.holds.has(one.when)) && canFill(one.text, group.values))

  /** The best-scoring templates of a group now, with the least recently used first among equals; null when none can be said. */
  const choose = (group: Group, nowS: number): Choice | null => {
    let best: Choice[] = []
    for (const template of fitting(group)) {
      if (nowS >= group.createdAtS + template.ttlS) continue
      const last = lastReturnedS.get(template.id)
      if (last !== undefined && nowS < last + template.cooldownS) continue
      const score = template.priority + (template.when === undefined ? 0 : T.specificBonus) + group.bonus
      if (best.length === 0 || score > (best[0]?.score ?? -Infinity)) best = [{ template, score }]
      else if (score === best[0]?.score) best.push({ template, score })
    }
    if (best.length <= 1) return best[0] ?? null
    const oldest = Math.min(...best.map((one) => lastReturnedS.get(one.template.id) ?? -Infinity))
    const rested = best.filter((one) => (lastReturnedS.get(one.template.id) ?? -Infinity) === oldest)
    return pickOne(rested, rng) ?? null
  }

  /** A group is worth keeping while one of its fitting templates has not expired. */
  const alive = (group: Group, nowS: number): boolean => fitting(group).some((one) => nowS < group.createdAtS + one.ttlS)

  const add = (groups: readonly Group[], nowS: number): void => {
    for (const group of groups) if (alive(group, nowS)) pending.push(group)
    if (pending.length > T.maxPending) pending = pending.slice(pending.length - T.maxPending)
  }

  // The player's place in the event (F-709): known before anything is observed, so it is a moment from time 0.
  const eventResult = context.eventPlace === undefined ? null : eventResultGroup(world, context.eventPlace, 0)
  if (eventResult !== null) add([eventResult], 0)

  const deliver = (group: Group, choice: Choice, nowS: number): SpokenLine => {
    const { template } = choice
    lastReturnedS.set(template.id, nowS)
    quietSinceS = nowS
    const text = fillText(template.text, group.values, (facts) => pickOne(facts, rng) ?? '')
    return { id: template.id, voice: template.voice, text, expiresAtS: group.createdAtS + template.ttlS, estimatedDurationS: estimateDurationS(text) }
  }

  return {
    observe(events: readonly SimEvent[], snapshot: SessionSnapshot, nowS: number): void {
      digest = digestOf(snapshot)
      const here = view(nowS)
      add(groupsFromEvents(events, here, derived), nowS)
      add(groupsFromClock(here, derived), nowS)
    },

    next(nowS: number, speakerBusy: boolean): SpokenLine | null {
      add(groupsFromClock(view(nowS), derived), nowS)
      pending = pending.filter((group) => alive(group, nowS))
      if (speakerBusy) {
        quietSinceS = nowS
        return null
      }
      let bestGroups: Array<{ group: Group; choice: Choice }> = []
      for (const group of pending) {
        const choice = choose(group, nowS)
        if (choice === null) continue
        const top = bestGroups[0]?.choice.score ?? -Infinity
        if (choice.score > top) bestGroups = [{ group, choice }]
        else if (choice.score === top) bestGroups.push({ group, choice })
      }
      const picked = pickOne(bestGroups, rng)
      if (picked !== undefined) {
        pending = pending.filter((group) => group !== picked.group)
        return deliver(picked.group, picked.choice, nowS)
      }
      if (nowS - quietSinceS < T.fillerAfterS) return null
      const filler = fillerGroup(view(nowS), rng)
      const choice = filler === null ? null : choose(filler, nowS)
      return filler === null || choice === null ? null : deliver(filler, choice, nowS)
    },
  }
}
