// The menu kit's look, as plain values (F-204), dressed in the drawn skin of F-802. Every colour is one already in the
// shared palette (spec/00-product/art-direction.md): the darkest ink, the carbon greys, the metal grey, the white ramp
// and the yellow body ramp's base. The skin's pictures are in the `skin` atlas (art/skin/build.py), which is loaded with
// the font before the title, so every screen has it.

/** The pixel font's glyph cell in art pixels (public/assets/manifest.json, fonts.pixel.cell). */
export const FONT_CELL = { w: 6, h: 12 } as const

export type TextSize = 'small' | 'body' | 'large' | 'huge'

export const THEME = {
  colours: {
    /** Behind every screen. */
    background: 0x16161e,
    /** A panel's fill, and the border around it. */
    panel: 0x22242e,
    border: 0x5a5e6e,
    /** The track-grey a car preview stands on. */
    stage: 0x5a5d68,
    /** Normal, secondary and unavailable text. */
    text: 0xeef1f6,
    textDim: 0xaab2c2,
    textOff: 0x5a5e6e,
    /** The title, and the focused item's text. */
    accent: 0xf0bc1e,
    /** The bar behind the focused item. */
    focusBar: 0x3a3d4a,
    /** Stat bars: the empty track and the filled part. */
    barTrack: 0x3a3d4a,
    barFill: 0xf0bc1e,
    /** Dims the scene under an overlay. */
    shade: 0x000000,
  },
  /**
   * Whole-number scales of the font's art pixel, so every glyph pixel is a block of whole screen pixels. 2 is the
   * font's native density (one art pixel = two logical pixels).
   */
  sizes: { small: 2, body: 3, large: 5, huge: 10 } satisfies Record<TextSize, number>,
  /** Space between a panel's edge and what it holds, in logical pixels. */
  padding: 24,
  /** The panel border's width, in logical pixels (one art pixel at the font's density). */
  borderPx: 2,
  /**
   * The drawn skins (art/skin/build.py), by the name of their pieces in the manifest (`<name>.<piece>`): every panel, the bar
   * behind a focused row and a table's current row, the frame of a button that is not focused, and the frame of a HUD plate.
   * A skin's fill is the colour above of the same role (`panel`, `focusBar`), so text reads on it as it did on the flat ones.
   */
  skin: {
    panel: 'skin.panel',
    bar: 'skin.bar',
    button: 'skin.button',
    hud: 'skin.hud',
    step: { 1: 'skin.step.gold', 2: 'skin.step.silver', 3: 'skin.step.bronze' },
  },
  /** Drawn in the cursor's column of a row that cannot be chosen: unavailable is told by shape as well as by the dim colour. At the text's own scale. */
  offMark: 'skin.mark.off',
  /** Marks the focused item; focus is never shown by colour alone. The font's own cursor glyph. */
  cursorGlyph: '▶',
  /** Shown at the ends of a selector, to say that left and right change it. */
  arrowLeft: '◀',
  arrowRight: '▶',
} as const

/** The width of one character of the text at `size`, in logical pixels. */
export const charWidth = (size: TextSize): number => FONT_CELL.w * THEME.sizes[size]
/** The height of one line of the text at `size`, in logical pixels. */
export const lineHeight = (size: TextSize): number => FONT_CELL.h * THEME.sizes[size]
