/// <reference lib="dom" />
import Phaser from 'phaser'
import { hideFailureDom, showFailureDom } from './failure-dom'
import { graphicsLost } from './failure'

// The graphics context can be taken from the page at any time (a driver reset, a GPU under memory pressure, the machine
// waking from sleep) and given back a moment later. The engine puts back what it loaded from files, but everything it
// drew *into* (the baked ground, the tyres, the rubber) comes back empty: a track of black under the cars. These events
// let a scene put its own pictures back (F-803).

/** On the game's event emitter: the context has been taken. The scene running a race stops the clock. */
export const GRAPHICS_LOST = 'mrr-graphics-lost'
/** On the game's event emitter: the context is back, and what the scenes drew into textures has to be drawn again. */
export const GRAPHICS_RESTORED = 'mrr-graphics-restored'

/** How long the context may stay lost before the page says so (in HTML: there is nothing to draw with), ms. */
export const LOST_PATIENCE_MS = 8000

/** Starts relaying the renderer's loss and restoration as the two events above. Call once the game is ready. */
export function watchGraphics(game: Phaser.Game): void {
  const { renderer } = game
  if (!(renderer instanceof Phaser.Renderer.WebGL.WebGLRenderer)) return
  let waiting: ReturnType<typeof setTimeout> | null = null
  renderer.on(Phaser.Renderer.Events.LOSE_WEBGL, () => {
    game.events.emit(GRAPHICS_LOST)
    waiting = setTimeout(() => showFailureDom(graphicsLost), LOST_PATIENCE_MS)
  })
  renderer.on(Phaser.Renderer.Events.RESTORE_WEBGL, () => {
    if (waiting !== null) clearTimeout(waiting)
    waiting = null
    hideFailureDom()
    game.events.emit(GRAPHICS_RESTORED)
  })
}
