import type Phaser from 'phaser'
import { TICK_RATE, type CarColour, type CarId, type CarSnapshot, type SessionEntry, type TrackData } from '@sim'
import { animation, type Animation } from '../assets/animation'
import type { AssetManifest } from '../assets/manifest'
import type { WorldView } from '../config'
import { setTextIfChanged, text } from '../ui/text'
import { HELP_BUBBLE, HELP_TEXT, PULSE_GROW_PX, SHOUT, driverFrame, driverPlaces, helpBubbleBox, needsHelp, pulseLevel, type ClipRate } from './decor-layout'
import { DEPTH } from './depth'
import type { EventBus } from './EventBus'
import type { PixelRect } from './hud-format'
import { Bubble } from './Official'

// The drivers on the stand (F-504): one for each car on track, in that car's colour, in start-slot order from the
// left, swaying where they stand. When their own car flips, gets stuck or sets a personal best lap they react. While
// their car is waiting for a marshal a small HELP! bubble stands beside their head (F-509, moved by F-514). While the
// marshal for their car is on his phone and the game is not saying "Marshal!" aloud (F-708), it reads MARSHAL! and
// pulses with each shout.

/** The colour of the call for help: the HUD's red, as the messages that are bad news have it. */
const HELP_COLOUR = 0xee5a48

/** The colour of the words at the height of a shout's pulse. */
const SHOUT_COLOUR = 0xffffff

/** What the debug hook reports about one driver. */
export interface DriverInfo {
  car: CarId
  colour: CarColour
  /** Where the driver's feet are on the 1920 x 1080 canvas. */
  x: number
  y: number
  clip: 'idle' | 'react'
  frame: string
  depth: number
  /** A HELP! bubble is up over the driver. */
  help: boolean
}

/** What the debug hook reports about a HELP! bubble: whose it is and the box it covers on the 1920 x 1080 canvas, tail included (it sticks out to the left of the body, towards the head). */
export interface HelpBubbleInfo extends PixelRect {
  car: CarId
  /** The words in it: HELP!, or MARSHAL! while the driver shouts for a marshal who is on his phone. */
  text: string
  /** How far into a shout's pulse it is drawn: 0 at rest, up to the pulse's last step (the box reported is the one at rest). */
  pulse: number
}

interface Help {
  bubble: Bubble
  label: Phaser.GameObjects.BitmapText
}

interface Driver {
  car: CarId
  colour: CarColour
  image: Phaser.GameObjects.Image
  idle: Animation
  react: Animation
  /** The sim time, in seconds, at which the reaction in progress began; null when there has been none. */
  reactSinceS: number | null
  clip: 'idle' | 'react'
  frame: number
  /** The HELP! bubble over the driver, made the first time it is wanted. */
  help: Help | null
  /** Where the bubble goes: the driver's feet. */
  feet: { x: number; y: number }
  helping: boolean
  /** The words on the bubble, and the step of its pulse, as last drawn. */
  words: string
  pulse: number
}

const rate = (clip: Animation): ClipRate => ({ frames: clip.frames.length, fps: clip.fps })

export class DriverStand {
  private drivers: Driver[] = []
  private release: Array<() => void> = []
  private readonly scene: Phaser.Scene
  private readonly manifest: AssetManifest

  /**
   * The atlases `people` and `ui` must be loaded. `entries` are the session's; a driver stands for each, and its index is
   * the car's id. `reverse` is whether the session's cars have reverse: without it a wedged car is helpless too.
   */
  constructor(
    scene: Phaser.Scene,
    view: WorldView,
    track: TrackData,
    manifest: AssetManifest,
    bus: EventBus,
    entries: readonly SessionEntry[],
    private readonly reverse = true,
  ) {
    this.scene = scene
    this.manifest = manifest
    // Left to right in start-slot order: pole on the left.
    const order = entries.map((entry, car) => ({ entry, car })).sort((a, b) => a.entry.startSlot - b.entry.startSlot || a.car - b.car)
    const places = driverPlaces(track, view.pxPerM, order.length)
    this.drivers = order.flatMap(({ entry, car }, i) => {
      const place = places[i]
      if (place === undefined) return []
      const idle = animation(manifest, `driver.${entry.colour}.idle`)
      const react = animation(manifest, `driver.${entry.colour}.react`)
      const image = scene.add
        .image(view.originX + place.x, view.originY + place.y, idle.atlas, idle.frames[0])
        .setOrigin(idle.pivot.x, idle.pivot.y)
        .setScale(idle.scale)
        .setDepth(DEPTH.people)
      return [{ car, colour: entry.colour, image, idle, react, reactSinceS: null, clip: 'idle', frame: 0, help: null, feet: { x: image.x, y: image.y }, helping: false, words: HELP_TEXT, pulse: 0 } satisfies Driver]
    })
    this.release.push(
      bus.on('flip', (event) => this.react(event.car, event.tick)),
      bus.on('stuck', (event) => this.react(event.car, event.tick)),
      bus.on('lap', (event) => {
        if (event.personalBest) this.react(event.car, event.tick)
      }),
    )
  }

  private react(car: CarId, tick: number): void {
    const driver = this.drivers.find((one) => one.car === car)
    if (driver !== undefined) driver.reactSinceS = tick / TICK_RATE
  }

  /** Shows every driver as they are at `timeS` on the sim's clock. Call it every frame. */
  update(timeS: number): void {
    this.drivers.forEach((driver, index) => {
      const shown = driverFrame(timeS, driver.reactSinceS, index, rate(driver.idle), rate(driver.react))
      driver.clip = shown.clip
      driver.frame = shown.frame
      const clip = shown.clip === 'idle' ? driver.idle : driver.react
      driver.image.setFrame(clip.frames[shown.frame] ?? clip.frames[0])
    })
  }

  /**
   * Puts a HELP! bubble over the driver of each car that is waiting for a marshal and takes it away from the others
   * (`needsHelp`). Call it every frame with the latest snapshot's cars; a bubble is moved only when it comes up or changes.
   * `calls` are the cars whose drivers shout for a marshal who is on his phone, with how strongly the shout pulses now,
   * 0..1 (`ShoutClock.pulses`): their bubbles read MARSHAL! and swell with each shout. Leave it out where the shout is
   * spoken.
   */
  showHelp(cars: readonly CarSnapshot[], calls?: ReadonlyMap<CarId, number>): void {
    for (const driver of this.drivers) {
      const car = cars[driver.car]
      const wanted = car !== undefined && needsHelp(car, this.reverse)
      const calling = wanted && calls?.has(driver.car) === true
      const words = calling ? SHOUT.words : HELP_TEXT
      const pulse = calling ? pulseLevel(calls.get(driver.car) ?? 0) : 0
      if (wanted === driver.helping && words === driver.words && pulse === driver.pulse) continue
      driver.helping = wanted
      driver.words = words
      driver.pulse = pulse
      if (!wanted) {
        driver.help?.bubble.hide()
        driver.help?.label.setVisible(false)
        continue
      }
      const box = helpBubbleBox(driver.feet.x, driver.feet.y, words)
      driver.help ??= {
        bubble: new Bubble(this.scene, this.manifest, 'bubble-small', 'left', DEPTH.hud + 1),
        label: text(this.scene, { x: 0, y: 0 }, HELP_TEXT, 'small').setTint(HELP_COLOUR).setDepth(DEPTH.hud + 2),
      }
      // A pulse swells the bubble up, down and to the right; its left edge, where the tail meets it, stays.
      const swell = pulse * PULSE_GROW_PX
      driver.help.bubble.place({ x: box.x, y: box.y - swell, w: box.w + 2 * swell, h: box.h + 2 * swell }, box.tailAlong + swell)
      setTextIfChanged(driver.help.label, words)
      driver.help.label.setTint(pulse > 0 ? SHOUT_COLOUR : HELP_COLOUR).setPosition(box.x + HELP_BUBBLE.inset, box.y + HELP_BUBBLE.inset).setVisible(true)
    }
  }

  /** The HELP! bubbles on show, left to right, for the debug hook and the tests. */
  helpBubbles(): HelpBubbleInfo[] {
    return this.drivers.flatMap((driver) => {
      if (!driver.helping) return []
      const box = helpBubbleBox(driver.feet.x, driver.feet.y, driver.words)
      return [{ car: driver.car, x: box.x - HELP_BUBBLE.tail, y: box.y, w: box.w + HELP_BUBBLE.tail, h: box.h, text: driver.words, pulse: driver.pulse }]
    })
  }

  /** The drivers on the stand, left to right, and what each is doing, for the debug hook and the tests. */
  info(): DriverInfo[] {
    return this.drivers.map((driver) => ({
      car: driver.car,
      colour: driver.colour,
      x: driver.image.x,
      y: driver.image.y,
      clip: driver.clip,
      frame: String(driver.image.frame.name),
      depth: driver.image.depth,
      help: driver.helping,
    }))
  }

  destroy(): void {
    for (const off of this.release) off()
    this.release = []
    for (const driver of this.drivers) {
      driver.image.destroy()
      driver.help?.bubble.destroy()
      driver.help?.label.destroy()
    }
    this.drivers = []
  }
}
