import { classFacts, gripLimitMS2, type CarParams, type ClassFacts, type DriveLayout } from '@sim'

/** The four stat bars of the garage, each 0..BEST_SHARE: the best class on a bar sits at BEST_SHARE and the others below it. */
export interface ClassStats {
  acceleration: number
  topSpeed: number
  grip: number
  stability: number
}

/** Where the best class on each bar sits, as a share of a full bar: a little under full, so that no bar reads 100 %. */
export const BEST_SHARE = 0.95

/**
 * The most the speed controller and motor can put through the wheels, in the game's own units (N x m/s per kg):
 * the largest value of (force at that speed x speed) on the model's force curve, which falls in a straight line
 * from the stall force at standstill to zero at the no-load speed and is cut flat at the current limit. A car with
 * less than half its stall force available stays on the flat part until the line takes over.
 */
export function peakPowerPerKg(p: Pick<CarParams, 'stallForceN' | 'thrustLimitN' | 'noLoadSpeedMS' | 'massKg'>): number {
  const { stallForceN, thrustLimitN, noLoadSpeedMS } = p
  const peak =
    thrustLimitN >= stallForceN / 2
      ? (stallForceN * noLoadSpeedMS) / 4
      : thrustLimitN * noLoadSpeedMS * (1 - thrustLimitN / stallForceN)
  return peak / p.massKg
}

/** Peak power per kilogram at which the motor has halved a car's steadiness (see `stabilityOf`), in the units of `peakPowerPerKg`. */
const POWER_HALVES_STABILITY = 12

/**
 * How steady a car is to drive, as a number to compare classes by, 0..1: the harder a car is hit by its own motor,
 * and the worse its layout and weight split, the less steady it is.
 *
 *   stability = layout x balance x motor
 *   layout    = 0.92 front drive  (the driven front tyres also steer, so power pushes the nose wide),
 *               1.00 four-wheel drive (belt drive splits torque by axle load: no axle is asked for more than it holds),
 *               0.55 rear drive   (power breaks the rear tyres loose first: the tail steps out)
 *   balance   = 1 - |front share of weight - 0.5|     (an even split is best)
 *   motor     = 1 / (1 + (peak power per kg / 12)^4)  (about 1 for a mild motor, falling fast once a car is far stronger than its tyres)
 *
 * The layout factors and the 12 are judgments, not measurements: they put the classes in the order the game design
 * gives them (Stock the planted one, FWD tidy and forgiving, Modified clearly more car than its grip, the F1 delicate).
 */
export function stabilityOf(drive: DriveLayout, weightFront: number, powerPerKg: number): number {
  const layout = drive === '4wd' ? 1 : drive === 'fwd' ? 0.92 : 0.55
  return layout * (1 - Math.abs(weightFront - 0.5)) / (1 + (powerPerKg / POWER_HALVES_STABILITY) ** 4)
}

/** What a class does in a straight line, measured by driving it (20 s of simulation), computed once per resolved car. */
const factsOf = new WeakMap<CarParams, ClassFacts>()
function facts(p: CarParams): ClassFacts {
  let known = factsOf.get(p)
  if (known === undefined) {
    known = classFacts(p)
    factsOf.set(p, known)
  }
  return known
}

/** Raw figures, in "more is better" units. */
function raw(p: CarParams): ClassStats {
  const { topSpeedMS, zeroToTenMetresS } = facts(p)
  return {
    // The reciprocal of the time to cover 10 m from rest, flat out: how soon everything arrives.
    acceleration: Number.isFinite(zeroToTenMetresS) && zeroToTenMetresS > 0 ? 1 / zeroToTenMetresS : 0,
    topSpeed: topSpeedMS,
    // The cornering limit of the weaker axle on dry asphalt (what the tyres' mu allows), in m/s².
    grip: gripLimitMS2(p),
    stability: stabilityOf(p.drive, p.cgToRearAxleM / p.wheelbaseM, peakPowerPerKg(p)),
  }
}

/**
 * The garage's four bars for `p`, each its raw figure divided by the best raw figure among `all` and then scaled to
 * `BEST_SHARE`, so the best class on a bar is at 95 % and the others are shown against it:
 *
 * - acceleration: 1 / (seconds to cover 10 m from rest at full throttle), measured by `classFacts`. The spec asked
 *   for peak wheel force over mass, but that ranks the Modified car last (the speed controller's current limit caps
 *   a high-KV motor's force at standstill while it still out-accelerates the others over distance), against the game
 *   design's order, so the measured time is used.
 * - topSpeed: the speed `classFacts` measures after 20 s flat out.
 * - grip: `gripLimitMS2`, the weaker axle's tyre mu times gravity: dry cornering grip.
 * - stability: `stabilityOf`, from the drive layout, the weight split and how much motor the car has.
 *
 * `p` need not be one of `all`. A bar whose best figure is 0 is 0 for everyone.
 */
export function classStats(p: CarParams, all: readonly CarParams[]): ClassStats {
  const own = raw(p)
  const best: ClassStats = { acceleration: own.acceleration, topSpeed: own.topSpeed, grip: own.grip, stability: own.stability }
  for (const other of all) {
    const figures = raw(other)
    best.acceleration = Math.max(best.acceleration, figures.acceleration)
    best.topSpeed = Math.max(best.topSpeed, figures.topSpeed)
    best.grip = Math.max(best.grip, figures.grip)
    best.stability = Math.max(best.stability, figures.stability)
  }
  const share = (value: number, top: number): number => (top > 0 ? (BEST_SHARE * value) / top : 0)
  return {
    acceleration: share(own.acceleration, best.acceleration),
    topSpeed: share(own.topSpeed, best.topSpeed),
    grip: share(own.grip, best.grip),
    stability: share(own.stability, best.stability),
  }
}
