import type { CarClassId, CarColour } from '@sim'
import { CLASS_ORDER } from '@content/classes'
import { saves } from '../persistence'

/** The seven body colours a player may choose, in the order the garage shows them (game-design.md, "Colours"). */
export const PLAYER_COLOURS: readonly CarColour[] = ['red', 'blue', 'yellow', 'green', 'white', 'orange', 'pink']

/** What the player chose in the garage. The race scene reads it when it builds a session; nothing else does. */
export interface Selection {
  carClass: CarClassId
  colour: CarColour
}

const FIRST_CLASS = CLASS_ORDER[0]
if (FIRST_CLASS === undefined) throw new Error('selection: CLASS_ORDER is empty')

let chosen: Selection | null = null

/** Where the choice starts: the car of the last event if one was saved and is still a car the game has, else the recommended first car in red. */
function remembered(): Selection {
  const { carClass, colour } = saves.read().settings.lastEvent
  return {
    carClass: carClass !== undefined && CLASS_ORDER.includes(carClass) ? carClass : FIRST_CLASS,
    colour: colour !== undefined && PLAYER_COLOURS.includes(colour) ? colour : 'red',
  }
}

/**
 * The session-wide choice of class and colour, kept for as long as the page is open and remembered between visits
 * through the save (F-405; the garage and the events write it there). It starts on the last car, or on the
 * recommended first car, red, when nothing is remembered. `get` returns a copy, so a reader cannot change the choice
 * by accident.
 */
export const selection = {
  get(): Selection {
    chosen ??= remembered()
    return { ...chosen }
  },
  set(change: Partial<Selection>): void {
    chosen = { ...(chosen ?? remembered()), ...change }
  },
}
