import type { CarId, CarSnapshot, MarshalSnapshot, TrackData } from '@sim'

// Where the track's decor stands, as data (F-504). Everything here is pure: the track's `decor` list in, a list of
// pictures to put down out. Nothing outside the walls is known to the sim; it is all for the eye. Positions are in
// screen pixels measured from the world's origin (metres times `pxPerM`): the caller adds where the origin is.

/** Which of the three groups of draw order a picture belongs to: flat on the ground (baked), standing, or over everything. */
export type Layer = 'ground' | 'standing' | 'canopy'

export interface DecorPlacement {
  /** Manifest name of the picture. */
  sprite: string
  x: number
  y: number
  angle: number
  /** Multiples of the picture's own size. */
  scaleX: number
  scaleY: number
  layer: Layer
  /** Which entry of `track.decor` this came from. */
  item: number
}

/** How big a picture is on screen, in screen pixels at its own density: the art cell times its pixels per art pixel. */
interface Size {
  w: number
  h: number
}

interface KindRow {
  layer: Layer
  /** True for a thing that stands behind the driver stand, its upper edge on the stand's lower edge, where the track has one; it lies on its footprint otherwise. */
  behindStand?: boolean
  /** The pictures of one item, in the order they are laid along its width. */
  sprites: (item: TrackData['decor'][number]) => readonly string[]
}

/**
 * The size on screen of each picture the decor uses. The art build's manifest is the source; this copy lets the
 * layout know how much room a picture takes without an engine, and a test holds it to the manifest.
 */
export const SPRITE_PX: Readonly<Record<string, Size>> = {
  'prop.driver-stand.pit': { w: 572, h: 118 },
  'prop.pit-table.1': { w: 112, h: 56 },
  'prop.pit-table.2': { w: 112, h: 56 },
  'prop.tree.1': { w: 108, h: 98 },
  'prop.tree.2': { w: 62, h: 58 },
}

/** The driver stand's picture (F-509): drawn to run the width of the pit, from the first block to the end of the strip. */
export const STAND_SPRITE = 'prop.driver-stand.pit'

/** The one table from a decor item's kind to what is drawn for it. A tree of a metre or more is the full canopy; a smaller one is a shrub. */
const KINDS: Readonly<Record<string, KindRow>> = {
  'driver-stand': { layer: 'ground', sprites: () => [STAND_SPRITE] },
  'pit-table': { layer: 'ground', behindStand: true, sprites: () => ['prop.pit-table.1', 'prop.pit-table.2'] },
  tree: { layer: 'canopy', sprites: (item) => [item.w >= 1 ? 'prop.tree.1' : 'prop.tree.2'] },
}

/** The kinds in the track's decor that have no picture, each named once: the view reports them in development builds and draws the rest. */
export function undrawnDecor(track: TrackData): string[] {
  return [...new Set(track.decor.filter((item) => !(item.kind in KINDS)).map((item) => item.kind))]
}

const sizeOf = (sprite: string): Size => {
  const size = SPRITE_PX[sprite]
  if (size === undefined) throw new Error(`decor-layout: no size is known for '${sprite}'`)
  return size
}

/**
 * Where the centre of a picture `size` pixels across is put so that its edge lies on a whole pixel: art placed on
 * the pixel grid stays as hard as it was drawn.
 */
export function snapCentre(centre: number, size: number): number {
  return Math.round(centre - size / 2) + size / 2
}

/** The art's distance from the stand's top edge to a driver's feet, in screen pixels (F-503: `art/out/props/stand/stats.json`). */
export const STAND_FEET_PX = 86
/** How many drivers the stand holds. */
export const STAND_PLACES = 7

/** The driver stand's drawn box in pixels from the origin: its picture's size, on the pixel grid. Null when the track has no stand. */
export function standRect(track: TrackData, pxPerM: number): { x: number; y: number; w: number; h: number } | null {
  const stand = track.decor.find((item) => item.kind === 'driver-stand')
  if (stand === undefined) return null
  const { w, h } = sizeOf(STAND_SPRITE)
  return { x: snapCentre(stand.x * pxPerM, w) - w / 2, y: snapCentre(stand.y * pxPerM, h) - h / 2, w, h }
}

/**
 * One picture for every decor item, except a pit table, which is two (variants 1 and 2) laid along the item's width
 * with their outer edges on its ends, as the pit tables of the photo are a pair. The tables stand behind the driver
 * stand, further from the track, their upper edge on the stand's lower edge (F-509); where the band is too shallow for
 * that they are lifted, over the strip of the stand's floor below the drivers' feet and no higher, so that no table is
 * cut by the edge of the world. A picture is drawn at its own size: the item's `w` and `h` are its footprint and, for a
 * tree, which canopy. The stand comes first among what lies flat, so that a table lifted over its floor is drawn over it.
 */
export function layoutDecor(track: TrackData, pxPerM: number): DecorPlacement[] {
  const out: DecorPlacement[] = []
  const stand = standRect(track, pxPerM)
  const floor = track.bounds.h * pxPerM
  track.decor.forEach((item, index) => {
    const row = KINDS[item.kind]
    if (row === undefined) return
    const sprites = row.sprites(item)
    const behind = row.behindStand === true && item.angle === 0 && stand !== null
    const cx = item.x * pxPerM
    const cy = item.y * pxPerM
    const cos = Math.cos(item.angle)
    const sin = Math.sin(item.angle)
    sprites.forEach((sprite, i) => {
      // Along the item's own width: the first picture at its start, the last at its end, the rest between.
      let along = 0
      if (sprites.length > 1) {
        const reach = Math.max(item.w * pxPerM - sizeOf(sprite).w, sizeOf(sprite).w * (sprites.length - 1)) / 2
        along = -reach + (2 * reach * i) / (sprites.length - 1)
      }
      let y = cy + sin * along
      if (behind && stand !== null) {
        const { h } = sizeOf(sprite)
        const top = Math.max(stand.y + STAND_FEET_PX, Math.min(stand.y + stand.h, floor - h))
        y = top + h / 2
      }
      out.push({ sprite, x: cx + cos * along, y, angle: item.angle, scaleX: 1, scaleY: 1, layer: row.layer, item: index })
    })
  })
  return out.sort((a, b) => Number(b.sprite === STAND_SPRITE) - Number(a.sprite === STAND_SPRITE))
}

/** Where the seven drivers' feet are on the driver stand, left to right (`x = (i + 0.5) x width / 7`). Empty if the track has no stand. */
export function standSlots(track: TrackData, pxPerM: number): Array<{ x: number; y: number }> {
  const box = standRect(track, pxPerM)
  if (box === null) return []
  return Array.from({ length: STAND_PLACES }, (_, i) => ({ x: box.x + ((i + 0.5) * box.w) / STAND_PLACES, y: box.y + STAND_FEET_PX }))
}

/**
 * Where `count` drivers stand, left to right, centred on the stand with the other places empty. An odd number of drivers
 * stand on places; an even number stand between them, so that the group is centred all the same. On whole pixels.
 */
export function driverPlaces(track: TrackData, pxPerM: number, count: number): Array<{ x: number; y: number }> {
  const slots = standSlots(track, pxPerM)
  const first = slots[0]
  const last = slots[STAND_PLACES - 1]
  if (first === undefined || last === undefined) return []
  const pitch = (last.x - first.x) / (STAND_PLACES - 1)
  const start = (STAND_PLACES - Math.min(count, STAND_PLACES)) / 2
  return Array.from({ length: Math.min(count, STAND_PLACES) }, (_, i) => ({ x: Math.round(first.x + (start + i) * pitch), y: Math.round(first.y) }))
}

// ---------------------------------------------------------------------------------------------------------
// A driver's moving picture

/** The two animations of a driver that play over a race: the sway, which loops, and the reaction, which plays once. */
export interface ClipRate {
  frames: number
  fps: number
}

/** The seconds between two drivers' sways, so that the stand does not move as one. */
export const SWAY_OFFSET_S = 0.37

/**
 * Which picture a driver shows at `timeS` on the sim's clock. A reaction that began at `reactSinceS` plays its frames
 * once, then the sway goes on; `index` puts each driver's sway out of step with the next.
 */
export function driverFrame(timeS: number, reactSinceS: number | null, index: number, idle: ClipRate, react: ClipRate): { clip: 'idle' | 'react'; frame: number } {
  if (reactSinceS !== null) {
    const elapsed = Math.max(0, timeS - reactSinceS)
    const frame = Math.floor(elapsed * react.fps)
    if (frame < react.frames) return { clip: 'react', frame }
  }
  const frame = Math.floor((timeS + index * SWAY_OFFSET_S) * idle.fps)
  return { clip: 'idle', frame: ((frame % idle.frames) + idle.frames) % idle.frames }
}

// ---------------------------------------------------------------------------------------------------------
// A driver whose car is waiting for a marshal (F-509)

/**
 * Whether a car is out of its driver's hands and waiting for a marshal to put it down: on its roof, or stuck in a way
 * it cannot drive out of, or in a marshal's hands, until it drives again (contracts.md § 6, F-508). A stuck car is
 * helpless when it is bogged down in the grass, and when it is wedged in a session whose cars have no reverse; wedged
 * with reverse it is still its driver's to get out, and gets no help.
 */
export function needsHelp(car: Pick<CarSnapshot, 'state' | 'strickenCause'>, reverse: boolean): boolean {
  if (car.state === 'flipped' || car.state === 'being-marshalled') return true
  return car.state === 'stuck' && (car.strickenCause !== 'wedged' || !reverse)
}

/** The words of the call for help. */
export const HELP_TEXT = 'HELP!'

/**
 * The little bubble beside a driver (F-514): the `ui.bubble-small` nine-slice round the word at `small` size, `inset`
 * from its edge (the skin's own rim is 4 px, so the word sits just inside it; 68 x 32 px, 20 % smaller than the first, 76 x 40), and its `tail-left` pointing at the driver's head. It stands to the right of the head and lower than a
 * bubble over it would, so that it lies wholly below the pit blocks: the tail's tip aims `aimUpPx` above the driver's
 * feet (the middle of the head, which is `headPx` high: 29 art pixels of figure in a 40-pixel cell, `art/out/people`)
 * and stops `gap` short of the head's right side, `headReachPx` from the feet's x. The bubble's left edge is a tail's
 * length further right (the tail sticks out `tail` px, its pivot on the edge), and its top `alongPx` above the aim, so
 * that the tail meets the edge a whole number of art pixels down and clear of the corner. It may cover the driver next to him.
 */
export const HELP_BUBBLE = { corner: 6, inset: 4, tail: 8, headPx: 58, headReachPx: 12, gap: 2, aimUpPx: 48, alongPx: 16, charPx: 12, linePx: 24 } as const

/**
 * The box of the HELP! bubble's body for a driver whose feet are at (`x`, `feetY`), and where the tail meets its left
 * edge, px down from its top. `words` are what it says: HELP!, or MARSHAL! (F-708), which makes the body wider.
 */
export function helpBubbleBox(x: number, feetY: number, words: string = HELP_TEXT): { x: number; y: number; w: number; h: number; tailAlong: number } {
  const w = words.length * HELP_BUBBLE.charPx + 2 * HELP_BUBBLE.inset
  const h = HELP_BUBBLE.linePx + 2 * HELP_BUBBLE.inset
  return {
    x: Math.round(x) + HELP_BUBBLE.headReachPx + HELP_BUBBLE.gap + HELP_BUBBLE.tail,
    y: Math.round(feetY) - HELP_BUBBLE.aimUpPx - HELP_BUBBLE.alongPx,
    w,
    h,
    tailAlong: HELP_BUBBLE.alongPx,
  }
}

/**
 * The driver who shouts for his marshal (F-708): the words, as the bubble shows them (when they are not spoken) and as
 * they are said, how often (s), and how long a bubble pulses for after each shout (s). A pulse is drawn in
 * `PULSE_LEVELS` steps, each making the bubble `PULSE_GROW_PX` bigger on every side that can grow.
 */
export const SHOUT = { words: 'MARSHAL!', spoken: 'Marshal!', everyS: 2, pulseS: 0.4 } as const
export const PULSE_LEVELS = 2
export const PULSE_GROW_PX = 2

/** The step of a pulse, 0 (none) to `PULSE_LEVELS`, for a pulse of 0..1. */
export const pulseLevel = (pulse: number): number => (pulse <= 0 ? 0 : pulse > 0.5 ? PULSE_LEVELS : 1)

/**
 * The cars whose drivers shout "Marshal!": a car that waits for help (`needsHelp`) and whose marshal is on his phone —
 * he has been given the car, and has not seen it. When he puts the phone away and sets off, the car is in hand and the
 * shouting stops. `cars` are indexed by car id.
 */
export function callingCars(
  cars: readonly Pick<CarSnapshot, 'state' | 'strickenCause'>[],
  marshals: readonly Pick<MarshalSnapshot, 'state' | 'targetCar'>[],
  reverse: boolean,
): CarId[] {
  return cars.flatMap((car, id) => (needsHelp(car, reverse) && marshals.some((marshal) => marshal.state === 'distracted' && marshal.targetCar === id) ? [id] : []))
}

/**
 * When each calling driver shouts: at once when he starts, then every `SHOUT.everyS` for as long as he is calling, on the
 * session's clock (a pause holds it). A shout that comes due while the clock has jumped past more than a period is not
 * made up. Pure; one per session.
 */
export class ShoutClock {
  private readonly next = new Map<CarId, number>()
  private readonly last = new Map<CarId, number>()

  /** Call it every frame with the cars calling now: the cars whose shout is due this frame. Cars no longer calling are forgotten. */
  update(nowS: number, calling: readonly CarId[]): CarId[] {
    for (const car of [...this.next.keys()]) {
      if (calling.includes(car)) continue
      this.next.delete(car)
      this.last.delete(car)
    }
    const due: CarId[] = []
    for (const car of calling) {
      const at = this.next.get(car) ?? nowS
      if (nowS < at) continue
      due.push(car)
      this.last.set(car, nowS)
      const after = at + SHOUT.everyS
      this.next.set(car, after > nowS ? after : nowS + SHOUT.everyS)
    }
    return due
  }

  /** How strongly a calling car's bubble pulses at `nowS`: 1 at the shout, down to 0 `SHOUT.pulseS` later; 0 for a car that is not calling. */
  pulse(car: CarId, nowS: number): number {
    const at = this.last.get(car)
    return at === undefined ? 0 : Math.max(0, 1 - (nowS - at) / SHOUT.pulseS)
  }

  /** The cars calling now, with each one's pulse. */
  pulses(nowS: number): Map<CarId, number> {
    return new Map([...this.next.keys()].map((car) => [car, this.pulse(car, nowS)]))
  }
}
