import { INITIALS_MAX } from './boards'

// Typing initials, arcade style (F-406): the rules of the entry field as a pure reducer, so that they are tested without
// an engine. The screen only turns keys into `InitialsKey`s and draws the state.

/** The characters initials are made of, in the order the arrow keys step through them. */
export const ALLOWED = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'

/**
 * The text typed so far (0..6 characters, never a gap) and the cursor: the slot a key acts on, from 0 to the length of
 * the text. At the length it is on the empty slot after the last character; with six characters typed that is past
 * the end, and nothing more can be added.
 */
export interface InitialsState {
  text: string
  cursor: number
}

export type InitialsKey = { type: 'char'; char: string } | { type: 'left' | 'right' | 'up' | 'down' | 'backspace' }

/** The state a field opens in: `last` (the initials used last time, if any and valid) typed in, the cursor after it. */
export function initialsStart(last: string | null): InitialsState {
  const text = last === null ? '' : [...last].filter((char) => ALLOWED.includes(char)).slice(0, INITIALS_MAX).join('')
  return { text, cursor: text.length }
}

/** Enter confirms once there is at least one character. */
export const canConfirm = (s: InitialsState): boolean => s.text.length >= 1

/** The character `step` places further along the allowed ones from `char`, going round the ends. */
function stepped(char: string, step: 1 | -1): string {
  const at = ALLOWED.indexOf(char)
  return ALLOWED.charAt((at + step + ALLOWED.length) % ALLOWED.length)
}

/** `text` with the character at `at` replaced, or one appended when `at` is the end. */
const put = (text: string, at: number, char: string): string => text.slice(0, at) + char + text.slice(at + 1)

/**
 * The state after a key. A typed letter or digit goes under the cursor (replacing what is there, or added at the end
 * if there is room) and the cursor moves on; lower case is taken as upper case and any other character is ignored.
 * Left and right move the cursor; up and down step the character under it through the allowed ones (on the empty slot
 * after the last character, up starts it at A and down at 9); backspace deletes the character before the cursor.
 */
export function initialsReduce(s: InitialsState, k: InitialsKey): InitialsState {
  const cursor = Math.min(Math.max(s.cursor, 0), s.text.length)
  const here = { text: s.text, cursor }
  switch (k.type) {
    case 'char': {
      // Plain ASCII only, before the case is changed: 'ı' and 'ſ' would otherwise turn into an I and an S.
      if (!/^[A-Za-z0-9]$/.test(k.char) || cursor >= INITIALS_MAX) return here
      return { text: put(s.text, cursor, k.char.toUpperCase()), cursor: cursor + 1 }
    }
    case 'left':
      return { text: s.text, cursor: Math.max(0, cursor - 1) }
    case 'right':
      return { text: s.text, cursor: Math.min(s.text.length, cursor + 1) }
    case 'up':
    case 'down': {
      const step = k.type === 'up' ? 1 : -1
      if (cursor < s.text.length) return { text: put(s.text, cursor, stepped(s.text.charAt(cursor), step)), cursor }
      if (s.text.length >= INITIALS_MAX) return here
      return { text: put(s.text, cursor, step === 1 ? 'A' : '9'), cursor }
    }
    case 'backspace':
      return cursor === 0 ? here : { text: s.text.slice(0, cursor - 1) + s.text.slice(cursor), cursor: cursor - 1 }
  }
}
