import type { RaceControlCall } from '@sim'

/**
 * What the race director says from the PA (F-404), in English: terse and procedural, as at a club meeting. One or
 * more variants of each call; the first is the plain one, which a text display shows (in capitals), and the others
 * are for the voice to vary. `{label}` is the session's label, "Qualifying round 1" or "A final". Every character
 * is in the game's bitmap font: a test over the strings the HUD can show checks it.
 *
 * `weather-notice` is called a second after every change of sky (F-601); what the sky has changed to is the
 * commentator's to say and the screen's to show. `session-intro` is here so that the table covers every call; the
 * session does not make it yet.
 */
export const RACE_CONTROL_EN: Readonly<Record<RaceControlCall, readonly [string, ...string[]]>> = {
  'session-intro': ['{label}, drivers to your stands', '{label} is next, drivers to your stands'],
  'cars-to-line': ['Cars to the line', 'Marshals, cars to the line, please'],
  'ten-seconds': ['Ten seconds', 'Ten seconds to the start'],
  'three-seconds': ['Three seconds', 'Three seconds to the start'],
  'start-tone': ['Go', 'Tone, go'],
  halfway: ['Halfway', 'Halfway, time check'],
  'last-minute': ['Last minute', 'One minute left'],
  'time-up': ['Time is up, finish your lap', 'Time, finish your lap and park it'],
  'provisional-result': ['Provisional result is on the board', 'Provisional result is up'],
  'thank-marshals': ['Thank you, marshals', 'Marshals, thank you, you can come off the track'],
  'weather-notice': ['Weather notice, the sky is changing', 'Weather notice'],
}
