// The audio graph uses the browser's types. The Node-side tests (tsconfig.node.json, no DOM lib) import these modules with
// a stand-in for the context, so the declaration is made here, where the types are first needed.
/// <reference lib="dom" />
import { softLimitCurve, volumeGain } from './mapping'

/** ZzFX's 21 parameters, as `ZZFX.buildSamples` takes them. */
export type ZzfxParams = ReadonlyArray<number | undefined>

/**
 * What the mixer runs on. The game's backend is ZzFX's context and sample builder (`zzfx-backend.ts`, the one module
 * that imports `zzfx`, which creates its `AudioContext` the moment it is imported); tests give a fake.
 */
export interface AudioBackend {
  ctx: AudioContext
  /** One mono sample channel, at `sampleRate`, for a ZzFX parameter set. */
  buildSamples(...params: ZzfxParams): number[]
  sampleRate: number
}

/** The slice of `document` the mixer watches, so that a test can stand in for it. */
export interface VisibilitySource {
  readonly hidden: boolean
  addEventListener(type: 'visibilitychange', listener: () => void): void
  removeEventListener(type: 'visibilitychange', listener: () => void): void
}

/** The levels of the settings (`SaveData['settings']['volume']`), each 0..1. */
export interface Volumes {
  master: number
  sfx: number
  voice: number
}

/** The levels the buses start at, before the saved settings are applied: the defaults of a fresh save (F-405). */
export const DEFAULT_VOLUMES: Readonly<Volumes> = { master: 0.8, sfx: 0.8, voice: 1 }

/** Time constant of a level change, so that the slider and the mute never click. */
const LEVEL_TAU_S = 0.02

/** The music's own level on the slider scale (gain = level squared), set so that the loudest motor stays well above it (F-705). */
export const DEFAULT_MUSIC_LEVEL = 0.28
/** The share of its level the music keeps while race control or the commentator speaks: about -9 dB. */
export const DUCK_GAIN = 0.35
/** How fast the music gives way when someone starts to speak, and how slowly it comes back when they stop; seconds. */
export const DUCK_ATTACK_TAU_S = 0.06
export const DUCK_RELEASE_TAU_S = 0.5

/** Who can be speaking over the music. The two speakers are counted apart, so that one finishing does not lift the duck while the other talks. */
export type Speaker = 'official' | 'commentator'

/**
 * The game's one audio graph (ADR-006), on one `AudioContext` the game owns (AGENTS.md, Phaser rule 4; never Phaser's
 * sound manager, which cannot be paused):
 *
 * ```
 * effects voices ─► sfx ───┐
 *                          ├─► master ─► compressor ─► limiter ─► destination
 * (any WebAudio voice) ─► voice ─┤
 * music pieces ─► music ───┘
 * ```
 *
 * `sfx` carries every game sound: motors, tyres, one-shots, weather, the start tones. `voice` is the spoken commentary's
 * bus for anything that goes through WebAudio; speech itself runs in the browser's `speechSynthesis`, which cannot be
 * routed here, so F-703 reads `voiceVolume()` instead. The compressor is the clipping guard, and behind it a soft limiter
 * that no pile-up of one-shots can get past (`softLimit`: transparent to 0.7 of full scale, never above 0.98).
 * `music` (F-705) is the ambient music's bus: its own level, and ducked while either speaker talks (`setSpeaking`).
 *
 * Whether the context runs follows four things: it has been unlocked by a key press, the game is not paused, the tab
 * is not hidden. Mute is separate: it silences and refuses one-shots but leaves the context running.
 */
export class AudioMixer {
  readonly ctx: AudioContext
  readonly master: GainNode
  readonly sfx: GainNode
  readonly voice: GainNode
  /** The ambient music's bus (F-705): the player connects its pieces here. Its level is the music level times the duck. */
  readonly music: GainNode
  readonly compressor: DynamicsCompressorNode
  readonly limiter: WaveShaperNode
  readonly sampleRate: number

  private readonly build: AudioBackend['buildSamples']
  private readonly visibility: VisibilitySource | null
  private readonly onVisibility = (): void => {
    void this.sync()
  }
  private volumes: Volumes = { ...DEFAULT_VOLUMES }
  private musicLevelSetting = DEFAULT_MUSIC_LEVEL
  private readonly speakers = new Set<Speaker>()
  private isUnlocked = false
  private isPaused = false
  private isMuted = false
  private disposed = false

  constructor(backend: AudioBackend, visibility: VisibilitySource | null = typeof document === 'undefined' ? null : document) {
    this.ctx = backend.ctx
    this.build = backend.buildSamples
    this.sampleRate = backend.sampleRate
    const ctx = this.ctx
    this.compressor = ctx.createDynamicsCompressor()
    // A fast, firm limiter-like setting: the voices are budgeted to stay under full scale (mapping.ts), and this catches
    // the one-shots that land on top of them.
    this.compressor.threshold.value = -10
    this.compressor.knee.value = 8
    this.compressor.ratio.value = 12
    this.compressor.attack.value = 0.003
    this.compressor.release.value = 0.15
    this.limiter = ctx.createWaveShaper()
    this.limiter.curve = softLimitCurve()
    this.limiter.oversample = '2x'
    this.master = ctx.createGain()
    this.sfx = ctx.createGain()
    this.voice = ctx.createGain()
    this.music = ctx.createGain()
    this.sfx.connect(this.master)
    this.voice.connect(this.master)
    this.music.connect(this.master)
    this.master.connect(this.compressor)
    this.compressor.connect(this.limiter)
    this.limiter.connect(ctx.destination)
    this.applyLevels(true)
    this.visibility = visibility
    visibility?.addEventListener('visibilitychange', this.onVisibility)
    // A browser whose autoplay policy lets a context start on its own (a headless one, a page the person has already
    // used) would have the game making sound before a key press. The mixer keeps it suspended until it is unlocked.
    void this.sync()
  }

  /** True once a key press has let the context run. Until then nothing is audible and the context is suspended. */
  get unlocked(): boolean {
    return this.isUnlocked
  }

  get muted(): boolean {
    return this.isMuted
  }

  /** Whether the game has paused its sound (the pause overlay, a hidden tab not counted). */
  get paused(): boolean {
    return this.isPaused
  }

  /** Whether the mixer intends the context to run: unlocked, the game not paused, the tab visible. */
  get running(): boolean {
    return this.isUnlocked && !this.isPaused && !this.disposed && !(this.visibility?.hidden ?? false)
  }

  /** Whether a one-shot started now would be heard: running, and not muted. Voices ask before they play. */
  get audible(): boolean {
    return this.running && !this.isMuted
  }

  /** The level speech should be spoken at, 0..1 (`SpeechSynthesisUtterance.volume`): master times voice, and nothing when muted. */
  readonly voiceVolume = (): number => (this.isMuted ? 0 : this.volumes.master * this.volumes.voice)

  /**
   * A key press: lets the context run (the browsers' autoplay rule). Safe to call on every key press until the context
   * is running; a press the browser did not count (Escape, in Chrome) is simply asked again by the next.
   */
  async unlock(): Promise<void> {
    if (this.disposed) return
    this.isUnlocked = true
    await this.sync()
  }

  setVolumes(volumes: Volumes): void {
    this.volumes = { master: volumes.master, sfx: volumes.sfx, voice: volumes.voice }
    this.applyLevels(false)
  }

  /** The music's level on the slider scale, 0..1 (gain = level squared, like the other buses). */
  setMusicLevel(level: number): void {
    this.musicLevelSetting = level
    this.applyMusic(false)
  }

  get musicLevel(): number {
    return this.musicLevelSetting
  }

  /**
   * A speaker starts or stops talking (F-703 calls this): while either is, the music keeps `DUCK_GAIN` of its level, coming
   * down fast and back slowly. The two speakers are counted apart; a call that changes nothing does nothing.
   */
  setSpeaking(on: boolean, speaker: Speaker = 'commentator'): void {
    const before = this.speakers.size > 0
    if (on) this.speakers.add(speaker)
    else this.speakers.delete(speaker)
    if (before !== this.speakers.size > 0) this.applyMusic(false)
  }

  /** Whether the music is ducked: someone is speaking. */
  get speaking(): boolean {
    return this.speakers.size > 0
  }

  setMuted(muted: boolean): void {
    this.isMuted = muted
    this.applyLevels(false)
  }

  /** The game is paused: suspends the context, which freezes every voice and every sound in flight at once. */
  suspend(): void {
    this.isPaused = true
    void this.sync()
  }

  /** The game is running again: resumes the context, without a click (the page has had its key press). */
  resume(): void {
    this.isPaused = false
    void this.sync()
  }

  /** A mono buffer of ZzFX samples. */
  zzfxBuffer(params: ZzfxParams): AudioBuffer {
    const samples = this.build(...params)
    const buffer = this.ctx.createBuffer(1, samples.length, this.sampleRate)
    buffer.getChannelData(0).set(samples)
    return buffer
  }

  /** Stops watching the tab and silences the graph. The context itself is the page's for as long as the game lives. */
  dispose(): void {
    if (this.disposed) return
    this.disposed = true
    this.visibility?.removeEventListener('visibilitychange', this.onVisibility)
    this.sfx.disconnect()
    this.voice.disconnect()
    this.music.disconnect()
    this.master.disconnect()
    this.compressor.disconnect()
    this.limiter.disconnect()
    void this.ctx.suspend()
  }

  private applyLevels(immediate: boolean): void {
    const target = (param: AudioParam, value: number): void => {
      if (immediate) param.value = value
      else param.setTargetAtTime(value, this.ctx.currentTime, LEVEL_TAU_S)
    }
    target(this.master.gain, this.isMuted ? 0 : volumeGain(this.volumes.master))
    target(this.sfx.gain, volumeGain(this.volumes.sfx))
    target(this.voice.gain, volumeGain(this.volumes.voice))
    this.applyMusic(immediate)
  }

  /** The music bus: its level, times the duck while somebody speaks. Down quickly, up slowly. */
  private applyMusic(immediate: boolean): void {
    const ducked = this.speakers.size > 0
    const value = volumeGain(this.musicLevelSetting) * (ducked ? DUCK_GAIN : 1)
    if (immediate) this.music.gain.value = value
    else this.music.gain.setTargetAtTime(value, this.ctx.currentTime, ducked ? DUCK_ATTACK_TAU_S : DUCK_RELEASE_TAU_S)
  }

  /**
   * Asks the context to run or to stop, whichever `running` says. It does not look at the context's state first: a
   * suspend followed at once by a resume must end running, and the browser carries out the requests in the order they
   * were made, so each is made. Asking a running context to run, or a suspended one to suspend, does nothing.
   */
  private sync(): Promise<void> {
    const request = this.running ? this.ctx.resume() : this.ctx.suspend()
    // A browser that refuses (no key press has counted yet, a context closed under us) leaves the state as it was; the
    // next key press asks again.
    return request.catch(() => undefined)
  }
}
