import type { ShippedPreset } from './index'

/**
 * NEWBIE (F-807): the car made easy to drive, for a first-time player to try and tell the owner how it feels. Tuned
 * on Cuenca RC against scripted four-key drives that overcook every corner the way a new player does
 * (tests/sim/vehicle/newbie-preset.test.ts), within the tuning panel's slider ranges. A session run with it is tuned,
 * like any preset: it sets no best lap and no leaderboard entry.
 *
 * Every number is game tuning, not a real setup: no real tyre has this much grip.
 */
export const newbie: ShippedPreset = {
  name: 'NEWBIE',
  about: 'Easy to drive: more grip, a gentler throttle and steering, less punch, a little less top speed. A tuned session: no records.',
  tuning: {
    shaping: {
      // A gentler throttle: half a second from off to full on the key (the shipped car takes a quarter).
      throttleRisePerS: 2,
      // Gentler steering. With the grip below a held key would ask for more lock at speed and a tap would turn the
      // car half as far again as the shipped car's; a slower wheel (shipped 3.5) and a held key that asks for
      // eight tenths of the grip (shipped nine) bring a tap back to the shipped car's and leave the rest as margin.
      steerRatePerS: 2.8,
      lockGripFactor: 0.8,
    },
    // Less punch out of slow corners, most of all in the Modified, whose main lever this is (shipped 100 A).
    currentLimitA: 70,
    // A little less top speed in every class, four to six per cent (shipped 7.6 V).
    packVoltage: 6.8,
  },
  classes: {
    // Grip margin: about a third more grip, and more of it at the rear than at the front, so that the nose gives
    // first and the tail stays behind the car.
    'tc-stock-175': { muFront: 2.2, muRear: 2.5 },
    'tc-mod-45': { muFront: 2.3, muRear: 2.5 },
    // The front-drive car's front tyres steer and drive: a milder motor (seven tenths of the 340 W) and a lower,
    // more forward weight leave them grip to steer with when the throttle is held.
    'fwd-105': { muFront: 2.2, muRear: 2.35, weightFront: 0.6, cgHeightM: 0.03, motor: { peakPowerW: 238 } },
    // The F1's braking slide, its signature, is softened: the rear is braked as the others are and gives less.
    'f1-215': { muFront: 2.02, muRear: 2.25, brakeRearGain: 1, brakeSlideGive: 1 },
  },
}
