import type { CarClassId } from '@sim'

/**
 * What a class's car is made of, as far as its sound goes (F-704, the owner's request of 2026-10-10: the car's sound
 * is built from its drivetrain's real parts). Data, not code: the mapping reads this table and nothing branches on a
 * class id.
 *
 * The three sources, each at its own real frequency (then pitched for the speakers, see `AUDIBLE` below):
 * - the motor's whine: rotor revolutions per second times pole pairs (a sensored 540-size brushless rotor has four
 *   poles, so two pairs: from the wiki's powertrain pages);
 * - the pinion-and-spur gear mesh: motor revolutions per second times the pinion's teeth;
 * - the belt, on the belt-driven touring classes: the belt pulley's revolutions per second times its teeth. The
 *   pulley sits on the spur gear's shaft, so it turns at motor speed times pinion over spur.
 *
 * ASSUMPTIONS, labelled as such: the tooth counts and the internal ratio are not in the wiki or in the class rows.
 * They are chosen so that `spurTeeth / pinionTeeth * internalRatio` is the class's own `finalDriveRatio` (a test
 * holds them to it), with pinions and spurs in the range a 64-pitch touring car or pan car really runs. The pulley
 * (21 teeth) is a typical 3 mm-pitch touring-car belt pulley.
 */
export interface DrivetrainSound {
  /** Rotor pole pairs. */
  polePairs: number
  pinionTeeth: number
  spurTeeth: number
  /** The ratio after the spur gear (belt, pulleys and the differential's ring and pinion); 1 for direct drive. */
  internalRatio: number
  /** Teeth on the belt pulley; 0 where there is no belt. */
  pulleyTeeth: number
  /** Level of each source against the others, 0..1. They are mixed under one low-pass, so these set the character. */
  mix: { whine: number; mesh: number; belt: number }
  /** How loud the class is against the others (a Modified car is a louder, higher thing), around 1. */
  loudness: number
  /** Added to the low-pass's brightness, -0.2..0.2: where on the spectrum this class sits. */
  brightnessBias: number
}

export const DRIVETRAIN_SOUND: Readonly<Record<CarClassId, DrivetrainSound>> = {
  // 17.5T: 3.5 = 49/28 * 2.0. The planted one: a mellow whine, the belt audible underneath.
  'tc-stock-175': { polePairs: 2, pinionTeeth: 28, spurTeeth: 49, internalRatio: 2.0, pulleyTeeth: 21, mix: { whine: 0.6, mesh: 0.14, belt: 0.14 }, loudness: 1, brightnessBias: 0 },
  // 4.5T: 7.25 = 87/24 * 2.0. A small pinion on a big spur, a very high-revving motor: the loud, bright, screaming one.
  'tc-mod-45': { polePairs: 2, pinionTeeth: 24, spurTeeth: 87, internalRatio: 2.0, pulleyTeeth: 21, mix: { whine: 0.56, mesh: 0.16, belt: 0.14 }, loudness: 1.12, brightnessBias: 0.1 },
  // 10.5T: 4.8 = 60/25 * 2.0. One belt to the front differential: the same parts, in between.
  'fwd-105': { polePairs: 2, pinionTeeth: 25, spurTeeth: 60, internalRatio: 2.0, pulleyTeeth: 21, mix: { whine: 0.6, mesh: 0.14, belt: 0.12 }, loudness: 1.04, brightnessBias: 0.03 },
  // 21.5T: 3.25 = 78/24 * 1. Direct drive from the spur to the rear axle: gear mesh and no belt. The low, light one.
  'f1-215': { polePairs: 2, pinionTeeth: 24, spurTeeth: 78, internalRatio: 1, pulleyTeeth: 0, mix: { whine: 0.66, mesh: 0.2, belt: 0 }, loudness: 0.9, brightnessBias: -0.08 },
}

/**
 * How the real frequencies are pitched for speakers: a multiplier on each source's real frequency, and the knee and
 * ceiling of the soft cap that stops a source leaving the range a small speaker reproduces (and an ear tolerates).
 * Below the knee a frequency passes unchanged. These numbers are the first guess, to be tuned by ear (F-704, task 3).
 */
export const AUDIBLE = {
  whine: { scale: 1, kneeHz: 900, ceilingHz: 2200 },
  mesh: { scale: 0.12, kneeHz: 1200, ceilingHz: 3000 },
  belt: { scale: 0.25, kneeHz: 900, ceilingHz: 2200 },
} as const
