import Phaser from 'phaser'
import { atMost, createCommentary } from '@commentary'
import type { DriverId, SessionConfig, SessionEntry, SessionResult, SessionSnapshot } from '@sim'
import { ROSTER } from '@content/roster'
import { manifestOf } from '../assets/manifest'
import { mixerOf } from '../audio'
import { ttsOf } from '../audio/Tts'
import { LOGICAL_HEIGHT, LOGICAL_WIDTH } from '../config'
import { onKey, onNav, type NavKey } from '../input/keys'
import { carsOf, NO_OFFER, isOffered, offerFor, weatherOf, type Offer } from '../leaderboard'
import { bestKey, newBestLapWords, newBestRaceWords, newBests, saves, speechOn, storedName, toggleSpeech, updateBests, type NewBests } from '../persistence'
import { BAND_EDGE, OFFICIAL_PX } from '../race/hud-format'
import { COMMENTARY_LINES, CommentaryDirector } from '../race/CommentaryDirector'
import { Official, type OfficialInfo } from '../race/Official'
import { formatLapTime } from '../race/PracticeReadout'
import { ASSISTED_MEANS } from '../race/assistance'
import { DNF, driverName, FASTEST_MARK, RESULTS_COLUMNS, resultsTable, type ResultsTable } from '../race/quick-race'
import { Panel, Table, THEME, lineHeight, charWidth, tableChars, text, type HasReadout, type ScreenReadout } from '../ui'
import { SWATCH } from './GarageScene'
import type { InitialsInit } from './InitialsScene'

/**
 * What starts the results screen. It does not know where it goes next: Enter calls `onContinue`, so that a quick race
 * and (F-403) a race-day event can both use it unchanged.
 */
export interface ResultsInit {
  result: SessionResult
  /** The driver the person at the keyboard is: their row is highlighted. */
  playerId: DriverId
  /** The session's entries, for each car's colour. */
  entries: SessionEntry[]
  /** The session that was run: its track, direction, class and length say which bests the result counts towards (F-405). */
  config: SessionConfig
  /** The tuning panel changed something in the session: its lap times count for nothing. */
  tuned: boolean
  /** The player drove the DRIVING ASSISTANCE car (F-811): the records the session sets count, and carry (A*). Left out, it was not. */
  assisted?: boolean
  /** The autopilot drove the player's car at some point of the session (debug builds only): it counts for nothing on the leaderboards (F-406). */
  autopilot: boolean
  onContinue: () => void
  /** What the key hint at the bottom says Enter does. Left out: ENTER CONTINUE. */
  continueHint?: string
  /** How the session ended, for the commentator to say the result (F-703). Left out, he is silent. */
  closing?: Closing
}

/** How a finished session ended: its last snapshot and its configuration, which the commentator says the result from. */
export interface Closing {
  snapshot: SessionSnapshot
  config: SessionConfig
}

/** The registry key a race day session's `Closing` is kept under, for the standings and the podium that follow it. */
export const CLOSING_KEY = 'closing-session'

/** The window's place on the result screens: at the bottom left, its foot `BAND_EDGE` above the screen's, and its bubble stopping short of the key hint at the bottom centre. */
const CLOSING_BAND_TOP = LOGICAL_HEIGHT - BAND_EDGE - OFFICIAL_PX - 8
const CLOSING_BUBBLE_RIGHT = 660

/** Where a screen without room at the bottom left (the podium) puts the window: its left edge and top, and the right edge its bubble stops at, px. */
export interface ClosingPlace {
  left: number
  top: number
  right: number
}

/**
 * The commentator on a result screen (F-703): the same portrait and bubble as the race's, at the bottom left, saying
 * the session's result once. It is the director of the race with an engine that gives that many lines and no more;
 * the official has nothing to say here. On the podium (F-709) he then says one line about the player's place in the
 * event (`eventPlace`, 1 first), whatever it is. `V` turns speech on and off as in the race. Null where there is
 * nothing to say: no closing session (an event resumed at its standings or podium), or the art not loaded.
 */
export class ClosingVoice {
  private readonly official: Official
  private readonly director: CommentaryDirector
  private readonly releaseKey: (() => void) | null
  private startS: number | null = null

  /** `salt` makes each screen's engine choose its own variant of the line. */
  static mount(scene: Phaser.Scene, closing: Closing | null, salt: number, place?: ClosingPlace, eventPlace?: number): ClosingVoice | null {
    if (closing === null || !scene.textures.exists('ui')) return null
    return new ClosingVoice(scene, closing, salt, place, eventPlace)
  }

  private constructor(scene: Phaser.Scene, closing: Closing, salt: number, place?: ClosingPlace, eventPlace?: number) {
    const { config, snapshot } = closing
    // The official has nothing to say on a result screen, so the commentator is in the window all through it, at rest too (F-809).
    this.official = place === undefined
      ? new Official(scene, manifestOf(scene), CLOSING_BAND_TOP, CLOSING_BUBBLE_RIGHT + 6, undefined, 'commentator')
      : new Official(scene, manifestOf(scene), place.top - 8, place.right + 6, place.left, 'commentator')
    const name = storedName(saves.read())
    const engine = createCommentary(COMMENTARY_LINES, ROSTER, config.seed + salt, {
      kind: config.kind,
      entries: config.entries,
      ...(name === null ? {} : { playerName: name }),
      ...(eventPlace === undefined ? {} : { eventPlace }),
    })
    engine.observe([{ type: 'session-finished', tick: snapshot.tick }], snapshot, 0)
    // The result, then on the podium the player's place: the engine scores the place below the result (F-709).
    this.director = new CommentaryDirector(
      atMost(engine, eventPlace === undefined ? 1 : 2),
      this.official,
      ttsOf(scene.registry, () => mixerOf(scene.registry)?.voiceVolume() ?? 1),
      { speech: speechOn, commentaryColour: THEME.colours.text, onTalking: (speaker, on) => mixerOf(scene.registry)?.setSpeaking(on, speaker) },
    )
    const keyboard = scene.input.keyboard
    this.releaseKey = keyboard === null ? null : onKey(keyboard, 'V', () => void toggleSpeech())
  }

  /** The scene's clock, ms (Phaser's frame timestamp): the first frame is time 0. */
  update(timeMs: number): void {
    this.startS ??= timeMs / 1000
    const nowS = timeMs / 1000 - this.startS
    this.director.update(nowS)
    this.official.update(nowS)
  }

  /** The window as the debug hook reports it. */
  info(): OfficialInfo {
    return this.official.info()
  }

  destroy(): void {
    this.releaseKey?.()
    this.director.dispose()
    this.official.destroy()
  }
}

const MARGIN = 96
/** The panel sits in the band between the heading and the key hint, and never higher than this. */
const PANEL_TOP = 168
const PANEL_BOTTOM = LOGICAL_HEIGHT - 96
const CHIP_SIZE = 24
/** Room left of the table for each row's colour chip. */
const CHIP_COLUMN = 48
const FOOT_GAP = 36
/** Written at the end of the row of a car that finished the session still owing a pit stop (F-306): why it is where it is. */
const NO_PIT_STOP = 'NO PIT STOP'
/** And under the table, what that means for its place. */
const NO_PIT_STOP_MEANS = `${NO_PIT_STOP}: CLASSIFIED BEHIND EVERY CAR THAT STOPPED`

/**
 * The results of a finished session: a table in result order with position, car number, driver, laps and time (DNF
 * beside a car that did not finish) and best lap, the player's row marked with the cursor and a highlight bar, the
 * session's fastest lap marked with a star, and each car's colour beside its row. A car that missed a pit stop it
 * owed has NO PIT STOP at the end of its row, and a line under the table says what that cost it (F-306). The
 * player's result is counted towards their bests, and NEW BEST LAP and NEW BEST RACE announce what it set (F-405).
 * Enter continues; if the result makes a top-10 board (F-406) it goes by way of the initials screen and the board first.
 */
export class ResultsScene extends Phaser.Scene implements HasReadout {
  private panel: Panel | null = null
  private table: Table | null = null
  private parts: Phaser.GameObjects.GameObject[] = []
  private release: (() => void) | null = null
  private shown: ResultsTable | null = null
  /** How many rows are marked as having missed a pit stop. */
  private noPitStop = 0
  /** What this result added to the bests (F-405). */
  private added: NewBests = { lap: null, race: null }
  /** What this result is good enough for on the leaderboards (F-406). */
  private offer: Offer = NO_OFFER
  /** What the scene was started with. */
  private request: Partial<ResultsInit> = {}
  private handled = 0
  /** The commentator, saying the result (F-703). */
  voice: ClosingVoice | null = null

  constructor() {
    super('Results')
  }

  init(data: Partial<ResultsInit>): void {
    this.handled = 0
    this.shown = null
    this.noPitStop = 0
    this.added = { lap: null, race: null }
    this.offer = NO_OFFER
    this.request = data
  }

  create(): void {
    const { result, playerId, entries } = this.request
    if (result === undefined || playerId === undefined) throw new Error('ResultsScene: it was started without a result and a player')
    this.cameras.main.setBackgroundColor(THEME.colours.background)
    const shown = resultsTable(result, playerId, ROSTER)
    this.shown = shown
    this.added = this.countBests(result, playerId)
    this.offer = this.leaderboardOffer(result, playerId)

    this.parts.push(text(this, { x: MARGIN, y: 48 }, 'RESULTS', 'large').setTint(THEME.colours.accent))
    this.parts.push(text(this, { x: LOGICAL_WIDTH / 2, y: LOGICAL_HEIGHT - 64 }, this.request.continueHint ?? 'ENTER CONTINUE', 'small').setOrigin(0.5, 0).setTint(THEME.colours.textDim))

    // The cars that ended the session owing a pit stop: the result has them behind every car that owed none.
    const missedStop = result.rows.map((row) => (row.pitStopsMissed ?? 0) > 0)
    this.noPitStop = missedStop.filter(Boolean).length

    const rowsHeight = (shown.rows.length + 1) * lineHeight('body')
    const bestLines = this.bestLines()
    const footLines = [...bestLines, ...this.footLines(result, playerId, shown)]
    // Two characters more than the columns hold the cursor of the player's row.
    const tableWidth = (tableChars(RESULTS_COLUMNS) + 2) * charWidth('body')
    // Room right of the table for the reason, on a result that has one to give.
    const reasonWidth = this.noPitStop > 0 ? (NO_PIT_STOP.length + 1) * charWidth('body') : 0
    const panelWidth = tableWidth + reasonWidth + CHIP_COLUMN + 2 * THEME.padding
    const titleHeight = lineHeight('small') + 16
    const panelHeight = THEME.padding * 2 + titleHeight + rowsHeight + FOOT_GAP + footLines.length * Math.round(lineHeight('body') * 1.4)
    const panelTop = Math.max(PANEL_TOP, Math.round((PANEL_TOP + PANEL_BOTTOM - panelHeight) / 2))
    this.panel = new Panel(this, { x: Math.round((LOGICAL_WIDTH - panelWidth) / 2), y: panelTop, w: panelWidth, h: panelHeight }, { title: result.label.toUpperCase() })
    const inner = this.panel.inner

    const tableRect = { x: inner.x + CHIP_COLUMN, y: inner.y, w: tableWidth, h: rowsHeight + lineHeight('body') }
    this.table = new Table(this, tableRect, RESULTS_COLUMNS, 'body')
    this.table.setRows(shown.rows, shown.playerRow >= 0 ? shown.playerRow : undefined)

    // Each car's colour, beside its row.
    result.rows.forEach((row, i) => {
      const colour = entries?.find((entry) => entry.driverId === row.driverId)?.colour
      if (colour === undefined) return
      const y = tableRect.y + lineHeight('body') * (i + 1) + Math.round((lineHeight('body') - CHIP_SIZE) / 2)
      this.parts.push(this.add.rectangle(inner.x, y, CHIP_SIZE, CHIP_SIZE, SWATCH[colour]).setOrigin(0, 0))
    })

    // Why a car is at the back: beside its row, in the colour that marks what matters on this screen.
    missedStop.forEach((missed, i) => {
      if (!missed) return
      const at = { x: tableRect.x + tableWidth + charWidth('body'), y: tableRect.y + lineHeight('body') * (i + 1) }
      this.parts.push(text(this, at, NO_PIT_STOP, 'body').setTint(THEME.colours.accent))
    })

    footLines.forEach((line, i) => {
      const announced = i < bestLines.length
      this.parts.push(text(this, { x: inner.x, y: tableRect.y + rowsHeight + FOOT_GAP + i * Math.round(lineHeight('body') * 1.4) }, line, 'body').setTint(announced ? THEME.colours.accent : THEME.colours.textDim))
    })

    this.release = onNav(this, (key) => this.onKey(key))
    this.voice = ClosingVoice.mount(this, this.request.closing ?? null, 1)
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, this.dispose, this)
  }

  update(time: number): void {
    this.voice?.update(time)
  }

  readout(): ScreenReadout {
    const shown = this.shown
    return {
      focus: 'continue',
      values: {
        handled: this.handled,
        rows: shown?.rows.length ?? 0,
        playerRow: shown?.playerRow ?? -1,
        fastestRow: shown?.fastestRows[0] ?? -1,
        dnf: shown?.rows.filter((row) => row['time']?.endsWith(DNF) === true).length ?? 0,
        noPitStop: this.noPitStop,
        newBestLap: this.added.lap ?? 0,
        newBestRace: this.added.race === null ? 0 : 1,
        offerLap: this.offer.lap?.rank ?? 0,
        offerRace: this.offer.race?.rank ?? 0,
        assisted: this.assisted ? 1 : 0,
        bestLines: this.bestLines().join(' | '),
      },
    }
  }

  /**
   * Counts the player's result towards the bests of its track, direction and class (a qualifying heat or a final that
   * the player finished, in a race day or a quick race, and not in a session the tuning panel changed), saves them if
   * they changed, and says what is new.
   */
  private countBests(result: SessionResult, playerId: DriverId): NewBests {
    const { config, tuned } = this.request
    if (config === undefined || tuned !== false) return { lap: null, race: null }
    const { track, carClass, durationS } = config
    const before = saves.read()
    const after = saves.update((data) => updateBests(data, track.id, track.direction, carClass, result, playerId, durationS / 60, this.assisted))
    return newBests(before, after, bestKey(track.id, track.direction, carClass))
  }

  /** What the result is good enough for on the top-10 boards: nothing for a session that was not finished or was driven by the autopilot or with the tuning panel (F-406). */
  private leaderboardOffer(result: SessionResult, playerId: DriverId): Offer {
    const { config, tuned, autopilot } = this.request
    if (config === undefined) return NO_OFFER
    return offerFor({
      result,
      playerId,
      kind: config.kind,
      trackId: config.track.id,
      direction: config.track.direction,
      carClass: config.carClass,
      minutes: config.durationS / 60,
      weather: weatherOf(config.weather, config.seed),
      flags: { autopilot: autopilot !== false, tuned: tuned !== false },
      boards: saves.read().leaderboards,
    })
  }

  /** The announcements of a new best lap and a new best race, in that order; (A*) after each time when the session was driven with DRIVING ASSISTANCE. */
  private bestLines(): string[] {
    const { lap, race } = this.added
    return [...(lap === null ? [] : [newBestLapWords(lap, this.assisted)]), ...(race === null ? [] : [newBestRaceWords(race, this.assisted)])]
  }

  /** The session was driven with DRIVING ASSISTANCE (F-811). */
  private get assisted(): boolean {
    return this.request.assisted === true
  }

  /** What is written under the table: the session's fastest lap and who set it, what DNF means if any car shows it, and what a missed pit stop cost if any car missed one. */
  private footLines(result: SessionResult, playerId: DriverId, shown: ResultsTable): string[] {
    const lines: string[] = []
    if (result.fastestLap !== null) {
      lines.push(`${FASTEST_MARK} FASTEST LAP  ${driverName(result.fastestLap.driverId, playerId, ROSTER)}  ${formatLapTime(result.fastestLap.lapMs)}`)
    }
    if (shown.rows.some((row) => row['time']?.endsWith(DNF) === true)) lines.push(`${DNF} DID NOT FINISH`)
    if (this.noPitStop > 0) lines.push(NO_PIT_STOP_MEANS)
    if (this.assisted) lines.push(ASSISTED_MEANS)
    return lines
  }

  private onKey(key: NavKey): void {
    this.handled++
    if (key !== 'confirm') return
    const { config, onContinue } = this.request
    this.stopListening()
    if (config !== undefined && isOffered(this.offer)) {
      // The initials, then the board with the new row, then wherever the results were going.
      const data: InitialsInit = {
        offer: this.offer,
        where: { trackId: config.track.id, direction: config.track.direction, carClass: config.carClass, minutes: config.durationS / 60 },
        info: { cars: carsOf(config.entries.length), difficulty: config.difficulty, weather: weatherOf(config.weather, config.seed), assisted: this.assisted },
        onContinue: onContinue ?? (() => this.game.scene.start('Title')),
      }
      this.scene.start('Initials', data)
      return
    }
    this.scene.stop()
    onContinue?.()
  }

  private stopListening(): void {
    this.release?.()
    this.release = null
  }

  private dispose(): void {
    this.stopListening()
    this.voice?.destroy()
    this.voice = null
    this.table?.destroy()
    this.table = null
    this.panel?.destroy()
    this.panel = null
    for (const part of this.parts) part.destroy()
    this.parts = []
    this.shown = null
    this.added = { lap: null, race: null }
    this.offer = NO_OFFER
    this.request = {}
  }
}
