import type { AudioMixer } from './AudioMixer'
import { RateLimiter } from './mapping'
import { MAX_ONE_SHOTS, SFX_LIMITS, SFX_PEAK, SFX_PRESETS, type SfxKind } from './sfx-presets'

/** A level below this is not worth a node. */
const AUDIBLE_GAIN = 0.01

export interface PlayOptions {
  /** 0..1 against the kind's full level. */
  gain: number
  /** -1..1; 0 or left out is the middle. */
  pan?: number
  /** The car it belongs to, whose allowance it counts against. Left out: the one shared allowance. */
  car?: number
  /** The sim's clock in seconds, for the rate limit. Left out: the audio clock. */
  timeS?: number
}

interface OneShot {
  source: AudioBufferSourceNode
  nodes: AudioNode[]
}

/**
 * The one-shot effects (F-704): ZzFX parameter sets built once into buffers, then played through the mixer's sfx bus
 * with a level, a stereo position, a little pitch variation and a rate limit per kind and car. It plays nothing
 * unless the mixer is audible: a paused or muted game, or one not yet unlocked, makes no sound.
 */
export class Sfx {
  private readonly buffers = new Map<SfxKind, AudioBuffer>()
  private readonly limiters = new Map<string, RateLimiter>()
  private readonly sounding = new Set<OneShot>()
  /** How many one-shots were started, for the tests and the debug hook. */
  played = 0

  constructor(private readonly mixer: AudioMixer) {}

  /** Plays `kind`; false if it was dropped (inaudible, rate-limited, too many already sounding, or the game is not making sound). */
  play(kind: SfxKind, options: PlayOptions): boolean {
    const { mixer } = this
    const level = Math.min(1, options.gain)
    if (!mixer.audible || !(level >= AUDIBLE_GAIN) || this.sounding.size >= MAX_ONE_SHOTS) return false
    const limit = SFX_LIMITS[kind]
    let limiter = this.limiters.get(limit.group)
    if (limiter === undefined) this.limiters.set(limit.group, (limiter = new RateLimiter(limit.max, limit.windowS)))
    if (!limiter.allow(`${limit.group}:${options.car ?? '-'}`, options.timeS ?? mixer.ctx.currentTime)) return false

    const { ctx } = mixer
    let buffer = this.buffers.get(kind)
    if (buffer === undefined) this.buffers.set(kind, (buffer = mixer.zzfxBuffer(SFX_PRESETS[kind])))
    const source = ctx.createBufferSource()
    source.buffer = buffer
    // A few percent either way, so that the same hit twice is not the same sound twice.
    source.playbackRate.value = 0.96 + Math.random() * 0.08
    const gain = ctx.createGain()
    gain.gain.value = SFX_PEAK * level
    const nodes: AudioNode[] = [source, gain]
    source.connect(gain)
    let tail: AudioNode = gain
    if (options.pan !== undefined && options.pan !== 0) {
      const panner = ctx.createStereoPanner()
      panner.pan.value = Math.max(-1, Math.min(1, options.pan))
      tail.connect(panner)
      nodes.push(panner)
      tail = panner
    }
    tail.connect(mixer.sfx)
    const shot: OneShot = { source, nodes }
    this.sounding.add(shot)
    source.onended = () => this.release(shot)
    source.start()
    this.played++
    return true
  }

  /** Stops everything sounding and lets go of the buffers. */
  dispose(): void {
    for (const shot of [...this.sounding]) {
      try {
        shot.source.stop()
      } catch {
        // Already stopped.
      }
      this.release(shot)
    }
    this.buffers.clear()
    this.limiters.clear()
  }

  private release(shot: OneShot): void {
    if (!this.sounding.delete(shot)) return
    shot.source.onended = null
    for (const node of shot.nodes) node.disconnect()
  }
}
