import type Phaser from 'phaser'
import type { CarClass, CarSnapshot, CarState } from '@sim'
import type { WorldView } from '../config'
import { DEPTH } from './depth'
import type { RenderCar } from './interpolate'
import { DEFAULT_STYLE, GRAIN_FLECK_PX, TUFT_COLORS } from './track-style'

// Grass thrown up by a car that is bogging down (F-207): small flecks from the driven wheels, flung back the way
// the car came, for as long as its bog is rising. A fixed pool of rectangles, reused; nothing is created or
// destroyed while the race runs. It reads snapshots and keeps no gameplay state.

/**
 * The greens a fleck may be: the light blade of the grass tufts and the green of the grass round the slab. Both
 * are lighter than the infield and the border, where cars bog down, so a fleck shows against either.
 */
export const GRASS_FLECK_COLORS: readonly number[] = [TUFT_COLORS.light, DEFAULT_STYLE.outfieldGrass]
/** A fleck is one or two art pixels square (an art pixel is `GRAIN_FLECK_PX` screen pixels). */
const FLECK_SIZES_PX: readonly number[] = [2 * GRAIN_FLECK_PX, GRAIN_FLECK_PX, 2 * GRAIN_FLECK_PX]

/** The most flecks on screen at once, for every car together. */
const POOL_SIZE = 72
/** Flecks a second from a car that is barely moving, and the extra for each m/s, up to `RATE_SPEED_CAP_MS`. */
const RATE_BASE_PER_S = 30
const RATE_PER_MS = 24
const RATE_SPEED_CAP_MS = 4
/** How long a fleck lasts, s: this, plus up to as much again. */
const LIFE_S = 0.28
/** How fast a fleck leaves the wheel, px/s: this, plus up to as much again, and how quickly it slows. */
const THROW_PX_S = 70
const SLOWING_PER_S = 5
/** How far to either side of straight back a fleck may be thrown, rad. */
const SPREAD_RAD = 0.7

/**
 * How many flecks a second a car throws: none unless it is being driven and its bog rose since the last tick, and
 * then more the faster it is going, which is the faster its bog is rising.
 */
export function fleckRate(car: { bogBefore: number; bogNow: number; state: CarState; speedMS: number }): number {
  if (car.state !== 'driving' || !(car.bogNow > car.bogBefore)) return 0
  return RATE_BASE_PER_S + RATE_PER_MS * Math.min(RATE_SPEED_CAP_MS, Math.abs(car.speedMS))
}

/** A driven wheel's place on the car, from its centre: metres toward the nose and metres to the right. */
export interface WheelPlace {
  alongM: number
  acrossM: number
}

/** Where a class's driven wheels are: the front pair, the rear pair, or all four. */
export function drivenWheels(cls: Pick<CarClass, 'drive' | 'wheelbaseM' | 'weightFront' | 'widthM'>): WheelPlace[] {
  const front = cls.wheelbaseM * (1 - cls.weightFront)
  const rear = -cls.wheelbaseM * cls.weightFront
  const half = cls.widthM / 2
  const axles = cls.drive === 'fwd' ? [front] : cls.drive === 'rwd' ? [rear] : [front, rear]
  return axles.flatMap((alongM) => [
    { alongM, acrossM: -half },
    { alongM, acrossM: half },
  ])
}

interface Fleck {
  shape: Phaser.GameObjects.Rectangle
  vx: number
  vy: number
  /** Seconds left, and the whole life it was given. */
  leftS: number
  lifeS: number
}

export class SurfaceFx {
  private readonly flecks: Fleck[] = []
  /** The pool is used round and round: the next fleck thrown takes the place of the oldest. */
  private next = 0
  /** Flecks owed to each car: the part of its rate not yet thrown. */
  private readonly owed: number[]
  /** Its own small sequence of numbers, so that the same drive throws the same flecks. Looks only. */
  private seed = 0x2f6e2b1

  constructor(
    scene: Phaser.Scene,
    private readonly view: WorldView,
    /** For each car, where its driven wheels are. */
    private readonly wheels: ReadonlyArray<readonly WheelPlace[]>,
  ) {
    for (let i = 0; i < POOL_SIZE; i++) {
      const size = FLECK_SIZES_PX[i % FLECK_SIZES_PX.length]
      const shape = scene.add
        .rectangle(0, 0, size, size, GRASS_FLECK_COLORS[i % GRASS_FLECK_COLORS.length])
        .setDepth(DEPTH.cars - 2)
        .setVisible(false)
      this.flecks.push({ shape, vx: 0, vy: 0, leftS: 0, lifeS: 1 })
    }
    this.owed = wheels.map(() => 0)
  }

  /** How many flecks are in the air now. */
  alive(): number {
    return this.flecks.reduce((count, fleck) => count + (fleck.leftS > 0 ? 1 : 0), 0)
  }

  /**
   * Moves the flecks on by `dtS` and throws new ones from every car whose bog rose between the sim's last two
   * snapshots. `cars` are the cars as drawn on this frame.
   */
  update(dtS: number, cars: readonly RenderCar[], before: readonly CarSnapshot[], now: readonly CarSnapshot[]): void {
    for (const fleck of this.flecks) {
      if (fleck.leftS <= 0) continue
      fleck.leftS -= dtS
      if (fleck.leftS <= 0) {
        fleck.shape.setVisible(false)
        continue
      }
      const keep = Math.max(0, 1 - SLOWING_PER_S * dtS)
      fleck.vx *= keep
      fleck.vy *= keep
      fleck.shape.setPosition(fleck.shape.x + fleck.vx * dtS, fleck.shape.y + fleck.vy * dtS)
      // Gone by fading over the last third of its life.
      fleck.shape.setAlpha(Math.min(1, (3 * fleck.leftS) / fleck.lifeS))
    }

    for (const car of cars) {
      const wheels = this.wheels[car.id]
      const current = now[car.id]
      if (wheels === undefined || wheels.length === 0 || current === undefined) continue
      const rate = fleckRate({ bogBefore: (before[car.id] ?? current).bog, bogNow: current.bog, state: current.state, speedMS: current.speedMS })
      if (rate === 0) {
        this.owed[car.id] = 0
        continue
      }
      this.owed[car.id] += rate * dtS
      while (this.owed[car.id] >= 1) {
        this.owed[car.id] -= 1
        this.throwFrom(car, wheels[Math.floor(this.random() * wheels.length)], current.speedMS < 0)
      }
    }
  }

  private throwFrom(car: RenderCar, wheel: WheelPlace, reversing: boolean): void {
    const cos = Math.cos(car.angle)
    const sin = Math.sin(car.angle)
    const x = this.view.originX + (car.x + cos * wheel.alongM - sin * wheel.acrossM) * this.view.pxPerM
    const y = this.view.originY + (car.y + sin * wheel.alongM + cos * wheel.acrossM) * this.view.pxPerM
    // Back the way the wheels are pushing: behind the car, or ahead of it when it is backing out.
    const away = car.angle + (reversing ? 0 : Math.PI) + (this.random() * 2 - 1) * SPREAD_RAD
    const speed = THROW_PX_S * (1 + this.random())
    const fleck = this.flecks[this.next]
    this.next = (this.next + 1) % this.flecks.length
    fleck.lifeS = LIFE_S * (1 + this.random())
    fleck.leftS = fleck.lifeS
    fleck.vx = Math.cos(away) * speed
    fleck.vy = Math.sin(away) * speed
    fleck.shape.setPosition(Math.round(x), Math.round(y)).setAlpha(1).setVisible(true)
  }

  /** The next number of the sequence, 0 up to 1. */
  private random(): number {
    this.seed = (Math.imul(this.seed, 1664525) + 1013904223) >>> 0
    return this.seed / 0x100000000
  }

  destroy(): void {
    for (const fleck of this.flecks) fleck.shape.destroy()
    this.flecks.length = 0
  }
}
