/** The engine's own generator (mulberry32): commentary variety never touches the session's. */
export interface CommentaryRng {
  /** 0 up to but not including 1. */
  next(): number
  /** 0 up to but not including `n`. */
  int(n: number): number
}

export function createCommentaryRng(seed: number): CommentaryRng {
  let state = seed >>> 0
  const next = (): number => {
    state = (state + 0x6d2b79f5) >>> 0
    let t = state
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
  return { next, int: (n) => Math.floor(next() * n) }
}
