import Phaser from 'phaser'
import { LOGICAL_HEIGHT, LOGICAL_WIDTH } from '../config'
import { keyLabel } from '../input/bindings'
import { onCode, onNav, type NavKey } from '../input/keys'
import { saves } from '../persistence'
import { RACE_DAY_KEY, RaceDayController } from '../raceday/RaceDayController'
import { MenuList, Panel, THEME, setTextIfChanged, text, type HasReadout, type ScreenReadout } from '../ui'
import type { RaceSceneData } from './RaceScene'

/** What the race scene hands the pause overlay when it launches it: how to start the same session again. */
export interface PauseSceneData {
  restart: RaceSceneData
}

const ITEMS = [
  { id: 'resume', label: 'RESUME' },
  { id: 'restart', label: 'RESTART' },
  { id: 'garage', label: 'GARAGE' },
  { id: 'options', label: 'OPTIONS' },
  { id: 'title', label: 'MAIN MENU' },
]
/** During an event the car cannot change, so the garage is not offered (F-405). */
const EVENT_ITEMS = ITEMS.filter((item) => item.id !== 'garage')
const PANEL_WIDTH = 760
const PANEL_HEIGHT = 700

/**
 * The pause overlay, launched on top of the race scene, which stops with it: Resume, Restart (the same session
 * again), Garage, Options (F-801: the options screen opens over this one, and closing it brings this one back, the race
 * still paused) and Main menu (the title screen). Esc or the pause key (P unless the player moved it) resumes. During a
 * race-day event there is no Garage, and Main menu keeps the event as it stood at the last session boundary: the session
 * left part-way is driven again from its start (F-405).
 */
export class PauseScene extends Phaser.Scene implements HasReadout {
  private menu: MenuList | null = null
  private panel: Panel | null = null
  private parts: Phaser.GameObjects.GameObject[] = []
  /** The line that says which keys resume: the pause key is the player's to move (F-801). */
  private hint: Phaser.GameObjects.BitmapText | null = null
  private releases: Array<() => void> = []
  private restart: RaceSceneData = {}
  private handled = 0

  constructor() {
    super('Pause')
  }

  init(data: Partial<PauseSceneData>): void {
    this.restart = data.restart ?? {}
  }

  create(): void {
    this.handled = 0
    const cx = LOGICAL_WIDTH / 2
    const rect = { x: cx - PANEL_WIDTH / 2, y: Math.round((LOGICAL_HEIGHT - PANEL_HEIGHT) / 2), w: PANEL_WIDTH, h: PANEL_HEIGHT }
    this.parts.push(this.add.rectangle(0, 0, LOGICAL_WIDTH, LOGICAL_HEIGHT, THEME.colours.shade, 0.55).setOrigin(0, 0))
    this.panel = new Panel(this, rect)
    this.parts.push(text(this, { x: cx, y: rect.y + 40 }, 'PAUSED', 'huge').setOrigin(0.5, 0).setTint(THEME.colours.accent))
    const inEvent = this.registry.get(RACE_DAY_KEY) instanceof RaceDayController
    this.menu = new MenuList(this, { x: cx, y: rect.y + 210 }, inEvent ? EVENT_ITEMS : ITEMS, { size: 'large', anchor: 'centre', pitch: 76 })
    this.menu.onConfirm((id) => this.choose(id))
    this.hint = text(this, { x: cx, y: rect.y + rect.h - 72 }, '', 'small').setOrigin(0.5, 0).setTint(THEME.colours.textDim)
    this.parts.push(this.hint)

    this.listen()
    // Back from the options (they paused this screen): listen afresh, so that the key that closed them is not taken as one for this screen.
    this.events.on(Phaser.Scenes.Events.RESUME, this.listen, this)
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, this.dispose, this)
  }

  /** Starts listening for the menu keys and the pause key. */
  private listen = (): void => {
    this.stopListening()
    const keyboard = this.input.keyboard
    if (keyboard === null) throw new Error('PauseScene: the keyboard plugin is not available')
    const { pause } = saves.read().settings.bindings
    this.releases = [onNav(this, (key) => this.onKey(key)), onCode(keyboard, pause, () => this.choose('resume'))]
    if (this.hint !== null) setTextIfChanged(this.hint, `ESC OR ${keyLabel(pause)} TO RESUME`)
  }

  readout(): ScreenReadout {
    return { focus: this.menu?.focus ?? null, values: { handled: this.handled } }
  }

  private onKey(key: NavKey): void {
    this.handled++
    if (key === 'back') this.choose('resume')
    else this.menu?.handle(key)
  }

  /** Does what the item says. The overlay stops listening first, so a second press before the next frame does nothing. */
  private choose(id: string): void {
    if (this.releases.length === 0) return
    this.stopListening()
    switch (id) {
      case 'resume':
        this.scene.stop()
        this.scene.resume('Race')
        return
      case 'restart':
        this.scene.start('Race', this.restart)
        return
      case 'garage':
        this.scene.stop('Race')
        this.scene.start('Garage')
        return
      case 'options':
        this.scene.launch('Options', { from: 'pause' })
        this.scene.pause()
        return
      case 'title':
        this.scene.stop('Race')
        this.scene.start('Title')
        return
    }
  }

  private stopListening(): void {
    for (const off of this.releases) off()
    this.releases = []
  }

  private dispose(): void {
    this.events.off(Phaser.Scenes.Events.RESUME, this.listen, this)
    this.stopListening()
    this.menu?.destroy()
    this.menu = null
    this.panel?.destroy()
    this.panel = null
    for (const part of this.parts) part.destroy()
    this.parts = []
    this.hint = null
  }
}
