import { truncate } from './layout'
import { THEME } from './theme'

// The words and numbers of the options screen (F-801), pure so that they are tested without an engine: the volume
// steps, how a voice is named in a short line, and how a row of the screen is laid out on the font's character grid.

/** The volume steps: 0 to 100 % in tens. The saved defaults (0.8, 0.8, 1) are on them. */
export const VOLUME_STEPS: readonly number[] = Array.from({ length: 11 }, (_, i) => i / 10)

/** A level as the screen says it: 80%. */
export const volumeLabel = (level: number): string => `${Math.round(level * 100)}%`

/** The step nearest a level, for a saved value that is between two (a hand-edited save). */
export function nearestStep(level: number): number {
  return VOLUME_STEPS.reduce((best, step) => (Math.abs(step - level) < Math.abs(best - level) ? step : best), 0)
}

/** The options of a volume row. */
export const volumeOptions = (): Array<{ value: number; label: string }> => VOLUME_STEPS.map((step) => ({ value: step, label: volumeLabel(step) }))

/** How many characters of a voice's name the picker shows. */
export const VOICE_CHARS = 26

/** The shorter names of the regions voices are listed under. */
const REGIONS: Readonly<Record<string, string>> = {
  'united states': 'US',
  'united kingdom': 'UK',
  australia: 'AU',
  india: 'IN',
  ireland: 'IE',
  'south africa': 'ZA',
  canada: 'CA',
  'new zealand': 'NZ',
}

/** The characters of the pixel font: printable ASCII and the accented letters it has. */
const FONT_LETTERS = /^[ -~¡°³·¿À-ÏÑ-ÖÙ-Ýß-ïñ-öù-ýÿ–—‘’“”…×]$/

/**
 * A voice's name in the picker's few characters, in capitals and the font's letters. Microsoft's prefix, "Online" and
 * "(Natural)" go; the region a system tags a voice with — "Eddy (English (United Kingdom))", "Microsoft Guy Online (Natural)
 * - English (United Kingdom)" — becomes a short tag: "EDDY (UK)", "GUY (UK)". Anything else is shown as it is, cut with an ellipsis.
 */
export function voiceLabel(name: string): string {
  const { base, region } = voiceParts(name)
  const tag = region === null ? '' : ` (${REGIONS[region.toLowerCase()] ?? region.toUpperCase()})`
  return truncate(inFont(`${base}${tag}`), VOICE_CHARS)
}

/** The capitals of `words` in the font's letters, a question mark for one it does not have. */
const inFont = (words: string): string =>
  words
    .toUpperCase()
    .split('')
    .map((char) => (FONT_LETTERS.test(char) ? char : '?'))
    .join('')

/** A voice's own name, and the region the system tags it with (null for none). */
function voiceParts(name: string): { base: string; region: string | null } {
  let base = name.replace(/^Microsoft\s+/i, '')
  let region: string | null = null
  const dashed = / - English \((.+)\)$/i.exec(base)
  if (dashed !== null) {
    region = dashed[1] ?? null
    base = base.slice(0, dashed.index)
  }
  const nested = /\s*\(English \((.+)\)\)$/i.exec(base)
  if (nested !== null) {
    region = nested[1] ?? null
    base = base.slice(0, nested.index)
  }
  base = base
    .replace(/\s*\(Natural\)/i, '')
    .replace(/\s+Online$/i, '')
    .trim()
  return { base, region }
}

/** The picker's first choice: the game picks (F-708). */
export const AUTO_VOICE = 'AUTO'

/**
 * AUTO as the picker shows it (F-816): with the voice the game would choose on this system, by its own name without the
 * region — "AUTO (EDDY)" — cut to fit the picker's characters with its bracket kept; plain AUTO where it would choose none.
 */
export function autoLabel(name: string | null): string {
  if (name === null) return AUTO_VOICE
  const room = VOICE_CHARS - `${AUTO_VOICE} ()`.length
  return `${AUTO_VOICE} (${truncate(inFont(voiceParts(name).base), room).replace(/\s+…$/, '…')})`
}

/**
 * The options of a voice picker: AUTO (with `auto`, the voice it stands for, when there is one), then the voices by name.
 * Two voices that come out with one label are told apart by a number. The value is the voice's own name, which is what
 * the save keeps.
 */
export function voiceOptions(names: readonly string[], auto: string | null = null): Array<{ value: string | null; label: string }> {
  const used = new Map<string, number>()
  const options: Array<{ value: string | null; label: string }> = [{ value: null, label: autoLabel(auto) }]
  for (const name of names) {
    const label = voiceLabel(name)
    const times = (used.get(label) ?? 0) + 1
    used.set(label, times)
    options.push({ value: name, label: times === 1 ? label : truncate(`${label} ${times}`, VOICE_CHARS) })
  }
  return options
}

/** The column widths a screen lays its rows out with, in characters. */
export interface RowColumns {
  label: number
  value: number
}

/** `▶ LABEL      ◀ value ▶`: a row with a fixed list of choices, as `Selector` draws one. */
export function choiceLine(focused: boolean, label: string, value: string, columns: RowColumns): string {
  const cursor = focused ? THEME.cursorGlyph : ' '
  return `${cursor} ${truncate(label, columns.label).padEnd(columns.label)} ${THEME.arrowLeft} ${truncate(value, columns.value).padEnd(columns.value)} ${THEME.arrowRight}`
}

/** `▶ LABEL      value`: a row whose value is shown and not stepped (a key, a message). */
export function valueLine(focused: boolean, label: string, value: string, columns: RowColumns): string {
  const cursor = focused ? THEME.cursorGlyph : ' '
  return `${cursor} ${truncate(label, columns.label).padEnd(columns.label)} ${truncate(value, columns.value + 4)}`
}

/** `▶ LABEL`: a row that is a button. */
export const buttonLine = (focused: boolean, label: string): string => `${focused ? THEME.cursorGlyph : ' '} ${label}`
