import Phaser from 'phaser'
import { saves } from '../persistence'
import { ACTIONS, captureCodeOf, type Bindings } from './bindings'
import { trackKeys, type HeldKeyTracker } from './keys'
import type { HeldKeys } from './keys-to-input'

/** The arrow keys are always captured, so that the browser does not scroll or move focus while someone drives or steers a menu. */
const ARROW_KEY_CODES = [Phaser.Input.Keyboard.KeyCodes.UP, Phaser.Input.Keyboard.KeyCodes.DOWN, Phaser.Input.Keyboard.KeyCodes.LEFT, Phaser.Input.Keyboard.KeyCodes.RIGHT]

export interface KeyboardOptions {
  /** The keys to read; left out, the saved bindings (F-801). */
  bindings?: Bindings
}

/**
 * The driving keys, read by polling (AGENTS.md, Phaser rule 2): `held()` says which are down right now, by the bindings
 * in the settings (F-801). Keys are tracked by their `KeyboardEvent.code` through the guarded tracker in `keys.ts`.
 * Losing the window's focus or the tab's visibility, or the scene being paused and resumed (a paused scene hears no key
 * events, so a key let go meanwhile is never heard), releases every key at once, so a car cannot keep its throttle
 * open because the key-up went elsewhere; a key still held after that is counted again with its next repeat.
 */
export class Keyboard {
  private readonly tracker: HeldKeyTracker
  private readonly bindings: Bindings
  private readonly captured: number[]
  private disposed = false

  constructor(
    private readonly scene: Phaser.Scene,
    private readonly plugin: Phaser.Input.Keyboard.KeyboardPlugin,
    options: KeyboardOptions = {},
  ) {
    const { settings } = saves.read()
    this.bindings = options.bindings ?? settings.bindings
    // The arrow keys, and any other bound key that the page would act on (space scrolls it).
    this.captured = ACTIONS.flatMap((action) => captureCodeOf(this.bindings[action]) ?? [])
    plugin.addCapture([...ARROW_KEY_CODES, ...this.captured])
    this.tracker = trackKeys(plugin)
    this.scene.game.events.on(Phaser.Core.Events.BLUR, this.reset, this)
    this.scene.game.events.on(Phaser.Core.Events.HIDDEN, this.reset, this)
    this.scene.events.on(Phaser.Scenes.Events.RESUME, this.reset, this)
  }

  /** Which driving keys are down now. */
  held(): HeldKeys {
    const { bindings, tracker } = this
    return {
      up: tracker.isDown(bindings.throttle),
      down: tracker.isDown(bindings.brake),
      left: tracker.isDown(bindings.left),
      right: tracker.isDown(bindings.right),
    }
  }

  /** Releases every key, as if the player had let go. */
  reset(): void {
    this.tracker.releaseAll()
  }

  destroy(): void {
    if (this.disposed) return
    this.disposed = true
    this.scene.game.events.off(Phaser.Core.Events.BLUR, this.reset, this)
    this.scene.game.events.off(Phaser.Core.Events.HIDDEN, this.reset, this)
    this.scene.events.off(Phaser.Scenes.Events.RESUME, this.reset, this)
    this.tracker.destroy()
    // The arrows stay captured (the menus are steered with them); a key bound for this race only does not.
    const extra = this.captured.filter((code) => !ARROW_KEY_CODES.includes(code))
    if (extra.length > 0) this.plugin.removeCapture(extra)
  }
}
