import type { LineTrigger } from './types'

// The fixed vocabularies a line library may use: triggers the engine produces, the conditions that gate a template,
// and the placeholders a text may hold. `validate.ts` checks a library against these; `candidates.ts` produces them.

export const PLACEHOLDERS = ['name', 'number', 'colour', 'lap', 'time', 'pos', 'other', 'otherNumber', 'sky', 'gap', 'bio'] as const
export type Placeholder = (typeof PLACEHOLDERS)[number]

/** Conditions about the session as a whole: true or false whoever the line is about. */
const SESSION_CONDITIONS = ['wet', 'dry', 'final', 'qualifying', 'last-minute', 'duel'] as const
/** Conditions about the car or cars a line is about. */
const CAR_CONDITIONS = ['player', 'leader', 'backmarker', 'close'] as const

/**
 * The player's place in the event's classification, on the podium (F-709): exactly one holds for the event-result
 * moment. Fourth is just off the podium; fifth and below are further back.
 */
export const EVENT_PLACE_CONDITIONS = ['event-won', 'event-second', 'event-third', 'event-fourth', 'event-further-back'] as const
export type EventPlaceCondition = (typeof EVENT_PLACE_CONDITIONS)[number]

/** The place condition that holds for the player's place in the event, 1 first. */
export function eventPlaceCondition(place: number): EventPlaceCondition {
  return EVENT_PLACE_CONDITIONS[Math.min(Math.max(place, 1), EVENT_PLACE_CONDITIONS.length) - 1] ?? 'event-further-back'
}

export const CONDITIONS = [
  ...SESSION_CONDITIONS,
  ...CAR_CONDITIONS,
  ...EVENT_PLACE_CONDITIONS,
  // lap
  'personal-best',
  'session-best',
  'first-lap',
  'milestone',
  // race-control
  'halfway',
  // contact (what the car met)
  'car',
  'wall',
  'marker',
  'marshal',
  // flip
  'kerb',
  'impact',
  // stuck
  'grass',
  'wedged',
  // marshals
  'distracted',
  'long-wait',
  // penalty (why)
  'off-limits',
  'cut',
  'contact',
] as const
export type Condition = (typeof CONDITIONS)[number]

/** The triggers this engine produces candidates for. Every other event is the official's, or too small to remark on. */
export const ENGINE_TRIGGERS = [
  'phase',
  'race-control',
  'lap',
  'position',
  'lead-change',
  'contact',
  'spin',
  'off-track',
  'kerb-hop',
  'flip',
  'stuck',
  'marshal-distracted',
  'marshal-dispatched',
  'car-righted',
  'sky',
  'gust',
  'puddle',
  'aquaplane',
  'penalty',
  'car-finished',
  'session-result',
  'event-result',
  'filler',
] as const satisfies readonly LineTrigger[]
export type EngineTrigger = (typeof ENGINE_TRIGGERS)[number]

const SUBJECTLESS: ReadonlySet<LineTrigger> = new Set(['sky', 'gust', 'puddle'])

const EXTRA_CONDITIONS: Partial<Record<LineTrigger, readonly Condition[]>> = {
  'race-control': ['halfway'],
  lap: ['personal-best', 'session-best', 'first-lap', 'milestone'],
  contact: ['car', 'wall', 'marker', 'marshal'],
  flip: ['kerb', 'impact'],
  stuck: ['grass', 'wedged'],
  'marshal-distracted': ['distracted'],
  'marshal-dispatched': ['distracted', 'long-wait'],
  'car-righted': ['distracted', 'long-wait'],
  penalty: ['off-limits', 'cut', 'contact'],
}

/**
 * The event result (F-709) is a moment the context gives, not an event: it is about the player, has no snapshot behind
 * it, and so has only the kind of session, the duel, the player and the place.
 */
const EVENT_RESULT_CONDITIONS: readonly Condition[] = ['final', 'qualifying', 'duel', 'player', ...EVENT_PLACE_CONDITIONS]
const EVENT_RESULT_PLACEHOLDERS: readonly Placeholder[] = ['name', 'number', 'colour', 'pos']

/** The conditions that can ever hold for a trigger's candidates. */
export function allowedConditions(trigger: LineTrigger): ReadonlySet<string> {
  if (trigger === 'event-result') return new Set(EVENT_RESULT_CONDITIONS)
  const base: string[] = [...SESSION_CONDITIONS]
  if (!SUBJECTLESS.has(trigger)) base.push(...CAR_CONDITIONS)
  return new Set([...base, ...(EXTRA_CONDITIONS[trigger] ?? [])])
}

const EXTRA_PLACEHOLDERS: Partial<Record<LineTrigger, readonly Placeholder[]>> = {
  lap: ['time'],
  position: ['other', 'otherNumber'],
  'lead-change': ['other', 'otherNumber'],
  contact: ['other', 'otherNumber'],
  'car-finished': ['time'],
  'session-result': ['time', 'other', 'otherNumber'],
  filler: ['time', 'other', 'otherNumber'],
}

/** The placeholders that can ever be filled for a trigger's candidates. */
export function allowedPlaceholders(trigger: LineTrigger): ReadonlySet<Placeholder> {
  if (trigger === 'event-result') return new Set(EVENT_RESULT_PLACEHOLDERS)
  if (SUBJECTLESS.has(trigger)) return new Set<Placeholder>(['sky'])
  return new Set<Placeholder>(['name', 'number', 'colour', 'lap', 'pos', 'sky', 'gap', 'bio', ...(EXTRA_PLACEHOLDERS[trigger] ?? [])])
}
