import type Phaser from 'phaser'
import { AudioMixer } from './AudioMixer'

export { AudioMixer, DEFAULT_VOLUMES, type AudioBackend, type Volumes } from './AudioMixer'
export { Crowd } from './Crowd'
export { RaceAudio, type RaceAudioOptions } from './RaceAudio'
export { zzfxBackend } from './zzfx-backend'

/** The registry key the mixer is kept under, so that any scene can reach it. */
export const MIXER_KEY = 'audio-mixer'

/** The game's mixer (made by the boot scene), or null in a game that was started without one. */
export function mixerOf(registry: Phaser.Data.DataManager): AudioMixer | null {
  const mixer: unknown = registry.get(MIXER_KEY)
  return mixer instanceof AudioMixer ? mixer : null
}
