import type Phaser from 'phaser'
import type { CarId, SessionKind, SessionPhase, SessionSnapshot, Tick } from '@sim'
import { text } from '../ui/text'
import { THEME, charWidth, type TextSize } from '../ui/theme'
import { DEPTH } from './depth'
import type { EventBus } from './EventBus'
import { saidByOfficial, startCallFor, startCallMessage, type HudMessage, type StartFlow } from './hud-messages'

// What the start says on screen (F-304): the numbers 10 down to 4 of the countdown and "GO" at the start, plain text
// with nothing behind it, in the middle of the screen. "DRIVERS GET READY" through the staging (F-607), and in a
// staggered start the number of each car as it is released and the wait for the player's own (F-514), are the
// official's, said in his bubble: this keeps them, for the HUD to hand him. What it knows of the start it learns from the sim's `phase` and `car-released` events; what
// it shows is decided by `startCallFor`.

const WHITE = THEME.colours.text
/** The words, in the title's yellow; the numbers stay white. */
const WORDS = THEME.colours.accent

/** A number or GO is huge. */
const sizeOf = (call: string): TextSize => (call === 'GO' || /^\d+$/.test(call) ? 'huge' : 'large')
const colourOf = (call: string): number => (/^\d+$/.test(call) ? WHITE : WORDS)

export class StartLights {
  private readonly words: Phaser.GameObjects.BitmapText
  private readonly release: Array<() => void> = []
  private readonly flow: StartFlow
  private shown: string | null = null
  /** The call the official says, as a message; null when none is being made. */
  private said: HudMessage | null = null

  /**
   * `centreX` and `top` place the call on the canvas. `playerId` is the car that gets "GO" and "WAIT"; `numbers` are
   * the cars' numbers by car id, for the calls of a staggered start. With no player a final still counts down and says
   * GO, and a heat still calls each car.
   */
  constructor(
    scene: Phaser.Scene,
    bus: EventBus,
    kind: SessionKind,
    private readonly playerId: CarId | null,
    private readonly numbers: readonly number[],
    private readonly centreX: number,
    private readonly top: number,
  ) {
    this.flow = { phase: 'staging', tick: 0, countdownTick: null, goTick: null, release: null, staggered: kind === 'qualifying' && playerId !== null, ownReleased: false }
    this.words = text(scene, { x: 0, y: 0 }, '', 'huge').setDepth(DEPTH.hud + 1).setVisible(false)
    this.release.push(
      bus.on('phase', (event) => this.onPhase(event.phase, event.tick, kind)),
      bus.on('car-released', (event) => {
        const own = this.playerId !== null && event.car === this.playerId
        this.flow.release = { tick: event.tick, number: this.numbers[event.car] ?? event.car + 1, own }
        if (own) this.flow.ownReleased = true
      }),
    )
  }

  private onPhase(phase: SessionPhase, tick: Tick, kind: SessionKind): void {
    if (phase === 'countdown') this.flow.countdownTick = tick
    // In a final everybody is released by the start tone; a heat is released car by car, and `car-released` says when.
    if (phase === 'running' && kind === 'final') this.flow.goTick = tick
  }

  /** The call at this snapshot, or null. Rewrites the text only when it is different from the last frame's. */
  update(snapshot: SessionSnapshot): void {
    this.flow.phase = snapshot.phase
    this.flow.tick = snapshot.tick
    const call = startCallFor(this.flow)
    if (call === this.shown) return
    this.shown = call
    this.said = startCallMessage(call)
    this.words.setVisible(call !== null && !saidByOfficial(call))
    if (call === null || saidByOfficial(call)) return
    const size = sizeOf(call)
    this.words.setText(call).setScale(THEME.sizes[size]).setTint(colourOf(call))
    this.words.setPosition(Math.round(this.centreX - (call.length * charWidth(size)) / 2), this.top)
  }

  /** The call on the middle of the screen now, for tests: null while the call is the official's. */
  call(): string | null {
    return this.shown !== null && saidByOfficial(this.shown) ? null : this.shown
  }

  /** The call the official is to say now, as a message (the same object for as long as it is the same call), or null. */
  officialCall(): HudMessage | null {
    return this.said
  }

  destroy(): void {
    for (const off of this.release) off()
    this.release.length = 0
    this.words.destroy()
  }
}
