import Phaser from 'phaser'
import type { CarClassId } from '@sim'
import { ROSTER } from '@content/roster'
import { animation } from '../assets/animation'
import { Crowd, mixerOf } from '../audio'
import { directionSet, manifestOf, queueAtlas, type AssetManifest, type Still } from '../assets/manifest'
import { LOGICAL_HEIGHT, LOGICAL_WIDTH } from '../config'
import { onNav, type NavKey } from '../input/keys'
import { NUMBER_TINT, SHADOW_OFFSET_PX, carSpriteName, numberSpriteName, shadowSpriteName } from '../race/CarView'
import { podiumItemSprite, podiumPoseSprite, podiumView, type OutfitItem, type PodiumPlace, type PodiumPose, type PodiumView } from '../race/event-tables'
import type { RaceDayFlowData, RaceDayController } from '../raceday/RaceDayController'
import { Panel, THEME, lineHeight, queueClassAtlas, text, wrapText, charsInPanel, type HasReadout, type Rect, type ScreenReadout } from '../ui'
import { Confetti } from '../ui/Confetti'
import { CLOSING_KEY, ClosingVoice, type Closing } from './ResultsScene'
import { drawTable, keyHint, tablePanelHeight, tablePanelWidth, type DrawnTable } from './SessionIntroScene'

const MARGIN = 96
const TOP = 168
const PANEL_GAP = 44
/** The width of one place of the podium, and the room between two. A place holds a name of 15 characters. */
const BLOCK_WIDTH = 330
const BLOCK_GAP = 20
/** The room between the rows of a place: its heading, its trophy, its car and its lines. */
const ROW_GAP = 16
const ORDINAL: Readonly<Record<number, string>> = { 1: '1ST', 2: '2ND', 3: '3RD' }
const LINE_PITCH = Math.round(lineHeight('body') * 1.4)
/** Where the places stand left to right: the winner in the middle, as on a real podium (a duel: second, then first). */
const STANDING_ORDER: readonly number[] = [2, 1, 3]
/**
 * How many screen pixels each art pixel of a person covers, by pose: a whole number, so that every art pixel is a block of
 * whole screen pixels. The winner is the largest, as the gold trophy they lift was the largest of the three (F-408, the
 * owner's sizes); second is two thirds of that and third half. The cups are drawn into the art of second and third
 * (F-506), so there is no separate trophy picture.
 */
const PERSON_PX: Readonly<Record<PodiumPose, number>> = { first: 6, suited: 6, second: 5, 'suited-second': 5, third: 4, 'suited-third': 4 }
/**
 * How many screen pixels each art pixel of the cell's height the room a place keeps for its person is. The winner's
 * figure is shown larger than that room and rises out of it over the heading's row, where only the middle of the row is
 * free (the heading's words are at its edges); second and third fill the room they keep, which is why the winner
 * stands highest and third lowest.
 */
const SLOT_PX: Readonly<Record<PodiumPose, number>> = { first: 4, suited: 4, second: 5, 'suited-second': 5, third: 4, 'suited-third': 4 }
/** Whole-number scale of a car on the podium: the sprites are 36 px long and there is no larger art (F-203). */
const CAR_SCALE = 6
/** The strip of track-grey a car stands on, as in the garage: the ground the car and its shadow are drawn for. */
const STAGE_HEIGHT = 144
/** The confetti falls behind everything else on the screen (F-802): over the background, between and around the places, never over them. */
const CONFETTI_DEPTH = -1
/** The name of the placeholder shown while the atlases download. */
const LOADING_NAME = 'loading'

/** The frames a person plays, and how many a second. */
interface Clip {
  frames: readonly string[]
  fps: number
}

/** What stands on one place of the podium, kept for the readout. */
interface Stand {
  place: number
  stage: Rect
  body: Phaser.GameObjects.Image
  shadow: Phaser.GameObjects.Image
  number: Phaser.GameObjects.Image
  /** The person on the place, in their pose, and the overlays they wear on it, in drawing order. */
  person: Phaser.GameObjects.Image
  pose: PodiumPose
  items: Array<{ item: OutfitItem; image: Phaser.GameObjects.Image; frames: readonly string[] }>
  play: Clip
}

/** The person on a place: the picture and the whole number of screen pixels each of its art pixels covers there, the moving frames, and the overlays they wear on it. */
interface Person {
  art: Still
  scale: number
  /** The height the place keeps for them, px. */
  slot: number
  play: Clip
  pose: PodiumPose
  items: Array<{ item: OutfitItem; frames: readonly string[] }>
}

/** The player's place in the event, 1 first, as the classification the podium shows has it (F-709); undefined if the player is not in it. */
function eventPlaceOf(view: PodiumView): number | undefined {
  const place = Number(view.table.rows[view.table.playerRow]?.['pos'])
  return Number.isInteger(place) && place >= 1 ? place : undefined
}

/** The person of a place as the manifest has them, in their car's colour and the outfit the event's seed gave them. */
function personOf(manifest: AssetManifest, place: PodiumPlace): Person {
  const pose = animation(manifest, podiumPoseSprite(place.pose, place.colour))
  const first = pose.frames[0]
  if (first === undefined) throw new Error(`PodiumScene: the picture of place ${place.place} has no frames`)
  const items = place.items.map((item) => {
    const overlay = animation(manifest, podiumItemSprite(item, place.pose))
    if (overlay.frames.length !== pose.frames.length) throw new Error(`PodiumScene: ${item} on the ${place.pose} pose has ${overlay.frames.length} frames, the pose ${pose.frames.length}`)
    return { item, frames: overlay.frames }
  })
  return {
    art: { atlas: pose.atlas, frame: first, size: pose.size, pivot: pose.pivot, scale: pose.scale },
    scale: PERSON_PX[place.pose],
    slot: pose.size.h * SLOT_PX[place.pose],
    play: { frames: pose.frames, fps: pose.fps },
    pose: place.pose,
    items,
  }
}

/** How tall a place is whose person has `personHeight` of room: the heading, the person, the car on its strip, the name and the points. */
const blockHeight = (personHeight: number): number =>
  2 * THEME.padding + lineHeight('large') + ROW_GAP + personHeight + ROW_GAP + STAGE_HEIGHT + ROW_GAP + LINE_PITCH + lineHeight('body')

/**
 * The end of a race day: the top three of the final classification on a podium (the top two in a duel), each with
 * their person (the winner lifting the gold cup; second with the silver cup at their side, smiling; third beside the bronze
 * one, not smiling; all three in racing suits, and none in a hat, in the class with a mandatory pit stop), dressed in the outfit the event's seed gave them, their car
 * as the race draws it, their driver and finals points; the whole classification beside it; and under both the TQ and
 * the fastest single lap of the event. A place is as tall as what stands on it, so the winner stands highest; each stands
 * on a podium step with a lip of its trophy's metal, and confetti falls behind them as the podium appears (F-802). Enter
 * returns to the main menu.
 */
export class PodiumScene extends Phaser.Scene implements HasReadout {
  private parts: Phaser.GameObjects.GameObject[] = []
  private panels: Panel[] = []
  private stands: Stand[] = []
  private drawn: DrawnTable | null = null
  private release: (() => void) | null = null
  private controller: RaceDayController | null = null
  private shown: PodiumView | null = null
  private handled = 0
  /** The commentator, saying how the final ended (F-703), then a word about the player's place in the event (F-709). */
  voice: ClosingVoice | null = null
  /** The confetti that falls once behind the podium as it appears (F-802); null before and after it. */
  confetti: Confetti | null = null
  /** The crowd that cheers once as the podium appears (F-712). Null where the game has no mixer, and before and after the podium. */
  crowd: Crowd | null = null

  constructor() {
    super('Podium')
  }

  init(data: Partial<RaceDayFlowData>): void {
    this.controller = data.controller ?? null
    this.handled = 0
    this.shown = null
  }

  /** Fetches what the podium shows and may not be loaded yet: the class's car atlas (an event resumed at its end) and the people's. */
  preload(): void {
    const controller = this.controller
    if (controller === null || controller.peek().kind !== 'podium') return
    const manifest = manifestOf(this)
    const cars = queueClassAtlas(this, controller.state.settings.carClass)
    const people = queueAtlas(this, manifest, 'people')
    if (cars || people) {
      text(this, { x: LOGICAL_WIDTH / 2, y: LOGICAL_HEIGHT / 2 }, 'LOADING', 'body').setOrigin(0.5).setTint(THEME.colours.textDim).setName(LOADING_NAME)
    }
  }

  create(): void {
    const controller = this.controller
    if (controller === null) throw new Error('PodiumScene: it was started without a race day')
    const step = controller.peek()
    if (step.kind !== 'podium') {
      this.scene.start(controller.nextScene(), { controller } satisfies RaceDayFlowData)
      return
    }
    this.children.getByName(LOADING_NAME)?.destroy()
    const manifest = manifestOf(this)
    const carClass = controller.state.settings.carClass
    const view = podiumView(controller.state, ROSTER)
    this.shown = view
    // The podium is shown: the event is over, and its classification is the last result (F-405).
    controller.finish()

    this.cameras.main.setBackgroundColor(THEME.colours.background)
    this.confetti = new Confetti(this, controller.state.settings.seed, LOGICAL_WIDTH, CONFETTI_DEPTH)
    this.parts.push(text(this, { x: MARGIN, y: 48 }, 'PODIUM', 'large').setTint(THEME.colours.accent))
    this.parts.push(text(this, { x: MARGIN, y: 116 }, 'FINAL CLASSIFICATION', 'small').setTint(THEME.colours.textDim))
    this.parts.push(keyHint(this, 'ENTER MAIN MENU'))

    // The classification takes the right edge; the podium stands in the room to its left, ending on one floor.
    const tableRect: Rect = { x: LOGICAL_WIDTH - MARGIN - tablePanelWidth(view.table), y: TOP, w: tablePanelWidth(view.table), h: tablePanelHeight(view.table.rows.length) }
    const table = new Panel(this, tableRect, { title: 'CLASSIFICATION' })
    this.panels.push(table)
    this.drawn = drawTable(this, { x: table.inner.x, y: table.inner.y }, view.table)

    const places = STANDING_ORDER.flatMap((place) => view.places.filter((one) => one.place === place))
    const people = places.map((place) => personOf(manifest, place))
    const heights = people.map(({ slot }) => blockHeight(slot))
    const floor = TOP + Math.max(...heights)
    const groupWidth = places.length * BLOCK_WIDTH + (places.length - 1) * BLOCK_GAP
    const room = tableRect.x - PANEL_GAP - MARGIN
    const left = MARGIN + Math.max(0, Math.round((room - groupWidth) / 2))
    places.forEach((place, i) => {
      const person = people[i]
      const height = heights[i]
      if (person === undefined || height === undefined) return
      this.block(place, { x: left + i * (BLOCK_WIDTH + BLOCK_GAP), y: floor - height, w: BLOCK_WIDTH, h: height }, manifest, carClass, person)
    })

    // Under both: what the event gave besides the places.
    const eventTop = Math.max(floor, tableRect.y + tableRect.h) + PANEL_GAP
    const facts = [view.tq, view.fastest].filter((line): line is string => line !== null)
    const wide = LOGICAL_WIDTH - 2 * MARGIN
    const chars = charsInPanel(wide, 'body')
    const lines = facts.flatMap((line) => (line.length <= chars ? [line] : wrapText(line, chars)))
    const eventPanel = new Panel(this, { x: MARGIN, y: eventTop, w: wide, h: 2 * THEME.padding + lineHeight('small') + 16 + Math.max(1, lines.length) * LINE_PITCH }, { title: 'THE EVENT' })
    this.panels.push(eventPanel)
    lines.forEach((line, i) => this.parts.push(text(this, { x: eventPanel.inner.x, y: eventPanel.inner.y + i * LINE_PITCH }, line, 'body').setTint(THEME.colours.text)))

    this.release = onNav(this, (key) => this.onKey(key))
    const closing: unknown = this.registry.get(CLOSING_KEY)
    const windowPlace = { left: tableRect.x, top: tableRect.y + tableRect.h + PANEL_GAP, right: tableRect.x + tableRect.w }
    this.voice = ClosingVoice.mount(this, (closing as Closing | undefined) ?? null, 3, windowPlace, eventPlaceOf(view))
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, this.dispose, this)
    // The event's podium appears and the crowd cheers, once (F-712): on its own, through the mixer's effects bus, so that the mute and the effects slider reach it.
    const mixer = mixerOf(this.registry)
    if (mixer !== null) {
      this.crowd = new Crowd(mixer)
      this.crowd.cheer()
    }
  }

  /**
   * One place of the podium: a panel standing on the floor with, from the top, the place and the car's number, the
   * person with what they wear, the car on a strip of track, the driver and the points.
   */
  private block(place: PodiumPlace, rect: Rect, manifest: AssetManifest, carClass: CarClassId, person: Person): void {
    const panel = new Panel(this, rect, { skin: THEME.skin.step[place.place as 1 | 2 | 3] })
    this.panels.push(panel)
    const { x, y, w } = panel.inner
    const centre = x + Math.round(w / 2)
    const heading = lineHeight('large')
    this.parts.push(text(this, { x, y }, ORDINAL[place.place] ?? String(place.place), 'large').setTint(place.place === 1 ? THEME.colours.accent : THEME.colours.text))
    this.parts.push(text(this, { x: x + w, y: y + heading - lineHeight('body') }, `NO ${place.number}`, 'body').setOrigin(1, 0).setTint(THEME.colours.textDim))

    // The person stands with their feet on the bottom of the room the place keeps for them; what they wear is the same picture's cell, drawn over them: glasses, sunglasses, hat.
    const personTop = y + heading + ROW_GAP
    const personHeight = person.slot
    const at = { x: centre, y: personTop + Math.round(personHeight * person.art.pivot.y) }
    const figure = this.add.image(at.x, at.y, person.art.atlas, person.art.frame).setOrigin(person.art.pivot.x, person.art.pivot.y).setScale(person.scale)
    const worn = person.items.map(({ item, frames }) => ({
      item,
      frames,
      image: this.add.image(at.x, at.y, person.art.atlas, frames[0]).setOrigin(person.art.pivot.x, person.art.pivot.y).setScale(person.scale),
    }))

    // The car as the race draws it: the shadow, the body in the driver's colour, the number on it. It faces right and never turns.
    const stage: Rect = { x, y: personTop + personHeight + ROW_GAP, w, h: STAGE_HEIGHT }
    const cy = stage.y + Math.round(stage.h / 2)
    const body = directionSet(manifest, carSpriteName(carClass, place.colour))
    const shadow = directionSet(manifest, shadowSpriteName(carClass))
    const number = directionSet(manifest, numberSpriteName(carClass, place.number))
    const ground = this.add.rectangle(stage.x, stage.y, stage.w, stage.h, THEME.colours.stage).setOrigin(0, 0)
    const shadowImage = this.add
      .image(centre + SHADOW_OFFSET_PX.x * CAR_SCALE, cy + SHADOW_OFFSET_PX.y * CAR_SCALE, shadow.atlas, shadow.frames[0])
      .setOrigin(shadow.pivot.x, shadow.pivot.y)
      .setScale(shadow.scale * CAR_SCALE)
    const bodyImage = this.add.image(centre, cy, body.atlas, body.frames[0]).setOrigin(body.pivot.x, body.pivot.y).setScale(body.scale * CAR_SCALE)
    const numberImage = this.add
      .image(centre, cy, number.atlas, number.frames[0])
      .setOrigin(number.pivot.x, number.pivot.y)
      .setScale(number.scale * CAR_SCALE)
      .setTint(NUMBER_TINT[place.colour])
    this.parts.push(figure, ...worn.map(({ image }) => image), ground, shadowImage, bodyImage, numberImage)
    this.stands.push({ place: place.place, stage, body: bodyImage, shadow: shadowImage, number: numberImage, person: figure, pose: person.pose, items: worn, play: person.play })

    const lines = stage.y + stage.h + ROW_GAP
    this.parts.push(text(this, { x, y: lines }, place.name, 'body').setTint(place.isPlayer ? THEME.colours.accent : THEME.colours.text))
    this.parts.push(text(this, { x, y: lines + LINE_PITCH }, `${place.points} ${place.points === 1 ? 'POINT' : 'POINTS'}`, 'body').setTint(THEME.colours.textDim))
  }

  /** The people move: the winner lifts the cup, second and third shift where they stand. The pose's frames play on the frame clock's time, over and over, and what they wear is on the same frame of its own. */
  update(time: number): void {
    this.voice?.update(time)
    this.confetti?.update(time)
    for (const { person, items, play } of this.stands) {
      if (play.frames.length === 0) continue
      const index = Math.floor((time / 1000) * play.fps) % play.frames.length
      const frame = play.frames[index]
      if (frame !== undefined) person.setFrame(frame)
      for (const { image, frames } of items) {
        const worn = frames[index]
        if (worn !== undefined) image.setFrame(worn)
      }
    }
  }

  readout(): ScreenReadout {
    const view = this.shown
    return {
      focus: 'continue',
      values: {
        handled: this.handled,
        places: view?.places.length ?? 0,
        podium: view?.places.map((place) => place.number).join(',') ?? '',
        classified: view?.table.rows.map((row) => row['no']).join(',') ?? '',
        tq: view?.tq ?? '',
        fastest: view?.fastest ?? '',
        playerRow: view?.table.playerRow ?? -1,
        confetti: this.confetti?.falling ?? 0,
        ...this.standFacts(),
      },
    }
  }

  /**
   * What stands on each place, read back from the pictures themselves and named `place<n>...`: the car's atlas and
   * frame, where its centre is and how many screen pixels an art pixel of it covers, its number and shadow, the strip
   * it stands on, and the person with the box their cell covers, their pose and what they wear.
   */
  private standFacts(): Record<string, string | number> {
    const facts: Record<string, string | number> = {}
    for (const { place, stage, body, shadow, number, person, pose, items } of this.stands) {
      const cell = person.getBounds()
      const named: Record<string, string | number> = {
        CarAtlas: body.texture.key,
        CarFrame: body.frame.name,
        CarScale: body.scaleX,
        CarX: body.x,
        CarY: body.y,
        NumberFrame: number.visible ? number.frame.name : '',
        NumberTint: number.tintTopLeft,
        ShadowFrame: shadow.visible ? shadow.frame.name : '',
        StageX: stage.x,
        StageY: stage.y,
        StageW: stage.w,
        StageH: stage.h,
        PersonPose: pose,
        PersonAtlas: person.texture.key,
        PersonFrame: person.frame.name,
        PersonScale: person.scaleX,
        PersonX: cell.x,
        PersonY: cell.y,
        PersonW: cell.width,
        PersonH: cell.height,
        Items: items.map(({ item }) => item).join(','),
        ItemFrames: items.map(({ image }) => image.frame.name).join(','),
        ItemScales: items.map(({ image }) => image.scaleX).join(','),
        ItemBoxes: items.map(({ image }) => { const box = image.getBounds(); return `${box.x},${box.y},${box.width},${box.height}` }).join(';'),
      }
      for (const [fact, value] of Object.entries(named)) facts[`place${place}${fact}`] = value
    }
    return facts
  }

  private onKey(key: NavKey): void {
    this.handled++
    if (key !== 'confirm') return
    this.stopListening()
    this.scene.start('Title')
  }

  private stopListening(): void {
    this.release?.()
    this.release = null
  }

  private dispose(): void {
    this.stopListening()
    this.crowd?.dispose()
    this.crowd = null
    this.confetti?.destroy()
    this.confetti = null
    this.voice?.destroy()
    this.voice = null
    this.drawn?.destroy()
    this.drawn = null
    for (const panel of this.panels) panel.destroy()
    this.panels = []
    for (const part of this.parts) part.destroy()
    this.parts = []
    this.stands = []
    this.controller = null
    this.shown = null
  }
}
