import type { TrackData } from '@sim'
import cuencaRcFile from './cuenca-rc.json'

// A JSON module is typed loosely: a point is number[], a kind is string. The file is held to the format by the
// validator (`pnpm track:validate`) and the Cuenca RC scenarios in tests/sim/track/, so the one assertion here is safe.
export const cuencaRc = cuencaRcFile as unknown as TrackData

/** One track the game ships. `load` is how a tool or a screen asks for the data; every track is bundled, so it settles at once. */
export interface TrackEntry {
  id: string
  name: string
  load: () => Promise<TrackData>
}

/**
 * The tracks the game ships, in the order the selector lists them: the first is the default. To add one, import its
 * file above and add it to this list (guides/adding-a-track.md); `pnpm track:validate` and the all-tracks test then cover it.
 */
const SHIPPED: readonly TrackData[] = [cuencaRc]

export const TRACKS: ReadonlyArray<TrackEntry> = SHIPPED.map((data) => ({ id: data.id, name: data.name, load: () => Promise.resolve(data) }))

/** The same tracks by id, for the code that needs the data at once (the screens, the leaderboards). */
export const tracks: Readonly<Record<string, TrackData>> = Object.fromEntries(SHIPPED.map((data) => [data.id, data]))
