import type Phaser from 'phaser'
import type { Vec2 } from '@sim'
import type { NavKey } from '../input/keys'
import { Row } from './Row'
import { THEME, charWidth, lineHeight, type TextSize } from './theme'

export interface ButtonSpec {
  id: string
  label: string
}

/** Blank characters between two buttons. */
const BUTTON_GAP = 3

/** Buttons side by side: left and right move between them, Enter presses the one in focus. While the row itself is not focused no button shows a cursor. */
export class ButtonRow {
  private readonly rows: Row[] = []
  private readonly pressed: Array<(id: string) => void> = []
  private index = 0
  private focused = false

  constructor(
    scene: Phaser.Scene,
    pos: Vec2,
    private readonly buttons: readonly ButtonSpec[],
    private readonly size: TextSize = 'body',
  ) {
    let x = pos.x
    for (const button of buttons) {
      const chars = button.label.length + 2
      this.rows.push(new Row(scene, x, pos.y, chars * charWidth(size), size, `  ${button.label}`, { button: true }))
      x += (chars + BUTTON_GAP) * charWidth(size)
    }
    this.paint()
  }

  /** The id of the button that Enter would press. */
  get focusedButton(): string {
    return this.buttons[this.index]?.id ?? ''
  }

  /** The height of the row, for stacking. */
  get heightPx(): number {
    return lineHeight(this.size)
  }

  /** Calls `fn` with the id of the button Enter pressed. */
  onPress(fn: (id: string) => void): void {
    this.pressed.push(fn)
  }

  setFocused(focused: boolean): void {
    this.focused = focused
    this.paint()
  }

  /** Acts on a menu key; true if the buttons used it. */
  handle(key: NavKey): boolean {
    const count = this.buttons.length
    if (key === 'left' || key === 'right') {
      this.index = (this.index + (key === 'right' ? 1 : -1) + count) % count
      this.paint()
      return true
    }
    if (key === 'confirm') {
      for (const fn of this.pressed) fn(this.focusedButton)
      return true
    }
    return false
  }

  private paint(): void {
    this.buttons.forEach((button, i) => {
      const row = this.rows[i]
      const here = this.focused && i === this.index
      row?.setLabel(`${here ? THEME.cursorGlyph : ' '} ${button.label}`)
      row?.setTone(here ? 'focus' : 'normal')
    })
  }

  destroy(): void {
    for (const row of this.rows) row.destroy()
    this.rows.length = 0
    this.pressed.length = 0
  }
}
