import { browserStorage, clearSave, defaultSave, load, save, type SaveData } from './storage'

/** The part of the browser's storage the store uses. */
export type StoreStorage = Pick<Storage, 'getItem' | 'setItem' | 'removeItem'>

/**
 * The game's one copy of what it remembers: read from storage the first time it is asked, kept in memory, and written
 * through on every change. When the storage is blocked the copy still serves the visit (an event left for the title can
 * still be continued) and nothing outlasts it. `storage` is resolved on first use, so a store made before the page has
 * storage, or in Node with a fake, behaves.
 */
export interface SaveStore {
  read(): SaveData
  /** Replaces the copy with `change` of it and writes it; a change that returns the same object writes nothing. Returns the new copy. */
  update(change: (data: SaveData) => SaveData): SaveData
  /** Whether the latest write reached the storage. True before anything was written. */
  readonly persisted: boolean
  /** Forgets everything: the stored key is removed and the copy goes back to the defaults. */
  clear(): void
}

export function createStore(storage: StoreStorage | null | undefined = undefined): SaveStore {
  let current: SaveData | null = null
  let persisted = true
  const target = (): StoreStorage | null => (storage === undefined ? browserStorage() : storage)
  const store: SaveStore = {
    read() {
      current ??= load(target())
      return current
    },
    update(change) {
      const before = store.read()
      const next = change(before)
      if (next !== before) {
        current = next
        persisted = save(next, target())
      }
      return next
    },
    get persisted() {
      return persisted
    },
    clear() {
      current = defaultSave()
      persisted = clearSave(target())
    },
  }
  return store
}

/** The game's store, on the browser's local storage. */
export const saves: SaveStore = createStore()
