import Phaser from 'phaser'
import { cuencaRc } from '@content/tracks'
import { LOGICAL_WIDTH } from '../config'
import { onNav, onText, type NavKey, type TextKey } from '../input/keys'
import {
  BOARD_WORDS,
  CLASS_WORDS,
  DIRECTION_WORDS,
  DISCARD_CANCEL,
  DISCARD_CONFIRM,
  DISCARD_QUESTION,
  INITIALS_HEADING,
  INITIALS_HINT,
  INITIALS_KEYS,
  INITIALS_MAX,
  INITIALS_PANEL,
  canConfirm,
  initialsReduce,
  initialsStart,
  isRaceMinutes,
  offerWords,
  type BoardWhere,
  type EntryInfo,
  type InitialsKey,
  type InitialsState,
  type Offer,
} from '../leaderboard'
import { saves, withResultOnBoards } from '../persistence'
import { ConfirmDialog, Panel, THEME, charWidth, lineHeight, setTextIfChanged, text, type HasReadout, type ScreenReadout } from '../ui'
import type { LeaderboardInit } from './LeaderboardScene'

/** What starts the initials screen: the result and the boards it makes, the session it came from, and where the player goes after the board. */
export interface InitialsInit {
  offer: Offer
  where: BoardWhere
  info: EntryInfo
  /** Called when the player is done with the initials and the board (or discarded the result): the screen the results were going to. */
  onContinue: () => void
}

const PANEL_W = 1200
const PANEL_TOP = 200
const LINE_PITCH = 54
/** Characters across one slot of the field: the letter and the two blanks after it. */
const SLOT_CHARS = 3
const EMPTY_SLOT = '_'
/** Under the slot the cursor is on. */
const MARK = '▲'

/**
 * The initials of a result that makes a top-10 board: up to six letters and digits, typed or stepped with the arrow
 * keys, arcade style (F-406). It says which boards the result is on and at what rank, opens with the initials used
 * last time, and Enter writes the result to every board it makes, once, and moves on to the board with the new row
 * highlighted. Esc asks whether to discard the result.
 */
export class InitialsScene extends Phaser.Scene implements HasReadout {
  private panel: Panel | null = null
  private parts: Phaser.GameObjects.GameObject[] = []
  private field: Phaser.GameObjects.BitmapText | null = null
  private marker: Phaser.GameObjects.BitmapText | null = null
  private dialog: ConfirmDialog | null = null
  private releaseNav: (() => void) | null = null
  private releaseText: (() => void) | null = null
  private request: Partial<InitialsInit> = {}
  private state: InitialsState = { text: '', cursor: 0 }
  private handled = 0

  constructor() {
    super('Initials')
  }

  init(data: Partial<InitialsInit>): void {
    this.request = data
    this.handled = 0
    // The initials last used; before any, the first letters and digits of the player's name (F-407).
    const { lastInitials, driverName } = saves.read().settings
    this.state = initialsStart(lastInitials ?? driverName)
  }

  create(): void {
    const { offer, where } = this.request
    if (offer === undefined || where === undefined) throw new Error('InitialsScene: it was started without a result and the session it came from')
    this.cameras.main.setBackgroundColor(THEME.colours.background)
    this.parts.push(text(this, { x: 96, y: 48 }, INITIALS_HEADING, 'large').setTint(THEME.colours.accent))

    const lines = [...(offer.lap === null ? [] : [offerWords('lap', offer.lap)]), ...(offer.race === null ? [] : [offerWords('race', offer.race)])]
    const trackName = cuencaRc.id === where.trackId ? cuencaRc.name : where.trackId
    const context = [trackName.toUpperCase(), DIRECTION_WORDS[where.direction], CLASS_WORDS[where.carClass], ...(offer.race !== null && isRaceMinutes(where.minutes) ? [`${where.minutes} MIN`] : [])].join('  ')

    const height = THEME.padding * 2 + lineHeight('small') + 16 + lines.length * LINE_PITCH + lineHeight('small') + 48 + lineHeight('large') + lineHeight('large') + 72 + 2 * lineHeight('small') + 24
    this.panel = new Panel(this, { x: Math.round((LOGICAL_WIDTH - PANEL_W) / 2), y: PANEL_TOP, w: PANEL_W, h: height }, { title: INITIALS_PANEL })
    const { inner } = this.panel

    let y = inner.y
    for (const line of lines) {
      this.parts.push(text(this, { x: inner.x, y }, line, 'body').setTint(THEME.colours.accent))
      y += LINE_PITCH
    }
    this.parts.push(text(this, { x: inner.x, y }, context, 'small').setTint(THEME.colours.textDim))
    y += lineHeight('small') + 48

    // The field: six slots, a character in each that has one and a bar in each that has not, and a mark under the one the cursor is on.
    const fieldWidth = (INITIALS_MAX * SLOT_CHARS - (SLOT_CHARS - 1)) * charWidth('large')
    const left = Math.round(inner.x + (inner.w - fieldWidth) / 2)
    this.field = text(this, { x: left, y }, '', 'large')
    this.marker = text(this, { x: left, y: y + lineHeight('large') + 4 }, MARK, 'large').setTint(THEME.colours.accent)
    this.parts.push(this.field, this.marker)
    y += 2 * lineHeight('large') + 72

    this.parts.push(text(this, { x: inner.x, y }, INITIALS_HINT, 'small').setTint(THEME.colours.textDim))
    this.parts.push(text(this, { x: inner.x, y: y + lineHeight('small') + 12 }, INITIALS_KEYS, 'small').setTint(THEME.colours.textDim))
    this.paint()

    this.releaseNav = onNav(this, (key) => this.onNavKey(key))
    this.releaseText = onText(this, (key) => this.onTextKey(key))
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, this.dispose, this)
  }

  readout(): ScreenReadout {
    const { offer } = this.request
    return {
      focus: 'initials',
      values: {
        handled: this.handled,
        text: this.state.text,
        cursor: this.state.cursor,
        lapRank: offer?.lap?.rank ?? 0,
        raceRank: offer?.race?.rank ?? 0,
        boards: [offer?.lap == null ? '' : BOARD_WORDS.lap, offer?.race == null ? '' : BOARD_WORDS.race].filter((words) => words !== '').join(','),
        asking: this.dialog === null ? 0 : 1,
      },
    }
  }

  private paint(): void {
    const { field, marker } = this
    if (field === null || marker === null) return
    const slots = Array.from({ length: INITIALS_MAX }, (_, i) => this.state.text.charAt(i) || EMPTY_SLOT)
    setTextIfChanged(field, slots.join(' '.repeat(SLOT_CHARS - 1)))
    marker.setVisible(this.state.cursor < INITIALS_MAX)
    marker.setX(field.x + this.state.cursor * SLOT_CHARS * charWidth('large'))
  }

  private onNavKey(key: NavKey): void {
    this.handled++
    if (this.dialog !== null) {
      this.dialog.handle(key)
      return
    }
    if (key === 'confirm') this.confirm()
    else if (key === 'back') this.ask()
    else this.type({ type: key })
  }

  private onTextKey(key: TextKey): void {
    this.handled++
    if (this.dialog === null) this.type(key)
  }

  private type(key: InitialsKey): void {
    this.state = initialsReduce(this.state, key)
    this.paint()
  }

  /** Esc: asks whether to throw the result away. */
  private ask(): void {
    const dialog = new ConfirmDialog(this, { message: DISCARD_QUESTION, confirmLabel: DISCARD_CONFIRM, cancelLabel: DISCARD_CANCEL })
    this.dialog = dialog
    dialog.onAnswer((discard) => {
      this.closeDialog()
      if (discard) this.leave(null)
    })
  }

  private closeDialog(): void {
    this.dialog?.destroy()
    this.dialog = null
  }

  /** Enter: writes the result to every board it makes, under these initials, and shows the board. */
  private confirm(): void {
    const { offer, info } = this.request
    if (!canConfirm(this.state) || offer === undefined || info === undefined) return
    const initials = this.state.text
    const dateISO = new Date().toISOString()
    saves.update((data) => withResultOnBoards(data, offer, info, initials, dateISO))
    this.leave(initials)
  }

  /** Moves on: to the board with the new row highlighted when something was written, straight to where the results were going when it was discarded. */
  private leave(written: string | null): void {
    const { offer, where, info, onContinue } = this.request
    this.stopListening()
    if (written === null || offer === undefined || where === undefined || info === undefined) {
      this.scene.stop()
      onContinue?.()
      return
    }
    const data: LeaderboardInit = {
      open: { board: offer.lap === null ? 'race' : 'lap', trackId: where.trackId, direction: where.direction, carClass: where.carClass, minutes: isRaceMinutes(where.minutes) ? where.minutes : 5, weather: info.weather },
      highlight: {
        ...(offer.lap === null ? {} : { lap: { key: offer.lap.key, index: offer.lap.rank - 1, weather: info.weather } }),
        ...(offer.race === null ? {} : { race: { key: offer.race.key, index: offer.race.rank - 1, weather: info.weather } }),
      },
      onClose: onContinue ?? (() => this.game.scene.start('Title')),
    }
    this.scene.start('Leaderboard', data)
  }

  private stopListening(): void {
    this.releaseNav?.()
    this.releaseNav = null
    this.releaseText?.()
    this.releaseText = null
  }

  private dispose(): void {
    this.stopListening()
    this.closeDialog()
    this.panel?.destroy()
    this.panel = null
    for (const part of this.parts) part.destroy()
    this.parts = []
    this.field = null
    this.marker = null
    this.request = {}
  }
}
