import {
  classification,
  createRng,
  RULES,
  finalStandings,
  legPositions,
  PLAYER_DRIVER_ID,
  qualifyingStandings,
  rankRound,
  type CarClassId,
  type CarColour,
  type DriverProfile,
  type Placing,
  type RaceDayState,
  type ResultRow,
  type ScheduleItem,
  type SessionConfig,
} from '@sim'
import { classes } from '@content/classes'
import type { TableColumn } from '../ui/layout'
import { formatLapTime } from './PracticeReadout'
import { DNF, driverName } from './quick-race'

// What the race-day screens print (F-403), as plain strings and numbers, so that it is tested without an engine: the
// session intro's start order, the standings after a qualifying round or a final leg, the grid, and the podium. The
// scenes lay these out and add nothing to them. Every name is the roster's, in capitals, or YOU for the player.

/** Printed beside a standing that is the top qualifier. */
export const TQ = 'TQ'
/** Marks a point score that does not count towards a driver's total: `(5)`. */
export const NOT_COUNTED = ['(', ')'] as const

/** One printed table: the columns, a line of cells per row, each row's car colour, and the index of the player's row (-1 if none). */
export interface TableView {
  columns: readonly TableColumn[]
  rows: Array<Record<string, string>>
  colours: CarColour[]
  playerRow: number
}

const NAME_CHARS = 15
const col = (key: string, title: string, chars: number, align: 'left' | 'right'): TableColumn => ({ key, title, chars, align })

/** The state's entry for a driver. */
function entryOf(state: RaceDayState, driverId: string): { number: number; colour: CarColour } {
  const entry = state.entries.find((one) => one.driverId === driverId)
  if (entry === undefined) throw new Error(`event-tables: '${driverId}' is not in the event`)
  return entry
}

const playerRowOf = (drivers: readonly string[]): number => drivers.indexOf(PLAYER_DRIVER_ID)

// ── The session intro ─────────────────────────────────────────────────────────────────────────────────────────

/** "QUALIFYING ROUND 2 OF 2", "FINAL, LEG 1 OF 1". */
export function sessionHeading(item: ScheduleItem, state: Pick<RaceDayState, 'settings'>): string {
  return item.kind === 'qualifying'
    ? `QUALIFYING ROUND ${item.round} OF ${state.settings.qualifyingRounds}`
    : `FINAL, LEG ${item.leg} OF ${state.settings.finalsLegs}`
}

/** The round length as it is said: whole minutes, else seconds (the debug hook's override is in seconds). */
export function lengthWords(durationS: number): string {
  if (durationS >= 60 && durationS % 60 === 0) return `${durationS / 60} ${durationS === 60 ? 'MINUTE' : 'MINUTES'}`
  return `${durationS} SECONDS`
}

/** How the session starts, in lines: where from and how, and how long it lasts. A track without a pit lane starts from the boxes whatever was asked. */
export function startLines(config: SessionConfig): string[] {
  if (config.kind === 'final') return ['COUNTDOWN AND GRID START', 'ALL CARS GO TOGETHER ON ONE CLOCK', `${lengthWords(config.durationS)} PLUS THE LAP YOU ARE ON`]
  const fromPit = config.qualifyingStart === 'pit-lane' && config.track.pitLane !== undefined
  return [
    `STAGGERED START FROM THE ${fromPit ? 'PIT LANE' : 'START BOXES'}`,
    'CARS GO ONE AT A TIME, EACH RACING ITS OWN CLOCK',
    `${lengthWords(config.durationS)} PLUS THE LAP YOU ARE ON`,
  ]
}

// ── The pit stop ──────────────────────────────────────────────────────────────────────────────────────────────

/** The heading of the reminder. */
export const PIT_STOP_TITLE = 'PIT STOP REQUIRED'

/**
 * How many pit stops a car of the class owes in a session of the kind on a track that has a pit lane or not: the
 * class row's `mandatoryPitStops`, in a final on a track with a pit lane to make them in, and none anywhere else (the
 * rule of F-306, which the sim applies; the view reads the same row and never the class's id).
 */
export function pitStopsOwed(kind: SessionConfig['kind'], hasPitLane: boolean, carClass: CarClassId): number {
  if (kind !== 'final' || !hasPitLane) return 0
  const owed = classes[carClass].mandatoryPitStops
  return Number.isFinite(owed) ? Math.max(0, Math.floor(owed)) : 0
}

/** The reminder of a stop owed, in lines (none when none is owed): that the car must come through the pit lane and stand for the hold. */
export function pitStopLines(owed: number): string[] {
  if (owed < 1) return []
  const hold = `${RULES.pitHoldS} SECONDS`
  return [PIT_STOP_TITLE, owed === 1 ? `YOUR CAR MUST COME THROUGH THE PIT LANE ONCE AND STAND FOR ${hold}` : `YOUR CAR MUST COME THROUGH THE PIT LANE ${owed} TIMES AND STAND FOR ${hold} EACH TIME`]
}

/** The reminder for a session about to be run. */
export const pitStopLinesFor = (config: SessionConfig): string[] => pitStopLines(pitStopsOwed(config.kind, config.track.pitLane !== undefined, config.carClass))

/** Where the player starts: "YOU ARE CAR 1, RELEASED 4 OF 7", "YOU ARE CAR 1, STARTING FROM GRID POSITION 1 OF 7". Empty when no entry is the player's. */
export function playerStartLine(config: SessionConfig): string {
  const me = config.entries.find((entry) => entry.controller === 'human')
  if (me === undefined) return ''
  const where = config.kind === 'final' ? `STARTING FROM GRID POSITION ${me.startSlot + 1} OF ${config.entries.length}` : `RELEASED ${me.startSlot + 1} OF ${config.entries.length}`
  return `YOU ARE CAR ${me.number}, ${where}`
}

/** Who is on the line, in start order (the order of release in qualifying, the grid from pole in a final). */
export function introTable(config: SessionConfig, roster: readonly DriverProfile[]): TableView {
  const ordered = [...config.entries].sort((a, b) => a.startSlot - b.startSlot)
  const final = config.kind === 'final'
  return {
    columns: [col('slot', final ? 'GRID' : 'ORDER', 5, 'right'), col('no', 'NO', 2, 'right'), col('name', 'DRIVER', NAME_CHARS, 'left'), col('note', '', 4, 'left')],
    rows: ordered.map((entry, i) => ({
      slot: String(i + 1),
      no: String(entry.number),
      name: driverName(entry.driverId, PLAYER_DRIVER_ID, roster),
      note: final && i === 0 ? 'POLE' : '',
    })),
    colours: ordered.map((entry) => entry.colour),
    playerRow: playerRowOf(ordered.map((entry) => entry.driverId)),
  }
}

// ── The standings ─────────────────────────────────────────────────────────────────────────────────────────────

export interface StandingsView extends TableView {
  /** "QUALIFYING ROUND 2 OF 2". */
  heading: string
  /** The panel's title: what the table is. */
  panelTitle: string
  /** Lines under the table: what the marks mean, and who is TQ. */
  notes: string[]
  /** The final's grid, once qualifying is over and the standings shown are qualifying's. */
  grid: (TableView & { title: string }) | null
}

const lapsAndTime = (row: ResultRow): string => {
  const base = `${row.laps} ${formatLapTime(row.timeMs > 0 ? row.timeMs : null)}`
  return row.finished ? base : `${base} ${DNF}`
}

/**
 * Which of a driver's sessions count, by index: the `count` best places, the earlier session first among equals.
 * The sim says how many count (`counted.length`); this says which.
 */
export function countedSessions(places: readonly number[], count: number): Set<number> {
  const order = places.map((place, i) => ({ place, i })).sort((a, b) => a.place - b.place || a.i - b.i)
  return new Set(order.slice(0, count).map((one) => one.i))
}

/**
 * The standings after the latest session recorded: for a qualifying round the qualifying standings, for a final leg
 * the finals standings, each in rank order. A line has the rank, the car, the driver, that session's laps and time,
 * the place won in every session of the kind so far (one that does not count in parentheses), the total, and — when
 * qualifying is over — TQ on the top qualifier. After the last qualifying round the final's grid comes with it.
 */
export function standingsView(state: RaceDayState, roster: readonly DriverProfile[]): StandingsView {
  const latest = state.results.at(-1)
  if (latest === undefined) throw new Error('standingsView: no session has been recorded')
  const kind = latest.item.kind
  const sessions = state.results.filter(({ item }) => item.kind === kind)
  const placed = sessions.map(({ result }) => new Map<string, Placing>((kind === 'qualifying' ? rankRound(result) : legPositions(result)).map((p) => [p.driverId, p])))
  const standings = kind === 'qualifying' ? qualifyingStandings(state) : finalStandings(state)
  const qualifyingOver = kind === 'qualifying' && state.finalGrid !== null
  const unit = kind === 'qualifying' ? 'R' : 'L'

  const columns: TableColumn[] = [
    col('pos', 'POS', 3, 'right'),
    col('no', 'NO', 2, 'right'),
    col('name', 'DRIVER', NAME_CHARS, 'left'),
    col('session', 'LAPS / TIME', 15, 'left'),
    ...sessions.map((_, i) => col(`s${i}`, `${unit}${i + 1}`, 3, 'right')),
    col('pts', 'PTS', 3, 'right'),
    ...(qualifyingOver ? [col('tag', '', 2, 'left')] : []),
  ]
  const rows = standings.map((standing, rank) => {
    const row = latest.result.rows.find((one) => one.driverId === standing.driverId)
    const places = placed.map((map) => map.get(standing.driverId)?.place ?? 0)
    const counts = countedSessions(places, standing.counted.length)
    const cells: Record<string, string> = {
      pos: String(standing.rank),
      no: String(entryOf(state, standing.driverId).number),
      name: driverName(standing.driverId, PLAYER_DRIVER_ID, roster),
      session: row === undefined ? '' : lapsAndTime(row),
      pts: String(standing.points),
      tag: qualifyingOver && rank === 0 ? TQ : '',
    }
    places.forEach((place, i) => {
      cells[`s${i}`] = counts.has(i) ? String(place) : `${NOT_COUNTED[0]}${place}${NOT_COUNTED[1]}`
    })
    return cells
  })

  const countedOf = standings[0]?.counted.length ?? 0
  const notes: string[] = []
  const unitWord = kind === 'qualifying' ? 'ROUND' : 'LEG'
  if (sessions.length > countedOf) notes.push(`BEST ${countedOf} OF ${sessions.length} ${unitWord}S COUNT   A SCORE IN ${NOT_COUNTED.join(' ')} DOES NOT COUNT`)
  else notes.push(`${sessions.length === 1 ? 'THE' : 'EVERY'} ${unitWord} COUNTS`)
  notes.push('LOWEST POINTS WIN')

  const topQualifier = state.finalGrid?.[0]
  let grid: StandingsView['grid'] = null
  if (qualifyingOver && state.finalGrid !== null && topQualifier !== undefined) {
    notes.push(`${TQ}  ${driverName(topQualifier, PLAYER_DRIVER_ID, roster)}  STARTS THE FINAL FROM POLE`)
    grid = {
      title: 'FINAL GRID',
      columns: [col('slot', 'GRID', 4, 'right'), col('no', 'NO', 2, 'right'), col('name', 'DRIVER', NAME_CHARS, 'left')],
      rows: state.finalGrid.map((driverId, i) => ({ slot: String(i + 1), no: String(entryOf(state, driverId).number), name: driverName(driverId, PLAYER_DRIVER_ID, roster) })),
      colours: state.finalGrid.map((driverId) => entryOf(state, driverId).colour),
      playerRow: playerRowOf(state.finalGrid),
    }
  }

  const drivers = standings.map((standing) => standing.driverId)
  return {
    columns,
    rows,
    colours: drivers.map((driverId) => entryOf(state, driverId).colour),
    playerRow: playerRowOf(drivers),
    heading: sessionHeading(latest.item, state),
    panelTitle: kind === 'qualifying' ? `QUALIFYING STANDINGS AFTER ROUND ${sessions.length}` : `FINALS POINTS AFTER LEG ${sessions.length}`,
    notes,
    grid,
  }
}

// ── The podium ────────────────────────────────────────────────────────────────────────────────────────────────

/** What a person on the podium wears besides their colour (F-510), in the order the overlays are drawn: glasses, sunglasses, hat. */
export const OUTFIT_ITEMS = ['glasses', 'sunglasses', 'hat'] as const
export type OutfitItem = (typeof OUTFIT_ITEMS)[number]

/**
 * The picture of a person on the podium: the winner lifting the gold cup, second with the silver cup, third beside the bronze;
 * or, on the podium of the class with a mandatory pit stop, each of the three in the racing suit (F-513). The art has a set of
 * each (and of every overlay but the hat, which no suited person wears).
 */
export type PodiumPose = 'first' | 'second' | 'third' | 'suited' | 'suited-second' | 'suited-third'

/** Whether a pose is one in the racing suit. */
export const isSuitedPose = (pose: PodiumPose): boolean => pose === 'suited' || pose === 'suited-second' || pose === 'suited-third'

/**
 * Whether the podium of an event in `carClass` is in racing suits, all three places: the class whose events carry a mandatory
 * pit stop, the one data field that is F1's alone (`CarClass.mandatoryPitStops`, the one `pitStopsOwed` reads). Never the class's id.
 */
export const podiumInSuits = (carClass: CarClassId): boolean => classes[carClass].mandatoryPitStops > 0

/** The pose of `place` (1 is the winner), in the racing suit when `suited`. */
export const podiumPose = (place: number, suited: boolean): PodiumPose =>
  place === 1 ? (suited ? 'suited' : 'first') : place === 2 ? (suited ? 'suited-second' : 'second') : suited ? 'suited-third' : 'third'

/** The manifest name of a person's pose in a colour (F-506, F-511): the gold cup, the silver, the bronze, and the suit's three. */
export const podiumPoseSprite = (pose: PodiumPose, colour: CarColour): string =>
  pose === 'first' ? `driver.${colour}.trophy` : pose === 'suited' ? `driver.${colour}.suit.trophy` : pose === 'suited-second' ? `driver.${colour}.suit.second` : pose === 'suited-third' ? `driver.${colour}.suit.third` : `driver.${colour}.${pose}`

/** The manifest name of an overlay on a pose (F-506, F-511): the same cell, pivot and frame count as the pose. The art has no hat for a suited pose, and `podiumOutfit` never asks for one. */
export const podiumItemSprite = (item: OutfitItem, pose: PodiumPose): string => `driver.item.${item}.${pose}`

/**
 * What the person on `place` of an event with `seed` wears: some, all or none of a hat, glasses and sunglasses, never both
 * kinds of glasses, in drawing order. A pure function of the seed and the place, from its own named fork of the game's
 * generator (`podium/place-<n>`), so the same event shows the same people every time and a place is dressed alike
 * whatever the field. Each person has half a chance of a hat, and a third each of no eyewear, glasses and sunglasses.
 * Someone `suited` (F-513) wears no hat, whatever the draw: the draws are the same, so their glasses are the ones they
 * would have had on any other podium.
 */
export function podiumOutfit(seed: number, place: number, suited = false): OutfitItem[] {
  const rng = createRng(seed).fork(`podium/place-${place}`)
  const hat = rng.chance(0.5)
  const eyewear = rng.int(0, 2)
  const items: OutfitItem[] = []
  if (eyewear === 1) items.push('glasses')
  if (eyewear === 2) items.push('sunglasses')
  if (hat && !suited) items.push('hat')
  return items
}

export interface PodiumPlace {
  place: number
  number: number
  name: string
  colour: CarColour
  /** Finals points. */
  points: number
  isPlayer: boolean
  /** Which picture stands for them, and the overlays they wear on it, in drawing order (F-510). */
  pose: PodiumPose
  items: OutfitItem[]
}

export interface PodiumView {
  /** The top three, or the top two in a duel, 1st first. */
  places: PodiumPlace[]
  /** The whole classification. */
  table: TableView
  /** "TQ  RAFA VILLACÍS" — null if qualifying set no grid. */
  tq: string | null
  /** "FASTEST LAP  GUS TREMBLAY  0:23.456  QUALIFYING ROUND 2" — null if nobody completed a lap. */
  fastest: string | null
}

/** The quickest single lap of the whole event, with the session it was set in; the earlier session wins a tie. Null if no session had a lap. */
export function eventFastestLap(state: RaceDayState): { driverId: string; lapMs: number; label: string } | null {
  let best: { driverId: string; lapMs: number; label: string } | null = null
  for (const { result } of state.results) {
    if (result.fastestLap !== null && (best === null || result.fastestLap.lapMs < best.lapMs)) best = { ...result.fastestLap, label: result.label }
  }
  return best
}

/** The podium of a finished event: the classification, the top places, the TQ and the event's fastest lap. */
export function podiumView(state: RaceDayState, roster: readonly DriverProfile[]): PodiumView {
  const classified = classification(state)
  if (classified === null) throw new Error('podiumView: the event is not over')
  const points = new Map(finalStandings(state).map((standing) => [standing.driverId, standing.points]))
  const names = classified.map((one) => driverName(one.driverId, PLAYER_DRIVER_ID, roster))
  const drivers = classified.map((one) => one.driverId)
  const suited = podiumInSuits(state.settings.carClass)
  const places = classified.slice(0, Math.min(3, classified.length)).map((one, i) => ({
    place: one.position,
    number: entryOf(state, one.driverId).number,
    name: names[i] ?? '',
    colour: entryOf(state, one.driverId).colour,
    points: points.get(one.driverId) ?? 0,
    isPlayer: one.driverId === PLAYER_DRIVER_ID,
    pose: podiumPose(one.position, suited),
    items: podiumOutfit(state.settings.seed, one.position, suited),
  }))
  const topQualifier = state.finalGrid?.[0]
  const fastest = eventFastestLap(state)
  return {
    places,
    table: {
      columns: [col('pos', 'POS', 3, 'right'), col('no', 'NO', 2, 'right'), col('name', 'DRIVER', NAME_CHARS, 'left'), col('pts', 'PTS', 3, 'right')],
      rows: classified.map((one, i) => ({ pos: String(one.position), no: String(entryOf(state, one.driverId).number), name: names[i] ?? '', pts: String(points.get(one.driverId) ?? 0) })),
      colours: drivers.map((driverId) => entryOf(state, driverId).colour),
      playerRow: playerRowOf(drivers),
    },
    tq: topQualifier === undefined ? null : `${TQ}  ${driverName(topQualifier, PLAYER_DRIVER_ID, roster)}`,
    fastest: fastest === null ? null : `FASTEST LAP  ${driverName(fastest.driverId, PLAYER_DRIVER_ID, roster)}  ${formatLapTime(fastest.lapMs)}  ${fastest.label.toUpperCase()}`,
  }
}
