import type Phaser from 'phaser'
import type { Vec2 } from '@sim'
import type { NavKey } from '../input/keys'
import { OptionCursor } from './options'
import { Row } from './Row'
import { THEME, charWidth, type TextSize } from './theme'

export interface SelectorOptions {
  size?: TextSize
  /** Characters the label column takes; the default fits the label. */
  labelChars?: number
  /** Characters the value column takes; the default fits the longest option. */
  valueChars?: number
}

/**
 * One setting with a fixed list of options: left and right step through them, cycling round the ends. Drawn as
 * `▶ LABEL   ◀ value ▶` on one line, the leading ▶ and the highlight showing focus and the arrows showing that it
 * can be changed. Pass the row to a `Form` to share a focus ring with other rows.
 */
export class Selector<T> {
  private readonly cursor: OptionCursor<T>
  private readonly row: Row
  private readonly labelChars: number
  private readonly valueChars: number
  private focused = false

  constructor(
    scene: Phaser.Scene,
    pos: Vec2,
    private readonly label: string,
    options: ReadonlyArray<{ value: T; label: string }>,
    initial: T,
    opts: SelectorOptions = {},
  ) {
    const size = opts.size ?? 'body'
    this.labelChars = opts.labelChars ?? label.length
    this.valueChars = opts.valueChars ?? options.reduce((most, option) => Math.max(most, option.label.length), 0)
    this.cursor = new OptionCursor(options, initial)
    const chars = this.line().length
    this.row = new Row(scene, pos.x, pos.y, chars * charWidth(size), size, this.line())
    this.paint()
  }

  get value(): T {
    return this.cursor.value
  }

  /** The words of the option showing. */
  get shownLabel(): string {
    return this.cursor.label
  }

  /** The height of the row, for stacking. */
  get heightPx(): number {
    return this.row.heightPx
  }

  /** Calls `fn` with the new value each time left or right changes it. */
  onChange(fn: (value: T) => void): void {
    this.cursor.onChange(fn)
  }

  /** Shows `value` without calling the change listeners. */
  set(value: T): void {
    this.cursor.set(value)
    this.paint()
  }

  setFocused(focused: boolean): void {
    this.focused = focused
    this.paint()
  }

  /** Acts on a menu key; true if the selector used it. */
  handle(key: NavKey): boolean {
    if (key !== 'left' && key !== 'right') return false
    this.cursor.step(key === 'right' ? 1 : -1)
    this.paint()
    return true
  }

  private line(): string {
    const cursor = this.focused ? THEME.cursorGlyph : ' '
    return `${cursor} ${this.label.padEnd(this.labelChars)} ${THEME.arrowLeft} ${this.cursor.label.padEnd(this.valueChars)} ${THEME.arrowRight}`
  }

  private paint(): void {
    this.row.setLabel(this.line())
    this.row.setTone(this.focused ? 'focus' : 'normal')
  }

  destroy(): void {
    this.row.destroy()
  }
}
