import type Phaser from 'phaser'

// The guarded key helper (AGENTS.md, Phaser rule 2; ADR-001). It is the only way the game listens for a key press.
//
// Phaser 4.2.1 handles the whole pending key-event queue on every DOM key event and only clears it after the frame,
// so when two or more key events land between two frames the earlier ones are delivered again, including to a scene
// created in between (Enter on one screen would also press a button on the next). The DOM event object is the same
// each time: remember it per listener and ignore events older than the listener.

/** The keys every menu is driven by. */
export type NavKey = 'up' | 'down' | 'left' | 'right' | 'confirm' | 'back'

/** The part of a DOM key event the guard reads (a `KeyboardEvent` has it), so that the guard is tested without a browser. */
export interface KeyLike {
  keyCode: number
  timeStamp: number
  /** The character the key makes (a `KeyboardEvent` has it): `S`, `s`, `5`, `Backspace`. Read by `onText` only. */
  key?: string
  /** The key's place on the keyboard (`KeyA`, `ArrowLeft`): the same whatever the layout. What the bindings are kept as (F-801). */
  code?: string
  ctrlKey?: boolean
  metaKey?: boolean
  altKey?: boolean
  /** The key is being held down and repeating (a `KeyboardEvent` has it). */
  repeat?: boolean
}

/** The part of Phaser's keyboard plugin the guard uses, so that it can be tested without an engine. */
export interface KeyEvents {
  on(event: string, listener: (event: KeyLike) => void): unknown
  off(event: string, listener: (event: KeyLike) => void): unknown
}

/**
 * Guards are numbered in the order they are made, and a key event is stamped with the number it was first taken at. A guard
 * refuses an event that was taken before it existed: the Enter that opens a screen, handed again to that screen's listeners
 * by Phaser, was taken by the screen before. This is by order, not by time, because WebKit and Firefox give `timeStamp` and
 * `performance.now()` in whole milliseconds: the opening Enter and the new listener can have the same stamp, and the time
 * test alone lets the Enter through twice (Enter on the results skipping the standings).
 */
let guardClock = 0
const takenAt = new WeakMap<object, number>()

/**
 * Returns a function that says whether a DOM key event should be acted on: true the first time it is asked about an
 * event that happened after the guard was made and that no earlier guard had taken, false for an event it has seen and for one older than itself.
 */
export function createKeyGuard(born = performance.now()): (event: KeyLike) => boolean {
  const madeAt = ++guardClock
  const seen = new WeakSet<object>()
  return (event) => {
    if (seen.has(event)) return false
    seen.add(event)
    const first = takenAt.get(event)
    if (first !== undefined && first < madeAt) return false
    if (event.timeStamp < born) return false
    if (first === undefined) takenAt.set(event, ++guardClock)
    return true
  }
}

/**
 * `keyboard.on('keydown-NAME', fn)` with the guards. `name` is a Phaser key name such as 'ESC', 'P' or 'O'. Returns
 * a function that removes the listener. Holding a key down for driving is not done with this: poll `Keyboard`.
 */
export function onKey(keyboard: KeyEvents, name: string, handler: () => void): () => void {
  const eventName = `keydown-${name}`
  const accept = createKeyGuard()
  const listener = (event: KeyLike): void => {
    if (accept(event)) handler()
  }
  keyboard.on(eventName, listener)
  return () => {
    keyboard.off(eventName, listener)
  }
}

/** The menu key each DOM key code stands for (Enter on the main keyboard and on the numeric pad share a code). */
const NAV_CODES: Readonly<Record<number, NavKey>> = { 38: 'up', 40: 'down', 37: 'left', 39: 'right', 13: 'confirm', 27: 'back' }

/**
 * Like `onKey`, for the six menu keys together, through one listener so that the keys reach the handler in the order
 * they were pressed. `born` is when the listener starts, for tests; the default is now.
 */
export function onNavKeys(keyboard: KeyEvents, handler: (key: NavKey) => void, born?: number): () => void {
  const accept = createKeyGuard(born)
  const listener = (event: KeyLike): void => {
    const key = NAV_CODES[event.keyCode]
    if (key !== undefined && accept(event)) handler(key)
  }
  keyboard.on('keydown', listener)
  return () => {
    keyboard.off('keydown', listener)
  }
}

/**
 * Subscribes `handler` to the menu keys of a scene. Every press reaches it once, in order, and a press made before
 * this call (on the screen that opened this one) never does. Returns the unsubscribe, which the scene calls when it
 * shuts down or leaves for another.
 */
export function onNav(scene: Phaser.Scene, handler: (key: NavKey) => void): () => void {
  const keyboard = scene.input.keyboard
  if (keyboard === null) throw new Error(`${scene.scene.key}: the keyboard plugin is not available`)
  return onNavKeys(keyboard, handler)
}

/** A key press as the options screen reads it: the menu key it is, if it is one, and the key's own code. */
export interface KeyPress {
  nav: NavKey | null
  code: string
}

/**
 * Like `onNavKeys`, but each press arrives with its `KeyboardEvent.code` too, in the one listener so that menu keys and
 * the key being captured for a binding are never told apart late. Every key reaches the handler, menu key or not.
 */
export function onKeyPressesOf(keyboard: KeyEvents, handler: (press: KeyPress) => void, born?: number): () => void {
  const accept = createKeyGuard(born)
  const listener = (event: KeyLike): void => {
    if (accept(event)) handler({ nav: NAV_CODES[event.keyCode] ?? null, code: event.code ?? '' })
  }
  keyboard.on('keydown', listener)
  return () => {
    keyboard.off('keydown', listener)
  }
}

/** Subscribes `handler` to every key press of a scene with its code, guarded as `onNav` is. Returns the unsubscribe. */
export function onKeyPresses(scene: Phaser.Scene, handler: (press: KeyPress) => void): () => void {
  const keyboard = scene.input.keyboard
  if (keyboard === null) throw new Error(`${scene.scene.key}: the keyboard plugin is not available`)
  return onKeyPressesOf(keyboard, handler)
}

/** `handler` each time the key with this `KeyboardEvent.code` goes down (the pause key, which the player may have moved), guarded as `onKey` is. Returns the unsubscribe. */
export function onCode(keyboard: KeyEvents, code: string, handler: () => void, born?: number): () => void {
  const accept = createKeyGuard(born)
  const listener = (event: KeyLike): void => {
    if (event.code === code && accept(event)) handler()
  }
  keyboard.on('keydown', listener)
  return () => {
    keyboard.off('keydown', listener)
  }
}

/** The part of the page (`window`) the page-wide key listener uses, so that it is tested without a browser. */
export interface PageKeyEvents {
  addEventListener(type: 'keydown', listener: (event: KeyLike) => void, capture: boolean): void
  removeEventListener(type: 'keydown', listener: (event: KeyLike) => void, capture: boolean): void
}

/**
 * `handler` for every key press on the page, whatever screen is showing, through the same guard as the rest (each DOM event
 * once, none from before the listener). This reads the DOM's own events, not Phaser's: it is for what no one screen owns
 * (the code that unlocks the tuning tools, F-813) and never for driving or menus. It listens in the capture phase, so that it
 * sees a key press before Phaser has handed it to a scene (Phaser handles a key in its own listener at the moment it arrives):
 * what the screens say about themselves when the handler asks, such as "waiting for a key to bind", is then as it was when
 * the key went down. `born` is when the listener starts, for tests; the default is now. Returns the function that stops listening.
 */
export function onPageKeys(page: PageKeyEvents, handler: (event: KeyLike) => void, born?: number): () => void {
  const accept = createKeyGuard(born)
  const listener = (event: KeyLike): void => {
    if (accept(event)) handler(event)
  }
  page.addEventListener('keydown', listener, true)
  return () => {
    page.removeEventListener('keydown', listener, true)
  }
}

/** Which keys are down, by `KeyboardEvent.code`, kept up from the key events. */
export interface HeldKeyTracker {
  isDown(code: string): boolean
  /** Lets go of every key at once, as when the window loses focus. */
  releaseAll(): void
  /** Stops listening. */
  destroy(): void
}

/**
 * Keeps the set of keys that are down, for driving (AGENTS.md, Phaser rule 2: held-key state is polled, never acted on in
 * a handler). Every event goes through one guard, so a key event Phaser 4.2.1 delivers again changes nothing and a key-up
 * can never be undone by an older key-down arriving after it. A key that went down before the tracker was made is not
 * counted until it is pressed again.
 */
export function trackKeys(keyboard: KeyEvents, born?: number): HeldKeyTracker {
  const accept = createKeyGuard(born)
  const down = new Set<string>()
  const onDown = (event: KeyLike): void => {
    if (accept(event) && event.code !== undefined) down.add(event.code)
  }
  const onUp = (event: KeyLike): void => {
    if (accept(event) && event.code !== undefined) down.delete(event.code)
  }
  keyboard.on('keydown', onDown)
  keyboard.on('keyup', onUp)
  return {
    isDown: (code) => down.has(code),
    releaseAll: () => down.clear(),
    destroy: () => {
      keyboard.off('keydown', onDown)
      keyboard.off('keyup', onUp)
      down.clear()
    },
  }
}

/** What typing a name is made of: a letter or digit (always upper case) and the key that deletes. */
export type TextKey = { type: 'char'; char: string } | { type: 'backspace' }

const BACKSPACE = 8

/** What a text field accepts besides letters and digits: the initials screen takes none, a name takes the space. */
export interface TextOptions {
  spaces?: boolean
}

/** The text key a DOM key event is, or undefined for any other: only A-Z and 0-9 (and the space where `spaces` is set) are characters, and a key held with Ctrl, Cmd or Alt is a shortcut, not a letter. */
export function textKeyOf(event: KeyLike, options: TextOptions = {}): TextKey | undefined {
  if (event.ctrlKey === true || event.metaKey === true || event.altKey === true) return undefined
  if (event.keyCode === BACKSPACE || event.key === 'Backspace') return { type: 'backspace' }
  const typed = event.key
  if (options.spaces === true && typed === ' ') return { type: 'char', char: ' ' }
  // Plain ASCII only, before the case is changed ('ı' and 'ſ' would otherwise turn into an I and an S).
  return typed !== undefined && /^[A-Za-z0-9]$/.test(typed) ? { type: 'char', char: typed.toUpperCase() } : undefined
}

/**
 * Like `onNavKeys`, for typing: the letters and digits (upper-cased) and Backspace, through the same guard, so that
 * a key reaches the handler once and a press made before this call never does. Every other key is left to `onNav`
 * or ignored. `born` is when the listener starts, for tests; the default is now.
 */
export function onTextKeys(keyboard: KeyEvents, handler: (key: TextKey) => void, born?: number, options: TextOptions = {}): () => void {
  const accept = createKeyGuard(born)
  const listener = (event: KeyLike): void => {
    const key = textKeyOf(event, options)
    if (key !== undefined && accept(event)) handler(key)
  }
  keyboard.on('keydown', listener)
  return () => {
    keyboard.off('keydown', listener)
  }
}

/** Subscribes `handler` to the typed letters, digits and Backspace of a scene, guarded as `onNav` is, and keeps the browser from acting on Backspace. Returns the unsubscribe. */
export function onText(scene: Phaser.Scene, handler: (key: TextKey) => void, options: TextOptions = {}): () => void {
  const keyboard = scene.input.keyboard
  if (keyboard === null) throw new Error(`${scene.scene.key}: the keyboard plugin is not available`)
  // Backspace deletes a letter here, so the page must not act on it as well: some browsers (WebKit, older Safari) go back a page on it.
  keyboard.addCapture(BACKSPACE)
  const stop = onTextKeys(keyboard, handler, undefined, options)
  return () => {
    stop()
    keyboard.removeCapture(BACKSPACE)
  }
}
