import type Phaser from 'phaser'
import { TICK_RATE, type CarClassId, type CarColour, type CarId, type CarSnapshot, type MarshalSnapshot, type Tick } from '@sim'
import type { DirectionSet } from '../assets/manifest'
import type { WorldView } from '../config'
import { brakeTell, lateralAccelMS2, leanOffsetPx, leanVector } from './car-effects'
import { heldScale, showsRoof, turnOver, turnOverSeconds } from './car-incident'
import { DEPTH } from './depth'
import { headingFrame, type RenderCar } from './interpolate'

/** Where a car's shadow falls from it, in screen pixels: a fixed direction, down and to the right (art-direction.md). */
export const SHADOW_OFFSET_PX = { x: 2, y: 2 } as const

/**
 * How much larger a car is drawn at the top of a kerb hop: a quarter again. The feature's first figure, 8 %, was
 * three pixels on a 36-pixel car and read as a flicker; this reads as a jump at the game's own size.
 */
export const HOP_SCALE = 0.25
/** How much further its shadow falls from it there, in screen pixels, the way the shadow already falls: clear of the body. */
export const HOP_SHADOW_PX = 12

/**
 * How high a car is `airborneTicks` into a kerb hop that lasts `totalTicks`, from 0 on the ground to 1 at the top:
 * a smooth up and down, half a sine, that takes exactly as long as the hop. Outside the hop it is 0.
 */
export function hopLift(airborneTicks: number, totalTicks: number): number {
  if (!(totalTicks > 0)) return 0
  const share = airborneTicks / totalTicks
  if (!(share > 0 && share < 1)) return 0
  return Math.sin(Math.PI * share)
}

/**
 * How a car `lift` of the way up (0..1) is drawn: by how much its sprite is enlarged, and where its shadow falls
 * from it in whole screen pixels. On the ground that is the sprite as baked and the fixed shadow offset.
 */
export function liftedLook(lift: number): { scale: number; shadowX: number; shadowY: number } {
  const reach = Math.hypot(SHADOW_OFFSET_PX.x, SHADOW_OFFSET_PX.y)
  const further = HOP_SHADOW_PX * lift
  return {
    scale: 1 + HOP_SCALE * lift,
    shadowX: SHADOW_OFFSET_PX.x + Math.round((further * SHADOW_OFFSET_PX.x) / reach),
    shadowY: SHADOW_OFFSET_PX.y + Math.round((further * SHADOW_OFFSET_PX.y) / reach),
  }
}

/** Ink, the darkest colour in the game (art-direction.md): the number on the five lighter body colours. */
export const NUMBER_INK = 0x16161e
/** No tint: the number overlay's own white. */
const NUMBER_WHITE = 0xffffff

/**
 * What each body colour's race number is tinted (art-direction.md, "Cars"): the overlay frames are white, so white on
 * red and blue and ink on the five lighter colours. The one table for it.
 */
export const NUMBER_TINT: Readonly<Record<CarColour, number>> = {
  red: NUMBER_WHITE,
  blue: NUMBER_WHITE,
  yellow: NUMBER_INK,
  green: NUMBER_INK,
  white: NUMBER_INK,
  orange: NUMBER_INK,
  pink: NUMBER_INK,
}

/** The manifest name of a car's race number overlay: one frame set a class, per number. */
export const numberSpriteName = (carClass: CarClassId, number: number): string => `car.${carClass}.number.${number}`

/** The tail light (art-direction.md, "Shared materials": reserved for the brake tell), and how big a lamp is. */
export const TAIL_LIGHT = 0xff7a1c
const LAMP_PX = 2

/** Where a car's tail lamps sit, from its centre: metres behind it and either side of the middle line. */
export interface LampPlace {
  alongM: number
  acrossM: number
}

/** The manifest name of a car body in a colour, as the art build emits it. */
export const carSpriteName = (carClass: CarClassId, colour: CarColour): string => `car.${carClass}.${colour}`
/** The manifest name of a car body in a colour when it is on its roof (F-503): the same headings as the upright set. */
export const flippedSpriteName = (carClass: CarClassId, colour: CarColour): string => `car.${carClass}.${colour}.flipped`
/** The manifest name of a class's shadow set. */
export const shadowSpriteName = (carClass: CarClassId): string => `car.${carClass}.shadow`

/** What it takes to draw one car: its body set, its race number's overlay, the shadow set of its class and what it leans against. */
export interface CarLook {
  body: DirectionSet
  /** The same body on its roof: the frames a rolled car shows from halfway through its turn-over. */
  flipped: DirectionSet
  shadow: DirectionSet
  /** The number overlay set, `car.<class>.number.<n>`, and the tint it takes on this body colour. */
  number: DirectionSet
  numberTint: number
  /** Where the tail lamps are. */
  lamps: LampPlace
  /** The class's grip limit, m/s²: the sideways acceleration at which the body leans. */
  gripLimitMS2: number
}

/** Where a car's sprite is on the logical canvas and how much of the cell it covers, for the debug hook and tests. */
export interface CarSpriteInfo {
  id: number
  /** The sprite's centre of rotation, canvas pixels, without the lean. */
  x: number
  y: number
  /** The index of the baked heading being shown. */
  frame: number
  /** The trimmed drawing's width and height as drawn, in canvas pixels: at heading 0 the car's length and width. */
  lengthPx: number
  widthPx: number
  /** How high the car is in a kerb hop, 0 on the ground to 1 at the top, and where its shadow is drawn from it. */
  lift: number
  shadowX: number
  shadowY: number
  /** Whether the roof-down frames are showing, whether the car is being turned over by a roll (F-510), and the size it is drawn at as a multiple of its baked size (the lift of a hop or of a turn-over, and a marshal's hands, together). */
  roofDown: boolean
  turningOver: boolean
  scale: number
  /** The atlas frame of the body being shown. */
  frameName: string
  /** The race number overlay: whether it is shown, which frame, and the tint it is drawn in. */
  numberShown: boolean
  numberFrame: string
  numberTint: number
  /** How far the body is moved from its shadow by the lean, px (at most one in all), and whether the tail lamps are lit. */
  leanX: number
  leanY: number
  braking: boolean
}

interface CarImages {
  body: Phaser.GameObjects.Image
  shadow: Phaser.GameObjects.Image
  number: Phaser.GameObjects.Image
  lamps: [Phaser.GameObjects.Rectangle, Phaser.GameObjects.Rectangle]
  frame: number
  /** The lift the body was last drawn at. */
  lift: number
  /** The size the body was last drawn at, as a multiple of its baked size, and whether it showed the roof-down set then. */
  scale: number
  roofDown: boolean
  turningOver: boolean
  /** A marshal has it in his hands and is walking it to where it is put down (F-510). */
  carried: boolean
  /** The tick of the roll the car is in or was last in (F-505). */
  flipTick: Tick | null
  /** The car was stricken (rolled, bogged or in a marshal's hands) when it was last drawn. */
  stricken: boolean
  /** The lean the body was last drawn at: -1, 0 or 1 pixel toward the car's left, and as a screen offset. */
  lean: number
  leanX: number
  leanY: number
  braking: boolean
  /** The kerb hop the car is in or was last in: the tick it began on and how many ticks it lasts. */
  hop: { fromTick: Tick; ticks: number } | null
}

/**
 * Draws the cars: for each, its baked sprite of the heading nearest the car's, and under it the shadow set's frame of
 * the same heading, at a fixed screen offset. Sprites are never rotated or scaled to the car (AGENTS.md, Phaser
 * rule 7); positions land on whole pixels so that the pixel art stays crisp. The one exception is a kerb hop
 * (F-207): while a car is in the air it is drawn a little larger and its shadow a little further off, by `hopLift`.
 * It reads `RenderCar`s and the hops it is told of, and keeps no gameplay state of its own.
 */
export class CarView {
  private readonly cars: CarImages[] = []

  constructor(
    scene: Phaser.Scene,
    private readonly view: WorldView,
    private readonly looks: readonly CarLook[],
  ) {
    for (const look of looks) {
      // Cars draw in id order, so that where two touch the later one is on top, whole: body, then its lamps, then its number.
      const depth = DEPTH.cars + this.cars.length * 0.01
      const shadow = scene.add
        .image(0, 0, look.shadow.atlas, look.shadow.frames[0])
        .setOrigin(look.shadow.pivot.x, look.shadow.pivot.y)
        .setScale(look.shadow.scale)
        .setDepth(DEPTH.cars - 1)
      const body = scene.add
        .image(0, 0, look.body.atlas, look.body.frames[0])
        .setOrigin(look.body.pivot.x, look.body.pivot.y)
        .setScale(look.body.scale)
        .setDepth(depth)
      const lamp = (): Phaser.GameObjects.Rectangle =>
        scene.add.rectangle(0, 0, LAMP_PX, LAMP_PX, TAIL_LIGHT).setDepth(depth + 0.003).setVisible(false)
      const number = scene.add
        .image(0, 0, look.number.atlas, look.number.frames[0])
        .setOrigin(look.number.pivot.x, look.number.pivot.y)
        .setScale(look.number.scale)
        .setTint(look.numberTint)
        .setDepth(depth + 0.005)
      this.cars.push({ body, shadow, number, lamps: [lamp(), lamp()], frame: 0, lift: 0, scale: 1, roofDown: false, turningOver: false, carried: false, flipTick: null, stricken: false, lean: 0, leanX: 0, leanY: 0, braking: false, hop: null })
    }
  }

  /** A car has met a kerb at speed (the sim's `kerb-hop` event): it is in the air for `ticks` ticks from `fromTick`. */
  hop(car: CarId, fromTick: Tick, ticks: number): void {
    const images = this.cars[car]
    if (images !== undefined) images.hop = { fromTick, ticks }
  }

  /** A car has rolled (the sim's `flip` event) on `tick`: it is turned over from there for the going-over time the snapshot gives (`ROLL_TURN_S` if it gives none), lifting, turning over at the top and coming down on its roof, and shows its roof-down frames from then on. */
  flip(car: CarId, tick: Tick): void {
    const images = this.cars[car]
    if (images !== undefined) images.flipTick = tick
  }

  /**
   * Which cars a marshal has in his hands, from the sim's latest marshals (F-510): they are drawn upright and lifted, wherever the sim
   * has them, until he sets them down. Called before `update` each frame.
   */
  carrying(marshals: readonly Pick<MarshalSnapshot, 'carrying'>[]): void {
    for (const images of this.cars) images.carried = false
    for (const { carrying } of marshals) {
      const images = carrying === null ? undefined : this.cars[carrying]
      if (images !== undefined) images.carried = true
    }
  }

  /**
   * Puts each car where `cars` says, facing the way it faces. `atTick` is the instant being drawn on the sim's
   * clock, fractions of a tick included; a car in a kerb hop at that instant is drawn lifted. `now` are the sim's
   * latest snapshots, for what is not blended between ticks: the brake that lights the tail lamps and the sideways
   * acceleration that leans the body toward the outside of a corner, by a pixel, away from its shadow.
   */
  update(cars: readonly RenderCar[], atTick = 0, now: readonly CarSnapshot[] = []): void {
    for (const car of cars) {
      const images = this.cars[car.id]
      const look = this.looks[car.id]
      if (images === undefined || look === undefined) continue
      const snap = now[car.id]
      // A car a marshal has just put down is drawn where it now is from the tick it was put down, however short the
      // way: it was carried, not driven, so it does not slide there (F-505).
      const setDown = snap !== undefined && images.stricken && snap.state === 'driving' && atTick < snap.stateSinceTick
      const x = Math.round(this.view.originX + (setDown ? snap.pose.x : car.x) * this.view.pxPerM)
      const y = Math.round(this.view.originY + (setDown ? snap.pose.y : car.y) * this.view.pxPerM)
      const angle = setDown ? snap.pose.angle : car.angle

      // A roll is a car turned over once: over the sim's going-over phase (from the flip to `rollSlideTick`) it lifts, turns over at
      // the top and comes down on its roof; from the slide on it is drawn on its roof wherever the sim has it, at the baked heading
      // nearest the one the sim gives, so that the drag and the turn are seen as it moves and the frames change. A snapshot with no
      // slide tick (written by hand) keeps the fixed time. A marshal bent to a rolled car finds it on its roof; once he carries it,
      // it is upright. The heading is always the sim's own: nothing here turns the car through headings (Phaser rule 7).
      const rolled = snap !== undefined && snap.state === 'flipped'
      const turning = rolled && images.flipTick !== null
      const sinceS = (atTick - (images.flipTick ?? 0) + 1) / TICK_RATE
      const goingOverS = snap?.rollSlideTick == null ? null : (snap.rollSlideTick - snap.stateSinceTick) / TICK_RATE
      const turn = turning ? turnOver(sinceS, goingOverS) : null
      const carried = images.carried && snap !== undefined && snap.state === 'being-marshalled'
      const roofDown = turn === null ? snap !== undefined && showsRoof(snap.state, snap.strickenCause, carried) : turn.roofDown
      const set = roofDown ? look.flipped : look.body
      const frame = headingFrame(angle, set.frames.length)

      // A hop that began on tick T covers the step that ended on T and the ones after it. A car is not in a hop and a turn-over together.
      const lift = Math.max(images.hop === null ? 0 : hopLift(atTick - (images.hop.fromTick - 1), images.hop.ticks), turn?.lift ?? 0)
      const lifted = liftedLook(lift)
      const scale = lifted.scale * (snap === undefined ? 1 : heldScale(snap.state, carried))
      if (frame !== images.frame || roofDown !== images.roofDown || scale !== images.scale) {
        if (roofDown !== images.roofDown) images.body.setOrigin(set.pivot.x, set.pivot.y)
        images.frame = frame
        images.roofDown = roofDown
        images.body.setFrame(set.frames[frame]).setScale(set.scale * scale)
        images.number.setFrame(look.number.frames[headingFrame(angle, look.number.frames.length)]).setScale(look.number.scale * scale)
        images.shadow.setFrame(look.shadow.frames[headingFrame(angle, look.shadow.frames.length)])
        images.scale = scale
      }
      images.lift = lift
      images.turningOver = turning && sinceS < turnOverSeconds(goingOverS)
      images.stricken = snap !== undefined && (snap.state === 'flipped' || snap.state === 'stuck' || snap.state === 'being-marshalled')

      // The lean moves the body, not its shadow; the number and the lamps are on the body. A car on its roof does not lean.
      images.lean = snap === undefined || images.stricken ? 0 : leanOffsetPx(lateralAccelMS2(snap.speedMS, snap.yawRateRadS), look.gripLimitMS2, images.lean)
      const lean = leanVector(angle, images.lean)
      images.leanX = lean.x
      images.leanY = lean.y
      const bodyX = x + lean.x
      const bodyY = y + lean.y
      images.body.setPosition(bodyX, bodyY)
      images.number.setPosition(bodyX, bodyY).setVisible(!roofDown)
      images.shadow.setPosition(x + lifted.shadowX, y + lifted.shadowY)

      // The tail lamps light while the brake is on and the car is going forward; they sit where the body's frame says.
      images.braking = snap !== undefined && snap.state === 'driving' && brakeTell(snap.brake, snap.speedMS)
      const facing = (frame * Math.PI * 2) / set.frames.length
      const cos = Math.cos(facing)
      const sin = Math.sin(facing)
      const reach = this.view.pxPerM * lifted.scale
      const along = -look.lamps.alongM * reach
      const across = look.lamps.acrossM * reach
      images.lamps[0].setPosition(Math.round(bodyX + cos * along + sin * across), Math.round(bodyY + sin * along - cos * across)).setVisible(images.braking)
      images.lamps[1].setPosition(Math.round(bodyX + cos * along - sin * across), Math.round(bodyY + sin * along + cos * across)).setVisible(images.braking)
    }
  }

  /** Where each car's sprite is now. */
  sprites(): CarSpriteInfo[] {
    return this.cars.map(({ body, shadow, number, frame, lift, scale, roofDown, turningOver, leanX, leanY, braking }, id) => ({
      id,
      x: body.x - leanX,
      y: body.y - leanY,
      frame,
      lengthPx: body.frame.cutWidth * body.scaleX,
      widthPx: body.frame.cutHeight * body.scaleY,
      lift,
      roofDown,
      turningOver,
      scale,
      frameName: String(body.frame.name),
      shadowX: shadow.x - (body.x - leanX),
      shadowY: shadow.y - (body.y - leanY),
      numberShown: number.visible,
      numberFrame: String(number.frame.name),
      numberTint: number.tintTopLeft,
      leanX,
      leanY,
      braking,
    }))
  }

  destroy(): void {
    for (const { body, shadow, number, lamps } of this.cars) {
      body.destroy()
      shadow.destroy()
      number.destroy()
      for (const lamp of lamps) lamp.destroy()
    }
    this.cars.length = 0
  }
}
