import type Phaser from 'phaser'
import type { CarId, MarshalSnapshot, MarshalState, Vec2 } from '@sim'
import { animation, type Animation } from '../assets/animation'
import { still, type AssetManifest } from '../assets/manifest'
import type { WorldView } from '../config'
import { DEPTH } from './depth'
import { advancePhase, frameAt, interpolateMarshals, isRunning, marshalAnim, nearestMarshal, type RenderMarshal } from './marshal-anim'

// The marshals at their posts and on the move (F-505): one sprite and one shadow each, following the sim's marshal
// snapshots. What animation plays, and how fast, is decided by `marshal-anim.ts`; this class only owns the images.

/** The numbers of the marshals' rules that the picture follows, from the sim's tuning (`INCIDENT_TUNING`). */
export interface MarshalTiming {
  /** How long he bends to a car, s: the bend animation plays once over it. */
  rightingS: number
  /** How long a marshal who has been hit shows the flinch frame, s. */
  flinchS: number
  /** His walking and his running speed, m/s: he is running when he goes nearer the second than the first. */
  walkSpeedMS: number
  runSpeedMS: number
}

/** What the debug hook reports of one marshal: where his feet are on the 1920x1080 canvas, and what he is playing. */
export interface MarshalInfo {
  id: number
  state: MarshalState
  /** The car in his hands (F-510), or null. */
  carrying: CarId | null
  /** The manifest name of the animation playing, such as `marshal.walk.left`. */
  anim: string
  x: number
  y: number
  /** The atlas frame on show, how fast the animation is played (1 is the manifest's rate), whether he is running, and where he is drawn among the layers. */
  frame: string
  rate: number
  running: boolean
  depth: number
}

interface Figure {
  sprite: Phaser.GameObjects.Image
  shadow: Phaser.GameObjects.Image
  /** What is playing, how far into it in frames, and how fast. */
  anim: Animation
  name: string
  phase: number
  rate: number
  frame: string
  running: boolean
  state: MarshalState
  carrying: CarId | null
  /** The session time until which he shows the flinch frame, s. */
  flinchUntilS: number
}

/** The animations of one family, such as every direction of the walk, share a phase when a marshal turns. */
const family = (name: string): string => name.replace(/\.(up|down|left|right)$/, '')

/**
 * One sprite per marshal, made as the sim's snapshots first mention him, placed on whole pixels with his feet at his
 * position, interpolated between ticks the way the cars are. Drawn above the cars and below the tree canopies. It
 * reads snapshots and the one event the sim tells (a hit); it keeps no gameplay state of its own.
 */
export class MarshalView {
  private readonly figures = new Map<number, Figure>()
  private readonly render: RenderMarshal[] = []
  private readonly animations = new Map<string, Animation>()
  private lastTimeS = 0

  constructor(
    private readonly scene: Phaser.Scene,
    private readonly view: WorldView,
    private readonly manifest: AssetManifest,
    private readonly timing: MarshalTiming,
  ) {}

  /**
   * Draws every marshal at the instant `alpha` of the way from `prev` to `curr`. `timeS` is that instant on the sim's
   * clock, in seconds: it times the animations, so pausing the race pauses them and a faster sim plays them faster.
   * `flagOut` (F-711, `flagIsOut`): the chequered flag is out, and every marshal without a car waves it.
   */
  update(prev: readonly MarshalSnapshot[], curr: readonly MarshalSnapshot[], alpha: number, timeS: number, flagOut = false): void {
    const dtS = Math.max(0, timeS - this.lastTimeS)
    this.lastTimeS = timeS
    interpolateMarshals(prev, curr, alpha, this.render)
    for (const m of this.render) {
      const figure = this.figures.get(m.id) ?? this.create(m)
      const flinching = timeS < figure.flinchUntilS
      const running = isRunning(m.speedMS, this.timing.walkSpeedMS, this.timing.runSpeedMS)
      const next = marshalAnim(m, running, flinching, flagOut)
      const to = this.animationOf(next.name)
      if (next.name !== figure.name) {
        if (family(next.name) !== family(figure.name)) figure.phase = 0
        figure.name = next.name
        figure.anim = to
      }
      // The bend plays once over the time it takes to right the car, whatever the manifest's own rate.
      const rate = next.name === 'marshal.bend' ? (to.frames.length / to.fps) / this.timing.rightingS : next.rate
      figure.rate = rate
      figure.phase = advancePhase(figure.phase, dtS, to.fps, rate)
      figure.frame = to.frames[frameAt(figure.phase, to.frames.length, to.loop)]
      figure.running = running
      figure.state = m.state
      figure.carrying = m.carrying
      const x = Math.round(this.view.originX + m.x * this.view.pxPerM)
      const y = Math.round(this.view.originY + m.y * this.view.pxPerM)
      figure.sprite.setFrame(figure.frame).setPosition(x, y).setDepth(depthAt(y))
      figure.shadow.setPosition(x, y).setDepth(depthAt(y) - 1)
    }
  }

  /**
   * A car has run into a marshal (the sim's `contact` event, `other: 'marshal'`, which names the car and not him): the
   * marshal nearest that car, at `at`, flinches for the tuning's time from `timeS`, if the car was going faster than a
   * walking pace, `carSpeedMS` (a marshal who walks round or nudges a standing car does not stop for it, F-508). Not one
   * who is bent to a car, nor the one whose car it is (the sim does not flinch him from the car he is standing over), nor
   * one who is still showing a flinch. One who is walking a car he carries does flinch, with it in his hands.
   */
  flinch(car: CarId, at: Readonly<Vec2>, timeS: number, carSpeedMS: number): void {
    if (!(carSpeedMS > this.timing.walkSpeedMS)) return
    const id = nearestMarshal(this.render.map((m) => ({ id: m.id, pos: { x: m.x, y: m.y } })), at)
    const figure = id === null ? undefined : this.figures.get(id)
    const marshal = this.render.find((m) => m.id === id)
    if (figure === undefined || marshal === undefined) return
    if ((marshal.state === 'righting' && marshal.carrying === null) || marshal.targetCar === car || timeS < figure.flinchUntilS) return
    figure.flinchUntilS = timeS + this.timing.flinchS
  }

  /** Where each marshal is on the canvas and what he is playing, for the debug hook and tests. */
  info(): MarshalInfo[] {
    return [...this.figures].map(([id, figure]) => ({
      id,
      state: figure.state,
      carrying: figure.carrying,
      anim: figure.name,
      x: figure.sprite.x,
      y: figure.sprite.y,
      frame: figure.frame,
      rate: figure.rate,
      running: figure.running,
      depth: figure.sprite.depth,
    }))
  }

  destroy(): void {
    for (const { sprite, shadow } of this.figures.values()) {
      sprite.destroy()
      shadow.destroy()
    }
    this.figures.clear()
    this.render.length = 0
  }

  private animationOf(name: string): Animation {
    let found = this.animations.get(name)
    if (found === undefined) {
      found = animation(this.manifest, name)
      this.animations.set(name, found)
    }
    return found
  }

  private create(m: RenderMarshal): Figure {
    const { name } = marshalAnim(m, false, false)
    const anim = this.animationOf(name)
    const ground = still(this.manifest, 'people.shadow')
    const shadow = this.scene.add.image(0, 0, ground.atlas, ground.frame).setOrigin(ground.pivot.x, ground.pivot.y).setScale(ground.scale).setDepth(DEPTH.people - 1)
    const sprite = this.scene.add.image(0, 0, anim.atlas, anim.frames[0]).setOrigin(anim.pivot.x, anim.pivot.y).setScale(anim.scale).setDepth(DEPTH.people)
    const figure: Figure = { sprite, shadow, anim, name, phase: 0, rate: 1, frame: anim.frames[0], running: false, state: m.state, carrying: m.carrying, flinchUntilS: -Infinity }
    this.figures.set(m.id, figure)
    return figure
  }
}

/** Marshals lower on the screen are in front of those higher up, within the people's band of the draw order. */
const depthAt = (y: number): number => DEPTH.people + y * 1e-4
