import type Phaser from 'phaser'
import { gameFile } from './base'

// The art build's manifest (contracts.md §11, ADR-005): logical names to atlas frames. Game code asks for a name
// such as 'car.tc-stock-175.red', never for an atlas frame. This part has no engine in it (only its types), so that what
// reads a sprite by name can be imported where the engine cannot be (F-802); manifest.ts adds the loading and re-exports it.

export type SpriteEntry = ({ atlas: string; frame: string } | { atlas: string; frames: string[]; fps: number; loop: boolean }) & {
  /** Untrimmed cell size in art pixels. */
  frameSize?: { w: number; h: number }
  /** Normalised 0..1 within the cell. */
  pivot?: { x: number; y: number }
  /** Display scale is 1 / this value: 1 for cars, 0.5 for art drawn at "2x density". */
  artPixelsPerScreenPixel?: number
  /** Present on a baked direction set: `frames[i]` is heading `i x stepDegrees`, clockwise from +x. */
  directions?: number
  stepDegrees?: number
}

export interface FontEntry {
  atlas: string
  descriptor: string
  cell: { w: number; h: number }
  artPixelsPerScreenPixel: number
}

export interface AssetManifest {
  version: number
  atlases: Array<{ key: string; image: string; data: string }>
  sprites: Record<string, SpriteEntry>
  /** Bitmap fonts. `descriptor` is a JSON file holding Phaser's RetroFont config under `config`. */
  fonts: Record<string, FontEntry>
}

/** A baked set of headings of one thing, such as a car body in one colour, ready for `CarView`. */
export interface DirectionSet {
  atlas: string
  /** `frames[i]` shows heading `i x stepDegrees`, clockwise from +x. */
  frames: readonly string[]
  /** Where the sprite's centre of rotation lies in its cell, 0..1. */
  pivot: { x: number; y: number }
  /** Screen pixels per art pixel. */
  scale: number
}

/** One picture by manifest name: a sprite that is a single frame, such as a trophy. */
export interface Still {
  atlas: string
  frame: string
  /** The whole cell, in art pixels. */
  size: { w: number; h: number }
  /** The point of the cell that is placed, 0..1. */
  pivot: { x: number; y: number }
  /** Screen pixels per art pixel at the art's own density. */
  scale: number
}

export const MANIFEST_KEY = 'asset-manifest'
export const MANIFEST_URL = gameFile('manifest.json')
const FORMAT_VERSION = 1

export const isRecord = (value: unknown): value is Record<string, unknown> => typeof value === 'object' && value !== null && !Array.isArray(value)

function isFontEntry(value: unknown): value is FontEntry {
  return (
    isRecord(value) &&
    typeof value.atlas === 'string' &&
    typeof value.descriptor === 'string' &&
    isRecord(value.cell) &&
    typeof value.cell.w === 'number' &&
    typeof value.cell.h === 'number' &&
    typeof value.artPixelsPerScreenPixel === 'number'
  )
}

function isSpriteEntry(value: unknown): value is SpriteEntry {
  if (!isRecord(value) || typeof value.atlas !== 'string') return false
  if (typeof value.frame === 'string') return true
  return Array.isArray(value.frames) && value.frames.every((f) => typeof f === 'string') && typeof value.fps === 'number'
}

/** True if `value` has the shape of `public/assets/manifest.json`. */
export function isAssetManifest(value: unknown): value is AssetManifest {
  return (
    isRecord(value) &&
    value.version === FORMAT_VERSION &&
    Array.isArray(value.atlases) &&
    value.atlases.every((a) => isRecord(a) && typeof a.key === 'string' && typeof a.image === 'string' && typeof a.data === 'string') &&
    isRecord(value.sprites) &&
    Object.values(value.sprites).every(isSpriteEntry) &&
    isRecord(value.fonts) &&
    Object.values(value.fonts).every(isFontEntry)
  )
}

/** The manifest the boot scene loaded. Throws if it is missing or is not a manifest this code understands. */
export function manifestOf(scene: Phaser.Scene): AssetManifest {
  const loaded: unknown = scene.cache.json.get(MANIFEST_KEY)
  if (!isAssetManifest(loaded)) throw new Error(`The asset manifest is missing or not in format version ${FORMAT_VERSION}`)
  return loaded
}

/** A baked direction set by manifest name. Throws for an unknown name or one that is not a direction set. */
export function directionSet(manifest: AssetManifest, name: string): DirectionSet {
  const entry = manifest.sprites[name]
  if (entry === undefined) throw new Error(`The manifest has no sprite named '${name}'`)
  if (!('frames' in entry) || entry.directions === undefined || entry.frames.length !== entry.directions) {
    throw new Error(`Sprite '${name}' is not a baked direction set`)
  }
  return {
    atlas: entry.atlas,
    frames: entry.frames,
    pivot: entry.pivot ?? { x: 0.5, y: 0.5 },
    scale: 1 / (entry.artPixelsPerScreenPixel ?? 1),
  }
}

/** A single picture by manifest name. Throws for an unknown name or one that is not a single frame with a size. */
export function still(manifest: AssetManifest, name: string): Still {
  const entry = manifest.sprites[name]
  if (entry === undefined) throw new Error(`The manifest has no sprite named '${name}'`)
  if (!('frame' in entry) || entry.frameSize === undefined) throw new Error(`Sprite '${name}' is not a single frame with a size`)
  return {
    atlas: entry.atlas,
    frame: entry.frame,
    size: entry.frameSize,
    pivot: entry.pivot ?? { x: 0.5, y: 0.5 },
    scale: 1 / (entry.artPixelsPerScreenPixel ?? 1),
  }
}
