import type Phaser from 'phaser'
import { manifestOf, still } from '../assets/sprites'
import type { Rect } from './layout'
import { NINE, insetsOf, nineSliceRects, type Insets, type Piece } from './skin-layout'

/**
 * One drawn nine-slice of the UI skin (F-802, art/skin/build.py) over a rectangle of the screen: the corners at their own
 * size, the edges and the middle stretched (each is the same along its length, so stretching shows nothing). `name` is
 * the skin's in the manifest (`THEME.skin`). The skin atlas is loaded before the title (manifest.ts, `queueAssets`), so
 * every scene has it. Made hidden; `place` lays it out and shows it.
 */
export class Skin {
  readonly insets: Insets
  private readonly pieces: Array<{ piece: Piece; image: Phaser.GameObjects.Image; fits: boolean }>

  constructor(scene: Phaser.Scene, name: string) {
    const manifest = manifestOf(scene)
    const nw = still(manifest, `${name}.nw`)
    const se = still(manifest, `${name}.se`)
    this.insets = insetsOf(nw.size, se.size, nw.scale)
    this.pieces = NINE.map((piece) => {
      const art = still(manifest, `${name}.${piece}`)
      return { piece, image: scene.add.image(0, 0, art.atlas, art.frame).setOrigin(0, 0).setVisible(false), fits: false }
    })
  }

  /** Lays the skin out over `rect` (screen pixels, whole numbers) and shows it. */
  place(rect: Rect): this {
    const boxes = nineSliceRects(rect, this.insets)
    for (const one of this.pieces) {
      const box = boxes[one.piece]
      // A piece with no room (an edge of a box exactly as long as its corners) is not drawn.
      one.fits = box.w > 0 && box.h > 0
      one.image.setPosition(box.x, box.y).setDisplaySize(Math.max(1, box.w), Math.max(1, box.h)).setVisible(one.fits)
    }
    return this
  }

  /** Shows or hides it where it was last placed; before the first `place` it stays hidden. */
  setVisible(visible: boolean): this {
    for (const { image, fits } of this.pieces) image.setVisible(visible && fits)
    return this
  }

  setDepth(depth: number): this {
    for (const { image } of this.pieces) image.setDepth(depth)
    return this
  }

  /** Whether it is on screen. */
  get visible(): boolean {
    return this.pieces.some(({ image }) => image.visible)
  }

  destroy(): void {
    for (const { image } of this.pieces) image.destroy()
    this.pieces.length = 0
  }
}
