// The credits (F-805): data only, drawn by the credits screen. Every runtime package is here with its version, licence and
// author, as `pnpm licenses list --prod` reports them for this app; `scripts/licences.mjs` (`pnpm licences`) fails when
// this list and the installed packages disagree, when a licence is not on its allow-list, or when a statement below is gone.
// The licences were read from each package's own LICENSE file and package.json, and the skill's from its LICENSE.

export interface PackageCredit {
  /** The package's name on npm. */
  name: string
  version: string
  /** The SPDX identifier the package declares. */
  licence: string
  /** Who wrote it, as its licence file says. */
  by: string
  /** `game`: a runtime dependency, in every build. `panel`: the tuning panel's library: in every build too, as a file of its own that the released game fetches only when the panel is unlocked (F-813), and from the start in the demo build. */
  shipsIn: 'game' | 'panel'
}

export interface CreditsSection {
  heading: string
  lines: readonly string[]
}

export const PACKAGE_CREDITS: readonly PackageCredit[] = [
  { name: 'phaser', version: '4.2.1', licence: 'MIT', by: 'Richard Davey, Phaser Studio Inc.', shipsIn: 'game' },
  { name: 'planck', version: '1.5.0', licence: 'MIT', by: 'Erin Catto, Ali Shakiba', shipsIn: 'game' },
  { name: 'stage-js', version: '1.0.2', licence: 'MIT', by: 'Ali Shakiba', shipsIn: 'game' },
  { name: 'eventemitter3', version: '5.0.4', licence: 'MIT', by: 'Arnout Kazemier', shipsIn: 'game' },
  { name: 'zzfx', version: '1.4.0', licence: 'MIT', by: 'Frank Force', shipsIn: 'game' },
  { name: 'tweakpane', version: '4.0.5', licence: 'MIT', by: 'cocopon', shipsIn: 'panel' },
]

