import Phaser from 'phaser'
import type { SessionConfig } from '@sim'
import { ROSTER } from '@content/roster'
import { LOGICAL_HEIGHT, LOGICAL_WIDTH } from '../config'
import { onNav, type NavKey } from '../input/keys'
import { introHint } from '../persistence'
import { introTable, pitStopLinesFor, playerStartLine, sessionHeading, startLines, type TableView } from '../race/event-tables'
import { withDebugOverrides } from '../race/quick-race'
import { FLOW_SCENES, type FlowStep, type RaceDayController, type RaceDayFlowData } from '../raceday/RaceDayController'
import { Panel, Table, THEME, charWidth, charsInPanel, lineHeight, tableChars, text, wrapText, type HasReadout, type Rect, type ScreenReadout } from '../ui'
import { SWATCH } from './GarageScene'
import type { RaceSceneData } from './RaceScene'

const MARGIN = 96
const PANEL_TOP = 168
const PANEL_GAP = 44
const CHIP_SIZE = 24
/** Room left of a table for each row's colour chip. */
const CHIP_COLUMN = 48
/** The two characters at the left of a table hold the cursor of the player's row. */
const CURSOR_CHARS = 2
const TITLE_HEIGHT = lineHeight('small') + 16
/** The distance between two lines of running text. */
const LINE_PITCH = Math.round(lineHeight('body') * 1.4)

/** How wide a table is on screen, with its chip column and a panel's padding either side: what a panel holding it needs. */
export const tablePanelWidth = (view: Pick<TableView, 'columns'>): number => (tableChars(view.columns) + CURSOR_CHARS) * charWidth('body') + CHIP_COLUMN + 2 * THEME.padding

/** How tall a panel is that holds a table of `rows` rows (and its header), a title and `extra` pixels more. */
export const tablePanelHeight = (rows: number, extra = 0): number => 2 * THEME.padding + TITLE_HEIGHT + (rows + 1) * lineHeight('body') + extra

/** A table on the canvas: the kit's table, with each row's car colour in a chip beside it. */
export interface DrawnTable {
  table: Table
  chips: Phaser.GameObjects.Rectangle[]
  destroy(): void
}

/**
 * Draws a table view at `at` (the top-left of its chip column): the colour chips, then the table with the player's row
 * highlighted. The scenes of the race-day flow share it; it lays out what `event-tables` returns and adds nothing.
 */
export function drawTable(scene: Phaser.Scene, at: { x: number; y: number }, view: TableView): DrawnTable {
  const rect: Rect = { x: at.x + CHIP_COLUMN, y: at.y, w: (tableChars(view.columns) + CURSOR_CHARS) * charWidth('body'), h: (view.rows.length + 1) * lineHeight('body') }
  const table = new Table(scene, rect, view.columns, 'body')
  table.setRows(view.rows, view.playerRow >= 0 ? view.playerRow : undefined)
  const chips = view.colours.map((colour, i) =>
    scene.add.rectangle(at.x, rect.y + lineHeight('body') * (i + 1) + Math.round((lineHeight('body') - CHIP_SIZE) / 2), CHIP_SIZE, CHIP_SIZE, SWATCH[colour]).setOrigin(0, 0),
  )
  return {
    table,
    chips,
    destroy() {
      table.destroy()
      for (const chip of chips) chip.destroy()
    },
  }
}

/** The line at the bottom of every screen of the flow: which keys do what. */
export function keyHint(scene: Phaser.Scene, words: string): Phaser.GameObjects.BitmapText {
  return text(scene, { x: LOGICAL_WIDTH / 2, y: LOGICAL_HEIGHT - 64 }, words, 'small').setOrigin(0.5, 0).setTint(THEME.colours.textDim)
}

/**
 * The session about to run: its name (Qualifying round 2 of 2, Final, leg 1 of 1), the drivers in start order with
 * their numbers and colours and the player's row marked, and how it starts. Enter starts the race scene with the
 * session's config; when the session finishes the result is recorded (`onFinished`) and the results screen shown,
 * whose Enter leads on to the standings. Esc leaves for the title with the event kept (F-405).
 */
export class SessionIntroScene extends Phaser.Scene implements HasReadout {
  private parts: Phaser.GameObjects.GameObject[] = []
  private panels: Panel[] = []
  private drawn: DrawnTable | null = null
  private release: (() => void) | null = null
  private controller: RaceDayController | null = null
  private step: Extract<FlowStep, { kind: 'session' }> | null = null
  /** The step's config as the race will run it (the debug hook may have changed its length). */
  private config: SessionConfig | null = null
  private shown: TableView | null = null
  private handled = 0

  constructor() {
    super('SessionIntro')
  }

  init(data: Partial<RaceDayFlowData>): void {
    this.controller = data.controller ?? null
    this.handled = 0
    this.step = null
    this.config = null
    this.shown = null
  }

  create(): void {
    const controller = this.controller
    if (controller === null) throw new Error('SessionIntroScene: it was started without a race day')
    const step = controller.peek()
    if (step.kind !== 'session') {
      // Not a session after all (the flow has moved on): show what is next instead.
      this.scene.start(FLOW_SCENES[step.kind], { controller } satisfies RaceDayFlowData)
      return
    }
    this.step = step
    const { item } = step
    const config = withDebugOverrides(step.config)
    this.config = config
    const { settings } = controller.state
    const view = introTable(config, ROSTER)
    this.shown = view

    this.cameras.main.setBackgroundColor(THEME.colours.background)
    this.parts.push(text(this, { x: MARGIN, y: 48 }, sessionHeading(item, controller.state), 'large').setTint(THEME.colours.accent))
    this.parts.push(text(this, { x: MARGIN, y: 116 }, `${settings.carsPerRace} CARS   ${settings.direction.toUpperCase()}   ${settings.difficulty.toUpperCase()}`, 'small').setTint(THEME.colours.textDim))
    this.parts.push(keyHint(this, introHint))

    const lineWidth = tablePanelWidth(view)
    const howRect: Rect = { x: MARGIN + lineWidth + PANEL_GAP, y: PANEL_TOP, w: LOGICAL_WIDTH - MARGIN - (MARGIN + lineWidth + PANEL_GAP), h: 0 }
    const chars = charsInPanel(howRect.w, 'body')
    const pit = pitStopLinesFor(config).flatMap((words) => wrapText(words, chars))
    const lines = [...startLines(config).flatMap((words) => wrapText(words, chars)), '', ...wrapText(playerStartLine(config), chars), ...(pit.length === 0 ? [] : ['', ...pit])]
    // The line that says a pit stop is owed stands out, as the first line of the panel does.
    const pitFrom = pit.length === 0 ? -1 : lines.length - pit.length
    // Both panels are as tall as the taller of the two contents.
    const height = Math.max(tablePanelHeight(view.rows.length), 2 * THEME.padding + TITLE_HEIGHT + lines.length * LINE_PITCH)
    howRect.h = height

    const line = new Panel(this, { x: MARGIN, y: PANEL_TOP, w: lineWidth, h: height }, { title: config.kind === 'final' ? 'ON THE GRID' : 'ON THE LINE' })
    this.panels.push(line)
    this.drawn = drawTable(this, { x: line.inner.x, y: line.inner.y }, view)

    const howPanel = new Panel(this, howRect, { title: 'HOW IT STARTS' })
    this.panels.push(howPanel)
    lines.forEach((words, i) => {
      this.parts.push(text(this, { x: howPanel.inner.x, y: howPanel.inner.y + i * LINE_PITCH }, words, 'body').setTint(i === 0 || (pitFrom >= 0 && i >= pitFrom) ? THEME.colours.accent : THEME.colours.text))
    })

    this.release = onNav(this, (key) => this.onKey(key))
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, this.dispose, this)
  }

  readout(): ScreenReadout {
    const view = this.shown
    const config = this.config
    return {
      focus: 'start',
      values: {
        handled: this.handled,
        label: config?.label ?? '',
        kind: config?.kind ?? '',
        rows: view?.rows.length ?? 0,
        playerRow: view?.playerRow ?? -1,
        order: view?.rows.map((row) => row['no']).join(',') ?? '',
        pitStop: this.config === null ? 0 : pitStopLinesFor(this.config).length,
        heading: this.step === null || this.controller === null ? '' : sessionHeading(this.step.item, this.controller.state),
      },
    }
  }

  private onKey(key: NavKey): void {
    this.handled++
    if (key === 'back') {
      // The event is saved at every boundary, so leaving loses nothing: CONTINUE on the title resumes at this session.
      this.stopListening()
      this.scene.start('Title')
      return
    }
    if (key !== 'confirm') return
    const { config, controller } = this
    if (config === null || controller === null) return
    this.stopListening()
    const scenes = this.game.scene
    // The result is recorded the moment the session finishes; Enter on the results screen then leads to the standings.
    const data: RaceSceneData = {
      config,
      onFinished: (result) => controller.record(result),
      onContinue: () => scenes.start(controller.nextScene(), { controller } satisfies RaceDayFlowData),
      continueHint: 'ENTER STANDINGS',
    }
    this.scene.start('Race', data)
  }

  private stopListening(): void {
    this.release?.()
    this.release = null
  }

  private dispose(): void {
    this.stopListening()
    this.drawn?.destroy()
    this.drawn = null
    for (const panel of this.panels) panel.destroy()
    this.panels = []
    for (const part of this.parts) part.destroy()
    this.parts = []
    this.controller = null
    this.step = null
    this.config = null
    this.shown = null
  }
}
