import Phaser from 'phaser'
import { ROSTER } from '@content/roster'
import { onNav, type NavKey } from '../input/keys'
import { standingsHint } from '../persistence'
import { NOT_COUNTED, sessionHeading, standingsView, type StandingsView } from '../race/event-tables'
import { FLOW_SCENES, type RaceDayController, type RaceDayFlowData } from '../raceday/RaceDayController'
import { Panel, THEME, charsInPanel, lineHeight, text, wrapText, type HasReadout, type Rect, type ScreenReadout } from '../ui'
import { CLOSING_KEY, ClosingVoice, type Closing } from './ResultsScene'
import { drawTable, keyHint, tablePanelHeight, tablePanelWidth, type DrawnTable } from './SessionIntroScene'

const MARGIN = 96
const PANEL_TOP = 168
const PANEL_GAP = 24
/** Space between a table and the notes under it. */
const NOTES_GAP = 28
const NOTE_PITCH = Math.round(lineHeight('body') * 1.4)

/**
 * The standings after a session. After a qualifying round: every driver in rank order with that round's laps and time,
 * the place won in each round so far (a round that does not count in brackets) and the points; once qualifying is over
 * the TQ is marked and the final's grid stands beside the table, pole first. After a final leg: the same for the
 * finals, with the leg's finishing order and each driver's finals points. Enter goes on to the next session, or to the
 * podium after the last leg. Esc leaves for the title with the event kept (F-405).
 */
export class StandingsScene extends Phaser.Scene implements HasReadout {
  private parts: Phaser.GameObjects.GameObject[] = []
  private panels: Panel[] = []
  private drawn: DrawnTable[] = []
  private release: (() => void) | null = null
  private controller: RaceDayController | null = null
  private shown: StandingsView | null = null
  private handled = 0
  /** The commentator, saying how the session just run ended (F-703). */
  voice: ClosingVoice | null = null

  constructor() {
    super('Standings')
  }

  init(data: Partial<RaceDayFlowData>): void {
    this.controller = data.controller ?? null
    this.handled = 0
    this.shown = null
  }

  create(): void {
    const controller = this.controller
    if (controller === null) throw new Error('StandingsScene: it was started without a race day')
    const step = controller.peek()
    if (step.kind !== 'standings') {
      this.scene.start(FLOW_SCENES[step.kind], { controller } satisfies RaceDayFlowData)
      return
    }
    const view = standingsView(controller.state, ROSTER)
    this.shown = view
    const { state } = controller
    const upNext = state.schedule[state.cursor]

    this.cameras.main.setBackgroundColor(THEME.colours.background)
    this.parts.push(text(this, { x: MARGIN, y: 48 }, 'STANDINGS', 'large').setTint(THEME.colours.accent))
    this.parts.push(text(this, { x: MARGIN, y: 116 }, `AFTER ${view.heading}   NEXT: ${upNext === undefined ? 'THE PODIUM' : sessionHeading(upNext, state)}`, 'small').setTint(THEME.colours.textDim))
    this.parts.push(keyHint(this, standingsHint(upNext === undefined)))

    // The grid, when there is one, takes the room to the right of the table.
    const gridWidth = view.grid === null ? 0 : tablePanelWidth(view.grid)
    const standingsRect: Rect = { x: MARGIN, y: PANEL_TOP, w: tablePanelWidth(view), h: 0 }
    const chars = charsInPanel(standingsRect.w, 'body')
    // A note that fits is shown as it is, its spacing kept; a longer one is broken at spaces.
    const notes = view.notes.flatMap((note) => (note.length <= chars ? [note] : wrapText(note, chars)))
    standingsRect.h = tablePanelHeight(view.rows.length, NOTES_GAP + notes.length * NOTE_PITCH)

    const panel = new Panel(this, standingsRect, { title: view.panelTitle })
    this.panels.push(panel)
    this.drawn.push(drawTable(this, { x: panel.inner.x, y: panel.inner.y }, view))
    const notesTop = panel.inner.y + (view.rows.length + 1) * lineHeight('body') + NOTES_GAP
    notes.forEach((note, i) => {
      const isTq = note.startsWith('TQ')
      this.parts.push(text(this, { x: panel.inner.x, y: notesTop + i * NOTE_PITCH }, note, 'body').setTint(isTq ? THEME.colours.accent : THEME.colours.textDim))
    })

    if (view.grid !== null) {
      const gridRect: Rect = { x: standingsRect.x + standingsRect.w + PANEL_GAP, y: PANEL_TOP, w: gridWidth, h: tablePanelHeight(view.grid.rows.length) }
      const gridPanel = new Panel(this, gridRect, { title: view.grid.title })
      this.panels.push(gridPanel)
      this.drawn.push(drawTable(this, { x: gridPanel.inner.x, y: gridPanel.inner.y }, view.grid))
    }

    this.release = onNav(this, (key) => this.onKey(key))
    const closing: unknown = this.registry.get(CLOSING_KEY)
    this.voice = ClosingVoice.mount(this, (closing as Closing | undefined) ?? null, 2)
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, this.dispose, this)
  }

  update(time: number): void {
    this.voice?.update(time)
  }

  readout(): ScreenReadout {
    const view = this.shown
    const bracketed = view?.rows.reduce((total, row) => total + Object.values(row).filter((cell) => cell.startsWith(NOT_COUNTED[0])).length, 0) ?? 0
    return {
      focus: 'continue',
      values: {
        handled: this.handled,
        heading: view?.heading ?? '',
        rows: view?.rows.length ?? 0,
        playerRow: view?.playerRow ?? -1,
        order: view?.rows.map((row) => row['no']).join(',') ?? '',
        points: view?.rows.map((row) => row['pts']).join(',') ?? '',
        notCounted: bracketed,
        tq: view?.rows.findIndex((row) => row['tag'] === 'TQ') ?? -1,
        gridRows: view?.grid?.rows.length ?? 0,
        gridOrder: view?.grid?.rows.map((row) => row['no']).join(',') ?? '',
      },
    }
  }

  private onKey(key: NavKey): void {
    this.handled++
    if (key === 'back') {
      // The event is saved at every boundary, so leaving loses nothing: CONTINUE on the title resumes at what is next.
      this.stopListening()
      this.scene.start('Title')
      return
    }
    if (key !== 'confirm') return
    const controller = this.controller
    if (controller === null) return
    this.stopListening()
    controller.acknowledgeStandings()
    this.scene.start(controller.nextScene(), { controller } satisfies RaceDayFlowData)
  }

  private stopListening(): void {
    this.release?.()
    this.release = null
  }

  private dispose(): void {
    this.stopListening()
    this.voice?.destroy()
    this.voice = null
    for (const table of this.drawn) table.destroy()
    this.drawn = []
    for (const panel of this.panels) panel.destroy()
    this.panels = []
    for (const part of this.parts) part.destroy()
    this.parts = []
    this.controller = null
    this.shown = null
  }
}
