import { LOGICAL_HEIGHT, LOGICAL_WIDTH } from '../config'
import { charsAcross, type Rect } from '../ui/layout'
import { THEME, charWidth, lineHeight } from '../ui/theme'

// Where the leaderboards screen puts its two panels (F-815). Pure, so that a test measures the widest real row against the
// room the table really has, at the body size: a row set with DRIVING ASSISTANCE has (A*) after its time and must not make
// the table shrink to the small size.

/** The screen's side margin: less than the other screens', to give the table the room its widest row needs at body size. */
export const MARGIN = 48
export const PANEL_TOP = 168
/** The distance between two selector rows of the form. */
export const ROW_PITCH = 61
/** The most rows the form has: track, direction, class, board, the race board's length, and the weather (F-818). */
export const MAX_ROWS = 6
/** The selectors' label and value columns, in characters: `DIRECTION` and `COUNTER-CLOCKWISE` are the longest words. */
export const LABEL_CHARS = 9
export const VALUE_CHARS = 17
/** A selector's whole line: the cursor, the label, the two arrows and the value, with a space between each (`Selector`). */
const SELECTOR_CHARS = 1 + 1 + LABEL_CHARS + 1 + 1 + 1 + VALUE_CHARS + 1 + 1
const GAP = 16

/** The form's panel, as wide as its widest selector and the padding. */
export const LEFT_PANEL: Rect = { x: MARGIN, y: PANEL_TOP, w: SELECTOR_CHARS * charWidth('body') + 2 * THEME.padding, h: 500 }
const RIGHT_X = LEFT_PANEL.x + LEFT_PANEL.w + GAP
/** The table's panel, which holds the table and, under it, a line in the hints' size. */
export const RIGHT_PANEL: Rect = { x: RIGHT_X, y: PANEL_TOP, w: LOGICAL_WIDTH - MARGIN - RIGHT_X, h: Math.min(588, LOGICAL_HEIGHT - 96 - PANEL_TOP) }

/** Characters of body text the table has across its panel, the cursor's two included. */
export const TABLE_ROOM = charsAcross(RIGHT_PANEL.w - 2 * THEME.padding, 'body')

/** The footnote's line, in the hints' style, and the gap above it. */
export const FOOTNOTE_GAP = 24
export const FOOTNOTE_H = lineHeight('small') + FOOTNOTE_GAP
