import type { CarId, SessionEntry } from '@sim'

/**
 * The car the person at the keyboard drives: the first entry a human controls, wherever it is on the grid. Null in
 * a session whose every car is the game's. The view never assumes it is car 0.
 */
export function playerCarId(entries: readonly SessionEntry[]): CarId | null {
  const id = entries.findIndex((entry) => entry.controller === 'human')
  return id === -1 ? null : id
}
