import type { QuickRaceChoices } from '../race/quick-race'
import type { SaveData } from './storage'

// The quick race's choices in the save (F-808), as `withEvent` keeps the event setup's: written when a quick race is
// started, so that the screen opens on them after a reload.

/** The save with these as the quick race's last choices; the same save, unchanged, when they already are, so that nothing is written. */
export function withQuickRace(data: SaveData, choices: Readonly<QuickRaceChoices>): SaveData {
  const last = data.settings.lastQuickRace
  const same = (Object.keys(choices) as Array<keyof QuickRaceChoices>).every((key) => last[key] === choices[key]) && Object.keys(last).length === Object.keys(choices).length
  return same ? data : { ...data, settings: { ...data.settings, lastQuickRace: { ...choices } } }
}
