/** What a menu screen says about itself to tests and tools (the debug hook): which item has focus, and what it shows. */
export interface ScreenReadout {
  /** The id of the focused item. */
  focus: string | null
  /** Named facts about what is on screen: choices made, text shown, sprite and bar figures. */
  values: Readonly<Record<string, string | number>>
}

export interface HasReadout {
  readout(): ScreenReadout
}

export const hasReadout = (scene: unknown): scene is HasReadout =>
  typeof scene === 'object' && scene !== null && 'readout' in scene && typeof scene.readout === 'function'
