import type { CarClassId, RaceControlCall } from '@sim'
import { classes } from '@content/classes'
import { tuning } from '@content/tuning'
import { AUDIBLE, DRIVETRAIN_SOUND } from './motor-sound'

// The pure half of the audio layer (F-704): sim values in, synth parameters out. No WebAudio types here, so Node
// tests every number. The synths in this folder only apply what these functions say.

const TWO_PI = Math.PI * 2

const clamp = (value: number, low: number, high: number): number => Math.min(high, Math.max(low, value))
const clamp01 = (value: number): number => clamp(value, 0, 1)
/** 0 up to `from`, 1 from `to`, a smooth S between. */
const smoothstep = (from: number, to: number, value: number): number => {
  const t = clamp01((value - from) / (to - from))
  return t * t * (3 - 2 * t)
}

// ── The loudness budget ─────────────────────────────────────────────────────────────────────────────────────────
// Every continuous voice has a ceiling on its peak amplitude (before the sfx and master gains, which are at most 1).
// They are chosen so that the worst case a full grid can make, all at once, stays under 1.0 even before the master
// compressor, which is the second guard (AudioMixer).

/** Peak amplitude of one non-player motor voice at its loudest; the player's is `PLAYER_BOOST` times it. */
export const MOTOR_GAIN_MAX = 0.06
/** The player's car is about 6 dB louder than the others (the doc), a factor of 2 in amplitude. */
export const PLAYER_BOOST = 2
export const SCRUB_GAIN_MAX = 0.035
export const GRASS_GAIN_MAX = 0.03
export const RAIN_GAIN_MAX = 0.08
export const WIND_GAIN_MAX = 0.05
/** The low-pass in a motor voice can ring above its input a little. */
const FILTER_HEADROOM = 1.15
/** The share of its loudness a moving car has off the throttle. The rest comes with load. */
export const MOTOR_COAST_SHARE = 0.4

// ── Volume ──────────────────────────────────────────────────────────────────────────────────────────────────────

/** A volume setting (0..1, a slider) as a gain: squared, so that equal slider steps sound like equal steps. */
export const volumeGain = (level: number): number => clamp01(level) ** 2

// ── The motor ───────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * Passes `hz` through unchanged below `kneeHz`, and above it bends smoothly toward `ceilingHz` without ever
 * reaching it. Strictly increasing, so a rising source never stops rising, only slows.
 */
export function softCap(hz: number, kneeHz: number, ceilingHz: number): number {
  if (hz <= kneeHz) return Math.max(0, hz)
  const room = ceilingHz - kneeHz
  return kneeHz + room * (1 - Math.exp(-(hz - kneeHz) / room))
}

/** Motor shaft speed at no load for a class, rad/s: KV times the pack voltage. What its sound is measured against. */
export function noLoadRadS(classId: CarClassId): number {
  return (classes[classId].motor.kv * tuning.packVoltage * TWO_PI) / 60
}

/** Rotor revolutions per second. */
export const motorRevHz = (motorRadS: number): number => Math.abs(motorRadS) / TWO_PI

export interface MotorVoice {
  /** The whine's fundamental: rotor revolutions per second times pole pairs, pitched for speakers. */
  freqHz: number
  /** Peak amplitude of the whole voice before the player boost, 0..`MOTOR_GAIN_MAX` × the class's loudness. */
  gain: number
  /** 0..1: how bright the low-pass is. Load (throttle) and speed open it. */
  brightness: number
}

export function motorVoice(p: { motorRadS: number; throttle: number; classId: CarClassId }): MotorVoice {
  const sound = DRIVETRAIN_SOUND[p.classId]
  const share = clamp(Math.abs(p.motorRadS) / noLoadRadS(p.classId), 0, 1.2)
  const whine = AUDIBLE.whine
  const freqHz = softCap(motorRevHz(p.motorRadS) * sound.polePairs * whine.scale, whine.kneeHz, whine.ceilingHz)
  // A motor that is not turning makes no sound; it comes in over the first few percent of its speed.
  const spin = smoothstep(0, 0.05, share)
  const load = MOTOR_COAST_SHARE + (1 - MOTOR_COAST_SHARE) * clamp01(Math.abs(p.throttle))
  return {
    freqHz,
    gain: MOTOR_GAIN_MAX * sound.loudness * spin * load,
    brightness: clamp01(0.2 + 0.5 * clamp01(Math.abs(p.throttle)) + 0.3 * clamp01(share) + sound.brightnessBias),
  }
}

export interface MotorPartials {
  /** The pinion-and-spur gear mesh: rotor revolutions times pinion teeth, pitched for speakers. */
  meshHz: number
  /** The belt's tooth-passing rate: pulley revolutions times its teeth; 0 where there is no belt. */
  beltHz: number
}

export function motorPartials(p: { motorRadS: number; classId: CarClassId }): MotorPartials {
  const sound = DRIVETRAIN_SOUND[p.classId]
  const rev = motorRevHz(p.motorRadS)
  const { mesh, belt } = AUDIBLE
  const pulleyRev = (rev * sound.pinionTeeth) / sound.spurTeeth
  return {
    meshHz: softCap(rev * sound.pinionTeeth * mesh.scale, mesh.kneeHz, mesh.ceilingHz),
    beltHz: sound.pulleyTeeth === 0 ? 0 : softCap(pulleyRev * sound.pulleyTeeth * belt.scale, belt.kneeHz, belt.ceilingHz),
  }
}

/** The motor low-pass's cutoff for a brightness. */
export const motorCutoffHz = (brightness: number): number => 700 + 4300 * clamp01(brightness) ** 1.5

/** The most amplitude a motor voice can have at its output, filter ringing included: its gain times the sum of its sources' levels. */
export function motorPeak(gain: number, classId: CarClassId): number {
  const { whine, mesh, belt } = DRIVETRAIN_SOUND[classId].mix
  return gain * (whine + mesh + belt) * FILTER_HEADROOM
}

// ── Tyres and ground ────────────────────────────────────────────────────────────────────────────────────────────

export interface NoiseVoice {
  gain: number
  cutoffHz: number
}

/**
 * Tyre scrub: noise that comes in as an axle nears and passes its grip (saturation 0.75 to 1.25) and only at
 * speed. A wet track makes it hissier, not louder.
 */
export function scrubVoice(p: { slipFront: number; slipRear: number; speedMS: number; wetness: number }): NoiseVoice {
  const over = smoothstep(0.75, 1.25, Math.max(p.slipFront, p.slipRear))
  const moving = smoothstep(0.4, 2.5, Math.abs(p.speedMS))
  return { gain: SCRUB_GAIN_MAX * over * moving, cutoffHz: 1100 + 1800 * over + 1600 * clamp01(p.wetness) }
}

/**
 * What a car on grass should be given for `bog`: the sim reports 0 at the edge of the lane and grows it with the
 * distance run on grass, so the first metres would be silent. A car on the grass drags at once.
 */
export const GRASS_ENTRY_BOG = 0.1

/** The drag of grass: filtered noise that rises with how deep the car is in it, and with its speed. */
export function grassVoice(p: { bog: number; speedMS: number }): NoiseVoice {
  const bog = clamp01(p.bog)
  const speed = Math.abs(p.speedMS)
  return {
    gain: GRASS_GAIN_MAX * smoothstep(0.2, 2, speed) * (0.4 + 0.6 * bog),
    // Duller the deeper it is, brighter the faster the blades go by.
    cutoffHz: (450 + 250 * Math.min(speed, 4)) * (1 - 0.4 * bog),
  }
}

// ── One-shots ───────────────────────────────────────────────────────────────────────────────────────────────────

/** An impulse below this (N·s) is a brush, not a hit, and plays nothing. */
export const IMPACT_THRESHOLD_NS = 0.08
/** An impulse at and above this plays at full level. */
export const IMPACT_FULL_NS = 4

/** 0 below the threshold; from the threshold it rises with the logarithm of the impulse (loudness is logarithmic) from 0.15 to 1. */
export function impactGain(impulseNs: number): number {
  if (!(impulseNs >= IMPACT_THRESHOLD_NS)) return 0
  const t = clamp01(Math.log(impulseNs / IMPACT_THRESHOLD_NS) / Math.log(IMPACT_FULL_NS / IMPACT_THRESHOLD_NS))
  return 0.15 + 0.85 * t
}

/** The thump of a kerb hop, by the speed it was taken at (m/s). */
export const kerbThumpGain = (speedMS: number): number => 0.25 + 0.75 * clamp01(Math.abs(speedMS) / 7)

/** The rumble of a wheel on a kerb: nothing when crawling, then rising with speed. */
export const kerbRumbleGain = (speedMS: number): number => {
  const speed = Math.abs(speedMS)
  return speed < 0.8 ? 0 : 0.15 + 0.5 * clamp01(speed / 6)
}

/** A car through a puddle, by speed and how deep the puddle is (0..1). */
export const splashGain = (speedMS: number, depth: number): number => {
  const speed = Math.abs(speedMS)
  return speed < 0.6 ? 0 : (0.2 + 0.8 * clamp01(speed / 6)) * (0.5 + 0.5 * clamp01(depth))
}

/**
 * Stereo position for a screen x: the 1920-wide screen's left edge is -`PAN_WIDTH`, its right edge +`PAN_WIDTH`.
 * A little less than full, because a car at the edge of the track is still in the room.
 */
export const PAN_WIDTH = 0.8
export const SCREEN_WIDTH_PX = 1920
export const panForScreenX = (screenXPx: number, widthPx = SCREEN_WIDTH_PX): number => clamp((screenXPx / widthPx - 0.5) * 2 * PAN_WIDTH, -1, 1)

// ── Weather ─────────────────────────────────────────────────────────────────────────────────────────────────────

/** Rain on the track and the cars: linear in intensity (0..1), so that a ramp has no step in it. */
export const rainGain = (intensity: number): number => RAIN_GAIN_MAX * clamp01(intensity)

/** Wind: nothing in still air (under 0.4 m/s), then rising with the air's speed to a full level at 8 m/s. */
export const windGain = (speedMS: number): number => WIND_GAIN_MAX * clamp01((Math.abs(speedMS) - 0.4) / 7.6) ** 0.8

/** The wind bed's low-pass cutoff: it whistles higher the harder it blows. */
export const windCutoffHz = (speedMS: number): number => 250 + 110 * clamp(Math.abs(speedMS), 0, 12)

/** Below this a bed is inaudible and is stopped rather than left running silent. */
export const BED_STOP_BELOW = 0.0004

// ── Rate limiting ───────────────────────────────────────────────────────────────────────────────────────────────

/**
 * At most `max` of anything per `key` in any sliding window of `windowS` seconds. Times are the caller's (the sim's
 * clock), so a paused game does not let anything through.
 */
export class RateLimiter {
  private readonly times = new Map<string, number[]>()

  constructor(
    private readonly max: number,
    private readonly windowS: number,
  ) {}

  /** True, and counts it, if one more fits in the window ending at `nowS`. */
  allow(key: string, nowS: number): boolean {
    const recent = (this.times.get(key) ?? []).filter((t) => nowS - t < this.windowS)
    const fits = recent.length < this.max
    if (fits) recent.push(nowS)
    this.times.set(key, recent)
    return fits
  }

  clear(): void {
    this.times.clear()
  }
}

// ── The start tones ─────────────────────────────────────────────────────────────────────────────────────────────

export interface ToneStep {
  /** Seconds after the race-control call that makes it. */
  offsetS: number
  freqHz: number
  durationS: number
  /** Peak amplitude. */
  gain: number
}

export const START_TONE_LOW_HZ = 440
export const START_TONE_HIGH_HZ = 880

/**
 * What each call makes: 'three-seconds' is three short low tones, one second apart, starting at once (at -3, -2 and
 * -1 s to the start); 'start-tone' is the one long high tone, at once. Nothing is scheduled ahead of its call, so
 * the long tone sounds on the tick the race starts.
 */
export function startTones(call: RaceControlCall): readonly ToneStep[] {
  switch (call) {
    case 'three-seconds':
      return [0, 1, 2].map((offsetS) => ({ offsetS, freqHz: START_TONE_LOW_HZ, durationS: 0.18, gain: 0.22 }))
    case 'start-tone':
      return [{ offsetS: 0, freqHz: START_TONE_HIGH_HZ, durationS: 0.9, gain: 0.22 }]
    default:
      return []
  }
}

// ── The last guard ─────────────────────────────────────────────────────────────────────────────────────────────

/** Below this (of full scale) the final limiter does not touch the signal. */
export const LIMIT_KNEE = 0.7
/** The limiter's output never reaches this: a hair under full scale. */
export const LIMIT_CEILING = 0.98

/** The limiter's transfer function: the signal itself up to the knee, then a smooth bend (tanh) toward the ceiling. Odd, increasing, never above the ceiling. */
export function softLimit(x: number): number {
  const magnitude = Math.abs(x)
  if (magnitude <= LIMIT_KNEE) return x
  const room = LIMIT_CEILING - LIMIT_KNEE
  return Math.sign(x) * (LIMIT_KNEE + room * Math.tanh((magnitude - LIMIT_KNEE) / room))
}

/** The limiter as a table over -1..1 for a `WaveShaperNode`; an input beyond that takes the end value. */
export function softLimitCurve(points = 2049): Float32Array<ArrayBuffer> {
  const curve = new Float32Array(points)
  for (let i = 0; i < points; i++) curve[i] = softLimit((i / (points - 1)) * 2 - 1)
  return curve
}

// ── The worst case ──────────────────────────────────────────────────────────────────────────────────────────────

/**
 * The most amplitude a full grid can have before the sfx and master gains: `cars` motors of one class at full
 * throttle and full speed (one of them the player's), their scrub, and rain and wind at full. An upper bound, since it
 * adds the peaks as if they all fell on the same sample. Grass is left out: a car on grass is not at full speed, and
 * a car cannot scrub and drag at once.
 */
export function worstCasePeak(classId: CarClassId, cars: number, withPlayer: boolean): number {
  const top = motorVoice({ motorRadS: noLoadRadS(classId), throttle: 1, classId })
  const motor = motorPeak(top.gain, classId)
  const motors = motor * (cars - (withPlayer ? 1 : 0)) + (withPlayer && cars > 0 ? motor * PLAYER_BOOST : 0)
  return motors + SCRUB_GAIN_MAX * cars + RAIN_GAIN_MAX + WIND_GAIN_MAX
}
