import { ZZFX } from 'zzfx'
import type { AudioBackend } from './AudioMixer'

/**
 * The game's backend: ZzFX's own `AudioContext` (which it creates on import, suspended until a key press) adopted as
 * the game's one context, and its sample builder (ADR-006). This is the only module that imports `zzfx`.
 */
export function zzfxBackend(): AudioBackend {
  return {
    ctx: ZZFX.audioContext,
    sampleRate: ZZFX.sampleRate,
    buildSamples: (...params) => ZZFX.buildSamples(...params),
  }
}
