import Phaser from 'phaser'
import type { Point, RoutePoint, TrackRuntime } from '@sim'
import type { WorldView } from '../config'
import { DEPTH } from '../race/depth'

// Palette colours (spec/00-product/art-direction.md), one per kind of thing, chosen to stand out from the ground.
const WALL = 0xff9a78
const ROUTE = 0x2a6fd6
const ROUTE_EDGE = 0x9ad4ff
const TIMING = 0xfbdc4a
const SECTOR = 0xff7a1c
const GRID = 0x5cc85a
const STAGGER = 0xeef1f6
const MARSHAL = 0xffffff
const PIT_ROUTE = 0xfa90be
const PIT_ROUTE_EDGE = 0xffe0ea
const PIT_STOP_ZONE = 0xf0bc1e
const PIT_BLOCK = 0xc05096
/** The islands inside the track and the green band round it, which the physics tells apart (`grassLookAt`). */
const GRASS_INFIELD = 0xfa8c34
const GRASS_BORDER = 0x4c98ec
/** Spacing of the dots that show which grass is which, in metres. */
const GRASS_PROBE_M = 0.25

/** Drawn above everything in the race but the HUD. */
const OVERLAY_DEPTH = DEPTH.hud - 5
/** A car's footprint, for the slot boxes (the class rows set the real values; this only has to be recognisable). */
const SLOT_LENGTH_M = 0.44
const SLOT_WIDTH_M = 0.19

/**
 * A development overlay: what the physics and timing see, drawn as one-pixel vector lines over the ground so that
 * it can be compared with the picture. Walls, the route with its half-widths, the timing line and sector gates,
 * grid and stagger slots, marshal posts, the pit lane (route, stop zone, block poses) and a dot on each patch
 * of grass that is an island or the surround. Hidden until `toggle()`; the scene binds the O key to it, in
 * development builds only.
 */
export class TrackOverlay {
  private readonly graphics: Phaser.GameObjects.Graphics

  constructor(scene: Phaser.Scene, runtime: TrackRuntime, private readonly view: WorldView) {
    this.graphics = scene.add.graphics().setDepth(OVERLAY_DEPTH).setVisible(false)
    this.draw(runtime)
  }

  get visible(): boolean {
    return this.graphics.visible
  }

  setVisible(visible: boolean): void {
    this.graphics.setVisible(visible)
  }

  /** Flips the overlay and returns whether it is now showing. */
  toggle(): boolean {
    this.graphics.setVisible(!this.graphics.visible)
    return this.graphics.visible
  }

  destroy(): void {
    this.graphics.destroy()
  }

  private px(x: number, y: number): [number, number] {
    return [this.view.originX + x * this.view.pxPerM, this.view.originY + y * this.view.pxPerM]
  }

  private line(a: Point, b: Point): void {
    const [x0, y0] = this.px(a[0], a[1])
    const [x1, y1] = this.px(b[0], b[1])
    this.graphics.lineBetween(x0, y0, x1, y1)
  }

  private polyline(points: readonly Point[], closed: boolean): void {
    const count = closed ? points.length : points.length - 1
    for (let i = 0; i < count; i++) this.line(points[i], points[(i + 1) % points.length])
  }

  private box(x: number, y: number, angle: number): void {
    const c = Math.cos(angle)
    const s = Math.sin(angle)
    const corner = (u: number, v: number): Point => [x + c * u - s * v, y + s * u + c * v]
    const l = SLOT_LENGTH_M / 2
    const w = SLOT_WIDTH_M / 2
    this.polyline([corner(-l, -w), corner(l, -w), corner(l, w), corner(-l, w)], true)
    this.line([x, y], corner(l, 0))
  }

  /** The two limits of a route: its centreline moved sideways by its half-width, to either side. */
  private routeEdges(pts: readonly RoutePoint[], closed: boolean): void {
    for (const side of [1, -1]) {
      const edge: Point[] = pts.map((p, i) => {
        const next = pts[closed ? (i + 1) % pts.length : Math.min(i + 1, pts.length - 1)]
        const prev = pts[closed ? (i - 1 + pts.length) % pts.length : Math.max(i - 1, 0)]
        const len = Math.hypot(next[0] - prev[0], next[1] - prev[1]) || 1
        return [p[0] - (side * p[2] * (next[1] - prev[1])) / len, p[1] + (side * p[2] * (next[0] - prev[0])) / len]
      })
      this.polyline(edge, closed)
    }
  }

  /** The pit lane: its route and limits, the stretch where a stop is served, and the pose a car is parked in at each block. */
  private pitLane(runtime: TrackRuntime): void {
    const pit = runtime.data.pitLane
    if (pit === undefined) return
    const g = this.graphics

    g.lineStyle(1, PIT_ROUTE_EDGE, 1)
    this.routeEdges(pit.route, false)
    g.lineStyle(1, PIT_ROUTE, 1)
    this.polyline(pit.route.map((p): Point => [p[0], p[1]]), false)

    g.lineStyle(1, PIT_STOP_ZONE, 1)
    for (const s of [pit.stopZone.fromS, pit.stopZone.toS]) {
      const pose = runtime.pitRoutePose(s)
      if (pose === null) continue
      const near = runtime.nearestPitRoute(pose.x, pose.y)
      if (near === null) continue
      const nx = -Math.sin(pose.angle) * near.halfWidthM
      const ny = Math.cos(pose.angle) * near.halfWidthM
      this.line([pose.x - nx, pose.y - ny], [pose.x + nx, pose.y + ny])
    }

    g.lineStyle(1, PIT_BLOCK, 1)
    for (const block of pit.blocks) this.box(block.pose.x, block.pose.y, block.pose.angle)
  }

  /** A dot on every spot of grass, in the colour of its kind, where the physics says it is an island or the surround. */
  private grass(runtime: TrackRuntime): void {
    const g = this.graphics
    const { w, h } = runtime.data.bounds
    for (let x = GRASS_PROBE_M / 2; x < w; x += GRASS_PROBE_M) {
      for (let y = GRASS_PROBE_M / 2; y < h; y += GRASS_PROBE_M) {
        const look = runtime.grassLookAt(x, y)
        if (look === null || look === 'outfield') continue
        g.fillStyle(look === 'infield' ? GRASS_INFIELD : GRASS_BORDER, 1)
        const [px, py] = this.px(x, y)
        g.fillRect(px - 1, py - 1, 2, 2)
      }
    }
  }

  private draw(runtime: TrackRuntime): void {
    const g = this.graphics
    const { data } = runtime

    this.grass(runtime)

    g.lineStyle(1, WALL, 1)
    for (const wall of runtime.wallSegments()) this.polyline(wall.polyline, wall.closed)

    const pts = data.route.points
    g.lineStyle(1, ROUTE_EDGE, 1)
    this.routeEdges(pts, true)
    g.lineStyle(1, ROUTE, 1)
    this.polyline(pts.map((p): Point => [p[0], p[1]]), true)

    this.pitLane(runtime)

    g.lineStyle(1, TIMING, 1)
    this.line(data.timing.line[0], data.timing.line[1])
    g.lineStyle(1, SECTOR, 1)
    for (const fraction of data.timing.sectorFractions) {
      const pose = runtime.routePose(fraction * runtime.lengthM)
      const { halfWidthM } = runtime.nearestRoute(pose.x, pose.y)
      const nx = -Math.sin(pose.angle) * halfWidthM
      const ny = Math.cos(pose.angle) * halfWidthM
      this.line([pose.x - nx, pose.y - ny], [pose.x + nx, pose.y + ny])
    }

    g.lineStyle(1, GRID, 1)
    for (const slot of data.grid) this.box(slot.x, slot.y, slot.angle)
    g.lineStyle(1, STAGGER, 1)
    for (const slot of data.staggerStart) this.box(slot.x, slot.y, slot.angle)

    g.lineStyle(1, MARSHAL, 1)
    for (const post of data.marshalPosts) {
      this.line([post.x - 0.1, post.y], [post.x + 0.1, post.y])
      this.line([post.x, post.y - 0.1], [post.x, post.y + 0.1])
    }
  }
}
