import { cleanName, NO_NAME } from './name'
import type { SaveData } from './storage'
import { saves } from './store'

// The player's name (F-407): what the screens call the person at the keyboard. It is view-side only: the sim's id
// for the player stays 'player'. `playerName()` is the one function that hands it out; every table asks it.

/** The name the player gave, or null. */
export const storedName = (data: SaveData): string | null => data.settings.driverName

/**
 * What every screen calls the player: the name that was set, or YOU. Read from the game's save, so that no screen has
 * its own idea of it.
 */
export const playerName = (): string => storedName(saves.read()) ?? NO_NAME

/** The save with the player's name set (cleaned), or cleared when `name` is null or nothing but spaces. */
export function withDriverName(data: SaveData, name: string | null): SaveData {
  const driverName = name === null ? null : cleanName(name)
  return driverName === data.settings.driverName ? data : { ...data, settings: { ...data.settings, driverName } }
}

