import type Phaser from 'phaser'
import type { Vec2 } from '@sim'
import { THEME, type TextSize } from './theme'

/** The pixel font's name in the manifest and the bitmap-font cache. */
export const FONT = 'pixel'

/**
 * A line of text in the game's pixel font (ADR-006), top-left at `pos`, at one of the four sizes. A "\n" starts a
 * new line. Colour is white; change it with `setTint`.
 */
export function text(scene: Phaser.Scene, pos: Vec2, value: string, size: TextSize = 'body'): Phaser.GameObjects.BitmapText {
  return scene.add.bitmapText(pos.x, pos.y, FONT, value).setScale(THEME.sizes[size]).setTint(THEME.colours.text)
}

/** Changes the words only when they are different, so that a text that has not changed costs nothing. */
export function setTextIfChanged(object: Phaser.GameObjects.BitmapText, value: string): void {
  if (object.text !== value) object.setText(value)
}
