import type Phaser from 'phaser'
import { THEME, lineHeight } from './theme'
import { PANEL_NAME, type Rect } from './layout'
import { Skin } from './skin'
import { text } from './text'

export { PANEL_NAME } from './layout'

/** Space between a panel's title and what is below it. */
const TITLE_GAP = 16

/**
 * A panel in the drawn skin (F-802: `THEME.skin.panel`, or another skin such as a podium step) and, if asked, a title in
 * its top-left corner. Its outside edge is also a rectangle named `PANEL_NAME` that draws nothing, so that tools (the debug
 * hook) find the panels on screen as they always have.
 */
export class Panel {
  /** The panel's outside edge. */
  readonly rect: Rect
  /** The room inside, after the padding and the title: where content goes. */
  readonly inner: Rect
  private readonly parts: Phaser.GameObjects.GameObject[] = []
  private readonly skin: Skin

  constructor(scene: Phaser.Scene, rect: Rect, opts: { title?: string; skin?: string } = {}) {
    this.rect = { ...rect }
    this.parts.push(scene.add.rectangle(rect.x, rect.y, rect.w, rect.h, THEME.colours.panel).setOrigin(0, 0).setAlpha(0).setName(PANEL_NAME))
    this.skin = new Skin(scene, opts.skin ?? THEME.skin.panel).place(this.rect)
    const pad = THEME.padding
    let top = rect.y + pad
    if (opts.title !== undefined) {
      this.parts.push(text(scene, { x: rect.x + pad, y: top }, opts.title, 'small').setTint(THEME.colours.accent))
      top += lineHeight('small') + TITLE_GAP
    }
    this.inner = { x: rect.x + pad, y: top, w: rect.w - 2 * pad, h: rect.y + rect.h - pad - top }
  }

  destroy(): void {
    this.skin.destroy()
    for (const part of this.parts) part.destroy()
    this.parts.length = 0
  }
}
