import type { Bindings } from '../input/bindings'
import { sameBindings } from '../input/bindings'
import type { SaveData } from './storage'

// The settings the options screen changes (F-801), each as a function from one save to the next, like `withSpeech`: the
// same save, unchanged, when the value is what it already is, so that nothing is written for it.

/** The three volumes of the mixer. */
export type VolumeChannel = keyof SaveData['settings']['volume']

/** The save with one volume set (0..1; anything else is brought into range). */
export function withVolume(data: SaveData, channel: VolumeChannel, level: number): SaveData {
  const value = Math.min(1, Math.max(0, Number.isFinite(level) ? level : 0))
  if (data.settings.volume[channel] === value) return data
  return { ...data, settings: { ...data.settings, volume: { ...data.settings.volume, [channel]: value } } }
}

/** The save with DRIVING ASSISTANCE (F-811) on or off. */
export function withDrivingAssistance(data: SaveData, on: boolean): SaveData {
  return data.settings.drivingAssistance === on ? data : { ...data, settings: { ...data.settings, drivingAssistance: on } }
}

/** The save with these key bindings. */
export function withBindings(data: SaveData, bindings: Bindings): SaveData {
  return sameBindings(data.settings.bindings, bindings) ? data : { ...data, settings: { ...data.settings, bindings: { ...bindings } } }
}

/** Who has a voice of his own to choose. */
export type VoiceSpeaker = 'commentator' | 'official'

/** The save with a speaker's voice set by name; null leaves the choice to the game (F-708). */
export function withVoice(data: SaveData, who: VoiceSpeaker, name: string | null): SaveData {
  const key = who === 'commentator' ? 'commentatorVoice' : 'officialVoice'
  return data.settings[key] === name ? data : { ...data, settings: { ...data.settings, [key]: name } }
}
