import type Phaser from 'phaser'
import { THEME } from './theme'

/** The bar's size and the line round it, in logical pixels. */
export const BAR = { w: 640, h: 28, border: 4 } as const

/**
 * A progress bar of plain rectangles (F-803), so that it can be drawn before the pixel font has arrived: an empty track
 * with a frame, and the filled part growing from the left. `set` takes the share done, 0..1.
 */
export class LoadingBar {
  readonly parts: Phaser.GameObjects.Rectangle[]
  private readonly fill: Phaser.GameObjects.Rectangle
  private share = 0

  constructor(scene: Phaser.Scene, centre: { x: number; y: number }, name = 'loading-bar') {
    const left = centre.x - BAR.w / 2
    const top = centre.y - BAR.h / 2
    const frame = scene.add.rectangle(left - BAR.border, top - BAR.border, BAR.w + 2 * BAR.border, BAR.h + 2 * BAR.border, THEME.colours.border).setOrigin(0, 0)
    const track = scene.add.rectangle(left, top, BAR.w, BAR.h, THEME.colours.barTrack).setOrigin(0, 0)
    this.fill = scene.add.rectangle(left, top, BAR.w, BAR.h, THEME.colours.barFill).setOrigin(0, 0).setName(name)
    this.parts = [frame, track, this.fill]
    this.set(0)
  }

  /** The share shown, 0..1. */
  get progress(): number {
    return this.share
  }

  set(share: number): void {
    this.share = Math.min(1, Math.max(0, Number.isFinite(share) ? share : 0))
    this.fill.setSize(Math.max(1, Math.round(BAR.w * this.share)), BAR.h)
    this.fill.setVisible(this.share > 0)
  }

  destroy(): void {
    for (const part of this.parts) part.destroy()
  }
}
