import { createRng, type CarColour } from '@sim'

// The podium's confetti (F-802) as numbers: where each flake starts, how fast it falls and sways, and its colour. Pure, so
// it is tested without an engine; `Confetti` (Confetti.ts) draws it. The looks have their own seeded sequence and never
// draw from the sim's.

export const CONFETTI = {
  count: 140,
  /** How far above the top of the screen a flake may start, px: the burst arrives over the first seconds. */
  spreadPx: 900,
  /** Falling speed, px/s, from the slowest to the fastest flake. */
  fallPxS: [190, 300] as const,
  /** How far a flake swings to either side, px, and how many swings a second at most. */
  swayPx: 18,
  swayHz: [0.6, 1.4] as const,
  /** The bottom of the screen and a flake's size: past this it is gone. */
  floorPx: 1080,
  /** By this many seconds after the podium appears, every flake has fallen out of sight. */
  lastS: 11,
} as const

const COLOURS: readonly CarColour[] = ['red', 'blue', 'yellow', 'green', 'white', 'orange', 'pink']

export interface Flake {
  x: number
  /** Where it starts, above the screen (negative). */
  y0: number
  fallPxS: number
  swayHz: number
  phase: number
  colour: CarColour
  /** Its first frame of the four turns. */
  frame: number
}

/** The flakes of one podium, from `seed`, over a screen `width` px wide. Colours go round the seven in turn. */
export function confettiFlakes(seed: number, width: number): Flake[] {
  const rng = createRng(seed >>> 0)
  return Array.from({ length: CONFETTI.count }, (_, i) => ({
    x: Math.round(rng.range(8, width - 8)),
    y0: -8 - Math.round(rng.range(0, CONFETTI.spreadPx)),
    fallPxS: rng.range(CONFETTI.fallPxS[0], CONFETTI.fallPxS[1]),
    swayHz: rng.range(CONFETTI.swayHz[0], CONFETTI.swayHz[1]),
    phase: rng.range(0, Math.PI * 2),
    colour: COLOURS[i % COLOURS.length] ?? 'white',
    frame: rng.int(0, 3),
  }))
}

/** Where a flake is `t` seconds after the podium appeared, in whole screen pixels. */
export function flakeAt(flake: Flake, t: number): { x: number; y: number } {
  return {
    x: Math.round(flake.x + CONFETTI.swayPx * Math.sin(flake.phase + 2 * Math.PI * flake.swayHz * t)),
    y: Math.round(flake.y0 + flake.fallPxS * t),
  }
}
