// The sequence that unlocks the tuning tools in the released game (F-813): letters in, "done" out. Pure: no Phaser, no DOM,
// so it is tested in Node. Where the keys come from is `tools.ts`'s business.

/** The letters, in order, that unlock the tuning panel (T) and the racing lines (L) for the rest of the page's life. */
export const UNLOCK_CODE = 'FUJIWARA'

/** The part of a DOM key event the code reads (a `KeyboardEvent` has it). */
export interface CodeKey {
  /** What the key makes: `f`, `F`, `ArrowUp`, `Enter`. */
  key?: string
  /** The key's place on the keyboard (`KeyF`): the same whatever the layout. */
  code?: string
  ctrlKey?: boolean
  metaKey?: boolean
  altKey?: boolean
}

/**
 * The capital letter a key event types, or null for anything that is not a letter: arrows, Enter, Escape, digits,
 * punctuation, modifier keys, and a letter held with Ctrl, Cmd or Alt (a shortcut, not a letter). A letter of another
 * alphabet (`ф` on the key where a Latin keyboard has A) counts as the letter at that place; punctuation never does.
 */
export function letterOf(event: CodeKey): string | null {
  if (event.ctrlKey === true || event.metaKey === true || event.altKey === true) return null
  const typed = event.key
  if (typed === undefined) return null
  if (/^[A-Za-z]$/.test(typed)) return typed.toUpperCase()
  if (!/^\p{L}$/u.test(typed)) return null
  const place = /^Key([A-Z])$/.exec(event.code ?? '')
  return place?.[1] ?? null
}

/** Reads key events against a code. */
export interface CodeReader {
  /** Takes one key event; true when it is the last letter of the code. A key that is not a letter changes nothing. */
  feed(event: CodeKey): boolean
  /** How many letters of the code the letters typed last make, for the tests. */
  progress(): number
}

/**
 * A reader for `code`. A wrong letter starts the sequence again from that letter if it begins the code (FFUJIWARA
 * completes), and from nothing otherwise; letters typed in between are the only thing that resets it.
 */
export function createCodeReader(code: string = UNLOCK_CODE): CodeReader {
  let tail = ''
  const overlap = (): number => {
    for (let n = Math.min(tail.length, code.length); n > 0; n--) if (tail.endsWith(code.slice(0, n))) return n
    return 0
  }
  return {
    feed(event) {
      const letter = letterOf(event)
      if (letter === null) return false
      tail = (tail + letter).slice(-code.length)
      return tail === code
    },
    progress: overlap,
  }
}
