import type { SimEvent } from '@sim'

type SimEventType = SimEvent['type']
type Listener = (event: SimEvent) => void

/**
 * The one stream of sim events (architecture.md, "The view"): HUD, commentary, audio and effects subscribe here
 * and nothing polls the sim for "did X just happen". The scene emits each frame's events once.
 */
export class EventBus {
  private readonly listeners = new Map<SimEventType, Listener[]>()

  /** Calls `fn` for every event of `type` emitted from now on. Returns a function that unsubscribes (safe to call twice). */
  on<T extends SimEventType>(type: T, fn: (event: Extract<SimEvent, { type: T }>) => void): () => void {
    const isType = (event: SimEvent): event is Extract<SimEvent, { type: T }> => event.type === type
    // One wrapper per registration, so the same function registered twice is delivered to twice and removed one by one.
    const listener: Listener = (event) => {
      if (isType(event)) fn(event)
    }
    // A fresh array on every change, never an in-place edit: a delivery under way keeps the list it began with.
    this.listeners.set(type, [...(this.listeners.get(type) ?? []), listener])
    return () => {
      const current = this.listeners.get(type)
      const at = current?.indexOf(listener) ?? -1
      if (current !== undefined && at >= 0) this.listeners.set(type, current.filter((l) => l !== listener))
    }
  }

  /** Delivers each event, in order, to the listeners subscribed to its type when delivery of that event began. */
  emit(events: readonly SimEvent[]): void {
    for (const event of events) {
      const list = this.listeners.get(event.type)
      if (list === undefined) continue
      for (const listener of list) listener(event)
    }
  }

  clear(): void {
    this.listeners.clear()
  }
}
