import Phaser from 'phaser'
import { baseGameConfig } from './engine'
import { BootScene } from './scenes/BootScene'
import { CreditsScene } from './scenes/CreditsScene'
import { EventSetupScene } from './scenes/EventSetupScene'
import { GarageScene } from './scenes/GarageScene'
import { InitialsScene } from './scenes/InitialsScene'
import { LeaderboardScene } from './scenes/LeaderboardScene'
import { OptionsScene } from './scenes/OptionsScene'
import { PauseScene } from './scenes/PauseScene'
import { PodiumScene } from './scenes/PodiumScene'
import { QuickRaceScene } from './scenes/QuickRaceScene'
import { RaceScene } from './scenes/RaceScene'
import { ResultsScene } from './scenes/ResultsScene'
import { SessionIntroScene } from './scenes/SessionIntroScene'
import { StandingsScene } from './scenes/StandingsScene'
import { TitleScene } from './scenes/TitleScene'
import { ErrorScene } from './lifecycle/ErrorScene'
import { startFailure, WEBGL_UNAVAILABLE } from './lifecycle/failure'
import { showFailureDom } from './lifecycle/failure-dom'
import { watchGraphics } from './lifecycle/context'
import { webglAvailable } from './lifecycle/webgl'
import { watchForCode } from './input/tools'
import { hasReadout } from './ui/readout'
import { announceUnlock, ToolsToastScene } from './ui/ToolsToast'

// The debug hook exists in development and test builds only; production and the demo build never load it. It is
// loaded before the game exists so that it is in place before the first scene runs. The tuning tools (the panel of F-206
// and the racing lines of F-301) are on from the start in development, test and the demo build (`vite build --mode demo`),
// and work without the hook. In the released game they are chunks of their own that the page fetches only once the player
// has typed the code (F-813): nothing that production loads at start imports them. Each build switch is written out where it
// is used, in full: the bundler does not fold a constant shared between modules, and a switch it cannot fold would leave
// the code behind it in the production bundle. Keep these expressions the same as the one in RaceScene.ts.
const installHook = import.meta.env.DEV || import.meta.env.MODE === 'test' ? (await import('./debug/hook')).installDebugHook : null

/** The tuning panel's code (with Tweakpane) and the racing-line overlay's: the two dynamic imports of the tools, and the only ones besides the overlay's in RaceScene. */
const loadPanel = (): Promise<typeof import('./debug/TuningPanel')> => import('./debug/TuningPanel')
const loadLines = (): Promise<typeof import('./debug/RacingLineOverlay')> => import('./debug/RacingLineOverlay')

const installTuning =
  import.meta.env.DEV || import.meta.env.MODE === 'test' || import.meta.env.MODE === 'demo' ? (await loadPanel()).installTuningTools : null

// A browser with no WebGL (or one that will not start it) gets a page that says so, not a blank one (F-803): there is no engine to draw it with, so it is HTML.
function startGame(): Phaser.Game | null {
  if (!webglAvailable()) {
    showFailureDom(WEBGL_UNAVAILABLE)
    return null
  }
  try {
    return new Phaser.Game({ ...baseGameConfig, scene: [BootScene, TitleScene, GarageScene, QuickRaceScene, EventSetupScene, SessionIntroScene, StandingsScene, PodiumScene, RaceScene, ResultsScene, InitialsScene, LeaderboardScene, PauseScene, OptionsScene, CreditsScene, ErrorScene, ToolsToastScene] })
  } catch (error) {
    showFailureDom(startFailure(error instanceof Error ? error.message : ''))
    return null
  }
}

/** The options screen is waiting for a key to bind: that key press is a binding, not a letter of the code. */
function bindingAKey(game: Phaser.Game): boolean {
  const options = game.scene.getScene('Options')
  return game.scene.isActive('Options') && hasReadout(options) && options.readout().values.capturing !== ''
}

/**
 * The tools' code is fetched at the moment of the unlock, not at the first press of T or L: the player has asked for them by
 * typing the code, T then opens the panel at once with no wait on a download in the middle of a race, and until then no
 * request is made for either chunk. The panel's own T key starts working when `installTuningTools` has run.
 */
async function loadTools(game: Phaser.Game): Promise<void> {
  const [panel] = await Promise.all([loadPanel(), loadLines()])
  panel.installTuningTools(game)
}

const game = startGame()
if (game !== null) {
  if (game.isBooted) watchGraphics(game)
  else game.events.once(Phaser.Core.Events.READY, () => watchGraphics(game))
  const tuning = installTuning?.(game) ?? null
  installHook?.(game, tuning)
  // The code (F-813). Where the tools are on from the start it does nothing; in the released game it unlocks them for the page's life.
  watchForCode(game, window, {
    startUnlocked: import.meta.env.DEV || import.meta.env.MODE === 'test' || import.meta.env.MODE === 'demo',
    capturing: () => bindingAKey(game),
    onUnlock: () => {
      announceUnlock(game)
      loadTools(game).catch((error: unknown) => console.error('The tuning tools could not be loaded', error))
    },
  })
}
