import type { Rect } from './layout'

// Where the nine pieces of a skin go over a rectangle of the screen (F-802). Pure, so that the rule is tested without an
// engine; `Skin` (skin.ts) puts the pictures there.

/** The pieces of a nine-slice, by the names the art build gives them. */
export const NINE = ['nw', 'n', 'ne', 'w', 'c', 'e', 'sw', 's', 'se'] as const
export type Piece = (typeof NINE)[number]

/** How far in from each side the corners reach, in screen pixels. */
export interface Insets {
  left: number
  right: number
  top: number
  bottom: number
}

/** The insets of a skin from its corner pieces' sizes in art pixels (the top-left one and the bottom-right one), at `scale` screen pixels an art pixel. */
export function insetsOf(nw: { w: number; h: number }, se: { w: number; h: number }, scale: number): Insets {
  return { left: nw.w * scale, right: se.w * scale, top: nw.h * scale, bottom: se.h * scale }
}

/**
 * The box each piece covers: the corners at their own size in their corners, the edges stretched along their side, the
 * middle stretched to fill. Together they cover `rect` exactly. Throws for a rectangle that the corners do not fit.
 */
export function nineSliceRects(rect: Rect, insets: Insets): Record<Piece, Rect> {
  const { x, y, w, h } = rect
  const { left, right, top, bottom } = insets
  const midW = w - left - right
  const midH = h - top - bottom
  if (midW < 0 || midH < 0) throw new Error(`nineSliceRects: a ${w} x ${h} box is smaller than its corners`)
  const xs = [x, x + left, x + w - right] as const
  const ys = [y, y + top, y + h - bottom] as const
  const ws = [left, midW, right] as const
  const hs = [top, midH, bottom] as const
  const out = {} as Record<Piece, Rect>
  NINE.forEach((piece, i) => {
    const column = i % 3
    const row = Math.floor(i / 3)
    out[piece] = { x: xs[column], y: ys[row], w: ws[column], h: hs[row] }
  })
  return out
}
