import Phaser from 'phaser'
import { CLASS_ORDER } from '@content/classes'
import { LOGICAL_HEIGHT, LOGICAL_WIDTH } from '../config'
import { mixerOf } from '../audio'
import { Sfx } from '../audio/Sfx'
import { musicOf, toggleMusic } from '../audio/music'
import { ttsOf, type Tts } from '../audio/Tts'
import { ACTIONS, ACTION_LABELS, DEFAULT_BINDINGS, keyLabel, rebind, type Action } from '../input/bindings'
import { onKeyPresses, type KeyPress } from '../input/keys'
import { saves, speechOn, toggleSpeech, withBindings, withDrivingAssistance, withVoice, withVolume, type VoiceSpeaker, type VolumeChannel } from '../persistence'
import { RACE_DAY_KEY } from '../raceday/RaceDayController'
import { PLAYER_COLOURS, selection } from '../state/selection'
import {
  ConfirmDialog,
  FocusRing,
  Panel,
  Row,
  THEME,
  VOLUME_STEPS,
  buttonLine,
  charWidth,
  choiceLine,
  nearestStep,
  setTextIfChanged,
  text,
  valueLine,
  voiceOptions,
  volumeLabel,
  type HasReadout,
  type Rect,
  type RowColumns,
  type RowTone,
  type ScreenReadout,
} from '../ui'

/** Where the options were opened from: the title (leaving goes back to it), or the pause menu of a race (leaving closes the options over it). */
export interface OptionsInit {
  from?: 'title' | 'pause'
}

const LEFT_PANEL: Rect = { x: 60, y: 116, w: 1020, h: 790 }
const RIGHT_PANEL: Rect = { x: 1110, y: 116, w: 750, h: 790 }
const PITCH = 56
const SECTION_GAP = 34
const ROW_SIZE = 'body'
const SOUND_COLUMNS: RowColumns = { label: 14, value: 26 }
const CONTROL_COLUMNS: RowColumns = { label: 18, value: 12 }

/** What the scene says in its bottom line, and the key line under it. */
const HINT = '↑ ↓ MOVE   ← → CHANGE   ENTER CHOOSE   ESC BACK'
const NO_SPEECH = 'THIS BROWSER HAS NO VOICES, SO THE COMMENTARY STAYS IN WRITING.'
/** Under the DRIVING ASSISTANCE row (F-811): what it does, in two lines of the small size. */
const ASSISTANCE_NOTE = ['AN EASIER CAR: MORE GRIP, GENTLER THROTTLE AND', 'STEERING. LAPS ARE MARKED (A*).']
const RESET_QUESTION =
  'RESET ALL SAVED DATA? THE LEADERBOARDS WILL BE ERASED, AND SO WILL YOUR SETTINGS, YOUR BEST TIMES AND ANY EVENT IN PROGRESS. THIS CANNOT BE UNDONE. THE GAME GOES BACK TO THE TITLE WITH ITS DEFAULTS.'

/** The wait between a volume changing and the blip that shows the new level, s: the mixer's gain takes a moment to settle. */
const BLIP_DELAY_MS = 90
/** How often the voice list is looked at again, ms: a browser loads its voices late. */
const VOICES_POLL_MS = 500

type Column = 'sound' | 'controls'

/** One line of the screen: what it says, whether the focus can land on it, and what the keys do to it. */
interface Entry {
  id: string
  row: Row
  enabled(): boolean
  line(focused: boolean): string
  /** Left and right. */
  change?(delta: 1 | -1): void
  /** Enter. */
  activate?(): void
}

/**
 * The options (F-801): the volumes, music and voices with the keys that switch them in a race, the two voices that speak
 * (the commentator's and the official's, natural ones only) with a test, DRIVING ASSISTANCE (F-811), the five driving keys,
 * and the two resets. Opened from the title, or over the pause menu of a race (which then goes on exactly where it was).
 * Everything is saved the moment it changes, and the volumes are applied to the mixer at once.
 */
export class OptionsScene extends Phaser.Scene implements HasReadout {
  private from: 'title' | 'pause' = 'title'
  private entries: Entry[] = []
  private ring = new FocusRing([])
  private panels: Panel[] = []
  private parts: Phaser.GameObjects.GameObject[] = []
  private notes: Phaser.GameObjects.BitmapText | null = null
  private message: Phaser.GameObjects.BitmapText | null = null
  private release: (() => void) | null = null
  private dialog: ConfirmDialog | null = null
  private sfx: Sfx | null = null
  private tts: Tts | null = null
  /** The action whose key is being chosen, while the next key press is the new binding. */
  private capturing: Action | null = null
  private voiceNames: string[] = []
  private voicesReady = false
  private voicesCheckedAt = 0
  private handled = 0
  private blipsAsked = 0
  private blipLevel = -1
  private said = ''
  private columnY: Record<Column, number> = { sound: 0, controls: 0 }

  constructor() {
    super('Options')
  }

  init(data: OptionsInit): void {
    this.from = data.from ?? 'title'
  }

  create(): void {
    this.handled = 0
    this.blipsAsked = 0
    this.blipLevel = -1
    this.said = ''
    this.capturing = null
    this.entries = []
    const mixer = mixerOf(this.registry)
    this.sfx = mixer === null ? null : new Sfx(mixer)
    this.tts = ttsOf(this.registry, () => mixer?.voiceVolume() ?? 1)
    this.cameras.main.setBackgroundColor(this.from === 'pause' ? 0x000000 : THEME.colours.background)
    if (this.from === 'pause') this.parts.push(this.add.rectangle(0, 0, LOGICAL_WIDTH, LOGICAL_HEIGHT, THEME.colours.shade, 0.92).setOrigin(0, 0))

    this.parts.push(text(this, { x: LOGICAL_WIDTH / 2, y: 28 }, 'OPTIONS', 'large').setOrigin(0.5, 0).setTint(THEME.colours.accent))
    const sound = new Panel(this, LEFT_PANEL, { title: 'SOUND' })
    const controls = new Panel(this, RIGHT_PANEL, { title: 'CONTROLS' })
    this.panels.push(sound, controls)
    this.columnY = { sound: sound.inner.y, controls: controls.inner.y }

    this.refreshVoices()
    this.buildSound(sound.inner)
    this.buildControls(controls.inner)

    this.message = text(this, { x: LOGICAL_WIDTH / 2, y: 930 }, '', 'body').setOrigin(0.5, 0).setTint(THEME.colours.accent)
    this.parts.push(this.message, text(this, { x: LOGICAL_WIDTH / 2, y: 1008 }, HINT, 'small').setOrigin(0.5, 0).setTint(THEME.colours.textDim))
    this.paint()

    this.release = onKeyPresses(this, (press) => this.onPress(press))
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, this.dispose, this)
  }

  readout(): ScreenReadout {
    const { settings } = saves.read()
    return {
      focus: this.dialog === null ? this.ring.current : 'dialog',
      values: {
        handled: this.handled,
        master: settings.volume.master,
        sfx: settings.volume.sfx,
        voiceVolume: settings.volume.voice,
        music: settings.music ? 1 : 0,
        speech: settings.tts ? 1 : 0,
        assistance: settings.drivingAssistance ? 1 : 0,
        commentatorVoice: settings.commentatorVoice ?? '',
        officialVoice: settings.officialVoice ?? '',
        voicesAvailable: this.voicesReady ? 1 : 0,
        voiceChoices: this.voiceNames.length,
        throttle: settings.bindings.throttle,
        brake: settings.bindings.brake,
        left: settings.bindings.left,
        right: settings.bindings.right,
        pause: settings.bindings.pause,
        capturing: this.capturing ?? '',
        message: this.said,
        blipsAsked: this.blipsAsked,
        blipsPlayed: this.sfx?.played ?? 0,
        blipLevel: this.blipLevel,
        from: this.from,
      },
    }
  }

  update(time: number): void {
    if (time - this.voicesCheckedAt < VOICES_POLL_MS) return
    this.voicesCheckedAt = time
    if (this.refreshVoices()) this.paint()
  }

  // ── The rows ────────────────────────────────────────────────────────────────────────────────────────────────

  private buildSound(inner: Rect): void {
    const volume = (id: string, label: string, channel: VolumeChannel): void =>
      this.addRow(
        'sound',
        inner,
        {
          id,
          enabled: () => true,
          line: (focused) => choiceLine(focused, label, volumeLabel(this.volumeOf(channel)), SOUND_COLUMNS),
          change: (delta) => this.stepVolume(channel, delta),
        },
        0,
      )
    volume('master', 'MASTER VOLUME', 'master')
    volume('sfx', 'EFFECTS VOLUME', 'sfx')
    volume('voice-volume', 'VOICE VOLUME', 'voice')
    this.addRow('sound', inner, { id: 'music', enabled: () => true, line: (focused) => choiceLine(focused, 'MUSIC [M]', this.onOff(saves.read().settings.music), SOUND_COLUMNS), change: () => this.toggleMusicNow(), activate: () => this.toggleMusicNow() }, SECTION_GAP / 2)
    this.addRow(
      'sound',
      inner,
      {
        id: 'speech',
        enabled: () => this.voicesReady,
        line: (focused) => (this.voicesReady ? choiceLine(focused, 'VOICES [V]', this.onOff(speechOn()), SOUND_COLUMNS) : valueLine(focused, 'VOICES [V]', 'NOT AVAILABLE', SOUND_COLUMNS)),
        change: () => this.toggleSpeechNow(),
        activate: () => this.toggleSpeechNow(),
      },
      0,
    )
    this.heading('sound', inner, 'WHO SPEAKS', SECTION_GAP)
    this.addRow('sound', inner, this.voiceEntry('commentator', 'COMMENTATOR'), 6)
    this.addRow('sound', inner, this.voiceEntry('official', 'OFFICIAL'), 0)
    this.notes = text(this, { x: inner.x, y: this.columnY.sound + 6 }, '', 'small').setTint(THEME.colours.textDim)
    this.parts.push(this.notes)
    this.columnY.sound += 40
  }

  private buildControls(inner: Rect): void {
    this.addRow(
      'controls',
      inner,
      { id: 'assistance', enabled: () => true, line: (focused) => choiceLine(focused, 'DRIVING ASSISTANCE', this.onOff(saves.read().settings.drivingAssistance), CONTROL_COLUMNS), change: () => this.toggleAssistance(), activate: () => this.toggleAssistance() },
      0,
    )
    // What it does, in a line under the row.
    ASSISTANCE_NOTE.forEach((line, i) => this.parts.push(text(this, { x: inner.x + charWidth(ROW_SIZE) * 2, y: this.columnY.controls - 8 + i * 26 }, line, 'small').setTint(THEME.colours.textDim)))
    this.columnY.controls += ASSISTANCE_NOTE.length * 26 - 8
    this.heading('controls', inner, 'KEYS', SECTION_GAP)
    for (const action of ACTIONS) {
      this.addRow(
        'controls',
        inner,
        {
          id: action,
          enabled: () => true,
          line: (focused) => valueLine(focused, ACTION_LABELS[action], this.capturing === action ? 'PRESS A KEY' : keyLabel(saves.read().settings.bindings[action]), CONTROL_COLUMNS),
          activate: () => this.startCapture(action),
        },
        action === 'throttle' ? 6 : 0,
      )
    }
    this.addRow('controls', inner, { id: 'reset-keys', enabled: () => true, line: (focused) => buttonLine(focused, 'RESET KEYS'), activate: () => this.resetKeys() }, SECTION_GAP / 2)
    this.heading('controls', inner, 'SAVED DATA', SECTION_GAP)
    this.addRow('controls', inner, { id: 'reset-data', enabled: () => true, line: (focused) => buttonLine(focused, 'RESET ALL SAVED DATA'), activate: () => this.askReset() }, 6)
    this.addRow('controls', inner, { id: 'back', enabled: () => true, line: (focused) => buttonLine(focused, 'BACK'), activate: () => this.leave() }, SECTION_GAP)
  }

  /** A voice picker: AUTO (and whom it stands for) and the natural voices for the language, with Enter to test it; disabled where the browser has no voice. */
  private voiceEntry(who: VoiceSpeaker, label: string): Omit<Entry, 'row'> {
    return {
      id: who,
      enabled: () => this.voicesReady,
      line: (focused) => {
        if (!this.voicesReady) return valueLine(focused, label, 'NOT AVAILABLE', SOUND_COLUMNS)
        // AUTO says whom it stands for on this system: the voice the game would choose (F-816).
        return choiceLine(focused, label, voiceOptions(this.voiceNames, this.tts?.autoVoiceName(who) ?? null)[this.voiceIndex(who)]?.label ?? '', SOUND_COLUMNS)
      },
      change: (delta) => this.stepVoice(who, delta),
      activate: () => this.testVoice(who),
    }
  }

  /** Adds a row under the ones so far in a column, `gap` logical pixels lower than the pitch would put it. */
  private addRow(column: Column, inner: Rect, entry: Omit<Entry, 'row'>, gap: number): void {
    const y = this.columnY[column] + gap
    this.columnY[column] = y + PITCH
    const row = new Row(this, inner.x, y, inner.w - 2 * 12, ROW_SIZE, '')
    this.entries.push({ ...entry, row })
  }

  private heading(column: Column, inner: Rect, words: string, gap: number): void {
    const y = this.columnY[column] + gap
    this.parts.push(text(this, { x: inner.x, y }, words, 'small').setTint(THEME.colours.accent))
    this.columnY[column] = y + 30
  }

  // ── What the rows show ────────────────────────────────────────────────────────────────────────────────────

  private onOff = (on: boolean): string => (on ? 'ON' : 'OFF')

  private volumeOf(channel: VolumeChannel): number {
    return nearestStep(saves.read().settings.volume[channel])
  }

  private voiceIndex(who: VoiceSpeaker): number {
    const { settings } = saves.read()
    const saved = who === 'commentator' ? settings.commentatorVoice : settings.officialVoice
    const at = voiceOptions(this.voiceNames).findIndex((option) => option.value === saved)
    return Math.max(0, at)
  }

  private paint(): void {
    this.ring.update(this.entries.map((entry) => ({ id: entry.id, enabled: entry.enabled() })))
    const focus = this.dialog === null ? this.ring.current : null
    for (const entry of this.entries) {
      const focused = entry.id === focus
      entry.row.setLabel(entry.line(focused))
      const tone: RowTone = !entry.enabled() ? 'off' : focused ? 'focus' : 'normal'
      entry.row.setTone(tone)
    }
    if (this.notes !== null) setTextIfChanged(this.notes, this.voicesReady ? 'ENTER ON A VOICE TESTS IT' : NO_SPEECH)
    if (this.message !== null) setTextIfChanged(this.message, this.said)
  }

  private say(words: string): void {
    this.said = words
    if (this.message !== null) setTextIfChanged(this.message, words)
  }

  // ── Keys ──────────────────────────────────────────────────────────────────────────────────────────────────

  private onPress(press: KeyPress): void {
    this.handled++
    if (this.capturing !== null) {
      this.capture(press.code)
      return
    }
    if (this.dialog !== null) {
      if (press.nav !== null) this.dialog.handle(press.nav)
      return
    }
    // The same keys that switch the music and the voices in a race.
    if (press.code === 'KeyM') return this.toggleMusicNow()
    if (press.code === 'KeyV') return this.voicesReady ? this.toggleSpeechNow() : this.say('NO VOICES IN THIS BROWSER')
    switch (press.nav) {
      case 'up':
      case 'down':
        this.ring.move(press.nav === 'down' ? 1 : -1)
        this.paint()
        return
      case 'left':
      case 'right':
        this.focused()?.change?.(press.nav === 'right' ? 1 : -1)
        this.paint()
        return
      case 'confirm':
        this.focused()?.activate?.()
        this.paint()
        return
      case 'back':
        this.leave()
        return
      default:
        return
    }
  }

  private focused(): Entry | undefined {
    return this.entries.find((entry) => entry.id === this.ring.current)
  }

  // ── Changing things ───────────────────────────────────────────────────────────────────────────────────────

  /** Steps a volume by one tenth, up to the ends (no wrapping: a slider does not jump from silent to full), and applies it at once. */
  private stepVolume(channel: VolumeChannel, delta: 1 | -1): void {
    const now = this.volumeOf(channel)
    const at = VOLUME_STEPS.indexOf(now)
    const next = VOLUME_STEPS[Math.min(VOLUME_STEPS.length - 1, Math.max(0, at + delta))] ?? now
    if (next === now) return
    saves.update((data) => withVolume(data, channel, next))
    const { volume } = saves.read().settings
    mixerOf(this.registry)?.setVolumes(volume)
    this.say(`${channel === 'sfx' ? 'EFFECTS' : channel === 'voice' ? 'VOICE' : 'MASTER'} VOLUME ${volumeLabel(next)}`)
    // The blip at the new level: effects and master change what it sounds like; the voice volume is heard in a spoken line.
    this.time.delayedCall(BLIP_DELAY_MS, () => (channel === 'voice' ? this.testVoiceQuietly() : this.blip()))
  }

  private blip(): void {
    this.blipsAsked++
    this.blipLevel = saves.read().settings.volume.sfx * saves.read().settings.volume.master
    this.sfx?.play('menu-select', { gain: 1 })
  }

  private testVoiceQuietly(): void {
    if (this.voicesReady) this.tts?.sample('commentator')
  }

  private toggleMusicNow(): void {
    this.say(`MUSIC ${this.onOff(toggleMusic(this.registry))}`)
    this.paint()
  }

  private toggleSpeechNow(): void {
    this.say(`VOICES ${this.onOff(toggleSpeech())}`)
    this.paint()
  }

  private toggleAssistance(): void {
    const on = !saves.read().settings.drivingAssistance
    saves.update((data) => withDrivingAssistance(data, on))
    this.say(on ? 'DRIVING ASSISTANCE ON: THE EASIER CAR FROM THE NEXT SESSION' : 'DRIVING ASSISTANCE OFF: THE CLASS CAR FROM THE NEXT SESSION')
  }

  /** Looks at the browser's voices; true if what the pickers offer changed. Speech is "available" where there is a voice to say a line with. */
  private refreshVoices(): boolean {
    const tts = this.tts
    if (tts === null) return false
    const names = tts.voiceNames()
    const ready = tts.available
    const changed = ready !== this.voicesReady || names.join('\n') !== this.voiceNames.join('\n')
    this.voiceNames = names
    this.voicesReady = ready
    return changed
  }

  private stepVoice(who: VoiceSpeaker, delta: 1 | -1): void {
    const options = voiceOptions(this.voiceNames)
    const next = options[(this.voiceIndex(who) + delta + options.length) % options.length]
    if (next === undefined) return
    saves.update((data) => withVoice(data, who, next.value))
    this.say(`${who === 'commentator' ? 'COMMENTATOR' : 'OFFICIAL'}: ${next.label}`)
  }

  private testVoice(who: VoiceSpeaker): void {
    if (!this.voicesReady) return
    this.tts?.sample(who)
    this.say(`${who === 'commentator' ? 'THE COMMENTATOR' : 'THE OFFICIAL'} SPEAKS`)
  }

  private startCapture(action: Action): void {
    this.capturing = action
    this.say(`PRESS THE KEY FOR ${ACTION_LABELS[action]}   ESC CANCELS`)
    this.paint()
  }

  /** The key pressed while a binding is being chosen: Esc gives up, a reserved key is refused, any other becomes the binding (swapping with the action that had it). */
  private capture(code: string): void {
    const action = this.capturing
    if (action === null) return
    if (code === 'Escape') {
      this.capturing = null
      this.say('')
      this.paint()
      return
    }
    const current = saves.read().settings.bindings
    const result = rebind(current, action, code)
    if ('error' in result) {
      this.say(result.error === 'reserved' ? 'THAT KEY IS RESERVED   TRY ANOTHER, OR ESC' : 'THAT KEY CANNOT BE USED   TRY ANOTHER, OR ESC')
      return
    }
    saves.update((data) => withBindings(data, result.bindings))
    this.capturing = null
    this.say(
      result.swappedWith === null
        ? `${ACTION_LABELS[action]} IS NOW ${keyLabel(code)}`
        : `${ACTION_LABELS[action]} IS NOW ${keyLabel(code)}   ${ACTION_LABELS[result.swappedWith]} TOOK ${keyLabel(current[action])}`,
    )
    this.paint()
  }

  private resetKeys(): void {
    saves.update((data) => withBindings(data, DEFAULT_BINDINGS))
    this.say('KEYS BACK TO THE ARROWS AND P')
  }

  private askReset(): void {
    const dialog = new ConfirmDialog(this, { message: RESET_QUESTION, confirmLabel: 'ERASE EVERYTHING', cancelLabel: 'KEEP MY DATA', widthPx: 1200 })
    this.dialog = dialog
    dialog.onAnswer((confirmed) => {
      dialog.destroy()
      this.dialog = null
      if (confirmed) this.resetAll()
      else this.paint()
    })
    this.paint()
  }

  /** Clears storage and every copy of it the game holds, applies the defaults to the sound, and goes to the title. */
  private resetAll(): void {
    saves.clear()
    const { settings } = saves.read()
    mixerOf(this.registry)?.setVolumes(settings.volume)
    musicOf(this.registry)?.setEnabled(settings.music)
    this.tts?.cancel()
    this.registry.remove(RACE_DAY_KEY)
    const first = CLASS_ORDER[0]
    if (first !== undefined) selection.set({ carClass: first, colour: PLAYER_COLOURS[0] ?? 'red' })
    this.stopListening()
    if (this.from === 'pause') {
      this.scene.stop('Race')
      this.scene.stop('Pause')
    }
    this.scene.start('Title', {})
  }

  /** Closes the options: to the title, or, over a race, back to the pause menu, which resumes the race exactly where it was. */
  private leave(): void {
    this.stopListening()
    if (this.from === 'pause') {
      this.scene.stop()
      this.scene.resume('Pause')
      return
    }
    this.scene.start('Title', {})
  }

  private stopListening(): void {
    this.release?.()
    this.release = null
  }

  private dispose(): void {
    this.stopListening()
    this.dialog?.destroy()
    this.dialog = null
    // A test voice still speaking is cut off with the screen; a blip in flight is stopped.
    this.tts?.cancel()
    this.tts = null
    this.sfx?.dispose()
    this.sfx = null
    for (const entry of this.entries) entry.row.destroy()
    this.entries = []
    for (const panel of this.panels) panel.destroy()
    this.panels = []
    for (const part of this.parts) part.destroy()
    this.parts = []
    this.notes = null
    this.message = null
    this.capturing = null
  }
}
