import { markAssisted } from '../race/assistance'
import { formatLapTime } from '../race/PracticeReadout'
import type { BestRace, RoundMinutes } from './storage'

// What the screens say about saving (F-405), in one place so that a test can check every character against the pixel font.

export const CONTINUE_LABEL = 'CONTINUE'

/** Beside CONTINUE on the title: the session that is next. */
export const nextWords = (heading: string): string => `NEXT: ${heading}`

/** The question asked before a new event is started over one in progress, and its two answers. */
export const DROP_QUESTION = 'THERE IS AN EVENT IN PROGRESS. STARTING A NEW ONE DROPS IT AND ITS RESULTS SO FAR. DROP IT?'
export const DROP_CONFIRM = 'DROP IT'
export const DROP_CANCEL = 'KEEP IT'

/** Esc on the session intro and the standings leaves for the main menu; the event is saved and CONTINUE resumes it. */
export const LEAVE_WORDS = 'ESC MAIN MENU: THE EVENT IS KEPT'
export const introHint = `ENTER START   ${LEAVE_WORDS}`
export const standingsHint = (upNextIsPodium: boolean): string => `${upNextIsPodium ? 'ENTER PODIUM' : 'ENTER CONTINUE'}   ${LEAVE_WORDS}`

/** On the results screen, when the session set one; with (A*) after the time when it was driven with DRIVING ASSISTANCE (F-811). */
export const newBestLapWords = (lapMs: number, assisted = false): string => `NEW BEST LAP  ${markAssisted(formatLapTime(lapMs), assisted)}`
export const newBestRaceWords = (best: BestRace & { minutes: RoundMinutes }, assisted = false): string =>
  `NEW BEST RACE  ${best.minutes} MIN  ${best.laps} ${best.laps === 1 ? 'LAP' : 'LAPS'}  ${markAssisted(formatLapTime(best.timeMs), assisted)}`
