import type { CarId, CarState, DriverProfile, SessionKind, SessionSnapshot, SimEvent, Sky } from '@sim'
import { formatTime, ordinalWord, skyText, type FillValues } from './fill'
import type { CommentaryRng } from './rng'
import { COMMENTARY_TUNING as T } from './tuning'
import type { CommentaryContext, LineTrigger } from './types'
import { eventPlaceCondition, type Condition } from './vocabulary'

// Events to candidates (F-701). A candidate is a *group*: the moment (its trigger, the conditions that hold in it,
// what can be said about it) rather than one line. The engine chooses the line from the library when it is asked,
// so cooldowns and variety are judged then and not when the event happened.

/** The few fields of a snapshot the engine reads, copied: the session reuses its snapshot buffer. */
export interface CarDigest {
  readonly id: CarId
  readonly position: number
  readonly lap: number
  readonly bestLapMs: number | null
  readonly gapAheadMs: number | null
  readonly state: CarState
}
export interface Digest {
  readonly phase: SessionSnapshot['phase']
  readonly clockRemainingS: number
  readonly sky: Sky
  readonly wetness: number
  readonly cars: readonly CarDigest[]
}

export function digestOf(snapshot: SessionSnapshot): Digest {
  return {
    phase: snapshot.phase,
    clockRemainingS: snapshot.clockRemainingS,
    sky: snapshot.weather.sky,
    wetness: snapshot.weather.wetness,
    cars: snapshot.cars.map((car) => ({ id: car.id, position: car.position, lap: car.lap, bestLapMs: car.bestLapMs, gapAheadMs: car.gapAheadMs, state: car.state })),
  }
}

/** Who is who: the session's entries joined to the roster. */
export interface Driver {
  readonly carId: CarId
  readonly name: string
  readonly number: number
  readonly colour: string
  readonly facts: readonly string[]
  readonly human: boolean
}
export interface World {
  readonly kind: SessionKind
  readonly drivers: readonly Driver[]
}

export function buildWorld(roster: readonly DriverProfile[], context: CommentaryContext): World {
  const drivers = context.entries.map((entry, carId): Driver => {
    const profile = roster.find((driver) => driver.id === entry.driverId)
    const human = entry.controller === 'human'
    const fallback = `car ${entry.number}`
    const name = human ? (context.playerName ?? profile?.shortName ?? fallback) : (profile?.shortName ?? fallback)
    return { carId, name, number: entry.number, colour: entry.colour, facts: profile?.bio ?? [], human }
  })
  return { kind: context.kind, drivers }
}

/** One moment that may be remarked on. */
export interface Group {
  readonly trigger: LineTrigger
  /** The conditions that hold in this moment. */
  readonly holds: ReadonlySet<string>
  readonly values: FillValues
  /** Added to the score of whichever template is chosen. */
  readonly bonus: number
  readonly createdAtS: number
}

/** What the engine has seen over the session that the events do not repeat. Never sim state. */
export interface DerivedState {
  /** Cars that have completed a lap: the first lap of a driver is remarked on once. */
  readonly completedLap: Set<CarId>
  /** Cars whose marshal was on his phone when they fell to him. */
  readonly distractedFor: Set<CarId>
  /** When each car now out of its driver's hands went out. */
  readonly strickenAtS: Map<CarId, number>
  /** Cars whose long wait has been remarked on while it lasted. */
  readonly longWaitTold: Set<CarId>
  /** Big kerb hops not yet called, until the car is seen not to roll. */
  hops: Array<{ car: CarId; dueS: number }>
}

export function createDerived(): DerivedState {
  return { completedLap: new Set(), distractedFor: new Set(), strickenAtS: new Map(), longWaitTold: new Set(), hops: [] }
}

export interface View {
  readonly world: World
  /** Null until a snapshot has been observed. */
  readonly digest: Digest | null
  readonly nowS: number
}

interface Spec {
  trigger: LineTrigger
  subject?: CarId | null | undefined
  other?: CarId | null | undefined
  /** The other car is named but is not what the moment is about: it counts for no condition or bonus. */
  otherNamedOnly?: boolean | undefined
  extras?: readonly Condition[] | undefined
  sky?: Sky | undefined
  time?: string | undefined
  lap?: number | undefined
  pos?: number | undefined
  leader?: boolean | undefined
  bonus?: number | undefined
}

const isRain = (sky: Sky): boolean => sky === 'light-rain' || sky === 'heavy-rain'

function make(spec: Spec, view: View): Group | null {
  const { world, digest } = view
  const car = (id: CarId | null | undefined): CarDigest | undefined => (id == null ? undefined : digest?.cars.find((one) => one.id === id))
  const driver = (id: CarId | null | undefined): Driver | undefined => (id == null ? undefined : world.drivers[id])
  const subjectCar = car(spec.subject)
  const subjectDriver = driver(spec.subject)
  if (spec.subject != null && (subjectCar === undefined || subjectDriver === undefined)) return null
  const otherCar = car(spec.other)
  const otherDriver = driver(spec.other)

  const involved = [subjectCar, spec.otherNamedOnly === true ? undefined : otherCar].filter((one) => one !== undefined)
  const involvedDrivers = [subjectDriver, spec.otherNamedOnly === true ? undefined : otherDriver].filter((one) => one !== undefined)
  const fieldSize = digest?.cars.length ?? 0

  const holds = new Set<string>(spec.extras ?? [])
  const player = involvedDrivers.some((one) => one.human)
  const leader = spec.leader ?? involved.some((one) => one.position === 1)
  if (player) holds.add('player')
  if (leader) holds.add('leader')
  if (fieldSize >= 3 && involved.some((one) => one.position === fieldSize)) holds.add('backmarker')
  if (involved.some((one) => one.gapAheadMs !== null && one.gapAheadMs < T.closeGapMs)) holds.add('close')
  if (digest !== null) {
    const wet = spec.sky !== undefined ? isRain(spec.sky) : isRain(digest.sky) || digest.wetness >= T.wetFromWetness
    holds.add(wet ? 'wet' : 'dry')
    if (world.kind !== 'practice' && digest.phase === 'running' && digest.clockRemainingS > 0 && digest.clockRemainingS <= T.lastMinuteS) holds.add('last-minute')
  } else if (spec.sky !== undefined) {
    holds.add(isRain(spec.sky) ? 'wet' : 'dry')
  }
  if (world.kind === 'final') holds.add('final')
  if (world.kind === 'qualifying') holds.add('qualifying')
  if (world.drivers.length === 2) holds.add('duel')

  const values: Record<string, string | readonly string[]> = {}
  if (subjectCar !== undefined && subjectDriver !== undefined) {
    values.name = subjectDriver.name
    values.number = String(subjectDriver.number)
    values.colour = subjectDriver.colour
    values.pos = ordinalWord(spec.pos ?? subjectCar.position)
    values.lap = String(spec.lap ?? subjectCar.lap)
    if (subjectCar.gapAheadMs !== null) values.gap = formatTime(subjectCar.gapAheadMs)
    if (subjectDriver.facts.length > 0) values.bio = subjectDriver.facts
  }
  if (otherDriver !== undefined) {
    values.other = otherDriver.name
    values.otherNumber = String(otherDriver.number)
  }
  const sky = spec.sky ?? digest?.sky
  if (sky !== undefined) values.sky = skyText(sky)
  if (spec.time !== undefined) values.time = spec.time

  const bonus = (player ? T.playerBonus : 0) + (leader ? T.leaderBonus : 0) + (spec.bonus ?? 0)
  return { trigger: spec.trigger, holds, values: values as FillValues, bonus, createdAtS: view.nowS }
}

const leaderOf = (digest: Digest | null): CarId | null => digest?.cars.find((one) => one.position === 1)?.id ?? null

/** A wait is long beyond `longWaitS` since the car went out. */
const waitedLong = (state: DerivedState, car: CarId, nowS: number): boolean => {
  const since = state.strickenAtS.get(car)
  return since !== undefined && nowS - since >= T.longWaitS
}

function fromEvent(event: SimEvent, view: View, state: DerivedState, leadChanged: ReadonlySet<CarId>): Group | null {
  const { nowS } = view
  switch (event.type) {
    case 'phase':
      return event.phase === 'running' ? make({ trigger: 'phase', subject: leaderOf(view.digest) }, view) : null
    case 'race-control':
      if (event.call === 'halfway') return make({ trigger: 'race-control', subject: leaderOf(view.digest), extras: ['halfway'] }, view)
      if (event.call === 'last-minute') return make({ trigger: 'race-control', subject: leaderOf(view.digest), extras: ['last-minute'] }, view)
      return null
    case 'lap': {
      const first = !state.completedLap.has(event.car)
      state.completedLap.add(event.car)
      const car = view.digest?.cars.find((one) => one.id === event.car)
      const isPlayer = view.world.drivers[event.car]?.human === true
      const notable = isPlayer || (car !== undefined && car.position <= T.notablePlaces)
      const extras: Condition[] = []
      if (event.personalBest && notable) extras.push('personal-best')
      if (event.sessionBest) extras.push('session-best')
      if (first && notable) extras.push('first-lap')
      if (event.lap > 0 && event.lap % T.milestoneEveryLaps === 0 && (isPlayer || car?.position === 1)) extras.push('milestone')
      if (extras.length === 0) return null
      return make({ trigger: 'lap', subject: event.car, extras, lap: event.lap, time: formatTime(event.lapMs), bonus: event.personalBest || event.sessionBest ? T.bestBonus : 0 }, view)
    }
    case 'position':
      if (event.to === 1 && leadChanged.has(event.car)) return null
      return make({ trigger: 'position', subject: event.car, other: event.passed, pos: event.to }, view)
    case 'lead-change':
      return make({ trigger: 'lead-change', subject: event.car, other: event.previous, pos: 1, leader: true }, view)
    case 'contact': {
      if (event.other !== 'marshal' && event.impulseNs < T.contactMinImpulseNs) return null
      if (typeof event.other === 'number') return make({ trigger: 'contact', subject: event.car, other: event.other, extras: ['car'] }, view)
      return make({ trigger: 'contact', subject: event.car, extras: [event.other] }, view)
    }
    case 'spin':
      return make({ trigger: 'spin', subject: event.car }, view)
    case 'off-track':
      return make({ trigger: 'off-track', subject: event.car }, view)
    case 'kerb-hop':
      if (event.speedMS >= T.bigHopSpeedMS) state.hops.push({ car: event.car, dueS: nowS + event.airborneTicks / T.ticksPerS + T.bigHopSettleS })
      return null
    case 'flip':
      state.hops = state.hops.filter((hop) => hop.car !== event.car)
      if (!state.strickenAtS.has(event.car)) state.strickenAtS.set(event.car, nowS)
      return make({ trigger: 'flip', subject: event.car, extras: [event.cause] }, view)
    case 'stuck':
      if (!state.strickenAtS.has(event.car)) state.strickenAtS.set(event.car, nowS)
      return make({ trigger: 'stuck', subject: event.car, extras: [event.cause] }, view)
    case 'marshal-distracted':
      state.distractedFor.add(event.car)
      return make({ trigger: 'marshal-distracted', subject: event.car, extras: ['distracted'] }, view)
    case 'marshal-dispatched': {
      const extras: Condition[] = []
      if (state.distractedFor.has(event.car)) extras.push('distracted')
      if (waitedLong(state, event.car, nowS)) extras.push('long-wait')
      return make({ trigger: 'marshal-dispatched', subject: event.car, extras }, view)
    }
    case 'car-righted': {
      const extras: Condition[] = []
      if (state.distractedFor.has(event.car)) extras.push('distracted')
      if (event.downtimeS > T.longWaitS) extras.push('long-wait')
      state.distractedFor.delete(event.car)
      state.strickenAtS.delete(event.car)
      state.longWaitTold.delete(event.car)
      return make({ trigger: 'car-righted', subject: event.car, extras }, view)
    }
    case 'sky':
      return make({ trigger: 'sky', sky: event.to }, view)
    case 'gust':
      return make({ trigger: 'gust' }, view)
    case 'puddle':
      return make({ trigger: 'puddle' }, view)
    case 'aquaplane':
      return make({ trigger: 'aquaplane', subject: event.car }, view)
    case 'penalty': {
      const reason: Condition = event.reason === 'off-track' ? 'off-limits' : event.reason === 'cut-track' ? 'cut' : 'contact'
      return make({ trigger: 'penalty', subject: event.car, extras: [reason] }, view)
    }
    case 'car-finished':
      return make({ trigger: 'car-finished', subject: event.car, pos: event.position, lap: event.laps, time: formatTime(event.timeMs), leader: event.position === 1 }, view)
    case 'session-finished': {
      const ranked = [...(view.digest?.cars ?? [])].sort((a, b) => a.position - b.position)
      const winner = ranked[0]
      if (winner === undefined) return null
      return make(
        {
          trigger: 'session-result',
          subject: winner.id,
          other: ranked[1]?.id,
          otherNamedOnly: true,
          pos: 1,
          lap: winner.lap,
          time: winner.bestLapMs === null ? undefined : formatTime(winner.bestLapMs),
          leader: true,
        },
        view,
      )
    }
    default:
      return null
  }
}

/** The candidates the events make, in order. Updates `state` as it goes. */
export function groupsFromEvents(events: readonly SimEvent[], view: View, state: DerivedState): Group[] {
  const leadChanged = new Set<CarId>()
  for (const event of events) if (event.type === 'lead-change') leadChanged.add(event.car)
  const groups: Group[] = []
  for (const event of events) {
    const group = fromEvent(event, view, state, leadChanged)
    if (group !== null) groups.push(group)
  }
  return groups
}

/** Candidates that come from the passing of time: a big kerb hop that was survived, a marshal wait that goes on. */
export function groupsFromClock(view: View, state: DerivedState): Group[] {
  const { digest, nowS } = view
  if (digest === null) return []
  const groups: Group[] = []
  const due = state.hops.filter((hop) => hop.dueS <= nowS)
  state.hops = state.hops.filter((hop) => hop.dueS > nowS)
  for (const hop of due) {
    const group = make({ trigger: 'kerb-hop', subject: hop.car }, view)
    if (group !== null) groups.push(group)
  }
  for (const [car, since] of [...state.strickenAtS]) {
    const state_ = digest.cars.find((one) => one.id === car)?.state
    if (state_ !== 'flipped' && state_ !== 'stuck' && state_ !== 'being-marshalled') {
      state.strickenAtS.delete(car)
      state.longWaitTold.delete(car)
      continue
    }
    if (state_ === 'being-marshalled' || state.longWaitTold.has(car) || nowS - since < T.longWaitS) continue
    state.longWaitTold.add(car)
    const extras: Condition[] = state.distractedFor.has(car) ? ['long-wait', 'distracted'] : ['long-wait']
    const group = make({ trigger: 'marshal-dispatched', subject: car, extras }, view)
    if (group !== null) groups.push(group)
  }
  return groups
}

/**
 * The player's place in the event (F-709): a moment the context gives rather than an event, about the player, with
 * the place as `pos` and its place condition. Null with no player in the field or no place.
 */
export function eventResultGroup(world: World, place: number, nowS: number): Group | null {
  const player = world.drivers.find((one) => one.human)
  if (player === undefined || !Number.isInteger(place) || place < 1) return null
  const holds = new Set<string>(['player', eventPlaceCondition(place)])
  if (world.kind === 'final') holds.add('final')
  if (world.kind === 'qualifying') holds.add('qualifying')
  if (world.drivers.length === 2) holds.add('duel')
  const values: FillValues = { name: player.name, number: String(player.number), colour: player.colour, pos: ordinalWord(place) }
  return { trigger: 'event-result', holds, values, bonus: T.playerBonus, createdAtS: nowS }
}

/** The moment to fill a silence with: a car chosen by the engine's generator, and the one ahead of it. */
export function fillerGroup(view: View, rng: CommentaryRng): Group | null {
  const cars = (view.digest?.cars ?? []).filter((one) => view.world.drivers[one.id] !== undefined)
  const subject = cars.length === 0 ? undefined : cars[rng.int(cars.length)]
  const ahead = subject === undefined ? undefined : cars.find((one) => one.position === subject.position - 1)
  return make(
    {
      trigger: 'filler',
      subject: subject?.id,
      other: ahead?.id,
      otherNamedOnly: true,
      time: subject?.bestLapMs == null ? undefined : formatTime(subject.bestLapMs),
    },
    view,
  )
}
