import type { CarClass, DriveLayout } from '@sim'
import { wrapText } from './layout'

/** The words the garage prints for a drive layout. */
export const DRIVE_LABELS: Readonly<Record<DriveLayout, string>> = { '4wd': '4WD', fwd: 'FWD, front-wheel drive', rwd: 'RWD, rear-wheel drive' }

/** What the garage prints about a class, all of it from the class row: its name, drive layout, motor and character line. */
export interface ClassCard {
  name: string
  drive: string
  motor: string
  /** The character line, broken into lines of at most `wrapChars` characters. */
  character: string[]
}

/** "17.5T, 2200 KV": the winding and the speed it turns per volt, from the row's motor. */
export const motorLabel = (motor: CarClass['motor']): string => `${motor.turns}T, ${Math.round(motor.kv)} KV`

export function classCard(row: CarClass, wrapChars: number): ClassCard {
  return { name: row.name, drive: DRIVE_LABELS[row.drive], motor: motorLabel(row.motor), character: wrapText(row.character, wrapChars) }
}
