import { placeholdersIn } from './fill'
import type { LineTemplate } from './types'
import { allowedConditions, allowedPlaceholders, ENGINE_TRIGGERS, PLACEHOLDERS } from './vocabulary'

/**
 * Checks a line library and throws, listing every problem at once: unique ids; triggers the engine makes candidates
 * for; conditions and placeholders that are in the vocabulary and can hold for the template's trigger; the
 * commentator's voice only (the official's words are the HUD's message table); sane numbers.
 */
export function validateLines(lines: readonly LineTemplate[]): void {
  const problems: string[] = []
  const seen = new Set<string>()
  const triggers: readonly string[] = ENGINE_TRIGGERS
  for (const line of lines) {
    const at = `line "${line.id}"`
    if (seen.has(line.id)) problems.push(`${at}: duplicate id`)
    seen.add(line.id)
    if (line.voice !== 'commentator') problems.push(`${at}: voice "${line.voice}" (the engine makes the commentator's lines only)`)
    if (line.text.trim() === '') problems.push(`${at}: empty text`)
    if (!Number.isFinite(line.priority)) problems.push(`${at}: priority must be a number`)
    if (!(line.ttlS > 0) || !Number.isFinite(line.ttlS)) problems.push(`${at}: ttlS must be a positive number`)
    if (!(line.cooldownS >= 0) || !Number.isFinite(line.cooldownS)) problems.push(`${at}: cooldownS must be zero or more`)
    if (!triggers.includes(line.trigger)) {
      problems.push(`${at}: trigger "${line.trigger}" has no source in this engine`)
      continue
    }
    if (line.when !== undefined && !allowedConditions(line.trigger).has(line.when)) {
      problems.push(`${at}: condition "${line.when}" is unknown or can never hold for trigger "${line.trigger}"`)
    }
    const allowed = allowedPlaceholders(line.trigger)
    for (const name of placeholdersIn(line.text)) {
      if (!(PLACEHOLDERS as readonly string[]).includes(name)) problems.push(`${at}: unknown placeholder {${name}}`)
      else if (!(allowed as ReadonlySet<string>).has(name)) problems.push(`${at}: placeholder {${name}} is never available for trigger "${line.trigger}"`)
    }
  }
  if (problems.length > 0) throw new Error(`Invalid commentary lines:\n  ${problems.join('\n  ')}`)
}
