import { classification, type CarClassId, type CarColour, type EventSettings, type RaceDayState } from '@sim'
import { withOffer, type EntryInfo, type Offer } from '../leaderboard/boards'
import type { SaveData } from './storage'

// Pure changes to a `SaveData` for the things the race day does to it. Each returns a new value.

/** The choices of an event that a new event setup starts on, and the car: everything in the settings except what is made fresh for each event. */
export function rememberedSettings(settings: EventSettings): Partial<EventSettings> {
  const choices: Partial<EventSettings> = { ...settings }
  delete choices.trackId
  delete choices.seed
  return choices
}

/** An event has begun or has moved on: it is the event in progress, and its choices and car are the ones to offer next time. */
export function withEvent(data: SaveData, state: RaceDayState): SaveData {
  return { ...data, settings: { ...data.settings, lastEvent: rememberedSettings(state.settings) }, eventInProgress: state }
}

/** The podium has been shown: there is no event in progress, and its classification is the last result. A state not yet classified (the final not yet recorded) is left as it is. */
export function withFinishedEvent(data: SaveData, state: RaceDayState): SaveData {
  const rows = classification(state)
  if (rows === null) return data
  return { ...data, eventInProgress: null, lastClassification: { settings: state.settings, rows } }
}

/** The garage's pick, remembered as the car of the last event so that the garage opens on it next time. */
export function withCar(data: SaveData, car: { carClass: CarClassId; colour: CarColour }): SaveData {
  const { lastEvent } = data.settings
  if (lastEvent.carClass === car.carClass && lastEvent.colour === car.colour) return data
  return { ...data, settings: { ...data.settings, lastEvent: { ...lastEvent, ...car } } }
}

/** The player's result is on the boards under `initials` (written to each board on offer, once), and those initials are the ones to offer next time. */
export function withResultOnBoards(data: SaveData, offer: Offer, info: EntryInfo, initials: string, dateISO: string): SaveData {
  return { ...data, settings: { ...data.settings, lastInitials: initials }, leaderboards: withOffer(data.leaderboards, offer, info, initials, dateISO) }
}
