import type Phaser from 'phaser'
import { THEME, lineHeight, type TextSize } from './theme'

/** How far the current row's bar reaches past the table's sides. */
const BAR_PAD_X = 6
import { charsAcross, tableLines, type Rect, type TableColumn } from './layout'
import { Skin } from './skin'
import { setTextIfChanged, text } from './text'

/** Columns on a fixed character grid: a header line, then rows of text and right-aligned numbers, one row marked as the current one (the cursor glyph and the skin's focus bar). A cell too long for its column ends in an ellipsis; a line too long for the rectangle is cut to fit. */
export class Table {
  private readonly header: Phaser.GameObjects.BitmapText
  private readonly body: Phaser.GameObjects.BitmapText
  private readonly bar: Skin
  private readonly maxChars: number
  private readonly maxRows: number
  private readonly lineHeightPx: number

  constructor(
    scene: Phaser.Scene,
    private readonly rect: Rect,
    private readonly columns: readonly TableColumn[],
    size: TextSize = 'body',
  ) {
    // Two characters at the left hold the cursor glyph of the highlighted row.
    this.maxChars = Math.max(0, charsAcross(rect.w, size) - 2)
    this.lineHeightPx = lineHeight(size)
    this.maxRows = Math.max(0, Math.floor(rect.h / this.lineHeightPx) - 1)
    this.bar = new Skin(scene, THEME.skin.bar)
    this.header = text(scene, { x: rect.x, y: rect.y }, '', size).setTint(THEME.colours.textDim)
    this.body = text(scene, { x: rect.x, y: rect.y + this.lineHeightPx }, '', size)
    setTextIfChanged(this.header, `  ${tableLines(this.columns, [], this.maxChars)[0] ?? ''}`)
  }

  /** The rows that fit under the header. */
  get capacity(): number {
    return this.maxRows
  }

  /** Shows `rows` (cells by column key); `highlightRow` is the index of the current row, if any. Only the changed text is redrawn. */
  setRows(rows: ReadonlyArray<Record<string, string>>, highlightRow?: number): void {
    const shown = rows.slice(0, this.maxRows)
    const lines = tableLines(this.columns, shown, this.maxChars).slice(1)
    setTextIfChanged(this.body, lines.map((line, i) => `${i === highlightRow ? `${THEME.cursorGlyph} ` : '  '}${line}`).join('\n'))
    const marked = highlightRow !== undefined && highlightRow >= 0 && highlightRow < shown.length
    if (marked) this.bar.place({ x: this.rect.x - BAR_PAD_X, y: this.rect.y + this.lineHeightPx * (highlightRow + 1), w: this.rect.w + 2 * BAR_PAD_X, h: this.lineHeightPx })
    this.bar.setVisible(marked)
  }

  destroy(): void {
    this.bar.destroy()
    this.header.destroy()
    this.body.destroy()
  }
}
