import type { ZzfxParams } from './AudioMixer'

// Every ZzFX parameter set in the game, as named constants (F-704). ZzFX takes 21 positional numbers; `zz` writes
// them by name, in ZzFX's own order, so a preset reads as what it is. Filter: negative is a low-pass, positive a
// high-pass (cut-off in Hz). Shape: 0 sine, 1 triangle, 2 saw, 3 clipped tan, 4 noise, 5 square.
//
// ALL OF THESE ARE FIRST GUESSES from the parameters' meanings, not tuned by ear (the implementer cannot hear).
// They are meant to be auditioned in ZzFX's designer and adjusted here; nothing else in the game depends on them.

interface Zz {
  volume?: number
  randomness?: number
  frequency?: number
  attack?: number
  sustain?: number
  release?: number
  shape?: number
  shapeCurve?: number
  slide?: number
  deltaSlide?: number
  pitchJump?: number
  pitchJumpTime?: number
  repeatTime?: number
  noise?: number
  modulation?: number
  bitCrush?: number
  delay?: number
  sustainVolume?: number
  decay?: number
  tremolo?: number
  filter?: number
}

/** A preset written by name, as the 21 positional parameters ZzFX takes. The volume is always 1: the level is the voice's gain. */
export function zz(p: Zz): ZzfxParams {
  return [
    p.volume ?? 1,
    p.randomness,
    p.frequency,
    p.attack,
    p.sustain,
    p.release,
    p.shape,
    p.shapeCurve,
    p.slide,
    p.deltaSlide,
    p.pitchJump,
    p.pitchJumpTime,
    p.repeatTime,
    p.noise,
    p.modulation,
    p.bitCrush,
    p.delay,
    p.sustainVolume,
    p.decay,
    p.tremolo,
    p.filter,
  ]
}

export type SfxKind =
  | 'contact-wall'
  | 'contact-car'
  | 'contact-tyre'
  | 'kerb-thump'
  | 'roll-thump'
  | 'roll-scrape'
  | 'righted'
  | 'kerb-rumble'
  | 'splash'
  | 'lap'
  | 'personal-best'
  | 'menu-move'
  | 'menu-select'
  | 'tools-unlocked'

