import Phaser from 'phaser'
import { createRaceDay } from '@sim'
import { ROSTER } from '@content/roster'
import { LOGICAL_HEIGHT, LOGICAL_WIDTH } from '../config'
import { onNav, type NavKey } from '../input/keys'
import { CLASS_WORDS } from '../leaderboard'
import { CARS_CHOICES, freshSeed, MINUTES_CHOICES, PENALTY_SECONDS_CHOICES } from '../race/quick-race'
import { DROP_CANCEL, DROP_CONFIRM, DROP_QUESTION, saves } from '../persistence'
import { choicesFrom, eventSettings, RACE_DAY_KEY, RaceDayController, type EventChoices, type RaceDayFlowData } from '../raceday/RaceDayController'
import { availableTracks, chooseTrack, chosenTrack, showsTrackSelector, trackOptions } from '../raceday/track-choice'
import { selection } from '../state/selection'
import { ButtonRow, CarPicture, ConfirmDialog, Form, Panel, THEME, text, type HasReadout, type Rect, type ScreenReadout, type Selector } from '../ui'
import type { GarageSceneData } from './GarageScene'

/** What the screen has chosen: null until it is first opened, when it takes the last event's settings from the save (F-405). Kept while the page is open, so a second event starts as the last one did. */
let chosen: EventChoices | null = null
const choices = (): EventChoices => (chosen ??= choicesFrom(saves.read().settings.lastEvent))

const PANEL: Rect = { x: Math.round((LOGICAL_WIDTH - 1200) / 2), y: 168, w: 1200, h: 780 }
/** The car's picture takes the left of the panel; the form stands to the right of it. */
const PICTURE_W = 280
const PICTURE_H = 170
const PICTURE_GAP = 40
const ROW_PITCH = 56
/** With the TRACK row there is one row more in the same panel (the selector shows only with a second track), so the rows stand closer. */
const ROW_PITCH_WITH_TRACK = 51
const LABEL_CHARS = 13

/** The rows of the form, top to bottom; the track only with more than one to choose from; the qualifying start is there only on a track with a pit lane, and the penalty's length only while penalties are on. */
type RowId = keyof EventChoices | 'track' | 'actions'

const COUNT_OPTIONS = ([1, 2, 3] as const).map((n) => ({ value: n, label: String(n) }))
const ON_OFF = [{ value: true, label: 'ON' }, { value: false, label: 'OFF' }]

/**
 * The settings of a race day (race-format.md, "Event settings"), the screen after the garage: cars per race,
 * direction, round length, qualifying start, qualifying rounds, finals legs, difficulty and forecast, each changed with
 * the arrow keys. The car is the garage's, shown here and not changed here. The screen opens on the last event's settings.
 * Enter on START makes the race day with exactly these settings and the garage's car, saves it as the event in progress
 * and opens the first session's intro; with an event already in progress it asks first, and drops nothing unless the
 * player confirms. Esc or BACK returns to the garage.
 */
export class EventSetupScene extends Phaser.Scene implements HasReadout {
  private parts: Phaser.GameObjects.GameObject[] = []
  private panel: Panel | null = null
  private form: Form | null = null
  private picture: CarPicture | null = null
  private buttons: ButtonRow | null = null
  private rowIds: RowId[] = []
  private release: (() => void) | null = null
  /** The question about dropping the event in progress, while it is on screen. */
  private dialog: ConfirmDialog | null = null
  /** Penalties were switched, so the form (which has the penalty's length only with penalties on) is built again once the key has been handled. */
  private rebuild = false
  private handled = 0

  constructor() {
    super('EventSetup')
  }

  create(): void {
    this.handled = 0
    this.dialog = null
    this.rebuild = false
    this.cameras.main.setBackgroundColor(THEME.colours.background)
    this.parts.push(text(this, { x: 96, y: 48 }, 'RACE DAY', 'large').setTint(THEME.colours.accent))
    this.parts.push(text(this, { x: 96, y: 116 }, 'SET UP THE EVENT, THEN START', 'small').setTint(THEME.colours.textDim))
    this.parts.push(
      text(this, { x: LOGICAL_WIDTH / 2, y: LOGICAL_HEIGHT - 64 }, '↑ ↓ MOVE   ← → CHANGE   ENTER CHOOSE   ESC BACK', 'small').setOrigin(0.5, 0).setTint(THEME.colours.textDim),
    )
    this.panel = new Panel(this, PANEL, { title: 'EVENT SETTINGS' })
    // The garage's car, as a picture with its class under it: the sprite shows the colour, so no words do.
    const { carClass, colour } = selection.get()
    const { inner } = this.panel
    this.picture = new CarPicture(this, { x: inner.x, y: inner.y, w: PICTURE_W, h: PICTURE_H }, carClass, colour, CLASS_WORDS[carClass])
    this.buildForm()
    this.release = onNav(this, (key) => this.onKey(key))
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, this.dispose, this)
  }

  readout(): ScreenReadout {
    const { carClass, colour } = selection.get()
    const car = this.picture?.info()
    return {
      focus: this.form?.focus ?? null,
      values: {
        handled: this.handled,
        class: carClass,
        colour,
        carLabel: car?.label ?? '',
        carAtlas: car?.atlas ?? '',
        carFrame: car?.frame ?? '',
        carScale: car?.scale ?? 0,
        carLengthPx: car?.lengthPx ?? 0,
        carLoading: car?.loading === true ? 1 : 0,
        ...choices(),
        track: chosenTrack().id,
        penalties: choices().penalties ? 'on' : 'off',
        reverse: choices().reverse ? 'on' : 'off',
        rows: this.rowIds.join(','),
        buttonFocus: this.buttons?.focusedButton ?? '',
        asking: this.dialog === null ? 0 : 1,
      },
    }
  }

  /** Builds the form from the choices; `focus` is the row that had focus, which gets it back when the form is built again. */
  private buildForm(focus: string | null = null): void {
    this.form?.destroy()
    const inner = (this.panel as Panel).inner
    const form = new Form(this, { x: inner.x + PICTURE_W + PICTURE_GAP, y: inner.y }, { size: 'body', pitch: showsTrackSelector() ? ROW_PITCH_WITH_TRACK : ROW_PITCH })
    const ids: RowId[] = []
    /** A row for one of the choices: the options it offers, the value it starts on (the screen's last choice), and the choice it changes. */
    const add = <K extends keyof EventChoices>(id: K, label: string, options: ReadonlyArray<{ value: EventChoices[K]; label: string }>): Selector<EventChoices[K]> => {
      const selector = form.addSelector(id, label, options, choices()[id], { labelChars: LABEL_CHARS })
      selector.onChange((value) => {
        chosen = { ...choices(), [id]: value }
      })
      ids.push(id)
      return selector
    }

    if (showsTrackSelector()) {
      const selector = form.addSelector('track', 'TRACK', trackOptions(), chosenTrack().id, { labelChars: LABEL_CHARS })
      selector.onChange((value) => {
        chooseTrack(value)
        // The qualifying start depends on the track's pit lane: build the form again.
        this.rebuild = true
      })
      ids.push('track')
    }
    add('carsPerRace', 'CARS PER RACE', CARS_CHOICES.map((n) => ({ value: n, label: String(n) })))
    add('direction', 'DIRECTION', [
      { value: 'counter-clockwise', label: 'COUNTER-CLOCKWISE' },
      { value: 'clockwise', label: 'CLOCKWISE' },
    ])
    add('roundMinutes', 'ROUND LENGTH', MINUTES_CHOICES.map((n) => ({ value: n, label: `${n} MINUTES` })))
    if (chosenTrack().pitLane !== undefined) {
      add('qualifyingStart', 'QUAL START', [
        { value: 'pit-lane', label: 'PIT LANE' },
        { value: 'start-boxes', label: 'START BOXES' },
      ])
    }
    add('qualifyingRounds', 'QUAL ROUNDS', COUNT_OPTIONS)
    add('finalsLegs', 'FINAL LEGS', COUNT_OPTIONS)
    add('difficulty', 'DIFFICULTY', [
      { value: 'club', label: 'CLUB' },
      { value: 'regional', label: 'REGIONAL' },
      { value: 'national', label: 'NATIONAL' },
    ])
    add('forecast', 'FORECAST', [
      { value: 'dry', label: 'DRY' },
      { value: 'changeable', label: 'CHANGEABLE' },
      { value: 'wet', label: 'WET' },
      { value: 'surprise', label: 'SURPRISE ME' },
    ])
    add('penalties', 'PENALTIES', ON_OFF).onChange(() => {
      // Not now: the selector that called this is about to draw itself.
      this.rebuild = true
    })
    if (choices().penalties) add('penaltySeconds', 'PENALTY', PENALTY_SECONDS_CHOICES.map((n) => ({ value: n, label: `${n} SECONDS` })))
    add('reverse', 'REVERSE', ON_OFF)
    this.buttons = form.addButtons('actions', [{ id: 'start', label: 'START' }, { id: 'back', label: 'BACK' }], 24)
    ids.push('actions')
    this.buttons.onPress((id) => this.leave(id))
    this.form = form
    this.rowIds = ids

    // Focus is on the first row of a new form; move it to the row that had it.
    const at = focus === null ? 0 : Math.max(0, (ids as readonly string[]).indexOf(focus))
    for (let i = 0; i < at; i++) form.handle('down')
  }

  private onKey(key: NavKey): void {
    this.handled++
    if (this.dialog !== null) {
      this.dialog.handle(key)
      return
    }
    if (key === 'back') {
      this.leave('back')
      return
    }
    const focus = this.form?.focus ?? null
    this.form?.handle(key)
    if (this.rebuild) {
      this.rebuild = false
      this.buildForm(focus)
    }
  }

  /** Goes back to the garage, or starts the event: at once, or once the player has said the event in progress may go. */
  private leave(id: string): void {
    if (id === 'back') {
      this.stopListening()
      const garage: GarageSceneData = { role: 'race-day' }
      this.scene.start('Garage', garage)
    } else if (RaceDayController.savedAmong(availableTracks()) === null) this.start()
    else this.askToDrop()
  }

  /** Asks whether the event in progress may be dropped. Until the answer every key goes to the question. */
  private askToDrop(): void {
    const dialog = new ConfirmDialog(this, { message: DROP_QUESTION, confirmLabel: DROP_CONFIRM, cancelLabel: DROP_CANCEL })
    this.dialog = dialog
    dialog.onAnswer((confirmed) => {
      this.closeDialog()
      if (confirmed) this.start()
    })
  }

  private closeDialog(): void {
    this.dialog?.destroy()
    this.dialog = null
  }

  /** Stops listening at once, so that a second press before the next scene appears does nothing, then makes the event, saves it as the one in progress and opens its first session. */
  private start(): void {
    this.stopListening()
    const { carClass, colour } = selection.get()
    const track = chosenTrack()
    const controller = new RaceDayController(createRaceDay(eventSettings(choices(), { carClass, colour }, track.id, freshSeed()), ROSTER), track)
    controller.save()
    this.registry.set(RACE_DAY_KEY, controller)
    this.scene.start(controller.nextScene(), { controller } satisfies RaceDayFlowData)
  }

  private stopListening(): void {
    this.release?.()
    this.release = null
  }

  private dispose(): void {
    this.stopListening()
    this.closeDialog()
    this.form?.destroy()
    this.form = null
    this.picture?.destroy()
    this.picture = null
    this.buttons = null
    this.rowIds = []
    this.panel?.destroy()
    this.panel = null
    for (const part of this.parts) part.destroy()
    this.parts = []
  }
}
