import {
  nextSession,
  recordResult,
  type CarClassId,
  type CarColour,
  type CarsPerRace,
  type Difficulty,
  type Direction,
  type EventSettings,
  type Forecast,
  type RaceDayState,
  type ScheduleItem,
  type SessionConfig,
  type SessionResult,
  type TrackData,
} from '@sim'
import { saves as gameSaves, withEvent, withFinishedEvent, type SaveStore } from '../persistence'
import { sessionHeading } from '../race/event-tables'

// The view side of a race day (F-403). No Phaser here: the controller holds the event's state and says what the flow
// shows next; the scenes do the showing and the moving. It adds to the state a single bit of its own, whether the
// standings of the session just recorded have been seen, and nothing a save would need: the save is `state` (F-405).
// The weather needs nothing of it either (F-601): a session's result carries what it hands on, `record` puts it in
// the state with the result, and the next session's config, from `peek`, begins with it, across a save and a load.

/** The key under which the running controller is kept in the game's registry, so that tools (the debug hook) can find it. Cleared by the title screen; an event left for the title is kept in the save, not here. */
export const RACE_DAY_KEY = 'raceDay'

/** What the flow shows next. */
export type FlowStep = { kind: 'session'; item: ScheduleItem; config: SessionConfig } | { kind: 'standings' } | { kind: 'podium' }

/** The scene that shows each kind of step. */
export const FLOW_SCENES = { session: 'SessionIntro', standings: 'Standings', podium: 'Podium' } as const satisfies Record<FlowStep['kind'], string>

/** What starts every scene of the flow: the controller of the event being run. */
export interface RaceDayFlowData {
  controller: RaceDayController
}

/** What the event setup screen lets the player change (race-format.md, "Event settings"; the class and the colour are the garage's). */
export interface EventChoices {
  carsPerRace: CarsPerRace
  direction: Direction
  roundMinutes: 3 | 5 | 7
  qualifyingStart: 'pit-lane' | 'start-boxes'
  qualifyingRounds: 1 | 2 | 3
  finalsLegs: 1 | 2 | 3
  difficulty: Difficulty
  forecast: Forecast
  /** Whether the stop penalties are on (F-508, F-510), how long they hold a car, s, and whether the cars can reverse. */
  penalties: boolean
  penaltySeconds: 3 | 4 | 5
  reverse: boolean
}

/** The settings a fresh event setup screen starts on: the defaults column of race-format.md. */
export const EVENT_DEFAULTS: Readonly<EventChoices> = {
  carsPerRace: 7,
  direction: 'counter-clockwise',
  roundMinutes: 5,
  qualifyingStart: 'pit-lane',
  qualifyingRounds: 2,
  finalsLegs: 1,
  difficulty: 'club',
  forecast: 'changeable',
  penalties: true,
  penaltySeconds: 5,
  reverse: true,
}

/** What each choice may be: a saved value outside these (an edited or an older save) is not offered. */
const ALLOWED = {
  carsPerRace: [2, 4, 7],
  direction: ['counter-clockwise', 'clockwise'],
  roundMinutes: [3, 5, 7],
  qualifyingStart: ['pit-lane', 'start-boxes'],
  qualifyingRounds: [1, 2, 3],
  finalsLegs: [1, 2, 3],
  difficulty: ['club', 'regional', 'national'],
  forecast: ['dry', 'changeable', 'wet', 'surprise'],
  penalties: [true, false],
  penaltySeconds: [3, 4, 5],
  reverse: [true, false],
} as const satisfies { [K in keyof EventChoices]: readonly EventChoices[K][] }

/** The event setup's starting choices from what was saved of the last event: each saved value that is still a valid choice, the rulebook's default for the rest (a save made before the penalty and reverse settings has none of them: on, 5 s, on). */
export function choicesFrom(last: Partial<EventSettings>): EventChoices {
  const pick = <K extends keyof EventChoices>(key: K): EventChoices[K] => {
    const value = last[key]
    const allowed: readonly unknown[] = ALLOWED[key]
    return allowed.includes(value) ? (value as EventChoices[K]) : EVENT_DEFAULTS[key]
  }
  return {
    carsPerRace: pick('carsPerRace'),
    direction: pick('direction'),
    roundMinutes: pick('roundMinutes'),
    qualifyingStart: pick('qualifyingStart'),
    qualifyingRounds: pick('qualifyingRounds'),
    finalsLegs: pick('finalsLegs'),
    difficulty: pick('difficulty'),
    forecast: pick('forecast'),
    penalties: pick('penalties'),
    penaltySeconds: pick('penaltySeconds'),
    reverse: pick('reverse'),
  }
}

/** The event's settings: the screen's choices, the garage's car, the track and the event's seed. */
export function eventSettings(choices: EventChoices, car: { carClass: CarClassId; colour: CarColour }, trackId: string, seed: number): EventSettings {
  return { ...choices, carClass: car.carClass, colour: car.colour, trackId, seed }
}

/**
 * Holds the state of the event being run and answers the one question the flow asks: what next?
 *
 * After every session `peek()` returns `standings` once before the next session, and after the last final leg it
 * returns `standings` and then `podium`. `peek()` changes nothing, so a scene may ask as often as it likes.
 */
export class RaceDayController {
  state: RaceDayState
  /** A session has been recorded and its standings have not been acknowledged. */
  private standingsPending = false

  /**
   * `saves` is where the event is kept (F-405): the game's store unless a test gives its own, or null for none. The
   * controller does not write at construction: a new event calls `save()` when the player has started it.
   */
  constructor(
    state: RaceDayState,
    private readonly track: TrackData,
    private readonly saves: SaveStore | null = gameSaves,
  ) {
    this.state = state
  }

  /**
   * The controller for an event that was saved, or null when the saved state is not one this track can run (the sim
   * says what comes next, and says nothing sensible of a state it did not make). When a session has been recorded the
   * flow opens on the standings as they stood after the last one (what the cursor and the results already say, so the
   * save holds nothing extra), then goes on to the session that was next, or to the podium; with nothing recorded it
   * opens on the first session.
   */
  static resume(state: RaceDayState, track: TrackData, saves: SaveStore | null = gameSaves): RaceDayController | null {
    if (state.settings.trackId !== track.id) return null
    try {
      const controller = new RaceDayController(state, track, saves)
      controller.peek()
      controller.standingsPending = state.cursor > 0
      return controller
    } catch {
      return null
    }
  }

  /** The controller for the event in progress in the save, or null when there is none that can be run. */
  static saved(track: TrackData, saves: SaveStore = gameSaves): RaceDayController | null {
    const state = saves.read().eventInProgress
    return state === null ? null : RaceDayController.resume(state, track, saves)
  }

  /** The controller for the event in progress when it is on any of `tracks` (a game with several tracks): the one the event was made on runs it. Null when there is none that can be run. */
  static savedAmong(tracks: readonly TrackData[], saves: SaveStore = gameSaves): RaceDayController | null {
    for (const track of tracks) {
      const controller = RaceDayController.saved(track, saves)
      if (controller !== null) return controller
    }
    return null
  }

  /** Keeps the event as it stands as the event in progress, with its choices and car as the ones to offer next time. */
  save(): void {
    this.saves?.update((data) => withEvent(data, this.state))
  }

  /** The event is over and its podium shown: it is no longer in progress, and its classification is the last result. */
  finish(): void {
    this.saves?.update((data) => withFinishedEvent(data, this.state))
  }

  /** The session that is next after any standings, in words: its name, or the podium. */
  get nextHeading(): string {
    const item = this.state.schedule[this.state.cursor]
    return item === undefined ? 'THE PODIUM' : sessionHeading(item, this.state)
  }

  peek(): FlowStep {
    if (this.standingsPending) return { kind: 'standings' }
    const next = nextSession(this.state, this.track)
    return next === null ? { kind: 'podium' } : { kind: 'session', item: next.item, config: next.config }
  }

  /** The key of the scene that shows what `peek()` says is next. */
  nextScene(): string {
    return FLOW_SCENES[this.peek().kind]
  }

  /**
   * Records the result of the session that was run (it throws unless that is the next session of the event) and puts
   * the standings next. With the result goes the weather it hands on (`SessionResult.weatherNext`, F-601): the next
   * session begins with it.
   */
  record(result: SessionResult): void {
    this.state = recordResult(this.state, result)
    this.standingsPending = true
    this.save()
  }

  /** The player has seen the standings: the next session, or the podium, is next. */
  acknowledgeStandings(): void {
    this.standingsPending = false
    this.save()
  }

  /** Every session of the event has been recorded. */
  get over(): boolean {
    return this.state.cursor >= this.state.schedule.length
  }
}
