import { RACE_CONTROL_EN } from '@content/lines/en/race-control'
import { formatLapTime } from './PracticeReadout'
import { RULES, TICK_RATE, type CarId, type CarState, type PenaltyReason, type SessionPhase, type SessionSnapshot, type SimEvent, type Sky, type Tick } from '@sim'

// What the HUD says, as pure tables (F-304): the message line, the start calls, and the end-of-session calls. The
// HUD only displays what these return. It holds no engine, so every row is tested in Node.
//
// Adding a message (F-306's pit stops, F-307's track limits, F-309's race rules): add a row to `ROWS` below, keyed
// by the event it answers, and add a test. Nothing in `Hud.ts` changes: it listens to every event type that has a row.

/** How a message is coloured: neutral news, good news, a penalty or a fault. */
export type MessageTone = 'info' | 'good' | 'bad'

/** What a row decides: the words, how long they stay, and whether the seconds left are counted out after them. */
export interface HudMessage {
  text: string
  /**
   * How long it stays up, in session seconds: the sim's clock, so pausing the race pauses it. `Infinity` is a
   * standing message: it stays until another message takes the line.
   */
  seconds: number
  tone: MessageTone
  /** Show the whole seconds left after the words: "HELD 3", "HELD 2", "HELD 1". */
  countdown?: boolean
  /**
   * What stands on the line from this message on (see `MessageLine`): the standing message to show again once this
   * one's time is up, or null to take the standing message down. Left out, the standing message is as it was.
   */
  standing?: HudMessage | null
  /** The words pulse between their tone's colour and white, half a second each (TIME UP). */
  pulse?: boolean
}

/** What a row may look at besides the event itself. */
export interface MessageContext {
  snapshot: SessionSnapshot
  /** The car the person at the keyboard drives; null when nobody does. */
  playerId: CarId | null
}

type EventOf<T extends SimEvent['type']> = Extract<SimEvent, { type: T }>
type Rows = { [T in SimEvent['type']]?: (event: EventOf<T>, context: MessageContext) => HudMessage | null }

/** Whether the event is about the player's own car. */
const isPlayer = (car: CarId, context: MessageContext): boolean => context.playerId !== null && car === context.playerId

/**
 * What stands on the line from a jumped start until the hold begins (F-509): the hold is owed, and is served at the
 * line. The sim's `hold` event takes it down, and its own message and countdown take over.
 */
export const HOLD_COMING: HudMessage = Object.freeze({ text: `${RULES.holdS} SECOND HOLD AT THE LINE`, seconds: Infinity, tone: 'bad' })

/** The words of the pit-stop messages (F-306). The hold's are followed by its seconds: "PIT STOP 5". */
export const PIT_TEXT = {
  lastMinute: 'PIT STOP OWED — LAST MINUTE',
  hold: 'PIT STOP',
  done: 'PIT STOP DONE',
} as const

/** The words of each penalty that is served on the track (F-307, F-309). They are followed by the seconds left of the hold: "OFF TRACK PENALTY 5". */
export const PENALTY_TEXT: Readonly<Record<PenaltyReason, string>> = {
  'off-track': 'OFF TRACK PENALTY',
  'cut-track': 'TRACK CUT PENALTY',
  contact: 'CONTACT PENALTY',
}

/** The words of the track-limits penalty (F-307). */
export const OFF_TRACK_PENALTY_TEXT = PENALTY_TEXT['off-track']

/** The words of the other race rules (F-309). */
export const RULE_TEXT = {
  /** Flashed while the stop zone is taken and the player is coming to it. */
  pitOccupied: 'PIT OCCUPIED',
  pitStopVoid: `PIT STOP VOID — LEAVE THE PIT WITHIN ${RULES.pitLeaveS} SECONDS`,
  startBlocked: 'BLOCKING THE PIT LANE — YOU START LAST',
  contactWarning: (warning: number, of: number): string => `CONTACT WARNING ${warning} OF ${of}`,
} as const

/** What the line says when the marshal sent for the player's stricken car is looking at his phone (F-505). */
export const MARSHAL_PHONE_TEXT = 'MARSHAL IS ON HIS PHONE'

/** The words of the weather notices (F-603): a change of sky that the player will feel in the car. */
export const WEATHER_TEXT = { rain: 'RAIN', heavyRain: 'HEAVY RAIN', easing: 'RAIN EASING', stopped: 'RAIN STOPPED' } as const

/** How long a weather notice stays up, s. */
export const WEATHER_SECONDS = 4

/**
 * What a change of sky says: RAIN when light rain comes from a dry sky, HEAVY RAIN when the rain turns heavy, RAIN
 * EASING when heavy rain turns light and RAIN STOPPED when rain gives way to cloud; nothing between sun and cloud.
 */
function weatherNotice(from: Sky, to: Sky): HudMessage | null {
  const words =
    to === 'heavy-rain'
      ? WEATHER_TEXT.heavyRain
      : to === 'light-rain'
        ? from === 'heavy-rain'
          ? WEATHER_TEXT.easing
          : WEATHER_TEXT.rain
        : from === 'light-rain' || from === 'heavy-rain'
          ? WEATHER_TEXT.stopped
          : null
  return words === null ? null : { text: words, seconds: WEATHER_SECONDS, tone: 'info' }
}

/** How long the race director's time checks stay on the message line, s. */
export const RACE_CONTROL_SECONDS = 3

/**
 * The race director's words on the message line (F-404): the first variant of the call, in capitals, for three
 * seconds. These are the calls that tell the player something the screen does not already: the start calls are
 * the start display's, and 'time-up' is the end display's.
 */
function raceDirector(call: 'halfway' | 'last-minute'): HudMessage {
  return { text: RACE_CONTROL_EN[call][0].toUpperCase(), seconds: RACE_CONTROL_SECONDS, tone: 'info' }
}

/** A message of no words and no time: it takes down whatever is on the line. */
export const NO_MESSAGE: HudMessage = Object.freeze({ text: '', seconds: 0, tone: 'info' })

/** The pit-stop warning with a minute left: what 'pit-reminder' says, and what the last minute says to a player who owes the stop. */
const PIT_LAST_MINUTE: HudMessage = Object.freeze({ text: PIT_TEXT.lastMinute, seconds: Infinity, tone: 'bad' })

/** The player's car, if somebody is driving and it still owes a pit stop. */
function owingCar(context: MessageContext): SessionSnapshot['cars'][number] | null {
  const car = context.playerId === null ? undefined : context.snapshot.cars.find((one) => one.id === context.playerId)
  return car !== undefined && car.pitStopsOwed > 0 ? car : null
}

/**
 * The standing warning that the player still owes a pit stop (F-306), or null: with no more than `RULES.pitReminderAtS`
 * on the clock and a stop still owed, the car neither standing for its stop nor finished, nor the clock run out, it is
 * PIT STOP OWED — LAST MINUTE. Before that nothing stands on the line (F-514): the top band's PITS boxes say that a stop is owed.
 */
function pitStopOwed(context: MessageContext): HudMessage | null {
  const { snapshot } = context
  const car = owingCar(context)
  if (car === null || car.state === 'pit-hold' || car.state === 'finished') return null
  if (snapshot.phase === 'time-up' || snapshot.phase === 'finished') return null
  return snapshot.clockRemainingS <= RULES.pitReminderAtS ? PIT_LAST_MINUTE : null
}

/** The rows of the table: one function per event type that can put a message up. Only the player's own events speak. */
const ROWS: Rows = {
  // A jumped start is said for three seconds and then the hold that is owed is said, standing, until it begins (F-509):
  // the hold's own message takes it down, and puts the pit warning back if it is the last minute and the stop is still owed.
  'jump-start': (event, context) => (isPlayer(event.car, context) ? { text: 'JUMP START', seconds: 3, tone: 'bad', standing: HOLD_COMING } : null),
  hold: (event, context) => (isPlayer(event.car, context) ? { text: 'HELD', seconds: event.seconds, tone: 'bad', countdown: true, standing: pitStopOwed(context) } : null),
  // Pit stops (F-306). The warning with a minute left is the standing message from then on; a timed message shows
  // over it and it is shown again when that ends (`MessageLine`), so no lap has to put it back. A standing message
  // has to be taken down: when time is up, the warning of a stop still owed goes, and the stop's own messages say it
  // is not owed while it is served.
  phase: (event, context) => (event.phase === 'time-up' || event.phase === 'finished' ? (owingCar(context) === null ? null : NO_MESSAGE) : pitStopOwed(context)),
  // Race control (F-404). Halfway is the director's time check. The last minute is the director's too, unless the
  // player still owes a pit stop: then it is the pit reminder, which is the same minute said with the stop in it,
  // and standing, so the line never carries both. The sim tells 'pit-reminder' on the same tick; the two agree.
  'race-control': (event, context) => {
    if (event.call === 'halfway') return raceDirector('halfway')
    if (event.call !== 'last-minute') return null
    if (owingCar(context) === null) return raceDirector('last-minute')
    return pitStopOwed(context) === null ? null : PIT_LAST_MINUTE
  },
  'pit-reminder': (event, context) => (isPlayer(event.car, context) ? PIT_LAST_MINUTE : null),
  'pit-stop-start': (event, context) => (isPlayer(event.car, context) ? { text: PIT_TEXT.hold, seconds: RULES.pitHoldS, tone: 'info', countdown: true, standing: null } : null),
  'pit-stop-done': (event, context) => (isPlayer(event.car, context) ? { text: PIT_TEXT.done, seconds: 3, tone: 'good', standing: null } : null),
  // A penalty (F-307, F-309): up for as long as the car is held, with the seconds left counted out, and gone when it is released.
  penalty: (event, context) => (isPlayer(event.car, context) ? { text: PENALTY_TEXT[event.reason], seconds: event.holdS, tone: 'bad', countdown: true } : null),
  // The race rules of F-309. A hit that counts against the player is a warning, by number.
  'contact-warning': (event, context) => (isPlayer(event.car, context) ? { text: RULE_TEXT.contactWarning(event.warning, event.of), seconds: 3, tone: 'bad' } : null),
  // The sim tells it on a steady beat while it is so; shown for half of each beat, it flashes, and stops by itself.
  'pit-occupied': (event, context) => (isPlayer(event.car, context) ? { text: RULE_TEXT.pitOccupied, seconds: RULES.pitWarnEveryS / 2, tone: 'bad' } : null),
  'pit-stop-void': (event, context) => (isPlayer(event.car, context) ? { text: RULE_TEXT.pitStopVoid, seconds: 4, tone: 'bad', standing: pitStopOwed(context) } : null),
  // Lifted out of the pit queue: said for as long as the car stands aside, and taken down when it is put back.
  'start-blocked': (event, context) => (isPlayer(event.car, context) ? { text: RULE_TEXT.startBlocked, seconds: Infinity, tone: 'bad' } : null),
  'start-unblocked': (event, context) => (isPlayer(event.car, context) ? NO_MESSAGE : null),
  // The sky has changed (F-603): said to everyone, whoever is driving.
  sky: (event) => weatherNotice(event.from, event.to),
  // The marshal for a stricken car has his eyes on his phone (F-505): said of the player's car only.
  'marshal-distracted': (event, context) => (isPlayer(event.car, context) ? { text: MARSHAL_PHONE_TEXT, seconds: 3, tone: 'bad' } : null),
}

/** The event types that have a row: the HUD subscribes to exactly these. */
export const MESSAGE_EVENTS = Object.keys(ROWS) as ReadonlyArray<SimEvent['type']>

/** What `event` puts on the message line, or null for an event that says nothing. */
export function messageFor(event: SimEvent, snapshot: SessionSnapshot, playerId: CarId | null): HudMessage | null {
  // One row takes one type of event; the cast says what the lookup by the event's own type already guarantees.
  const row = ROWS[event.type] as ((event: SimEvent, context: MessageContext) => HudMessage | null) | undefined
  return row === undefined ? null : row(event, { snapshot, playerId })
}

/** The tick a message put up at `tick` is taken down on; never, for a standing message. */
export const messageUntil = (message: HudMessage, tick: Tick): Tick => tick + Math.round(message.seconds * TICK_RATE)

/** The words on the line at `tick` for a message that ends at `untilTick`; null once it is over. */
export function messageText(message: HudMessage, untilTick: Tick, tick: Tick): string | null {
  if (tick >= untilTick) return null
  if (message.countdown !== true) return message.text
  return `${message.text} ${Math.ceil((untilTick - tick) / TICK_RATE)}`
}

// ── The line ────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * What the message line remembers (F-404): the standing message, which stays until it is taken down, and the timed
 * message shown over it, which hands the line back to the standing one when its time is up. Plain data the HUD
 * keeps and these functions change.
 */
export interface MessageLine {
  standing: HudMessage | null
  timed: HudMessage | null
  /** The tick the timed message ends on. */
  timedEnds: Tick
}

export const createMessageLine = (): MessageLine => ({ standing: null, timed: null, timedEnds: 0 })

/**
 * Takes a message told at `tick` onto the line. A timed message goes over the standing one, which it leaves as it
 * was unless it says otherwise (`HudMessage.standing`). A standing message replaces the standing one, and takes the
 * line from a timed one. A message of no words (`NO_MESSAGE`) takes both down.
 */
export function postToLine(line: MessageLine, message: HudMessage, tick: Tick): void {
  if (message.seconds === Infinity) {
    line.standing = message
    line.timed = null
    return
  }
  if (message.text === '') {
    line.standing = null
    line.timed = null
    return
  }
  line.timed = message
  line.timedEnds = messageUntil(message, tick)
  if (message.standing !== undefined) line.standing = message.standing
}

/**
 * The message on the line at `tick`: the timed one until its time is up, then the standing one, then, with the
 * player's clock out and a lap still to finish (`call` is 'time-up'), TIME UP (F-509). TIME UP is the line's floor, not
 * its standing message: a message that comes while it shows is shown over it, whether it is timed or standing, and a
 * message that takes the standing message down cannot take TIME UP down with it. It comes back when they end.
 */
export function onLine(line: MessageLine, tick: Tick, call: EndCall | null = null): HudMessage | null {
  if (line.timed !== null && tick < line.timedEnds) return line.timed
  if (line.standing !== null) return line.standing
  return call === 'time-up' ? TIME_UP_MESSAGE : null
}

/** The tick the message `onLine` returned ends on: never, for the standing one. */
export const lineEnds = (line: MessageLine, shown: HudMessage): Tick => (shown === line.timed ? line.timedEnds : Infinity)

// ── The start ───────────────────────────────────────────────────────────────────────────────────────────────

/** The release the view last heard of: the tick it happened on and whose it was. */
export interface Release {
  tick: Tick
  /** The released car's number (the entry's, not its id). */
  number: number
  /** It is the player's. */
  own: boolean
}

/** What the view has noted from `phase` and `car-released` events, and the session's tick. */
export interface StartFlow {
  phase: SessionPhase
  tick: Tick
  /** The first tick of the countdown phase, null before it. */
  countdownTick: Tick | null
  /** The tick of the start tone in a final, where every car goes at once; null in a heat and before the tone. */
  goTick: Tick | null
  /** The latest release in a staggered start; null before the first. */
  release: Release | null
  /** The player is released after the start tone (a staggered start), so there is a time to wait for it. */
  staggered: boolean
  /** The player has been released. */
  ownReleased: boolean
}

/** How long "GO" stays up, in session seconds. */
export const GO_SECONDS = 1
/** The countdown shows the numbers from its start down to this one, and nothing for the seconds after it. */
export const LAST_NUMBER_S = 4

/** What the staging says, through its three seconds. */
export const GET_READY = 'DRIVERS GET READY'

/**
 * What the start says: "DRIVERS GET READY" through the staging (in the official's bubble, `saidByOfficial`); then the numbers 10 down to 4, one a second,
 * and nothing for the last three; "GO" for a second at the start tone. In a staggered start each release is called by
 * the car's number, "CAR 3", for as long as it is the car to go (`RULES.releaseIntervalS`); the player's own reads
 * "CAR 1 — GO"; "WAIT" fills in until then.
 */
export function startCallFor(flow: StartFlow): string | null {
  if (flow.phase === 'staging') return GET_READY
  if (flow.phase === 'countdown' && flow.countdownTick !== null) {
    const left = Math.ceil((flow.countdownTick + RULES.countdownS * TICK_RATE - flow.tick) / TICK_RATE)
    return left >= LAST_NUMBER_S && left <= RULES.countdownS ? String(left) : null
  }
  if (flow.phase !== 'running') return null
  const { release } = flow
  if (release !== null && flow.tick - release.tick < Math.round(RULES.releaseIntervalS * TICK_RATE)) {
    return release.own ? `CAR ${release.number} — GO` : `CAR ${release.number}`
  }
  if (flow.goTick !== null) return flow.tick - flow.goTick < GO_SECONDS * TICK_RATE ? 'GO' : null
  return flow.staggered && !flow.ownReleased ? 'WAIT' : null
}

// ── The end ─────────────────────────────────────────────────────────────────────────────────────────────────

/** The big call at the end: the player's clock is out and a lap is left to finish, the player has finished, or the session is over without the player's finish. */
export type EndCall = 'time-up' | 'finished' | 'did-not-finish'

/**
 * Which end call to show. In a final the session's `time-up` phase and the clock reaching zero are one moment; in a
 * qualifying heat the phase begins when the first car's own clock runs out, so the player's call waits for the
 * player's own clock on screen (`clockRemainingS`) to read zero.
 */
export function endCallFor(phase: SessionPhase, playerState: CarState | null, clockRemainingS: number): EndCall | null {
  if (playerState === null) return null
  if (playerState === 'finished') return phase === 'time-up' || phase === 'finished' ? 'finished' : null
  if (phase === 'time-up') return clockRemainingS <= 0 ? 'time-up' : null
  return phase === 'finished' ? 'did-not-finish' : null
}

/** The words of each end call. */
export const END_TEXT: Readonly<Record<EndCall, string>> = {
  'time-up': 'TIME UP — FINISH YOUR LAP',
  finished: 'FINISHED',
  'did-not-finish': 'DID NOT FINISH',
}

/** TIME UP as a message of the line's: standing for as long as the player has a lap to finish, and pulsing. */
export const TIME_UP_MESSAGE: HudMessage = Object.freeze({ text: END_TEXT['time-up'], seconds: Infinity, tone: 'bad', pulse: true })

// ── The start calls that the official says (F-514) ─────────────────────────────────────────────────────────

/**
 * Whether a start call is said by the official, in his bubble, and not in the middle of the screen: DRIVERS GET READY
 * through the staging (F-607), each release of a staggered start ("CAR 3", "CAR 1 — GO") and the wait for the player's
 * own. The countdown numbers and GO stay in the middle.
 */
export const saidByOfficial = (call: string): boolean => call === GET_READY || call === 'WAIT' || /^CAR \d+( — GO)?$/.test(call)

/** The words of a call said by the official, as a message of the line's: standing for as long as the call is made. Null for a call that is not his. */
export function startCallMessage(call: string | null): HudMessage | null {
  if (call === null || !saidByOfficial(call)) return null
  return { text: call, seconds: Infinity, tone: 'info' }
}

// ── Practice: the official calls each lap (F-810) ───────────────────────────────────────────────────────────

/** How long a lap call stays in the bubble, in session seconds: the time the other timed messages have. */
export const LAP_CALL_SECONDS = 3

/** A lap time as the practice readout shows it, without the minute while there is none: "18.423", "9.005", "1:02.345". */
export const lapCallTime = (ms: number): string => formatLapTime(ms).replace(/^0:0?/, '')

/** What the official's bubble says of a lap: "Lap 4: 18.423", and ", best lap" for the session's best. */
export const lapCallWords = (lap: number, lapMs: number, best: boolean): string => `Lap ${lap}: ${lapCallTime(lapMs)}${best ? ', best lap' : ''}`

const ONES = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen']
const TENS = ['', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety']

/** A whole number as words, to 999; beyond that its digits (no practice session has that many laps). */
function numberWords(n: number): string {
  if (n < 20) return ONES[n]
  if (n < 100) return n % 10 === 0 ? TENS[n / 10] : `${TENS[Math.floor(n / 10)]} ${ONES[n % 10]}`
  if (n < 1000) return n % 100 === 0 ? `${ONES[n / 100]} hundred` : `${ONES[Math.floor(n / 100)]} hundred ${numberWords(n % 100)}`
  return String(n)
}

/** What the official says aloud of a lap: "Lap four, eighteen point four two" (two decimals, each said as a digit), ", best lap" for the session's best. */
export function lapCallSpoken(lap: number, lapMs: number, best: boolean): string {
  const hundredths = Math.round(lapMs / 10)
  const minutes = Math.floor(hundredths / 6000)
  const seconds = Math.floor((hundredths % 6000) / 100)
  const rest = hundredths % 100
  const decimals = `${ONES[Math.floor(rest / 10)]} ${ONES[rest % 10]}`
  const time = `${minutes > 0 ? `${numberWords(minutes)} minute${minutes === 1 ? '' : 's'}, ` : ''}${numberWords(seconds)} point ${decimals}`
  return `Lap ${numberWords(lap)}, ${time}${best ? ', best lap' : ''}`
}

/** What the official has to say in practice, as the director takes it: the bubble's words, what is said aloud, the tone, and the tick it came up on. */
export interface PracticeSay {
  text: string
  spoken?: string
  tone: MessageTone
  /** It has no end of its own: it stays until it is taken down. */
  standing: boolean
  sinceTick: Tick
}

/** The official's first line of a practice session (F-815): the track is open. Shown and said once, when the session has loaded. */
export const OPENING_CALL = 'Track Opened for Practice'

/** A call of the official's own (the opening call or a lap) that has not been taken down yet. */
interface PendingLap {
  text: string
  spoken: string
  tone: MessageTone
  /** The tick it first came up on; null while another message has the bubble. */
  shownTick: Tick | null
}

/**
 * The official's line in practice, which has no HUD to hold one: the table's messages for the player (a car stuck and
 * its marshal on his phone) go on a `MessageLine`, and the lap the player has just completed is called whenever
 * nothing else is being said. A lap call waits for the bubble to be free, stays `LAP_CALL_SECONDS` once it is up, and is
 * replaced by a newer lap, whether it was up or waiting. "Best lap" is said of a lap that beats an earlier one, never of the first. The first crossing of the line completes no lap, so the sim
 * tells none and nothing is said.
 */
export class PracticeLine {
  private readonly line = createMessageLine()
  private lap: PendingLap | null = null
  private opening: PendingLap | null = null
  private shown: object | null = null
  private shownSince: Tick = 0

  /** The session has loaded and the car is on track: the official opens the track, before anything else he says, once. A lap call due meanwhile waits for it. */
  open(): void {
    this.opening = { text: OPENING_CALL, spoken: OPENING_CALL, tone: 'info', shownTick: null }
  }

  /** An event of the sim: the player's completed lap is the next call; a message of the table goes on the line. */
  tell(event: SimEvent, snapshot: SessionSnapshot, playerId: CarId | null): void {
    if (event.type === 'lap') {
      if (playerId === null || event.car !== playerId) return
      // The first lap is the session's best by default and beats nothing: only a later lap that sets the best says so.
      const best = event.sessionBest && event.lap > 1
      this.lap = { text: lapCallWords(event.lap, event.lapMs, best), spoken: lapCallSpoken(event.lap, event.lapMs, best), tone: best ? 'good' : 'info', shownTick: null }
      return
    }
    const message = messageFor(event, snapshot, playerId)
    if (message !== null) postToLine(this.line, message, event.tick)
  }

  /** What the official says at `tick`, or null when he has nothing to say. */
  at(tick: Tick): PracticeSay | null {
    const other = onLine(this.line, tick)
    if (other !== null) {
      const ends = lineEnds(this.line, other)
      return { text: messageText(other, ends, tick) ?? other.text, tone: other.tone, standing: ends === Infinity, sinceTick: this.since(other, tick) }
    }
    const first = this.call(this.opening, tick)
    if (first === 'done') this.opening = null
    else if (first !== null) return first
    const next = this.call(this.lap, tick)
    if (next === 'done') this.lap = null
    return next === 'done' ? null : next
  }

  /** What `call` says at `tick` (it starts its time the first tick it is asked for), 'done' once its time is up, null when there is none. */
  private call(call: PendingLap | null, tick: Tick): PracticeSay | 'done' | null {
    if (call === null) return null
    call.shownTick ??= tick
    if (tick >= call.shownTick + Math.round(LAP_CALL_SECONDS * TICK_RATE)) return 'done'
    return { text: call.text, spoken: call.spoken, tone: call.tone, standing: false, sinceTick: this.since(call, tick) }
  }

  /** The tick `what` came up on: the tick it was first asked for, kept while it stays the thing on show. */
  private since(what: object, tick: Tick): Tick {
    if (what !== this.shown) {
      this.shown = what
      this.shownSince = tick
    }
    return this.shownSince
  }
}
