import { TICK_RATE, type CarId, type CarSnapshot, type MarshalSnapshot, type MarshalState, type SessionKind, type SessionPhase, type Vec2 } from '@sim'
import { lerpPose } from './interpolate'

// What a marshal looks like at any instant (F-505), as pure rules: which of the manifest's animations he plays, how
// fast, and how his picture is blended between two ticks. `MarshalView` only draws what these say. There is no
// engine in this file, so every rule is tested in Node.

export type MarshalDir = 'up' | 'down' | 'left' | 'right'

/** The four directions, clockwise from +x (right), as the sim's angles run on a screen with y down. */
const DIRECTIONS: readonly MarshalDir[] = ['right', 'down', 'left', 'up']

/** The nearest of the four screen directions to `facingRad`, an angle clockwise from +x in any number of turns. */
export function dirOf(facingRad: number): MarshalDir {
  const quarter = Math.round(facingRad / (Math.PI / 2))
  return DIRECTIONS[((quarter % 4) + 4) % 4]
}

/** How fast the walk cycle is played, as a multiple of the manifest's own rate: a marshal's feet slide a little over the ground at this size, which is accepted. */
export const WALK_RATE = 2.5
/** The same for a marshal who is running. */
export const RUN_RATE = 3.5

/**
 * The manifest animation for a marshal, and how fast to play it (1 is the manifest's own rate). A marshal who has
 * been hit shows the flinch frame whatever else he was doing; one on the move plays the walk cycle of the direction
 * he moves in, at `WALK_RATE`, or at `RUN_RATE` if he is `running`; one at his post stands facing the way he faces;
 * one who is distracted, on his phone at his post, looks at it, whenever that is; one righting a car bends to it, and
 * once he has it in his hands (`carrying`, F-510) he walks with it: the walk cycle of the way he goes, not the bend.
 * Once the chequered flag is out (`waving`, F-711) a marshal at his post who has no car (`targetCar` null), on his phone or
 * not, waves it instead, facing as he stands; one with a car, or on his way back to his post, does what he was doing.
 */
export function marshalAnim(
  m: Pick<MarshalSnapshot, 'state' | 'facingRad'> & { carrying?: CarId | null; targetCar?: CarId | null },
  running: boolean,
  flinching: boolean,
  waving = false,
): { name: string; rate: number } {
  if (flinching) return { name: 'marshal.flinch', rate: 1 }
  if (waving && (m.targetCar ?? null) === null && (m.state === 'idle' || m.state === 'distracted')) return { name: `marshal.flag.${dirOf(m.facingRad)}`, rate: 1 }
  switch (m.state) {
    case 'idle':
      return { name: `marshal.idle.${dirOf(m.facingRad)}`, rate: 1 }
    case 'distracted':
      return { name: 'marshal.phone', rate: 1 }
    case 'righting':
      if (m.carrying !== undefined && m.carrying !== null) return { name: `marshal.walk.${dirOf(m.facingRad)}`, rate: running ? RUN_RATE : WALK_RATE }
      return { name: 'marshal.bend', rate: 1 }
    case 'walking-out':
    case 'walking-back':
      return { name: `marshal.walk.${dirOf(m.facingRad)}`, rate: running ? RUN_RATE : WALK_RATE }
  }
}

/**
 * Whether the chequered flag is out (F-711): in a heat or a final, from the moment the first car has finished until the
 * session is over. Read from the snapshot, so it holds across a pause and a resume; practice has no winner and no flag.
 */
export function flagIsOut(kind: SessionKind, phase: SessionPhase, cars: ReadonlyArray<Pick<CarSnapshot, 'state'>>): boolean {
  return kind !== 'practice' && phase !== 'finished' && cars.some((car) => car.state === 'finished')
}

/** Whether a marshal moving at `speedMS` is running: his speed is nearer `runMS` than `walkMS`. */
export const isRunning = (speedMS: number, walkMS: number, runMS: number): boolean => speedMS > (walkMS + runMS) / 2

/** How far into an animation, in frames, it is `dtS` later, at `fps` frames a second played at `rate`. Time never runs backwards. */
export function advancePhase(phase: number, dtS: number, fps: number, rate: number): number {
  return dtS > 0 ? phase + dtS * fps * rate : phase
}

/** Which of `count` frames shows `phase` frames into an animation: a loop starts again, a one-shot holds its last frame. */
export function frameAt(phase: number, count: number, loop: boolean): number {
  const frame = Math.max(0, Math.floor(phase))
  return loop ? frame % count : Math.min(frame, count - 1)
}

/** What the renderer needs of a marshal at the instant a frame is drawn: the sim's last two snapshots blended. */
export interface RenderMarshal {
  id: number
  /** World metres. */
  x: number
  y: number
  facingRad: number
  state: MarshalState
  targetCar: CarId | null
  /** The car in his hands (F-510), or null: he walks with it instead of bending to it. */
  carrying: CarId | null
  /** How fast he moved over the last tick, m/s. */
  speedMS: number
}

/**
 * Blends the previous and current snapshot of every marshal into `out`, reusing its objects, the way the cars are
 * blended. Marshals are matched by position in the arrays; one with no earlier snapshot is shown where he is. The
 * state, the target and the car he carries are the later snapshot's, never a blend.
 */
export function interpolateMarshals(prev: readonly MarshalSnapshot[], curr: readonly MarshalSnapshot[], alpha: number, out: RenderMarshal[]): void {
  out.length = curr.length
  for (let i = 0; i < curr.length; i++) {
    const b = curr[i]
    const a = prev[i] ?? b
    const target: RenderMarshal = out[i] ?? (out[i] = { id: b.id, x: 0, y: 0, facingRad: 0, state: b.state, targetCar: null, carrying: null, speedMS: 0 })
    const pose = lerpPose({ x: a.pos.x, y: a.pos.y, angle: a.facingRad }, { x: b.pos.x, y: b.pos.y, angle: b.facingRad }, alpha)
    target.id = b.id
    target.x = pose.x
    target.y = pose.y
    target.facingRad = pose.angle
    target.state = b.state
    target.targetCar = b.targetCar
    target.carrying = b.carrying
    target.speedMS = Math.hypot(b.pos.x - a.pos.x, b.pos.y - a.pos.y) * TICK_RATE
  }
}

/** The id of the marshal whose feet are nearest `at`, the lower id of two equally near; null when there are none. */
export function nearestMarshal(marshals: readonly Pick<MarshalSnapshot, 'id' | 'pos'>[], at: Readonly<Vec2>): number | null {
  let best: number | null = null
  let bestDistance = Infinity
  for (const m of marshals) {
    const distance = Math.hypot(m.pos.x - at.x, m.pos.y - at.y)
    if (distance < bestDistance || (distance === bestDistance && best !== null && m.id < best)) {
      best = m.id
      bestDistance = distance
    }
  }
  return best
}
