/**
 * The build-time switch of the debug hook's access to the scene, written out in full because the bundler does not fold a
 * constant shared between modules (F-206): the wall overlay and `DEBUG_HOOK` are development and mode `test` only. The tuning
 * tools (the panel, the racing lines, the `T TUNE   L LINES` hint) are not a build switch here since F-813: every session
 * allows tuning, and the tools are on when `toolsUnlocked` says so (from the start in development, test and demo builds; in
 * the released game once the code has been typed).
 */
const DEBUG_HOOK = import.meta.env.DEV || import.meta.env.MODE === 'test'

/** A kind of decor that has no picture is not drawn; development builds say so. */
const warnUndrawn = (kind: string): void => console.warn(`RaceScene: the track's decor has an item of kind '${kind}', which has no sprite; it is not drawn`)

/** What starts a race scene. Anything left out takes the practice defaults below. */
export interface RaceSceneData {
  config?: Partial<SessionConfig>
  /** What Enter on the results screen does when the session finishes (a quick race: back to the title; a race-day session: on to the standings). Left out, it goes to the title. */
  onContinue?: () => void
  /** Called once with the session's result, when the session has finished and the results screen is about to open (a race-day session records it here). */
  onFinished?: (result: SessionResult) => void
  /** What the results screen says Enter does, if not "continue". */
  continueHint?: string
}

/** How long after `session-finished` the results screen replaces the track: the finished cars have parked by then, and the person sees them do it. */
const RESULTS_DELAY_MS = 1500

/**
 * A practice session on the home track, raced counter-clockwise, one car on pole: the class and colour the player
 * chose in the garage (the recommended first car, red, if they chose nothing), unless `overrides` say otherwise.
 */
export function practiceSessionConfig(overrides: Partial<SessionConfig> = {}, choice: Selection = selection.get()): SessionConfig {
  // Whatever the overrides say, practice has no penalties and has reverse (F-810).
  return practiceSettings({
    seed: 1,
    kind: 'practice',
    label: 'Practice',
    track: orientTrack(cuencaRc, 'counter-clockwise'),
    carClass: choice.carClass,
    durationS: Infinity,
    entries: [{ driverId: 'player', number: 1, colour: choice.colour, controller: 'human', startSlot: 0 }],
    difficulty: 'club',
    // Practice is always calm (F-601): a lap must be comparable with a lap.
    weather: { ...CALM_WEATHER },
    ...overrides,
  })
}

/** Where the tail lamps sit, as shares of the car's length behind its centre and of its width either side of the middle. */
const LAMP_ALONG_SHARE = 0.46
const LAMP_ACROSS_SHARE = 0.34

/**
 * Practice on the home track: the track baked once, one car, the plain readout, a pause overlay on Esc or P. The
 * scene owns the session, the runner that steps it, the event bus and every renderer, and disposes all of them
 * when it shuts down. It never changes the sim: it reads snapshots and sends the keys as they are.
 */
export class RaceScene extends Phaser.Scene {
  /** Set while the scene is running (null before `create` and after shutdown). The debug hook reads these. */
  runner: SimRunner | null = null
  session: Session | null = null
  runtime: TrackRuntime | null = null
  overlay: TrackOverlay | null = null
  /** The racing lines and where each AI driver is aiming (F-301): null until the tools are unlocked and the overlay's code has loaded. */
  lineOverlay: RacingLineOverlay | null = null
  /** What a practice session shows: laps, last and best (F-106). Null in a qualifying heat or a final, which have the HUD. */
  readout: PracticeReadout | null = null
  /** The pause key the hints name, kept to word them again when the tools' hint comes or goes (F-813, F-819). */
  private pauseCode = ''
  /** What a qualifying heat or a final shows (F-304). Null in practice. */
  hud: Hud | null = null
  /** The class legend of practice, which has no HUD to carry it (F-711). Null in a heat or a final, whose HUD has its own. */
  practiceLegend: ClassLegend | null = null
  carView: CarView | null = null
  /** The tyres that mark the corners, drawn where a car has pushed them (F-308). */
  markerView: MarkerView | null = null
  /** The rubber on the track, and the smoke and dust (F-205). */
  skids: SkidLayer | null = null
  carFx: CarFx | null = null
  /** Grass thrown by a bogging car, and the tag over a stuck one (F-207). */
  surfaceFx: SurfaceFx | null = null
  strickenTag: StrickenTag | null = null
  /** The marshals at their posts and on the move (F-505). */
  marshalView: MarshalView | null = null
  /** The driver stand and the trees (F-504), and the drivers on the stand. */
  decor: DecorLayer | null = null
  /** Rain, the wet look, puddles, spray, cloud shadows and the light of the sky (F-603). */
  weatherFx: WeatherFx | null = null
  driverStand: DriverStand | null = null
  /** Everything the race hears: motors, tyres, effects, weather, the start tones (F-704). Null when the game has no mixer, and after shutdown. */
  audio: RaceAudio | null = null
  /** The official at the bottom left and his bubble, which carries every message to the player (F-509). */
  official: Official | null = null
  /** Who has the window, the official or the commentator, and the voice in step with the words (F-703). */
  director: CommentaryDirector | null = null
  /** What the official has to say in practice, which has no HUD to say it: each lap the player completes (F-810). Null in a heat or a final. */
  private practiceLine: PracticeLine | null = null
  /** Lines the debug hook has asked the commentator to say before anything the engine has: for tests only, empty in play. */
  private readonly asked: SpokenLine[] = []
  readonly bus = new EventBus()
  /** When the drivers whose marshals are on their phones shout "Marshal!" (F-708). */
  private shouts = new ShoutClock()

  private config: SessionConfig = practiceSessionConfig()
  /** What this scene was started with, so that the pause overlay can start the same session again. */
  private startData: RaceSceneData = {}
  private view: WorldView = fitWorld(this.config.track.bounds, { w: LOGICAL_WIDTH, h: LOGICAL_HEIGHT }, 0)
  private ground: TrackRenderer | null = null
  private keyboard: Keyboard | null = null
  private release: Array<() => void> = []
  private readonly renderCars: RenderCar[] = []
  /** The frame clock's last timestamp, -1 when the next frame should not count the time since. */
  private lastTime = -1
  /** True from the moment the pause overlay is asked for until the race resumes: scene changes take effect a frame later. */
  private pausing = false
  /** The car the keyboard drives: the human entry, wherever it is on the grid (null if the game drives every car). */
  private playerCar: CarId | null = null
  /** Set once the session has finished and the results screen is on its way. */
  private finishing = false
  /** The autopilot has driven the player's car at some point of this session: its result counts for nothing on the leaderboards (F-406). Set by the debug hook only. */
  autopilotUsed = false
  /** The player's car is the DRIVING ASSISTANCE car (F-811): the setting was on when this session was built. The tuning panel and the results read it. */
  assisted = false

  constructor() {
    super('Race')
  }

  init(data: RaceSceneData): void {
    this.startData = data
    // Every session lets the tuning panel (F-206) change the car's parameters mid-session, once the tools are unlocked (F-813; they are, from
    // the start, in development, test and demo builds). Nothing is tuned unless the panel is used, and a session it touched sets no record.
    // DRIVING ASSISTANCE (F-811), read as the session is built: the player's car alone is the NEWBIE car, from its first tick.
    this.config = assistedConfig(practiceSessionConfig({ allowTuning: true, ...data.config }), saves.read().settings.drivingAssistance)
    this.assisted = isAssistedConfig(this.config)
    this.playerCar = playerCarId(this.config.entries)
    this.finishing = false
    this.autopilotUsed = false
  }

  /** Fetches the chosen class's car atlas if the garage has not already (ADR-005: only what a session needs is loaded). */
  preload(): void {
    const manifest = manifestOf(this)
    // The people, the props and the portrait and bubbles are small and every race has them: the drivers, the stand, the trees, the official;
    // and the HUD's sky icons and windsock.
    const trackside = ['people', 'props', 'ui', 'hud'].map((atlas) => queueAtlas(this, manifest, atlas))
    if (queueClassAtlas(this, this.config.carClass) || trackside.includes(true)) {
      const { width, height } = this.scale
      // A file that does not arrive puts the error screen up (F-803); until they have all come there is the word and a bar that fills.
      failOnLoadError(this)
      text(this, { x: width / 2, y: height / 2 - 60 }, 'LOADING', 'body').setOrigin(0.5).setTint(THEME.colours.textDim).setName('loading')
      const bar = new LoadingBar(this, { x: width / 2, y: height / 2 }, 'loading')
      this.load.on(Phaser.Loader.Events.PROGRESS, (share: number) => bar.set(share))
      this.load.once(Phaser.Loader.Events.COMPLETE, () => bar.destroy())
    }
  }

  create(): void {
    if (hasFailed(this.game)) return
    // The pause key is the player's to move (F-801); Esc always pauses.
    const pauseCode = saves.read().settings.bindings.pause
    this.pauseCode = pauseCode
    const manifest = manifestOf(this)
    const { track } = this.config
    this.children.getByName('loading')?.destroy()
    this.view = fitWorld(track.bounds, { w: LOGICAL_WIDTH, h: LOGICAL_HEIGHT }, 0)
    this.lastTime = -1
    this.pausing = false

    this.session = createSession(this.config)
    this.runner = new SimRunner(this.session)

    this.ground = new TrackRenderer(this, track, this.view)
    // What lies flat (the stand, the pit tables) goes into the ground; the trees and the drivers stand over it.
    this.decor = new DecorLayer(this, this.view, track, manifest, this.ground, import.meta.env.DEV ? warnUndrawn : undefined)
    this.ground.bake()
    this.driverStand = new DriverStand(this, this.view, track, manifest, this.bus, this.config.entries, this.config.reverse !== false)
    // On the ground, under everything else: the tyres, which the ground no longer holds because they move (F-308).
    this.markerView = new MarkerView(this, this.view, track)

    // Under the cars, over the ground: the rubber every car lays, from the first tick of the session (F-205).
    const params = classes[this.config.carClass]
    const geometry = resolveCar(params, tuning)
    // A car with its own parameters (the assisted car, F-811) lays its rubber where its own wheels are.
    this.skids = new SkidLayer(this, this.view, this.config.entries.map((entry) => ({ geometry: entry.params ?? geometry })))
    this.carFx = new CarFx(this, this.view, this.config.entries.map(() => ({ geometry, lengthM: params.lengthM })), this.config.seed)
    this.carView = new CarView(this, this.view, this.looks(manifest))
    // The weather over it all: the wet look under the cars, the spray, shadows and rain over them. A forecast that cannot rain on a dry track has no wet pictures to make.
    const { weather } = this.config
    this.weatherFx = new WeatherFx(this, {
      view: this.view,
      track,
      bus: this.bus,
      cars: this.config.entries.map(() => ({ lengthM: params.lengthM, widthM: params.widthM })),
      seed: this.config.seed,
      lineWidthM: params.widthM,
      eager: weather.forecast !== 'dry' || weather.initialWetness > 0,
    })
    // Surfaces (F-207): the lift over a kerb, grass thrown by a bogging car, and STUCK over the player's car.
    const wheels = drivenWheels(classes[this.config.carClass])
    this.surfaceFx = new SurfaceFx(this, this.view, this.config.entries.map(() => wheels))
    this.strickenTag = new StrickenTag(this, this.view, this.config.entries.flatMap((entry, id) => (entry.controller === 'human' ? [id] : [])), this.config.reverse !== false)
    // The marshals (F-505): drawn over the cars, and the view of a roll and of a hit.
    const { marshal: marshalRules } = INCIDENT_TUNING
    this.marshalView = new MarshalView(this, this.view, manifest, marshalRules)
    this.bus.on('kerb-hop', (hop) => this.carView?.hop(hop.car, hop.tick, hop.airborneTicks))
    this.bus.on('flip', (flip) => this.carView?.flip(flip.car, flip.tick))
    this.bus.on('contact', (hit) => {
      if (hit.other === 'wall') this.carFx?.wall(hit.car, hit.impulseNs, this.runner?.prev.cars[hit.car], this.runner?.curr.cars[hit.car])
      const struck = this.runner?.curr.cars[hit.car]
      if (hit.other === 'marshal' && struck !== undefined) this.marshalView?.flinch(hit.car, struck.pose, hit.tick / TICK_RATE, Math.abs(struck.speedMS))
    })
    this.bus.on('session-finished', () => this.finish())
    // The official, in the bottom left under the stand's top edge: practice has him too, with nothing to say (F-509).
    const stand = standRect(track, this.view.pxPerM)
    const slab = trackRect(track, this.view)
    const official = new Official(this, manifest, stand === null ? Math.ceil(slab.y + slab.h) : this.view.originY + stand.y, stand === null ? null : this.view.originX + stand.x)
    this.official = official
    // Who has his window (F-703): the commentary engine's lines when the official has nothing to say, the speech in step with them.
    this.asked.length = 0
    this.shouts = new ShoutClock()
    this.director = new CommentaryDirector(
      this.config.kind === 'practice' ? NO_COMMENTATOR : this.commentator(),
      official,
      ttsOf(this.registry, () => mixerOf(this.registry)?.voiceVolume() ?? 1),
      { speech: speechOn, commentaryColour: THEME.colours.text, onTalking: (speaker, on) => mixerOf(this.registry)?.setSpeaking(on, speaker) },
    )
    // What the session shows (F-304): practice keeps the plain readout; a heat or a final has the HUD.
    if (this.config.kind === 'practice') {
      this.readout = new PracticeReadout(this, 'pixel', fontScale(manifest, 'pixel') * 1.5, keyHint(pauseCode, toolsHinted(this.registry)), this.assisted)
      // No commentator here (F-810): the window is the official's, and he opens the track (F-815) and calls each lap the player completes.
      const line = new PracticeLine()
      line.open()
      this.practiceLine = line
      const runner = this.runner
      for (const type of ['lap', ...MESSAGE_EVENTS] as const) this.bus.on(type, (event) => line.tell(event, runner.curr, this.playerCar))
      this.practiceLegend = new ClassLegend(this, CLASS_LEGEND[this.config.carClass], roundWords(this.config.kind, this.config.label), Math.max(0, Math.floor(slab.y)), true)
    } else {
      const runner = this.runner
      this.hud = new Hud(this, {
        config: this.config,
        director: this.director,
        manifest,
        bus: this.bus,
        view: this.view,
        snapshot: () => runner.curr,
        hint: keyHint(pauseCode, toolsHinted(this.registry)),
        carLengthM: params.lengthM,
        playerId: this.playerCar,
      })
    }

    // The sound (F-704), on the mixer the boot scene made. It reads the bus and the snapshot; it never touches the sim.
    const mixer = mixerOf(this.registry)
    if (mixer !== null) {
      this.audio = new RaceAudio(mixer, this.bus, {
        classId: this.config.carClass,
        kind: this.config.kind,
        cars: this.config.entries.length,
        playerCar: this.playerCar,
        panOf: (worldX) => panForScreenX(this.view.originX + worldX * this.view.pxPerM),
        volumes: saves.read().settings.volume,
      })
    }

    // The wall overlay and the hook's access to the scene: development and test builds only.
    if (DEBUG_HOOK) {
      this.runtime = buildTrackRuntime(track)
      this.overlay = new TrackOverlay(this, this.runtime, this.view)
    }

    const keyboard = this.input.keyboard
    if (keyboard === null) throw new Error('RaceScene: the keyboard plugin is not available')
    this.keyboard = new Keyboard(this, keyboard)
    this.release.push(onKey(keyboard, 'ESC', () => this.pause()), onCode(keyboard, pauseCode, () => this.pause()))
    // The music (F-705): the session's piece plays during a session, and M turns the music off and on.
    musicOf(this.registry)?.play('session')
    this.release.push(onKey(keyboard, 'M', () => toggleMusic(this.registry)))
    // Speech (F-703): V turns the spoken commentary and race control on and off, and the choice is remembered.
    this.release.push(onKey(keyboard, 'V', () => void toggleSpeech()))
    const overlay = this.overlay
    if (overlay !== null) this.release.push(onKey(keyboard, 'O', () => overlay.toggle()))
    // The racing-line overlay (F-301), on the L key, and the hint for it and the panel: once the tools are unlocked. In development, test
    // and demo builds that is at once; in the released game it is the moment the code is typed, even in a race that is running (F-813).
    if (toolsUnlocked(this.registry)) this.enableLines(keyboard, track, params.widthM)
    else {
      const onUnlocked = (): void => {
        this.enableLines(keyboard, track, params.widthM)
        this.applyCleanCapture()
      }
      this.game.events.once(TOOLS_UNLOCKED, onUnlocked)
      this.release.push(() => this.game.events.off(TOOLS_UNLOCKED, onUnlocked))
    }

    this.events.on(Phaser.Scenes.Events.PAUSE, this.onPause, this)
    this.events.on(Phaser.Scenes.Events.RESUME, this.onResume, this)
    this.game.events.on(Phaser.Core.Events.HIDDEN, this.onHidden, this)
    this.game.events.on(Phaser.Core.Events.VISIBLE, this.onVisible, this)
    this.game.events.on(GRAPHICS_LOST, this.onGraphicsLost, this)
    this.game.events.on(GRAPHICS_RESTORED, this.onGraphicsRestored, this)
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, this.dispose, this)

    this.draw()
  }

  /** Words the key hints again from what the registry says now: the tools unlocked in a race that is running (F-813), or the clean-capture flag changed by the debug hook (F-819). */
  applyCleanCapture(): void {
    const hint = keyHint(this.pauseCode, toolsHinted(this.registry))
    this.readout?.setHint(hint)
    this.hud?.setHint(hint)
  }

  /**
   * The racing lines (F-301), on the L key: loads the overlay's code (a chunk of its own, already fetched by the unlock where it
   * came from the code, F-813) and binds the key. Called once the tools are unlocked, at the scene's start or in the middle of a race.
   */
  private enableLines(keyboard: Phaser.Input.Keyboard.KeyboardPlugin, track: SessionConfig['track'], widthM: number): void {
    const session = this.session
    if (session === null) return
    const runtime = this.runtime ?? buildTrackRuntime(track)
    void import('../debug/RacingLineOverlay').then(({ RacingLineOverlay }) => {
      // The scene may have shut down, or started another session, while the code was on its way.
      if (this.session !== session || this.lineOverlay !== null) return
      this.lineOverlay = new RacingLineOverlay(this, session, runtime, widthM, this.view)
    })
    this.release.push(onKey(keyboard, 'L', () => this.lineOverlay?.toggle()))
  }

  /** The frame clock: `time` is the raw timestamp of this frame, not Phaser's smoothed delta (AGENTS.md, Phaser rule 3). */
  update(time: number): void {
    const { runner, keyboard } = this
    if (runner === null || keyboard === null) return
    const elapsedMs = this.lastTime < 0 ? 0 : time - this.lastTime
    this.lastTime = time

    if (this.playerCar !== null) runner.setInput(this.playerCar, keysToInput(keyboard.held()))
    const events = runner.advance(elapsedMs)
    this.bus.emit(events)
    this.director?.onSimEvents(events, runner.curr, this.sessionTimeS(runner))
    this.draw()
    this.weatherFx?.update(elapsedMs / 1000, runner.curr.weather, this.renderCars, runner.curr.cars)
    // Tyres leave no marks on a wet track (F-603): a car laying them stops when the surface under it is wetter than the limit.
    if (this.weatherFx !== null) for (const car of this.renderCars) this.skids?.setEnabledFor(car.id, this.weatherFx.skidsAllowed(car.id))
    this.skids?.update(this.renderCars, runner.curr.cars)
    this.carFx?.update(elapsedMs / 1000, this.renderCars, runner.curr.cars)
    this.surfaceFx?.update(elapsedMs / 1000, this.renderCars, runner.prev.cars, runner.curr.cars)
    this.audio?.update(elapsedMs / 1000, runner.curr, this.renderCars)
  }

  private draw(): void {
    const { runner } = this
    if (runner === null) return
    interpolateCars(runner.prev.cars, runner.curr.cars, runner.alpha, this.renderCars)
    // The instant being drawn, on the sim's clock: `alpha` of the way from the tick before to the current one.
    this.carView?.carrying(runner.curr.marshals)
    this.carView?.update(this.renderCars, runner.curr.tick - 1 + runner.alpha, runner.curr.cars)
    this.strickenTag?.update(this.renderCars, runner.curr.cars)
    // From the first car's chequered flag to the end of the session, every marshal with no car waves his (F-711).
    const flagOut = flagIsOut(this.config.kind, runner.curr.phase, runner.curr.cars)
    this.marshalView?.update(runner.prev.marshals, runner.curr.marshals, runner.alpha, (runner.curr.tick - 1 + runner.alpha) / TICK_RATE, flagOut)
    this.markerView?.update(runner.prev.markers, runner.curr.markers, runner.alpha)
    this.lineOverlay?.update(runner.curr.cars)
    // The readout and the HUD follow the player's car, wherever it is on the grid, not car 0.
    if (this.playerCar !== null) this.readout?.update(runner.curr.cars[this.playerCar])
    this.hud?.update(runner.curr, this.renderCars)
    const timeS = this.sessionTimeS(runner)
    this.driverStand?.update(timeS)
    // The drivers of stricken cars whose marshals are on their phones shout "Marshal!" every two seconds (F-708): aloud, or, where it is not, in the stand's bubble.
    // Nobody shouts once the session is over.
    const calling = this.finishing ? [] : callingCars(runner.curr.cars, runner.curr.marshals, this.config.reverse !== false)
    if (this.shouts.update(timeS, calling).length > 0) this.director?.shout(timeS)
    this.director?.calling(calling.length > 0)
    if (calling.length === 0) this.director?.hush()
    this.driverStand?.showHelp(runner.curr.cars, this.director?.shoutsAloud() === true ? undefined : this.shouts.pulses(timeS))
    // The HUD has just told the director what the official has to say (in practice, the scene does); it decides who has the window, and the portrait follows.
    this.callLap(runner)
    this.director?.update(timeS)
    this.official?.update(timeS)
  }

  /** The instant being drawn on the sim's clock, s: `alpha` of the way from the tick before to the current one. A pause holds it. */
  private sessionTimeS(runner: SimRunner): number {
    return (runner.curr.tick - 1 + runner.alpha) / TICK_RATE
  }

  /** In practice: tells the director what the official has to say, a lap call or a message of the table (F-810). */
  private callLap(runner: SimRunner): void {
    const { practiceLine } = this
    if (practiceLine === null) return
    const said = practiceLine.at(runner.curr.tick)
    this.director?.official(
      said === null ? null : { text: said.text, colour: MESSAGE_COLOUR[said.tone], standing: said.standing, since: said.sinceTick / TICK_RATE, ...(said.spoken === undefined ? {} : { spoken: said.spoken }) },
    )
  }

  /** The commentator of a heat or a final: the engine's lines, and the ones the debug hook asks for, before them. */
  private commentator(): CommentaryEngine {
    const name = storedName(saves.read())
    const engine = createCommentary(COMMENTARY_LINES, ROSTER, this.config.seed, { kind: this.config.kind, entries: this.config.entries, ...(name === null ? {} : { playerName: name }) })
    return { observe: (events, snapshot, nowS) => engine.observe(events, snapshot, nowS), next: (nowS, busy) => (busy ? null : this.asked.shift()) ?? engine.next(nowS, busy) }
  }

  /** Has the commentator say `words` next, for `durationS` seconds, before anything the engine has. For the debug hook. */
  commentate(words: string, durationS: number): void {
    this.asked.push({ id: 'debug', voice: 'commentator', text: words, expiresAtS: Infinity, estimatedDurationS: durationS })
  }

  private looks(manifest: AssetManifest): CarLook[] {
    const { carClass } = this.config
    const params = classes[carClass]
    const limit = gripLimitMS2(resolveCar(params, tuning))
    // The assisted car (F-811) has more grip, and squeals where its own limit is.
    return this.config.entries.map((entry) => ({
      body: directionSet(manifest, carSpriteName(carClass, entry.colour)),
      flipped: directionSet(manifest, flippedSpriteName(carClass, entry.colour)),
      shadow: directionSet(manifest, shadowSpriteName(carClass)),
      number: directionSet(manifest, numberSpriteName(carClass, entry.number)),
      numberTint: NUMBER_TINT[entry.colour],
      lamps: { alongM: params.lengthM * LAMP_ALONG_SHARE, acrossM: params.widthM * LAMP_ACROSS_SHARE },
      gripLimitMS2: entry.params === undefined ? limit : gripLimitMS2(entry.params),
    }))
  }

  /**
   * The session is over and the finished cars have parked: a moment later the results screen takes over. What its
   * Enter does is the caller's (`onContinue`); a session started without one goes to the title.
   */
  private finish(): void {
    if (this.finishing) return
    this.finishing = true
    this.time.delayedCall(RESULTS_DELAY_MS, () => {
      const result = this.session?.result() ?? null
      if (result === null) return
      const scenes = this.game.scene
      const player = this.playerCar === null ? undefined : this.config.entries[this.playerCar]
      const tuned = this.session !== null && isTunedSession(this.session)
      this.startData.onFinished?.(result)
      // How it ended, for the commentator to say on the screens that follow (F-703); a race day's standings and podium read it from the registry.
      const closing: Closing | null = this.runner === null ? null : { snapshot: structuredClone(this.runner.curr), config: this.config }
      if (closing !== null && this.startData.onFinished !== undefined) this.registry.set(CLOSING_KEY, closing)
      const init: ResultsInit = {
        result,
        playerId: player?.driverId ?? '',
        entries: this.config.entries,
        config: this.config,
        tuned,
        assisted: this.assisted,
        autopilot: this.autopilotUsed,
        onContinue: this.startData.onContinue ?? (() => scenes.start('Title')),
        ...(closing === null ? {} : { closing }),
        ...(this.startData.continueHint === undefined ? {} : { continueHint: this.startData.continueHint }),
      }
      this.scene.start('Results', init)
    })
  }

  private pause(): void {
    if (this.pausing) return
    this.pausing = true
    const data: PauseSceneData = { restart: this.startData }
    this.scene.launch('Pause', data)
    this.scene.pause()
  }

  private onPause(): void {
    if (this.runner !== null) this.runner.paused = true
    // Every voice and every sound in flight stops with the race (F-704): the mixer suspends its context, and speech is paused with it (F-703).
    mixerOf(this.registry)?.suspend()
    this.director?.pause()
  }

  /** Back from the pause overlay: the time spent paused is not owed to the sim, so the clock starts afresh. */
  private onResume(): void {
    this.pausing = false
    this.lastTime = -1
    if (this.runner !== null) this.runner.paused = false
    mixerOf(this.registry)?.resume()
    this.director?.resume()
  }

  /** The tab is hidden: stop at once, and show the pause overlay for when it comes back. */
  private onHidden(): void {
    if (this.runner !== null) this.runner.paused = true
    this.pause()
  }

  /** The tab is back. If the game was running, the frame that follows must not count the time away. */
  private onVisible(): void {
    this.lastTime = -1
  }

  /** The browser took the graphics away (F-803): the race stops where it is, as it does for a hidden tab, and the pause overlay waits for the picture to come back. */
  private onGraphicsLost(): void {
    if (this.runner !== null) this.runner.paused = true
    mixerOf(this.registry)?.suspend()
  }

  /** The graphics are back, and empty of everything drawn into a texture: the ground and the tyres are drawn again, and the race comes up paused, for the player to go on from. */
  private onGraphicsRestored(): void {
    this.ground?.rebake()
    this.pause()
  }

  private dispose(): void {
    this.game.events.off(GRAPHICS_LOST, this.onGraphicsLost, this)
    this.game.events.off(GRAPHICS_RESTORED, this.onGraphicsRestored, this)
    this.events.off(Phaser.Scenes.Events.PAUSE, this.onPause, this)
    this.events.off(Phaser.Scenes.Events.RESUME, this.onResume, this)
    this.game.events.off(Phaser.Core.Events.HIDDEN, this.onHidden, this)
    this.game.events.off(Phaser.Core.Events.VISIBLE, this.onVisible, this)
    for (const off of this.release) off()
    this.release = []
    // Every oscillator and node the race made is stopped and disconnected, and the mixer is handed back running (F-704).
    this.audio?.destroy()
    this.audio = null
    // Back among the menus (results, standings, title): the menu piece. A restart asks for the session's again at once, and the player never heard the change.
    musicOf(this.registry)?.play('title')
    this.keyboard?.destroy()
    this.keyboard = null
    this.carView?.destroy()
    this.carView = null
    this.weatherFx?.destroy()
    this.weatherFx = null
    this.carFx?.destroy()
    this.carFx = null
    this.skids?.destroy()
    this.skids = null
    this.surfaceFx?.destroy()
    this.surfaceFx = null
    this.strickenTag?.destroy()
    this.strickenTag = null
    this.marshalView?.destroy()
    this.marshalView = null
    this.readout?.destroy()
    this.readout = null
    this.practiceLine = null
    this.hud?.destroy()
    this.hud = null
    this.practiceLegend?.destroy()
    this.practiceLegend = null
    // Speech is cancelled and the window put away with the scene (F-703).
    this.director?.dispose()
    this.director = null
    this.official?.destroy()
    this.official = null
    this.overlay?.destroy()
    this.overlay = null
    this.lineOverlay?.destroy()
    this.lineOverlay = null
    this.markerView?.destroy()
    this.markerView = null
    this.driverStand?.destroy()
    this.driverStand = null
    this.decor?.destroy()
    this.decor = null
    this.ground?.destroy()
    this.ground = null
    this.bus.clear()
    this.runner = null
    this.session = null
    this.runtime = null
    this.renderCars.length = 0
  }
}
