import Phaser from 'phaser'
import { CREDITS, type CreditsSection } from '@content/credits'
import { LOGICAL_HEIGHT, LOGICAL_WIDTH } from '../config'
import { onNav, type NavKey } from '../input/keys'
import { THEME, lineHeight, text, type HasReadout, type ScreenReadout } from '../ui'

/** One line of the credits as laid out: its words (in capitals, as the screens print them), its size and colour, and where it stands in the block. */
interface Placed {
  words: string
  size: 'large' | 'body'
  tint: number
  /** The line's top, px below the top of the block. */
  y: number
}

/** Space after a heading, after a line, and between two sections, logical px. */
const AFTER_HEADING = 16
const AFTER_LINE = 14
const AFTER_SECTION = 40

/** The credits' data (`src/content/credits.ts`) as lines in a column: a heading in the title colour, then its lines. Returns them and the height of the block. */
export function layoutCredits(sections: readonly CreditsSection[]): { placed: Placed[]; height: number } {
  const placed: Placed[] = []
  let y = 0
  for (const section of sections) {
    placed.push({ words: section.heading.toUpperCase(), size: 'large', tint: THEME.colours.accent, y })
    y += lineHeight('large') + (section.lines.length > 0 ? AFTER_HEADING : 0)
    for (const line of section.lines) {
      placed.push({ words: line.toUpperCase(), size: 'body', tint: THEME.colours.text, y })
      y += lineHeight('body') + AFTER_LINE
    }
    y += AFTER_SECTION
  }
  return { placed, height: y }
}

/** How fast the credits rise, logical pixels a second. */
const SPEED_PX_S = 80
/** The strip under the key line, px high, and its depth over the credits' text. */
const STRIP_PX = 110
const DEPTH_STRIP = 5

/**
 * The credits (F-805, from `src/content/credits.ts`): scrolling text. The text rises from the bottom of the screen, goes off
 * the top and starts again from the bottom; Enter or Esc goes back to the title.
 */
export class CreditsScene extends Phaser.Scene implements HasReadout {
  private lines: Phaser.GameObjects.BitmapText[] = []
  /** Where each line stands in the block, and the block's height. */
  private ys: number[] = []
  private height = 0
  private parts: Phaser.GameObjects.GameObject[] = []
  private release: (() => void) | null = null
  private startedAt = -1
  private offset = 0
  private handled = 0

  constructor() {
    super('Credits')
  }

  create(): void {
    this.handled = 0
    this.startedAt = -1
    this.offset = 0
    this.cameras.main.setBackgroundColor(THEME.colours.background)
    const { placed, height } = layoutCredits(CREDITS)
    this.height = height
    this.ys = placed.map((one) => one.y)
    this.lines = placed.map((one) => text(this, { x: LOGICAL_WIDTH / 2, y: LOGICAL_HEIGHT }, one.words, one.size).setOrigin(0.5, 0).setTint(one.tint))
    // The key line stands on a strip of its own, over the text rising behind it.
    this.parts.push(
      this.add.rectangle(0, LOGICAL_HEIGHT - STRIP_PX, LOGICAL_WIDTH, STRIP_PX, THEME.colours.background).setOrigin(0, 0).setDepth(DEPTH_STRIP),
      text(this, { x: LOGICAL_WIDTH / 2, y: LOGICAL_HEIGHT - 72 }, 'ENTER OR ESC TO GO BACK', 'small').setOrigin(0.5, 0).setTint(THEME.colours.textDim).setDepth(DEPTH_STRIP + 1),
    )
    this.place()
    this.release = onNav(this, (key) => this.onKey(key))
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, this.dispose, this)
  }

  readout(): ScreenReadout {
    return { focus: 'back', values: { handled: this.handled, lines: this.lines.length, offset: Math.round(this.offset) } }
  }

  /** The frame clock's timestamp: the credits' position is a function of the time since they began. */
  update(time: number): void {
    if (this.startedAt < 0) this.startedAt = time
    this.offset = ((time - this.startedAt) / 1000) * SPEED_PX_S
    this.place()
  }

  /** Puts each line where the scroll has it; the block starts below the screen and the loop is one screen plus the block's height long. */
  private place(): void {
    const shift = this.offset % (LOGICAL_HEIGHT + this.height)
    this.lines.forEach((line, i) => line.setY(Math.round(LOGICAL_HEIGHT - shift + (this.ys[i] ?? 0))))
  }

  private onKey(key: NavKey): void {
    this.handled++
    if (key === 'confirm' || key === 'back') {
      this.stopListening()
      this.scene.start('Title', {})
    }
  }

  private stopListening(): void {
    this.release?.()
    this.release = null
  }

  private dispose(): void {
    this.stopListening()
    for (const line of this.lines) line.destroy()
    this.lines = []
    this.ys = []
    for (const part of this.parts) part.destroy()
    this.parts = []
  }
}
