import Phaser from 'phaser'
import type { Point, TrackData } from '@sim'
import type { WorldView } from '../config'
import { snapCentre } from './decor-layout'
import { DEPTH } from './depth'
import {
  checkerQuads,
  dashSegments,
  glyphArtPx,
  glyphCols,
  looseTyres,
  orderCommands,
  ringSectorTriangles,
  scatterPoints,
  strokeTriangles,
  trackDrawList,
  tyreParts,
  tyrePicturePx,
  tyreTextureKey,
  type DrawCommand,
} from './track-draw'
import {
  BAKE_SCALE,
  CHECKER_COLORS,
  DEFAULT_STYLE,
  FONT_ATLAS,
  glyphFrame,
  GLYPH,
  GRAIN_COLOR,
  GRAIN_FLECK_PX,
  TUFT_COLORS,
  TUFT_PX,
  type TrackStyle,
} from './track-style'

/**
 * The ground of a race: the track's draw list, baked once into one texture and shown as one image. The texture
 * has BAKE_SCALE times the screen's pixels each way and is shown at that fraction of its size with linear
 * filtering, which averages each screen pixel from the baked pixels under it: lines, kerbs and the edges of
 * every surface come out smooth. It is the only texture in the game that is filtered; whatever is painted on
 * whole screen pixels (the grain, the tufts, the digits) stays as hard as it was drawn. A scene creates it, may
 * add commands with `addToBake`, calls `bake()` once, and `destroy()`s it on shutdown (it also does so itself
 * when the scene shuts down).
 *
 * The tyres are not in the ground: they move (F-308). `bake()` makes one small picture of a tyre for each size the
 * track has, at the same scale and with the same filtering as the ground, under `tyreTextureKey`; MarkerView
 * shows one of them for every tyre, where the tyre is.
 */
export class TrackRenderer {
  static readonly TEXTURE_KEY = 'track-ground'

  private readonly extra: DrawCommand[] = []
  private image: Phaser.GameObjects.Image | null = null
  /** The textures of the tyre pictures this renderer made. */
  private readonly tyreKeys: string[] = []
  /** The outer radius of the tyre each of those pictures is of, by key. */
  private readonly tyreRadii = new Map<string, number>()
  private baked = false
  private destroyed = false
  /** Which of the font's glyph pixels are ink, by character: rows of the digit's height, columns of its width. */
  private readonly glyphBits = new Map<string, boolean[][]>()

  constructor(
    private readonly scene: Phaser.Scene,
    private readonly track: TrackData,
    private readonly view: WorldView,
    private readonly style: TrackStyle = DEFAULT_STYLE,
  ) {
    // A texture left behind by a scene that did not clean up would otherwise be found instead of replaced.
    if (scene.textures.exists(TrackRenderer.TEXTURE_KEY)) scene.textures.remove(TrackRenderer.TEXTURE_KEY)
    scene.events.once(Phaser.Scenes.Events.SHUTDOWN, this.destroy, this)
  }

  /** Extra commands, in world metres, drawn into the same texture in their stated layer order. Call before `bake()`. */
  addToBake(commands: DrawCommand[]): void {
    if (this.baked) throw new Error('TrackRenderer: addToBake() after bake()')
    this.extra.push(...commands)
  }

  bake(): void {
    if (this.baked) throw new Error('TrackRenderer: bake() called twice')
    if (this.destroyed) throw new Error('TrackRenderer: bake() after destroy()')
    this.baked = true

    const { scene } = this
    const { width, height } = scene.scale
    const texture = scene.textures.addDynamicTexture(TrackRenderer.TEXTURE_KEY, width * BAKE_SCALE, height * BAKE_SCALE)
    if (texture === null) throw new Error('TrackRenderer: the ground texture could not be created')
    texture.setFilter(Phaser.Textures.FilterMode.LINEAR)
    this.paintGround(texture)

    this.image = scene.add.image(0, 0, TrackRenderer.TEXTURE_KEY).setOrigin(0, 0).setScale(1 / BAKE_SCALE).setDepth(DEPTH.ground)

    for (const r of new Set(looseTyres(this.track).map((tyre) => tyre.r))) this.bakeTyre(r)
  }

  /**
   * Draws everything again into the textures that are there. A lost graphics context takes the contents of every texture the
   * engine drew into with it (F-803; the ones loaded from files it puts back by itself), so the scene calls this when
   * the context is restored. The pictures, their sizes and their keys are the ones that were baked.
   */
  rebake(): void {
    if (!this.baked || this.destroyed) return
    const ground = this.scene.textures.get(TrackRenderer.TEXTURE_KEY)
    if (ground instanceof Phaser.Textures.DynamicTexture) this.paintGround(ground)
    for (const [key, r] of this.tyreRadii) {
      const tyre = this.scene.textures.get(key)
      if (tyre instanceof Phaser.Textures.DynamicTexture) this.paintTyre(tyre, r)
    }
  }

  /** The ground's pictures, in order, into `texture`. */
  private paintGround(texture: Phaser.Textures.DynamicTexture): void {
    const { scene } = this
    // Everything outside the track's bounds, out to the edge of the screen, is outfield.
    texture.fill(this.style.outfieldGrass)

    // The painted commands go through one Graphics until a picture from an atlas comes: that is stamped on what is
    // painted so far, and the commands after it go through a new Graphics. The texture's own command buffer keeps the order.
    let g = scene.make.graphics({}, false)
    const runs = [g]
    for (const command of orderCommands(trackDrawList(this.track, this.style), this.extra)) {
      if (command.op === 'sprite') {
        texture.draw(g)
        this.stamp(texture, command)
        g = scene.make.graphics({}, false)
        runs.push(g)
      } else {
        this.paint(g, command)
      }
    }
    texture.draw(g)
    texture.render()
    for (const run of runs) run.destroy()
  }

  /** The picture of one tyre of outer radius `r`, in the middle of a texture of its own. */
  private bakeTyre(r: number): void {
    const { scene } = this
    const key = tyreTextureKey(r)
    if (scene.textures.exists(key)) scene.textures.remove(key)
    const side = tyrePicturePx(r, this.view.pxPerM) * BAKE_SCALE
    const texture = scene.textures.addDynamicTexture(key, side, side)
    if (texture === null) throw new Error(`TrackRenderer: the tyre texture '${key}' could not be created`)
    texture.setFilter(Phaser.Textures.FilterMode.LINEAR)
    this.tyreKeys.push(key)
    this.tyreRadii.set(key, r)
    this.paintTyre(texture, r)
  }

  private paintTyre(texture: Phaser.Textures.DynamicTexture, r: number): void {
    const side = tyrePicturePx(r, this.view.pxPerM) * BAKE_SCALE
    const g = this.scene.make.graphics({}, false)
    const scale = this.view.pxPerM * BAKE_SCALE
    for (const part of tyreParts(r)) {
      g.fillStyle(part.color, 1)
      const tris = ringSectorTriangles(side / 2, side / 2, part.inner * scale, part.outer * scale, part.from, part.to)
      for (let i = 0; i < tris.length; i += 6) g.fillTriangle(tris[i], tris[i + 1], tris[i + 2], tris[i + 3], tris[i + 4], tris[i + 5])
    }
    texture.draw(g)
    texture.render()
    g.destroy()
  }

  destroy(): void {
    if (this.destroyed) return
    this.destroyed = true
    this.scene.events.off(Phaser.Scenes.Events.SHUTDOWN, this.destroy, this)
    this.image?.destroy()
    this.image = null
    if (this.scene.textures.exists(TrackRenderer.TEXTURE_KEY)) this.scene.textures.remove(TrackRenderer.TEXTURE_KEY)
    for (const key of this.tyreKeys) if (this.scene.textures.exists(key)) this.scene.textures.remove(key)
    this.tyreKeys.length = 0
    this.tyreRadii.clear()
  }

  /** A picture from an atlas, its cell's edge on a whole screen pixel, at the density it is drawn at everywhere else. */
  private stamp(texture: Phaser.Textures.DynamicTexture, cmd: Extract<DrawCommand, { op: 'sprite' }>): void {
    const x = snapCentre(this.view.originX + cmd.x * this.view.pxPerM, cmd.wPx)
    const y = snapCentre(this.view.originY + cmd.y * this.view.pxPerM, cmd.hPx)
    texture.stamp(cmd.atlas, cmd.frame, x * BAKE_SCALE, y * BAKE_SCALE, { scale: cmd.scale * BAKE_SCALE })
  }

  /** A world point in baked pixels. */
  private px(p: Point): [number, number] {
    return [(this.view.originX + p[0] * this.view.pxPerM) * BAKE_SCALE, (this.view.originY + p[1] * this.view.pxPerM) * BAKE_SCALE]
  }

  private paint(g: Phaser.GameObjects.Graphics, cmd: DrawCommand): void {
    switch (cmd.op) {
      case 'fill':
        g.fillStyle(cmd.color, cmd.alpha ?? 1)
        this.fillPolygon(g, cmd.polygon, cmd.holes ?? [])
        break
      case 'flecks':
        g.fillStyle(cmd.color, 1)
        for (const [wx, wy] of cmd.points) this.fleck(g, wx, wy, cmd.sizePx, cmd.sizePx, 0, 0)
        break
      case 'stroke':
        g.fillStyle(cmd.color, 1)
        this.stroke(g, cmd)
        break
      case 'disc': {
        const [x, y] = this.px([cmd.x, cmd.y])
        g.fillStyle(cmd.color, 1)
        g.fillCircle(x, y, cmd.r * this.view.pxPerM * BAKE_SCALE)
        break
      }
      case 'checker':
        for (const { quad, dark } of checkerQuads(cmd)) {
          g.fillStyle(dark ? CHECKER_COLORS.dark : CHECKER_COLORS.light, 1)
          this.fillPolygon(g, quad, [])
        }
        break
      case 'block':
        g.fillStyle(cmd.color, 1)
        this.fillPolygon(g, cmd.polygon, [])
        if (cmd.border !== undefined) {
          g.fillStyle(cmd.border.color, 1)
          for (const edge of cmd.border.edges) {
            this.strokePolyline(g, [cmd.polygon[edge], cmd.polygon[(edge + 1) % cmd.polygon.length]], cmd.border.widthM, false)
          }
        }
        break
      case 'glyphs':
        g.fillStyle(cmd.color, 1)
        this.glyphs(g, cmd)
        break
      case 'grain':
        g.fillStyle(GRAIN_COLOR, 1)
        for (const [wx, wy] of scatterPoints(cmd, this.view.pxPerM, GRAIN_FLECK_PX)) this.fleck(g, wx, wy, GRAIN_FLECK_PX, GRAIN_FLECK_PX, 0, 0)
        break
      case 'sprite':
        // Stamped by `bake`, which has the texture.
        break
      case 'tufts':
        for (const [wx, wy] of scatterPoints(cmd, this.view.pxPerM, TUFT_PX)) {
          // A blade pair: a dark stalk with a light tip beside it.
          g.fillStyle(TUFT_COLORS.dark, 1)
          this.fleck(g, wx, wy, 1, TUFT_PX, 0, 0)
          this.fleck(g, wx, wy, 1, TUFT_PX - 1, 2, 1)
          g.fillStyle(TUFT_COLORS.light, 1)
          this.fleck(g, wx, wy, 1, TUFT_PX - 1, 1, 0)
        }
        break
    }
  }

  /** A rectangle of `w` x `h` screen pixels whose corner is `dx`, `dy` pixels from the world point's pixel: on the screen's pixel grid, as hard as ever. */
  private fleck(g: Phaser.GameObjects.Graphics, wx: number, wy: number, w: number, h: number, dx: number, dy: number): void {
    const x = Math.round(this.view.originX + wx * this.view.pxPerM) + dx
    const y = Math.round(this.view.originY + wy * this.view.pxPerM) + dy
    g.fillRect(x * BAKE_SCALE, y * BAKE_SCALE, w * BAKE_SCALE, h * BAKE_SCALE)
  }

  /** The glyph pixels of a character, rows then columns: the pixel font's own, read from its atlas once. */
  private bitsOf(char: string): boolean[][] {
    const known = this.glyphBits.get(char)
    if (known !== undefined) return known
    const { textures } = this.scene
    const frame = glyphFrame(char)
    if (!textures.exists(FONT_ATLAS) || !textures.get(FONT_ATLAS).has(frame)) throw new Error(`TrackRenderer: the pixel font has no glyph for '${char}'`)
    const bits = Array.from({ length: GLYPH.capRows }, (_, row) =>
      Array.from({ length: GLYPH.inkCols }, (_, col) => (textures.getPixelAlpha(col, GLYPH.capTop + row, FONT_ATLAS, frame) ?? 0) > 0),
    )
    this.glyphBits.set(char, bits)
    return bits
  }

  /**
   * A run of glyphs: each ink pixel of the font becomes a square of `glyphArtPx` screen pixels. On a quarter turn the
   * box of ink is moved to the pixel grid, so every square lands on whole screen pixels and the digits are as crisp
   * as the font; on any other heading they are rotated squares, smooth like the lines.
   */
  private glyphs(g: Phaser.GameObjects.Graphics, cmd: Extract<DrawCommand, { op: 'glyphs' }>): void {
    const art = glyphArtPx(cmd.heightM, this.view.pxPerM)
    const quarter = cmd.heading % (Math.PI / 2) === 0
    const c = quarter ? Math.round(Math.cos(cmd.heading)) : Math.cos(cmd.heading)
    const s = quarter ? Math.round(Math.sin(cmd.heading)) : Math.sin(cmd.heading)
    const halfW = (glyphCols(cmd.text) * art) / 2
    const halfH = (GLYPH.capRows * art) / 2
    let cx = this.view.originX + cmd.x * this.view.pxPerM
    let cy = this.view.originY + cmd.y * this.view.pxPerM
    if (quarter) {
      // The box's extent on screen: its half-sides, swapped on a quarter turn.
      const ex = Math.abs(c) * halfW + Math.abs(s) * halfH
      const ey = Math.abs(s) * halfW + Math.abs(c) * halfH
      cx = Math.round(cx - ex) + ex
      cy = Math.round(cy - ey) + ey
    }
    const at = (u: number, v: number): [number, number] => {
      const x = cx + c * u - s * v
      const y = cy + s * u + c * v
      return [x * BAKE_SCALE, y * BAKE_SCALE]
    }

    for (const [index, char] of [...cmd.text].entries()) {
      const bits = this.bitsOf(char)
      for (const [row, line] of bits.entries()) {
        for (let col = 0; col < line.length; col++) {
          if (!line[col]) continue
          let end = col
          while (end + 1 < line.length && line[end + 1]) end++
          const u0 = (index * GLYPH.advance + col) * art - halfW
          const u1 = (index * GLYPH.advance + end + 1) * art - halfW
          const v0 = row * art - halfH
          const v1 = (row + 1) * art - halfH
          const [ax, ay] = at(u0, v0)
          const [bx, by] = at(u1, v0)
          const [dx, dy] = at(u1, v1)
          const [ex, ey] = at(u0, v1)
          g.fillTriangle(ax, ay, bx, by, dx, dy)
          g.fillTriangle(ax, ay, dx, dy, ex, ey)
          col = end
        }
      }
    }
  }

  private stroke(g: Phaser.GameObjects.Graphics, cmd: Extract<DrawCommand, { op: 'stroke' }>): void {
    const pieces = cmd.dashM === undefined ? [cmd.polyline] : dashSegments(cmd.polyline, cmd.dashM[0], cmd.dashM[1], cmd.closed)
    const closed = cmd.dashM === undefined && cmd.closed
    for (const piece of pieces) this.strokePolyline(g, piece, cmd.widthM, closed)
  }

  private strokePolyline(g: Phaser.GameObjects.Graphics, polyline: readonly Point[], widthM: number, closed: boolean): void {
    const tris = strokeTriangles(polyline.map((p) => this.px(p)), widthM * this.view.pxPerM * BAKE_SCALE, closed)
    for (let i = 0; i < tris.length; i += 6) g.fillTriangle(tris[i], tris[i + 1], tris[i + 2], tris[i + 3], tris[i + 4], tris[i + 5])
  }

  /** Graphics cannot fill a polygon with holes, so triangulate it (ADR-001). */
  private fillPolygon(g: Phaser.GameObjects.Graphics, polygon: readonly Point[], holes: readonly (readonly Point[])[]): void {
    const flat: number[] = []
    const holeStarts: number[] = []
    for (const p of polygon) flat.push(...this.px(p))
    for (const hole of holes) {
      holeStarts.push(flat.length / 2)
      for (const p of hole) flat.push(...this.px(p))
    }
    const idx = Phaser.Geom.Polygon.Earcut(flat, holeStarts)
    for (let i = 0; i < idx.length; i += 3) {
      const a = idx[i] * 2
      const b = idx[i + 1] * 2
      const c = idx[i + 2] * 2
      g.fillTriangle(flat[a], flat[a + 1], flat[b], flat[b + 1], flat[c], flat[c + 1])
    }
  }
}
