// Layout constants and the world-to-screen mapping. Engine-free on purpose, so that tests can load it in Node.
import type { TrackData } from '@sim'

export const GAME_NAME = 'MINI RC RACERS'

/** The logical canvas. Everything is laid out in these pixels; the page scales the canvas to fit. */
export const LOGICAL_WIDTH = 1920
export const LOGICAL_HEIGHT = 1080

/** Where the sim's world sits on the logical canvas: world (0, 0) is at (originX, originY), one metre is pxPerM pixels. */
export interface WorldView {
  pxPerM: number
  originX: number
  originY: number
}

/**
 * The one world-to-screen mapping every race-scene renderer shares: the largest uniform scale at which the whole
 * bounds rectangle fits inside the screen less `marginPx` on every side, centred. The origin is rounded to a whole
 * pixel so that baked pictures and sprites sit on the same pixel grid. The home track's 21.33 x 12 m gives 90 px/m.
 */
export function fitWorld(bounds: TrackData['bounds'], screen: { w: number; h: number }, marginPx: number): WorldView {
  const pxPerM = Math.min((screen.w - 2 * marginPx) / bounds.w, (screen.h - 2 * marginPx) / bounds.h)
  return {
    pxPerM,
    originX: Math.round((screen.w - bounds.w * pxPerM) / 2),
    originY: Math.round((screen.h - bounds.h * pxPerM) / 2),
  }
}
