// The rules of the player's name (F-407): what it may be made of and how long it may be, and typing one. Pure, so that
// they are tested without an engine, and imported by the save's reader. `driver-name.ts` keeps the name and hands it out.

/** The longest name allowed: the length of the longest name on the roster (the roster has no rule for a full name, only for the short one). */
export const NAME_MAX = 15

/** What the screens call the player when no name is set. */
export const NO_NAME = 'YOU'

/** Whether `char` may be typed into a name: a letter, a digit or a space. Plain ASCII only. */
export const isNameChar = (char: string): boolean => /^[A-Za-z0-9 ]$/.test(char)

/**
 * A name as it is kept: capitals, letters, digits and spaces only (anything else is dropped), at most `NAME_MAX`
 * characters, with leading and trailing spaces dropped. Null when nothing is left (a name of spaces is no name).
 */
export function cleanName(raw: string): string | null {
  // Plain ASCII only, filtered before the case is changed ('ß' would otherwise become 'SS').
  const kept = [...raw].filter(isNameChar).join('').trim().slice(0, NAME_MAX).trimEnd()
  return kept === '' ? null : kept.toUpperCase()
}

// Typing a name: the rules of the entry as a pure reducer, so that they are tested without an engine.

/** The text typed so far (0..NAME_MAX characters) and the cursor: the place a typed character goes in, from 0 to the length. */
export interface NameState {
  text: string
  cursor: number
}

export type NameKey = { type: 'char'; char: string } | { type: 'left' | 'right' | 'backspace' }

/** The state a field opens in: the current name typed in, the cursor after it. */
export function nameStart(current: string | null): NameState {
  const text = current ?? ''
  return { text, cursor: text.length }
}

/**
 * The state after a key. A typed letter, digit or space goes in at the cursor (letters in capitals) while there is
 * room, and the cursor moves on; left and right move the cursor; backspace deletes the character before it. Any other
 * character is ignored.
 */
export function nameReduce(s: NameState, k: NameKey): NameState {
  const cursor = Math.min(Math.max(s.cursor, 0), s.text.length)
  switch (k.type) {
    case 'char':
      if (k.char.length !== 1 || !isNameChar(k.char) || s.text.length >= NAME_MAX) return { text: s.text, cursor }
      return { text: s.text.slice(0, cursor) + k.char.toUpperCase() + s.text.slice(cursor), cursor: cursor + 1 }
    case 'left':
      return { text: s.text, cursor: Math.max(0, cursor - 1) }
    case 'right':
      return { text: s.text, cursor: Math.min(s.text.length, cursor + 1) }
    case 'backspace':
      return cursor === 0 ? { text: s.text, cursor } : { text: s.text.slice(0, cursor - 1) + s.text.slice(cursor), cursor: cursor - 1 }
  }
}
