import type { SessionSnapshot, SimEvent } from '@sim'
import type { CommentaryEngine, SpokenLine } from '@commentary'
import { SHOUT } from './decor-layout'

// The commentator's English library: the one import to switch for another language or another set (F-702).
export { COMMENTARY_EN as COMMENTARY_LINES } from '@content/lines/en'

// Who has the window (F-703). One portrait and one bubble belong to two speakers, the race official and the
// commentator, and the owner's ruling is that the official's instructions come first. This is the rule, in no engine:
// the Hud tells it each frame what the official has to say, the commentary engine (F-701) tells it what the
// commentator would, and it tells the window who is talking and the voice what to say. Time is session time (the
// sim's clock), so a pause holds everything; the results screens, which have no sim, give it a clock of their own.

/** The speakers of the window. */
export type Speaker = 'official' | 'commentator'

/** The voices there are: the two speakers of the window, and the driver in the stand who shouts "Marshal!" (F-708), who has no portrait. */
export type Voiced = Speaker | 'driver'

/** The window that shows them: the official's portrait and bubble (`Official`), which takes the other speaker's too. */
export interface Window {
  /** `size` is the layout of the words: the official's (as big as they need) or the commentator's (small, three lines). */
  show(speaker: Speaker, words: string, colour: number, size: 'official' | 'commentary'): void
  /** Nobody talks: no bubble, and the official at rest. */
  rest(): void
}

/** The spoken voice (`Tts`). */
export interface Voice {
  /** Whether the browser can speak at all: it has speech synthesis and a voice. */
  readonly available: boolean
  /** Says `text` in the speaker's voice, ending whatever was being said; `onEnd` is called when it has been said, never when it was cancelled. */
  speak(text: string, who: Voiced, onEnd: () => void): void
  cancel(): void
  pause(): void
  resume(): void
}

/** What the official has to say this frame, as the Hud's message line gives it. */
export interface OfficialMessage {
  text: string
  colour: number
  /** It has no end of its own (TIME UP, a hold to come, WAIT, the last minute's pit warning, blocking the pit lane): it stays until it is taken down. */
  standing: boolean
  /** Session time it came on the line, s: a different message, or the same standing one come back after a timed one, is a different `since`. */
  since: number
  /** What is said aloud when it is not the words on the bubble (F-810: a lap time is read out in words, not digits). Left out, the text is said. */
  spoken?: string
}

/** The engine of a session with no commentator (practice, F-810): it sees nothing and has nothing to say, so the window is the official's alone. */
export const NO_COMMENTATOR: CommentaryEngine = { observe: () => undefined, next: () => null }

/** The numbers the director chooses by, s. */
export const DIRECTOR = {
  /** A standing message is shown first for this long, and again for this long each time it comes back after the commentator, before he may talk. */
  standingMinS: 3,
  /** A line without speech stays up for its estimated duration and this much more. */
  captionPadS: 0.4,
  /** A spoken line stays up until it has been said, and at most this many times its estimated duration, when it is cancelled. */
  speechCapFactor: 1.5,
  /** The commentator waits for the official to finish saying a message, and no longer than this. */
  officialSpeechCapS: 6,
  /** A driver's shout waits this long for its turn (the official's message, the commentator's line, another shout) and is dropped after: about as long as a line is, so that it is said between lines, and never so long that it is said for nothing. */
  shoutWaitS: 4,
  /** A shout is taken to have been said, whether or not the browser reports it, this long after it began. */
  shoutCapS: 1.5,
  /** A line is made to wait behind a shout only if it would still have this much time left after the shout's longest. */
  shoutSpareS: 0.5,
} as const

export interface DirectorOptions {
  /** Whether speech is on, asked each time a line is about to be said. */
  speech: () => boolean
  /** The colour of the commentator's words: the HUD's light text colour. */
  commentaryColour: number
  /** Told when a speaker starts or stops being heard saying something aloud (not when only the caption is up), for what should duck under a voice. */
  onTalking?: (speaker: Speaker, talking: boolean) => void
}

/** A commentator's line on screen. */
interface Line {
  /** Session time it has to be gone by, s. */
  endsAtS: number
  /** The time it would have to be gone by were it not said aloud, s: where it ends if speech is turned off while it is said. */
  captionEndsAtS: number
  /** It is being said aloud. */
  speaking: boolean
  /** The voice has finished saying it. */
  done: boolean
}

/** A driver's "Marshal!" being said aloud. */
interface Shouted {
  startedS: number
  done: boolean
}

/** A message of the official's that is being said aloud. */
interface Said {
  startedS: number
  done: boolean
}

/** What the window was last told, so that it is told again only when it changes. */
interface Told {
  speaker: Speaker
  words: string
  colour: number
}

/** The official's words as they are said aloud: a message in capitals is said as words, not spelt. */
const spokenForm = (text: string): string => (text === text.toUpperCase() ? text.toLowerCase() : text)

/**
 * Decides, every frame, who has the window. The official, when the message line has something for him; otherwise the
 * commentator, with the engine's next line. Keeps the words and the voice in step.
 *
 * - A timed message of the official's takes the window at once, drops the commentator's line (and cancels his speech),
 *   and the commentator does not talk again until it is over.
 * - A standing message is shown first, for `DIRECTOR.standingMinS`; after that the commentator may talk, and the
 *   official comes back after each of his lines for the same time, until the message is taken down.
 * - A line stays for its estimated duration and 0.4 s without speech; with speech, until it has been said or 1.5 times
 *   the estimate, whichever comes first (an utterance that overruns is cancelled).
 */
export class CommentaryDirector {
  private offered: OfficialMessage | null = null
  private seen: OfficialMessage | null = null
  private last: Told | null = null
  private told: Told | null = null
  private line: Line | null = null
  private said: Said | null = null
  /** The standing message that was last said aloud: it is not said again when it comes back after a line. */
  private standingSaid: string | null = null
  /** When the official got the window back from the commentator, s. */
  private backS = -Infinity
  private paused = false
  private disposed = false
  /** The session time a driver's shout came due, s, until it is said or dropped. */
  private shoutDueS: number | null = null
  /** The shout being said. */
  private shouted: Shouted | null = null
  /** A line the engine gave that waits for the shout to be said first: it has time to spare (F-708). */
  private queued: SpokenLine | null = null
  /** Who is heard saying something aloud now. */
  private heard: Speaker | null = null
  /** A driver is calling for his distracted marshal now (F-712): the commentator starts no new line, so that the shout has the gaps. */
  private callingNow = false

  constructor(
    private readonly engine: CommentaryEngine,
    private readonly window: Window,
    private readonly voice: Voice,
    private readonly options: DirectorOptions,
  ) {}

  /** The official's message as the message line gives it this frame (null with nothing to say). Call it every frame, before `update`. */
  official(message: OfficialMessage | null): void {
    this.offered = message
  }

  /**
   * A driver in the stand shouts "Marshal!" now (F-708). Call it, before `update`, in the frame his shout comes due. With
   * speech on it is said in a third voice whenever no utterance is in the air (F-712), whoever holds the window: between
   * the official's utterances, with his message still on the line, and between the commentator's lines; never over an
   * utterance and never through one. An official utterance that falls due in the same frame goes first. It waits
   * `DIRECTOR.shoutWaitS` for its turn and is dropped after, and it never pushes a line or a message back: they take the
   * voice from it. One waiting shout stands for all that come due while it waits. It shows nothing and ducks nothing; with
   * speech off, it is the stand's bubble that shouts, and the voice is not touched.
   */
  shout(nowS: number): void {
    if (this.disposed) return
    this.shoutDueS ??= nowS
  }

  /**
   * Whether any driver is calling for a marshal who is on his phone (F-712), told every frame, before `update`. While one
   * is, and the shout would be said aloud, the commentator starts no new line (the engine is told he is busy, so it keeps
   * its lines and their time-to-live; a line already in the air finishes), the official still comes first, and the shout
   * has every gap between the official's utterances. When nobody is calling he resumes. With speech off, or no voice, it
   * changes nothing.
   */
  calling(on: boolean): void {
    this.callingNow = on
  }

  /** Nobody is calling for a marshal now (the car is in hand or put down): a shout that is waiting for its turn is dropped. One being said is let finish. */
  hush(): void {
    this.shoutDueS = null
  }

  /** Whether a shout would be said aloud now: speech is on and the browser has a voice. Where it is not, the stand's bubble shouts. Asks the voice only with speech on. */
  shoutsAloud(): boolean {
    return !this.disposed && this.options.speech() && this.voice.available
  }

  /** The events of one or more ticks and the snapshot they led to, for the engine. */
  onSimEvents(events: readonly SimEvent[], snapshot: SessionSnapshot, nowS: number): void {
    this.engine.observe(events, snapshot, nowS)
  }

  update(nowS: number): void {
    if (this.disposed || this.paused) return
    const message = this.offered
    this.offered = null
    const fresh = this.note(message)
    this.muteIfSilenced()
    this.endLineIfDue(nowS)

    if (message !== null && (!message.standing || fresh)) {
      // The official's instruction comes first: at once, over whatever the commentator was saying.
      this.drop()
      this.showOfficial(message)
      if (fresh) this.say(message, nowS)
      this.engine.next(nowS, true)
    } else if (message !== null) {
      // A standing message that has been shown: the commentator may talk once it has had its time.
      if (this.line === null) {
        this.showOfficial(message)
        const held = nowS < Math.max(message.since, this.backS) + DIRECTOR.standingMinS || this.speaking(nowS)
        this.pull(nowS, held)
      } else {
        this.engine.next(nowS, true)
      }
    } else if (this.line === null) {
      if (this.speaking(nowS) && this.last !== null) {
        // A message of his that is over but still being said stays up until it has been.
        this.show(this.last, 'official')
        this.engine.next(nowS, true)
      } else if (!this.pull(nowS, false)) {
        this.rest()
      }
    } else {
      this.engine.next(nowS, true)
    }
    this.serveShout(nowS)
    this.announce(nowS)
  }

  /** The game is paused: speech pauses and the bubble holds. */
  pause(): void {
    if (this.disposed || this.paused) return
    this.paused = true
    this.voice.pause()
  }

  resume(): void {
    if (this.disposed || !this.paused) return
    this.paused = false
    this.voice.resume()
  }

  /** The scene is going: speech is cancelled and the window is left at rest. */
  dispose(): void {
    if (this.disposed) return
    this.disposed = true
    this.voice.cancel()
    this.line = null
    this.queued = null
    this.said = null
    this.shoutDueS = null
    this.shouted = null
    this.rest()
    this.announce(0)
  }

  /** Notes the message of this frame; true when it is a different showing from the one before (a message that came, or one that came back). */
  private note(message: OfficialMessage | null): boolean {
    if (message === null) {
      this.seen = null
      this.standingSaid = null
      return false
    }
    const fresh = this.seen === null || this.seen.since !== message.since
    this.seen = message
    if (fresh) this.backS = -Infinity
    return fresh
  }

  /** Whether the official's last message is still being said. */
  private speaking(nowS: number): boolean {
    const said = this.said
    return said !== null && !said.done && nowS < said.startedS + DIRECTOR.officialSpeechCapS
  }

  /** Says the official's message aloud if speech is on. A standing message is said once, not each time it comes back. */
  private say(message: OfficialMessage, nowS: number): void {
    this.said = null
    if (!this.options.speech() || !this.voice.available) return
    if (message.standing) {
      if (message.text === this.standingSaid) return
      this.standingSaid = message.text
    }
    const said: Said = { startedS: nowS, done: false }
    this.said = said
    this.shouted = null
    this.voice.speak(message.spoken ?? spokenForm(message.text), 'official', () => {
      said.done = true
    })
  }

  /** Asks the engine for a line; with the window free, starts it. True if one started. */
  private pull(nowS: number, busy: boolean): boolean {
    if (this.holdsHisTongue()) {
      // The shout has the gaps: his lines wait in the engine (or, one the director held for a shout, here) and nothing new starts.
      this.engine.next(nowS, true)
      return this.queued !== null
    }
    if (this.queued !== null) return this.releaseQueued(nowS, busy)
    const line = this.engine.next(nowS, busy)
    if (line === null || busy) return false
    if (this.shoutFirst(line, nowS)) {
      // The shout takes its turn between the lines: this one waits the moment it takes, with the window at rest.
      this.queued = line
      this.rest()
      return true
    }
    this.start(line, nowS)
    return true
  }

  /** A driver is calling and the shout is said aloud: the commentator starts nothing new. */
  private holdsHisTongue(): boolean {
    return this.callingNow && !this.disposed && this.options.speech() && this.voice.available
  }

  /** The line that waited for a shout starts when the shout has been said, if it is still in time. */
  private releaseQueued(nowS: number, busy: boolean): boolean {
    const line = this.queued
    if (line === null) return false
    if (this.shoutInTheAir(nowS)) {
      this.engine.next(nowS, true)
      return true
    }
    this.queued = null
    if (busy) return false
    if (line.expiresAtS <= nowS) return this.pull(nowS, busy)
    this.start(line, nowS)
    return true
  }

  /** A shout is being said (or was begun less than `DIRECTOR.shoutCapS` ago, and the browser has not said it is over). */
  private shoutInTheAir(nowS: number): boolean {
    return this.shouted !== null && !this.shouted.done && nowS < this.shouted.startedS + DIRECTOR.shoutCapS
  }

  /**
   * A line is ready and the voice is free. If a driver's shout is waiting, or in the air, and the line can wait the moment
   * it takes without running out of time, the shout goes first (said now, if it was waiting) and the line follows it: true.
   * A line with less time than that goes first, and the shout takes its turn after the line, or is dropped.
   */
  private shoutFirst(line: SpokenLine, nowS: number): boolean {
    if (!this.options.speech() || !this.voice.available) return false
    if (line.expiresAtS - nowS <= DIRECTOR.shoutCapS + DIRECTOR.shoutSpareS) return false
    if (this.shoutInTheAir(nowS)) return true
    const due = this.shoutDueS
    if (due === null || nowS - due > DIRECTOR.shoutWaitS || this.speaking(nowS)) return false
    this.sayShout(nowS)
    return true
  }

  private sayShout(nowS: number): void {
    this.shoutDueS = null
    const shouted: Shouted = { startedS: nowS, done: false }
    this.shouted = shouted
    this.voice.speak(SHOUT.spoken, 'driver', () => {
      shouted.done = true
    })
  }

  private start(spoken: SpokenLine, nowS: number): void {
    const speaking = this.options.speech() && this.voice.available
    const captionEndsAtS = nowS + spoken.estimatedDurationS + DIRECTOR.captionPadS
    const line: Line = {
      endsAtS: speaking ? nowS + DIRECTOR.speechCapFactor * spoken.estimatedDurationS : captionEndsAtS,
      captionEndsAtS,
      speaking,
      done: false,
    }
    this.line = line
    this.said = null
    this.show({ speaker: 'commentator', words: spoken.text, colour: this.options.commentaryColour }, 'commentary')
    if (speaking) {
      // His line takes the voice from a shout that is being said: a shout is dropped rather than a line pushed back.
      this.shouted = null
      this.voice.speak(spoken.text, 'commentator', () => {
        line.done = true
      })
    }
  }

  /** Speech was turned off while something is being said: it is cut short, and the caption goes on for the time it would have had without speech. */
  private muteIfSilenced(): void {
    if (this.options.speech()) return
    this.shoutDueS = null
    if (this.shouted !== null && !this.shouted.done) this.voice.cancel()
    this.shouted = null
    const line = this.line
    if (line !== null && line.speaking) {
      this.voice.cancel()
      line.speaking = false
      line.endsAtS = line.captionEndsAtS
    } else if (this.said !== null && !this.said.done) {
      this.voice.cancel()
      this.said = null
    }
  }

  /** Says the driver's shout if it is due and it is its turn, drops it if it has waited too long. */
  private serveShout(nowS: number): void {
    const due = this.shoutDueS
    if (due === null) return
    if (!this.options.speech() || !this.voice.available || nowS - due > DIRECTOR.shoutWaitS) {
      this.shoutDueS = null
      return
    }
    const line = this.line
    if (this.shoutInTheAir(nowS) || this.speaking(nowS) || (line !== null && line.speaking && !line.done)) return
    this.sayShout(nowS)
  }

  private endLineIfDue(nowS: number): void {
    const line = this.line
    if (line === null || !(line.done || nowS >= line.endsAtS)) return
    // An utterance that overran its time is cancelled; one that has ended has nothing to cancel.
    if (line.speaking && !line.done) this.voice.cancel()
    this.line = null
    this.backS = nowS
  }

  /** The commentator's line is dropped for the official: gone from the screen, and no longer said; so is one that waited for a shout. */
  private drop(): void {
    const line = this.line
    if (line !== null && line.speaking && !line.done) this.voice.cancel()
    this.line = null
    this.queued = null
  }

  private showOfficial(message: OfficialMessage): void {
    this.last = { speaker: 'official', words: message.text, colour: message.colour }
    this.show(this.last, 'official')
  }

  private show(what: Told, size: 'official' | 'commentary'): void {
    const before = this.told
    if (before !== null && before.speaker === what.speaker && before.words === what.words && before.colour === what.colour) return
    this.told = what
    this.window.show(what.speaker, what.words, what.colour, size)
  }

  private rest(): void {
    if (this.told === null) return
    this.told = null
    this.window.rest()
  }

  /** Tells what ducks under a voice who is heard now, when that changes. */
  private announce(nowS: number): void {
    const line = this.line
    const heard: Speaker | null = this.disposed ? null : line !== null ? (line.speaking && !line.done ? 'commentator' : null) : this.speaking(nowS) ? 'official' : null
    if (heard === this.heard) return
    const before = this.heard
    this.heard = heard
    if (before !== null) this.options.onTalking?.(before, false)
    if (heard !== null) this.options.onTalking?.(heard, true)
  }
}
