import { DT, NO_INPUT, type CarId, type ControlInput, type Session, type SessionSnapshot, type SimEvent, type Tick } from '@sim'
import type { InputRun } from '../debug/InputRecorder'

/** One input per human car, as `Session.step` takes them. */
export type TickInputs = Readonly<Record<CarId, ControlInput>>

export interface SimRunnerOptions {
  /** The most ticks one frame may step: 6 is 50 ms of sim time (AGENTS.md, Phaser rule 3). */
  maxStepsPerFrame?: number
}

/**
 * An input source that plays back a recorded drive of one car: `runs` as `InputRecorder.runs()` made them (tick 0 is
 * the first run's first tick). Past the end of the recording the car is given no input. It reads nothing of the
 * session, so the drive is the same at any time scale and frame rate. For tests only: the game does not count it as
 * the autopilot, and nothing in play uses it.
 */
export function replaySource(runs: readonly InputRun[], car: CarId): (tick: Tick) => TickInputs {
  const inputs: ControlInput[] = runs.flatMap(([throttle, brake, steer, ticks]) => Array.from({ length: ticks }, () => ({ throttle, brake, steer })))
  return (tick) => ({ [car]: inputs[tick] ?? NO_INPUT })
}

const DT_MS = DT * 1000
/** Guards against a frame time that is a whole number of ticks losing one to float noise in the running total. */
const EPSILON_MS = 1e-6
const NO_EVENTS: readonly SimEvent[] = Object.freeze([])

/**
 * Steps the fixed-rate sim from the browser's variable frame clock (architecture.md, "The view"). The scene feeds
 * it the real time of each frame; it steps a whole number of ticks, forwards their events, and keeps the previous
 * and current snapshot so renderers can interpolate with the fraction of a tick left over. It knows nothing of
 * Phaser, and it never changes what the sim does: the same inputs per tick give the same session at any frame rate.
 */
export class SimRunner {
  /** While true nothing is stepped and the time that passes is forgotten, not saved up. */
  paused = false
  /**
   * When set, asked for the inputs of every tick instead of using those given to `setInput`. A driver that has to
   * decide per tick (the autopilot, a replay) goes here; a keyboard, which only changes between frames, uses `setInput`.
   */
  inputSource: ((tick: Tick, snapshot: SessionSnapshot) => TickInputs) | null = null
  /** Called after each stepped tick with its number (the session tick after the step), the inputs applied and its events. */
  onTick: ((tick: Tick, inputs: TickInputs, events: readonly SimEvent[]) => void) | null = null

  /**
   * How many seconds of sim time pass for each second of real time: 1 in play. The debug hook raises it so that a
   * browser test can run a whole race in seconds (development and test builds; nothing else sets it: the shipped builds
   * have no hook, so it stays 1 there). Frame time is
   * scaled before it is counted, and the frame clamp is scaled with it, so a stall is still cut to 50 ms of real time.
   * It changes how many ticks a frame steps and nothing else: the same inputs per tick give the same session at any scale.
   */
  timeScale = 1

  /** The ticks stepped by the latest `advance`. */
  stepsLastFrame = 0
  /** How many frames so far were longer than the cap allows and had the excess dropped. */
  clampedFrames = 0

  private readonly maxSteps: number
  private readonly held: Record<CarId, ControlInput> = {}
  private accumulatedMs = 0
  private previous: SessionSnapshot
  private current: SessionSnapshot

  constructor(
    readonly session: Session,
    opts: SimRunnerOptions = {},
  ) {
    const max = opts.maxStepsPerFrame ?? 6
    if (!Number.isInteger(max) || max < 1) throw new Error(`SimRunner: maxStepsPerFrame must be a whole number of at least 1, not ${max}`)
    this.maxSteps = max
    session.config.entries.forEach((entry, car) => {
      if (entry.controller === 'human') this.setInput(car, NO_INPUT)
    })
    // The session hands out one reused buffer; the runner keeps its own copies, one fresh object per tick.
    this.current = structuredClone(session.snapshot())
    this.previous = this.current
  }

  /** The state one tick before `curr` (the same object as `curr` until the first step). Never mutated. */
  get prev(): SessionSnapshot {
    return this.previous
  }

  /** The state after the latest tick. Never mutated: it may be kept. */
  get curr(): SessionSnapshot {
    return this.current
  }

  /** How far the displayed instant lies from `prev` toward `curr`: the fraction of a tick not yet stepped, 0..1. */
  get alpha(): number {
    return Math.min(1, Math.max(0, this.accumulatedMs / DT_MS))
  }

  /** Holds `input` for `car` from now until it is set again; every tick of every frame from here on uses it. */
  setInput(car: CarId, input: ControlInput): void {
    this.held[car] = { throttle: input.throttle, brake: input.brake, steer: input.steer }
  }

  /**
   * Advance by real elapsed milliseconds. Returns the events of all ticks stepped this frame. A frame longer than
   * the cap allows steps the cap and drops the whole ticks beyond it, so a stall can never become a spiral. At a
   * `timeScale` above 1 the time counted and the cap are both that many times larger.
   */
  advance(elapsedMs: number): readonly SimEvent[] {
    this.stepsLastFrame = 0
    if (this.paused) return NO_EVENTS
    const scale = Number.isFinite(this.timeScale) && this.timeScale > 0 ? this.timeScale : 1
    if (Number.isFinite(elapsedMs) && elapsedMs > 0) this.accumulatedMs += elapsedMs * scale

    const cap = Math.max(1, Math.round(this.maxSteps * scale))
    const due = Math.floor((this.accumulatedMs + EPSILON_MS) / DT_MS)
    let steps = due
    if (due > cap) {
      steps = cap
      this.accumulatedMs -= (due - steps) * DT_MS
      this.clampedFrames++
    }
    this.accumulatedMs -= steps * DT_MS

    let events: SimEvent[] | null = null
    for (let i = 0; i < steps; i++) {
      const inputs = this.inputSource === null ? this.held : this.inputSource(this.session.tick, this.current)
      const stepped = this.session.step(inputs)
      this.previous = this.current
      this.current = structuredClone(this.session.snapshot())
      this.stepsLastFrame++
      this.onTick?.(this.session.tick, inputs, stepped)
      if (stepped.length > 0) {
        events ??= []
        events.push(...stepped)
      }
    }
    return events ?? NO_EVENTS
  }
}
