/// <reference lib="dom" />
import type { AudioMixer } from '../AudioMixer'
import { PIECES } from './pieces'
import { notesInWindow, type Piece, type PieceId, type ScheduledNote, type Voice } from './sequence'

// The ambient music's scheduler (F-705). It keeps the audio clock in view and hands notes to oscillators a little ahead
// of it (the lookahead), so that timing is the audio hardware's and not a timer's. Everything it makes goes to the
// mixer's `music` bus; pausing is the mixer's (it suspends the context, the audio clock stops, and the music stops and
// resumes at the same place). It makes no sound and no node until the mixer is running, that is, until a key press.

/** How far ahead of the audio clock notes are handed to the oscillators, seconds. */
export const LOOKAHEAD_S = 0.6
/** How often the scheduler looks, milliseconds. A quarter of the lookahead, so that a late look still has time in hand. */
export const TICK_MS = 150
/** A piece starts this long after it is asked for, seconds, so that its first notes are not already in the past. */
export const START_DELAY_S = 0.06
/** Fade times (time constants, seconds) and how long after the fade starts the nodes are cut: switching off is quick; changing piece is a crossfade. */
const OFF_TAU_S = 0.06
const OFF_CUT_S = 0.4
const SWAP_TAU_S = 0.25
const SWAP_CUT_S = 1.4
const FADE_IN_TAU_S = 0.2
/** A note that would start more than this far in the past (the page stalled) is dropped, not played in a heap with the next. */
const LATE_S = 0.04
/** Seconds of noise in the buffer the hats and snares are cut from. */
const NOISE_S = 0.5

/** The timer the scheduler runs on: the browser's, or a test's. */
export interface Timers {
  every(ms: number, fn: () => void): unknown
  cancel(handle: unknown): void
}

const browserTimers: Timers = {
  every: (ms, fn) => setInterval(fn, ms),
  cancel: (handle) => clearInterval(handle as ReturnType<typeof setInterval>),
}

export interface MusicPlayerOptions {
  timers?: Timers
  lookaheadS?: number
  /** For the tests: other pieces than the game's. */
  pieces?: Readonly<Record<PieceId, Piece>>
  /** Starts on, as the saved setting says. */
  enabled?: boolean
}

/** What a started piece has made: its output, one bus per voice, the notes handed over and not yet finished. */
interface Playing {
  piece: Piece
  /** Audio-clock time of the piece's time zero. */
  origin: number
  /** Piece time up to which every note has been handed over. */
  scheduledTo: number
  out: GainNode
  buses: AudioNode[]
  live: Set<{ stop(when?: number): void; disconnect(): void }>
}

/** A piece being faded out: cut and disconnected once the audio clock reaches `cutAt`. */
interface Retiring {
  playing: Playing
  cutAt: number
}

export class MusicPlayer {
  private readonly timers: Timers
  private readonly lookaheadS: number
  private readonly pieces: Readonly<Record<PieceId, Piece>>
  private isEnabled: boolean
  private wanted: PieceId | null = null
  private playing: Playing | null = null
  private readonly retiring: Retiring[] = []
  private handle: unknown = null
  private noise: AudioBuffer | null = null
  private disposed = false

  constructor(
    private readonly mixer: AudioMixer,
    options: MusicPlayerOptions = {},
  ) {
    this.timers = options.timers ?? browserTimers
    this.lookaheadS = options.lookaheadS ?? LOOKAHEAD_S
    this.pieces = options.pieces ?? PIECES
    this.isEnabled = options.enabled ?? true
    this.handle = this.timers.every(TICK_MS, () => this.tick())
  }

  get enabled(): boolean {
    return this.isEnabled
  }

  /** The piece asked for, whether or not it is sounding yet (it waits for the first key press and for the setting). */
  get wantedPiece(): PieceId | null {
    return this.wanted
  }

  /** The piece sounding now, if any. */
  get soundingPiece(): PieceId | null {
    return this.playing?.piece.id ?? null
  }

  /**
   * Asks for a piece. The same piece again changes nothing (the title and the garage share one, and it does not restart
   * between them). Takes effect at the next look, so that a scene that ends and the next that begins ask for one piece
   * after another without a change in between being heard.
   */
  play(id: PieceId): void {
    this.wanted = id
  }

  /** Asks for no music. */
  stop(): void {
    this.wanted = null
  }

  /** The setting: off silences the music at once (inside half a second), on starts the wanted piece from its first bar. */
  setEnabled(on: boolean): void {
    if (this.isEnabled === on) return
    this.isEnabled = on
    this.tick()
  }

  /** One look at the clock: reaps what has faded, switches piece, hands over the notes of the next stretch. */
  tick(): void {
    if (this.disposed) return
    const now = this.mixer.ctx.currentTime
    this.reap(now)
    const target = this.isEnabled ? this.wanted : null
    if (this.playing !== null && this.playing.piece.id !== target) this.retire(this.playing, target === null ? OFF_TAU_S : SWAP_TAU_S, target === null ? OFF_CUT_S : SWAP_CUT_S)
    // Nothing is made, and nothing is attempted, until a key press has let the context run, and not while it is paused.
    if (target === null || !this.mixer.running) return
    this.playing ??= this.start(this.pieces[target], now)
    this.schedule(this.playing, now)
  }

  /** Stops the scheduler and silences everything it made. */
  dispose(): void {
    if (this.disposed) return
    this.disposed = true
    this.timers.cancel(this.handle)
    this.handle = null
    if (this.playing !== null) this.cut(this.playing)
    this.playing = null
    for (const { playing } of this.retiring) this.cut(playing)
    this.retiring.length = 0
  }

  private start(piece: Piece, now: number): Playing {
    const { ctx } = this.mixer
    const out = ctx.createGain()
    out.gain.value = 0
    out.gain.setTargetAtTime(piece.level, now, FADE_IN_TAU_S)
    out.connect(this.mixer.music)
    const buses = piece.voices.map((voice) => this.makeBus(voice, out))
    return { piece, origin: now + START_DELAY_S, scheduledTo: 0, out, buses, live: new Set() }
  }

  /** A voice's bus: its level and its filter, into the piece's output. */
  private makeBus(voice: Voice, out: AudioNode): AudioNode {
    const { ctx } = this.mixer
    const filter = ctx.createBiquadFilter()
    filter.type = voice.wave === 'noise' ? (voice.name === 'snare' ? 'bandpass' : 'highpass') : 'lowpass'
    filter.frequency.value = voice.filterHz
    filter.Q.value = voice.wave === 'noise' && voice.name === 'snare' ? 0.8 : 0.7
    filter.connect(out)
    return filter
  }

  private schedule(playing: Playing, now: number): void {
    const horizon = now + this.lookaheadS - playing.origin
    if (horizon <= playing.scheduledTo) return
    const notes = notesInWindow(playing.piece, playing.scheduledTo, horizon)
    playing.scheduledTo = horizon
    for (const note of notes) {
      const at = playing.origin + note.startS
      if (at < now - LATE_S) continue
      this.sound(playing, note, at)
    }
  }

  /** One note: an oscillator (or a cut of the noise) through its envelope, started and stopped on the audio clock. */
  private sound(playing: Playing, note: ScheduledNote, at: number): void {
    const { ctx } = this.mixer
    const voice = playing.piece.voices[note.voice]
    const bus = playing.buses[note.voice]
    if (voice === undefined || bus === undefined) return
    const peak = voice.gain * note.vel
    const end = at + note.durS
    const env = ctx.createGain()
    const attackEnd = at + voice.attackS
    const holdEnd = Math.max(attackEnd, end - voice.releaseS)
    env.gain.setValueAtTime(0, at)
    env.gain.linearRampToValueAtTime(peak, attackEnd)
    // A note settles to its sustain level over the time it has, and fades out at its end.
    env.gain.linearRampToValueAtTime(peak * voice.sustain, holdEnd)
    env.gain.linearRampToValueAtTime(0, end + voice.releaseS * 0.5)
    env.connect(bus)
    const stopAt = end + voice.releaseS * 0.5 + 0.01
    let source: AudioScheduledSourceNode
    if (voice.wave === 'noise') {
      const buffer = (this.noise ??= this.makeNoise())
      const hit = ctx.createBufferSource()
      hit.buffer = buffer
      hit.start(at, (note.startS * 7.31) % (NOISE_S * 0.5))
      source = hit
    } else {
      const osc = ctx.createOscillator()
      osc.type = voice.wave
      osc.frequency.value = note.freqHz
      osc.start(at)
      source = osc
    }
    source.connect(env)
    source.stop(stopAt)
    const handle = {
      stop: (when?: number): void => {
        try {
          source.stop(when)
        } catch {
          // Already stopped.
        }
      },
      disconnect: (): void => {
        source.disconnect()
        env.disconnect()
      },
    }
    playing.live.add(handle)
    source.onended = (): void => {
      handle.disconnect()
      playing.live.delete(handle)
    }
  }

  /** The same noise on every run, so that the piece is the same sound every time. */
  private makeNoise(): AudioBuffer {
    const { ctx } = this.mixer
    const buffer = ctx.createBuffer(1, Math.round(ctx.sampleRate * NOISE_S), ctx.sampleRate)
    const data = buffer.getChannelData(0)
    let state = 0x2545f491
    for (let i = 0; i < data.length; i++) {
      state = (Math.imul(state, 1664525) + 1013904223) >>> 0
      data[i] = state / 0x80000000 - 1
    }
    return buffer
  }

  /** Fades a piece out and cuts it `cutS` after, on the audio clock; it makes no more notes. */
  private retire(playing: Playing, tauS: number, cutS: number): void {
    const now = this.mixer.ctx.currentTime
    playing.out.gain.setTargetAtTime(0, now, tauS)
    for (const note of playing.live) note.stop(now + cutS)
    this.retiring.push({ playing, cutAt: now + cutS })
    this.playing = null
  }

  private reap(now: number): void {
    for (let i = this.retiring.length - 1; i >= 0; i--) {
      const item = this.retiring[i]
      if (item === undefined || item.cutAt > now) continue
      this.cut(item.playing)
      this.retiring.splice(i, 1)
    }
  }

  private cut(playing: Playing): void {
    for (const note of playing.live) {
      note.stop()
      note.disconnect()
    }
    playing.live.clear()
    for (const bus of playing.buses) bus.disconnect()
    playing.out.disconnect()
  }
}
