import { LOGICAL_HEIGHT, LOGICAL_WIDTH } from '../config'
import { charWidth, lineHeight } from './theme'

// The unlock line's words, time and place (F-813): pure, so that they are tested in Node. `ToolsToast.ts` draws them.

/** What the line says, in the pixel font. */
export const UNLOCK_LINE = 'Tuning tools unlocked: T tune, L lines'
/** How long it stays, ms. */
export const TOAST_MS = 2500

export const TOAST_PAD_X = 24
export const TOAST_PAD_Y = 10
/** The gap between the plate's foot and the foot of the screen. */
const FOOT = 20

/** The plate's box on the 1920 x 1080 canvas for a line of this many characters: centred, near the bottom. */
export function toastBox(chars: number): { x: number; y: number; w: number; h: number } {
  const w = chars * charWidth('body') + 2 * TOAST_PAD_X
  const h = lineHeight('body') + 2 * TOAST_PAD_Y
  return { x: Math.round((LOGICAL_WIDTH - w) / 2), y: LOGICAL_HEIGHT - FOOT - h, w, h }
}
