import Phaser from 'phaser'
import { mixerOf } from '../audio'
import { Sfx } from '../audio/Sfx'
import { FONT, text } from './text'
import { THEME } from './theme'
import { TOAST_MS, TOAST_PAD_X, TOAST_PAD_Y, UNLOCK_LINE, toastBox } from './toast-layout'

// The line that tells the player the tuning tools are unlocked (F-813), on whatever screen is showing: a scene of its own,
// last in the scene list so that it is drawn over every other, started when the code has been typed and gone after a moment.

/** The scene's key. */
export const TOOLS_TOAST = 'ToolsToast'

/** Above the HUD, the menus and the pause overlay. */
const DEPTH = 1000
const PLATE_COLOUR = 0x16161e
const PLATE_ALPHA = 0.9

export class ToolsToastScene extends Phaser.Scene {
  private sfx: Sfx | null = null

  constructor() {
    super(TOOLS_TOAST)
  }

  create(): void {
    // The code can be typed before the font has arrived (during the first load): there is nothing to draw it with then, and the sound alone says it.
    const drawable = this.cache.bitmapFont.exists(FONT)
    const mixer = mixerOf(this.registry)
    if (mixer !== null) {
      this.sfx = new Sfx(mixer)
      this.sfx.play('tools-unlocked', { gain: 1 })
    }
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => {
      this.sfx?.dispose()
      this.sfx = null
    })
    if (drawable) {
      const box = toastBox(UNLOCK_LINE.length)
      this.add.rectangle(box.x, box.y, box.w, box.h, PLATE_COLOUR, PLATE_ALPHA).setOrigin(0, 0).setStrokeStyle(THEME.borderPx, THEME.colours.accent).setDepth(DEPTH)
      text(this, { x: box.x + TOAST_PAD_X, y: box.y + TOAST_PAD_Y }, UNLOCK_LINE, 'body').setTint(THEME.colours.accent).setDepth(DEPTH + 1)
    }
    this.time.delayedCall(TOAST_MS, () => this.scene.stop())
  }
}

/** Plays the unlock sound and puts the line up for `TOAST_MS`. */
export function announceUnlock(game: Phaser.Game): void {
  game.scene.start(TOOLS_TOAST)
}
